tables.code:
pgTable('media_deletion_queue', {
  assetId: uuid('asset_id').primaryKey(),
  requestId: uuid('request_id').notNull(),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
}, t => [index('media_deletion_queue_request_idx').on(t.requestId)])

pgTable('community_policy_acceptances', {
  accountId: uuid('account_id').primaryKey().references(() => accounts.id, { onDelete: 'cascade' }),
  version: text('version').notNull(),
  locale: text('locale').$type<'en' | 'tr' | 'de' | 'fr' | 'es' | 'ja'>().notNull(),
  acceptedAt: timestamp('accepted_at', { withTimezone: true }).notNull(),
}, t => [check('community_policy_locale_check', sql`${t.locale} in ('en','tr','de','fr','es','ja')`)])

pgTable('community_blocks', {
  blockerAccountId: uuid('blocker_account_id').notNull().references(() => accounts.id, { onDelete: 'cascade' }),
  targetAccountId: uuid('target_account_id').notNull().references(() => accounts.id, { onDelete: 'cascade' }),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull(),
}, t => [primaryKey({ columns: [t.blockerAccountId, t.targetAccountId] }),
  index('community_blocks_target_idx').on(t.targetAccountId),
  check('community_blocks_distinct_check', sql`${t.blockerAccountId} <> ${t.targetAccountId}`),
])

pgTable('announcement_reads', {
  accountId: uuid('account_id').notNull().references(() => accounts.id),
  announcementId: uuid('announcement_id').notNull().references(() => announcements.id),
  readAt: timestamp('read_at', { withTimezone: true }).notNull(),
}, (t) => [primaryKey({ columns: [t.accountId, t.announcementId] })])

pgTable('season_cycles', {
  id: uuid('id').primaryKey().defaultRandom(),
  /** Permanent player-facing season number. Shared by every shard in this cycle. */
  ordinal: integer('ordinal').notNull(),
  /** Cycle-wide cutover: transfers cannot move partial history into a complete snapshot. */
  statsVersion: integer('stats_version').notNull().default(0),
  /** Frozen at creation; zero means the cross-season reward program was not active. */
  rewardProgramVersion: integer('reward_program_version').notNull().default(0),
  startsAt: timestamp('starts_at', { withTimezone: true }).notNull(),
  endsAt: timestamp('ends_at', { withTimezone: true }).notNull(),
}, (t) => [
  uniqueIndex('season_cycles_ordinal_idx').on(t.ordinal),
  uniqueIndex('season_cycles_period_idx').on(t.startsAt, t.endsAt),
  check('season_cycles_period_check', sql`${t.endsAt} > ${t.startsAt}`),
])

pgTable('return_queue_counters', {
  cycleId: uuid('cycle_id').notNull().references(() => seasonCycles.id),
  targetShardId: uuid('target_shard_id').notNull().references(() => shards.id),
  // SQL default avoids drizzle-kit's JSON snapshot serializer rejecting a JS bigint.
  lastSequence: bigint('last_sequence', { mode: 'bigint' }).notNull().default(sql`0`),
}, (t) => [primaryKey({ columns: [t.cycleId, t.targetShardId] })])

pgTable('chat_read_markers', {
  playerId: uuid('player_id').notNull().references(() => players.id, { onDelete: 'cascade' }),
  language: text('language').$type<ChatLanguage>().notNull(),
  readAt: timestamp('read_at', { withTimezone: true }).notNull(),
}, (t) => [
  primaryKey({ columns: [t.playerId, t.language] }),
  index('chat_read_markers_player_idx').on(t.playerId),
])

pgTable('dm_conversations', {
  id: uuid('id').primaryKey().defaultRandom(),
  seasonId: uuid('season_id').notNull().references(() => seasons.id),
  playerLowId: uuid('player_low_id').notNull().references(() => players.id, { onDelete: 'cascade' }),
  playerHighId: uuid('player_high_id').notNull().references(() => players.id, { onDelete: 'cascade' }),
}, (t) => [
  uniqueIndex('dm_conversations_pair_idx').on(t.seasonId, t.playerLowId, t.playerHighId),
  index('dm_conversations_high_idx').on(t.playerHighId),
  check('dm_conversations_order_check', sql`${t.playerLowId} < ${t.playerHighId}`),
])

pgTable('dm_read_markers', {
  conversationId: uuid('conversation_id').notNull().references(() => dmConversations.id, { onDelete: 'cascade' }),
  playerId: uuid('player_id').notNull().references(() => players.id, { onDelete: 'cascade' }),
  readAt: timestamp('read_at', { withTimezone: true }).notNull(),
}, (t) => [primaryKey({ columns: [t.conversationId, t.playerId] })])

pgTable('dm_blocks', {
  blockerPlayerId: uuid('blocker_player_id').notNull().references(() => players.id, { onDelete: 'cascade' }),
  targetPlayerId: uuid('target_player_id').notNull().references(() => players.id, { onDelete: 'cascade' }),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull(),
}, (t) => [
  primaryKey({ columns: [t.blockerPlayerId, t.targetPlayerId] }),
  index('dm_blocks_target_idx').on(t.targetPlayerId),
  check('dm_blocks_distinct_check', sql`${t.blockerPlayerId} <> ${t.targetPlayerId}`),
])

pgTable('galaxy_events', {
  id: uuid('id').primaryKey().defaultRandom(),
  seasonId: uuid('season_id').notNull().references(() => seasons.id),
  kind: text('kind').notNull(),
  refId: text('ref_id').notNull(),
  /** No FK: the public snapshot survives an idle seat being reclaimed. */
  subjectPlanetId: uuid('subject_planet_id'),
  payload: jsonb('payload').$type<GalaxyEventPayload>().notNull(),
  occurredAt: timestamp('occurred_at', { withTimezone: true }).notNull(),
}, (t) => [
  uniqueIndex('galaxy_events_source_idx').on(t.seasonId, t.kind, t.refId),
  index('galaxy_events_season_cursor_idx').on(t.seasonId, t.occurredAt, t.id),
])

pgTable('season_telemetry_segments', {
  id: uuid('id').primaryKey().defaultRandom(),
  seasonId: uuid('season_id').notNull().references(() => seasons.id),
  playerId: uuid('player_id').notNull().references(() => players.id),
  sourcePlanetId: uuid('source_planet_id').notNull(),
  telemetry: jsonb('telemetry').$type<PlanetSeasonTelemetry>().notNull(),
  closedAt: timestamp('closed_at', { withTimezone: true }).notNull(),
}, (t) => [
  index('season_telemetry_segments_season_player_idx').on(t.seasonId, t.playerId),
])

