jsonb('season_telemetry').$type<PlanetSeasonTelemetry>().notNull().default({
    produced: { alloy: 0, crystal: 0, deuterium: 0 },
    productiveSeconds: 0,
    shipsBuilt: {},
  })

tables.code:
pgTable('buildings', {
  planetId: uuid('planet_id').notNull().references(() => planets.id),
  type: text('type').notNull(),
  level: integer('level').notNull().default(0),
}, (t) => [primaryKey({ columns: [t.planetId, t.type] })])

pgTable('player_research', {
  playerId: uuid('player_id').notNull().references(() => players.id),
  projectId: text('project_id').$type<ResearchProjectId>().notNull(),
  level: integer('level').notNull().default(1),
  completedAt: timestamp('completed_at', { withTimezone: true }).notNull(),
}, (t) => [primaryKey({ columns: [t.playerId, t.projectId] })])

pgTable('planet_research', {
  planetId: uuid('planet_id').notNull().references(() => planets.id),
  projectId: text('project_id').$type<ResearchProjectId>().notNull(),
  completedAt: timestamp('completed_at', { withTimezone: true }).notNull(),
}, (t) => [primaryKey({ columns: [t.planetId, t.projectId] })])

pgTable('satellites', {
  planetId: uuid('planet_id').notNull().references(() => planets.id),
  slot: integer('slot').notNull(),
  type: text('type').notNull(),
  level: integer('level').notNull().default(1),
  /** Paid Aegis investment; preserves old invoices across the October price cut. Null uses current catalogue value. */
  aegisInvestedValue: doublePrecision('aegis_invested_value'),
}, (t) => [primaryKey({ columns: [t.planetId, t.slot] })])

pgTable('units', {
  planetId: uuid('planet_id').notNull().references(() => planets.id),
  /** Null only for a neutral system garrison. */
  ownerPlayerId: uuid('owner_player_id').references(() => players.id),
  hull: text('hull').$type<HullId>().notNull(),
  location: text('location').notNull().default('home'),
  count: integer('count').notNull().default(0),
  /** Home injury metadata is a subset of count; away health lives on its mission/wave. */
  damage: jsonb('damage').$type<HpDamageLot[]>().notNull().default([]),
}, (t) => [
  primaryKey({ columns: [t.planetId, t.hull, t.location] }),
  // Physical fleets aboard named flights (`pirate:`, `trade:`, waves) are read by
  // location alone; the primary key leads with planet_id and cannot serve that.
  index('units_location_idx').on(t.location),
])

pgTable('clan_raid_roster', {
  missionId: uuid('mission_id').notNull().references(() => missions.id),
  clanId: uuid('clan_id').notNull().references(() => clans.id),
  playerId: uuid('player_id').notNull(),
  slot: integer('slot').notNull(),
}, (t) => [
  primaryKey({ columns: [t.missionId, t.playerId] }),
  uniqueIndex('clan_raid_roster_slot_idx').on(t.missionId, t.slot),
  check('clan_raid_roster_slot_check', sql`${t.slot} BETWEEN 0 AND 4`),
])

pgTable('clan_war_missions', {
  missionId: uuid('mission_id').primaryKey().references(() => missions.id),
  operationId: uuid('operation_id').notNull().references(() => clanWarOperations.id),
  /** NULL only for the one aggregate strike; every other leg belongs to a wave. */
  contributionId: uuid('contribution_id'),
  leg: text('leg').$type<ClanWarLeg>().notNull(),
}, (t) => [
  foreignKey({
    columns: [t.contributionId, t.operationId],
    foreignColumns: [clanWarContributions.id, clanWarContributions.operationId],
    name: 'clan_war_missions_contribution_operation_fk',
  }),
  /** One combined strike per operation, whatever a redelivered launch tries. */
  uniqueIndex('clan_war_missions_aggregate_idx')
    .on(t.operationId, t.leg)
    .where(sql`${t.contributionId} IS NULL`),
  /** One of each leg per wave, whatever a retried return planner tries. */
  uniqueIndex('clan_war_missions_contribution_leg_idx')
    .on(t.contributionId, t.leg)
    .where(sql`${t.contributionId} IS NOT NULL`),
  index('clan_war_missions_operation_idx').on(t.operationId),
  check(
    'clan_war_missions_leg_check',
    sql`${t.leg} IN ('SUPPORT_OUT', 'SUPPORT_RETURN', 'COMBINED_ATTACK', 'BATTLE_RETURN')`,
  ),
  check(
    'clan_war_missions_binding_check',
    sql`(${t.leg} = 'COMBINED_ATTACK') = (${t.contributionId} IS NULL)`,
  ),
])

columns.definition:
jsonb('silhouette').$type<{
    skin?: { id: PlanetSkinId; status: PlanetSkinStatus };
    owner: string;
    /** Optional frozen identity for records created before country labels. */
    country?: CountryCode;
    controllerPlayerId: string | null;
    clan: { id: string; name: string; tag: string } | null;
    kind: 'CAPITAL' | 'COLONY' | 'NEUTRAL';
    coreLevel: number;
    satellites: string[];
    shielded: boolean;
    /**
     * WHAT THIS COMMANDER HAS RESEARCHED INTO THEIR HULLS. T9 · D124.
     *
     * A 56% multiplier (D169) nobody can see would silently eat the value of every
     * scouting flight, and D124 is blunt: a rule the player cannot SEE is not a
     * rule. So the doctrines are a PROBE product — earned, never public — and
     * they freeze at the look like everything else here. Absent on reports
     * written before this existed, which read as no research at all.
     *
     * Written only before combat v3; a newer report carries `research` instead.
     */
    doctrines?: Partial<Record<ResearchProjectId, number>>;
    /** Combat research as windows holding each level (combat v3, owner 2026-10-25). */
    research?: Partial<Record<ResearchProjectId, { low: number; high: number }>>;
    /**
     * HOW MANY DEATH STARS THIS WORLD CAN SHOOT DOWN. T10 · owner, 2026-10-01.
     *
     * The READY charges on the pad at the look — one charge downs one weapon — and
     * what turns a strategic strike from a pure resource decision into an
     * INTELLIGENCE one. Never public, so the only way to know is to have looked.
     * Reports written before the count carried an `interceptor` flag instead; they
     * read as never measured.
     */
    interceptors?: number;
    /**
     * A COLONY'S LOYALTY AT THE LOOK, rounded up. Owner, 2026-10-01: a Death Star takes
     * twenty and a colony at twenty or less goes NEUTRAL. Absent on capitals and neutrals.
     */
    loyalty?: number;
  }>()

jsonb('silhouette').$type<{
    skin?: { id: PlanetSkinId; status: PlanetSkinStatus };
    owner: string;
    /** Same snapshot identity as the recorded owner, never today's controller. */
    country?: CountryCode;
    controllerPlayerId: string | null;
    clan: { id: string; name: string; tag: string } | null;
    kind: 'CAPITAL' | 'COLONY' | 'NEUTRAL';
    coreLevel: number;
    satellites: string[];
    shielded: boolean;
    doctrines?: Partial<Record<ResearchProjectId, number>>;
    research?: Partial<Record<ResearchProjectId, { low: number; high: number }>>;
    interceptors?: number;
    loyalty?: number;
  }>().notNull()

tables.code:
pgTable('probe_world_memories', {
  invalidatedAt: timestamp('invalidated_at', { withTimezone: true }),
  observerPlayerId: uuid('observer_player_id').notNull().references(() => players.id),
  targetPlanetId: uuid('target_planet_id').notNull().references(() => planets.id),
  /** The probe report this came from. NULL when a fleet took the look. */
  reportId: uuid('report_id').references(() => probeReports.id),
  /** Which craft's eyes these were. Never shown; it is here to be debuggable. */
  source: text('source').$type<'PROBE' | 'BATTLE'>().notNull().default('PROBE'),
  /**
   * The outside of the world as it was at `seenAt`. Same shape a probe report
   * carries, minus the two readings only a probe takes — a battle learns what a
   * world LOOKS like, never its research or what is on its interceptor pad.
   */
  silhouette: jsonb('silhouette').$type<{
    skin?: { id: PlanetSkinId; status: PlanetSkinStatus };
    owner: string;
    /** Same snapshot identity as the recorded owner, never today's controller. */
    country?: CountryCode;
    controllerPlayerId: string | null;
    clan: { id: string; name: string; tag: string } | null;
    kind: 'CAPITAL' | 'COLONY' | 'NEUTRAL';
    coreLevel: number;
    satellites: string[];
    shielded: boolean;
    doctrines?: Partial<Record<ResearchProjectId, number>>;
    research?: Partial<Record<ResearchProjectId, { low: number; high: number }>>;
    interceptors?: number;
    loyalty?: number;
  }>().notNull(),
  seenAt: timestamp('seen_at', { withTimezone: true }).notNull(),
}, (t) => [
  primaryKey({ columns: [t.observerPlayerId, t.targetPlanetId] }),
  uniqueIndex('probe_world_memories_report_idx').on(t.reportId),
])

pgTable('player_rivals', {
  id: uuid('id').primaryKey().defaultRandom(),
  playerId: uuid('player_id').notNull().references(() => players.id),
  /** Where the mark was placed. The anchor a player recognises, never the rule. */
  planetId: uuid('planet_id').notNull(),
  /** Who it is really about. Survives that world changing hands. D97. */
  targetPlayerId: uuid('target_player_id').notNull(),
  /** 0..RIVAL.max-1. Fixed for the life of the mark, because it IS the colour. */
  slot: integer('slot').notNull(),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
}, (t) => [
  /** One mark per commander marked: pressing a second world of theirs is the same mark. */
  uniqueIndex('player_rivals_target_idx').on(t.playerId, t.targetPlayerId),
  /** And one mark per colour, which is what makes the slot a colour at all. */
  uniqueIndex('player_rivals_slot_idx').on(t.playerId, t.slot),
])

pgTable('asteroid_claims', {
  seasonId: uuid('season_id').notNull().references(() => seasons.id),
  /** Index into the generated field for this season's seed. */
  index: integer('index').notNull(),
  oreTaken: real('ore_taken').notNull().default(0),
  updatedAt: timestamp('updated_at', { withTimezone: true }).notNull(),
}, (t) => [primaryKey({ columns: [t.seasonId, t.index] })])

pgTable('pirate_state', {
  seasonId: uuid('season_id').notNull().references(() => seasons.id),
  /** Index into the generated pirate lane for this season's key. Server-only. */
  index: integer('index').notNull(),
  /** Cumulative hulls destroyed across every commander who has hit it. */
  losses: jsonb('losses').$type<Fleet>().notNull().default({}),
  /** Hoard already loaded by all raids, excluding separately recovered wreckage. */
  lootPaid: jsonb('loot_paid').$type<Resources>().notNull().default({ alloy: 0, crystal: 0, deuterium: 0 }),
  /** Set once, by the raid that wiped it out. */
  destroyedAt: timestamp('destroyed_at', { withTimezone: true }),
  destroyedByPlayerId: uuid('destroyed_by_player_id').references(() => players.id),
  updatedAt: timestamp('updated_at', { withTimezone: true }).notNull(),
}, (t) => [primaryKey({ columns: [t.seasonId, t.index] })])

pgTable('unknown_signal_state', {
  playerId: uuid('player_id').primaryKey().references(() => players.id, { onDelete: 'cascade' }),
  seasonId: uuid('season_id').notNull().references(() => seasons.id, { onDelete: 'cascade' }),
  nextAt: timestamp('next_at', { withTimezone: true }),
  sequence: integer('sequence').notNull().default(0),
  /** Set by a first-game join; the first signal that actually appears spends it. */
  firstSignalSpared: boolean('first_signal_spared').notNull().default(false),
}, t => [index('unknown_signal_state_next_idx').on(t.nextAt)])

pgTable('reward_grants', {
  playerId: uuid('player_id').notNull().references(() => players.id),
  /** `CHAIN:GOAL`, built by `rewardId()` in @astera/rules. Text, so retiring a
   *  chain leaves old rows readable instead of failing an enum cast. */
  rewardId: text('reward_id').notNull(),
  alloy: real('alloy').notNull().default(0),
  crystal: real('crystal').notNull().default(0),
  deuterium: real('deuterium').notNull().default(0),
  /** NULL means unlocked and waiting. Season-scoped tiers are only ever written claimed. */
  claimedAt: timestamp('claimed_at', { withTimezone: true }),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
}, (t) => [primaryKey({ columns: [t.playerId, t.rewardId] })])

pgTable('account_rewards', {
  accountId: uuid('account_id').notNull().references(() => accounts.id),
  /** `CHAIN:GOAL`, built by `rewardId()`. Only chains with `scope: 'account'` land here. */
  rewardId: text('reward_id').notNull(),
  alloy: real('alloy').notNull().default(0),
  crystal: real('crystal').notNull().default(0),
  deuterium: real('deuterium').notNull().default(0),
  /** NULL means granted and waiting to be taken. */
  claimedAt: timestamp('claimed_at', { withTimezone: true }),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
}, (t) => [primaryKey({ columns: [t.accountId, t.rewardId] })])

pgTable('chat_mutes', {
  accountId: uuid('account_id').notNull().references(() => accounts.id, { onDelete: 'cascade' }),
  channel: text('channel').$type<'general' | 'clan' | 'dm'>().notNull(),
  expiresAt: timestamp('expires_at', { withTimezone: true }),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull(),
  actorAccountId: uuid('actor_account_id').references(() => accounts.id, { onDelete: 'set null' }),
}, (t) => [
  primaryKey({ columns: [t.accountId, t.channel] }),
  check('chat_mutes_channel_check', sql`${t.channel} IN ('general', 'clan', 'dm')`),
])

pgTable('arena_pilots', {
  accountId: uuid('account_id').primaryKey().references(() => accounts.id, { onDelete: 'cascade' }),
  grantedByAccountId: uuid('granted_by_account_id').references(() => accounts.id, { onDelete: 'set null' }),
  grantedAt: timestamp('granted_at', { withTimezone: true }).notNull(),
})

pgTable('paddle_webhook_events', {
  id: text('id').primaryKey(),
  eventType: text('event_type').notNull(),
  receivedAt: timestamp('received_at', { withTimezone: true }).notNull().defaultNow(),
})

pgTable('paddle_reversals', {
  transactionId: text('transaction_id').primaryKey(),
  action: text('action').notNull(),
  receivedAt: timestamp('received_at', { withTimezone: true }).notNull().defaultNow(),
})

pgTable('polar_webhook_events', {
  id: text('id').primaryKey(),
  eventType: text('event_type').notNull(),
  receivedAt: timestamp('received_at', { withTimezone: true }).notNull().defaultNow(),
})

pgTable('polar_reversals', {
  orderId: uuid('order_id').primaryKey(),
  receivedAt: timestamp('received_at', { withTimezone: true }).notNull().defaultNow(),
})

pgTable('shopier_webhook_events', {
  id: text('id').primaryKey(),
  eventType: text('event_type').notNull(),
  receivedAt: timestamp('received_at', { withTimezone: true }).notNull().defaultNow(),
})

pgTable('honor_seasons', {
  seasonId: uuid('season_id').primaryKey().references(() => seasons.id, { onDelete: 'cascade' }),
  version: integer('version').notNull(),
  mode: text('mode').$type<'SHADOW' | 'ACTIVE'>().notNull(),
  /** Opt-in frozen economic program; adding the column never changes existing prices. */
  benefitsVersion: integer('benefits_version'),
  /** New dispatches only; existing snapshots and earned retaliation stay frozen. */
  retaliationLootPercent: integer('retaliation_loot_percent').$type<20 | 40>().notNull().default(20),
  catalogue: jsonb('catalogue').$type<HonorCatalogue>().notNull(),
  shieldCatalogue: jsonb('shield_catalogue').$type<number[]>().notNull(),
  strategicCatalogue: jsonb('strategic_catalogue').$type<HonorStrategicCatalogue>(),
  /** Frozen at activation: real outgoing attacks that had no Honor launch contract. */
  legacySources: text('legacy_sources').array().notNull().default(sql`ARRAY[]::text[]`),
  /** Rebuildable projection, atomically updated under this row's transaction lock. */
  state: jsonb('state').$type<HonorAccountingState>().notNull(),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull(),
  /** Announced race boundary. Observation history keeps its original createdAt. */
  rankedAt: timestamp('ranked_at', { withTimezone: true }),
  closedAt: timestamp('closed_at', { withTimezone: true }),
  /** A hidden race the operator promised to the next cycle; it carries like an ACTIVE one. */
  successorAnnounced: boolean('successor_announced').notNull().default(false),
}, (t) => [
  check('honor_seasons_version_check', sql`${t.version} > 0`),
  check('honor_seasons_mode_check', sql`${t.mode} IN ('SHADOW', 'ACTIVE')`),
  check('honor_seasons_loot_percent_check', sql`${t.retaliationLootPercent} IN (20, 40)`),
  check('honor_seasons_ranked_boundary_check', sql`${t.rankedAt} IS NULL OR ${t.rankedAt} >= ${t.createdAt}`),
])

pgTable('honor_totals', {
  seasonId: uuid('season_id').notNull().references(() => honorSeasons.seasonId, { onDelete: 'cascade' }),
  playerId: uuid('player_id').notNull(),
  score: bigint('score', { mode: 'number' }).notNull(),
}, (t) => [
  primaryKey({ columns: [t.seasonId, t.playerId] }),
  index('honor_totals_rank_idx').on(t.seasonId, t.score),
  check('honor_totals_score_check', sql`${t.score} BETWEEN -9007199254740991 AND 9007199254740991`),
])

pgTable('honor_commitments', {
  seasonId: uuid('season_id').notNull().references(() => honorSeasons.seasonId, { onDelete: 'cascade' }),
  source: text('source').$type<HonorEvidence['source']>().notNull(),
  sourceId: text('source_id').notNull(),
  snapshot: jsonb('snapshot').$type<HonorCommitment>().notNull(),
}, (t) => [
  primaryKey({ columns: [t.seasonId, t.source, t.sourceId] }),
  check('honor_commitments_source_check', sql`${t.source} IN ('WORLD', 'CLAN_WAR', 'MONUMENT', 'STRATEGIC_IMPACT', 'STRATEGIC_INTERCEPTION')`),
])

pgTable('security_counters', {
  key: text('key').primaryKey(),
  count: integer('count').notNull(),
  expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
})

pgTable('mail_suppressions', {
  recipientKey: text('recipient_key').primaryKey(),
