import { dirname, join } from 'node:path';
import { z } from 'zod';
import { COSMETIC_IDS, EXTRA_COSMETIC_IDS, cosmeticById, MULTI_WORLD } from '@astera/rules';
import { BOTS } from './services/bots/personas.js';

const schema = z.object({
  CHAT_MEDIA_DIR: z.string().min(1).default('.data/chat-media'),
  NODE_ENV: z.enum(['development', 'test', 'production']).default('development'),
  /** 'api' serves HTTP, 'worker' drains scheduled events, 'both' does both. */
  ROLE: z.enum(['api', 'worker', 'both', 'arena']).default('both'),
  /** Real-time pilot mode (Komutan Gemisi arena) runs only when its process says so. */
  ARENA_ENABLED: z.enum(['true', 'false']).default('false').transform(value => value === 'true'),
  /** Local bots, network conditioning and debug controls must never reach production. */
  ARENA_DEV: z.enum(['true', 'false']).default('false').transform(value => value === 'true'),
  ARENA_ALLOWED_ORIGINS: z.string().default('http://localhost:5173,http://127.0.0.1:5173'),
  /** Private playtest reference pack on this host; unset serves none and the arena draws its procedural set. */
  ARENA_REF_DIR: z.string().min(1).optional(),
  /** Usernames that may fly the live playtest arena; `*` admits every signed-in account. */
  ARENA_PILOTS: z.string().default('').transform((value) =>
    value
      .split(',')
      .map((username) => username.trim().toLocaleLowerCase('en-US'))
      .filter((username) => username.length > 0),
  ),
  PORT: z.coerce.number().default(3000),
  DATABASE_URL: z.string().min(1),
  /** Request-pool budget per process; LISTEN uses one additional connection. */
  DB_POOL_MAX: z.coerce.number().int().min(1).max(50).default(10),
  /** Separate HTTP placement leases; each handler may also need the request pool. */
  PLACEMENT_POOL_MAX: z.coerce.number().int().min(1).max(50).default(2),
  /**
   * API roles only: PostgreSQL ends a transaction left idle this long, so a hung
   * handler cannot hold row locks or a placement connection indefinitely. The
   * worker and CLIs run long transactions of their own and are not bounded.
   */
  DB_IDLE_IN_TRANSACTION_TIMEOUT_MS: z.coerce.number().int().min(100).max(600_000).default(30_000),
  /**
   * Rotating this invalidates every session. Must be set in production.
   *
   * `SHARD_CODE` used to sit here and is gone (D21). One process now serves all ten
   * galaxies and works out which one a caller is in from their own player row, so a
   * variable naming "the" shard could only ever be wrong for nine of them.
   */
  JWT_SECRET: z.string().min(16).default('dev-only-secret-do-not-ship-me'),
  /** Enable only after every API/worker replica and the additive migration are current. */
  NATIVE_AUTH_ENABLED: z.enum(['true', 'false']).default('false').transform(value => value === 'true'),
  NATIVE_APP_ORIGINS: z.string().default('').transform(value => value.split(',').map(origin => origin.trim()).filter(Boolean))
    .pipe(z.array(z.enum(['https://localhost', 'capacitor://localhost', 'http://localhost']))),
  /** Bundled apps below this versionCode must update (426 UPDATE_REQUIRED); 0 gates nothing. */
  MIN_NATIVE_BUILD: z.coerce.number().int().min(0).default(0),
  /** Enable new registrations only after every replica supports consuming this grant. */
  FIRST_GAME_SHIELD_ENABLED: z.enum(['true', 'false']).default('true').transform(value => value === 'true'),
  /** Live checkout stays closed until all three secrets are supplied and enabled. */
  PADDLE_CHECKOUT_ENABLED: z.enum(['true', 'false']).default('false').transform(value => value === 'true'),
  PADDLE_ENV: z.enum(['sandbox', 'production']).default('production'),
  PADDLE_API_KEY: z.string().default(''),
  PADDLE_CLIENT_TOKEN: z.string().default(''),
  PADDLE_WEBHOOK_SECRET: z.string().default(''),
  PADDLE_PRICE_LAVA: z.string().startsWith('pri_').default('pri_01m3fwr44wjzkbenrjctb9k6dd'),
  PADDLE_PRICE_ICE: z.string().startsWith('pri_').default('pri_01m3fws4ewv6kp2yr4tztk8427'),
  PADDLE_PRICE_TOXIC: z.string().startsWith('pri_').default('pri_01m3fwtx8bvz0dbqdv3p18379m'),
  PADDLE_PRICE_DESERT: z.string().startsWith('pri_').default('pri_01m3fwvmk6eysq56ed05z1828m'),
  PADDLE_PRICE_TURKEY: z.string().startsWith('pri_').default('pri_01m3fx4wqpeqpzav659tz16e7t'),
