import { and, eq } from 'drizzle-orm';
import type { FastifyInstance } from 'fastify';
import { z } from 'zod';
import { PROBE } from '@astera/rules';
import { planets, players } from '../db/schema.js';
import { GameError } from '../services/planet.js';
import {
  assignWatch,
  launchProbe,
  readProbeCooldowns,
  readProbeReports,
  readRadarLog,
  readTelescopes,
} from '../services/intel.js';
import { requireAuth } from './auth.js';
import { ownedPlanet } from '../services/ownership.js';

const watchBody = z.object({
  observerPlanetId: z.string().uuid().optional(),
  targetPlanetId: z.string().uuid(),
  slot: z.number().int().min(0).max(15).default(0),
});

const probeBody = z.object({ originPlanetId: z.string().uuid().optional(), targetPlanetId: z.string().uuid() });

export function registerIntelRoutes(app: FastifyInstance): void {
  const me = async (accountId: string): Promise<{ playerId: string; planetId: string }> => {
    const rows = await app.db
      .select({ playerId: players.id, planetId: planets.id })
      .from(players)
      .innerJoin(planets, and(eq(planets.controllerPlayerId, players.id), eq(planets.kind, 'CAPITAL')))
      .where(eq(players.accountId, accountId))
      .limit(1);
    const row = rows[0];
    if (!row) throw new GameError('NO_PLANET', 'Join a galaxy first', 404);
    return row;
  };

  /**
   * The intel screen — the return moment's payload.
   *
   * Everything here is already filtered by the player's own clarity and radar
   * level. There is no "full" version of this response that a modified client
   * could ask for instead.
   */
  app.get('/api/intel', { preHandler: requireAuth }, async (req) => {
    /**
     * THE WHOLE COMMANDER, NOT THE CAPITAL. D97/D134.
     *
     * `me()` resolves the capital, which is right for the two POST routes below —
     * they need a default origin. It was wrong here: the radar log was read for
     * the capital alone, so every probe against a colony wrote its row and no
     * surface in the game ever read it. The telescope watches were already
     * commander-wide, so one payload was answering at two different scopes.
     */
    const self = await app.projections.commander(req.accountId!);
    const [watching, radarLog, reports, cooldowns] = await Promise.all([
      readTelescopes(app.db, self.playerId, app.clock),
      readRadarLog(app.db, self.planetIds),
      readProbeReports(app.db, self.playerId),
      readProbeCooldowns(app.db, self.playerId, app.clock.now()),
    ]);

    return {
      watching,
      radarLog,
      // Which worlds this commander may not look at again yet, and until when.
      probeCooldowns: cooldowns,
      probeReports: reports.map((r) => ({
        missionId: r.report.missionId,
        targetPlanetId: r.report.targetPlanetId,
        spatiallyCurrent: r.spatiallyCurrent,
        targetName: r.targetName,
        targetUsername: r.targetUsername,
        at: r.report.createdAt,
        // Rounded so the UI cannot imply more precision than the probe bought.
        accuracy: Math.round(r.report.accuracy * 100) / 100,
        stock: r.report.stock,
        deuteriumStock: r.report.deuteriumStock,
        defence: r.report.defence,
        fleetSize: r.report.fleetSize,
        fleetHome: r.report.fleetHome,
        deathStar: r.report.strategicStatus ?? 'UNKNOWN',
        /**
         * THE TWO READINGS THE PROBE HAS ALWAYS TAKEN AND NEVER DELIVERED. T9 · T10.
         *
         * `resolveProbe` has written both into the report's silhouette since they
         * shipped, and no route ever put them on the wire — so a commander paid
         * alloy, a flight bay, a round trip and the risk of being caught, and
         * could not read either one anywhere in the game.
         *
         *   · `doctrines` is what the target has researched into their hulls. It is
         *     worth up to a 56% combat multiplier (D169), and `CLAUDE.md` requires in as
         *     many words that combat-relevant doctrine be PROBE-VISIBLE (D137). It
         *     was probe-collected and invisible, which is the opposite.
         *   · `interceptors` is how many strategic weapons that world can shoot
         *     down (T10; a count since 2026-10-01). Without it a Death Star is spent
         *     blind — the feature's whole argument is that scouting turns the strike
         *     into an intelligence decision, and there was nothing to scout WITH.
         *   · `loyalty` is a colony's, because a Death Star takes twenty of it and a
         *     colony at twenty or less goes NEUTRAL (owner, 2026-10-01).
         *
         * Both are frozen at the look, like everything else in the silhouette, and
         * the client prints their age beside them for exactly that reason.
         *
         * ABSENT rather than defaulted when the report predates them or the target
         * is a caretaker world: an empty object would read as "they have researched
         * nothing", which is a claim this reading cannot make.
         */
        ...(r.report.silhouette?.doctrines
          ? { doctrines: r.report.silhouette.doctrines }
          : {}),
        // Combat v3: windows holding each level. A report carries one reading or the other.
        ...(r.report.silhouette?.research
          ? { research: r.report.silhouette.research }
          : {}),
        ...(r.report.silhouette?.interceptors === undefined
          ? {}
          : { interceptors: r.report.silhouette.interceptors }),
        ...(r.report.silhouette?.loyalty === undefined
          ? {}
          : { loyalty: r.report.silhouette.loyalty }),
        /*
          THE THREE READINGS D199 ADDED — the shape of what fires, the Aegis charge
          and the unarmed hulls in the line. ABSENT on a report written before them,
          never defaulted: `{ low: 0, high: 0 }` means "measured, and empty", and a
          launch sheet must not draw an undefended world out of a missing field.
        */
        ...(r.report.classReading ? { classReading: r.report.classReading } : {}),
        ...(r.report.shield ? { shield: r.report.shield } : {}),
        ...(r.report.unarmed ? { unarmed: r.report.unarmed } : {}),
        detected: r.report.detected,
      })),
      probeCost: { alloy: PROBE.alloy, crystal: PROBE.crystal, deuterium: 0 },
    };
  });

  /** Point a telescope slot at a planet. Silent — the target is never told. */
  app.post('/api/intel/watch', { preHandler: requireAuth }, async (req) => {
    const body = watchBody.parse(req.body);
    const { planetId, playerId } = await me(req.accountId!);
    const observerPlanetId = body.observerPlanetId ?? planetId;
    const owner = body.observerPlanetId
      ? await ownedPlanet(app.db, req.accountId!, observerPlanetId)
      : { playerId };
    return assignWatch(
      app.db,
      observerPlanetId,
      body.targetPlanetId,
      body.slot,
      app.clock,
      owner.playerId,
    );
  });

  /**
   * Send a probe. Costs alloy and time, and may trip the target's radar.
   *
   * The response deliberately does NOT say whether it was detected — that is only
   * known when the probe lands, and telling the player early would remove the
   * risk the decision is built on.
   */
  app.post('/api/intel/probe', { preHandler: requireAuth }, async (req) => {
    const body = probeBody.parse(req.body);
    const { planetId, playerId } = await me(req.accountId!);
    const originPlanetId = body.originPlanetId ?? planetId;
    const owner = body.originPlanetId
      ? await ownedPlanet(app.db, req.accountId!, originPlanetId)
      : { playerId };
    return launchProbe(
      app.db,
      originPlanetId,
      body.targetPlanetId,
      app.clock,
      owner.playerId,
    );
  });
}

sources.apps/server/src/routes/intergalacticConv:
import { and, eq } from 'drizzle-orm';
import type { FastifyInstance, FastifyRequest } from 'fastify';
import { FLEET_V2_HULLS } from '@astera/rules';
import { z } from 'zod';
import { planets } from '../db/schema.js';
import {
  launchIntergalacticConvoy,
  type IntergalacticConvoyLaunch,
} from '../services/intergalacticConvoyRaid.js';
import { idempotentMutation } from '../services/idempotency.js';
import { commanderForAccount, capitalPlanet } from '../services/ownership.js';
import { GameError } from '../services/planet.js';
import { loadPlanetViewData, buildPlanetResult } from '../services/planetView.js';
import { pendingThreads } from '../services/session.js';
import { requireAuth } from './auth.js';

const fleetFields = Object.fromEntries(FLEET_V2_HULLS.map((hull) => [
  hull,
  z.number().int().positive().max(Number.MAX_SAFE_INTEGER).optional(),
]));
const convoyFleet = z.object(fleetFields).strict().refine(
  (fleet) => Object.keys(fleet).length > 0,
  'Send at least one craft',
);

const convoyLaunchBody = z.object({
  originPlanetId: z.string().uuid(),
  occurrenceId: z.string().uuid(),
  fleet: convoyFleet,
  quotedAt: z.string().datetime({ offset: true }),
  quotedFlightSeconds: z.number().finite().nonnegative(),
  quotedArriveAt: z.string().datetime({ offset: true }),
  acknowledgeRadiationLoss: z.boolean().optional(),
  expectedHonorTier: z.union([z.literal(-2), z.literal(-1), z.literal(0), z.literal(1), z.literal(2)]).optional(),
}).strict();

const idempotencyKey = (req: FastifyRequest): string => {
  const parsed = z.string().min(8).max(128).safeParse(req.headers['idempotency-key']);
  if (!parsed.success) {
    throw new GameError('IDEMPOTENCY_KEY_REQUIRED', 'A valid idempotency-key header is required', 400);
  }
  return parsed.data;
};

type WireLaunch = Omit<
  IntergalacticConvoyLaunch,
  'departAt' | 'arriveAt' | 'engagementEndsAt' | 'homeAt'
> & {
  departAt: string;
  arriveAt: string;
  engagementEndsAt: string;
  homeAt: string;
};

const wireLaunch = (launch: IntergalacticConvoyLaunch): WireLaunch => ({
  ...launch,
  departAt: launch.departAt.toISOString(),
  arriveAt: launch.arriveAt.toISOString(),
  engagementEndsAt: launch.engagementEndsAt.toISOString(),
  homeAt: launch.homeAt.toISOString(),
});

/**
 * A REPLAY RE-READS VOLATILE D53 PROJECTIONS INSTEAD OF RESTORING OLD STATE.
 *
 * A DELIBERATE DEPARTURE FROM "IN THE SAME TRANSACTION", AND THE ONE ROUTE THAT
 * NEEDS IT. D53 says a mutation answers with the authoritative planet view its own
 * GET would give, read inside the mutating transaction — which is right precisely
 * because it stops a stale read landing after the write. This launch is idempotent,
 * so its answer is also REPLAYED: `request_log` stores the immutable command result
 * and hands it back to a retry of the same key, possibly minutes later.
 *
 * A stored `planet` and `pending` would then be a snapshot from that earlier
 * instant, and writing it into the client cache would roll the world BACKWARDS past
 * everything that happened in between — the exact failure D53 exists to prevent,
 * arriving through the door marked "safe retry". So only the immutable half of the
 * answer is stored, and the volatile half is hydrated here, after the command has
 * committed, on both the first response and every replay.
 *
 * The projection is therefore never older than the launch; it may be newer, which
 * is the direction that is always safe.
 */
async function freshProjection(
  app: FastifyInstance,
  playerId: string,
  requestedPlanetId: string,
) {
  return app.db.transaction(async (tx) => {
    const [stillMine] = await tx.select({ id: planets.id }).from(planets).where(and(
      eq(planets.id, requestedPlanetId),
      eq(planets.controllerPlayerId, playerId),
    )).limit(1);
    const projectionPlanetId = stillMine?.id ?? (await capitalPlanet(tx, playerId)).id;
    const planet = await loadPlanetViewData(tx, projectionPlanetId, app.clock);
    const pending = await pendingThreads(tx, projectionPlanetId, app.clock.now());
    return { planet, pending };
  }).then(buildPlanetResult);
}

export function registerIntergalacticConvoyRoutes(app: FastifyInstance): void {
  app.post('/api/intergalactic-convoy/launch', { preHandler: requireAuth }, async (req) => {
    const body = convoyLaunchBody.parse(req.body);
    const commander = await commanderForAccount(app.db, req.accountId!);
    const now = app.clock.now();
    const immutable = await idempotentMutation(app.db, {
      playerId: commander.playerId,
      operation: 'intergalactic-convoy.launch',
      key: idempotencyKey(req),
      body,
      now,
      onOutcome: (outcome) => {
        app.metrics.observeOperation('intergalactic-convoy.launch', outcome);
      },
    }, async (tx) => wireLaunch(await launchIntergalacticConvoy(tx, {
      planetId: body.originPlanetId,
      expectedPlayerId: commander.playerId,
      order: {
        occurrenceId: body.occurrenceId,
        fleet: body.fleet,
        quotedAt: new Date(body.quotedAt),
        quotedFlightSeconds: body.quotedFlightSeconds,
        quotedArriveAt: new Date(body.quotedArriveAt),
        acknowledgeRadiationLoss: body.acknowledgeRadiationLoss,
        expectedHonorTier: body.expectedHonorTier,
      },
      clock: { now: () => now },
    })));
    return {
      ...immutable,
      ...await freshProjection(app, commander.playerId, body.originPlanetId),
    };
  });
}

sources.apps/server/src/routes/mining.ts:
import { and, eq, inArray } from 'drizzle-orm';
import { alias } from 'drizzle-orm/pg-core';
import type { FastifyInstance } from 'fastify';
import { z } from 'zod';
import { buildings, miningRuns, planets, players, playerResearch, satellites, seasons } from '../db/schema.js';
import { GameError, orbitFromRows } from '../services/planet.js';
import { techOf } from '../services/researchState.js';
import {
  launchHarvest,
  launchMining,
  recallMining,
  projectIsotopeKnowledge,
  projectPrivateMiningView,
  prospectorCooldowns,
  projectVisibleDebris,
} from '../services/mining.js';
import { projectPlayerAsteroidField } from '../services/asteroidField.js';
import { requireAuth } from './auth.js';
import { ownedPlanet } from '../services/ownership.js';
import type { Queryable } from '../db/client.js';

const launchBody = z.object({
  originPlanetId: z.string().uuid().optional(),
  asteroidId: z.string().regex(/^[A-Za-z0-9_-]{22}$/),
  craft: z.number().int().min(1).max(500),
}).strict();

/**
 * MINING — the Drill's reason to exist. D19.
 *
 * Asteroid existence is earned through the commander's durable sensor history;
 * only then does the rock become a public race for that commander. The underlying
 * ore/wreck snapshot is shared, but `/field` applies caller fog and opaque ids on
 * every read. Hardware, research and own runs stay on `/status` so shard events do
 * not fan out those private rows.
 */
export function registerMiningRoutes(app: FastifyInstance): void {
  const me = async (accountId: string, db: Queryable = app.db) => {
    const rows = await db
      .select({ planetId: planets.id, seasonId: players.seasonId, playerId: players.id })
      .from(players)
      .innerJoin(planets, and(eq(planets.controllerPlayerId, players.id), eq(planets.kind, 'CAPITAL')))
      .where(eq(players.accountId, accountId))
      .limit(1);
    const row = rows[0];
    if (!row) throw new GameError('NO_PLANET', 'Join a galaxy first', 404);
    return row;
  };

  const privateView = async (accountId: string, planetId?: string) => {
    const capital = alias(planets, 'mining_capital');
    const selected = alias(planets, 'mining_selected');
    const runOrigin = alias(planets, 'mining_run_origin');
    const selectedId = planetId === undefined
      ? eq(selected.id, capital.id)
      : eq(selected.id, planetId);
    // Identity, ownership, active hardware, research and private flights are one
    // atomic SQL snapshot. No surrounding transaction is needed: there is no
    // second private read for ownership to race with.
    const rows = await app.db
      .select({
        playerId: players.id,
        seasonId: players.seasonId,
        asteroidKey: seasons.asteroidKey,
        planetId: selected.id,
        kind: selected.kind,
        coreLevel: buildings.level,
        satelliteSlot: satellites.slot,
        satelliteType: satellites.type,
        researchProjectId: playerResearch.projectId,
        run: miningRuns,
      })
      .from(players)
      .innerJoin(seasons, eq(seasons.id, players.seasonId))
      .innerJoin(
        capital,
        and(eq(capital.controllerPlayerId, players.id), eq(capital.kind, 'CAPITAL')),
      )
      .innerJoin(selected, and(eq(selected.controllerPlayerId, players.id), selectedId))
      .leftJoin(
        buildings,
        and(eq(buildings.planetId, selected.id), eq(buildings.type, 'CORE')),
      )
      .leftJoin(satellites, eq(satellites.planetId, selected.id))
      /*
        THE COMMANDER'S SPECTROMETRY, NOT THE WORLD'S. T7.

        This joined `planet_research` on the selected world. After research moved
        to the commander that join can only ever miss, and the failure is SILENT:
        the route would simply report every isotope anomaly as unreadable to a
        player who had paid for the project. Keyed on `players.id`, which is what
        the gate always meant.
      */
      .leftJoin(
        playerResearch,
        and(
          eq(playerResearch.playerId, players.id),
          eq(playerResearch.projectId, 'ISOTOPE_SPECTROMETRY'),
        ),
      )
      // Hardware belongs to the selected world; airborne Prospectors belong to
      // the commander. Joining every currently controlled origin keeps a run on
      // the galaxy and in the pending strip when another colony is selected.
      .leftJoin(runOrigin, eq(runOrigin.controllerPlayerId, players.id))
      .leftJoin(
        miningRuns,
        and(
          eq(miningRuns.planetId, runOrigin.id),
          inArray(miningRuns.status, ['outbound', 'returning']),
        ),
      )
      .where(eq(players.accountId, accountId));
    const first = rows[0];
    if (!first) {
      if (planetId !== undefined) {
        // Keep NO_PLANET distinct from naming another commander's world. The
        // extra lookup is on a refusal only.
        await me(accountId);
        throw new GameError('PLANET_NOT_OWNED', 'You do not control that world', 403);
      }
      throw new GameError('NO_PLANET', 'Join a galaxy first', 404);
    }
    if (first.kind === 'NEUTRAL') {
      throw new GameError('PLANET_NOT_OWNED', 'You do not control that world', 403);
    }
    const orbit = orbitFromRows(
      rows.flatMap((row) => row.satelliteSlot === null || row.satelliteType === null
        ? []
        : [{ slot: row.satelliteSlot, type: row.satelliteType }]),
      first.coreLevel ?? 0,
    );
    const runs = [...new Map(
      rows.flatMap((row) => row.run === null ? [] : [[row.run.id, row.run] as const]),
    ).values()];
    const cooldowns = await prospectorCooldowns(app.db, first.planetId, app.clock.now());
    return {
      seasonId: first.seasonId,
      revealIsotopes: rows.some(
        (row) => row.researchProjectId === 'ISOTOPE_SPECTROMETRY',
      ),
      playerId: first.playerId,
      view: projectPrivateMiningView(
        orbit,
        runs,
        await techOf(app.db, first.playerId),
        first.asteroidKey,
        cooldowns.at(-1)?.readyAt ?? null,
        cooldowns,
      ),
    };
  };

  const fieldView = async (seasonId: string, playerId: string, revealIsotopes: boolean) => {
    const now = app.clock.now();
    const snapshot = await app.projections.miningSnapshot(seasonId, now);
    const epochs = await app.projections.historyFor(playerId, seasonId);
    const field = projectPlayerAsteroidField(
      snapshot,
      snapshot.asteroidKey,
      epochs,
      now,
      revealIsotopes,
    );
    return {
      asteroids: field.asteroids.map((asteroid) => ({
        id: asteroid.id,
        level: asteroid.level,
        ore: asteroid.ore,
        oreRemaining: Math.round(asteroid.oreRemaining),
        crystalShare: Math.round(asteroid.crystalShare * 100) / 100,
        radius: asteroid.radius,
        period: asteroid.period,
        phase: asteroid.phase,
        inclination: asteroid.inclination,
        ascendingNode: asteroid.ascendingNode,
        speed: asteroid.speed,
        appearsAt: asteroid.appearsAt,
        expiresAt: asteroid.expiresAt,
        active: asteroid.active,
        isotopeRich: asteroid.isotopeRich,
        deuteriumShare: asteroid.deuteriumShare === null
          ? null
          : Math.round(asteroid.deuteriumShare * 100) / 100,
      })),
      debris: projectVisibleDebris(snapshot, now).map((field) => ({
        id: field.id,
        /** NULL when the battle happened in open space — a pirate fight. D150. */
        planetId: field.planetId,
        /** Where the wreckage is. Always present; the client never resolves a world. */
        at: { x: field.x, y: field.y, z: field.z },
        alloy: Math.round(field.alloy),
        crystal: Math.round(field.crystal),
        deuterium: Math.round(field.deuterium),
        minutesLeft: Math.round(field.minutesLeft),
      })),
      nextFieldChangeAt: field.nextFieldChangeAt,
    };
  };

  /**
   * What is crossing the disc right now, and what your craft could do about it.
   *
   * The rocks come with their full trajectory rather than a position, so the
   * client animates them from its own clock instead of polling — the same
   * arrangement that lets fleets move for zero bandwidth (A4, A5).
   */
  app.get('/api/mining', { preHandler: requireAuth }, async (req) => {
    const query = z.object({ planetId: z.string().uuid().optional() }).strict().parse(req.query);
    const own = await privateView(req.accountId!, query.planetId);
    return {
      ...own.view,
      ...await fieldView(own.seasonId, own.playerId, own.revealIsotopes),
    };
  });

  /** Caller-filtered field; shard invalidation is safe because the query reapplies fog. */
  app.get('/api/mining/field', { preHandler: requireAuth }, async (req) => {
    const commander = await app.projections.commander(req.accountId!);
    return fieldView(commander.seasonId, commander.playerId, false);
  });

  /** Caller-only hardware, isotope entitlement and active runs. */
  app.get('/api/mining/status', { preHandler: requireAuth }, async (req) => {
    const query = z.object({ planetId: z.string().uuid().optional() }).strict().parse(req.query);
    const own = await privateView(req.accountId!, query.planetId);
    const revealed = own.revealIsotopes
      ? projectIsotopeKnowledge((await fieldView(own.seasonId, own.playerId, true)).asteroids)
      : [];
    return { ...own.view, isotopes: revealed };
  });

  /** Send craft to a wreck field. D32. */
  app.post('/api/mining/harvest', { preHandler: requireAuth }, async (req) => {
    const body = z
      .object({ originPlanetId: z.string().uuid().optional(), fieldId: z.string().uuid(), craft: z.number().int().min(1).max(500) }).strict()
      .parse(req.body);
    const legacy = await me(req.accountId!);
    const planetId = body.originPlanetId ?? legacy.planetId;
    const owner = body.originPlanetId
      ? await ownedPlanet(app.db, req.accountId!, body.originPlanetId)
      : legacy;
    return launchHarvest(app.db, planetId, body.fieldId, body.craft, app.clock, owner.playerId);
  });

  /** Send craft at a rock. Refused if it will be gone before they arrive. */
  app.post('/api/mining/launch', { preHandler: requireAuth }, async (req) => {
    const body = launchBody.parse(req.body);
    const legacy = await me(req.accountId!);
    const planetId = body.originPlanetId ?? legacy.planetId;
    const owner = body.originPlanetId
      ? await ownedPlanet(app.db, req.accountId!, body.originPlanetId)
      : legacy;
    const result = await launchMining(
      app.db,
      planetId,
      body.asteroidId,
      body.craft,
      app.clock,
      owner.playerId,
    );
    const { asteroidIndex: _internalIndex, ...publicResult } = result;
    return publicResult;
  });

  /** Turn only an outbound Prospector run around; every other craft stays committed. */
  app.post('/api/mining/runs/:runId/recall', { preHandler: requireAuth }, async (req) => {
    const { runId } = z.object({ runId: z.string().uuid() }).strict().parse(req.params);
    const commander = await me(req.accountId!);
    return recallMining(app.db, runId, app.clock, commander.playerId);
  });
}

