import type { FastifyInstance } from 'fastify';
import { z } from 'zod';
import {
  BUILDING_IDS,
  HULLS,
  INSTRUMENT_IDS,
  RESEARCH_PROJECT_IDS,
  SATELLITE_IDS,
  SHIP_DAMAGE,
  FEATURE_FLAGS,
  type HullId,
} from '@astera/rules';
import { and, eq } from 'drizzle-orm';
import { planets } from '../db/schema.js';
import { startFaultRepair } from '../services/faultRepair.js';
import { startRepair } from '../services/repair.js';
import { loadPlanetViewData, buildPlanetView, type PlanetViewData } from '../services/planetView.js';
import { maintenanceAction } from '../services/maintenance.js';
import {
  buildUnits,
  collectWorks,
  installSatellite,
  raiseInstrument,
  upgradeBuilding,
} from '../services/build.js';
import { launchAttack } from '../services/mission.js';
import { requireAuth } from './auth.js';
import { completeResearch } from '../services/research.js';
import { capitalPlanet, commanderForAccount, ownedPlanet } from '../services/ownership.js';
import { GameError } from '../services/planet.js';
import { buildDeathStar, buildInterceptor, launchDeathStar } from '../services/strategic.js';
import { buildRadiationBomb, launchRadiationBomb } from '../services/radiationBomb.js';
import { setDefencePosture } from '../services/clanSupport.js';
import { launchSettlement, launchTransfer, recallFlight } from '../services/movement.js';
import { cancelBuildOrder } from '../services/buildQueue.js';
import { abandonColony, colonyAbandonment } from '../services/colonyAbandonment.js';
import { honorTargetPreview } from '../services/honorTarget.js';

/**
 * Five structures. The Orbital Ring is not one of them any more (D22): satellites
 * stopped being rationed by slots, which was the only thing it sold. A request
 * naming it is now rejected at the boundary rather than quietly raising a building
 * that does nothing.
 */
/**
 * EVERY ID LIST HERE IS DERIVED, AND NONE OF THEM IS TYPED TWICE.
 *
 * These were hand-written `z.enum` literals beside the generated enums in
 * `packages/rules`, and three of them had quietly fallen behind — the Hangar and
 * the Deuterium Refinery were missing from the buildings, and eleven of the fifteen
 * research projects were missing from the research list. The server answered 400 to
 * things it fully implements, which reads as a malformed request rather than as a
 * missing case, and nothing could catch it: a `z.enum` of string literals is valid
 * TypeScript whatever it leaves out.
 *
 * `zodEnum` is the one cast that makes this work — `z.enum` wants a non-empty
 * tuple and a readonly array does not prove it is one. Every list below is
 * non-empty by construction.
 */
const zodEnum = <T extends string>(values: readonly T[]) =>
  z.enum(values as unknown as [T, ...T[]]);

const BUILDING = zodEnum(BUILDING_IDS);
/**
 * TWO LISTS, BECAUSE THEY ARE TWO KINDS OF THING. D25.
 *
 * Instruments sit on the ground and carry levels; satellites sit in orbit, take a
 * slot, and are bought once. The Drill is on neither list — it became a craft, and
 * the Shipyard builds craft.
 */
const INSTRUMENT = zodEnum(INSTRUMENT_IDS);
const SATELLITE = zodEnum(SATELLITE_IDS);
/**
 * What may be put in an attack fleet. A Prospector is deliberately absent: it is
 * not a warship, and D19 keeps mining traffic out of the fog layer entirely.
 */
const ALL_HULL_IDS = Object.keys(HULLS) as HullId[];
/* By the PROPERTY that makes a hull mobile, not by a second list of names. */
const MOBILE = zodEnum(ALL_HULL_IDS.filter(
  (id) => !HULLS[id].ground && id !== 'PROSPECTOR',
));
const HULL = zodEnum(ALL_HULL_IDS);
const BOMB_LEVEL = z.union([z.literal(1), z.literal(2), z.literal(3)]);
const RESEARCH = zodEnum(RESEARCH_PROJECT_IDS);

const launchBody = z.object({
  originPlanetId: z.string().uuid().optional(),
  targetPlanetId: z.string().uuid(),
  fleet: z.record(MOBILE, z.number().int().min(0)).refine(
    (f) => Object.values(f).some((n) => n > 0),
    'Send at least one ship',
  ),
  /**
   * THE COMMANDER HAS READ WHAT THIS COSTS THEM. D183.
   *
   * Not client-authored state: it grants nothing and decides nothing. The launch
   * refuses once with `SHIELD_WOULD_DROP`, the surface asks, and this is the answer
   * coming back — a first-day shield spent without being offered is a shield the
   * player did not choose to spend.
   */
  acknowledgeShieldLoss: z.boolean().optional(),
  /** The commander has read what radiation on this route would take. Plan D10. */
  acknowledgeRadiation: z.boolean().optional(),
  /**
   * HOW FAST TO FLY IT. Owner decision, 2026-09-21.
   *
   * Parsed as a plain number rather than an enum of the ladder, so the refusal comes from
   * `allowedPaces` — the rule that knows about THIS flight — instead of from a schema that would
   * have to be kept in step with it and would give the same answer for "not a rung" and "too slow
   * for this distance".
   */
  pace: z.number().positive().max(1).optional(),
}).strict();

export function registerPlanetRoutes(app: FastifyInstance): void {
  /** Resolve the caller's planet, or 404. Never trusts a planet id from the client. */
  const myPlanet = async (accountId: string): Promise<string> => {
    const commander = await commanderForAccount(app.db, accountId);
    return (await capitalPlanet(app.db, commander.playerId)).id;
  };

  const explicitPlanet = async (accountId: string, raw: unknown) => {
    const { planetId } = z.object({ planetId: z.string().uuid() }).strict().parse(raw);
    return ownedPlanet(app.db, accountId, planetId);
  };

  /**
   * A PRIVATE VIEW IS A READ. Resource analysis 2026-10-13.
   *
   * These GETs used to take the season SHARE and every owned world FOR UPDATE, then
   * persist the lazy tick. A resync asks for all three together, so a commander's own
   * reads queued behind each other and the worker queued behind them. The economy is
   * a pure function of the stored row and the clock, and every mutation ticks under
   * its own lock first, so one read-only snapshot gives the same figures with no lock,
   * no write and no lock-order hazard against lifecycle writers.
   */
  const VIEW_SNAPSHOT = { isolationLevel: 'repeatable read', accessMode: 'read only' } as const;
  const READ_ONLY = { readOnly: true } as const;

  app.get('/api/planets', { preHandler: requireAuth }, async (req) => {
    const captured = await app.db.transaction(async (tx) => {
      const commander = await commanderForAccount(tx, req.accountId!);
      const owned = await tx.select({ id: planets.id, kind: planets.kind }).from(planets)
        .where(eq(planets.controllerPlayerId, commander.playerId));
      const worlds = owned.toSorted((a, b) =>
        a.kind === b.kind ? a.id.localeCompare(b.id) : a.kind === 'CAPITAL' ? -1 : 1,
      );
      const views: PlanetViewData[] = [];
      // One clock instant and commander snapshot for the whole response. The first
      // world brings the commander; the rest share it and load together, pipelined
      // on this snapshot, instead of one after another.
      const now = app.clock.now();
      const at = { now: () => now };
      const [first, ...rest] = worlds;
      if (first) {
        const head = await loadPlanetViewData(tx, first.id, at, undefined, READ_ONLY);
        views.push(head, ...await Promise.all(rest.map((world) =>
          loadPlanetViewData(tx, world.id, at, head.commander, READ_ONLY))));
      }
      return {
        playerId: commander.playerId,
        seasonId: commander.seasonId,
        capitalPlanetId: worlds.find((world) => world.kind === 'CAPITAL')?.id ?? null,
        planets: views,
      };
    }, VIEW_SNAPSHOT);
    return { ...captured, planets: captured.planets.map(buildPlanetView) };
  });

  app.get('/api/planets/:planetId', { preHandler: requireAuth }, async (req) => {
    const { planetId } = z.object({ planetId: z.string().uuid() }).strict().parse(req.params);
    return app.db.transaction(async (tx) => {
      const commander = await commanderForAccount(tx, req.accountId!);
      const [owned] = await tx.select({ id: planets.id }).from(planets).where(and(
        eq(planets.id, planetId),
        eq(planets.controllerPlayerId, commander.playerId),
      ));
      if (!owned) throw new GameError('PLANET_NOT_OWNED', 'You no longer control that world', 403);
      return loadPlanetViewData(tx, planetId, app.clock, undefined, READ_ONLY);
    }, VIEW_SNAPSHOT).then(buildPlanetView);
  });

  app.get('/api/planet', { preHandler: requireAuth }, async (req) => {
    const planetId = await myPlanet(req.accountId!);
    return app.db.transaction(tx => loadPlanetViewData(tx, planetId, app.clock, undefined, READ_ONLY), VIEW_SNAPSHOT)
      .then(buildPlanetView);
  });

  app.get('/api/planets/:planetId/abandon', { preHandler: requireAuth }, async req => {
    const owner = await explicitPlanet(req.accountId!, req.params);
    return colonyAbandonment(app.db, owner.planetId, owner.playerId, app.clock);
  });

  app.post('/api/planets/:planetId/abandon', { preHandler: requireAuth }, async req => {
    z.object({ confirm: z.literal(true) }).strict().parse(req.body);
    const owner = await explicitPlanet(req.accountId!, req.params);
    return abandonColony(app.db, owner.planetId, owner.playerId, app.clock);
  });

  /**
   * Empty the works into storage. D16.
   *
   * No body, and no error when there is nothing there: the interface offers this
   * button whenever the works hold anything, and a player who taps it a moment
   * after a raid emptied them should get a calm zero rather than a refusal.
   */
  app.post('/api/planet/collect', { preHandler: requireAuth }, async (req) => {
    const planetId = await myPlanet(req.accountId!);
    return collectWorks(app.db, planetId, app.clock);
  });

  app.post('/api/planets/:planetId/collect', { preHandler: requireAuth }, async (req) => {
    const owner = await explicitPlanet(req.accountId!, req.params);
    return collectWorks(app.db, owner.planetId, app.clock, owner.playerId);
  });

  app.post('/api/planet/upgrade', { preHandler: requireAuth }, async (req) => {
    const { type, confirmedLevel } = z.object({ type: BUILDING, confirmedLevel: z.number().int().positive().optional() }).strict().parse(req.body);
    const planetId = await myPlanet(req.accountId!);
    return upgradeBuilding(app.db, planetId, type, app.clock, undefined, { confirmedLevel });
  });
  app.post('/api/planets/:planetId/upgrade', { preHandler: requireAuth }, async (req) => {
    const { type, confirmedLevel } = z.object({ type: BUILDING, confirmedLevel: z.number().int().positive().optional() }).strict().parse(req.body);
    const owner = await explicitPlanet(req.accountId!, req.params);
    return upgradeBuilding(app.db, owner.planetId, type, app.clock, owner.playerId, { confirmedLevel });
  });

  app.post('/api/planet/build', { preHandler: requireAuth }, async (req) => {
    const { hull, count } = z
      .object({ hull: HULL, count: z.number().int().min(1).max(10_000) }).strict()
      .parse(req.body);
    const planetId = await myPlanet(req.accountId!);
    return buildUnits(app.db, planetId, hull, count, app.clock);
  });
  app.post('/api/planets/:planetId/build', { preHandler: requireAuth }, async (req) => {
    const { hull, count } = z
      .object({ hull: HULL, count: z.number().int().min(1).max(10_000) }).strict()
      .parse(req.body);
    const owner = await explicitPlanet(req.accountId!, req.params);
    return buildUnits(app.db, owner.planetId, hull, count, app.clock, owner.playerId);
  });

  app.post('/api/planet/build-orders/:orderId/cancel', { preHandler: requireAuth }, async (req) => {
    const { orderId } = z.object({ orderId: z.string().uuid() }).strict().parse(req.params);
    z.object({}).strict().parse(req.body ?? {});
    const planetId = await myPlanet(req.accountId!);
    return cancelBuildOrder(app.db, planetId, orderId, app.clock);
  });
  app.post(
    '/api/planets/:planetId/build-orders/:orderId/cancel',
    { preHandler: requireAuth },
    async (req) => {
      const { planetId, orderId } = z.object({
        planetId: z.string().uuid(),
        orderId: z.string().uuid(),
      }).strict().parse(req.params);
      z.object({}).strict().parse(req.body ?? {});
      const owner = await ownedPlanet(app.db, req.accountId!, planetId);
      return cancelBuildOrder(app.db, owner.planetId, orderId, app.clock, owner.playerId);
    },
  );

  /** Commander research has its own account-wide, irreversible queue. D4/D134. */
  app.post('/api/planet/research', { preHandler: requireAuth }, async (req) => {
    const { projectId } = z.object({ projectId: RESEARCH }).strict().parse(req.body);
    const planetId = await myPlanet(req.accountId!);
    return completeResearch(app.db, planetId, projectId, app.clock);
  });
  app.post('/api/planets/:planetId/research', { preHandler: requireAuth }, async (req) => {
    const { projectId } = z.object({ projectId: RESEARCH }).strict().parse(req.body);
    const owner = await explicitPlanet(req.accountId!, req.params);
    return completeResearch(app.db, owner.planetId, projectId, app.clock, owner.playerId);
  });
  app.post('/api/planet/research-orders/:orderId/cancel', { preHandler: requireAuth }, (req) => {
    z.object({ orderId: z.string().uuid() }).strict().parse(req.params);
    z.object({}).strict().parse(req.body ?? {});
    throw new GameError(
      'RESEARCH_CANNOT_BE_CANCELLED',
      'Research commitments cannot be cancelled',
      409,
    );
  });
  app.post(
    '/api/planets/:planetId/research-orders/:orderId/cancel',
    { preHandler: requireAuth },
    (req) => {
      z.object({
        planetId: z.string().uuid(),
        orderId: z.string().uuid(),
      }).strict().parse(req.params);
      z.object({}).strict().parse(req.body ?? {});
      throw new GameError(
        'RESEARCH_CANNOT_BE_CANCELLED',
        'Research commitments cannot be cancelled',
        409,
      );
    },
  );

  /** Raise one of the four ground instruments. D25. */
  app.post('/api/planet/instrument', { preHandler: requireAuth }, async (req) => {
    const { type } = z.object({ type: INSTRUMENT }).strict().parse(req.body);
    const planetId = await myPlanet(req.accountId!);
    return raiseInstrument(app.db, planetId, type, app.clock);
  });
  app.post('/api/planets/:planetId/instrument', { preHandler: requireAuth }, async (req) => {
    const { type } = z.object({ type: INSTRUMENT }).strict().parse(req.body);
    const owner = await explicitPlanet(req.accountId!, req.params);
    return raiseInstrument(app.db, owner.planetId, type, app.clock, owner.playerId);
  });

  /** Put one of the four satellites in orbit. Bought once, never raised. D25. */
  app.post('/api/planet/satellite', { preHandler: requireAuth }, async (req) => {
    const { type } = z.object({ type: SATELLITE }).strict().parse(req.body);
    const planetId = await myPlanet(req.accountId!);
    return installSatellite(app.db, planetId, type, app.clock);
  });
  app.post('/api/planets/:planetId/satellite', { preHandler: requireAuth }, async (req) => {
    const { type } = z.object({ type: SATELLITE }).strict().parse(req.body);
    const owner = await explicitPlanet(req.accountId!, req.params);
    return installSatellite(app.db, owner.planetId, type, app.clock, owner.playerId);
  });

  app.post('/api/planets/:planetId/radiation-bombs/build', { preHandler: requireAuth }, async (req) => {
    if (!FEATURE_FLAGS.STRATEGIC_CRAFTING_ENABLED) {
      throw new GameError('STRATEGIC_UNAVAILABLE', 'No such crafting route', 404);
    }
    const { level } = z.object({ level: BOMB_LEVEL }).strict().parse(req.body);
    const owner = await explicitPlanet(req.accountId!, req.params);
    return buildRadiationBomb(app.db, owner.planetId, level, app.clock, owner.playerId);
  });

  app.post('/api/planets/:planetId/death-star/build', { preHandler: requireAuth }, async (req) => {
    if (!FEATURE_FLAGS.STRATEGIC_CRAFTING_ENABLED) {
      throw new GameError('STRATEGIC_UNAVAILABLE', 'No such crafting route', 404);
    }
    z.object({}).strict().parse(req.body ?? {});
    const owner = await explicitPlanet(req.accountId!, req.params);
    return buildDeathStar(app.db, owner.planetId, app.clock, owner.playerId);
  });

  /**
   * LOAD ONE INTERCEPTION CHARGE. T10, wired in T12.
   *
   * `buildInterceptor` shipped complete and tested with no route to reach it, so
   * the Interception Grid was a research project that authorised nothing. It takes
   * the weapon's shape deliberately: same asset table, same completion event, same
   * answer — one charge is one row, and reloading is another build.
   */
  app.post('/api/planets/:planetId/interceptor/build', { preHandler: requireAuth }, async (req) => {
    if (!FEATURE_FLAGS.STRATEGIC_CRAFTING_ENABLED) {
      throw new GameError('STRATEGIC_UNAVAILABLE', 'No such crafting route', 404);
    }
    z.object({}).strict().parse(req.body ?? {});
    const owner = await explicitPlanet(req.accountId!, req.params);
    return buildInterceptor(app.db, owner.planetId, app.clock, owner.playerId);
  });

  /**
   * SAVE A WORLD'S TWO DEFENCE TOGGLES. Klan Savunma Desteği, owner K4 · 2026-10-01.
   *
   * The Hangar page drafts both switches and sends them together on Kaydet. Setting the
   * posture a world already has is a no-op, so a retried press changes nothing; the
   * answer carries the world and how many clan waves went home because of it.
   */
  app.post('/api/planets/:planetId/defence-posture', { preHandler: requireAuth }, async (req) => {
    const toggles = z.object({ escape: z.boolean(), support: z.boolean() }).strict().parse(req.body);
    const owner = await explicitPlanet(req.accountId!, req.params);
    return app.db.transaction((tx) => setDefencePosture(tx, {
      planetId: owner.planetId,
      playerId: owner.playerId,
      toggles,
      clock: app.clock,
    }));
  });

  /**
   * PUT ONE FAULT RIGHT. Koloni arızaları.
   *
   * THERE IS NO CANCEL ROUTE AND THERE IS NOT GOING TO BE ONE. Owner instruction:
   * *"Arıza fix başladıgında cancel edilemez olsun hiç ugrasma."* Its absence is the
   * contract — the strip draws three lanes with no way out and the sheet says so before
   * the button is pressed, which is the same promise stated twice rather than a gap.
   *
   * The planet is named in the path rather than taken from the session, because a
   * commander repairs a COLONY far more often than their capital and the notification
   * that brought them here names the world.
   */
  app.post('/api/planets/:planetId/faults/:faultId/repair', { preHandler: requireAuth }, async (req) => {
    const { planetId, faultId } = z
      .object({ planetId: z.string().uuid(), faultId: z.string().uuid() })
      .strict()
      .parse(req.params);
    z.object({}).strict().parse(req.body ?? {});
    const owner = await ownedPlanet(app.db, req.accountId!, planetId);
    return startFaultRepair(app.db, owner.planetId, faultId, app.clock, owner.playerId);
  });

  /**
   * THE REPAIR STATION. Kalıcı gemi hasarı (`plan.md` F4).
   *
   * The world is named in the path, as a fault repair names it: the dock a commander
   * opens is usually the colony a fight happened at. The body is exactly one of the two
   * shapes; a cancel is the yard's own `build-orders/:orderId/cancel` door.
   */
  app.post('/api/planets/:planetId/repairs', { preHandler: requireAuth }, async (req) => {
    const { planetId } = z.object({ planetId: z.string().uuid() }).strict().parse(req.params);
    const request = z.union([
      z.object({ lotIds: z.array(z.string().uuid()).min(1).max(SHIP_DAMAGE.repairLotsPerOrder),
        expectedHonorTier: z.union([z.literal(-2), z.literal(-1), z.literal(0), z.literal(1), z.literal(2)]).optional() }).strict(),
      z.object({ all: z.literal(true), expectedHonorTier: z.union([z.literal(-2), z.literal(-1), z.literal(0), z.literal(1), z.literal(2)]).optional() }).strict(),
      z.object({ lots: z.array(z.object({ id: z.string().uuid(), count: z.number().int().positive().max(2_147_483_647),
        damageBp: z.number().int().min(0).max(9999), remainderBp: z.number().min(0).lt(1),
      }).strict()).min(1).max(SHIP_DAMAGE.repairLotsPerOrder),
        expectedHonorTier: z.union([z.literal(-2), z.literal(-1), z.literal(0), z.literal(1), z.literal(2)]).optional() }).strict(),
    ]).parse(req.body ?? {});
    const owner = await ownedPlanet(app.db, req.accountId!, planetId);
    const key = req.headers['idempotency-key'] === undefined ? undefined : z.string().min(8).max(128).parse(req.headers['idempotency-key']);
    if ('lots' in request && key === undefined) throw new GameError('REPAIR_RETRY_KEY_REQUIRED', 'Confirm this repair with a retry key', 400);
    return startRepair(app.db, owner.planetId, request, app.clock, owner.playerId, key);
  });

  app.post('/api/planets/:planetId/maintenance', { preHandler: requireAuth }, async (req) => {
    const { planetId } = z.object({ planetId: z.string().uuid() }).strict().parse(req.params);
    const key = z.string().min(8).max(128).parse(req.headers['idempotency-key']);
    const count = z.number().int().positive().max(2_147_483_647);
    const mobileHull = zodEnum(ALL_HULL_IDS.filter((id) => !HULLS[id].ground));
    const body = z.object({ action: z.enum(['DOCK', 'RETURN', 'SCRAP']), selection: z.discriminatedUnion('source', [
      z.object({ source: z.literal('HOME'), groups: z.array(z.object({ hull: mobileHull, count,
        damageBp: z.number().int().min(0).max(9999), remainderBp: z.number().finite().min(0).lt(1).default(0),
      }).strict()).min(1).max(SHIP_DAMAGE.repairLotsPerOrder) }).strict(),
      z.object({ source: z.literal('DOCK'), lots: z.array(z.object({ id: z.string().uuid(), count,
        damageBp: z.number().int().min(0).max(9999).optional(), remainderBp: z.number().finite().min(0).lt(1).optional(),
      }).strict())
        .min(1).max(SHIP_DAMAGE.repairLotsPerOrder) }).strict(),
    ]) }).strict().refine(body => body.action !== 'SCRAP' || body.selection.source !== 'DOCK'
      || body.selection.lots.every(lot => lot.damageBp !== undefined && lot.remainderBp !== undefined),
    { message: 'Scrapping needs the selected ships’ health quote' }).parse(req.body);
    const owner = await ownedPlanet(app.db, req.accountId!, planetId);
    return maintenanceAction(app.db, owner.playerId, owner.planetId, body.action, body.selection, key, app.clock);
  });

  app.get('/api/honor/targets/:targetPlanetId', { preHandler: requireAuth }, async (req) => {
    const { targetPlanetId } = z.object({ targetPlanetId: z.string().uuid() }).parse(req.params);
    const owner = await commanderForAccount(app.db, req.accountId!);
    return honorTargetPreview(app.db, owner.playerId, targetPlanetId, app.clock, app.adminUsernames);
  });

  /**
   * Launch an attack. It may be turned once while it flies (`/api/fleet/:missionId/recall`, K8).
   *
   * The response leads with the exposure window because that is the line the UI
   * is built around: "home defence after launch, and for how long".
   */
  app.post('/api/fleet/launch', { preHandler: requireAuth }, async (req) => {
    const body = launchBody.parse(req.body);
    const planetId = body.originPlanetId ?? await myPlanet(req.accountId!);
    const owner = await ownedPlanet(app.db, req.accountId!, planetId);
    return launchAttack(
      app.db,
      planetId,
      body.targetPlanetId,
      body.fleet,
      app.clock,
      owner.playerId,
      body.acknowledgeShieldLoss ?? false,
      body.pace,
      body.acknowledgeRadiation ?? false,
      app.adminUsernames,
    );
  });

  app.post('/api/radiation-bombs/launch', { preHandler: requireAuth }, async (req) => {
    const body = z.object({
      originPlanetId: z.string().uuid(),
      level: BOMB_LEVEL,
      target: z.object({ kind: z.enum(['PLANET', 'MONUMENT']), id: z.string().uuid() }).strict(),
      acknowledgeShieldLoss: z.boolean().optional(),
    }).strict().parse(req.body);
    const key = z.string().min(8).max(128).parse(req.headers['idempotency-key']);
    const owner = await ownedPlanet(app.db, req.accountId!, body.originPlanetId);
    return launchRadiationBomb(app.db, { ...body, key, playerId: owner.playerId, clock: app.clock, adminUsernames: app.adminUsernames });
  });

  app.post('/api/death-star/launch', { preHandler: requireAuth }, async (req) => {
    const body = z.object({
      originPlanetId: z.string().uuid(),
      targetPlanetId: z.string().uuid(),
      /** The same acknowledgement the raid lane takes, for the same reason. D183. */
      acknowledgeShieldLoss: z.boolean().optional(),
    }).strict().parse(req.body);
    const owner = await ownedPlanet(app.db, req.accountId!, body.originPlanetId);
    return launchDeathStar(
      app.db,
      body.originPlanetId,
      body.targetPlanetId,
      app.clock,
      owner.playerId,
      body.acknowledgeShieldLoss ?? false,
      app.adminUsernames,
    );
  });

  app.post('/api/fleet/transfer', { preHandler: requireAuth }, async (req) => {
    const body = z.object({
      originPlanetId: z.string().uuid(),
      targetPlanetId: z.string().uuid(),
      fleet: z.record(HULL, z.number().int().min(0)),
      cargo: z.object({
        alloy: z.number().int().min(0),
        crystal: z.number().int().min(0),
        deuterium: z.number().int().min(0),
      }).strict(),
      /** How fast to fly it. Validated by `allowedPaces`, which knows about THIS flight. */
      pace: z.number().positive().max(1).optional(),
      returnPlan: z.object({
        cargoShips: z.enum(['STAY', 'RETURN']),
        otherShips: z.enum(['STAY', 'RETURN']),
      }).strict().default({ cargoShips: 'RETURN', otherShips: 'STAY' }),
      /** The commander has read what radiation on this route would take. Plan D10. */
      acknowledgeRadiation: z.boolean().optional(),
    }).strict().parse(req.body);
    const origin = await ownedPlanet(app.db, req.accountId!, body.originPlanetId);
    return launchTransfer(
      app.db,
      origin.playerId,
      body.originPlanetId,
      body.targetPlanetId,
      body.fleet,
      body.cargo,
      app.clock,
      body.pace,
      body.returnPlan,
      body.acknowledgeRadiation ?? false,
    );
  });

  /**
   * CALL A TRANSFER OR A RAID BACK. Owner decisions 2026-09-21 (transfers) and 2026-09-23 (raids, K8).
   *
   * The service decides everything — that it is a transfer or a raid, that it is still in the air,
   * that it has not already turned once, and that it belongs to the caller.
   */
  app.post('/api/fleet/:missionId/recall', { preHandler: requireAuth }, async (req) => {
    const { missionId } = z
      .object({ missionId: z.string().uuid() })
      .strict()
      .parse(req.params);
    z.object({}).strict().parse(req.body ?? {});
    const owner = await ownedPlanet(app.db, req.accountId!, await myPlanet(req.accountId!));
    return recallFlight(app.db, missionId, app.clock, owner.playerId);
  });

  app.post('/api/fleet/settle', { preHandler: requireAuth }, async (req) => {
    const body = z.object({
      originPlanetId: z.string().uuid(),
      targetPlanetId: z.string().uuid(),
    }).strict().parse(req.body);
    const origin = await ownedPlanet(app.db, req.accountId!, body.originPlanetId);
    return launchSettlement(
      app.db,
      origin.playerId,
      body.originPlanetId,
      body.targetPlanetId,
      app.clock,
    );
  });
}

