import type { FastifyInstance } from 'fastify';
import { z } from 'zod';
import { requireAuth } from './auth.js';
import { commanderForAccount } from '../services/ownership.js';
import { endVacation, startVacation, vacationStatus } from '../services/vacation.js';

export function registerVacationRoutes(app: FastifyInstance) {
  const days = z.coerce.number().int().min(1).max(7);
  app.get('/api/vacation', { preHandler: requireAuth }, async req => {
    const input = z.object({ days: days.default(1) }).strict().parse(req.query);
    const owner = await commanderForAccount(app.db, req.accountId!);
    return vacationStatus(app.db, owner.playerId, app.clock, input.days);
  });
  app.post('/api/vacation', { preHandler: requireAuth }, async req => {
    const input = z.object({ days: z.number().int().min(1).max(7), fingerprint: z.string().regex(/^[a-f0-9]{64}$/), requestId: z.string().uuid() }).strict().parse(req.body);
    const owner = await commanderForAccount(app.db, req.accountId!);
    return startVacation(app.db, owner.playerId, input.days, input.fingerprint, input.requestId, app.clock);
  });
  app.post('/api/vacation/end', { preHandler: requireAuth }, async req => {
    const input = z.object({ vacationId: z.string().uuid() }).strict().parse(req.body);
    const owner = await commanderForAccount(app.db, req.accountId!);
    return endVacation(app.db, owner.playerId, input.vacationId, app.clock);
  });
}

sources.apps/server/src/schemas/fleet.ts:
import {
  ALL_HULLS,
  FLEET_V2_HULLS,
} from '@astera/rules';
import { z } from 'zod';

/** Zod requires a mutable non-empty tuple; rules-owned catalogs are readonly. */
const zodEnum = <T extends string>(values: readonly T[]) =>
  z.enum(values as unknown as [T, ...T[]]);

/** Every persisted/buildable hull, including preserved ground/mining hardware. */
export const allHullIdSchema = zodEnum(ALL_HULLS);

/** Every craft allowed to move; ground defence and Prospector are intentionally absent. */
export const mobileHullIdSchema = zodEnum(FLEET_V2_HULLS);

export const mobileFleetSchema = z.record(
  mobileHullIdSchema,
  z.number().int().min(0),
);

/**
 * The unauthenticated rehearsal vocabulary. Build IDs stay exhaustive so the
 * authoritative build service — not a second route catalog — owns availability.
 * Launch remains only for cached pre-queue rehearsals and uses the same mobile
 * manifest parser as every other server boundary.
 */
export const onboardingIntentSchema = z.discriminatedUnion('kind', [
  z.object({
    kind: z.literal('upgrade'),
    building: z.enum(['CORE', 'REFINERY', 'EXTRACTOR', 'VAULT', 'SHIPYARD']),
  }),
  z.object({
    kind: z.literal('build'),
    hull: allHullIdSchema,
    count: z.number().int().min(1).max(100),
  }),
  z.object({
    kind: z.literal('launch'),
    targetPlanetId: z.string().uuid(),
    fleet: mobileFleetSchema,
  }),
]);

