/**
 * DELETING A PERSON, AT THEIR OWN REQUEST.
 *
 * `reclaim.ts` takes a SEASON PRESENCE from somebody who stopped coming back and
 * deliberately keeps the account, because they are expected to return. This takes
 * the account too, because they asked to be forgotten. The legacy command keeps
 * its historical guards; the app request path requires exact request identity
 * and operator approval before calling the same destructive implementation.
 *
 * ── IT DOES NOT HOLD A SECOND OPINION ABOUT WHAT A WORLD IS ─────────────────
 *
 * The whole destructive half is `commanderRows` / `busy` / `demolish`, imported
 * from `reclaim.ts` rather than restated. Those three are one set on purpose: a
 * caller that checks a different set from the one it deletes can delete something
 * it never checked was quiet, and this project has stranded a real player's fleet
 * that way once. A second implementation here would be exactly that hole, opened
 * again, in a command with no sweep behind it to notice.
 *
 * ── WHAT IS DIFFERENT FROM A RECLAIM ────────────────────────────────────────
 *
 *   1. A CAPTURED COLONY GOES BACK TO THE GALAXY. The ruleset's staged census
 *      determines how many caretaker worlds exist. A colony deleted outright is a world that has
 *      LEFT — one fewer thing for everybody else to fight over for the rest of the
 *      season, and that acceptance query permanently red. So the address is
 *      re-seeded through `createNeutralWorld`, from the same generator the season
 *      was born from: same slot, same tier, same profile seed, same name. An
 *      address the generator never put a neutral at — a Silent Space departure
 *      site — is simply left empty, because inventing one changes the census.
 *   2. THE ACCOUNT ROW GOES, and with it the once-and-for-ever ledger a reclaim
 *      protects. `account_rewards` survives a reclaim because the person is coming
 *      back; it cannot survive the person.
 *
 * ── AND WHAT IT REFUSES, IN WORDS ───────────────────────────────────────────
 *
 * Bots are never erased. The legacy command also refuses news authors, move
 * history and queued returns. An approved request anonymises shared history and
 * cancels queued returns transactionally; all live-world busy guards still apply.
 */
import { and, eq, isNull, or } from 'drizzle-orm';
import { randomUUID } from 'node:crypto';
import {
  MULTI_WORLD,
  SERVERS,
  generateGalaxy,
  neutralOpeningOrder,
  selectNeutralSlots,
  type NeutralTier,
} from '@astera/rules';
import type { Clock } from '../clock.js';
import type { Db, Tx } from '../db/client.js';
import { publishShard } from '../stream/bus.js';
import { normaliseUsername } from '../auth/credentials.js';
import {
  accountDeletionRequests,
  accountRewards,
  accounts,
  announcementReads,
  announcements,
  botProfiles,
  chatArchive,
  chatMediaAssets,
  mediaDeletionQueue,
  dmArchive,
  commanderTransfers,
  feedbackEntries,
  perfSessions,
  paddleSkinOrders,
  polarSkinOrders,
  shopierOrders,
  shopierPurchaseCodes,
  planets,
  players,
  returnApplications,
  seasonResults,
  seasonRewardEntitlements,
  seasons,
} from '../db/schema.js';
import { GameError } from './planet.js';
import { busy, commanderRows, demolish } from './reclaim.js';
import { reconcileClanPlayerReclaim } from './clan.js';
import { createNeutralWorld } from './season.js';

export interface DeleteAccountResult {
  /** The public display name, so the operator can read back who was removed. */
  account: string;
  username: string;
  /** Names of the worlds that stopped existing, capital first. */
  worldsRemoved: string[];
  /** Names of the caretaker worlds handed back to the galaxy. */
  coloniesReturned: string[];
}

/**
 * The caretaker world this address was born as, if it was born as one.
 *
 * Rebuilt from the season's seed rather than remembered, for the same reason the
 * galaxy itself is: a slot is a function of the seed, and storing it would be a
 * second copy to disagree with. The ordinal is counted in selection order so the
 * restored world carries the NAME it originally had — `createNeutralWorlds` numbers
 * them exactly this way, and a world that comes back as `Neutral T3-01` is the one
 * that left.
 */
function originalNeutral(
  seed: number,
  slotIndex: number,
): { neutral: ReturnType<typeof selectNeutralSlots>[number]; number: number } | undefined {
  const selected = neutralOpeningOrder(
    seed,
    selectNeutralSlots(seed, generateGalaxy(seed, MULTI_WORLD.neutralSlotPool).slots),
  );
  const ordinal = new Map<NeutralTier, number>([[1, 0], [2, 0], [3, 0]]);
  for (const neutral of selected) {
    const number = (ordinal.get(neutral.tier) ?? 0) + 1;
    ordinal.set(neutral.tier, number);
    if (neutral.slot.index === slotIndex) return { neutral, number };
  }
  return undefined;
}

/** Everything about the person that is not about a season. */
async function forgetAccount(tx: Tx, accountId: string, requestId: string = randomUUID()): Promise<void> {
  const media = await tx.select({ assetId: chatMediaAssets.id }).from(chatMediaAssets).where(eq(chatMediaAssets.ownerAccountId, accountId));
  if (media.length > 0) await tx.insert(mediaDeletionQueue).values(media.map(asset => ({ ...asset, requestId }))).onConflictDoNothing();
  await tx.delete(accountRewards).where(eq(accountRewards.accountId, accountId));
  await tx.delete(announcementReads).where(eq(announcementReads.accountId, accountId));
  await tx.delete(feedbackEntries).where(eq(feedbackEntries.accountId, accountId));
  await tx.delete(seasonRewardEntitlements)
    .where(eq(seasonRewardEntitlements.accountId, accountId));
  await tx.delete(seasonResults).where(eq(seasonResults.accountId, accountId));
  // Public messages by this account and private conversations involving it are removed.
  await tx.delete(chatArchive).where(eq(chatArchive.authorAccountId, accountId));
  await tx.delete(dmArchive).where(or(
    eq(dmArchive.senderAccountId, accountId), eq(dmArchive.recipientAccountId, accountId),
  ));
  // 0100's recordings reference the account with no cascade: left here, the
  // delete below failed on the key and the person could not be erased at all.
  await tx.delete(perfSessions).where(eq(perfSessions.accountId, accountId));
  // Keep immutable delivery/refund references, without customer details or checkout capabilities.
  await tx.update(paddleSkinOrders).set({ customerId: null }).where(eq(paddleSkinOrders.accountId, accountId));
  await tx.update(polarSkinOrders).set({ checkoutUrl: null }).where(eq(polarSkinOrders.accountId, accountId));
  await tx.update(shopierOrders).set({ note: null, code: null }).where(eq(shopierOrders.accountId, accountId));
  await tx.delete(shopierPurchaseCodes).where(eq(shopierPurchaseCodes.accountId, accountId));
  await tx.delete(accounts).where(eq(accounts.id, accountId));
}

/**
 * Remove one account, its commander and everything either was the reason for.
 *
 * ONE TRANSACTION. A half-deleted person is worse than a deleted one and much
 * worse than a refused one, and every guard below throws rather than returns
 * precisely so the rollback is the failure path.
 */
export async function deleteAccount(
  db: Db,
  clock: Clock,
  name: string,
): Promise<DeleteAccountResult> {
  return db.transaction(async (tx) => {
    /**
     * TWO EXACT MATCHES, AND DELIBERATELY NO `lower()` — the same rule
     * `grantReward` is written against. Case-folding a Turkish name is not
     * reversible: `İ` folds to `i` plus a combining dot, so a commander called
     * `İhsan` would never match `ihsan` and the operator would be told no such
     * person exists while looking at their message. The display name is compared
     * as written; the login is compared through the SAME normaliser that folded it
     * on the way in.
     */
    const [found] = await tx
      .select({
        id: accounts.id,
        username: accounts.username,
        displayName: accounts.displayName,
      })
      .from(accounts)
      .where(eq(accounts.displayName, name))
      .limit(1)
      .union(
        tx
          .select({
            id: accounts.id,
            username: accounts.username,
            displayName: accounts.displayName,
          })
          .from(accounts)
          .where(eq(accounts.username, normaliseUsername(name)))
          .limit(1),
      );
    if (!found) throw new GameError('PLAYER_NOT_FOUND', `No commander named ${name}`, 404);

    return eraseAccount(tx, clock, found, false);
  });
}


/** Only the verified request path may anonymise shared history instead of refusing it. */
export async function deleteRequestedAccount(tx: Tx, clock: Clock, accountId: string, requestId: string): Promise<DeleteAccountResult> {
  const [account] = await tx.select().from(accounts).where(eq(accounts.id, accountId)).for('update');
  const [request] = await tx.select().from(accountDeletionRequests).where(and(eq(accountDeletionRequests.accountId, accountId), eq(accountDeletionRequests.requestId, requestId)));
  if (!account?.deletionApprovedAt || !request?.approvedAt) throw new GameError('DELETION_NOT_APPROVED', 'Deletion has not been approved', 409);
  return eraseAccount(tx, clock, account, true, requestId);
}

async function eraseAccount(tx: Tx, clock: Clock, found: Pick<typeof accounts.$inferSelect, 'id' | 'username' | 'displayName'>, approvedRequest: boolean, requestId?: string): Promise<DeleteAccountResult> {
  const now = clock.now();
  // The row is read again under a lock, so nothing can join, move or be granted
  // anything between the search above and the deletion below.
  const [locked] = await tx
    .select({ id: accounts.id })
    .from(accounts)
    .where(eq(accounts.id, found.id))
    .for('update');
  if (!locked) throw new GameError('PLAYER_NOT_FOUND', `No commander named ${found.displayName}`, 404);

  const [bot] = await tx
    .select({ accountId: botProfiles.accountId })
    .from(botProfiles)
    .where(eq(botProfiles.accountId, found.id));
  if (bot) {
    throw new GameError(
      'BOT_ACCOUNT',
      `${found.displayName} is a commander the server plays. Retire it with 'pnpm bots retire' instead.`,
      409,
    );
  }

  const [authored] = await tx
    .select({ id: announcements.id })
    .from(announcements)
    .where(eq(announcements.authorAccountId, found.id));
  if (authored && !approvedRequest) {
    throw new GameError(
      'ANNOUNCEMENT_AUTHOR',
      `${found.displayName} has authored public news, which outlives its author. Reassign it first.`,
      409,
    );
  }

  /**
   * Silent Space move history is not this command's to take. `main_vacancies`
   * hangs return addresses off `commander_transfers`, and somebody else may be
   * queued for one of them; deleting the history would take an address a
   * different person is waiting on.
   */
  const [moved] = await tx
    .select({ id: commanderTransfers.id })
    .from(commanderTransfers)
    .where(eq(commanderTransfers.accountId, found.id));
  if (moved && !approvedRequest) {
    throw new GameError(
      'TRANSFER_HISTORY',
      `${found.displayName} has Silent Space move history other return addresses hang off. Not deletable here.`,
      409,
    );
  }

  const [player] = await tx
    .select({
      id: players.id,
      seasonId: players.seasonId,
      seed: seasons.seed,
    })
    .from(players)
    .innerJoin(seasons, eq(seasons.id, players.seasonId))
    .where(eq(players.accountId, found.id))
    .for('update', { of: players });

  // An account between galaxies is still a person, and still deletable.
  if (!player) {
    await forgetAccount(tx, found.id, requestId);
    return {
      account: found.displayName,
      username: found.username,
      worldsRemoved: [],
      coloniesReturned: [],
    };
  }

  const [queued] = await tx
    .select({ id: returnApplications.id })
    .from(returnApplications)
    .where(and(
      eq(returnApplications.playerId, player.id),
      eq(returnApplications.status, 'QUEUED'),
    ));
  if (queued && !approvedRequest) {
    throw new GameError(
      'RETURN_QUEUED',
      `${found.displayName} has a queued return application. Close it before deleting the account.`,
      409,
    );
  }

  if (queued) await tx.update(returnApplications).set({ status: 'CANCELLED', closedAt: now, updatedAt: now, closedReason: 'ACCOUNT_DELETION' }).where(eq(returnApplications.id, queued.id));

  /**
   * Read ONCE and used by both the quiet check and the deletion, so what is
   * checked and what is removed can never be different sets. See `commanderRows`.
   */
  const worlds = await tx
    .select({
      id: planets.id,
      name: planets.name,
      kind: planets.kind,
      slotIndex: planets.slotIndex,
    })
    .from(planets)
    .where(eq(planets.controllerPlayerId, player.id))
    .orderBy(planets.slotIndex);
  const planetIds = worlds.map((world) => world.id);
  const rows = await commanderRows(tx, planetIds, player.id);
  if (await busy(tx, planetIds, player.id, rows, now)) {
    throw new GameError(
      'WORLD_BUSY',
      `${found.displayName} still has craft in the air. Let them land and run this again.`,
      409,
    );
  }

  await reconcileClanPlayerReclaim(tx, {
    playerId: player.id,
    seasonId: player.seasonId,
    displayName: found.displayName,
    now,
    activeCutoff: new Date(now.getTime() - SERVERS.idleDays * 24 * 60 * 60_000),
  });
  await demolish(tx, planetIds, player.id, rows);

  /**
   * AND NOW GIVE THE GALAXY BACK WHAT WAS NEVER THIS COMMANDER'S TO REMOVE.
   *
   * After `demolish`, not before: the address is only free once the colony row
   * is gone, and `createNeutralWorld` inserts a new planet at the same slot.
   */
  const coloniesReturned: string[] = [];
  for (const world of worlds) {
    if (world.kind !== 'COLONY') continue;
    const original = originalNeutral(player.seed, world.slotIndex);
    if (!original) continue;
    await createNeutralWorld(tx, player.seasonId, original.neutral, now, original.number);
    coloniesReturned.push(world.name);
  }

  await forgetAccount(tx, found.id, requestId);

  // A public world left, some of them came back, a ladder row went and any
  // authored chat with it. Distinct query families; the client's coalescer turns
  // the transactional broadcasts into one visible refresh.
  await publishShard(tx, player.seasonId, 'world');
  await publishShard(tx, player.seasonId, 'mining');
  await publishShard(tx, player.seasonId, 'chat');
  await publishShard(tx, player.seasonId, 'score');

  return {
    account: found.displayName,
    username: found.username,
    worldsRemoved: worlds.map((world) => world.name),
    coloniesReturned,
  };
}

/** Not exported for anything but the CLI's dry run; nothing routes to this file. */
export async function describeAccount(
  db: Db,
  name: string,
): Promise<{
  account: string;
  username: string;
  createdAt: Date;
  worlds: { name: string; kind: string; slotIndex: number }[];
} | undefined> {
  const [found] = await db
    .select({
      id: accounts.id,
      username: accounts.username,
      displayName: accounts.displayName,
      createdAt: accounts.createdAt,
    })
    .from(accounts)
    .where(eq(accounts.displayName, name))
    .limit(1)
    .union(
      db
        .select({
          id: accounts.id,
          username: accounts.username,
          displayName: accounts.displayName,
          createdAt: accounts.createdAt,
        })
        .from(accounts)
        .where(eq(accounts.username, normaliseUsername(name)))
        .limit(1),
    );
  if (!found) return undefined;
  const worlds = await db
    .select({ name: planets.name, kind: planets.kind, slotIndex: planets.slotIndex })
    .from(planets)
    .innerJoin(players, eq(players.id, planets.controllerPlayerId))
    .where(and(eq(players.accountId, found.id), isNull(planets.recoveryUntil)))
    .orderBy(planets.slotIndex);
  return {
    account: found.displayName,
    username: found.username,
    createdAt: found.createdAt,
    worlds,
  };
}

import { and, asc, eq, sql } from 'drizzle-orm';
import type { Db, Tx } from '../db/client.js';
import type { Clock } from '../clock.js';
import { accountDeletionRequests, accounts, adminActions, mediaDeletionQueue, players, seasons } from '../db/schema.js';
import { verifyPassword } from '../auth/password.js';
import { normaliseUsername } from '../auth/credentials.js';
import { takeSecurityCounter } from './mail.js';
import { GameError } from './planet.js';
import { deleteRequestedAccount } from './accountDeletion.js';
import { writeErasureIntent, type ErasureJournalContext } from './erasureJournal.js';

const receipt = (request: typeof accountDeletionRequests.$inferSelect) => ({
  requestId: request.requestId, requestedAt: request.requestedAt.toISOString(), status: request.approvedAt ? 'approved' as const : 'requested' as const,
});

async function recordRequest(tx: Tx, accountId: string, locale: string, now: Date) {
  const [created] = await tx.insert(accountDeletionRequests).values({ accountId, requestedAt: now, locale }).onConflictDoNothing({ target: accountDeletionRequests.accountId }).returning();
  const [request] = created ? [created] : await tx.select().from(accountDeletionRequests).where(eq(accountDeletionRequests.accountId, accountId));
  if (!request) throw new Error('Deletion request was not recorded');
  return { request, created: !!created };
}

/** Support ownership verification is an explicit operator responsibility, never a public bypass. */
export async function recordSupportDeletionRequest(db: Db, clock: Clock, username: string, locale: string, actorAccountId: string) {
  return db.transaction(async tx => {
    const [account] = await tx.select({ id: accounts.id }).from(accounts).where(eq(accounts.username, normaliseUsername(username))).for('update');
    if (!account) throw new GameError('ACCOUNT_NOT_FOUND', 'Account not found', 404);
    const now = clock.now();
    const result = await recordRequest(tx, account.id, locale, now);
    if (result.created) await tx.insert(adminActions).values({ actorAccountId, targetAccountId: account.id, action: 'ACCOUNT_DELETION_SUPPORT_REQUEST', details: { requestId: result.request.requestId }, createdAt: now });
    return { request: receipt(result.request) };
  });
}

export async function accountDeletionStatus(db: Db, accountId: string) {
  const [request] = await db.select().from(accountDeletionRequests).where(eq(accountDeletionRequests.accountId, accountId));
  return { request: request ? receipt(request) : null };
}

/** Operator queue is bounded and contains no password, email or session credential. */
export async function listAccountDeletionRequests(db: Db) {
  const requests = await db.select({ request: accountDeletionRequests, accountId: accounts.id, username: accounts.username, displayName: accounts.displayName })
    .from(accountDeletionRequests).innerJoin(accounts, eq(accounts.id, accountDeletionRequests.accountId))
    .orderBy(asc(accountDeletionRequests.requestedAt), asc(accountDeletionRequests.requestId)).limit(100);
  const mediaPending = await db.select({ requestId: mediaDeletionQueue.requestId, files: sql<number>`count(*)::int` }).from(mediaDeletionQueue)
    .groupBy(mediaDeletionQueue.requestId).orderBy(sql`min(${mediaDeletionQueue.createdAt})`, asc(mediaDeletionQueue.requestId)).limit(100);
  return { requests: requests.map(row => ({ ...receipt(row.request), accountId: row.accountId, username: row.username, displayName: row.displayName })), mediaPending };
}

/** Approval closes access atomically; it never destroys worlds or accelerates flights. */
export async function approveAccountDeletion(db: Db, clock: Clock, requestId: string, actorAccountId: string, journal: ErasureJournalContext) {
  const [initial] = await db.select().from(accountDeletionRequests).where(eq(accountDeletionRequests.requestId, requestId));
  const missing = () => new GameError('DELETION_REQUEST_NOT_FOUND', 'Deletion request not found', 404);
  if (!initial) throw missing();
  return db.transaction(async tx => {
    const [account] = await tx.select().from(accounts).where(eq(accounts.id, initial.accountId)).for('update');
    const [request] = await tx.select().from(accountDeletionRequests).where(eq(accountDeletionRequests.requestId, requestId)).for('update');
    if (!account || !request) throw missing();
    if (request.approvedAt) {
      await writeErasureIntent(journal, { ...request, approvedAt: request.approvedAt }, clock.now());
      return { request: receipt(request) };
    }
    const now = clock.now();
    await tx.update(accounts).set({ authVersion: account.authVersion + 1, deletionApprovedAt: now }).where(eq(accounts.id, account.id));
    const [approved] = await tx.update(accountDeletionRequests).set({ approvedAt: now }).where(eq(accountDeletionRequests.requestId, requestId)).returning();
    if (!approved) throw new Error('Deletion approval was not recorded');
    await tx.insert(adminActions).values({ actorAccountId, targetAccountId: account.id, action: 'ACCOUNT_DELETION_APPROVED', details: { requestId }, createdAt: now });
    await writeErasureIntent(journal, { ...approved, approvedAt: now }, now);
    return { request: receipt(approved) };
  });
}

/** Manual fulfillment is retryable; shared-flight and lifecycle contention defer it. */
export async function completeAccountDeletion(db: Db, clock: Clock, requestId: string, actorAccountId: string, journal: ErasureJournalContext) {
  const result = { requestId, status: 'completed' as const };
  return db.transaction(async tx => {
    await tx.execute(sql`set local lock_timeout = '250ms'`);
    // Per-request admission also coalesces concurrent completion retries across replicas.
    await tx.execute(sql`select pg_advisory_xact_lock(hashtextextended(${`account-deletion:${requestId}`}, 0))`);
    const [completed] = await tx.select({ id: adminActions.id }).from(adminActions).where(and(eq(adminActions.action, 'ACCOUNT_DELETION_COMPLETED'), sql`${adminActions.details}->>'requestId' = ${requestId}`)).limit(1);
    if (completed) return result;
    const [request] = await tx.select().from(accountDeletionRequests).where(eq(accountDeletionRequests.requestId, requestId));
    if (!request) throw new GameError('DELETION_REQUEST_NOT_FOUND', 'Deletion request not found', 404);
    if (!request.approvedAt) throw new GameError('DELETION_NOT_APPROVED', 'Deletion has not been approved', 409);
    await writeErasureIntent(journal, { ...request, approvedAt: request.approvedAt }, clock.now());
    const [initial] = await tx.select().from(players).where(eq(players.accountId, request.accountId));
    if (initial) await tx.execute(sql`select pg_advisory_xact_lock(hashtextextended(${`placement:${initial.seasonId}`}, 0))`);
    const [lifecycle] = await tx.execute<{ acquired: boolean }>(sql`select pg_try_advisory_xact_lock(83202488) as acquired`);
    if (!lifecycle?.acquired) throw new GameError('DELETION_BUSY', 'The world is changing; retry later', 409);
    // An exclusive season row prevents a new incoming flight crossing the quiet check.
    if (initial) await tx.select({ id: seasons.id }).from(seasons).where(eq(seasons.id, initial.seasonId)).for('update');
    const [account] = await tx.select().from(accounts).where(eq(accounts.id, request.accountId)).for('update');
    const [current] = await tx.select().from(players).where(eq(players.accountId, request.accountId));
    if (!account || initial?.id !== current?.id || initial?.seasonId !== current?.seasonId || initial?.placementVersion !== current?.placementVersion) {
      throw new GameError('DELETION_BUSY', 'The world changed; retry later', 409);
    }
    await deleteRequestedAccount(tx, clock, request.accountId, requestId);
    await tx.insert(adminActions).values({ actorAccountId, action: 'ACCOUNT_DELETION_COMPLETED', details: { requestId }, createdAt: clock.now() });
    return result;
  }).catch((error: unknown) => {
    let current: unknown = error;
    for (let depth = 0; depth < 5 && typeof current === 'object' && current !== null; depth++) {
      if ('code' in current && typeof current.code === 'string' && ['55P03', '40P01', '57014'].includes(current.code)) throw new GameError('DELETION_BUSY', 'The world is busy; retry later', 409);
      current = 'cause' in current ? current.cause : undefined;
    }
    throw error;
  });
}

/** Authenticated identity is authoritative; the request cannot name another account. */
export async function requestAccountDeletion(db: Db, clock: Clock, accountId: string, version: number, password: string, locale: string) {
  const now = clock.now();
  // Shares the existing account-security guessing budget across operations and replicas.
  if (!await takeSecurityCounter(db, `password-check:${accountId}`, 10, 15 * 60_000, now)) {
    throw new GameError('RATE_LIMITED', 'Try later', 429, { seconds: 900 });
  }
  const [snapshot] = await db.select().from(accounts).where(eq(accounts.id, accountId));
  if (snapshot?.authVersion !== version || !await verifyPassword(password, snapshot.passwordHash)) {
    throw new GameError('BAD_CREDENTIALS', 'Credentials do not match', 401);
  }
  return db.transaction(async tx => {
    const [current] = await tx.select().from(accounts).where(eq(accounts.id, accountId)).for('update');
    if (current?.authVersion !== version || current.passwordHash !== snapshot.passwordHash) {
      throw new GameError('UNAUTHENTICATED', 'Sign in again', 401);
    }
    const { request } = await recordRequest(tx, accountId, locale, now);
    return { request: receipt(request) };
  });
}

