export interface AsyncCacheStats {
  entries: number;
  hits: number;
  misses: number;
  bypasses: number;
  invalidations: number;
  evictions: number;
  singleFlightWaits: number;
}

interface Entry<T> {
  token: symbol;
  pending: boolean;
  expiresAt: number;
  promise: Promise<T>;
}

/**
 * A bounded, disposable LRU with one Promise per key.
 *
 * Invalidation may race a cache fill. A pending fill's token is marked so a
 * loader that began before a committed shard event cannot install or return its
 * old snapshot after that event; it joins the post-invalidation fill instead.
 * Only in-flight tokens are retained, so the correctness bookkeeping is bounded
 * too. Eviction and TTL never affect correctness; they only cause more work.
 */
export class AsyncCache<T> {
  private readonly entries = new Map<string, Entry<T>>();
  /** Only fills invalidated while pending; bounded by the entry ceiling. */
  private readonly invalidatedFills = new Set<symbol>();
  private hits = 0;
  private misses = 0;
  private bypasses = 0;
  private invalidations = 0;
  private evictions = 0;
  private singleFlightWaits = 0;

  constructor(
    private readonly maxEntries: number,
    private readonly ttlMs: number,
    private readonly enabled: () => boolean = () => true,
    private readonly now: () => number = Date.now,
  ) {}

  async get(key: string, load: () => Promise<T>): Promise<T> {
    if (!this.enabled()) {
      this.bypasses += 1;
      return load();
    }

    const instant = this.now();
    const existing = this.entries.get(key);
    // A pending fill never expires. Starting a second database projection because
    // the first one has taken longer than the value TTL recreates the exact cache
    // stampede single-flight exists to prevent.
    if (existing && (existing.pending || existing.expiresAt > instant)) {
      this.hits += 1;
      if (existing.pending) this.singleFlightWaits += 1;
      this.touch(key, existing);
      return existing.promise;
    }
    if (existing) this.entries.delete(key);

    this.misses += 1;
    const token = Symbol(key);
    const promise = load()
      .then((value): T | Promise<T> => {
        if (this.invalidatedFills.delete(token)) {
          return this.get(key, load);
        }
        const current = this.entries.get(key);
        if (current?.token === token) {
          current.pending = false;
          current.expiresAt = this.now() + this.ttlMs;
          this.touch(key, current);
        }
        return value;
      })
      .catch((error: unknown) => {
        this.invalidatedFills.delete(token);
        if (this.entries.get(key)?.token === token) this.entries.delete(key);
        throw error;
      });
    const entry: Entry<T> = {
      token,
      pending: true,
      expiresAt: instant + this.ttlMs,
      promise,
    };

    this.entries.set(key, entry);
    this.evictOverflow();
    return entry.promise;
  }

  invalidate(key: string): void {
    const entry = this.entries.get(key);
    if (entry?.pending) this.invalidatedFills.add(entry.token);
    if (this.entries.delete(key)) this.invalidations += 1;
  }

  invalidatePrefix(prefix: string): void {
    for (const key of this.entries.keys()) {
      if (key.startsWith(prefix)) this.invalidate(key);
    }
  }

  clear(): void {
    for (const entry of this.entries.values()) {
      if (entry.pending) this.invalidatedFills.add(entry.token);
    }
    this.invalidations += this.entries.size;
    this.entries.clear();
  }

  status(): AsyncCacheStats {
    return {
      entries: this.entries.size,
      hits: this.hits,
      misses: this.misses,
      bypasses: this.bypasses,
      invalidations: this.invalidations,
      evictions: this.evictions,
      singleFlightWaits: this.singleFlightWaits,
    };
  }

  private touch(key: string, entry: Entry<T>): void {
    this.entries.delete(key);
    this.entries.set(key, entry);
  }

  private evictOverflow(): void {
    while (this.entries.size > this.maxEntries) {
      const oldest = this.entries.keys().next().value;
      if (oldest === undefined) return;
      this.entries.delete(oldest);
      this.evictions += 1;
    }
  }
}

sources.apps/server/src/services/attackProtectio:
import { and, eq, gt, inArray, isNotNull, isNull, lt, lte, ne, or } from 'drizzle-orm';
import {
  STANDARD_PVP_BALANCE,
  type PvpBalance,
  alloyRate,
  canAttack,
  crystalRate,
  deuteriumRate,
  earnsRecoveryShield,
  effectiveAttackProtection,
  extendRecoveryShield,
  fleetEntries,
  HULLS,
  netRecoveryLossHours,
  productionMult,
  resourceValue,
  type AttackProtection,
  type Fleet,
  type RecoveryLedgerEntry,
  type Resources,
} from '@astera/rules';
import type { Queryable, Tx } from '../db/client.js';
import {
  accounts,
  battleReports,
  buildings,
  clanWarContributions,
  clanWarOperations,
  clanSupportBattleResults,
  clanWarParticipantResults,
  missions,
  planets,
  players,
  satellites,
} from '../db/schema.js';
import { GameError, orbitFromRows } from './planet.js';
import { peakCoreLevels } from './player.js';
import { commanderPvpBalance } from './pvpBalance.js';

/**
 * WHO MAY BE ATTACKED, AND WHAT A DEFEAT BUYS. D183 · owner instruction 2026-09-14.
 *
 * ONE FILE FOR BOTH SHIELDS, because to a raider they are one rule. A commander
 * may hold the first-day shield, the recovery shield, or both, and every surface
 * that asks "is this commander reachable" has to get its answer from the same
 * place — `effectiveAttackProtection` in the rules package — or the disc, the
 * launch gate, the bots' target list and the HUD each answer it from whichever
 * column they happened to be written against. That is exactly the failure mode
 * `assertAttackProtections` was extracted out of `mission.ts` and `strategic.ts`
 * to avoid the first time, and adding a second column is when it would recur.
 *
 * WHAT IS PURE AND WHAT IS NOT. The rules package owns the bar, the window and the
 * composition of the two columns; this file owns the four things that need a
 * database — what a commander's works turn out across every world they hold, whether
 * they have a hostile fleet of their own in the air, whether they are a person at
 * all, and the atomic read-check-clear on the player rows.
 */

/**
 * THE STAGED ROLLOUT SWITCH FOR THE RECOVERY SHIELD. `deployment.md` carries the
 * order, and it is the same shape as `PIRATE_SPAWN_INCREASE_ENABLED`.
 *
 * Off means the column is written by the migration and read by nobody: no grant is
 * made and no stored instant protects anybody, so a fleet mid-roll cannot have one
 * instance refusing launches for a shield another instance does not know exists.
 * The first-day shield is untouched either way — it is a separate column and a
 * separate decision.
 */
export const recoveryShieldEnabled = (): boolean =>
  process.env.RECOVERY_SHIELD_ENABLED !== 'false';

/**
 * THE TWO STORED INSTANTS, READ AS ONE, WITH THE SWITCH APPLIED.
 *
 * Every surface that draws or enforces protection comes through here rather than
 * comparing a column to a clock: the disc badge, the season payload's countdown,
 * the launch gate and the bots' target list. One reading, one place for the
 * rollout switch, and no way for two of them to disagree about who is reachable.
 */
export const protectionFrom = (
  newcomerUntil: Date | null,
  recoveryUntil: Date | null,
  now: Date,
): AttackProtection | null => effectiveAttackProtection(
  newcomerUntil?.getTime() ?? null,
  recoveryShieldEnabled() ? recoveryUntil?.getTime() ?? null : null,
  now.getTime(),
);

/**
 * WHAT THE BAND MEASURES, IN THE SENTENCE A REFUSAL CARRIES. D168.
 *
 * It said "total strength" once, and the band has never read strength: it compares
 * the development tier of each commander's most developed world. A commander told
 * the wrong quantity goes and compares fleets, and comes back with "four can hit six
 * but six cannot hit four".
 */
export const TIER_BAND_REFUSAL = {
  TIER_BAND: "That commander's most developed world is more than one tier above yours",
  TIER_BAND_WEAK: "That commander's most developed world is more than one tier below yours",
} as const;

/**
 * THE DEVELOPMENT BAND FOR ONE LAUNCH, ON THE TWO COMMANDERS. D168.
 *
 * One reading for every lane that reaches out at another commander — a raid and a
 * Death Star strike — so the two cannot drift into the asymmetry the owner was
 * shown on 2026-10-01: the strike sat outside the band while its own Core gate is
 * the first level of tier 4, so a tier 4 commander could strike a tier 6 one who
 * was refused a raid back. Raised before anything is spent; the peaks come back
 * for a caller that asks `canAttack` again with a bash count.
 *
 * Unlocked on purpose: see `peakCoreLevels` for why a race with a Core upgrade
 * landing in the same instant does not justify locking another commander's worlds.
 */
export async function assertTierBand(
  tx: Tx,
  attackerPlayerId: string,
  defenderPlayerId: string,
): Promise<{ attackerPeak: number; defenderPeak: number }> {
  const peaks = await peakCoreLevels(tx, [attackerPlayerId, defenderPlayerId]);
  const attackerPeak = peaks.get(attackerPlayerId) ?? 1;
  const defenderPeak = peaks.get(defenderPlayerId) ?? 1;
  const band = canAttack(
    { playerId: attackerPlayerId, peakCoreLevel: attackerPeak },
    { playerId: defenderPlayerId, peakCoreLevel: defenderPeak },
    0,
  );
  if (band.ok) return { attackerPeak, defenderPeak };
  const reason = band.reason ?? 'FORBIDDEN';
  throw new GameError(
    reason,
    reason === 'TIER_BAND' || reason === 'TIER_BAND_WEAK'
      ? TIER_BAND_REFUSAL[reason]
      // A raid aimed at one of the caller's own colonies reaches here as SELF.
      : reason === 'SELF' ? 'You cannot attack your own planet' : 'You cannot attack that commander',
    403,
  );
}

/** The world-level occupation/recovery gate shared by every PvP launch lane. */
export function assertWorldAttackable(
  world: Pick<typeof planets.$inferSelect, 'protectedUntil' | 'recoveryUntil'> & { vacationUntil?: Date | null },
  now: Date,
): void {
  if (world.vacationUntil && world.vacationUntil > now) {
    throw new GameError('TARGET_VACATION', 'That commander is on vacation.', 409);
  }
  if (world.protectedUntil !== null && world.protectedUntil > now) {
    throw new GameError('OCCUPATION_PROTECTED', 'That world is protected', 409, {
      until: world.protectedUntil.toISOString(),
    });
  }
  if (world.recoveryUntil !== null && world.recoveryUntil > now) {
    throw new GameError('WORLD_RECOVERING', 'That world is recovering', 409, {
      until: world.recoveryUntil.toISOString(),
    });
  }
}

/**
 * WHAT THIS COMMANDER'S WORKS TURN OUT IN AN HOUR, ACROSS EVERY WORLD.
 *
 * The denominator of the recovery shield: the lookback is heavy when it costs at
 * least the selected profile's `recoveryLossHours` hours of this.
 *
 * IT REPLACED STORAGE CAPACITY, and the live field is why. Capacity is a ceiling
 * nobody reaches — the median commander holds 24% of theirs — so a floor written
 * against it meant a different fraction of a different quantity for every player,
 * and one caught with an empty store could lose everything they had and clear
 * nothing. Production is what a commander actually has going, it is the unit the
 * whole economy profile is already written in, and it can only be zero for someone
 * holding no world at all.
 *
 * NOMINAL, AND THAT IS DELIBERATE: the Foundry counts because it genuinely makes a
 * world bigger, while disruption and a struck world's fallen Core do not — the bar
 * must not drop because they were just hit, or the second raid of an evening would
 * be easier to earn a shield from than the first.
 */
async function commanderProductionRate(
  db: Queryable,
  playerId: string,
): Promise<Resources> {
  const total: Resources = { alloy: 0, crystal: 0, deuterium: 0 };
  const worlds = await db
    .select({ id: planets.id })
    .from(planets)
    .where(eq(planets.controllerPlayerId, playerId));
  if (worlds.length === 0) return total;

  const worldIds = worlds.map((world) => world.id);
  const [buildingRows, satelliteRows] = await Promise.all([
    db.select().from(buildings).where(inArray(buildings.planetId, worldIds)),
    db.select().from(satellites).where(inArray(satellites.planetId, worldIds)),
  ]);

  const levelsByWorld = new Map<string, Map<string, number>>();
  for (const row of buildingRows) {
    const levels = levelsByWorld.get(row.planetId) ?? new Map<string, number>();
    levels.set(row.type, row.level);
    levelsByWorld.set(row.planetId, levels);
  }
  const satellitesByWorld = new Map<string, typeof satelliteRows>();
  for (const row of satelliteRows) {
    const installed = satellitesByWorld.get(row.planetId) ?? [];
    installed.push(row);
    satellitesByWorld.set(row.planetId, installed);
  }

  for (const world of worlds) {
    const levels = levelsByWorld.get(world.id);
    const level = (type: string): number => levels?.get(type) ?? 0;
    const orbit = orbitFromRows(satellitesByWorld.get(world.id) ?? [], level('CORE'));
    const boost = productionMult(orbit);
    total.alloy += alloyRate(level('REFINERY')) * boost;
    total.crystal += crystalRate(level('EXTRACTOR')) * boost;
    total.deuterium += deuteriumRate(level('DEUTERIUM_PLANT')) * boost;
  }
  return total;
}

/**
 * WHAT A LIST OF DEAD HULLS COST TO BUILD, LESS WHATEVER STOOD BACK UP.
 *
 * Priced off the live catalogue rather than off a stored figure, because that is
 * what a rebuild will actually be charged. `defenceSalvage` is subtracted per
 * resource rather than by value: the two are the same hull table, and taking the
 * difference in hulls first would lose the split the recipes carry.
 *
 * Here rather than in the worker because the lookback prices past reports with it:
 * a defeat read back off the record must cost what the same defeat cost live.
 */
export function permanentFleetCost(lost: Fleet, salvaged: Fleet): Resources {
  const total: Resources = { alloy: 0, crystal: 0, deuterium: 0 };
  const add = (fleet: Fleet, sign: 1 | -1): void => {
    for (const [hull, count] of fleetEntries(fleet)) {
      const spec = HULLS[hull];
      total.alloy += sign * spec.alloy * count;
      total.crystal += sign * spec.crystal * count;
      total.deuterium += sign * spec.deuterium * count;
    }
  };
  add(lost, 1);
  add(salvaged, -1);
  return {
    alloy: Math.max(0, total.alloy),
    crystal: Math.max(0, total.crystal),
    deuterium: Math.max(0, total.deuterium),
  };
}

/**
 * EVERY PVP BATTLE THIS COMMANDER FOUGHT IN THE LOOKBACK, SPLIT BY SIDE.
 * Owner instruction, 2026-09-18.
 *
 * Read off the reports, which already carry both halves: the loot and each side's
 * dead hulls. `(now − lookback, now]` — a battle exactly one lookback old has aged
 * out. The selected profile determines whether this reads six or eight hours.
 *
 * PLAYER TARGETS ONLY. A caretaker world and a pirate raid have no commander on the
 * other side: neither a defeat nor a haul there is the war this rule is about.
 *
 * The battle being settled is not on the record yet — its report is written after
 * the grant — so the caller adds it.
 */
type TimedRecoveryEntry = RecoveryLedgerEntry & { at: number };

async function lookbackLedger(
  db: Queryable,
  playerId: string,
  now: Date,
  lookbackHours: number,
): Promise<{ defeats: TimedRecoveryEntry[]; raids: TimedRecoveryEntry[] }> {
  const since = new Date(now.getTime() - lookbackHours * 3_600_000);
  const [rows, jointRaids, hostShares] = await Promise.all([db
    .select({
      id: battleReports.id,
      at: battleReports.createdAt,
      defenderCount: battleReports.defenderCount,
      clanWarOperationId: battleReports.clanWarOperationId,
      attackerPlayerId: battleReports.attackerPlayerId,
      defenderPlayerId: battleReports.defenderPlayerId,
      loot: battleReports.loot,
      attackerLosses: battleReports.attackerLosses,
      defenderLosses: battleReports.defenderLosses,
      defenceSalvage: battleReports.defenceSalvage,
    })
    .from(battleReports)
    .where(and(
      eq(battleReports.targetKind, 'PLAYER'),
      or(
        eq(battleReports.defenderPlayerId, playerId),
        eq(battleReports.attackerPlayerId, playerId),
      ),
      gt(battleReports.createdAt, since),
      lte(battleReports.createdAt, now),
    )), db
      .select({
        loot: clanWarParticipantResults.loot,
        at: battleReports.createdAt,
        losses: clanWarParticipantResults.losses,
      })
      .from(clanWarParticipantResults)
      .innerJoin(battleReports, eq(battleReports.id, clanWarParticipantResults.reportId))
      .where(and(
        eq(clanWarParticipantResults.playerId, playerId),
        gt(battleReports.createdAt, since),
        lte(battleReports.createdAt, now),
      )),
    /*
      A SUPPORTED LINE'S LOSSES ARE NOT ALL THE HOST'S (Klan Savunma Desteği). The report
      holds the whole line; the host's own part is its result row.
    */
    db
      .select({ reportId: clanSupportBattleResults.reportId, losses: clanSupportBattleResults.losses })
      .from(clanSupportBattleResults)
      .innerJoin(battleReports, eq(battleReports.id, clanSupportBattleResults.reportId))
      .where(and(
        eq(clanSupportBattleResults.playerId, playerId),
        eq(clanSupportBattleResults.role, 'HOST'),
        gt(battleReports.createdAt, since),
        lte(battleReports.createdAt, now),
      )),
  ]);
  const hostLosses = new Map(hostShares.map((row) => [row.reportId, row.losses]));
  const defeats: TimedRecoveryEntry[] = [];
  const raids: TimedRecoveryEntry[] = [];
  for (const row of rows) {
    if (row.defenderPlayerId === playerId && row.attackerPlayerId !== playerId) {
      defeats.push({
        at: row.at.getTime(),
        loot: row.loot,
        fleetLost: permanentFleetCost(
          row.defenderCount > 1 ? hostLosses.get(row.id) ?? row.defenderLosses : row.defenderLosses,
          row.defenceSalvage,
        ),
      });
    } else if (row.clanWarOperationId === null
      && row.attackerPlayerId === playerId && row.defenderPlayerId !== playerId) {
      raids.push({ at: row.at.getTime(), loot: row.loot, fleetLost: permanentFleetCost(row.attackerLosses, {}) });
    }
  }
  for (const row of jointRaids) {
    raids.push({ at: row.at.getTime(), loot: row.loot, fleetLost: permanentFleetCost(row.losses, {}) });
  }
  return { defeats, raids };
}

/**
 * IS THIS COMMANDER IN THE MIDDLE OF ATTACKING SOMEBODY ELSE?
 *
 * The one refusal that is about the DEFENDER's own conduct. Without it, a
 * commander who has committed a raid and taken a counter-punch on the way would
 * collect twelve hours of immunity WHILE their own fleet is still in the air toward
 * a target that cannot answer back — a shield earned by attacking, which inverts
 * what the rule is for.
 *
 * RAID AND DEATH STAR, AT A COMMANDER'S WORLD. A probe, a transfer, a settlement,
 * clan aid, a merchant run and a pirate raid are not the reaching-out this rule is
 * about; a pirate raid is not even in this table. A neutral world has no commander
 * to be unfair to, so a caretaker assault does not count either.
 *
 * A RETURN LEG IS NOT AN ATTACK. It flies under `kind: 'return'`, so the filter
 * names the outbound kinds rather than excluding the inbound one.
 */
async function hasOutboundPvpStrike(
  db: Queryable,
  playerId: string,
): Promise<boolean> {
  const [row] = await db
    .select({ id: missions.id })
    .from(missions)
    .innerJoin(planets, eq(planets.id, missions.targetPlanetId))
    .where(and(
      eq(missions.ownerPlayerId, playerId),
      eq(missions.status, 'in_flight'),
      inArray(missions.kind, ['attack', 'death_star']),
      // A raid that turned (K8) is a fleet coming home, like a return leg.
      isNull(missions.recalledAt),
      ne(planets.kind, 'NEUTRAL'),
      ne(planets.controllerPlayerId, playerId),
    ))
    .limit(1);
  if (row !== undefined) return true;

  /*
    HULLS IN A CLAN'S JOINT POOL ARE AN OUTBOUND STRIKE. Klan Ortak Savaşı.

    A contributed wave is not a `missions` row while it waits in escrow, so
    without this a commander whose ships are already committed to an operation
    could take a beating, collect twelve hours of immunity, and then have their
    fleet arrive at the defender anyway — a shield earned WHILE attacking, which
    is the exact inversion this refusal exists to prevent.

    It also closes the other half: because no shield can be earned here, the
    leader's launch never has to silently spend one a member did not offer.
  */
  const [committed] = await db
    .select({ id: clanWarContributions.id })
    .from(clanWarContributions)
    .innerJoin(
      clanWarOperations,
      eq(clanWarOperations.id, clanWarContributions.operationId),
    )
    .where(and(
      eq(clanWarContributions.playerId, playerId),
      inArray(clanWarContributions.status, ['OUTBOUND', 'STAGED', 'IN_BATTLE']),
      inArray(clanWarOperations.status, ['ASSEMBLING', 'ATTACKING']),
      // A monument is a neutral PvE lane; only a player-targeted joint strike blocks recovery protection.
      eq(clanWarOperations.targetKind, 'PLANET'),
    ))
    .limit(1);
  return committed !== undefined;
}

/**
 * GRANT OR EXTEND THE COMMANDER’S RECOVERY WINDOW AFTER ONE BATTLE. Owner instruction.
 *
 * JUDGED ON THE WHOLE LOOKBACK, NOT ON THIS BATTLE. Owner instruction, 2026-09-18:
 * every PvP defeat in the selected profile's lookback (this one included),
 * less the profit of every raid this commander made on another commander in the same
 * hours — see `netRecoveryLossHours`. Small raids that each stayed under the bar add up.
 *
 * CALLED INSIDE THE BATTLE'S OWN TRANSACTION, with the defender's player row
 * already held `FOR UPDATE` by the settlement that got here (`lockLedgers`). Two
 * battles resolving against one commander in the same instant therefore queue
 * rather than race, and the read-check-write below is atomic against everything
 * that takes that row — see `assertAttackProtections` for the one thing that
 * deliberately does not, and why.
 *
 * THIS BATTLE'S LOSS COMES FROM THE CALLER, not from a second reading of the world.
 * The battle has already debited the stores and cleared the dead hulls, and its
 * report is not written yet. The earlier battles and the PRODUCTION are read here.
 *
 * IT RETURNS THE HOURS AS WELL AS THE WINDOW, so the battle report can record what
 * the decision was made on. The figure cannot be recomputed later: the production
 * rate at the instant of the fight is not stored anywhere else.
 */
export async function grantRecoveryShield(
  tx: Tx,
  input: {
    playerId: string;
    /** The world the battle was fought at; it receives the recovery production bonus. */
    planetId: string;
    lootLost: Resources;
    fleetLost: Resources;
    now: Date;
    balance?: PvpBalance;
  },
): Promise<{
  until: Date | null;
  hours: number;
  /**
   * Existing colony-fault eligibility: four net production hours in six hours.
   * Independent of the easier tier 1–3 shield, so protection cannot add damage.
   * `until` records whether a shield was actually granted (outbound PvP can refuse
   * it). False when the recovery system is disabled, preserving that switch’s scope.
   */
  earned: boolean;
}> {
  if (!recoveryShieldEnabled()) return { until: null, hours: 0, earned: false };
  /*
    NOTHING LOST, NOTHING TO ASK THE DATABASE. This runs on every resolved PvP
    arrival in the galaxy and most of them are REPELLED raids that took nothing;
    reading four tables to divide zero by something is work the worker should not
    do on every mission that lands. A defender who lost nothing just won, and the
    lookback cannot have crossed the bar since their last defeat, or it would have
    been granted there.
  */
  if (resourceValue(input.lootLost) + resourceValue(input.fleetLost) <= 0) {
    return { until: null, hours: 0, earned: false };
  }
  const balance = input.balance ?? await commanderPvpBalance(tx, input.playerId);
  const [production, ledger] = await Promise.all([
    commanderProductionRate(tx, input.playerId),
    lookbackLedger(tx, input.playerId, input.now, balance.recoveryLookbackHours),
  ]);
  const check = {
    balance,
    defeats: [...ledger.defeats, { loot: input.lootLost, fleetLost: input.fleetLost }],
    raids: ledger.raids,
    production,
  };
  const hours = netRecoveryLossHours(check);
  // Colony damage retains the existing heavy-defeat rule. A gentler shield must
  // never turn the same small defeat into a newly broken beginner colony.
  const faultSince = input.now.getTime() - STANDARD_PVP_BALANCE.recoveryLookbackHours * 3_600_000;
  const earned = earnsRecoveryShield({
    defeats: [...ledger.defeats.filter(entry => entry.at > faultSince), { loot: input.lootLost, fleetLost: input.fleetLost }],
    raids: ledger.raids.filter(entry => entry.at > faultSince),
    production,
  });
  if (!earnsRecoveryShield(check)) {
    return { until: null, hours, earned };
  }
  const until = await forceRecoveryShield(tx, {
    playerId: input.playerId,
    planetId: input.planetId,
    now: input.now,
    balance,
  });
  return { until, hours, earned };
}

/**
 * Grant the selected duration; `grantRecoveryShield` owns the loss test.
 * Outbound hostile missions still refuse the grant. Existing windows only extend,
 * and the struck world's production boost follows the resulting stored deadline.
 */
export async function forceRecoveryShield(
  tx: Tx,
  input: {
    playerId: string;
    balance?: PvpBalance;
    /**
     * THE STRUCK WORLD receives the recovery production bonus while the shield
     * stands. Its row is already held by the settlement that got here
     * (`loadLocked`), and its economy has been advanced to `now`, so the boost
     * starts exactly at the battle and nothing before it is paid twice.
     */
    planetId: string;
    now: Date;
  },
): Promise<Date | null> {
  if (!recoveryShieldEnabled()) return null;
  if (await hasOutboundPvpStrike(tx, input.playerId)) return null;
  const balance = input.balance ?? await commanderPvpBalance(tx, input.playerId);

  const [row] = await tx
    .select({ until: players.recoveryShieldUntil })
    .from(players)
    .where(eq(players.id, input.playerId))
    .for('update');
  if (!row) return null;

  // Never shorten a window that already reaches further, and never write a row
  // that is not a change — a no-op update still costs a lock and an SSE flush.
  const until = new Date(extendRecoveryShield(
    row.until?.getTime() ?? null,
    input.now.getTime(),
    balance,
  ));
  /*
    THE STRUCK WORLD'S BONUS LASTS UNTIL THE SHIELD'S END — the end the shield
    actually has, which is the existing one when that already reaches further. Only
    ever moved forward: a second defeat on this world extends its boost, and a
    defeat elsewhere leaves this world's boost at the window its own defeat bought.
  */
  const standing = row.until !== null && row.until.getTime() >= until.getTime()
    ? row.until
    : until;
  await tx.update(planets)
    .set({ recoveryBoostUntil: standing })
    .where(and(
      eq(planets.id, input.planetId),
      eq(planets.controllerPlayerId, input.playerId),
      or(isNull(planets.recoveryBoostUntil), lt(planets.recoveryBoostUntil, standing)),
    ));
  if (standing === row.until) return row.until;
  await tx.update(players)
    .set({ recoveryShieldUntil: until })
    .where(eq(players.id, input.playerId));
  return until;
}

/**
 * BOTH SHIELDS, ON BOTH SIDES OF ONE HOSTILE LAUNCH. D183, extended 2026-09-14.
 *
 * ONE STATEMENT, TWO LANES. A raid and a strike ask the identical question, and a
 * shield that stopped one and not the other would stop nothing worth stopping —
 * the strike is the loudest thing one commander can do to another. Written here
 * rather than twice because two copies of a rule are how the two lanes start
 * disagreeing about who is protected.
 *
 * THE ORDER IS LOAD-BEARING. The TARGET's protection is checked first: accepting
 * the loss of your own window to hit somebody who cannot be hit would spend a
 * position for nothing, and the launch is refused either way. Both refusals are
 * raised before anything is spent, like D168's band, because a refusal that costs
 * something is a punishment for asking a question.
 *
 * SPENT TOGETHER, AND SPENT, NEVER PAUSED. Accepting clears BOTH columns in the
 * one update: a commander who fires has committed to the war, and leaving the
 * other window standing would let somebody keep half a shield by owning two kinds
 * of it. Dropping writes null rather than a past instant, so "has this commander
 * committed" stays a presence rather than a date comparison somebody forgets to
 * make, and the first day can never come back.
 *
 * THE READ IS DELIBERATELY UNLOCKED, AND THE REASON IS A LOCK CYCLE.
 *
 * A launch already holds both PLANET rows by the time it gets here (`lockWorlds`),
 * while battle settlement holds both PLAYER rows before it takes the defender's
 * planet (`lockLedgers`, then `loadLocked`). Taking `FOR UPDATE` on the players
 * here would close the ring: the launch would hold a planet and wait for a player
 * while the settlement held that player and waited for that planet, and Postgres
 * would break the tie by aborting one of them — a 500 on a raid, at exactly the
 * busy moment the lock was added to make safe. So this reads the two rows the same
 * way the first-day shield has always read them, and the atomicity is bought on the
 * other side instead: `forceRecoveryShield` refuses a grant to a commander who has
 * an outbound raid in flight, so "attacking and protected at once" is closed by the
 * grant rather than by the spend.
 *
 * WHAT REMAINS IS ONE NARROW WINDOW, stated rather than glossed: a launch that has
 * read its rows but not yet committed its mission is invisible to a settlement
 * resolving in that instant, so a shield can be granted to a commander whose raid
 * is a few milliseconds from the air. It closes itself — the window is twelve hours,
 * their own next launch clears it, and it costs the galaxy one commander who could
 * not be hit back for one evening. Closing it properly means taking the player
 * locks BEFORE the planet locks in `startAttack`, which is a change to the launch
 * path's lock contract rather than to this rule.
 *
 * A NEUTRAL TARGET IS OUTSIDE IT ENTIRELY. There is no commander to protect and
 * none to charge; settling is not the reaching-out this rule is about.
 */
/** Both stored windows for a set of commanders, read as one live protection each. */
export async function protectionsOf(
  tx: Queryable,
  playerIds: readonly string[],
  now: Date,
): Promise<Map<string, AttackProtection | null>> {
  const rows = await tx
    .select({
      id: players.id,
      newcomer: players.newcomerShieldUntil,
      recovery: players.recoveryShieldUntil,
    })
    .from(players)
    .where(inArray(players.id, [...playerIds]));
  return new Map(rows.map((row) => [
    row.id,
    protectionFrom(row.newcomer, row.recovery, now),
  ]));
}

/** The one sentence a protected target is refused with, wherever it is asked. */
function refuseProtectedTarget(protection: AttackProtection | null): void {
  if (!protection) return;
  throw new GameError(
    'NEWCOMER_SHIELDED',
    protection.kind === 'RECOVERY'
      ? 'That commander is under a recovery shield'
      : 'That commander is still under their first-day shield',
    409,
    { until: new Date(protection.until).toISOString(), protection: protection.kind },
  );
}

/**
 * THE TARGET HALF ALONE, FOR SURFACES THAT ASK WITHOUT COMMITTING.
 *
 * Marking a clan's joint-war target is a statement of intent, not a launch: no
 * fleet moves, no fuel is spent, and the leader's own shield stays exactly where
 * it is until a wave is actually sent. So the question here is only "can this
 * commander be reached at all", and the answer has to be the same sentence the
 * launch gate gives — which is why it shares `refuseProtectedTarget` rather than
 * growing a second opinion about what a shield means.
 */
export async function assertTargetReachable(
  tx: Queryable,
  defenderPlayerId: string,
  now: Date,
): Promise<void> {
  await assertCommanderStaying(tx, defenderPlayerId);
  const protections = await protectionsOf(tx, [defenderPlayerId], now);
  refuseProtectedTarget(protections.get(defenderPlayerId) ?? null);
}

/**
 * A COMMANDER WHOSE DELETION IS APPROVED IS LEAVING. Owner decision, 2026-10-19.
 *
 * The account is erased once nothing is flying toward it, so a new launch at it
 * is the one way somebody could keep it in the game forever. Flights already in
 * the air still land; nothing new departs for this commander.
 */
export async function assertCommanderStaying(tx: Queryable, playerId: string): Promise<void> {
  const [leaving] = await tx.select({ id: players.id }).from(players)
    .innerJoin(accounts, eq(accounts.id, players.accountId))
    .where(and(eq(players.id, playerId), isNotNull(accounts.deletionApprovedAt))).limit(1);
  if (leaving) throw new GameError('TARGET_LEAVING', 'That commander is leaving Astera.', 409);
}

export async function assertAttackProtections(
  tx: Tx,
  input: {
    attackerPlayerId: string;
    defenderPlayerId: string | null;
    now: Date;
    acknowledgeShieldLoss: boolean;
  },
): Promise<void> {
  if (input.defenderPlayerId === null) return;

  const ids = [...new Set([input.attackerPlayerId, input.defenderPlayerId])];
  const onVacation = await tx.select({ id: players.id }).from(players)
    .where(and(inArray(players.id, ids), gt(players.vacationUntil, input.now)));
  if (onVacation.length) throw new GameError(onVacation.some(p => p.id === input.attackerPlayerId) ? 'VACATION_ACTIVE' : 'TARGET_VACATION', 'Vacation mode blocks this launch.', 409);
  await assertCommanderStaying(tx, input.defenderPlayerId);
  const protections = await protectionsOf(tx, ids, input.now);
  const protectionOf = (id: string): AttackProtection | null => protections.get(id) ?? null;

  refuseProtectedTarget(protectionOf(input.defenderPlayerId));

  const mine = protectionOf(input.attackerPlayerId);
  await commitOwnShieldLoss(tx, input, mine);
}

/** Monument defenders stand in space; only the launcher's own protection is relevant. */
export async function assertOwnShieldLoss(
  tx: Tx,
  input: { attackerPlayerId: string; now: Date; acknowledgeShieldLoss: boolean },
): Promise<void> {
  const protections = await protectionsOf(tx, [input.attackerPlayerId], input.now);
  await commitOwnShieldLoss(tx, input, protections.get(input.attackerPlayerId) ?? null);
}

async function commitOwnShieldLoss(
  tx: Tx,
  input: { attackerPlayerId: string; now: Date; acknowledgeShieldLoss: boolean },
  mine: AttackProtection | null,
): Promise<void> {
  if (!mine) return;
  if (!input.acknowledgeShieldLoss) {
    throw new GameError(
      'SHIELD_WOULD_DROP',
      mine.kind === 'RECOVERY'
        ? 'Launching this gives up your own recovery shield'
        : 'Launching this gives up your own first-day shield',
      409,
      { until: new Date(mine.until).toISOString(), protection: mine.kind },
    );
  }
  await tx.update(players)
    .set({ newcomerShieldUntil: null, recoveryShieldUntil: null })
    .where(eq(players.id, input.attackerPlayerId));
  /*
    THE BOOST GOES WITH THE SHIELD. Owner's words: "bu kalkan aktifken". Cut to NOW
    rather than nulled, so the lazy tick still pays every boosted minute up to the
    launch on a world that has not been read since. Only rows with a live boost are
    touched, which is none at all for almost every launch in the galaxy.
  */
  await tx.update(planets)
    .set({ recoveryBoostUntil: input.now })
    .where(and(
      eq(planets.controllerPlayerId, input.attackerPlayerId),
      gt(planets.recoveryBoostUntil, input.now),
    ));
}

