import {
  FAULT,
  HULLS,
  buildingCost,
  buildMinutes,
  buildingMinutes,
  collect,
  hullWorkMinutes,
  instrumentCost,
  instrumentMaxed,
  groundLoad,
  groundSlots,
  HANGAR,
  hangarCapacity,
  hangarLoad,
  hullBulk,
  plantCeiling,
  productionMult,
  prospectorCeiling,
  prospectorRoom,
  satelliteCost,
  satelliteMinutes,
  satelliteSlots,
  seeingUnlocked,
  type BuildingId,
  type FaultKind,
  type HullId,
  type InstrumentId,
  type SatelliteId,
} from '@astera/rules';
import { eq } from 'drizzle-orm';
import { planets } from '../db/schema.js';
import type { Clock } from '../clock.js';
import type { Db, Tx } from '../db/client.js';
import { buildQueueContext, placeBuildOrder } from './buildQueue.js';
import { asTech } from './researchState.js';
import { assertHullProductionAccess } from './hullAccess.js';
import { loadPlanetViewData, buildPlanetResult, type PlanetView } from './planetView.js';
import {
  GameError,
  assertWorldOperational,
  refreshWealth,
  saveResources,
  withPlanetLock,
  type LockedPlanet,
} from './planet.js';

/**
 * Ordinary purchases commit into one of two queues. This file owns the item gates
 * and prices; `buildQueue.ts` owns timing, persistence, cancellation and completion.
 */

/**
 * EVERY MUTATION ANSWERS WITH THE WHOLE WORLD. D53.
 *
 * Each of these used to return a fragment — a level, a hull count, two resource
 * figures — and the client threw it away and refetched `/api/planet` to find out
 * what had actually happened. Two round trips for one tap, in a game whose entire
 * construction model is "instant on payment, no build timers": on a phone that is
 * three to eight hundred milliseconds of a dead button after a decision the design
 * promises agrees with the tap.
 *
 * The view is free here — see `planetView` — and it is authoritative, because it
 * is built inside the same transaction under the same row lock. The fragment stays
 * beside it: it is what the toast and the animation read, and it says what THIS
 * action did, which the whole-world payload cannot.
 */
export interface WithPlanet {
  planet: PlanetView;
}

/** The broken row is a repair decision until its fault is gone, not an upgrade door. */
const BUILDING_FAULT: Partial<Record<BuildingId, FaultKind>> = {
  REFINERY: 'REFINERY_OUTAGE',
  EXTRACTOR: 'EXTRACTOR_OUTAGE',
  DEUTERIUM_PLANT: 'PLANT_OUTAGE',
  VAULT: 'VAULT_LEAK',
  CORE: 'CORE_OUTAGE',
  SHIPYARD: 'SHIPYARD_REVOLT',
};

function assertFaultItemOperational(
  planet: LockedPlanet,
  item: string,
  fault: FaultKind | undefined,
): void {
  if (!fault || !planet.faults.includes(fault)) return;
  throw new GameError(
    'FAULT_ITEM_BROKEN',
    'Repair this item before improving it',
    409,
    { item, fault },
  );
}

export interface CollectResult extends WithPlanet {
  moved: { alloy: number; crystal: number; deuterium: number };
  /** Would not fit; still sitting in the works. */
  blocked: { alloy: number; crystal: number; deuterium: number };
  alloy: number;
  crystal: number;
  deuterium: number;
  bufferAlloy: number;
  bufferCrystal: number;
  bufferDeuterium: number;
}

/**
 * Empty the works into storage. D16.
 *
 * The one manual step in the economy, and the reason to open the game when
 * nothing is in flight. Runs under the planet lock like every other mutation, so
 * a double-tap on a flaky connection cannot collect the same ore twice: the second
 * transaction blocks, re-reads an emptied buffer, and moves nothing.
 *
 * Deliberately NOT an error when there is nothing to collect. A player pressing a
 * button the interface offered them should never be told off; moving zero is a
 * perfectly good answer and the response says so.
 */
export async function collectWorks(
  db: Db,
  planetId: string,
  clock: Clock,
  expectedPlayerId?: string,
): Promise<CollectResult> {
  return withPlanetLock(db, planetId, clock, async (tx, planet) => {
    assertWorldOperational(planet);
    const result = collect(
      {
        alloy: planet.alloy,
        crystal: planet.crystal,
        deuterium: planet.deuterium,
        bufferAlloy: planet.bufferAlloy,
        bufferCrystal: planet.bufferCrystal,
        bufferDeuterium: planet.bufferDeuterium,
        shield: planet.shield,
        lastTickMinutes: planet.nowMinutes,
        disruptedUntilMinutes: 0,
      },
      {
        refineryLevel: planet.buildings.REFINERY,
        extractorLevel: planet.buildings.EXTRACTOR,
        plantLevel: planet.buildings.DEUTERIUM_PLANT,
        vaultLevel: planet.buildings.VAULT,
        aegisLevel: planet.effectiveInstruments.AEGIS ?? 0,
        production: productionMult(planet.orbit),
      },
    );

    await saveResources(tx, planetId, {
      alloy: result.state.alloy,
      crystal: result.state.crystal,
      deuterium: result.state.deuterium,
      bufferAlloy: result.state.bufferAlloy,
      bufferCrystal: result.state.bufferCrystal,
      bufferDeuterium: result.state.bufferDeuterium,
    });

    planet.alloy = result.state.alloy;
    planet.crystal = result.state.crystal;
    planet.deuterium = result.state.deuterium;
    planet.bufferAlloy = result.state.bufferAlloy;
    planet.bufferCrystal = result.state.bufferCrystal;
    planet.bufferDeuterium = result.state.bufferDeuterium;
    // Collected ore does not change what the player OWNS, only which pile it is
    // in — but Wealth is denormalised and the rank floor reads it, so it is
    // refreshed here rather than left to drift.
    await refreshWealth(tx, planet);

    return {
      moved: result.moved,
      blocked: result.blocked,
      alloy: result.state.alloy,
      crystal: result.state.crystal,
      deuterium: result.state.deuterium,
      bufferAlloy: result.state.bufferAlloy,
      bufferCrystal: result.state.bufferCrystal,
      bufferDeuterium: result.state.bufferDeuterium,
      planet: await loadPlanetViewData(tx, planetId, clock),
    };
  }, expectedPlayerId).then(buildPlanetResult);
}

/** Place one building commitment inside an already-held planet transaction. */
/**
 * THE HANGAR HAS ITS OWN CEILING, AND IT IS STILL THE CORE'S. 2026-09-18.
 *
 * IT ASKS NOTHING OF THE COMMAND CORE ANY MORE. Owner decision, 2026-09-22: *"tier atlamadan bir
 * kullanıcı filocu olabilmeli."* A fleet-path commander was forced up the Core ladder — and
 * therefore up the tier band — to buy room they had already paid for in ore. The economy closes
 * the door the gate used to: a Core-4 world cannot hold one late rung's price at once, let alone
 * buy nine and fill them. `hangarCeiling` carries the measurement.
 *
 * The top of the ladder is still a refusal, because there is nothing above it to sell.
 */
function assertHangarRung(level: number): void {
  if (level >= HANGAR.maxLevel) {
    throw new GameError('AT_MAX_LEVEL', 'Your Hangar is at its highest level.', 400, {
      building: 'HANGAR',
    });
  }
}

export async function placeBuildingUpgrade(
  tx: Tx,
  planet: LockedPlanet,
  type: BuildingId,
  intent: { confirmedLevel?: number } = {},
): Promise<number> {
  assertWorldOperational(planet);
  assertFaultItemOperational(planet, type, BUILDING_FAULT[type]);
  const context = await buildQueueContext(tx, planet, 'CONSTRUCTION');
  const level = context.projected.buildings[type];
  if (intent.confirmedLevel !== undefined && intent.confirmedLevel !== level + 1) {
    throw new GameError('UPGRADE_TARGET_CHANGED', 'The upgrade target changed. Review it again.', 409);
  }
  if (type === 'CORE' && level + 1 === 10 && intent.confirmedLevel !== 10) {
    throw new GameError('CORE_TIER_CONFIRMATION_REQUIRED', 'Confirm the level 10 transition first.', 409);
  }

  if (type === 'HANGAR') {
    assertHangarRung(level);
  } else if (type !== 'CORE' && level >= context.projected.buildings.CORE) {
    throw new GameError('CORE_CEILING', 'Command Core must be raised first');
  }
  /**
   * A SECOND CEILING, AND IT IS THE FIRST ONE SAID AGAIN. T5.
   *
   * No building may pass its Command Core; no Deuterium Refinery may pass its
   * research rung. Choosing the shape a player already knows is the whole point —
   * the mechanic teaches nothing new and reads the moment it refuses.
   *
   * Off the PROJECTED rung, so a research order already ahead in this same queue
   * counts. The two other producers have no such gate and take this branch for
   * free; only the plant has a rung to be measured against.
   */
  if (type === 'DEUTERIUM_PLANT') {
    const rung = context.projected.research.get('DEUTERIUM_SYNTHESIS') ?? 0;
    const ceiling = plantCeiling(rung);
    if (level >= ceiling) {
      throw new GameError(
        'RESEARCH_CEILING',
        `Deuterium Synthesis ${String(rung)} allows a Refinery of ${String(ceiling)}.`,
        409,
        { rung, ceiling },
      );
    }
  }

  const cost = buildingCost(type, level);
  await placeBuildOrder(tx, planet, context, {
    kind: 'BUILDING',
    subject: type,
    count: 1,
    cost,
    // `buildingMinutes`, never `profileBuilding().minutes`: the latter is the
    // design reference and knows nothing about what this commander automated. D198.
    minutes: buildingMinutes(type, level + 1, asTech(context.projected.research)),
  });
  // The order has passed every gate and payment. Keep this stamp in that same
  // planet-locked transaction: refused/rolled-back orders never buy protection.
  if (planet.kind === 'COLONY') {
    const until = new Date(Math.max(
      planet.now.getTime() + FAULT.developmentProtectionMinutes * 60_000,
      planet.faultProtectedUntil?.getTime() ?? 0,
    ));
    await tx.update(planets).set({ faultProtectedUntil: until }).where(eq(planets.id, planet.planetId));
    planet.faultProtectedUntil = until;
  }
  return level + 1;
}

export async function upgradeBuilding(
  db: Db,
  planetId: string,
  type: BuildingId,
  clock: Clock,
  expectedPlayerId?: string,
  intent: { confirmedLevel?: number } = {},
): Promise<WithPlanet & { type: BuildingId; level: number; alloy: number; crystal: number }> {
  return withPlanetLock(db, planetId, clock, async (tx, planet) => {
    const level = await placeBuildingUpgrade(tx, planet, type, intent);
    return {
      type,
      level,
      alloy: planet.alloy,
      crystal: planet.crystal,
      planet: await loadPlanetViewData(tx, planetId, clock),
    };
  }, expectedPlayerId).then(buildPlanetResult);
}

/** Place one hull batch inside an already-held planet transaction. */
export async function placeUnitBuild(
  tx: Tx,
  planet: LockedPlanet,
  hull: HullId,
  count: number,
): Promise<void> {
  if (!Number.isInteger(count) || count < 1) {
    throw new GameError('BAD_COUNT', 'Count must be a positive integer');
  }

  assertWorldOperational(planet);
  if (hull === 'PROSPECTOR') {
    assertFaultItemOperational(planet, hull, 'PROSPECTOR_FAULT');
  }
  const context = await buildQueueContext(tx, planet, 'YARD');
  const spec = HULLS[hull];
  const tech = asTech(context.projected.research);
  assertHullProductionAccess(hull, context.projected.buildings.SHIPYARD, tech);
    /**
     * A DRILL IS A CRAFT, AND THE SHIPYARD BUILDS CRAFT. D25.
     *
     * It used to require a DRILL satellite, which was the wrong shape twice over:
     * a drill is not hardware holding station beside a world, and gating a hull on
     * an orbit slot made mining an all-or-nothing detour. `spec.minShipyard` above
     * is the only gate now; the DERRICK in orbit is what makes the craft BETTER.
     */

    /**
     * TWO PROSPECTORS, EVER. `PROSPECTOR.max`.
     *
     * Counted over every `units` row for this planet rather than over
     * `planet.homeFleet`, because a craft that is away mining is still a craft this
     * planet owns — counting only what is home would let a player build three, send
     * them out, and build three more while the first squadron was in the air.
     *
     * Inside the planet row lock, so two simultaneous builds cannot both see room
     * for the last one. This is the same check-then-act shape `assertFreeBay`
     * exists for, and it gets the same treatment.
     */
  if (hull === 'PROSPECTOR') {
    const have = context.projected.units.PROSPECTOR ?? 0;
    /*
      THE CEILING IS THE COMMANDER'S, NOT A CONSTANT. D170: the third rung of
      Prospector Holds buys a third craft, so the refusal has to quote the number
      this commander actually has rather than `PROSPECTOR.max`.
    */
    const ceiling = prospectorCeiling(tech);
    // `prospectorRoom` is the one place the cap arithmetic lives, so this door and
    // the transfer doors in `movement.ts` cannot answer the question differently.
    if (count > prospectorRoom(have, tech)) {
      throw new GameError(
        'PROSPECTOR_CAP',
        have >= ceiling
          ? `You already have ${String(ceiling)} Prospectors. That is the limit.`
          : `You may hold ${String(ceiling)} Prospectors, and you have ${String(have)}.`,
        400,
        // `context` picks the variant client-side, the same way it picks the
        // wording here. i18next reads it off the params like any other value.
        { max: ceiling, have, ...(have >= ceiling ? { context: 'atLimit' } : {}) },
      );
    }
  }

  /**
   * TWO CEILINGS, ONE PER POOL. T4 · T4b, the Hangar restored 2026-09-18.
   *
   * A ship needs a berth in the Hangar, a gun needs ground the Core stands. Neither
   * pool spends the other. Counted over `projected.units`, so what is already in
   * this queue counts — two orders that each fit and together do not must be
   * refused on the second, or the ceiling is a suggestion anybody walks past by
   * tapping twice. Only THIS queue is projected: a Hangar rising in CONSTRUCTION
   * cannot honestly hand room to a hull that may finish first in YARD.
   *
   * Inside the planet row lock, the same check-then-act shape `assertFreeBay` and
   * the Prospector cap already take.
   */
  const needed = hullBulk(hull) * count;
  const capacity = spec.ground
    ? groundSlots(context.projected.buildings.CORE)
    : hangarCapacity(context.projected.buildings.HANGAR);
  const used = spec.ground
    ? groundLoad(context.projected.units)
    : hangarLoad(context.projected.units);
  if (used + needed > capacity) {
    throw new GameError(
      spec.ground ? 'GROUND_SLOTS_FULL' : 'HANGAR_FULL',
      spec.ground
        ? `This world stands ${String(capacity)} of ground defence and holds ${String(used)}.`
        : `Your Hangar holds ${String(capacity)} and is carrying ${String(used)}.`,
      409,
      { capacity, used, needed },
    );
  }

  const cost = {
    alloy: spec.alloy * count,
    crystal: spec.crystal * count,
    deuterium: spec.deuterium * count,
  };
  await placeBuildOrder(tx, planet, context, {
    kind: 'HULL',
    subject: hull,
    count,
    cost,
    minutes: hullWorkMinutes(hull, count, context.projected.buildings.SHIPYARD, tech),
  });
}

export async function buildUnits(
  db: Db,
  planetId: string,
  hull: HullId,
  count: number,
  clock: Clock,
  expectedPlayerId?: string,
): Promise<WithPlanet & { hull: HullId; built: number; alloy: number; crystal: number }> {
  return withPlanetLock(db, planetId, clock, async (tx, planet) => {
    await placeUnitBuild(tx, planet, hull, count);
    return {
      hull,
      built: count,
      alloy: planet.alloy,
      crystal: planet.crystal,
      planet: await loadPlanetViewData(tx, planetId, clock),
    };
  }, expectedPlayerId).then(buildPlanetResult);
}

/**
 * RAISE A GROUND INSTRUMENT. D25.
 *
 * The four instruments — Telescope, Radar, Aegis, Veil — sit on the planet, carry
 * real levels, and take no orbit slot. Any of them, in any order: price is what
 * makes choosing between them cost something, and the Command Core is the ceiling
 * every structure on the planet obeys.
 *
 * THE UPLINK GATES THE TWO SEEING INSTRUMENTS. It is the one place a satellite is
 * allowed to gate anything, and it is what makes a planet's first orbit slot a real
 * decision: eyes, or production, or faster drills.
 */
export async function raiseInstrument(
  db: Db,
  planetId: string,
  type: InstrumentId,
  clock: Clock,
  expectedPlayerId?: string,
): Promise<WithPlanet & { type: InstrumentId; level: number }> {
  return withPlanetLock(db, planetId, clock, async (tx, planet) => {
    assertWorldOperational(planet);
    if (type === 'TELESCOPE') {
      assertFaultItemOperational(planet, type, 'TELESCOPE_FAULT');
    }
    const context = await buildQueueContext(tx, planet, 'CONSTRUCTION');
    const level = context.projected.instruments[type] ?? 0;

    if (NEEDS_UPLINK.has(type) && !seeingUnlocked(context.projected.effectiveOrbit)) {
      throw new GameError('NEEDS_UPLINK', 'Put an Uplink in orbit first', 403);
    }
    if (level >= context.projected.buildings.CORE) {
      throw new GameError('CORE_CEILING', 'Command Core must be raised first');
    }

    /**
     * NOTHING LEFT TO SELL. D36.
     *
     * A Radar past L8 and a Telescope past L8 have exhausted their own tables — the
     * warning is at its longest, the range is already everywhere, the origin is
     * already named. Before this the purchase went through, at an exponential
     * price, and changed nothing whatsoever. That is not a balance question; it is
     * the game taking money for a product it does not have.
     */
    if (instrumentMaxed(type, level)) {
      throw new GameError(
        'AT_MAX_LEVEL',
        `Your ${type === 'TELESCOPE' ? 'Telescope' : 'Radar'} is at its highest level. There is nothing further to gain.`,
        400,
        // The instrument is named by ID, not by its English label: the client has
        // its own name for it and would otherwise print "Telescope" in Turkish.
        { instrument: type },
      );
    }

    const cost = instrumentCost(type, level);
    await placeBuildOrder(tx, planet, context, {
      kind: 'INSTRUMENT',
      subject: type,
      count: 1,
      cost,
      minutes: buildMinutes(
        cost, context.projected.buildings.CORE, asTech(context.projected.research),
      ),
    });

    return { type, level: level + 1, planet: await loadPlanetViewData(tx, planetId, clock) };
  }, expectedPlayerId).then(buildPlanetResult);
}

/** The two that hang off the Uplink. The Aegis and the Veil stand on their own. */
const NEEDS_UPLINK = new Set<InstrumentId>(['TELESCOPE', 'RADAR']);

/**
 * PUT A SATELLITE IN ORBIT. D25.
 *
 * Bought once, never raised, and it takes one of the slots the Command Core opens
 * at levels 1, 9, 15 and 18. Four satellites and four slots is not a checklist,
 * because the fourth slot is a Core 18 planet — for the part of a season anybody
 * actually plays, a world runs one, two or three of them, and which ones is who it
 * is.
 *
 * THE REFUSAL IS THE DESIGN. `NO_FREE_SLOT` is the moment the choice becomes real,
 * so it says what would fix it rather than merely saying no.
 */
export async function installSatellite(
  db: Db,
  planetId: string,
  type: SatelliteId,
  clock: Clock,
  expectedPlayerId?: string,
): Promise<WithPlanet & { type: SatelliteId; slot: number }> {
  return withPlanetLock(db, planetId, clock, async (tx, planet) => {
    assertWorldOperational(planet);
    const context = await buildQueueContext(tx, planet, 'CONSTRUCTION');
    if (context.projected.orbit.includes(type)) {
      throw new GameError('ALREADY_IN_ORBIT', 'That satellite is already in orbit', 409);
    }
    if (
      context.projected.orbit.length
      >= satelliteSlots(context.projected.buildings.CORE)
    ) {
      throw new GameError('NO_FREE_SLOT', 'Raise the Command Core for another orbit slot');
    }

    const cost = satelliteCost(type);
    const slot = context.projected.orbit.length;
    await placeBuildOrder(tx, planet, context, {
      kind: 'SATELLITE',
      subject: type,
      count: 1,
      cost,
      // The satellite quote: the Uplink's fixed five minutes or the price-based clock. D209.
      minutes: satelliteMinutes(
        type, context.projected.buildings.CORE, asTech(context.projected.research),
      ),
    });
    return { type, slot, planet: await loadPlanetViewData(tx, planetId, clock) };
  }, expectedPlayerId).then(buildPlanetResult);
}

