import { chatVisibleTo } from './communityBlocks.js';
import { randomUUID } from 'node:crypto';
import { claimChatMedia } from './chatMedia.js';
import type { ChatMedia } from '@astera/rules';
import { and, count, desc, eq, gt, isNull, lt, ne, or, sql } from 'drizzle-orm';
import { CHAT, type ChatLanguage } from '@astera/rules';
import type { Clock } from '../clock.js';
import type { Db } from '../db/client.js';
import { accounts, chatMessages, chatReadMarkers, clanMemberships, clans, planets, players } from '../db/schema.js';
import { GameError } from './planet.js';
import { locationIsKnown, type LocationSight } from './locationSight.js';
import { publishShard } from '../stream/bus.js';
import { assertChatAllowed, assertCleanMessage } from './chatModeration.js';
import { messageDecorations, authorRecognition, type PodiumPlace, type ReactionView, type ReplyPreview } from './messageDecorations.js';

export interface ChatMessageView {
  id: string;
  authorPlayerId: string;
  planetId?: string;
  username: string;
  clanTag: string | null;
  content: string;
  media?: ChatMedia | null;
  language: ChatLanguage;
  createdAt: Date;
  self: boolean;
  replyTo: ReplyPreview | null;
  reactions: ReactionView[];
  previousSeasonRank?: PodiumPlace;
  previousSeasonRanking?: 'HONOR' | 'DOMINION';
  supporter?: boolean;
  /**
   * THE AUTHOR SPEAKS WITH ADMIN AUTHORITY. Owner instruction.
   *
   * `admin.ts` keeps this off the wire everywhere else on purpose — a visible flag
   * "would merely advertise the hidden identity", so the galaxy omits an admin's
   * worlds rather than labelling them. Chat is the one surface where the argument
   * does not apply: the author is speaking publicly under their own name, and this
   * payload already carries their `planetId`, so nothing about their world becomes
   * knowable that was not already. What the flag adds is who is answerable.
   *
   * Resolved at the RESPONSE BOUNDARY from the configured usernames, never stored
   * on a player or a planet, so it still cannot be granted by an API call.
   */
  admin: boolean;
}

async function chatPlayer(db: Db, accountId: string) {
  const [row] = await db
    .select({
      player: players, planetId: planets.id,
      username: accounts.displayName, login: accounts.username,
      clanTag: clans.tag,
    })
    .from(players)
    .innerJoin(accounts, eq(players.accountId, accounts.id))
    .innerJoin(planets, and(eq(planets.controllerPlayerId, players.id), eq(planets.kind, 'CAPITAL')))
    .leftJoin(clanMemberships, and(
      eq(clanMemberships.playerId, players.id), isNull(clanMemberships.leftAt),
    ))
    .leftJoin(clans, and(eq(clans.id, clanMemberships.clanId), isNull(clans.disbandedAt)))
    .where(eq(players.accountId, accountId))
    .limit(1);
  if (!row) throw new GameError('NO_PLANET', 'Join a galaxy first', 404);
  return row;
}

/** Newest page on the wire, chronological inside the page for direct rendering. */
export async function readChat(
  db: Db,
  accountId: string,
  limit: number,
  sight: LocationSight,
  language: ChatLanguage = 'tr',
  before?: string,
  /** Configured admin logins, resolved at the boundary. Empty marks nobody. */
  adminUsernames: ReadonlySet<string> = new Set(),
): Promise<{ messages: ChatMessageView[]; nextBefore: string | null }> {
  const me = await chatPlayer(db, accountId);
  let cursor: { createdAt: Date; id: string } | undefined;
  if (before !== undefined) {
    const [found] = await db
      .select({ createdAt: chatMessages.createdAt, id: chatMessages.id })
      .from(chatMessages)
      .where(and(
        eq(chatMessages.id, before),
        eq(chatMessages.seasonId, me.player.seasonId),
        eq(chatMessages.language, language),
      ))
      .limit(1);
    if (!found) throw new GameError('BAD_CHAT_CURSOR', 'That chat cursor is not visible', 400);
    cursor = found;
  }

  const rows = await db
    .select({
      id: chatMessages.id,
      authorPlayerId: chatMessages.authorPlayerId,
      planetId: planets.id,
      x: planets.x,
      y: planets.y,
      z: planets.z,
      username: accounts.displayName,
      clanTag: clans.tag,
      login: accounts.username,
      content: chatMessages.content, media: chatMessages.media,
      replyToMessageId: chatMessages.replyToMessageId,
      language: chatMessages.language,
      createdAt: chatMessages.createdAt,
    })
    .from(chatMessages)
    .innerJoin(players, eq(chatMessages.authorPlayerId, players.id))
    .innerJoin(accounts, eq(players.accountId, accounts.id))
    .innerJoin(planets, and(eq(planets.controllerPlayerId, players.id), eq(planets.kind, 'CAPITAL')))
    .leftJoin(clanMemberships, and(
      eq(clanMemberships.playerId, players.id), isNull(clanMemberships.leftAt),
    ))
    .leftJoin(clans, and(eq(clans.id, clanMemberships.clanId), isNull(clans.disbandedAt)))
    .where(and(
      eq(chatMessages.seasonId, me.player.seasonId),
      chatVisibleTo(accountId, chatMessages.authorPlayerId),
      eq(chatMessages.language, language),
      cursor
        ? or(
            lt(chatMessages.createdAt, cursor.createdAt),
            and(eq(chatMessages.createdAt, cursor.createdAt), lt(chatMessages.id, cursor.id)),
          )
        : undefined,
    ))
    .orderBy(desc(chatMessages.createdAt), desc(chatMessages.id))
    .limit(limit + 1);

  const page = rows.slice(0, limit);
  const nextBefore = rows.length > limit ? (page.at(-1)?.id ?? null) : null;
  const decorations = await messageDecorations(db, 'general', page, me.player.id);
  return {
    messages: page.reverse().map((row) => {
      const self = row.authorPlayerId === me.player.id;
      const { x, y, z, planetId, login, replyToMessageId: _replyToMessageId, ...message } = row;
      const canLocate = (self || !adminUsernames.has(login)) && locationIsKnown(planetId, { x, y, z }, self, sight);
      return {
        ...message,
        ...(canLocate ? { planetId } : {}),
        self,
        admin: adminUsernames.has(login),
        ...(decorations.get(row.id) ?? { replyTo: null, reactions: [] }),
      };
    }),
    nextBefore,
  };
}

/**
 * Five committed messages in a rolling ten-second window.
 *
 * The season lock also makes `createdAt` strictly monotonic inside one chat. The
 * durable read marker is an instant, so allowing two authors to share that instant
 * would make marking one visible message accidentally mark its timestamp twin.
 */
export async function postChat(
  db: Db,
  accountId: string,
  content: string,
  clock: Clock,
  language: ChatLanguage = 'tr',
  /** Same boundary resolution as `readChat`, so the sender sees their own mark. */
  adminUsernames: ReadonlySet<string> = new Set(),
  replyToMessageId?: string,
  mediaInput?: ChatMedia,
): Promise<ChatMessageView> {
  assertCleanMessage(content);
  const me = await chatPlayer(db, accountId);
  const requestedAt = clock.now();
  return db.transaction(async (tx) => {
    await tx.execute(sql`select pg_advisory_xact_lock(hashtext(${`chat:${me.player.seasonId}`}))`);
    await assertChatAllowed(tx, accountId, 'general', clock);
    const [replyTo] = replyToMessageId ? await tx.select({
      id: chatMessages.id, content: chatMessages.content, media: chatMessages.media, username: accounts.displayName,
    }).from(chatMessages)
      .innerJoin(players, eq(players.id, chatMessages.authorPlayerId))
      .innerJoin(accounts, eq(accounts.id, players.accountId))
      .where(and(eq(chatMessages.id, replyToMessageId), eq(chatMessages.seasonId, me.player.seasonId),
        chatVisibleTo(accountId, chatMessages.authorPlayerId),
        eq(chatMessages.language, language))).limit(1) : [];
    if (replyToMessageId && !replyTo) throw new GameError('CHAT_MESSAGE_NOT_VISIBLE', 'That message is not visible', 404);
    const [latest] = await tx
      .select({ createdAt: chatMessages.createdAt })
      .from(chatMessages)
      .where(eq(chatMessages.seasonId, me.player.seasonId))
      .orderBy(desc(chatMessages.createdAt), desc(chatMessages.id))
      .limit(1);
    const createdAt = latest && latest.createdAt >= requestedAt
      ? new Date(latest.createdAt.getTime() + 1)
      : requestedAt;
    const cutoff = new Date(requestedAt.getTime() - CHAT.windowSeconds * 1_000);
    const [rate] = await tx
      .select({ value: count() })
      .from(chatMessages)
      .where(and(
        eq(chatMessages.authorPlayerId, me.player.id),
        gt(chatMessages.createdAt, cutoff),
      ));
    if ((rate?.value ?? 0) >= CHAT.burst) {
      throw new GameError('CHAT_RATE_LIMIT', 'Send at most five messages every ten seconds', 429, {
        seconds: CHAT.windowSeconds,
      });
    }

    const messageId = randomUUID();
    const media = await claimChatMedia(tx, accountId, mediaInput, adminUsernames, requestedAt, 'general', messageId);
    const [message] = await tx
      .insert(chatMessages)
      .values({
        id: messageId, media,
        seasonId: me.player.seasonId,
        authorPlayerId: me.player.id,
        language,
        content,
        replyToMessageId: replyToMessageId ?? null,
        createdAt,
      })
      .returning({
        id: chatMessages.id,
        authorPlayerId: chatMessages.authorPlayerId,
        language: chatMessages.language,
        content: chatMessages.content, media: chatMessages.media,
        createdAt: chatMessages.createdAt,
      });
    if (!message) throw new Error('chat insert returned no row');

    await publishShard(tx, me.player.seasonId, 'chat');
    const recognition = (await authorRecognition(tx, [me.player.id])).get(me.player.id);
    return {
      ...message, planetId: me.planetId, username: me.username, clanTag: me.clanTag, self: true,
      admin: adminUsernames.has(me.login),
      replyTo: replyTo ?? null, reactions: [],
      ...recognition,
    };
  });
}

export async function unreadChat(db: Db, accountId: string, language: ChatLanguage = 'tr'): Promise<number> {
  const me = await chatPlayer(db, accountId);
  const [marker] = await db
    .select({ readAt: chatReadMarkers.readAt })
    .from(chatReadMarkers)
    .where(and(eq(chatReadMarkers.playerId, me.player.id), eq(chatReadMarkers.language, language)))
    .limit(1);
  const [row] = await db
    .select({ value: count() })
    .from(chatMessages)
    .where(and(
      eq(chatMessages.seasonId, me.player.seasonId),
      chatVisibleTo(accountId, chatMessages.authorPlayerId),
      eq(chatMessages.language, language),
      ne(chatMessages.authorPlayerId, me.player.id),
      marker?.readAt ? gt(chatMessages.createdAt, marker.readAt) : undefined,
    ));
  return row?.value ?? 0;
}

export async function markChatRead(
  db: Db,
  accountId: string,
  messageId: string,
  language: ChatLanguage = 'tr',
): Promise<Date> {
  const me = await chatPlayer(db, accountId);
  return db.transaction(async (tx) => {
    const [message] = await tx
      .select({ createdAt: chatMessages.createdAt })
      .from(chatMessages)
      .where(and(
        eq(chatMessages.id, messageId),
        eq(chatMessages.seasonId, me.player.seasonId),
        chatVisibleTo(accountId, chatMessages.authorPlayerId),
        eq(chatMessages.language, language),
      ))
      .limit(1);
    if (!message) throw new GameError('CHAT_MESSAGE_NOT_VISIBLE', 'That message is not visible', 404);

    const [lockedPlayer] = await tx
      .select({ id: players.id })
      .from(players)
      .where(eq(players.id, me.player.id))
      .for('update');
    if (!lockedPlayer) throw new GameError('NO_PLANET', 'Join a galaxy first', 404);
    const [locked] = await tx
      .select({ readAt: chatReadMarkers.readAt })
      .from(chatReadMarkers)
      .where(and(
        eq(chatReadMarkers.playerId, me.player.id),
        eq(chatReadMarkers.language, language),
      ))
      .limit(1);
    const readAt = locked?.readAt && locked.readAt > message.createdAt
      ? locked.readAt
      : message.createdAt;
    await tx.insert(chatReadMarkers).values({ playerId: me.player.id, language, readAt })
      .onConflictDoUpdate({
        target: [chatReadMarkers.playerId, chatReadMarkers.language],
        set: { readAt },
      });
    return readAt;
  });
}

