import { randomUUID } from 'node:crypto';
import { mkdir, readdir, stat, unlink, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { and, eq, inArray, isNull, lt } from 'drizzle-orm';
import { fileTypeFromBuffer } from 'file-type';
import { z } from 'zod';
import { CHAT, CHAT_MEDIA, type ChatMedia } from '@astera/rules';
import type { Db, Tx } from '../db/client.js';
import { chatMediaAssets } from '../db/schema.js';
import { isAdminAccount } from './admin.js';
import type { MessageChannel } from './messageDecorations.js';
import { GameError } from './planet.js';

export const chatMediaSchema = z.discriminatedUnion('kind', [
  z.object({ kind: z.literal('youtube'), videoId: z.string().regex(/^[A-Za-z0-9_-]{11}$/) }).strict(),
  z.object({ kind: z.literal('image'), assetId: z.string().uuid(), mimeType: z.string().max(60) }).strict(),
  z.object({ kind: z.literal('video'), assetId: z.string().uuid(), mimeType: z.string().max(60) }).strict(),
]);
export const chatMessageBody = z.object({
  content: z.string().trim().refine(value => Array.from(value).length <= CHAT.maxChars),
  replyToMessageId: z.string().uuid().optional(),
  media: chatMediaSchema.optional(),
}).strict().refine(value => value.content.length > 0 || value.media !== undefined, 'Write a message or attach media');

export async function claimChatMedia(
  tx: Tx, accountId: string, input: ChatMedia | undefined, adminUsernames: ReadonlySet<string>,
  now: Date, channel: MessageChannel, messageId: string,
): Promise<ChatMedia | null> {
  if (!input) return null;
  if (!await isAdminAccount(tx, accountId, adminUsernames)) throw new GameError('ADMIN_REQUIRED', 'Administrator access required', 403);
  if (input.kind === 'youtube') return chatMediaSchema.parse(input);
  const [asset] = await tx.select().from(chatMediaAssets)
    .where(and(eq(chatMediaAssets.id, input.assetId), eq(chatMediaAssets.ownerAccountId, accountId))).for('update').limit(1);
  if (!asset) throw new GameError('CHAT_MEDIA_NOT_FOUND', 'Choose the file again', 404);
  if (asset.claimedAt) throw new GameError('CHAT_MEDIA_USED', 'This upload was already sent; choose the file again', 409);
  if (asset.createdAt.getTime() + CHAT_MEDIA.uploadLifetimeMs <= now.getTime()) {
    throw new GameError('CHAT_MEDIA_NOT_FOUND', 'Upload expired; choose the file again', 404);
  }
  if (asset.kind !== input.kind) throw new GameError('BAD_CHAT_MEDIA', 'Choose a supported file', 400);
  await tx.update(chatMediaAssets).set({ claimedAt: now, channel, messageId }).where(eq(chatMediaAssets.id, asset.id));
  return { kind: asset.kind, assetId: asset.id, mimeType: asset.mimeType };
}

export async function saveChatUpload(db: Db, accountId: string, bytes: Buffer, declaredType: string, directory: string, now: Date) {
  if (bytes.length === 0) throw new GameError('BAD_CHAT_MEDIA', 'Choose a supported file', 400);
  const limit = declaredType.startsWith('image/') ? CHAT_MEDIA.imageMaxBytes : CHAT_MEDIA.videoMaxBytes;
  if (bytes.length > limit) throw new GameError('CHAT_MEDIA_TOO_LARGE', 'Choose a smaller file', 413);
  let detected;
  try { detected = await fileTypeFromBuffer(bytes.subarray(0, 8192)); } catch { detected = undefined; }
  if (!detected || !CHAT_MEDIA.mimeTypes.some(type => type === detected.mime) || detected.mime !== declaredType) {
    throw new GameError('BAD_CHAT_MEDIA', 'Choose a JPEG, PNG, WebP, GIF, MP4 or WebM file', 400);
  }
  await mkdir(directory, { recursive: true });
  const id = randomUUID();
  const kind = detected.mime.startsWith('image/') ? 'image' as const : 'video' as const;
  await writeFile(join(directory, id), bytes, { flag: 'wx', mode: 0o600 });
  try {
    await db.insert(chatMediaAssets).values({ id, ownerAccountId: accountId, kind, mimeType: detected.mime, byteSize: bytes.length, createdAt: now });
  } catch (error) { await unlink(join(directory, id)); throw error; }
  return { media: { kind, assetId: id, mimeType: detected.mime } };
}

/** Pending claims are row-locked against sending; claimed files never expire. */
export async function cleanupChatUploads(db: Db, directory: string, now: Date): Promise<void> {
  const cutoff = new Date(now.getTime() - CHAT_MEDIA.uploadLifetimeMs);
  await db.transaction(async tx => {
    const expired = await tx.select({ id: chatMediaAssets.id }).from(chatMediaAssets)
      .where(and(isNull(chatMediaAssets.claimedAt), lt(chatMediaAssets.createdAt, cutoff))).limit(256).for('update');
    for (const asset of expired) {
      await unlink(join(directory, asset.id)).catch((error: unknown) => { if (!(error instanceof Error && 'code' in error && error.code === 'ENOENT')) throw error; });
    }
    if (expired.length > 0) await tx.delete(chatMediaAssets).where(inArray(chatMediaAssets.id, expired.map(asset => asset.id)));
  });
  // Retained files are resolved in bounded batches, without one database read per file.
  const files = await readdir(directory).catch(() => []);
  const idSchema = z.string().uuid();
  const candidates = files.filter(id => idSchema.safeParse(id).success);
  for (let offset = 0; offset < candidates.length; offset += 256) {
    const batch = candidates.slice(offset, offset + 256);
    const existing = await db.select({ id: chatMediaAssets.id }).from(chatMediaAssets).where(inArray(chatMediaAssets.id, batch));
    const retained = new Set(existing.map(asset => asset.id));
    for (const id of batch) {
      if (retained.has(id)) continue;
      const info = await stat(join(directory, id)).catch(() => null);
      if (!info || info.mtimeMs >= cutoff.getTime()) continue;
      await unlink(join(directory, id)).catch((error: unknown) => {
        if (!(error instanceof Error && 'code' in error && error.code === 'ENOENT')) throw error;
      });
    }
  }
}

import { and, desc, eq, gt, inArray, isNull, or, sql } from 'drizzle-orm';
import { findProfanity, type ChatLanguage } from '@astera/rules';
import type { Clock } from '../clock.js';
import type { Db, Tx } from '../db/client.js';
import { accounts, adminActions, chatMessages, chatMutes, clanMessages, clans, players, seasons } from '../db/schema.js';
import { publishPrivate, publishShard } from '../stream/bus.js';
import { activeClanPlayerIds } from './clanCombat.js';
import { GameError } from './planet.js';

export type ModeratedChannel = 'general' | 'clan' | 'dm';
export const MUTE_MINUTES = { '5m': 5, '15m': 15, '1h': 60, '4h': 240, '1d': 1440 } as const;
export type MuteDuration = keyof typeof MUTE_MINUTES | 'permanent' | 'remove';

/** Every channel refuses the same words; the player sees which one and keeps the draft. */
export function assertCleanMessage(content: string): void {
  const word = findProfanity(content);
  if (word) throw new GameError('MESSAGE_NOT_ALLOWED', 'This message breaks the community rules', 400, { word });
}

/** Shared by senders and exclusive for mute changes, across API replicas. */
export async function assertChatAllowed(tx: Tx, accountId: string, channel: ModeratedChannel, clock: Clock): Promise<void> {
  await assertCommunityPolicyAccepted(tx, accountId);
  await tx.execute(sql`select pg_advisory_xact_lock_shared(hashtextextended(${`chat-moderation:${accountId}`}, 0))`);
  const now = clock.now();
  const [mute] = await tx.select({ expiresAt: chatMutes.expiresAt }).from(chatMutes).where(and(
    eq(chatMutes.accountId, accountId), eq(chatMutes.channel, channel),
    or(isNull(chatMutes.expiresAt), gt(chatMutes.expiresAt, now)),
  )).limit(1);
  if (mute) throw new GameError('CHAT_MUTED', 'You are muted in this chat channel', 403, {
    channel, expiresAt: mute.expiresAt?.toISOString() ?? 'permanent',
  });
}

async function targetAccount(tx: Tx, username: string) {
  const [account] = await tx.select({ id: accounts.id, username: accounts.username }).from(accounts)
    .where(eq(accounts.username, username.toLowerCase())).limit(1);
  if (!account) throw new GameError('ACCOUNT_NOT_FOUND', 'Account not found', 404);
  return account;
}

export async function setChatMute(db: Db, actorAccountId: string, input: {
  username: string; channels: ModeratedChannel[]; duration: MuteDuration;
}, clock: Clock) {
  return db.transaction(async tx => {
    const target = await targetAccount(tx, input.username);
    await tx.execute(sql`select pg_advisory_xact_lock(hashtextextended(${`chat-moderation:${target.id}`}, 0))`);
    const now = clock.now();
    const expiresAt = input.duration === 'permanent' || input.duration === 'remove' ? null
      : new Date(now.getTime() + MUTE_MINUTES[input.duration] * 60_000);
    if (input.duration === 'remove') {
      await tx.delete(chatMutes).where(and(eq(chatMutes.accountId, target.id), inArray(chatMutes.channel, input.channels)));
    } else {
      await tx.insert(chatMutes).values(input.channels.map(channel => ({
        accountId: target.id, channel, expiresAt, createdAt: now, actorAccountId,
      }))).onConflictDoUpdate({ target: [chatMutes.accountId, chatMutes.channel], set: { expiresAt, createdAt: now, actorAccountId } });
    }
    await tx.insert(adminActions).values({ actorAccountId, targetAccountId: target.id, action: 'CHAT_MUTE',
      details: { channels: input.channels, duration: input.duration, expiresAt: expiresAt?.toISOString() ?? null }, createdAt: now });
    return { username: target.username, channels: input.channels, duration: input.duration, expiresAt };
  });
}

export type MaskScope = { channel: 'general'; seasonId: string; language: ChatLanguage }
  | { channel: 'clan'; clanId: string };

export async function maskChatMessages(db: Db, actorAccountId: string, input: MaskScope & { username: string; count: number }, now: Date) {
  return db.transaction(async tx => {
    const target = await targetAccount(tx, input.username);
    let seasonId: string;
    if (input.channel === 'clan') {
      const [clan] = await tx.select({ seasonId: clans.seasonId }).from(clans).where(eq(clans.id, input.clanId)).limit(1);
      if (!clan) throw new GameError('CLAN_NOT_FOUND', 'Clan not found', 404);
      seasonId = clan.seasonId;
    } else {
      seasonId = input.seasonId;
      const [season] = await tx.select({ id: seasons.id }).from(seasons).where(eq(seasons.id, seasonId)).limit(1);
      if (!season) throw new GameError('SEASON_NOT_FOUND', 'Galaxy not found', 404);
    }
    await tx.execute(sql`select pg_advisory_xact_lock(hashtext(${input.channel === 'clan' ? `clan-chat:${input.clanId}` : `chat:${seasonId}`}))`);
    const table = input.channel === 'general' ? chatMessages : clanMessages;
    const scope = input.channel === 'general'
      ? and(eq(chatMessages.seasonId, input.seasonId), eq(chatMessages.language, input.language))
      : eq(clanMessages.clanId, input.clanId);
    const rows = await tx.select({ id: table.id, content: table.content, media: table.media }).from(table)
      .innerJoin(players, eq(players.id, table.authorPlayerId))
      .where(and(scope, eq(players.accountId, target.id)))
      .orderBy(desc(table.createdAt), desc(table.id)).limit(input.count);
    // Count the same last X on retry; never walk backwards into older, unselected text.
    const changed = rows.filter(row => row.content !== '**' || row.media !== null);
    if (changed.length > 0) {
      await tx.update(table).set({ content: '**', media: null }).where(inArray(table.id, changed.map(row => row.id)));
      await tx.insert(adminActions).values({ actorAccountId, targetAccountId: target.id, action: 'CHAT_MASK',
        details: { ...input, messages: changed }, createdAt: now });
      if (input.channel === 'general') await publishShard(tx, seasonId, 'chat');
      else for (const playerId of await activeClanPlayerIds(tx, input.clanId)) await publishPrivate(tx, playerId, 'chat');
    }
    return { masked: changed.length };
  });
}
import { assertCommunityPolicyAccepted } from './communityPolicy.js';

