import { randomUUID } from 'node:crypto';
import { settlePlanetRadiationAt } from './planetRadiation.js';
import { and, eq, inArray, isNull, or } from 'drizzle-orm';
import {
  CLAN_SUPPORT,
  HULLS,
  NON_COMBATANT_HULLS,
