import { and, eq } from 'drizzle-orm';
import {
  clanDefenseApplies,
  combatValue,
  fleetCount,
  fleetEntries,
  hangarLoad,
  normalizeLots,
  normalizeHpDamage,
  partitionCombatFleet,
  shipDamageApplies,
  withinTierBand,
  type HpDamageLot,
  type DefenderOutcome,
  type DefenderStack,
  type Fleet,
  type HullId,
  type Resources,
  type SupportFactor,
  supportFactor,
} from '@astera/rules';
import type { Tx } from '../db/client.js';
import { clanSupportBattleResults, clanSupportWaves } from '../db/schema.js';
import { activeClanMembership } from './clanCombat.js';
import { loseWave, lockWaves, publishSupport, returnWave, shipsOf, supportFlightTech } from './clanSupport.js';
import type { WaveRow } from './clanSupportView.js';
import { notify } from './notifications.js';
import { recomputePlayerWealth, setUnits, type LockedPlanet } from './planet.js';
import { peakCoreLevels } from './player.js';

/**
 * KLAN SAVUNMA DESTEĞİ — THE DEFENDING LINE, WHOEVER HOLDS IT. Plan §Server.
 *
 * The ordinary raid (`worker/handlers.ts`) and a clan's joint war
 * (`clanWarSettlement.ts`) both fight a world, and both read the clanmates' waves
 * standing at it through here, so the line is assembled once and settled once:
 *
 *   1. `lockStationsAt` — the STATIONED waves at the world, locked after the world and
 *      before any clan or player row (season → planets → waves → clans → players);
 *   2. `standStations` — each wave re-checked at the instant of the fight: same clan,
 *      inside the host's tier band, the world still at SUPPORT. One that fails goes home
 *      untouched before a shot (owner K3); the rest become owned stacks;
 *   3. `settleStations` — each wave's survivors and damage written back to its own row;
 *   4. `supportFactorOf` / `writeDefenderResults` / `notifySupporters`.
 */

export interface Station {
  wave: WaveRow;
  fleet: Fleet;
  stack: DefenderStack;
  /** `combatValue` the wave brought — its Dominion weight (owner K6). */
  power: number;
}

export async function lockStationsAt(
  tx: Tx,
  input: { hostPlanetId: string; rulesetVersion: number },
): Promise<WaveRow[]> {
  if (!clanDefenseApplies(input.rulesetVersion)) return [];
  const candidates = await tx.select({ id: clanSupportWaves.id }).from(clanSupportWaves)
    .where(and(eq(clanSupportWaves.hostPlanetId, input.hostPlanetId), eq(clanSupportWaves.status, 'STATIONED')));
  if (candidates.length === 0) return [];
  return (await lockWaves(tx, candidates.map((row) => row.id)))
    .filter((wave) => wave.status === 'STATIONED' && wave.hostPlanetId === input.hostPlanetId);
}

/** The commanders a battle must lock a ledger for, beyond attacker and host. */
export const supporterIdsOf = (waves: readonly WaveRow[]): string[] =>
  [...new Set(waves.map((wave) => wave.senderPlayerId))].sort();

export async function standStations(
  tx: Tx,
  input: { waves: readonly WaveRow[]; host: LockedPlanet; rulesetVersion: number; now: Date },
): Promise<Station[]> {
  if (input.waves.length === 0) return [];
  if (input.host.defencePosture !== 'SUPPORT') {
    for (const wave of input.waves) await returnWave(tx, wave, 'HOST_CLOSED', input.now);
    return [];
  }
  const senders = supporterIdsOf(input.waves);
  const [peaks, hostMembership] = await Promise.all([
    peakCoreLevels(tx, [input.host.playerId, ...senders]),
    activeClanMembership(tx, input.host.playerId),
  ]);
  const hostPeak = peaks.get(input.host.playerId) ?? 1;
  const damageRule = shipDamageApplies(input.rulesetVersion);
  const stations: Station[] = [];
  for (const wave of input.waves) {
    if (wave.hostPlayerId !== input.host.playerId) {
      await returnWave(tx, wave, 'WORLD_CHANGED', input.now);
      continue;
    }
    const membership = await activeClanMembership(tx, wave.senderPlayerId);
    if (membership?.clanId !== wave.clanId || hostMembership?.clanId !== wave.clanId) {
      await returnWave(tx, wave, 'MEMBERSHIP', input.now);
      continue;
    }
    if (!withinTierBand(peaks.get(wave.senderPlayerId) ?? 1, hostPeak)) {
      await returnWave(tx, wave, 'BAND', input.now);
      continue;
    }
    const fleet = await shipsOf(tx, wave);
    if (fleetCount(fleet) === 0) {
      await loseWave(tx, wave, input.now);
      continue;
    }
    const lots = !damageRule ? [] : normalizeHpDamage(fleet, wave.damage);
    const ready = partitionCombatFleet(fleet, lots);
    stations.push({
      wave,
      fleet,
      power: combatValue(ready.eligible),
      stack: {
        stackId: wave.id,
        playerId: wave.senderPlayerId,
        fleet: ready.eligible,
        tech: { tech: await supportFlightTech(tx, wave) },
        ...(ready.damage.length > 0 ? { damage: ready.damage } : {}),
      },
    });
  }
  return stations;
}

/** One for the host, plus one per commander who stood at least one ship in the line. */
export const defenderCountOf = (stations: readonly Station[]): number =>
  1 + new Set(stations.filter((station) => fleetCount(station.stack.fleet) > 0).map((s) => s.wave.senderPlayerId)).size;

/** The whole line as it stood: the host's own and every wave's ships. */
export function lineOf(hostLine: Fleet, stations: readonly Station[]): Fleet {
  const out: Fleet = { ...hostLine };
  for (const station of stations) {
    for (const [hull, n] of fleetEntries(station.stack.fleet)) out[hull] = (out[hull] ?? 0) + n;
  }
  return out;
}

/** Each wave's survivors and damage written back to its own row; a wiped wave is lost. */
export async function settleStations(
  tx: Tx,
  input: { stations: readonly Station[]; outcomes: readonly DefenderOutcome[]; damageRule: boolean; now: Date },
): Promise<void> {
  for (const station of input.stations) {
    const outcome = input.outcomes.find((row) => row.stackId === station.wave.id);
    if (!outcome) throw new Error(`support wave ${station.wave.id} left the battle unrecorded`);
    const excluded = partitionCombatFleet(station.fleet, station.wave.damage);
    const physical: Fleet = { ...outcome.survivors };
    for (const [hull, count] of fleetEntries(excluded.excluded)) physical[hull] = (physical[hull] ?? 0) + count;
    if (fleetCount(physical) === 0) {
      await loseWave(tx, station.wave, input.now);
      continue;
    }
    // Every hull the wave stood with is written, so one wiped out is zeroed rather than kept.
    const remaining: Fleet = {};
    for (const hull of Object.keys(station.fleet) as HullId[]) remaining[hull] = physical[hull] ?? 0;
    await setUnits(tx, station.wave.originPlanetId, remaining, station.wave.unitLocation, station.wave.senderPlayerId);
    const wounds = normalizeHpDamage(physical, [...outcome.survivorDamage, ...excluded.excludedDamage]);
    const damage = input.damageRule
      ? (wounds.length > 0 ? wounds : null)
      : station.wave.damage;
    await tx.update(clanSupportWaves).set({
      damage,
      reservedBulk: hangarLoad(physical),
      battles: station.wave.battles + (fleetCount(station.stack.fleet) > 0 ? 1 : 0),
    }).where(eq(clanSupportWaves.id, station.wave.id));
    await recomputePlayerWealth(tx, station.wave.senderPlayerId, input.now);
    await publishSupport(tx, station.wave);
  }
}

/** Each supporting commander's waves summed — the unit the ladder and the report use. */
function bySupporter(stations: readonly Station[], outcomes: readonly DefenderOutcome[]) {
  const rows = new Map<string, {
    playerId: string;
    power: number;
    sent: Fleet;
    losses: Fleet;
    survivors: Fleet;
    lossValue: number;
    damage: HpDamageLot[];
  }>();
  const add = (into: Fleet, from: Fleet) => {
    for (const [hull, n] of fleetEntries(from)) into[hull] = (into[hull] ?? 0) + n;
  };
  for (const station of stations) {
    if (fleetCount(station.stack.fleet) === 0) continue;
    const outcome = outcomes.find((row) => row.stackId === station.wave.id);
    const row = rows.get(station.wave.senderPlayerId) ?? {
      playerId: station.wave.senderPlayerId, power: 0, sent: {}, losses: {}, survivors: {}, lossValue: 0, damage: [],
    };
    row.power += station.power;
    add(row.sent, station.stack.fleet);
    if (outcome) {
      add(row.losses, outcome.losses);
      add(row.survivors, outcome.survivors);
      row.lossValue += outcome.lossValue;
      row.damage.push(...outcome.survivorDamage);
    }
    rows.set(row.playerId, row);
  }
  return [...rows.values()].sort((a, b) => (a.playerId < b.playerId ? -1 : 1));
}

/**
 * HOW MUCH THIS LINE'S SUPPORT MULTIPLIES THE HOST'S DOMINION. Owner decision, 2026-10-02.
 *
 * `hostPower` is the host's own line as it stood — ships and the guns that fired — and the
 * support is every wave's ships; see `supportFactor`. Only the host's ledger moves.
 */
export const supportFactorOf = (hostPower: number, stations: readonly Station[]): SupportFactor =>
  supportFactor({ hostPower, supportPower: stations.reduce((sum, station) => sum + station.power, 0) });

/**
 * WHAT THE SUPPORTERS' SHIPS WERE WORTH WHEN THEY DIED — the part of the exchange written at
 * face value, never multiplied (owner decision (b), `defendedTransfer`).
 */
export function supportLossOf(stations: readonly Station[], outcomes: readonly DefenderOutcome[]): number {
  let total = 0;
  for (const station of stations) {
    total += outcomes.find((row) => row.stackId === station.wave.id)?.lossValue ?? 0;
  }
  return total;
}

/** The report's per-commander rows: who stood, what they lost, what the ladder said. */
export async function writeDefenderResults(
  tx: Tx,
  input: {
    seasonId: string;
    reportId: string;
    host: { playerId: string; outcome: DefenderOutcome; power: number; lootLost: Resources };
    stations: readonly Station[];
    outcomes: readonly DefenderOutcome[];
    /** What the host's ledger moved by; a supporter's never moves (owner, 2026-10-02). */
    hostDelta: number;
    now: Date;
  },
): Promise<void> {
  await tx.insert(clanSupportBattleResults).values([
    {
      seasonId: input.seasonId,
      reportId: input.reportId,
      playerId: input.host.playerId,
      role: 'HOST' as const,
      sent: input.host.outcome.sent,
      losses: input.host.outcome.losses,
      survivors: input.host.outcome.survivors,
      power: input.host.power,
      lossValue: input.host.outcome.lossValue,
      damage: input.host.outcome.survivorDamage,
      lootLost: input.host.lootLost,
      dominionDelta: input.hostDelta,
      createdAt: input.now,
    },
    ...bySupporter(input.stations, input.outcomes).map((row) => ({
      seasonId: input.seasonId,
      reportId: input.reportId,
      playerId: row.playerId,
      role: 'SUPPORT' as const,
      sent: row.sent,
      losses: row.losses,
      survivors: row.survivors,
      power: row.power,
      lossValue: row.lossValue,
      damage: row.damage.some((lot) => lot.remainderBp !== undefined) ? normalizeHpDamage(row.survivors, row.damage) : normalizeLots(row.damage),
      dominionDelta: 0,
      createdAt: input.now,
    })),
  ]);
}

/** Every supporter hears their wave fought, with the way into the report. */
export async function notifySupporters(
  tx: Tx,
  input: {
    missionId: string;
    reportId: string;
    grade: string;
    hostPlanetId: string;
    hostPlanetName: string;
    stations: readonly Station[];
    outcomes: readonly DefenderOutcome[];
    now: Date;
  },
): Promise<void> {
  for (const row of bySupporter(input.stations, input.outcomes)) {
    await notify(tx, {
      playerId: row.playerId,
      kind: 'clan_support_result',
      payload: {
        reportId: input.reportId,
        grade: input.grade,
        hostPlanetId: input.hostPlanetId,
        hostPlanetName: input.hostPlanetName,
        lost: fleetCount(row.losses),
        survived: fleetCount(row.survivors),
      },
      at: input.now,
      refId: input.missionId,
    });
  }
}

sources.apps/server/src/services/dm.ts:
import { accountForPlayer, chatVisibleTo, lockCommunityPair } from './communityBlocks.js';
import { randomUUID } from 'node:crypto';
import { claimChatMedia } from './chatMedia.js';
import type { ChatMedia } from '@astera/rules';
import { and, asc, desc, eq, inArray, isNull, or, sql } from 'drizzle-orm';
import { CHAT } from '@astera/rules';
import type { Clock } from '../clock.js';
import type { Db, Queryable, Tx } from '../db/client.js';
import {
  accounts, botProfiles, dmBlocks, dmConversations, dmMessages, dmReadMarkers,
  players, seasons, shards,
} from '../db/schema.js';
import { CHANNEL, publish } from '../stream/bus.js';
import { GameError } from './planet.js';
import { assertChatAllowed, assertCleanMessage } from './chatModeration.js';
import { messageDecorations, authorRecognition } from './messageDecorations.js';

interface Commander {
  id: string;
  accountId: string;
  seasonId: string;
  username: string;
  country: string;
  role: 'MAIN' | 'WAITING';
  seasonStatus: string;
}

async function commander(db: Queryable, accountId: string): Promise<Commander> {
  const [row] = await db.select({
    id: players.id, accountId: players.accountId, seasonId: players.seasonId,
    username: accounts.displayName, country: accounts.countryCode,
    role: shards.role, seasonStatus: seasons.status,
  }).from(players)
    .innerJoin(accounts, eq(accounts.id, players.accountId))
    .innerJoin(seasons, eq(seasons.id, players.seasonId))
    .innerJoin(shards, eq(shards.id, seasons.shardId))
    .where(eq(players.accountId, accountId)).limit(1);
  if (!row) throw new GameError('NO_PLANET', 'Join a galaxy first', 404);
  return row;
}

async function participant(db: Queryable, accountId: string, conversationId: string) {
  const me = await commander(db, accountId);
  const [conversation] = await db.select().from(dmConversations).where(and(
    eq(dmConversations.id, conversationId),
    or(eq(dmConversations.playerLowId, me.id), eq(dmConversations.playerHighId, me.id)),
  )).limit(1);
  if (!conversation) throw new GameError('DM_NOT_FOUND', 'Conversation not found', 404);
  return { me, conversation };
}

export async function lockDmPair(tx: Tx, a: string, b: string): Promise<void> {
  const [low, high] = a < b ? [a, b] : [b, a];
  await tx.execute(sql`select pg_advisory_xact_lock(hashtext(${`dm:${low}:${high}`}))`);
}

async function isBlocked(db: Queryable, a: string, b: string): Promise<boolean> {
  const [row] = await db.select({ blocker: dmBlocks.blockerPlayerId }).from(dmBlocks).where(or(
    and(eq(dmBlocks.blockerPlayerId, a), eq(dmBlocks.targetPlayerId, b)),
    and(eq(dmBlocks.blockerPlayerId, b), eq(dmBlocks.targetPlayerId, a)),
  )).limit(1);
  if (row) return true;
  const [community] = await db.execute<{ blocked: boolean }>(sql`SELECT NOT ${chatVisibleTo(accountForPlayer(a), sql`${b}::uuid`)} AS blocked`);
  return community?.blocked ?? false;
}

export async function dmContacts(db: Db, accountId: string, query: string) {
  const me = await commander(db, accountId);
  if (me.role !== 'MAIN' || me.seasonStatus !== 'live') return { contacts: [] };
  const pattern = `%${query.replaceAll('\\', '\\\\').replaceAll('%', '\\%').replaceAll('_', '\\_')}%`;
  const contacts = await db.select({
    playerId: players.id, username: accounts.displayName, country: accounts.countryCode,
  }).from(players)
    .innerJoin(accounts, eq(accounts.id, players.accountId))
    .leftJoin(botProfiles, eq(botProfiles.accountId, accounts.id))
    .where(and(
      eq(players.seasonId, me.seasonId), isNull(botProfiles.accountId),
      chatVisibleTo(accountId, players.id),
      sql`${players.id} <> ${me.id}`,
      sql`${accounts.displayName} ILIKE ${pattern} ESCAPE '\\'`,
      sql`NOT EXISTS (
        SELECT 1 FROM dm_blocks b
        WHERE (b.blocker_player_id = ${me.id} AND b.target_player_id = ${players.id})
           OR (b.blocker_player_id = ${players.id} AND b.target_player_id = ${me.id})
      )`,
    ))
    .orderBy(asc(accounts.displayName))
    .limit(30);
  return { contacts };
}

interface ConversationRow extends Record<string, unknown> {
  id: string;
  conversationSeasonId: string;
  peerId: string;
  username: string;
  country: string;
  peerSeasonId: string;
  blockedByMe: boolean;
  blockedByPeer: boolean;
  communityBlockedByMe: boolean;
  communityBlocked: boolean;
  unreadCount: number;
  lastId: string;
  lastContent: string;
  lastCreatedAt: Date;
}

export async function dmConversationsFor(db: Db, accountId: string) {
  const me = await commander(db, accountId);
  const rows = await db.execute<ConversationRow>(sql`
    SELECT c.id, c.season_id AS "conversationSeasonId",
           peer.id AS "peerId", a.display_name AS username, a.country_code AS country,
           peer.season_id AS "peerSeasonId",
           (mine.blocker_player_id IS NOT NULL) AS "blockedByMe",
           EXISTS(SELECT 1 FROM community_blocks cb WHERE cb.blocker_account_id=${accountId} AND cb.target_account_id=peer.account_id) AS "communityBlockedByMe",
           (NOT ${chatVisibleTo(accountId, sql`peer.id`)}) AS "communityBlocked",
           (theirs.blocker_player_id IS NOT NULL) AS "blockedByPeer",
           (SELECT count(*)::int FROM dm_messages m
             WHERE m.conversation_id = c.id AND m.author_player_id <> ${me.id}
               AND ${chatVisibleTo(accountId, sql`m.author_player_id`)}
               AND (r.read_at IS NULL OR m.created_at > r.read_at)) AS "unreadCount",
           last.id AS "lastId", last.content AS "lastContent", last.created_at AS "lastCreatedAt"
      FROM dm_conversations c
      JOIN players peer ON peer.id = CASE WHEN c.player_low_id = ${me.id}
                                         THEN c.player_high_id ELSE c.player_low_id END
      JOIN accounts a ON a.id = peer.account_id
      LEFT JOIN dm_read_markers r ON r.conversation_id = c.id AND r.player_id = ${me.id}
      LEFT JOIN dm_blocks mine ON mine.blocker_player_id = ${me.id} AND mine.target_player_id = peer.id
      LEFT JOIN dm_blocks theirs ON theirs.blocker_player_id = peer.id AND theirs.target_player_id = ${me.id}
      JOIN LATERAL (
        SELECT m.id, m.content, m.created_at FROM dm_messages m
         WHERE m.conversation_id = c.id ORDER BY m.created_at DESC, m.id DESC LIMIT 1
      ) last ON true
     WHERE c.player_low_id = ${me.id} OR c.player_high_id = ${me.id}
     ORDER BY last.created_at DESC, last.id DESC
  `);
  const conversations = rows.map((row) => {
    const unavailableReason = me.seasonStatus !== 'live' ? 'SEASON_ENDED' as const
      : me.seasonId !== row.conversationSeasonId
        || row.peerSeasonId !== row.conversationSeasonId || me.role !== 'MAIN'
        ? 'WAITING' as const
      : row.blockedByMe || row.blockedByPeer || row.communityBlocked ? 'BLOCKED' as const : null;
    return {
      id: row.id,
      peer: { playerId: row.peerId, username: row.username, country: row.country },
      lastMessage: { id: row.lastId, content: row.lastContent, createdAt: row.lastCreatedAt },
      unreadCount: row.unreadCount,
      blockedByMe: row.blockedByMe,
      communityBlockedByMe: row.communityBlockedByMe,
      canSend: unavailableReason === null,
      unavailableReason,
    };
  });
  return { conversations, totalUnread: conversations.reduce((total, row) => total + row.unreadCount, 0) };
}

export async function dmUnread(db: Db, accountId: string): Promise<number> {
  const me = await commander(db, accountId);
  const [row] = await db.execute<{ count: number }>(sql`
    SELECT count(*)::int AS count
      FROM dm_conversations c
      JOIN dm_messages m ON m.conversation_id = c.id AND m.author_player_id <> ${me.id}
      LEFT JOIN dm_read_markers r ON r.conversation_id = c.id AND r.player_id = ${me.id}
     WHERE (c.player_low_id = ${me.id} OR c.player_high_id = ${me.id})
       AND (r.read_at IS NULL OR m.created_at > r.read_at)
       AND ${chatVisibleTo(accountId, sql`m.author_player_id`)}
  `);
  return row?.count ?? 0;
}

export async function dmPage(db: Db, accountId: string, conversationId: string, limit: number, before?: string) {
  const { me, conversation } = await participant(db, accountId, conversationId);
  let cursor: { createdAt: Date; id: string } | undefined;
  if (before) {
    const [found] = await db.select({ createdAt: dmMessages.createdAt, id: dmMessages.id })
      .from(dmMessages).where(and(eq(dmMessages.id, before), eq(dmMessages.conversationId, conversationId))).limit(1);
    if (!found) throw new GameError('BAD_DM_CURSOR', 'Conversation cursor not found', 400);
    cursor = found;
  }
  const rows = await db.select({
    id: dmMessages.id, authorPlayerId: dmMessages.authorPlayerId,
    username: accounts.displayName, content: dmMessages.content, media: dmMessages.media,
    replyToMessageId: dmMessages.replyToMessageId, createdAt: dmMessages.createdAt,
  }).from(dmMessages)
    .innerJoin(players, eq(players.id, dmMessages.authorPlayerId))
    .innerJoin(accounts, eq(accounts.id, players.accountId))
    .where(and(
      eq(dmMessages.conversationId, conversationId),
      cursor ? or(
        sql`${dmMessages.createdAt} < ${cursor.createdAt}`,
        and(eq(dmMessages.createdAt, cursor.createdAt), sql`${dmMessages.id} < ${cursor.id}`),
      ) : undefined,
    ))
    .orderBy(desc(dmMessages.createdAt), desc(dmMessages.id)).limit(limit + 1);
  const page = rows.slice(0, limit);
  const decorations = await messageDecorations(db, 'dm', page, me.id);
  const peerId = conversation.playerLowId === me.id ? conversation.playerHighId : conversation.playerLowId;
  const [peer] = await db.select({ seasonId: players.seasonId }).from(players).where(eq(players.id, peerId)).limit(1);
  const blocked = await isBlocked(db, me.id, peerId);
  const unavailableReason = me.seasonStatus !== 'live' ? 'SEASON_ENDED' as const
    : me.seasonId !== conversation.seasonId || peer?.seasonId !== conversation.seasonId || me.role !== 'MAIN'
      ? 'WAITING' as const : blocked ? 'BLOCKED' as const : null;
  return {
    messages: page.reverse().map(({ replyToMessageId: _replyToMessageId, ...row }) => ({
      ...row, self: row.authorPlayerId === me.id,
      ...(decorations.get(row.id) ?? { replyTo: null, reactions: [] }),
    })),
    nextBefore: rows.length > limit ? (page.at(-1)?.id ?? null) : null,
    canSend: unavailableReason === null,
    unavailableReason,
  };
}

export async function postDm(db: Db, accountId: string, recipientPlayerId: string, content: string, clock: Clock, replyToMessageId?: string, mediaInput?: ChatMedia, adminUsernames: ReadonlySet<string> = new Set()) {
  assertCleanMessage(content);
  const requestedAt = clock.now();
  return db.transaction(async (tx) => {
    const me = await commander(tx, accountId);
    if (me.id === recipientPlayerId) throw new GameError('DM_SELF', 'Cannot message yourself', 400);
    await tx.execute(sql`select pg_advisory_xact_lock(hashtext(${`dm-rate:${me.id}`}))`);
    const pair = [me.id, recipientPlayerId].sort();
    const locked = await tx.select({ id: players.id, seasonId: players.seasonId, accountId: players.accountId })
      .from(players).where(inArray(players.id, pair)).orderBy(asc(players.id)).for('update');
    const recipient = locked.find((row) => row.id === recipientPlayerId);
    if (!recipient) throw new GameError('DM_RECIPIENT_NOT_FOUND', 'Commander not found', 404);
    const [bot] = await tx.select({ accountId: botProfiles.accountId }).from(botProfiles)
      .where(eq(botProfiles.accountId, recipient.accountId)).limit(1);
    if (bot) throw new GameError('DM_RECIPIENT_NOT_FOUND', 'Commander not found', 404);
    if (me.role !== 'MAIN' || me.seasonStatus !== 'live' || recipient.seasonId !== me.seasonId) {
      throw new GameError('DM_UNAVAILABLE', 'Both commanders must be in the same live galaxy', 409);
    }
    await lockDmPair(tx, me.id, recipientPlayerId);
    await lockCommunityPair(tx, accountId, recipient.accountId);
    await assertChatAllowed(tx, accountId, 'dm', clock);
    if (await isBlocked(tx, me.id, recipientPlayerId)) {
      throw new GameError('DM_BLOCKED', 'This conversation cannot receive messages', 403);
    }
    const cutoff = new Date(requestedAt.getTime() - CHAT.windowSeconds * 1000);
    const [rate] = await tx.execute<{ count: number }>(sql`
      SELECT count(*)::int AS count FROM dm_messages
       WHERE author_player_id = ${me.id} AND created_at > ${cutoff.toISOString()}::timestamptz
    `);
    if ((rate?.count ?? 0) >= CHAT.burst) {
      throw new GameError('CHAT_RATE_LIMIT', 'Slow down before sending another message', 429, { seconds: CHAT.windowSeconds });
    }
    const [inserted] = await tx.insert(dmConversations).values({
      seasonId: me.seasonId, playerLowId: pair[0]!, playerHighId: pair[1]!,
    }).onConflictDoNothing().returning({ id: dmConversations.id });
    const [existing] = inserted ? [] : await tx.select({ id: dmConversations.id }).from(dmConversations).where(and(
      eq(dmConversations.seasonId, me.seasonId), eq(dmConversations.playerLowId, pair[0]!), eq(dmConversations.playerHighId, pair[1]!),
    )).limit(1);
    const conversationId = inserted?.id ?? existing?.id;
    if (!conversationId) throw new Error('DM conversation insert returned no row');
    const [replyTo] = replyToMessageId ? await tx.select({
      id: dmMessages.id, content: dmMessages.content, media: dmMessages.media, username: accounts.displayName,
    }).from(dmMessages)
      .innerJoin(players, eq(players.id, dmMessages.authorPlayerId))
      .innerJoin(accounts, eq(accounts.id, players.accountId))
      .where(and(eq(dmMessages.id, replyToMessageId), eq(dmMessages.conversationId, conversationId))).limit(1) : [];
    if (replyToMessageId && !replyTo) throw new GameError('DM_MESSAGE_NOT_FOUND', 'Message not found', 404);
    const [latest] = await tx.select({ createdAt: dmMessages.createdAt }).from(dmMessages)
      .where(eq(dmMessages.conversationId, conversationId))
      .orderBy(desc(dmMessages.createdAt), desc(dmMessages.id)).limit(1);
    const createdAt = latest && latest.createdAt >= requestedAt
      ? new Date(latest.createdAt.getTime() + 1) : requestedAt;
    const messageId = randomUUID();
    const media = await claimChatMedia(tx, accountId, mediaInput, adminUsernames, requestedAt, 'dm', messageId);
    const [message] = await tx.insert(dmMessages).values({
      id: messageId, media,
      conversationId, authorPlayerId: me.id, content, replyToMessageId: replyToMessageId ?? null, createdAt,
    }).returning({ id: dmMessages.id, authorPlayerId: dmMessages.authorPlayerId,
      content: dmMessages.content, media: dmMessages.media, createdAt: dmMessages.createdAt });
    if (!message) throw new Error('DM insert returned no row');
    await publish(tx, me.id, 'private:dm');
    await publish(tx, recipientPlayerId, 'private:dm');
    const recognition = (await authorRecognition(tx, [me.id])).get(me.id);
    return { conversationId, message: { ...message, username: me.username, self: true,
      replyTo: replyTo ?? null, reactions: [],
      ...recognition } };
  });
}

export async function markDmRead(db: Db, accountId: string, conversationId: string, messageId: string) {
  return db.transaction(async (tx) => {
    const { me } = await participant(tx, accountId, conversationId);
    const [message] = await tx.select({ createdAt: dmMessages.createdAt }).from(dmMessages)
      .where(and(eq(dmMessages.id, messageId), eq(dmMessages.conversationId, conversationId))).limit(1);
    if (!message) throw new GameError('DM_MESSAGE_NOT_FOUND', 'Message not found', 404);
    await tx.select({ id: players.id }).from(players).where(eq(players.id, me.id)).for('update');
    const [marker] = await tx.select({ readAt: dmReadMarkers.readAt }).from(dmReadMarkers).where(and(
      eq(dmReadMarkers.conversationId, conversationId), eq(dmReadMarkers.playerId, me.id),
    )).limit(1);
    const readAt = marker?.readAt && marker.readAt > message.createdAt ? marker.readAt : message.createdAt;
    await tx.insert(dmReadMarkers).values({ conversationId, playerId: me.id, readAt })
      .onConflictDoUpdate({ target: [dmReadMarkers.conversationId, dmReadMarkers.playerId], set: { readAt } });
    return { readAt };
  });
}

export async function setDmBlock(db: Db, accountId: string, targetPlayerId: string, blocked: boolean, clock: Clock) {
  return db.transaction(async (tx) => {
    const me = await commander(tx, accountId);
    if (me.id === targetPlayerId) throw new GameError('DM_SELF', 'Cannot block yourself', 400);
    const [target] = await tx.select({ id: players.id, seasonId: players.seasonId })
      .from(players).where(eq(players.id, targetPlayerId)).limit(1);
    if (!target) throw new GameError('DM_RECIPIENT_NOT_FOUND', 'Commander not found', 404);
    const [existing] = await tx.select({ id: dmConversations.id }).from(dmConversations).where(or(
      and(eq(dmConversations.playerLowId, me.id), eq(dmConversations.playerHighId, targetPlayerId)),
      and(eq(dmConversations.playerHighId, me.id), eq(dmConversations.playerLowId, targetPlayerId)),
    )).limit(1);
    if (target.seasonId !== me.seasonId && !existing) throw new GameError('DM_RECIPIENT_NOT_FOUND', 'Commander not found', 404);
    await lockDmPair(tx, me.id, targetPlayerId);
    if (blocked) {
      await tx.insert(dmBlocks).values({ blockerPlayerId: me.id, targetPlayerId, createdAt: clock.now() }).onConflictDoNothing();
    } else {
      await tx.delete(dmBlocks).where(and(eq(dmBlocks.blockerPlayerId, me.id), eq(dmBlocks.targetPlayerId, targetPlayerId)));
    }
    await publish(tx, me.id, 'private:dm');
    await publish(tx, targetPlayerId, 'private:dm');
    return { blocked };
  });
}

/** A transfer changes every peer's send permission; fan out only to actual DM peers. */
export async function notifyDmPeers(tx: Tx, playerId: string): Promise<void> {
  await tx.execute(sql`
    SELECT pg_notify(${CHANNEL}, json_build_object(
      'playerId', CASE WHEN player_low_id = ${playerId} THEN player_high_id ELSE player_low_id END,
      'kind', 'private:dm'
    )::text)
      FROM dm_conversations
     WHERE player_low_id = ${playerId} OR player_high_id = ${playerId}
  `);
  await publish(tx, playerId, 'private:dm');
}

