import { MULTI_WORLD, dominion as ledgerDominion } from '@astera/rules';
import { and, asc, desc, eq, notInArray, sql } from 'drizzle-orm';
import type { Queryable } from '../db/client.js';
import { clans, planets, players } from '../db/schema.js';

/** Canonical integer score expressions used by every public projection. */
export const playerDominionSql = sql<number>`
  ${players.dominionTaken} - ${players.dominionLost}
`.mapWith(Number);
export const clanDominionSql = sql<number>`
  ${clans.dominionTaken} - ${clans.dominionLost}
`.mapWith(Number);

/** Add two monotonic Dominion counters without ever rounding through `number`. */
export function addDominionCounters(
  left: number,
  right: number,
  label = 'Dominion counter sum',
): number {
  if (!Number.isSafeInteger(left) || !Number.isSafeInteger(right)) {
    throw new RangeError(`${label} is outside the safe integer range`);
  }
  if (left < 0 || right < 0) {
    throw new RangeError(`${label} requires non-negative counters`);
  }
  const exact = BigInt(left) + BigInt(right);
  if (exact > BigInt(Number.MAX_SAFE_INTEGER)) {
    throw new RangeError(`${label} is outside the safe integer range`);
  }
  return Number(exact);
}

export function dominionScore(taken: number, lost: number): number {
  return ledgerDominion({ taken, lost });
}

/** Sum signed Dominion scores without lossy intermediate `number` arithmetic. */
export function sumDominionScores(
  values: readonly number[],
  label = 'Dominion score sum',
): number {
  let exact = 0n;
  for (const value of values) {
    if (!Number.isSafeInteger(value)) {
      throw new RangeError(`${label} is outside the safe integer range`);
    }
    exact += BigInt(value);
  }
  if (
    exact > BigInt(Number.MAX_SAFE_INTEGER)
    || exact < BigInt(Number.MIN_SAFE_INTEGER)
  ) {
    throw new RangeError(`${label} is outside the safe integer range`);
  }
  return Number(exact);
}

/** Descending score order without subtracting two opposite safe-integer extremes. */
export function compareDominionScoresDescending(left: number, right: number): number {
  if (!Number.isSafeInteger(left) || !Number.isSafeInteger(right)) {
    throw new RangeError('Dominion score is outside the safe integer range');
  }
  return left === right ? 0 : right > left ? 1 : -1;
}

/** The same eligible top-three ordering used by the ladder, without operator accounts. */
export async function dominionPodium(
  db: Queryable,
  seasonId: string,
  excludedPlayerIds: ReadonlySet<string>,
): Promise<Map<string, 1 | 2 | 3>> {
  const rows = await db
    .select({ playerId: players.id })
    .from(players)
    .innerJoin(
      planets,
      and(eq(planets.controllerPlayerId, players.id), eq(planets.kind, 'CAPITAL')),
    )
    .where(and(
      eq(players.seasonId, seasonId),
      excludedPlayerIds.size > 0
        ? notInArray(players.id, [...excludedPlayerIds])
        : undefined,
    ))
    .orderBy(desc(playerDominionSql), asc(players.joinedAt), asc(players.id))
    .limit(3);
  return new Map(rows.map((row, index) => [row.playerId, (index + 1) as 1 | 2 | 3]));
}

/** Replace cached all-player podium marks with the competition-eligible podium. */
export function applyDominionPodium<World extends {
  controller: { kind: string; playerId?: string };
  dominionRank?: 1 | 2 | 3;
}>(worlds: readonly World[], podium: ReadonlyMap<string, 1 | 2 | 3>): World[] {
  return worlds.map((world) => {
    const { dominionRank: _discarded, ...withoutRank } = world;
    if (world.controller.kind !== 'PLAYER' || world.controller.playerId === undefined) {
      return withoutRank as World;
    }
    const rank = podium.get(world.controller.playerId);
    return (rank === undefined ? withoutRank : { ...withoutRank, dominionRank: rank }) as World;
  });
}

interface DominionLedgerRow {
  playerId: string;
  taken: number;
  lost: number;
}

interface DominionEventRow {
  attackerPlayerId: string;
  defenderPlayerId: string | null;
  dominionSwing: number | null;
  dominionRuleVersion: number | null;
  dominionLootValue: number | null;
  dominionAttackerLossValue: number | null;
  dominionDefenderLossValue: number | null;
  dominionRawExchange: number | null;
  dominionEligible: boolean | null;
}

interface ClanDominionLedgerRow {
  clanId: string;
  taken: number;
  lost: number;
}

interface ClanDominionEventRow {
  clanId: string;
  dominionDelta: number;
}

const addMovement = (
  ledger: { taken: number; lost: number },
  movement: number,
): void => {
  if (movement >= 0) {
    ledger.taken = addDominionCounters(
      ledger.taken,
      movement,
      'Dominion audit failed: accumulated movement',
    );
  } else {
    ledger.lost = addDominionCounters(
      ledger.lost,
      -movement,
      'Dominion audit failed: accumulated movement',
    );
  }
};

/**
 * Reproduce v7 ledgers from their immutable score journal before final ranks freeze.
 *
 * A player keeps the same id and balance while D174 moves them between MAIN and
 * Silent Space, so `events` must cover the whole cycle while `roster` is the
 * local galaxy being frozen. This is intentionally a hard assertion: silently
 * publishing a rank that cannot be explained by its reports would make the
 * competitive record untrustworthy.
 */
export function assertDominionLedgers(
  roster: readonly DominionLedgerRow[],
  events: readonly DominionEventRow[],
  rulesetVersion: number,
  /**
   * A JOINT WAR'S SHARES, FROM THEIR OWN JOURNAL (`clan_war_dominion_events`). Klan Ortak
   * Savaşı books each participant's `delta` and the defender's `-adjusted` straight into
   * the ledgers, by the same sign rule as below; leaving them out made every season a
   * clan had won a war in impossible to close.
   */
  jointWarEvents: readonly { playerId: string; delta: number }[] = [],
): void {
  if (rulesetVersion < MULTI_WORLD.dominionLinearRulesetVersion) return;

  const expected = new Map(roster.map((player) => [
    player.playerId,
    { taken: 0, lost: 0 },
  ]));

  for (const event of events) {
    const attacker = expected.get(event.attackerPlayerId);
    const defender = event.defenderPlayerId === null
      ? undefined
      : expected.get(event.defenderPlayerId);
    if (!attacker && !defender) continue;

    const equationDetail = [
      event.dominionLootValue,
      event.dominionAttackerLossValue,
      event.dominionDefenderLossValue,
      event.dominionRawExchange,
    ];
    // The explicit marker survives room moves and operator configuration changes;
    // a zero with blank detail alone is never enough to infer an exemption.
    if (event.dominionEligible === false) {
      if (
        event.defenderPlayerId === null
        || event.dominionSwing !== 0
        || event.dominionRuleVersion !== rulesetVersion
        || equationDetail.some((value) => value !== null)
      ) {
        throw new Error('Dominion audit failed: invalid competition exemption');
      }
      continue;
    }
    if (event.dominionEligible !== true) {
      throw new Error('Dominion audit failed: a v7 event has no eligibility marker');
    }
    const audit = [event.dominionSwing, event.dominionRuleVersion, ...equationDetail];
    if (event.defenderPlayerId === null || audit.some((value) => value === null)) {
      throw new Error('Dominion audit failed: a scored v7 event has incomplete audit data');
    }
    const [swing, rule, loot, attackerLoss, defenderLoss, raw] = audit as [
      number,
      number,
      number,
      number,
      number,
      number,
    ];
    if (
      !audit.every((value) => Number.isSafeInteger(value))
      || rule !== rulesetVersion
      || loot < 0
      || attackerLoss < 0
      || defenderLoss < 0
    ) {
      throw new Error('Dominion audit failed: a scored v7 event does not reproduce its transfer');
    }
    // Keep the audit as exact as the rule that produced the row. All operands are
    // safe integers here, but an intermediate `number` sum can cross 2^53 before
    // the subtraction brings the result back into range and silently lose one.
    const exactRaw = BigInt(loot) + BigInt(defenderLoss) - BigInt(attackerLoss);
    if (exactRaw !== BigInt(raw) || raw !== swing) {
      throw new Error('Dominion audit failed: a scored v7 event does not reproduce its transfer');
    }

    if (attacker) addMovement(attacker, swing);
    if (defender) addMovement(defender, -swing);
  }

  for (const event of jointWarEvents) {
    if (!Number.isSafeInteger(event.delta)) {
      throw new Error('Dominion audit failed: a joint war share is not a whole figure');
    }
    const ledger = expected.get(event.playerId);
    if (ledger) addMovement(ledger, event.delta);
  }

  for (const player of roster) {
    const reproduced = expected.get(player.playerId)!;
    if (
      !Number.isSafeInteger(player.taken)
      || !Number.isSafeInteger(player.lost)
      || reproduced.taken !== player.taken
      || reproduced.lost !== player.lost
    ) {
      throw new Error(`Dominion audit failed: player ${player.playerId} ledger does not match journal`);
    }
  }
}

/** Reproduce every active clan cache from its immutable per-mission event log. */
export function assertClanDominionLedgers(
  roster: readonly ClanDominionLedgerRow[],
  events: readonly ClanDominionEventRow[],
  rulesetVersion: number,
): void {
  if (rulesetVersion < MULTI_WORLD.dominionLinearRulesetVersion) return;

  const expected = new Map(roster.map((clan) => [
    clan.clanId,
    { taken: 0, lost: 0 },
  ]));
  for (const event of events) {
    const ledger = expected.get(event.clanId);
    if (!ledger) continue;
    if (!Number.isSafeInteger(event.dominionDelta)) {
      throw new Error('Clan Dominion audit failed: event is outside the safe integer range');
    }
    addMovement(ledger, event.dominionDelta);
  }

  for (const clan of roster) {
    const reproduced = expected.get(clan.clanId)!;
    if (
      !Number.isSafeInteger(clan.taken)
      || !Number.isSafeInteger(clan.lost)
      || reproduced.taken !== clan.taken
      || reproduced.lost !== clan.lost
    ) {
      throw new Error(`Clan Dominion audit failed: clan ${clan.clanId} cache does not match events`);
    }
  }
}

import { createHash, createHmac, randomUUID, timingSafeEqual } from 'node:crypto';
import { chmod, lstat, mkdir, open, readdir, readFile, rename, rm } from 'node:fs/promises';
import { join } from 'node:path';
import { eq } from 'drizzle-orm';
import { z } from 'zod';
import type { Db } from '../db/client.js';
import { accounts, accountDeletionRequests, adminActions } from '../db/schema.js';
import { GameError } from './planet.js';

export interface ErasureJournalContext { directory: string; secret: string }
const intentSchema = z.object({
  version: z.literal(1), accountHash: z.string().regex(/^[a-f0-9]{64}$/), requestId: z.string().uuid(),
  requestedAt: z.string().datetime(), approvedAt: z.string().datetime(), recordedAt: z.string().datetime(),
  locale: z.enum(['en', 'tr', 'fr', 'de', 'es', 'ja']),
}).strict();
const signedSchema = z.object({ intent: intentSchema, signature: z.string().regex(/^[a-f0-9]{64}$/) }).strict();
export type ErasureIntent = z.infer<typeof intentSchema>;
const accountHash = (id: string) => createHash('sha256').update(id).digest('hex');
const signature = (secret: string, intent: ErasureIntent) => createHmac('sha256', secret).update('astera-erasure-intent-v1\0').update(JSON.stringify(intent)).digest();
const journalDirectory = (context: ErasureJournalContext) => join(context.directory, '.account-erasure-ledger');

/** Durable before destructive commit; a rolled-back DB attempt may leave a valid approved intent. */
export async function writeErasureIntent(context: ErasureJournalContext, request: { accountId: string; requestId: string; requestedAt: Date; approvedAt: Date; locale: string }, now: Date): Promise<void> {
  const intent = intentSchema.parse({ version: 1, accountHash: accountHash(request.accountId), requestId: request.requestId,
    requestedAt: request.requestedAt.toISOString(), approvedAt: request.approvedAt.toISOString(), recordedAt: now.toISOString(), locale: request.locale });
  const directory = journalDirectory(context);
  const temporary = join(directory, `.${intent.accountHash}.${randomUUID()}.partial`);
  try {
    await mkdir(directory, { recursive: true, mode: 0o700 });
    if (!(await lstat(directory)).isDirectory() || (await lstat(directory)).isSymbolicLink()) throw new Error('Invalid erasure directory');
    await chmod(directory, 0o700);
    const file = await open(temporary, 'wx', 0o600);
    try { await file.writeFile(JSON.stringify({ intent, signature: signature(context.secret, intent).toString('hex') }) + '\n'); await file.sync(); }
    finally { await file.close(); }
    await rename(temporary, join(directory, `${intent.accountHash}.json`));
    const parent = await open(directory, 'r');
    try { await parent.sync(); } finally { await parent.close(); }
  } catch {
    throw new GameError('DELETION_LEDGER_UNAVAILABLE', 'The private deletion journal is unavailable; retry later', 503);
  } finally { await rm(temporary, { force: true }).catch(() => undefined); }
}

/** A missing, corrupted or wrong-key journal must never be interpreted as an empty history. */
export async function readErasureJournal(context: ErasureJournalContext): Promise<ErasureIntent[]> {
  const directory = journalDirectory(context); const info = await lstat(directory);
  if (!info.isDirectory() || info.isSymbolicLink()) throw new Error('Invalid erasure directory');
  const names = (await readdir(directory)).filter(name => name.endsWith('.json')).sort();
  if (names.length === 0 || names.length > 100_000) throw new Error('Missing or oversized erasure journal');
  const entries: ErasureIntent[] = []; const requests = new Set<string>();
  for (const name of names) {
    if (!/^[a-f0-9]{64}\.json$/.test(name)) throw new Error('Invalid erasure filename');
    const path = join(directory, name); const file = await lstat(path);
    if (!file.isFile() || file.isSymbolicLink() || file.size > 4096) throw new Error('Invalid erasure file');
    const raw: unknown = JSON.parse(await readFile(path, 'utf8'));
    const parsed = signedSchema.parse(raw);
    if (name !== `${parsed.intent.accountHash}.json` || requests.has(parsed.intent.requestId)
      || !timingSafeEqual(signature(context.secret, parsed.intent), Buffer.from(parsed.signature, 'hex'))) throw new Error('Invalid erasure signature or identity');
    requests.add(parsed.intent.requestId); entries.push(parsed.intent);
  }
  return entries;
}

/** Maintenance restore only: revoke credentials and recreate approved requests, never delete worlds. */
export async function reapplyErasureJournal(db: Db, input: readonly ErasureIntent[], apply: boolean): Promise<{ matched: number; changed: number }> {
  const intents = new Map(z.array(intentSchema).parse(input).map(entry => [entry.accountHash, entry]));
  if (intents.size !== input.length) throw new Error('Duplicate erasure identity');
  return db.transaction(async tx => {
    const rows = await tx.select({ id: accounts.id }).from(accounts).orderBy(accounts.id);
    let matched = 0; let changed = 0;
    for (const row of rows) {
      const intent = intents.get(accountHash(row.id)); if (!intent) continue;
      matched++; if (!apply) continue;
      const [account] = await tx.select().from(accounts).where(eq(accounts.id, row.id)).for('update');
      if (!account) throw new Error('Account changed during restore');
      const [existing] = await tx.select().from(accountDeletionRequests).where(eq(accountDeletionRequests.accountId, account.id)).for('update');
      if (existing && existing.requestId !== intent.requestId) throw new Error('Conflicting deletion request; restore remains closed');
      if (account.deletionApprovedAt && existing?.approvedAt) continue;
      const approvedAt = new Date(intent.approvedAt);
      if (!existing) await tx.insert(accountDeletionRequests).values({ accountId: account.id, requestId: intent.requestId,
        requestedAt: new Date(intent.requestedAt), approvedAt, locale: intent.locale });
      else await tx.update(accountDeletionRequests).set({ approvedAt }).where(eq(accountDeletionRequests.accountId, account.id));
      await tx.update(accounts).set({ deletionApprovedAt: approvedAt, authVersion: account.authVersion + 1 }).where(eq(accounts.id, account.id));
      await tx.insert(adminActions).values({ action: 'ACCOUNT_DELETION_RESTORED', targetAccountId: account.id, details: { requestId: intent.requestId }, createdAt: new Date(intent.recordedAt) });
      changed++;
    }
    return { matched, changed };
  });
}

/** Keep pending accounts protected; completed-account markers outlive the entire backup horizon. */
export async function pruneErasureJournal(db: Db, context: ErasureJournalContext, now: Date): Promise<{ removed: number }> {
  // Once an account is absent, all its transactional journal writers have finished.
  // Reading this first avoids deleting a marker concurrently refreshed by completion.
  const live = new Set((await db.select({ id: accounts.id }).from(accounts)).map(row => accountHash(row.id)));
  let entries: ErasureIntent[];
  try {
    if (!(await readdir(journalDirectory(context))).some(name => name.endsWith('.json'))) return { removed: 0 };
    entries = await readErasureJournal(context);
  } catch (error) {
    if (error instanceof Error && 'code' in error && error.code === 'ENOENT') return { removed: 0 };
    throw error;
  }
  let removed = 0;
  for (const entry of entries) {
    if (live.has(entry.accountHash) || now.getTime() - Date.parse(entry.recordedAt) < 30 * 86_400_000) continue;
    await rm(join(journalDirectory(context), `${entry.accountHash}.json`), { force: true }); removed++;
  }
  return { removed };
}

