import { and, eq, inArray, isNotNull, isNull, ne, not, notInArray, or, sql } from 'drizzle-orm';
import { clanBayAvailable, flightSlots, hasFault, type FaultSet } from '@astera/rules';
import type { Queryable } from '../db/client.js';
import {
  clanSupportWaves,
  clanWarContributions,
  clanWarMissions,
  intergalacticConvoyRuns,
  miningRuns,
  missions,
  monumentWaves,
  pirateRaids,
  radiationBombFlights,
  tradeRuns,
  unknownSignals,
  planets,
  type ClanWarLeg,
} from '../db/schema.js';
import { GameError } from './planet.js';

/**
 * FLIGHT SLOTS — how much a planet may have in the air at once. D28.
 *
 * The rule lives in `@astera/rules`; this is the only place that counts what
 * is currently using it, and every launch path goes through `assertFreeBay`.
 *
 * WHY ONE HELPER AND NOT THREE COPIES. The count has to be taken under the planet
 * row lock or two launches racing each other both see a free bay — the same
 * failure the one-fleet-per-target check was written to avoid, and its comment
 * says so. Three copies of a concurrency-sensitive count is three chances to
 * forget the lock.
 */

/**
 * Which in-flight legs belong to THIS planet.
 *
 * A return leg is stored with its origin and target SWAPPED (`handlers.ts` builds
 * it that way so the craft flies back down the same line), so ownership cannot be
 * read off `originPlanetId` alone:
 *
 *   my attack, outbound     kind 'attack'  origin ME
 *   my attack, coming home  kind 'return'  target ME
 *   my probe, outbound      kind 'probe'   origin ME   parentMissionId NULL
 *   my probe, coming home   kind 'probe'   target ME   parentMissionId SET
 *
 * An enemy raid inbound at me is `kind 'attack'` with target ME, and their fleet
 * flying home afterwards is `kind 'return'` with origin ME — both of which look
 * like mine if you match on either column alone. So: **an outbound leg belongs to
 * its origin, a return leg belongs to its target**, and a return leg is one whose
 * kind is `return` or which carries a parent.
 *
 * This also quietly fixes a real bug in the probe cap it replaces, which matched
 * `origin OR target` and therefore let somebody else's probe consume one of my
 * three scouting slots.
 */
const isReturnLeg = or(eq(missions.kind, 'return'), isNotNull(missions.parentMissionId));
const isOutboundLeg = and(ne(missions.kind, 'return'), isNull(missions.parentMissionId));

/**
 * A JOINT WAR LEG IS COUNTED BY ITS CONTRIBUTION, NOT BY ITS MISSIONS.
 *
 * One contributed wave flies up to three legs — out to the staging world, in with
 * the combined strike, home again — and each of those is a `missions` row. Counted
 * generically that is a wave taking two or three bays at once, and a wave WAITING
 * at the staging world taking none at all, which would let a commander park a
 * fleet abroad and launch a fresh raid out of the empty bay it left behind.
 *
 * So joint-war missions are excluded here and the CONTRIBUTION is counted below:
 * one bay at the origin world, held from the moment the wave leaves until it is
 * `HOME` or `LOST`, which is exactly the D28 rule stated about the right object.
 */
const isClanWarLeg = sql`EXISTS (
  SELECT 1 FROM ${clanWarMissions} WHERE ${clanWarMissions.missionId} = ${missions.id}
)`;

const minesOf = (planetId: string) =>
  and(
    eq(missions.status, 'in_flight'),
    // Probes are paid intelligence packets paced per target, not fleet squadrons.
    // They remain visible and pending, but never consume an ordinary flight bay.
    ne(missions.kind, 'probe'),
    not(isClanWarLeg),
    // A clan support wave is counted once, by its own row below, for its whole life.
    ne(missions.kind, 'clan_support'),
    or(
      and(isOutboundLeg, eq(missions.originPlanetId, planetId)),
      and(isReturnLeg, eq(missions.targetPlanetId, planetId)),
    ),
  );

/**
 * THE RULE ITSELF, IN ONE PLACE, FOR CODE THAT HOLDS A ROW RATHER THAN A QUERY.
 *
 * The SQL below and this predicate are the same sentence said twice because they
 * are asked in two different places — a `WHERE` clause cannot be applied to a row
 * already in memory, and a JavaScript filter cannot be pushed into a count. What
 * must never happen again is a THIRD statement of it written from scratch, which
 * is exactly what `pendingThreads` had: it matched `origin OR target` and then
 * special-cased only an inbound attack, so every other foreign leg standing at one
 * end of your world — a probe flying at you, a probe flying home from you, a
 * raider's survivors leaving your orbit — was handed to you as YOUR OWN craft,
 * with its route, its composition and the other world's NAME on it.
 *
 * That was a duplicate and a leak at the same time: the same mission was drawn
 * once out of `pending` as your fleet and once out of `traffic` as an anonymous
 * contact, in two different places, on the same disc.
 *
 * `traffic.ts` reads this too, so the three surfaces that have to agree about
 * whose craft something is — the bay count, the public contact list and your own
 * pending list — now agree by construction.
 */
type Leg = Pick<
  typeof missions.$inferSelect,
  'kind' | 'parentMissionId' | 'originPlanetId' | 'targetPlanetId'
>;

export const legBelongsTo = (mission: Leg, planetId: string): boolean =>
  mission.kind === 'return' || mission.parentMissionId !== null
    ? mission.targetPlanetId === planetId
    : mission.originPlanetId === planetId;

/**
 * Whether this exact flight leg is an attack aimed at its target.
 *
 * A joint-war mission kind names four physically different legs, so `kind` alone
 * cannot answer this question. Only the aggregate strike is hostile; support and
 * both return legs remain ordinary traffic. Keeping that distinction here makes
 * traffic intent, the defender's pending strip and the scheduled warning agree.
 *
 * A RAID THAT TURNED (K8) IS NOT AIMED AT ANYTHING ANY MORE. It is flying home, so
 * the defender's strip drops it, its scheduled warning stays silent and the galaxy
 * draws it as ordinary traffic — like a return leg, which is what it has become.
 */
export const isHostileMission = (
  mission: Pick<typeof missions.$inferSelect, 'kind' | 'parentMissionId' | 'recalledAt'>,
  clanWarLeg: ClanWarLeg | null = null,
): boolean => mission.parentMissionId === null && mission.recalledAt === null && (
  mission.kind === 'attack'
  || mission.kind === 'death_star'
  || (mission.kind === 'clan_war' && clanWarLeg === 'COMBINED_ATTACK')
);

/**
 * One statement counts every flight lane without eight database round trips.
 * A run/wave consumes one bay regardless of craft count. Physical clan waves
 * keep their bay until home/lost; leader-capital contributions never depart.
 * Monument fragments share their root's bay until the last fragment returns.
 */
export async function baysInUse(tx: Queryable, planetId: string): Promise<number> {
  const bombs = tx.select({ n: sql<number>`count(*)::int` }).from(radiationBombFlights)
    .where(and(eq(radiationBombFlights.originPlanetId, planetId), eq(radiationBombFlights.status, 'OUTBOUND')));
  const flights = tx
    .select({ n: sql<number>`count(*)::int` })
    .from(missions)
    .where(minesOf(planetId));
  const mining = tx
    .select({ n: sql<number>`count(*)::int` })
    .from(miningRuns)
    .where(
      and(eq(miningRuns.planetId, planetId), inArray(miningRuns.status, ['outbound', 'returning'])),
    );
  const pirate = tx
    .select({ n: sql<number>`count(*)::int` })
    .from(pirateRaids)
    .where(
      and(
        eq(pirateRaids.planetId, planetId),
        inArray(pirateRaids.status, ['outbound', 'returning']),
      ),
    );
  const trade = tx
    .select({ n: sql<number>`count(*)::int` })
    .from(tradeRuns)
    .where(
      and(eq(tradeRuns.planetId, planetId), inArray(tradeRuns.status, ['outbound', 'returning'])),
    );
  const convoy = tx
    .select({ n: sql<number>`count(*)::int` })
    .from(intergalacticConvoyRuns)
    .where(
      and(
        eq(intergalacticConvoyRuns.planetId, planetId),
        inArray(intergalacticConvoyRuns.status, ['outbound', 'returning']),
      ),
    );
  const contributed = tx
    .select({ n: sql<number>`count(*)::int` })
    .from(clanWarContributions)
    .where(and(
      eq(clanWarContributions.originPlanetId, planetId),
      eq(clanWarContributions.sourceKind, 'PHYSICAL'),
      notInArray(clanWarContributions.status, ['HOME', 'LOST', 'TRANSFERRED']),
    ));
  const supporting = tx
    .select({ n: sql<number>`count(*)::int` })
    .from(clanSupportWaves)
    .where(and(
      eq(clanSupportWaves.originPlanetId, planetId),
      notInArray(clanSupportWaves.status, ['HOME', 'LOST']),
    ));
  const monument = tx.select({
    n: sql<number>`count(distinct coalesce(${monumentWaves.rootWaveId}, ${monumentWaves.id}))::int`,
  }).from(monumentWaves).where(and(
    eq(monumentWaves.originPlanetId, planetId),
    notInArray(monumentWaves.status, ['HOME', 'LOST']),
  ));
  const signals = tx.select({ n: sql<number>`count(*)::int` }).from(unknownSignals)
    .innerJoin(planets, eq(planets.id, planetId))
    .where(and(eq(planets.controllerPlayerId, unknownSignals.playerId),
      inArray(unknownSignals.status, ['outbound', 'returning', 'recalled']),
      or(eq(unknownSignals.originPlanetId, planetId), and(eq(planets.kind, 'CAPITAL'),
        sql`not exists (select 1 from planets p where p.id = ${unknownSignals.originPlanetId} and p.player_id = ${unknownSignals.playerId})`))));
  const [row] = await tx.execute<{ used: number }>(sql`select ((${flights}) + (${mining}) + (${pirate}) + (${trade}) + (${convoy}) + (${contributed}) + (${supporting}) + (${monument}) + (${bombs}) + (${signals}))::int as used`);
  return row?.used ?? 0;
}

export interface BayCount {
  used: number;
  total: number;
}

export const baysOf = async (tx: Queryable, planetId: string, coreLevel: number): Promise<BayCount> => ({
  used: await baysInUse(tx, planetId),
  total: flightSlots(coreLevel),
});

/**
 * Refuse a launch that has nowhere to launch from.
 *
 * MUST be called inside the transaction that holds the planet row lock. Every
 * caller already has one — `loadLocked` takes it — so this asks for the `tx`
 * rather than a `Db` to make using it outside a transaction awkward.
 */
export async function assertFreeBay(
  tx: Queryable,
  planetId: string,
  coreLevel: number,
  faults: FaultSet,
): Promise<void> {
  assertDeparturesAllowed(planetId, faults);
  const { used, total } = await baysOf(tx, planetId, coreLevel);
  if (used >= total) {
    throw new GameError(
      'NO_FREE_BAY',
      `All ${String(total)} flight bays are in use. Something has to land first.`,
      409,
      { total },
    );
  }
}

/** D114's one extra seat, available only to a mission that remains clan aid. */
export async function assertFreeClanAidBay(
  tx: Queryable,
  planetId: string,
  coreLevel: number,
  faults: FaultSet,
): Promise<void> {
  assertDeparturesAllowed(planetId, faults);
  const { used, total } = await baysOf(tx, planetId, coreLevel);
  if (!clanBayAvailable(total, used, true)) {
    throw new GameError(
      'NO_FREE_CLAN_AID_BAY',
      'All ordinary and clan-aid flight bays are in use',
      409,
      { total: total + 1 },
    );
  }
}

/**
 * TERSANEDE İSYAN: NOTHING LEAVES. Koloni arızaları, `SHIPYARD_REVOLT`.
 *
 * THE ONE CHOKEPOINT, and that is why it lives here rather than in thirteen routes.
 * Every departure in the game — a raid, a transfer, a settlement, a trade convoy, a
 * pirate run, an intergalactic convoy, a mining launch, a salvage run, a strategic
 * weapon, clan aid — reserves a flight bay immediately before it commits, and the two
 * `assert…Bay` functions are the only way that reservation is made. A lane added
 * tomorrow inherits this rule by taking a bay, which is the only guarantee that scales.
 *
 * `faults` IS A REQUIRED ARGUMENT AND DELIBERATELY NOT A QUERY. Every caller already
 * holds a `LockedPlanet`, read under the lock it is about to commit inside; re-reading
 * the fault rows here would be a second snapshot of the same fact, thirteen times
 * over, on the hot path of every launch in the game. Required rather than defaulted so
 * a new lane cannot silently opt out — the compiler visits every call site, which is
 * the only reliable way to visit them all.
 *
 * WHAT IT DOES NOT STOP: landing, returning, and the probe. A fleet already in the air
 * comes home — the revolt is in the yard, not in the sky — and a probe neither takes a
 * bay nor is built here. Leaving the intel layer running is deliberate: a fault that
 * blinded AND grounded a commander would leave them nothing to do but wait.
 */
export function assertDeparturesAllowed(planetId: string, faults: FaultSet): void {
  if (!hasFault(faults, 'SHIPYARD_REVOLT')) return;
  throw new GameError(
    'FAULT_SHIPYARD',
    'The yard is in revolt. Nothing launches from this world until it is put right.',
    409,
    { planetId },
  );
}

