import { createHmac } from 'node:crypto';
import { and, asc, desc, eq, gt, gte, inArray, isNotNull, isNull, lt, lte, or } from 'drizzle-orm';
import {
  MULTI_WORLD,
  galaxyEventConfigForRuleset,
  galaxyEventKindsForRuleset,
  generateGalaxyEventSchedule,
  plannedEffectFor,
  plannedEndAtFor,
  type GalaxyEventKind,
  type IntergalacticConvoyEffect,
  type IntergalacticConvoySpec,
  type OrbitElements,
  type PlannedGalaxyEvent,
  type TradeRate,
  type TradeShipSpec,
} from '@astera/rules';
import { z } from 'zod';
import type { Clock } from '../clock.js';
import { addMinutes, minutesSince } from '../clock.js';
import type { Db, Queryable, Tx } from '../db/client.js';
import {
  galaxyEventOccurrences,
  asteroidSpawnHours,
  notifications,
  players,
  scheduledEvents,
  seasons,
  type GalaxyEventLifecyclePayload,
} from '../db/schema.js';
import { publishShard } from '../stream/bus.js';
import { recordGalaxyEvent } from './chronicle.js';
import { HOUR_MS, floorHour, scheduleAsteroidHour } from './asteroidSpawn.js';
import { tradeShipOf } from './tradeField.js';
import { intergalacticConvoyOf } from './intergalacticConvoyField.js';
import { GameError } from './planet.js';

const showerEffectSchema = z.object({
  asteroidSpawnMultiplier: z.number().finite().gt(1),
}).strict();

const tradeRateSchema = z.object({
  alloy: z.number().finite().positive(),
  crystal: z.number().finite().positive(),
  deuterium: z.number().finite().positive(),
}).strict();

const tradeEffectSchema = z.object({ rate: tradeRateSchema }).strict();

const convoyEffectSchema = z.object({
  routeVersion: z.literal(1),
  formationVersion: z.literal(1),
  // Read immutable v1 occurrences, D204's two-hour snapshots and 2026-09-16's four.
  resourceCapHours: z.union([z.literal(1), z.literal(2), z.literal(4)]),
  fullRewardForceRatio: z.literal(1),
  shipDropFullFirepower: z.number().finite().positive(),
  shipDropChanceAtFullQuality: z.number().finite().min(0).max(1),
  shipCountWeights: z.tuple([
    z.number().finite().min(0).max(1),
    z.number().finite().min(0).max(1),
    z.number().finite().min(0).max(1),
  ]).refine((weights) => Math.abs(weights.reduce((sum, weight) => sum + weight, 0) - 1) <= 1e-9),
  shipTierWeights: z.tuple([
    z.number().finite().min(0).max(1),
    z.number().finite().min(0).max(1),
    z.number().finite().min(0).max(1),
    z.number().finite().min(0).max(1),
  ]).refine((weights) => Math.abs(weights.reduce((sum, weight) => sum + weight, 0) - 1) <= 1e-9),
  rewardPoolVersion: z.literal(1),
}).strict();

/**
 * THE PERSISTED `kind` COLUMN IS THE DISCRIMINATOR, BECAUSE THE JSONB HAS NONE.
 *
 * This used to be one flat object schema and four call sites that read
 * `.asteroidSpawnMultiplier` off it unconditionally — `activeGalaxyEvents`,
 * `notifySeason`, `processGalaxyEventLifecycle` and
 * `notifyActiveGalaxyEventsForPlayer`. The first TRADE_SHIP occurrence in any
 * season would have thrown in all four, and one of those runs inside the worker:
 * a lifecycle handler that raises stops the event queue, which is D47's outage —
 * no fleet in the galaxy lands again and `/health` still says ok.
 *
 * Pairing the column with the payload and discriminating on it also refuses a row
 * whose effect does not match its kind, which a bare `z.union` of two `.strict()`
 * objects would have quietly accepted in the wrong lane if the shapes ever
 * converged.
 */
const effectSchema = z.discriminatedUnion('kind', [
  z.object({ kind: z.literal('ASTEROID_SHOWER'), effect: showerEffectSchema }).strict(),
  z.object({ kind: z.literal('TRADE_SHIP'), effect: tradeEffectSchema }).strict(),
  z.object({ kind: z.literal('INTERGALACTIC_CONVOY'), effect: convoyEffectSchema }).strict(),
]);

type OccurrenceEffect = z.infer<typeof effectSchema>;

/** Parse one persisted row into its kind-tagged effect. The only reader of `effect`. */
const occurrenceEffect = (
  row: { kind: GalaxyEventKind; effect: unknown },
): OccurrenceEffect => effectSchema.parse({ kind: row.kind, effect: row.effect });

/**
 * ONE HMAC STREAM PER KIND, AND THE SHOWER'S LABEL IS FROZEN.
 *
 * A season's calendar is dealt once at creation and persisted, so a change that
 * re-deals it fails nowhere — every future season would just quietly be a
 * different season, and the Asteroid Shower has been live since D149. Its label
 * therefore stays `galaxy-events:v1:<n>` byte for byte; the merchant gets its own
 * namespace, which cannot collide because `trade-ship` is not a number.
 */
const CALENDAR_LABEL: Record<GalaxyEventKind, string> = {
  ASTEROID_SHOWER: 'galaxy-events:v1',
  TRADE_SHIP: 'galaxy-events:trade-ship:v1',
  INTERGALACTIC_CONVOY: 'galaxy-events:intergalactic-convoy:v1',
};

function calendarRng(asteroidKey: string, kind: GalaxyEventKind): () => number {
  let counter = 0;
  const label = CALENDAR_LABEL[kind];
  return () => {
    const digest = createHmac('sha256', asteroidKey)
      .update(`${label}:${String(counter)}`)
      .digest();
    counter += 1;
    return digest.readUInt32BE(0) / 0x1_0000_0000;
  };
}

/**
 * RESTAMP THE EFFECTS OF WINDOWS THAT HAVE NOT OPENED YET. D178.
 *
 * An occurrence's effect is a SNAPSHOT frozen at deal time, which is what lets two
 * showers of one season legitimately be worth different numbers — and what means a
 * definition change reaches nothing already on the calendar. `seedGalaxyEventCalendar`
 * has exactly one caller, season creation, so nothing re-deals a live season on its
 * own. This is the operator's door onto that, and it has one rule.
 *
 * A WINDOW THAT HAS OPENED IS NEVER TOUCHED, and the reason is arithmetic rather
 * than caution. `withAsteroidShowerLanes` appends each shower's rocks after
 * everything already in the field, so a lane's size decides the INDEX of every rock
 * in every later lane. A rock's public id is an HMAC of its index, `asteroid_claims`
 * is keyed by it, and an in-flight `mining_runs.asteroid_index` resolves through it
 * — so resizing a lane whose rocks are in the sky would move a commander's claim,
 * and a drill already on its way, onto a different rock. Nothing would throw. A
 * window that has not opened owns no rocks yet, and resizing it moves only lanes
 * that own none either.
 *
 * The strict `>` is deliberate: an occurrence starting exactly now has opened.
 * A changed shower also has to retain its authored duration and own no already-planned
 * asteroid hour or processed lifecycle marker. A future 12:30 window may be frozen
 * by the 12:00 hour's plan; lifecycle work may finish before a delayed hour job.
 * Shape changes use `adoptLiveEventCalendar`, never an effect-only restamp.
 *
 * THE KIND IS AN ARGUMENT AND HAS NO DEFAULT. A calendar holds more than one lane
 * and their definitions move on their own schedules: `TRADE_SHIP` went to version
 * 2 at D166 with a SHAPE change, three windows a day becoming four. Sweeping every
 * kind would rewrite a merchant's rate and stamp today's version onto a window
 * dealt under the old one — a row that lies about itself, and a silent mid-season
 * change to what the merchant pays, from a command whose operator asked about
 * asteroids.
 *
 * It reads `plannedEffectFor`, the same statement the planner deals with, so the
 * restamped figure cannot drift from the dealt one.
 */
export async function restampFutureOccurrences(
  tx: Tx,
  input: { now: Date; seasonId?: string; kinds: readonly GalaxyEventKind[] },
): Promise<number> {
  if (input.kinds.length === 0) return 0;
  const rows = await tx
    .select({
      occurrence: galaxyEventOccurrences,
      rulesetVersion: seasons.rulesetVersion,
      dynamicFrom: seasons.asteroidDynamicFrom,
    })
    .from(galaxyEventOccurrences)
    .innerJoin(seasons, eq(seasons.id, galaxyEventOccurrences.seasonId))
    .where(and(
      gt(galaxyEventOccurrences.startsAt, input.now),
      inArray(galaxyEventOccurrences.kind, [...input.kinds]),
      ...(input.seasonId === undefined
        ? []
        : [eq(galaxyEventOccurrences.seasonId, input.seasonId)]),
    ))
    .for('update');

  let changed = 0;
  for (const joined of rows) {
    const row = joined.occurrence;
    const kind = row.kind;
    const config = galaxyEventConfigForRuleset(joined.rulesetVersion);
    const incompatible = () => new Error(
      `Cannot restamp ${kind} at ${row.startsAt.toISOString()}: stored window differs from ` +
      'its authored shape, its asteroid hour is already frozen, or its lifecycle was already processed. Use adopt-event-calendar.',
    );
    if (kind === 'ASTEROID_SHOWER') {
      let expectedEnd: number;
      try {
        expectedEnd = Math.round(plannedEndAtFor(kind, row.startsAt.getTime() / 60_000, config) * 60_000);
      } catch (error) {
        if (error instanceof RangeError) throw incompatible();
        throw error;
      }
      if (row.endsAt.getTime() !== expectedEnd) throw incompatible();
    }
    const wanted = plannedEffectFor(kind, row.startsAt.getTime() / 60_000, config);
    const version = config.definitions[kind].version;
    if (JSON.stringify(row.effect) === JSON.stringify(wanted)
      && row.definitionVersion === version) {
      continue;
    }
    if (kind === 'ASTEROID_SHOWER'
      && (row.startProcessedAt !== null || row.endProcessedAt !== null)) {
      throw incompatible();
    }
    // FOR UPDATE above also locks the joined season, excluding the hour worker's
    // FOR SHARE. A 12:30 window may still be pending inside an already-planned 12:00 hour.
    if (kind === 'ASTEROID_SHOWER' && joined.dynamicFrom !== null) {
      const [frozenHour] = await tx.select({ at: asteroidSpawnHours.hourStartsAt })
        .from(asteroidSpawnHours).where(and(
          eq(asteroidSpawnHours.seasonId, row.seasonId),
          gte(asteroidSpawnHours.hourStartsAt, floorHour(row.startsAt)),
          lt(asteroidSpawnHours.hourStartsAt, row.endsAt),
        )).limit(1);
      if (frozenHour) throw incompatible();
    }
    await tx
      .update(galaxyEventOccurrences)
      .set({ effect: wanted, definitionVersion: version })
      .where(eq(galaxyEventOccurrences.id, row.id));
    changed += 1;
  }
  return changed;
}

/**
 * Append fixed windows added after a live season's calendar was dealt.
 *
 * Existing rows are never renumbered. Asteroid lanes allocate public ids in
 * sequence order, so every inserted row receives a sequence after the current
 * maximum even when its clock time is earlier than a previously dealt future
 * window. This preserves every existing asteroid id while allowing a newly
 * authored window that is currently active to begin on the next worker tick.
 */
export async function syncMissingFixedOccurrences(
  tx: Tx,
  input: { now: Date; seasonId?: string; kinds: readonly GalaxyEventKind[] },
): Promise<number> {
  if (input.kinds.length === 0) return 0;
  const live = await tx
    .select({
      id: seasons.id,
      startsAt: seasons.startsAt,
      endsAt: seasons.endsAt,
      rulesetVersion: seasons.rulesetVersion,
    })
    .from(seasons)
    .where(and(
      eq(seasons.status, 'live'),
      ...(input.seasonId === undefined ? [] : [eq(seasons.id, input.seasonId)]),
    ))
    .for('update');

  let insertedCount = 0;
  for (const season of live) {
    const config = galaxyEventConfigForRuleset(season.rulesetVersion);
    for (const kind of input.kinds) {
      if (config.definitions[kind].schedule !== 'FIXED_DAILY') {
        throw new RangeError(`${kind} does not use a fixed calendar in this season`);
      }
    }

    const existing = await tx
      .select()
      .from(galaxyEventOccurrences)
      .where(and(
        eq(galaxyEventOccurrences.seasonId, season.id),
        inArray(galaxyEventOccurrences.kind, [...input.kinds]),
      ));
    const existingStarts = new Set(existing.map((row) =>
      `${row.kind}:${row.startsAt.getTime()}`));
    let nextSequence = Math.max(-1, ...existing.map((row) => row.sequence)) + 1;
    const plan = generateGalaxyEventSchedule({
      seasonStartsAtUnixMinute: season.startsAt.getTime() / 60_000,
      seasonDurationMinutes: minutesSince(season.startsAt, season.endsAt),
      kinds: input.kinds,
      config,
      rngFor: (kind) => { throw new Error(`fixed kind ${kind} requested RNG`); },
    }).filter((event) => {
      const startsAt = addMinutes(season.startsAt, event.startsAtMinute);
      const endsAt = addMinutes(season.startsAt, event.endsAtMinute);
      return endsAt > input.now && !existingStarts.has(`${event.kind}:${startsAt.getTime()}`);
    });

    for (const event of plan) {
      const startsAt = addMinutes(season.startsAt, event.startsAtMinute);
      const endsAt = addMinutes(season.startsAt, event.endsAtMinute);
      const [inserted] = await tx
        .insert(galaxyEventOccurrences)
        .values({
          seasonId: season.id,
          sequence: nextSequence,
          kind: event.kind,
          definitionVersion: event.definitionVersion,
          startsAt,
          endsAt,
          effect: event.effect,
          createdAt: input.now,
        })
        .returning({ id: galaxyEventOccurrences.id });
      if (!inserted) throw new Error('Failed to append fixed galaxy-event occurrence');
      nextSequence += 1;
      insertedCount += 1;
      await tx.insert(scheduledEvents).values([
        {
          seasonId: season.id,
          kind: 'galaxy_event_start',
          refId: inserted.id,
          dedupeKey: `galaxy-event:start:${inserted.id}`,
          resolveAt: startsAt,
        },
        {
          seasonId: season.id,
          kind: 'galaxy_event_end',
          refId: inserted.id,
          dedupeKey: `galaxy-event:end:${inserted.id}`,
          resolveAt: endsAt,
        },
      ]);
    }
  }
  return insertedCount;
}

/** What adopting the current calendar did to one live season. */
export interface CalendarAdoptionReport {
  seasonId: string;
  /** The hour the new calendar and the dynamic asteroid field begin. */
  cutoverAt: Date;
  /** Whether this run froze the derived field's calendar (only ever the first run). */
  frozen: boolean;
  deleted: number;
  inserted: number;
}

/**
 * JSON WITH ITS OBJECT KEYS SORTED. `jsonb` does not keep the key order it was given,
 * so an effect read back from the database and the same effect built in memory
 * stringify differently; comparing them needs one order both can agree on.
 */
function canonicalJson(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(',')}]`;
  if (value !== null && typeof value === 'object') {
    return `{${Object.entries(value)
      .sort(([left], [right]) => (left < right ? -1 : left > right ? 1 : 0))
      .map(([key, inner]) => `${JSON.stringify(key)}:${canonicalJson(inner)}`)
      .join(',')}}`;
  }
  return JSON.stringify(value);
}

/** The lanes a live season re-deals when it adopts the current calendar. */
const ADOPTED_KINDS = ['ASTEROID_SHOWER', 'INTERGALACTIC_CONVOY'] as const;


/**
 * MOVE A LIVE SEASON ONTO THE CURRENT CALENDAR AND THE DYNAMIC ASTEROID FIELD, WITHOUT
 * A RESET. Owner instruction, 2026-09-16: *"productiondaki aktif sezon'a reset atmadan
 * deploy etmemiz lazım."*
 *
 * EVERYTHING HAPPENS AT ONE HOUR BOUNDARY — the next unplanned one, or the one a previous run
 * already chose. Hours and lifecycle boundaries committed while this command waited for its
 * season lock can push that boundary later. From that instant the showers and convoys are the current
 * weekday/weekend windows and its new rocks come from stored hours. Before it, nothing
 * moves: every window that has opened (or opens before the boundary) keeps its row,
 * and the merchant is not touched at all.
 *
 * THE DERIVED FIELD IS FROZEN FIRST, AND THAT IS THE WHOLE SAFETY ARGUMENT. The
 * derived field numbers its rocks lane by lane from the shower rows, so deleting a
 * future shower would renumber rocks that are in the sky right now — silently moving
 * claims and the craft flying at them onto other rocks. The rows are copied onto the
 * season before any is deleted, and the derived part of the field reads the copy.
 *
 * Idempotent: a second run finds every row from the boundary on already matching the
 * current definitions and changes nothing.
 */
export async function adoptLiveEventCalendar(
  tx: Tx,
  input: { now: Date; seasonId?: string },
): Promise<CalendarAdoptionReport[]> {
  const live = await tx.select().from(seasons).where(and(
    eq(seasons.status, 'live'),
    gt(seasons.endsAt, input.now),
    ...(input.seasonId === undefined ? [] : [eq(seasons.id, input.seasonId)]),
  )).for('update');

  const reports: CalendarAdoptionReport[] = [];
  for (const season of live) {
    if (season.rulesetVersion < MULTI_WORLD.fixedGalaxyEventScheduleRulesetVersion) continue;
    const nextHour = new Date(floorHour(input.now).getTime() + HOUR_MS);
    let cutoverAt = season.asteroidDynamicFrom !== null && season.asteroidDynamicFrom > input.now
      ? season.asteroidDynamicFrom
      : nextHour;

    // `now` was captured before taking the season lock. The worker may have crossed
    // its hour boundary while we waited; do not re-deal an hour it already committed.
    if (season.asteroidDynamicFrom !== null) {
      const [lastFrozen] = await tx.select({ at: asteroidSpawnHours.hourStartsAt })
        .from(asteroidSpawnHours).where(and(
          eq(asteroidSpawnHours.seasonId, season.id),
          gte(asteroidSpawnHours.hourStartsAt, cutoverAt),
        )).orderBy(desc(asteroidSpawnHours.hourStartsAt)).limit(1);
      if (lastFrozen) cutoverAt = new Date(lastFrozen.at.getTime() + HOUR_MS);
    }
    // Lifecycle fanout also locks the season. Preserve an announced start or end,
    // including an end delivered while a failed start still waits for retry.
    const [lastProcessed] = await tx.select({ at: galaxyEventOccurrences.startsAt })
      .from(galaxyEventOccurrences).where(and(
        eq(galaxyEventOccurrences.seasonId, season.id),
        inArray(galaxyEventOccurrences.kind, [...ADOPTED_KINDS]),
        gte(galaxyEventOccurrences.startsAt, cutoverAt),
        or(isNotNull(galaxyEventOccurrences.startProcessedAt), isNotNull(galaxyEventOccurrences.endProcessedAt)),
      )).orderBy(desc(galaxyEventOccurrences.startsAt)).limit(1);
    if (lastProcessed) cutoverAt = new Date(floorHour(lastProcessed.at).getTime() + HOUR_MS);

    let frozen = false;
    if (season.asteroidDynamicFrom === null) {
      const legacyCalendar = (await loadGalaxyEventSchedule(tx, season.id, season.startsAt))
        .filter((event) => event.kind === 'ASTEROID_SHOWER');
      await tx.update(seasons)
        .set({ asteroidDynamicFrom: cutoverAt, asteroidLegacyCalendar: legacyCalendar })
        .where(eq(seasons.id, season.id));
      await scheduleAsteroidHour(tx, { seasonId: season.id, hourStartsAt: cutoverAt });
      frozen = true;
    }

    const config = galaxyEventConfigForRuleset(season.rulesetVersion);
    const kinds = galaxyEventKindsForRuleset(season.rulesetVersion)
      .filter((kind) => (ADOPTED_KINDS as readonly GalaxyEventKind[]).includes(kind)
        && config.definitions[kind].schedule === 'FIXED_DAILY');
    const plan = kinds.length === 0 ? [] : generateGalaxyEventSchedule({
      seasonStartsAtUnixMinute: season.startsAt.getTime() / 60_000,
      seasonDurationMinutes: minutesSince(season.startsAt, season.endsAt),
      kinds,
      config,
      rngFor: (kind) => { throw new Error(`fixed kind ${kind} requested RNG`); },
    }).filter((event) => addMinutes(season.startsAt, event.startsAtMinute) >= cutoverAt);

    const existing = kinds.length === 0 ? [] : await tx.select().from(galaxyEventOccurrences)
      .where(and(
        eq(galaxyEventOccurrences.seasonId, season.id),
        inArray(galaxyEventOccurrences.kind, [...kinds]),
      ));
    const signature = (row: {
      kind: GalaxyEventKind; startsAt: Date; endsAt: Date; definitionVersion: number; effect: unknown;
    }) => [
      row.kind, row.startsAt.getTime(), row.endsAt.getTime(), row.definitionVersion,
      canonicalJson(row.effect),
    ].join('|');
    const wanted = new Map(plan.map((event) => {
      const row = {
        kind: event.kind,
        startsAt: addMinutes(season.startsAt, event.startsAtMinute),
        endsAt: addMinutes(season.startsAt, event.endsAtMinute),
        definitionVersion: event.definitionVersion,
        effect: event.effect,
      };
      return [signature(row), row] as const;
    }));

    const stale = existing.filter((row) => row.startsAt >= cutoverAt && !wanted.has(signature(row)));
    const kept = new Set(existing
      .filter((row) => row.startsAt >= cutoverAt && wanted.has(signature(row)))
      .map(signature));
    if (stale.length > 0) {
      const staleIds = stale.map((row) => row.id);
      await tx.delete(scheduledEvents).where(inArray(scheduledEvents.refId, staleIds));
      await tx.delete(galaxyEventOccurrences).where(inArray(galaxyEventOccurrences.id, staleIds));
    }

    const nextSequence = new Map(kinds.map((kind) => [
      kind,
      Math.max(-1, ...existing.filter((row) => row.kind === kind).map((row) => row.sequence)) + 1,
    ]));
    let inserted = 0;
    for (const [key, row] of wanted) {
      if (kept.has(key)) continue;
      const sequence = nextSequence.get(row.kind) ?? 0;
      nextSequence.set(row.kind, sequence + 1);
      const [created] = await tx.insert(galaxyEventOccurrences).values({
        seasonId: season.id,
        sequence,
        kind: row.kind,
        definitionVersion: row.definitionVersion,
        startsAt: row.startsAt,
        endsAt: row.endsAt,
        effect: row.effect,
        createdAt: input.now,
      }).returning({ id: galaxyEventOccurrences.id });
      if (!created) throw new Error('Failed to insert an adopted galaxy-event occurrence');
      await tx.insert(scheduledEvents).values([
        {
          seasonId: season.id,
          kind: 'galaxy_event_start',
          refId: created.id,
          dedupeKey: `galaxy-event:start:${created.id}`,
          resolveAt: row.startsAt,
        },
        {
          seasonId: season.id,
          kind: 'galaxy_event_end',
          refId: created.id,
          dedupeKey: `galaxy-event:end:${created.id}`,
          resolveAt: row.endsAt,
        },
      ]);
      inserted += 1;
    }
    if (frozen || stale.length > 0 || inserted > 0) {
      await publishShard(tx, season.id, 'galaxy-event');
    }
    reports.push({ seasonId: season.id, cutoverAt, frozen, deleted: stale.length, inserted });
  }
  return reports;
}

/** Seed occurrences and their two queue moments in the season-creation transaction. */
export async function seedGalaxyEventCalendar(
  tx: Tx,
  season: typeof seasons.$inferSelect,
  initializedAt: Date = season.startsAt,
): Promise<void> {
  if (season.rulesetVersion < MULTI_WORLD.galaxyEventsRulesetVersion) return;
  const durationMinutes = minutesSince(season.startsAt, season.endsAt);
  /*
    ONE LANE PER RULESET BOUNDARY, AND THE OLDER SEASONS KEEP THEIR CALENDAR. D156.

    `generateGalaxyEventSchedule` is multi-kind, so this asks for a stream per kind
    rather than handing over one generator. A ruleset-4 season is entitled to the
    Asteroid Shower alone and is dealt exactly the calendar it has always been
    dealt — same kind, same stream, same HMAC sequence, byte for byte. The merchant
    is gated on its own boundary rather than on `galaxyEventsRulesetVersion`,
    because raising that to 5 would have stopped seeding showers for every
    ruleset-4 season still alive.

    `rngFor` is asked once per planned kind and memoised here anyway: a stream that
    was rebuilt mid-deal would restart at counter zero and re-deal what it had
    already dealt.
  */
  const config = galaxyEventConfigForRuleset(season.rulesetVersion);
  const kinds = galaxyEventKindsForRuleset(season.rulesetVersion);
  const streams = new Map<GalaxyEventKind, () => number>();
  const plan = generateGalaxyEventSchedule({
    seasonStartsAtUnixMinute: season.startsAt.getTime() / 60_000,
    seasonDurationMinutes: durationMinutes,
    rngFor: (kind) => {
      const existing = streams.get(kind);
      if (existing) return existing;
      const stream = calendarRng(season.asteroidKey, kind);
      streams.set(kind, stream);
      return stream;
    },
    kinds,
    config,
  });
  if (plan.length === 0) return;

  const inserted = await tx
    .insert(galaxyEventOccurrences)
    .values(plan.map((event) => ({
      seasonId: season.id,
      sequence: event.sequence,
      kind: event.kind,
      definitionVersion: event.definitionVersion,
      startsAt: addMinutes(season.startsAt, event.startsAtMinute),
      endsAt: addMinutes(season.startsAt, event.endsAtMinute),
      effect: event.effect,
      createdAt: initializedAt,
      startProcessedAt: addMinutes(season.startsAt, event.startsAtMinute) < initializedAt ? initializedAt : null,
      endProcessedAt: addMinutes(season.startsAt, event.endsAtMinute) <= initializedAt ? initializedAt : null,
    })))
    .returning({
      id: galaxyEventOccurrences.id,
      startsAt: galaxyEventOccurrences.startsAt,
      endsAt: galaxyEventOccurrences.endsAt,
    });

  const moments = inserted.flatMap((occurrence) => [
    {
      seasonId: season.id,
      kind: 'galaxy_event_start' as const,
      refId: occurrence.id,
      dedupeKey: `galaxy-event:start:${occurrence.id}`,
      resolveAt: occurrence.startsAt,
    },
    {
      seasonId: season.id,
      kind: 'galaxy_event_end' as const,
      refId: occurrence.id,
      dedupeKey: `galaxy-event:end:${occurrence.id}`,
      resolveAt: occurrence.endsAt,
    },
  ]).map((event) => ({
    ...event,
    // Keep the dedupe key even for past boundaries so restart repair cannot enqueue them.
    status: event.resolveAt < initializedAt ? 'done' as const : 'pending' as const,
  }));
  if (moments.length > 0) await tx.insert(scheduledEvents).values(moments);
}

/** Repair only missing queue rows for already-persisted live-season occurrences. */
export async function ensureGalaxyEventLifecycleEvents(db: Db): Promise<number> {
  const occurrences = await db
    .select({
      id: galaxyEventOccurrences.id,
      seasonId: galaxyEventOccurrences.seasonId,
      startsAt: galaxyEventOccurrences.startsAt,
      endsAt: galaxyEventOccurrences.endsAt,
    })
    .from(galaxyEventOccurrences)
    .innerJoin(seasons, eq(galaxyEventOccurrences.seasonId, seasons.id))
    .where(eq(seasons.status, 'live'));
  if (occurrences.length === 0) return 0;

  const inserted = await db
    .insert(scheduledEvents)
    .values(occurrences.flatMap((occurrence) => [
      {
        seasonId: occurrence.seasonId,
        kind: 'galaxy_event_start' as const,
        refId: occurrence.id,
        dedupeKey: `galaxy-event:start:${occurrence.id}`,
        resolveAt: occurrence.startsAt,
      },
      {
        seasonId: occurrence.seasonId,
        kind: 'galaxy_event_end' as const,
        refId: occurrence.id,
        dedupeKey: `galaxy-event:end:${occurrence.id}`,
        resolveAt: occurrence.endsAt,
      },
    ]))
    .onConflictDoNothing({ target: scheduledEvents.dedupeKey })
    .returning({ id: scheduledEvents.id });
  return inserted.length;
}

/** Immutable rules projection used only by the server-private asteroid field. */
export async function loadGalaxyEventSchedule(
  db: Queryable,
  seasonId: string,
  seasonStartsAt: Date,
): Promise<PlannedGalaxyEvent[]> {
  const rows = await db
    .select()
    .from(galaxyEventOccurrences)
    .where(eq(galaxyEventOccurrences.seasonId, seasonId))
    /*
      ORDERED BY KIND THEN SEQUENCE, SO THE ROW ORDER IS TOTAL.

      `sequence` alone stopped being a unique key the day a second lane arrived,
      and a tie the database is free to break either way would make
      `privateAsteroidFieldWithEvents`'s cache signature unstable for one
      unchanged calendar — a miss on every read rather than a wrong field, but the
      cache exists because generation is not free. The composed field itself is
      order-independent: `withAsteroidShowerLanes` filters and re-sorts the
      showers internally.
    */
    .orderBy(asc(galaxyEventOccurrences.kind), asc(galaxyEventOccurrences.sequence));
  return rows.map((row) => {
    const base = {
      sequence: row.sequence,
      startsAtMinute: minutesSince(seasonStartsAt, row.startsAt),
      endsAtMinute: minutesSince(seasonStartsAt, row.endsAt),
      definitionVersion: row.definitionVersion,
    };
    const parsed = occurrenceEffect(row);
    switch (parsed.kind) {
      case 'ASTEROID_SHOWER':
        return { ...base, kind: parsed.kind, effect: parsed.effect };
      case 'TRADE_SHIP':
        return { ...base, kind: parsed.kind, effect: parsed.effect };
      case 'INTERGALACTIC_CONVOY':
        return { ...base, kind: parsed.kind, effect: parsed.effect };
    }
  });
}

interface ActiveGalaxyEventBase {
  id: string;
  startsAt: Date;
  endsAt: Date;
}

/**
 * WHAT AN ACTIVE PUBLIC EVENT LOOKS LIKE ON THE WIRE. D149/D156.
 *
 * A discriminated union rather than a widened object, because the two kinds share
 * a clock and nothing else, and a client that had to guess which fields were
 * present would guess wrong exactly once.
 *
 * THE MERCHANT PUBLISHES ITS ORBIT, AND THAT IS CORRECT HERE AND ONLY HERE. A
 * pirate's orbital elements ARE its route, and D150 keeps them server-private
 * because a pirate is a private opportunity that sight is sold for. A trade ship
 * is an announced moment — fog hides pre-decision knowledge, never a public live
 * event — so the disc may draw the whole circle. `asteroidSchema` already
 * publishes exactly these six numbers for a discovered rock, and handing them over
 * is what lets the launch screen run the same shared `interceptOrbit` the server
 * runs: without it the sheet and the server would disagree about the meeting
 * minute, which is the one number a convoy is committed against.
 *
 * IT STAYS GATED TO THE OCCURRENCE THAT IS ACTIVE RIGHT NOW. The future calendar
 * never leaves the server, so no elements are derived for a merchant that has not
 * appeared and none survive one that has gone.
 */
export type ActiveGalaxyEventView =
  | (ActiveGalaxyEventBase & {
      kind: 'ASTEROID_SHOWER';
      asteroidSpawnMultiplier: number;
    })
  | (ActiveGalaxyEventBase & {
      kind: 'TRADE_SHIP';
      rate: TradeRate;
      /** Minutes since season start — the same clock `orbit` is evaluated on. */
      appearsAtMinute: number;
      expiresAtMinute: number;
      orbit: OrbitElements;
    })
  | (ActiveGalaxyEventBase & {
      kind: 'INTERGALACTIC_CONVOY';
      appearsAtMinute: number;
      expiresAtMinute: number;
      route: {
        from: { x: number; y: number; z: number };
        to: { x: number; y: number; z: number };
        velocity: { x: number; y: number; z: number };
        speed: number;
      };
      visual: { formationVersion: 1 };
      rewardPolicy: {
        resourceCapHours: number;
        fullRewardForceRatio: number;
        shipDropFullFirepower: number;
        shipDropChanceAtFullQuality: number;
        maxAwardedShips: number;
      };
    });

/**
 * Serialize changes to the season's notification audience with lifecycle fanout.
 * Membership changes share the row; a lifecycle transition takes it exclusively.
 */
export async function lockGalaxyEventAudience(
  tx: Tx,
  seasonId: string,
  purpose: 'membership' | 'lifecycle',
): Promise<void> {
  const [season] = await tx
    .select({ id: seasons.id })
    .from(seasons)
    .where(eq(seasons.id, seasonId))
    .for(purpose === 'membership' ? 'share' : 'update');
  if (!season) throw new GameError('SEASON_NOT_FOUND', 'No such season', 404);
}

/** Existing NPC contacts are retired at the explicit idle cutover; future windows stay scheduled. */
function retiredMerchant(
  occurrence: Pick<typeof galaxyEventOccurrences.$inferSelect, 'kind' | 'startsAt'>,
  tempoStartsAt: Date | null,
  seasonStartsAt: Date,
): boolean {
  return occurrence.kind === 'TRADE_SHIP' && tempoStartsAt !== null
    && tempoStartsAt > seasonStartsAt && occurrence.startsAt <= tempoStartsAt;
}

/** Authenticated, active-only surface. Future occurrence timestamps never leave the server. */
export async function activeGalaxyEvents(
  db: Db,
  accountId: string,
  clock: Clock,
): Promise<ActiveGalaxyEventView[]> {
  const [me] = await db
    .select({
      seasonId: players.seasonId,
      seasonStartsAt: seasons.startsAt,
      asteroidKey: seasons.asteroidKey,
      tempoStartsAt: seasons.tempoStartsAt,
    })
    .from(players)
    .innerJoin(seasons, eq(players.seasonId, seasons.id))
    .where(eq(players.accountId, accountId))
    .limit(1);
  if (!me) throw new GameError('NO_PLANET', 'Join a galaxy first', 404);
  const now = clock.now();
  const rows = await db
    .select()
    .from(galaxyEventOccurrences)
    .where(and(
      eq(galaxyEventOccurrences.seasonId, me.seasonId),
      lte(galaxyEventOccurrences.startsAt, now),
      gt(galaxyEventOccurrences.endsAt, now),
    ))
    .orderBy(
      asc(galaxyEventOccurrences.startsAt),
      asc(galaxyEventOccurrences.kind),
      asc(galaxyEventOccurrences.id),
    );

  return rows.filter(row => !retiredMerchant(row, me.tempoStartsAt, me.seasonStartsAt)).map((row): ActiveGalaxyEventView => {
    const base = { id: row.id, startsAt: row.startsAt, endsAt: row.endsAt };
    const parsed = occurrenceEffect(row);
    if (parsed.kind === 'ASTEROID_SHOWER') {
      return {
        ...base,
        kind: parsed.kind,
        asteroidSpawnMultiplier: parsed.effect.asteroidSpawnMultiplier,
      };
    }
    if (parsed.kind === 'INTERGALACTIC_CONVOY') {
      const startsAtMinute = minutesSince(me.seasonStartsAt, row.startsAt);
      const endsAtMinute = minutesSince(me.seasonStartsAt, row.endsAt);
      const spec = intergalacticConvoyOf(me.asteroidKey, {
        sequence: row.sequence,
        kind: parsed.kind,
        startsAtMinute,
        endsAtMinute,
        definitionVersion: row.definitionVersion,
        effect: parsed.effect,
      });
      return {
        ...base,
        kind: parsed.kind,
        appearsAtMinute: spec.appearsAt,
        expiresAtMinute: spec.expiresAt,
        route: { from: spec.from, to: spec.to, velocity: spec.velocity, speed: spec.speed },
        visual: { formationVersion: parsed.effect.formationVersion },
        rewardPolicy: {
          resourceCapHours: parsed.effect.resourceCapHours,
          fullRewardForceRatio: parsed.effect.fullRewardForceRatio,
          shipDropFullFirepower: parsed.effect.shipDropFullFirepower,
          shipDropChanceAtFullQuality: parsed.effect.shipDropChanceAtFullQuality,
          maxAwardedShips: parsed.effect.shipCountWeights.length,
        },
      };
    }
    /*
      The ship is derived from the same season secret and the same occurrence the
      server solves a rendezvous against, so the circle the client draws and the
      circle the server aims at are one object, not two that have to agree.
    */
    const spec = tradeShipOf(me.asteroidKey, {
      sequence: row.sequence,
      kind: parsed.kind,
      startsAtMinute: minutesSince(me.seasonStartsAt, row.startsAt),
      endsAtMinute: minutesSince(me.seasonStartsAt, row.endsAt),
      definitionVersion: row.definitionVersion,
      effect: parsed.effect,
    });
    return {
      ...base,
      kind: parsed.kind,
      rate: spec.rate,
      appearsAtMinute: spec.appearsAt,
      expiresAtMinute: spec.expiresAt,
      orbit: {
        radius: spec.radius,
        period: spec.period,
        phase: spec.phase,
        inclination: spec.inclination,
        ascendingNode: spec.ascendingNode,
        speed: spec.speed,
      },
    };
  });
}

/** Only the next public fixed-window start is disclosed; legacy random windows stay secret. */
export async function nextPublicGalaxyEvent(db: Db, accountId: string, clock: Clock) {
  const [me] = await db
    .select({
      seasonId: players.seasonId,
      rulesetVersion: seasons.rulesetVersion,
      seasonStatus: seasons.status,
    })
    .from(players)
    .innerJoin(seasons, eq(players.seasonId, seasons.id))
    .where(eq(players.accountId, accountId))
    .limit(1);
  if (!me) throw new GameError('NO_PLANET', 'Join a galaxy first', 404);
  if (me.seasonStatus !== 'live') return null;

  const kinds = galaxyEventKindsForRuleset(me.rulesetVersion);
  if (kinds.length === 0) return null;
  const definitions = galaxyEventConfigForRuleset(me.rulesetVersion).definitions;
  const fixedKinds = kinds.filter(
    (kind) => definitions[kind].schedule === 'FIXED_DAILY',
  );
  if (fixedKinds.length === 0) return null;

  const [next] = await db
    .select({ kind: galaxyEventOccurrences.kind, startsAt: galaxyEventOccurrences.startsAt })
    .from(galaxyEventOccurrences)
    .where(and(
      eq(galaxyEventOccurrences.seasonId, me.seasonId),
      gt(galaxyEventOccurrences.startsAt, clock.now()),
      inArray(galaxyEventOccurrences.kind, fixedKinds),
    ))
    .orderBy(asc(galaxyEventOccurrences.startsAt), asc(galaxyEventOccurrences.kind))
    .limit(1);
  return next ?? null;
}

/**
 * THE MERCHANT ONE OCCURRENCE ID NAMES, OR NULL. D156.
 *
 * The single door between "a client sent me a uuid" and "here is the ship the
 * server will solve a rendezvous against". It exists so `trade.ts` never has to
 * hold an opinion about how a calendar row becomes a ship: `occurrenceEffect` is
 * the only reader of the jsonb column and `tradeShipOf` the only generator, and
 * both stay behind this function.
 *
 * SCOPED TO THE CALLER'S OWN SEASON, which is a fog rule and not a tidiness one.
 * An id from another galaxy must be indistinguishable from an id that names
 * nothing — otherwise a probe of this route reports whether some other shard has a
 * merchant up right now.
 *
 * NULL COVERS EVERY "NOT THAT" — no such row, another season's row, a row that is
 * an Asteroid Shower. The caller turns all of them into one refusal, because from
 * the player's seat they are one fact: there is no merchant there.
 */
export async function tradeShipOccurrence(
  tx: Queryable,
  seasonId: string,
  occurrenceId: string,
): Promise<TradeShipSpec | null> {
  const [row] = await tx
    .select({
      occurrence: galaxyEventOccurrences,
      seasonStartsAt: seasons.startsAt,
      asteroidKey: seasons.asteroidKey,
      tempoStartsAt: seasons.tempoStartsAt,
    })
    .from(galaxyEventOccurrences)
    .innerJoin(seasons, eq(seasons.id, galaxyEventOccurrences.seasonId))
    .where(and(
      eq(galaxyEventOccurrences.id, occurrenceId),
      eq(galaxyEventOccurrences.seasonId, seasonId),
    ))
    .limit(1);
  if (!row) return null;
  const parsed = occurrenceEffect(row.occurrence);
  if (parsed.kind !== 'TRADE_SHIP') return null;
  if (retiredMerchant(row.occurrence, row.tempoStartsAt, row.seasonStartsAt)) return null;
  return tradeShipOf(row.asteroidKey, {
    sequence: row.occurrence.sequence,
    kind: parsed.kind,
    startsAtMinute: minutesSince(row.seasonStartsAt, row.occurrence.startsAt),
    endsAtMinute: minutesSince(row.seasonStartsAt, row.occurrence.endsAt),
    definitionVersion: row.occurrence.definitionVersion,
    effect: parsed.effect,
  });
}

export interface IntergalacticConvoyOccurrence {
  spec: IntergalacticConvoySpec;
  effect: IntergalacticConvoyEffect;
}

/** Active-window authority for one client-supplied convoy occurrence id. */
export async function intergalacticConvoyOccurrence(
  tx: Queryable,
  seasonId: string,
  occurrenceId: string,
): Promise<IntergalacticConvoyOccurrence | null> {
  const [row] = await tx
    .select({
      occurrence: galaxyEventOccurrences,
      seasonStartsAt: seasons.startsAt,
      asteroidKey: seasons.asteroidKey,
    })
    .from(galaxyEventOccurrences)
    .innerJoin(seasons, eq(seasons.id, galaxyEventOccurrences.seasonId))
    .where(and(
      eq(galaxyEventOccurrences.id, occurrenceId),
      eq(galaxyEventOccurrences.seasonId, seasonId),
    ))
    .limit(1);
  if (!row) return null;
  const parsed = occurrenceEffect(row.occurrence);
  if (parsed.kind !== 'INTERGALACTIC_CONVOY') return null;
  const spec = intergalacticConvoyOf(row.asteroidKey, {
    sequence: row.occurrence.sequence,
    kind: parsed.kind,
    startsAtMinute: minutesSince(row.seasonStartsAt, row.occurrence.startsAt),
    endsAtMinute: minutesSince(row.seasonStartsAt, row.occurrence.endsAt),
    definitionVersion: row.occurrence.definitionVersion,
    effect: parsed.effect,
  });
  return { spec, effect: parsed.effect };
}

type Lifecycle = 'start' | 'end';

/**
 * The one payload every lifecycle surface writes — notification and Chronicle.
 *
 * Built in one place so a third kind cannot be taught to two of the three readers
 * and quietly forgotten by the fourth, which is exactly the shape the bug in
 * `effectSchema` had.
 */
function lifecyclePayload(
  occurrence: typeof galaxyEventOccurrences.$inferSelect,
): GalaxyEventLifecyclePayload {
  const window = {
    startsAt: occurrence.startsAt.toISOString(),
    endsAt: occurrence.endsAt.toISOString(),
  };
  const parsed = occurrenceEffect(occurrence);
  if (parsed.kind === 'ASTEROID_SHOWER') {
    return {
        eventKind: parsed.kind,
        ...window,
        asteroidSpawnMultiplier: parsed.effect.asteroidSpawnMultiplier,
      };
  }
  if (parsed.kind === 'TRADE_SHIP') {
    return { eventKind: parsed.kind, ...window, rate: parsed.effect.rate };
  }
  return {
    eventKind: parsed.kind,
    ...window,
    resourceCapHours: parsed.effect.resourceCapHours,
    shipDropChanceAtFullQuality: parsed.effect.shipDropChanceAtFullQuality,
  };
}

async function claimLifecycle(
  tx: Tx,
  occurrenceId: string,
  seasonId: string,
  lifecycle: Lifecycle,
  processedAt: Date,
) {
  return lifecycle === 'start'
    ? (await tx
        .update(galaxyEventOccurrences)
        .set({ startProcessedAt: processedAt })
        .where(and(
          eq(galaxyEventOccurrences.id, occurrenceId),
          eq(galaxyEventOccurrences.seasonId, seasonId),
          isNull(galaxyEventOccurrences.startProcessedAt),
        ))
        .returning())[0]
    : (await tx
        .update(galaxyEventOccurrences)
        .set({ endProcessedAt: processedAt })
        .where(and(
          eq(galaxyEventOccurrences.id, occurrenceId),
          eq(galaxyEventOccurrences.seasonId, seasonId),
          isNull(galaxyEventOccurrences.endProcessedAt),
        ))
        .returning())[0];
}

/** One bulk INSERT and one shard invalidation, even with three hundred players. */
async function notifySeason(
  tx: Tx,
  occurrence: typeof galaxyEventOccurrences.$inferSelect,
  lifecycle: Lifecycle,
): Promise<void> {
  const audience = await tx
    .select({ id: players.id })
    .from(players)
    .where(eq(players.seasonId, occurrence.seasonId));
  if (audience.length === 0) return;
  const payload = lifecyclePayload(occurrence);
  await tx
    .insert(notifications)
    .values(audience.map(({ id }) => ({
      playerId: id,
      kind: lifecycle === 'start' ? 'galaxy_event_started' as const : 'galaxy_event_ended' as const,
      refId: occurrence.id,
      createdAt: lifecycle === 'start' ? occurrence.startsAt : occurrence.endsAt,
      payload,
    })))
    .onConflictDoNothing();
}

/** Idempotent lifecycle side effects; gameplay authority is the occurrence clock, not this worker. */
export async function processGalaxyEventLifecycle(
  db: Db,
  input: { occurrenceId: string; seasonId: string; lifecycle: Lifecycle; processedAt: Date },
): Promise<void> {
  await db.transaction(async (tx) => {
    await lockGalaxyEventAudience(tx, input.seasonId, 'lifecycle');
    const occurrence = await claimLifecycle(
      tx,
      input.occurrenceId,
      input.seasonId,
      input.lifecycle,
      input.processedAt,
    );
    if (!occurrence) return;
    if (occurrence.kind === 'TRADE_SHIP') {
      const [season] = await tx.select({ startsAt: seasons.startsAt, tempoStartsAt: seasons.tempoStartsAt })
        .from(seasons).where(eq(seasons.id, occurrence.seasonId));
      if (season && retiredMerchant(occurrence, season.tempoStartsAt, season.startsAt)) return;
    }
    await notifySeason(tx, occurrence, input.lifecycle);
    await recordGalaxyEvent(tx, {
      seasonId: occurrence.seasonId,
      kind: input.lifecycle === 'start' ? 'galaxy_event_started' : 'galaxy_event_ended',
      refId: occurrence.id,
      subjectPlanetId: null,
      payload: lifecyclePayload(occurrence),
      occurredAt: input.lifecycle === 'start' ? occurrence.startsAt : occurrence.endsAt,
    });
    await publishShard(tx, occurrence.seasonId, 'galaxy-event');
  });
}

/** Backfill only an event that is active at the exact join instant. */
export async function notifyActiveGalaxyEventsForPlayer(
  tx: Tx,
  input: { playerId: string; seasonId: string; at: Date },
): Promise<void> {
  const rows = await tx
    .select({ occurrence: galaxyEventOccurrences, tempoStartsAt: seasons.tempoStartsAt, seasonStartsAt: seasons.startsAt })
    .from(galaxyEventOccurrences)
    .innerJoin(seasons, eq(seasons.id, galaxyEventOccurrences.seasonId))
    .where(and(
      eq(galaxyEventOccurrences.seasonId, input.seasonId),
      lte(galaxyEventOccurrences.startsAt, input.at),
      gt(galaxyEventOccurrences.endsAt, input.at),
    ));
  const active = rows.filter(row => !retiredMerchant(row.occurrence, row.tempoStartsAt, row.seasonStartsAt));
  if (active.length === 0) return;
  await tx.insert(notifications).values(active.map(({ occurrence }) => ({
    playerId: input.playerId,
    kind: 'galaxy_event_started' as const,
    refId: occurrence.id,
    createdAt: occurrence.startsAt,
    payload: lifecyclePayload(occurrence),
  }))).onConflictDoNothing();
}

