import { and, desc, eq, exists, lte, or } from 'drizzle-orm';
import { isHonorCandidate, isSupportedHonorVersion, type HonorVersion } from '@astera/rules';
import type { Tx } from '../db/client.js';
import { honorSeasons, seasonCycles, seasons, shards } from '../db/schema.js';

/** Continue the announced main-galaxy program, never promote an invisible trial.
 * A same-cycle new galaxy can inherit the program, as can the next cycle. A race
 * hidden with a promise of the next season is announced, not a trial. */
async function latestHonorPrograms(tx: Tx, startsAt: Date) {
  const [latest] = await tx.select({ id: seasonCycles.id }).from(seasonCycles)
    .where(and(lte(seasonCycles.startsAt, startsAt), exists(tx.select({ id: seasons.id }).from(seasons)
      .innerJoin(shards, eq(shards.id, seasons.shardId))
      .where(and(eq(seasons.cycleId, seasonCycles.id), eq(shards.role, 'MAIN')))))).orderBy(desc(seasonCycles.ordinal)).limit(1);
  if (!latest) return [];
  return tx.select({ version: honorSeasons.version, benefitsVersion: honorSeasons.benefitsVersion }).from(honorSeasons)
    .innerJoin(seasons, eq(seasons.id, honorSeasons.seasonId)).innerJoin(shards, eq(shards.id, seasons.shardId))
    .where(and(eq(seasons.cycleId, latest.id), eq(shards.role, 'MAIN'),
      or(eq(honorSeasons.mode, 'ACTIVE'), eq(honorSeasons.successorAnnounced, true))));
}

export async function inheritedHonorProgram(tx: Tx, startsAt: Date): Promise<HonorVersion | undefined> {
  const configs = await latestHonorPrograms(tx, startsAt);
  const versions = [...new Set(configs.map(row => row.version))];
  if (versions.length === 0) return undefined;
  if (versions.length !== 1) throw new Error('Conflicting announced Honor programs require an explicit successor version');
  const version = versions[0]!;
  if (!isSupportedHonorVersion(version) || isHonorCandidate(version)) throw new Error('Unreleased Honor successor program');
  return version;
}

/** Only a program actually announced in the preceding main cycle can carry. */
export async function inheritedHonorBenefitsProgram(tx: Tx, startsAt: Date): Promise<1 | null> {
  const configs = await latestHonorPrograms(tx, startsAt);
  // Null is an unannounced program, not a second incompatible version. Opening
  // galaxies one at a time must not break the next cycle's atomic rollover.
  const versions = [...new Set(configs.flatMap(row => row.benefitsVersion === null ? [] : [row.benefitsVersion]))];
  if (versions.length === 0) return null;
  if (versions.length !== 1 || versions[0] !== 1) throw new Error('Conflicting announced Honor economic programs');
  return 1;
}

import { and, eq, inArray } from 'drizzle-orm';
import { HONOR_LAUNCH_VERSION, honorRadiationDamage, type Fleet, type HpDamageLots, type HpRadiationSource,
  type Segment, type TechLevels } from '@astera/rules';
import type { Tx } from '../db/client.js';
import { honorSeasons, hpRadiationSources, radiationBombFlights } from '../db/schema.js';
import { strategicHonorEvidence, strategicHonorIntent } from './honorStrategic.js';
import { deferHonor } from './honorDeferred.js';

/** Same pre-dose inventory and path as the health writer. Its persisted cursor
 * makes each interval unique; the journal caps positive return across the bomb. */
export async function recordRadiationHonor(tx: Tx, input: {
  seasonId: string; victim: string; slice: string; until: Date;
  fleet: Fleet; damage: HpDamageLots | null | undefined; tech: TechLevels;
  segments: readonly Segment[]; sources: readonly HpRadiationSource[];
}) {
  if (!input.sources.some(source => source.origin === 'BOMB')) return;
  const [config] = await tx.select().from(honorSeasons).where(eq(honorSeasons.seasonId, input.seasonId));
  if (config?.version !== HONOR_LAUNCH_VERSION) return;
  const harm = honorRadiationDamage({ ...input, catalogue: config.catalogue });
  if (harm.length === 0) return;
  const bombs = await tx.select({ sourceId: hpRadiationSources.id, flight: radiationBombFlights })
    .from(hpRadiationSources).innerJoin(radiationBombFlights, eq(radiationBombFlights.id, hpRadiationSources.bombFlightId))
    .where(and(eq(hpRadiationSources.seasonId, input.seasonId), inArray(hpRadiationSources.id, harm.map(row => row.id))));
  for (const damage of harm) {
    const bomb = bombs.find(row => row.sourceId === damage.id)?.flight;
    if (!bomb || bomb.ownerPlayerId === input.victim) continue;
    const ready = await strategicHonorIntent(tx, input.seasonId, `bomb:${bomb.id}`);
    if (!ready?.intent.defence.some(row => row.id === input.victim)) continue;
    // A deliberately selected owner keeps their frozen conditions. Newly arriving
    // voluntary holders/support do not retroactively become selected weak victims.
    const intent = ready.intent;
    const id = JSON.stringify(['bomb', bomb.id, input.victim, input.slice,
      input.segments[0]?.startMs, input.until.getTime()]);
    const evidence = strategicHonorEvidence(intent, id, new Date(input.until.getTime() - 1));
    evidence.attackKey = `bomb:${bomb.id}`;
    evidence.tacticalCap = { id: `bomb:${bomb.id}`, limit: 2_500_000 };
    evidence.tactical = [{ actor: bomb.ownerPlayerId, enemy: input.victim,
      base: 0, pressureFifths: 0, radiation: { armedMicros: damage.armedMicros, allMicros: damage.allMicros } }];
    deferHonor(tx, input.seasonId, evidence);
  }
}

import { and, asc, desc, eq, lte, notInArray, sql } from 'drizzle-orm';
import { coreTier, honorReferenceAt } from '@astera/rules';
import type { Queryable, Tx } from '../db/client.js';
import { accounts, botProfiles, buildings, honorObservations, honorSeasons, planets, players } from '../db/schema.js';
import { ownedHonorNavy } from './honorNavy.js';

/**
 * Call after ownership/production/loss mutations, in their transaction, with
 * the injected observation time. World locks precede sorted player locks.
 * Wealth refresh already holds the same player lock; no Honor journal lock is
 * taken, so recording inventory never acquires the ledger before gameplay.
 */
export async function observeHonorOwner(tx: Tx, playerId: string, at?: Date): Promise<void> {
  const [identity] = await tx.select({ seasonId: players.seasonId }).from(players).where(eq(players.id, playerId));
  if (!identity) return;
  const [config] = await tx.select().from(honorSeasons).where(eq(honorSeasons.seasonId, identity.seasonId));
  if (config?.closedAt !== null) return;
  if (!at) throw new Error('Honor inventory requires an injected observation time');
  const [locked] = await tx.select({ seasonId: players.seasonId }).from(players).where(eq(players.id, playerId)).for('update');
  if (locked?.seasonId !== identity.seasonId) throw new Error('Honor owner moved during observation');
  const [previous] = await tx.select().from(honorObservations).where(and(
    eq(honorObservations.seasonId, identity.seasonId), eq(honorObservations.playerId, playerId),
  )).orderBy(desc(honorObservations.at), desc(honorObservations.id)).limit(1);
  if (!Number.isSafeInteger(at.getTime())) throw new Error('Honor inventory requires a valid observation time');
  // This reads TODAY's inventory. A delayed worker or a transaction that lost the
  // player lock race stamps it no earlier than the newest row, never backdated.
  const floor = previous?.at ?? config.createdAt;
  const stamp = at < floor ? floor : at;
  const [navy, coreRows] = await Promise.all([
    ownedHonorNavy(tx, playerId, config),
    tx.select({ level: buildings.level }).from(buildings).innerJoin(planets, eq(buildings.planetId, planets.id))
      .where(and(eq(planets.controllerPlayerId, playerId), eq(buildings.type, 'CORE'))),
  ]);
  // units already includes anıt/support/dock escrow. Never add their manifests again.
  const tier = coreTier(Math.max(1, ...coreRows.map(row => row.level)));
  if (previous?.navy === navy && previous.coreTier === tier) return;
  await tx.insert(honorObservations).values({ seasonId: identity.seasonId, playerId, at: stamp, navy, coreTier: tier });
}

/** Historical reference at commitment, never today's navy applied to an older launch. */
export async function honorOwnerReference(db: Queryable, seasonId: string, playerId: string, at: Date, throughOrder?: number): Promise<{ navy: number; tier: number }> {
  const rows = await db.select().from(honorObservations).where(and(eq(honorObservations.seasonId, seasonId),
    eq(honorObservations.playerId, playerId), lte(honorObservations.at, at),
    ...(throughOrder === undefined ? [] : [lte(honorObservations.id, throughOrder)])))
    .orderBy(asc(honorObservations.at), asc(honorObservations.id));
  return honorReferenceAt(rows.map(row => ({ at: row.at.getTime(), order: row.id, navy: row.navy, coreTier: row.coreTier })), at.getTime());
}

/** One read snapshot, no new locks. Match Honor's season Core peak, including
 * current Core not yet journalled, but only for commanders still in this galaxy.
 * A neutral world, old resident, bot, admin or another galaxy cannot move it. */
export async function honorGalaxyTopTier(db: Queryable, seasonId: string, at: Date,
  adminUsernames: ReadonlySet<string>): Promise<number> {
  const [row] = await db.execute<{ tier: number; level: number }>(sql`
    WITH honor_contenders AS (
      SELECT ${players.id} FROM ${players}
      INNER JOIN ${accounts} ON ${accounts.id} = ${players.accountId}
      LEFT JOIN ${botProfiles} ON ${botProfiles.accountId} = ${players.accountId}
      WHERE ${players.seasonId} = ${seasonId} AND ${botProfiles.accountId} IS NULL
        AND ${adminUsernames.size > 0 ? notInArray(accounts.username, [...adminUsernames]) : sql`true`}
    )
    SELECT
      (SELECT coalesce(max(${honorObservations.coreTier}), 1)::int
       FROM ${honorObservations}
       INNER JOIN honor_contenders ON honor_contenders.id = ${honorObservations.playerId}
       WHERE ${honorObservations.seasonId} = ${seasonId}
         AND ${honorObservations.at} <= ${at.toISOString()}::timestamptz) AS tier,
      (SELECT coalesce(max(${buildings.level}), 1)::int
       FROM ${buildings}
       INNER JOIN ${planets} ON ${planets.id} = ${buildings.planetId}
       INNER JOIN honor_contenders ON honor_contenders.id = ${planets.controllerPlayerId}
       WHERE ${buildings.type} = 'CORE'
         AND ${planets.seasonId} = ${seasonId}) AS level
  `);
  if (!row) throw new Error('Missing Honor galaxy tier');
  return Math.max(row.tier, coreTier(Math.max(1, row.level)));
}

import { and, eq, gt, inArray, isNull, lte, or } from 'drizzle-orm';
import type { Queryable } from '../db/client.js';
import { accounts, botProfiles, clanAidCommitments, clanMemberships, players, seasons } from '../db/schema.js';

const RELATION_WINDOW = 7 * 86_400_000;

/** Read at commitment. Never accept client-supplied eligibility or relationship flags. */
export async function readHonorRelations(db: Queryable, input: {
  seasonId: string; attack: readonly string[]; defence: readonly string[];
  at: Date; adminUsernames: ReadonlySet<string>;
}): Promise<{ eligible: boolean; relations: { a: string; b: string; related: boolean }[] }> {
  const time = input.at.getTime();
  if (!Number.isSafeInteger(time) || time < 0) throw new Error('Invalid Honor relationship time');
  const attack = [...new Set(input.attack)].sort(), defence = [...new Set(input.defence)].sort();
  if (attack.length === 0 || attack.some(id => defence.includes(id))) throw new Error('Invalid Honor actor sides');
  const ids = [...new Set([...attack, ...defence])];
  const actors = await db.select({ id: players.id, accountId: players.accountId,
    username: accounts.username, bot: botProfiles.accountId }).from(players)
    .innerJoin(accounts, eq(accounts.id, players.accountId))
    .leftJoin(botProfiles, eq(botProfiles.accountId, players.accountId))
    .where(and(eq(players.seasonId, input.seasonId), inArray(players.id, ids)));
  if (actors.length !== ids.length) throw new Error('Missing or foreign-season Honor actor');
  const [season] = await db.select({ cycleId: seasons.cycleId }).from(seasons).where(eq(seasons.id, input.seasonId));
  if (!season) throw new Error('Missing Honor relationship season');
  // Player identities persist across Silent Space moves within the same cycle.
  // Their actual membership/aid rows prove the relationship, not their location now.
  const historySeasons = db.select({ id: seasons.id }).from(seasons).where(eq(seasons.cycleId, season.cycleId));
  const since = new Date(time - RELATION_WINDOW);
  const [memberships, aid] = await Promise.all([
    db.select().from(clanMemberships).where(and(inArray(clanMemberships.seasonId, historySeasons),
      inArray(clanMemberships.playerId, ids), lte(clanMemberships.joinedAt, input.at),
      or(isNull(clanMemberships.leftAt), gt(clanMemberships.leftAt, since)))),
    db.select({ sender: clanAidCommitments.senderPlayerId, recipient: clanAidCommitments.recipientPlayerId })
      .from(clanAidCommitments).where(and(inArray(clanAidCommitments.seasonId, historySeasons),
        inArray(clanAidCommitments.senderPlayerId, ids), inArray(clanAidCommitments.recipientPlayerId, ids),
        eq(clanAidCommitments.status, 'DELIVERED'), gt(clanAidCommitments.resolvedAt, since),
        lte(clanAidCommitments.resolvedAt, input.at))),
  ]);
  const eligible = defence.length > 0 && actors.every(row => row.bot === null && !input.adminUsernames.has(row.username))
    && new Set(actors.map(row => row.accountId)).size === actors.length;
  const relations = attack.flatMap(a => defence.map(b => {
    const recentClan = memberships.filter(row => row.playerId === a).some(left =>
      memberships.filter(row => row.playerId === b && row.clanId === left.clanId).some(right => {
        const start = Math.max(left.joinedAt.getTime(), right.joinedAt.getTime());
        const end = Math.min(left.leftAt?.getTime() ?? Infinity, right.leftAt?.getTime() ?? Infinity);
        // Half-open membership intervals; equal leave/join times are not shared membership.
        return start <= time && start < end && end > since.getTime();
      }));
    const directAid = aid.some(row => (row.sender === a && row.recipient === b) || (row.sender === b && row.recipient === a));
    return { a, b, related: recentClan || directAid };
  }));
  return { eligible, relations };
}

