import { and, asc, eq, gt, inArray, isNotNull, sql } from 'drizzle-orm';
import { z } from 'zod';
import {
  asteroidActive,
  claimOre,
  hasFault,
  interceptAsteroid,
  prospectorHold,
  prospectorReadyAt,
  prospectorAvailability,
  prospectorSpeed,
  prospectorReturnSpeed,
  PROSPECTOR,
  travelExact,
  DEBRIS,
  claimDebris,
  collectorCap,
  debrisAlive,
  debrisRemaining,
  deuteriumCollectorCap,
  deuteriumRate,
  productionMult,
  alloyRate,
  crystalRate,
  distance,
  surfaceStandoff,
  visualLeg,
  worldRadius,
  type AsteroidSpec,
  type SatelliteSet,
  type Vec3,
  orbitDiscoveredAt,
  type FaultSet,
} from '@astera/rules';
import { addMinutes, atMinute, minutesSince, type Clock } from '../clock.js';
import type { Db, Queryable, Tx } from '../db/client.js';
import { asteroidClaims, debrisFields, miningRuns, planets, seasons, units } from '../db/schema.js';
import { applySpawnGate } from './spawnGateRead.js';
import { assertFreeBay } from './flight.js';
import { takeHomeHealth } from './homeHealth.js';
import { landHpShips } from './shipDamage.js';
import {
  assertSeasonOpenThrough,
  assertWorldOperational,
  buildingLevelsOf,
  GameError,
  loadLocked,
  lockSeason,
  orbitOf,
  saveResources,
  setUnits,
  type LockedPlanet,
} from './planet.js';
import {
  asteroidId,
  asteroidIndexFromId,
  composeSeasonAsteroidField,
  projectPlayerAsteroidField,
} from './asteroidField.js';
import { FIELD_LOOKBACK_HOURS, HOUR_MS, floorHour, loadAsteroidHours } from './asteroidSpawn.js';
import { loadGalaxyEventSchedule } from './galaxyEvents.js';
import { sensorHistoryForPlayer } from './sensorHistory.js';
import { notify } from './notifications.js';
import { schedule } from '../worker/queue.js';
import { publish, publishShard } from '../stream/bus.js';
import { hasResearch, techOf } from './researchState.js';
import type { TechLevels } from '@astera/rules';
import { publicPlanetIdentity, recordGalaxyEvent } from './chronicle.js';
import { pendingThreads, type PendingThread } from './session.js';
import { loadPlanetViewData, buildPlanetResult, type PlanetView } from './planetView.js';
import { assertOutsideSilentSpace } from './waitingRoom.js';

/**
 * MINING — D19.
 *
 * A Prospector flies to the place a passing rock WILL BE, takes what its hold can
 * carry, and comes home. Everything about the field is derived from the season
 * seed; the only stored facts are how much ore has already been taken out of each
 * rock and which craft are currently out.
 *
 * THE RACE IS DECIDED BY ARRIVAL TIME AND NOTHING ELSE. Ore is claimed inside the
 * transaction that resolves an arrival, under a lock on the claim row, so two
 * squadrons landing in the same second cannot both take the last of it. There is
 * no dwell time at the rock — a craft that arrives second takes whatever is left.
 * When one arrival strips the last ore, every squadron still travelling to that
 * rock turns immediately at its current point instead of completing a dead leg.
 */

/**
 * Where the field lives. Regenerated per season, cached, never downloaded.
 *
 * `now` BOUNDS THE DYNAMIC PART (2026-09-16): a season on the dynamic field holds a
 * stored hour for every hour it has run, and a read only needs the ones whose rocks
 * can still be seen, reached or flown home from — see `FIELD_LOOKBACK_HOURS`.
 */
async function fieldOf(tx: Queryable, seasonId: string, now: Date): Promise<{
  asteroids: AsteroidSpec[];
  startsAt: Date;
  asteroidKey: string;
}> {
  const raw = await rawAsteroidField(tx, seasonId, now);
  return { ...raw.field, asteroids: await applySpawnGate(tx, raw.season, 'ASTEROID', raw.field.asteroids, now) };
}

/** The planned field before the spawn gate — only the gate itself and its tests read this. */
export async function rawAsteroidField(tx: Queryable, seasonId: string, now: Date): Promise<{
  season: typeof seasons.$inferSelect;
  field: { asteroids: AsteroidSpec[]; startsAt: Date; asteroidKey: string };
}> {
  const [season] = await tx.select().from(seasons).where(eq(seasons.id, seasonId));
  if (!season) throw new GameError('SEASON_NOT_FOUND', 'No such season', 404);
  const dynamicFrom = season.asteroidDynamicFrom;
  const calendar = dynamicFrom === null
    ? await loadGalaxyEventSchedule(tx, season.id, season.startsAt)
    : [];
  const hours = dynamicFrom === null ? [] : await loadAsteroidHours(tx, season.id, now);
  const hourZero = floorHour(season.startsAt).getTime();
  return { season, field: {
    asteroids: composeSeasonAsteroidField({
      key: season.asteroidKey,
      calendar,
      dynamicFromMinute: dynamicFrom === null ? null : minutesSince(season.startsAt, dynamicFrom),
      legacyCalendar: season.asteroidLegacyCalendar === null
        ? null
        : legacyCalendarSchema.parse(season.asteroidLegacyCalendar),
      hours: hours.map((hour) => ({
        hourOrdinal: Math.round((hour.hourStartsAt.getTime() - hourZero) / HOUR_MS),
        lanes: hour.lanes,
        levelWeights: hour.levelWeights,
        generation: hour.generation,
      })),
      nowMinutes: minutesSince(season.startsAt, now),
      lookbackMinutes: (FIELD_LOOKBACK_HOURS / 2) * 60,
    }),
    startsAt: season.startsAt,
    asteroidKey: season.asteroidKey,
  } };
}

/** The frozen shower calendar, read back through the same shape it was written in. */
const legacyCalendarSchema = z.array(z.object({
  sequence: z.number().int().nonnegative(),
  kind: z.literal('ASTEROID_SHOWER'),
  startsAtMinute: z.number().finite(),
  endsAtMinute: z.number().finite(),
  definitionVersion: z.number().int().positive(),
  effect: z.object({ asteroidSpawnMultiplier: z.number().finite().gt(1) }).strict(),
}).strict());

export interface AsteroidView extends Omit<AsteroidSpec, 'isotopeRich' | 'deuteriumShare'> {
  /** Ore still in it. Internal full-field projection; API routes apply caller fog. */
  oreRemaining: number;
  /** Visible rocks are active; retained in the wire shape for client compatibility. */
  active: boolean;
  /** Hidden until spectroscopy; a normal-looking active rock reveals no fuel. */
  isotopeRich: boolean;
  deuteriumShare: number | null;
}

/**
 * The caller-independent raw snapshot behind `/api/mining`. D99.
 *
 * It intentionally carries raw asteroid/debris facts rather than a response:
 * activity, decay and isotope visibility are derived at request time. Nothing
 * about a player's research, orbit or own runs can enter this shared snapshot.
 */
export interface MiningSnapshot {
  asteroids: AsteroidSpec[];
  startsAt: Date;
  asteroidKey: string;
  oreTaken: ReadonlyMap<number, number>;
  debris: (typeof debrisFields.$inferSelect)[];
}

export async function loadMiningSnapshot(
  db: Queryable,
  seasonId: string,
  now: Date,
): Promise<MiningSnapshot> {
  const field = await fieldOf(db, seasonId, now);
  const oldest = new Date(now.getTime() - DEBRIS.decayMinutes * 60_000);
  const [claims, debris] = await Promise.all([
    field.asteroids.length === 0 ? Promise.resolve([]) : db.select().from(asteroidClaims).where(and(
      eq(asteroidClaims.seasonId, seasonId),
      inArray(asteroidClaims.index, field.asteroids.map(rock => rock.index)),
    )),
    db
      .select()
      .from(debrisFields)
      .where(and(eq(debrisFields.seasonId, seasonId), gt(debrisFields.createdAt, oldest))),
  ]);
  return {
    ...field,
    oreTaken: new Map(claims.map((claim) => [claim.index, claim.oreTaken])),
    debris,
  };
}

export function projectVisibleAsteroids(
  snapshot: MiningSnapshot,
  now: Date,
  revealIsotopes = false,
): AsteroidView[] {
  const nowMinutes = minutesSince(snapshot.startsAt, now);
  return snapshot.asteroids
    .filter((asteroid) => asteroidActive(asteroid, nowMinutes))
    .map((asteroid) => ({
      index: asteroid.index,
      level: asteroid.level,
      ore: asteroid.ore,
      crystalShare: asteroid.crystalShare,
      radius: asteroid.radius,
      period: asteroid.period,
      phase: asteroid.phase,
      inclination: asteroid.inclination,
      ascendingNode: asteroid.ascendingNode,
      speed: asteroid.speed,
      appearsAt: asteroid.appearsAt,
      expiresAt: asteroid.expiresAt,
      oreRemaining: Math.max(0, asteroid.ore - (snapshot.oreTaken.get(asteroid.index) ?? 0)),
      active: true,
      isotopeRich: asteroid.isotopeRich,
      deuteriumShare: revealIsotopes ? asteroid.deuteriumShare : null,
    }))
    .filter((asteroid) => asteroid.oreRemaining > 0);
}

export function projectVisibleDebris(snapshot: MiningSnapshot, now: Date) {
  return snapshot.debris
    .map((field) => {
      const age = (now.getTime() - field.createdAt.getTime()) / 60_000;
      return {
        id: field.id,
        /** NULL for a pirate battle: open space has no world to orbit. D150. */
        planetId: field.planetId,
        x: field.x,
        y: field.y,
        z: field.z,
        alloy: debrisRemaining(field.alloy, field.takenAlloy, age),
        crystal: debrisRemaining(field.crystal, field.takenCrystal, age),
        deuterium: debrisRemaining(field.deuterium, field.takenDeuterium, age),
        minutesLeft: Math.max(0, DEBRIS.decayMinutes - age),
        createdAt: field.createdAt,
      };
    })
    .filter((field) => field.alloy + field.crystal + field.deuterium > 1);
}

/**
 * Every active rock, for trusted simulation/capacity tooling and legacy service
 * tests. This is deliberately not an API projection: player routes must pass the
 * result through `projectPlayerAsteroidField` and durable sensor history.
 */
export async function visibleAsteroids(
  db: Queryable,
  seasonId: string,
  now: Date,
  revealIsotopes = false,
): Promise<AsteroidView[]> {
  return projectVisibleAsteroids(await loadMiningSnapshot(db, seasonId, now), now, revealIsotopes);
}

/** The caller-only half of mining, built identically for GET and launch POST. */
export function projectPrivateMiningView(
  orbit: SatelliteSet,
  runs: readonly (typeof miningRuns.$inferSelect)[],
  tech: TechLevels,
  asteroidKey: string,
  /**
   * Legacy aggregate clock, retained for already-open clients. New clients use
   * the independent landed batches below, so a rest never locks fresh craft.
   */
  craftReadyAt: Date | null = null,
  craftCooldowns: readonly ProspectorCooldown[] = [],
) {
  return {
    /** Whether the DERRICK is in orbit. D25 — hardware, never a level. */
    derrick: orbit.includes('DERRICK'),
    craftSpeed: prospectorSpeed(orbit),
    craftHold: prospectorHold(orbit, tech),
    derrickHold: prospectorHold(['DERRICK'], tech),
    craftReadyAt,
    craftCooldowns,
    runs: runs.map((run) => ({
      id: run.id,
      planetId: run.planetId,
      targetKind: run.targetKind,
      asteroidId: run.asteroidIndex === null ? null : asteroidId(asteroidKey, run.asteroidIndex),
      debrisFieldId: run.debrisFieldId,
      status: run.status,
      craft: run.craft,
      departAt: run.departAt,
      arriveAt: run.arriveAt,
      recalledAt: run.recalledAt,
      homeAt: run.homeAt,
      intercept: { x: run.interceptX, y: run.interceptY, z: run.interceptZ },
      minedAlloy: Math.round(run.minedAlloy),
      minedCrystal: Math.round(run.minedCrystal),
      minedDeuterium: Math.round(run.minedDeuterium),
    })),
  };
}

/** The isotope subset of a private status response, from an already-authorised field. */
export function projectIsotopeKnowledge(
  asteroids: readonly {
    id: string;
    isotopeRich: boolean;
    deuteriumShare: number | null;
  }[],
) {
  return asteroids.flatMap((asteroid) =>
    asteroid.isotopeRich && asteroid.deuteriumShare !== null
      ? [{ id: asteroid.id, deuteriumShare: asteroid.deuteriumShare }]
      : []);
}

export type MiningStatusView = ReturnType<typeof projectPrivateMiningView> & {
  isotopes: ReturnType<typeof projectIsotopeKnowledge>;
};

/**
 * The private mining view immediately after a launch, read before the transaction
 * commits so the run in the answer is the row the mutation just created. D120.
 */
async function miningStatusAfterLaunch(
  tx: Tx,
  origin: Pick<LockedPlanet, 'planetId' | 'playerId' | 'seasonId' | 'orbit' | 'now'>,
): Promise<MiningStatusView> {
  const runs = await activePlayerMiningRuns(tx, origin.playerId);
  const field = await fieldOf(tx, origin.seasonId, origin.now);
  const cooldowns = await prospectorCooldowns(tx, origin.planetId, origin.now);
  const view = projectPrivateMiningView(
    origin.orbit,
    runs,
    await techOf(tx, origin.playerId),
    field.asteroidKey,
    cooldowns.at(-1)?.readyAt ?? null,
    cooldowns,
  );
  // The commander's spectrometry, not the world's. T7.
  if (!(await hasResearch(tx, origin.playerId, 'ISOTOPE_SPECTROMETRY'))) {
    return { ...view, isotopes: [] };
  }

  // Only the asteroid half is needed here. Pulling live debris into a planet-locked
  // launch transaction would lengthen the lock for a payload this response does not
  // carry; claims are the only stored fact isotope visibility needs.
  const claims = await tx
    .select({ index: asteroidClaims.index, oreTaken: asteroidClaims.oreTaken })
    .from(asteroidClaims)
    .where(eq(asteroidClaims.seasonId, origin.seasonId));
  const taken = new Map(claims.map((claim) => [claim.index, claim.oreTaken]));
  const epochs = await sensorHistoryForPlayer(tx, origin.playerId, origin.seasonId, field.startsAt);
  const projected = projectPlayerAsteroidField(
    { asteroids: field.asteroids, startsAt: field.startsAt, oreTaken: taken },
    field.asteroidKey,
    epochs,
    origin.now,
    true,
  );
  const isotopes = projectIsotopeKnowledge(projected.asteroids.map((asteroid) => ({
    id: asteroid.id,
    isotopeRich: asteroid.isotopeRich,
    deuteriumShare: asteroid.deuteriumShare === null
      ? null
      : Math.round(asteroid.deuteriumShare * 100) / 100,
  })));
  return { ...view, isotopes };
}

async function launchViews(
  tx: Tx,
  origin: LockedPlanet,
  clock: Clock,
) {
  // Deliberately sequential on one transaction connection. Each is the same
  // projection its GET endpoint uses, but no second HTTP request or second DB
  // snapshot can race the launch.
  const mining = await miningStatusAfterLaunch(tx, origin);
  const pending = await pendingThreads(tx, origin.planetId, origin.now);
  const planet = await loadPlanetViewData(tx, origin.planetId, clock);
  return { mining, pending, planet };
}

export interface MiningLaunch {
  runId: string;
  /** Absent on a harvest — a wreck field is not in the generated asteroid field. */
  asteroidIndex?: number;
  /** Public target handle. Absent on a harvest. */
  asteroidId?: string;
  craft: number;
  arriveAt: Date;
  flightMinutes: number;
  intercept: Vec3;
  /** Ore the squadron could carry if the rock still has it when they land. */
  capacity: number;
  /** Private run/hardware state, in the exact shape `/api/mining/status` serves. */
  mining: MiningStatusView;
  /** Mission strip state, protected against an older read landing after this POST. */
  pending: PendingThread[];
  /** The selected world after the Prospectors and one flight bay have left it. */
  planet: PlanetView;
}

export interface MiningRecall {
  runId: string;
  homeAt: Date;
  /** Private run/hardware state after the turn was committed. */
  mining: MiningStatusView;
  /** Mission strip state from the same transaction as the turn. */
  pending: PendingThread[];
  /** The origin still has the craft and its bay committed until `homeAt`. */
  planet: PlanetView;
}

/**
 * Send Prospectors at a rock.
 *
 * The aim point is solved once, here, and stored — see `mining_runs`. Re-deriving
 * it later would let a Drill upgrade mid-flight silently move a craft onto a new
 * course, and a player watching their squadron cross the disc would see it jump.
 */
export async function launchMining(
  db: Db,
  planetId: string,
  asteroidTarget: number | string,
  craft: number,
  clock: Clock,
  expectedPlayerId?: string,
): Promise<MiningLaunch> {
  if (!Number.isInteger(craft) || craft < 1) {
    throw new GameError('BAD_COUNT', 'Send at least one Prospector', 400, {
      context: 'prospector',
    });
  }

  return db.transaction(async (tx) => {
    const origin = await loadLocked(tx, planetId, clock, { expectedPlayerId });
    assertWorldOperational(origin);
    assertOutsideSilentSpace(origin);

    const field = await fieldOf(tx, origin.seasonId, origin.now);
    const nowMinutes = minutesSince(field.startsAt, origin.now);
    const fromOpaqueId = typeof asteroidTarget === 'string';
    const asteroidIndex = fromOpaqueId
      ? asteroidIndexFromId(field.asteroidKey, field.asteroids, asteroidTarget)
      : asteroidTarget;
    const rock = asteroidIndex === null
      ? undefined
      : field.asteroids.find((candidate) => candidate.index === asteroidIndex);

    if (fromOpaqueId) {
      const epochs = await sensorHistoryForPlayer(tx, origin.playerId, origin.seasonId, field.startsAt);
      const earned = rock !== undefined
        && asteroidActive(rock, nowMinutes)
        && orbitDiscoveredAt(rock, epochs, nowMinutes) !== null;
      if (!earned) {
        throw new GameError(
          'ASTEROID_UNAVAILABLE',
          'That asteroid is not available to your sensors',
          404,
        );
      }
    }
    if (!rock || asteroidIndex === null) {
      throw new GameError('NO_SUCH_ASTEROID', 'No such asteroid', 404);
    }

    /**
     * NO GATE ON SENDING. D25.
     *
     * It used to demand a DRILL satellite, which is a structure that no longer
     * exists — a drill is a craft you build at the Shipyard. Owning one is the
     * whole permission; the DERRICK in orbit makes it faster and roomier.
     */
    const available = origin.homeFleet.PROSPECTOR ?? 0;
    if (available < craft) {
      throw new GameError('NOT_ENOUGH_CRAFT', `Only ${String(available)} Prospectors at home`, 400, {
        available,
      });
    }

    // Before the intercept solve: no point finding a meeting point for a launch
    // that has nowhere to launch from. D28.
    assertProspectorsUsable(origin.faults, planetId);
    await assertFreeBay(tx, planetId, origin.buildings.CORE, origin.faults);
    await assertProspectorsRested(tx, planetId, origin.now, available, craft);

    if (!asteroidActive(rock, nowMinutes)) {
      throw new GameError('ASTEROID_GONE', 'That rock is not in the disc', 409);
    }
    if (
      rock.isotopeRich
      && !(await hasResearch(tx, origin.playerId, 'ISOTOPE_SPECTROMETRY'))
    ) {
      throw new GameError(
        'NEEDS_ISOTOPE_SPECTROMETRY',
        'Research Isotope Spectrometry before mining this anomaly',
        403,
      );
    }

    // Already stripped? Refuse before charging anyone a round trip for nothing.
    const [claim] = await tx
      .select()
      .from(asteroidClaims)
      .where(
        and(eq(asteroidClaims.seasonId, origin.seasonId), eq(asteroidClaims.index, asteroidIndex)),
      );
    if ((claim?.oreTaken ?? 0) >= rock.ore) {
      throw new GameError('ASTEROID_EMPTY', 'That rock has already been stripped', 409);
    }

    // Independently available craft may share a target. The origin row lock,
    // home inventory and flight bays guard concurrent dispatches, not the target.
    const speed = prospectorSpeed(origin.orbit);
    const hit = interceptAsteroid(origin, speed, rock, nowMinutes);
    if (!hit) {
      throw new GameError(
        'CANNOT_INTERCEPT',
        'It will leave the disc before your craft could reach it',
        409,
      );
    }

    const arriveAt = atMinute(field.startsAt, hit.meetsAtMinutes);
    // Budget a laden return: the haul is unknown until arrival, and this guard
    // must not admit a run that cannot get home before the season closes. D117.
    const homeMinutes = travelExact(
      distance(hit.at, origin),
      prospectorReturnSpeed(origin.orbit, true),
    );
    assertSeasonOpenThrough(origin, addMinutes(arriveAt, homeMinutes));
    const holdEach = prospectorHold(origin.orbit, await techOf(tx, origin.playerId));

    const [run] = await tx
      .insert(miningRuns)
      .values({
        seasonId: origin.seasonId,
        planetId,
        ownerPlayerId: origin.playerId,
        asteroidIndex,
        craft,
        holdEach,
        interceptX: hit.at.x,
        interceptY: hit.at.y,
        interceptZ: hit.at.z,
        departAt: origin.now,
        arriveAt,
      })
      .returning();

    // The craft leave the home stack, exactly like an attack fleet — they are
    // demonstrably not on the planet — but under a `mine:` location so nothing
    // that reads mission ids can mistake them for one.
    const damage = await takeHomeHealth(tx, planetId, { PROSPECTOR: craft });
    const remaining = { ...origin.homeFleet, PROSPECTOR: available - craft };
    await setUnits(tx, planetId, remaining, 'home');
    await setUnits(tx, planetId, { PROSPECTOR: craft }, `mine:${run!.id}`);
    await tx.update(units).set({ damage }).where(and(eq(units.planetId, planetId), eq(units.location, `mine:${run!.id}`)));

    await schedule(tx, {
      seasonId: origin.seasonId,
      kind: 'mining_arrival',
      refId: run!.id,
      resolveAt: arriveAt,
    });

    /**
     * AND THE RACE IS ANNOUNCED. D53.
     *
     * A mining run is the most public thing in the game — D19 publishes the whole
     * leg, the route and the clock, because two players racing for a rock is only
     * a race if both of them can see it. Learning about it up to thirty seconds
     * late is losing the part of the race that was worth watching.
     */
    await publishShard(tx, origin.seasonId, 'mining');
    // The shard wake lets everybody refresh the public race, but another tab or
    // phone owned by the launcher also needs the private run, bay and home-fleet
    // state. The initiating client already has the POST response; this narrow
    // private event closes the same-account multi-device gap.
    await publish(tx, origin.playerId, 'private:mining');

    return {
      runId: run!.id,
      asteroidIndex,
      asteroidId: asteroidId(field.asteroidKey, asteroidIndex),
      craft,
      arriveAt,
      flightMinutes: hit.flightMinutes,
      intercept: hit.at,
      capacity: holdEach * craft,
      ...await launchViews(tx, origin, clock),
    };
  }).then(buildPlanetResult);
}

/**
 * Turn an outbound Prospector squadron around before it reaches its target.
 *
 * The row lock is the arbitration point between this action and the arrival
 * worker. Only an `outbound` row strictly before `arriveAt` can be recalled. Once
 * this transition wins, the already-scheduled arrival becomes an idempotent no-op
 * and therefore cannot claim asteroid ore or wreckage later.
 */
export async function recallMining(
  db: Db,
  runId: string,
  clock: Clock,
  expectedPlayerId: string,
): Promise<MiningRecall> {
  return db.transaction(async (tx) => {
    // Recall follows current world control, just like the private mining roster.
    // A capture transfers every Prospector unit to the new controller while the
    // immutable run owner remains the launch/statistics actor. Joining the pad is
    // therefore both the correct authority and a 404-shaped privacy boundary.
    const [candidate] = await tx.select({ seasonId: miningRuns.seasonId })
      .from(miningRuns)
      .innerJoin(planets, eq(planets.id, miningRuns.planetId))
      .where(and(
        eq(miningRuns.id, runId),
        eq(planets.controllerPlayerId, expectedPlayerId),
      ));
    if (!candidate) {
      throw new GameError('MINING_RUN_NOT_FOUND', 'No such Prospector flight', 404);
    }
    // Match arrival workers and season administration: season → run → planet.
    // The pre-read discovers the parent lock; only the locked row is authority.
    await lockSeason(tx, candidate.seasonId);
    const [run] = await tx
      .select()
      .from(miningRuns)
      .where(eq(miningRuns.id, runId))
      .for('update');
    if (!run) {
      throw new GameError('MINING_RUN_NOT_FOUND', 'No such Prospector flight', 404);
    }

    const origin = await loadLocked(tx, run.planetId, clock, { expectedPlayerId });
    // A planet lock may have waited past contact. Decide using the clock AFTER
    // that wait, not the moment the HTTP request first found the flight.
    const now = origin.now;
    if (run.status !== 'outbound' || now.getTime() >= run.arriveAt.getTime()) {
      throw new GameError(
        'MINING_ALREADY_ARRIVED',
        'Prospectors cannot be recalled after reaching their target',
        409,
      );
    }

    const legMs = run.arriveAt.getTime() - run.departAt.getTime();
    // A clock correction must not put the turn behind the pad. Zero-length legs
    // are already rejected by the strict arrival check above.
    const progress = legMs <= 0
      ? 0
      : Math.max(0, Math.min(1, (now.getTime() - run.departAt.getTime()) / legMs));
    // Store the point the player is actually looking at. Mining craft are drawn
    // from the world's surface, not its centre; interpolating the raw endpoints
    // here would make a recalled craft jump by the remaining surface clearance
    // on the exact frame it turned around.
    const outbound = visualLeg(
      origin,
      { x: run.interceptX, y: run.interceptY, z: run.interceptZ },
      surfaceStandoff(worldRadius(origin.buildings.CORE)),
      0,
    );
    const turn = {
      x: outbound.from.x + (outbound.to.x - outbound.from.x) * progress,
      y: outbound.from.y + (outbound.to.y - outbound.from.y) * progress,
      z: outbound.from.z + (outbound.to.z - outbound.from.z) * progress,
    };
    const returnMinutes = travelExact(
      // Fly back to the same surface point the outbound marker left from. Using
      // the world centre adds one planet radius to the clock while the rendered
      // return leg stops at the surface, leaving an immediate recall visibly
      // motionless for several seconds.
      distance(turn, outbound.from),
      prospectorReturnSpeed(origin.orbit, false),
    );
    const homeAt = addMinutes(now, returnMinutes);

    // `arriveAt` is the start instant of every returning mining leg. Replacing the
    // obsolete target contact with the turn instant lets every existing position,
    // traffic and countdown projection draw the physical return without a second
    // trajectory model. `recalledAt` preserves why that contact moved.
    await tx
      .update(miningRuns)
      .set({
        status: 'returning',
        interceptX: turn.x,
        interceptY: turn.y,
        interceptZ: turn.z,
        arriveAt: now,
        recalledAt: now,
        homeAt,
      })
      .where(eq(miningRuns.id, run.id));

    await schedule(tx, {
      seasonId: run.seasonId,
      kind: 'mining_return',
      refId: run.id,
      resolveAt: homeAt,
    });
    await publishShard(tx, run.seasonId, 'mining');
    await publish(tx, expectedPlayerId, 'private:mining');

    return {
      runId: run.id,
      homeAt,
      ...await launchViews(tx, origin, clock),
    };
  }).then(buildPlanetResult);
}

/**
 * A rock has just been stripped. Turn every squadron that is still travelling to
 * it around at the point it occupies NOW, rather than letting it continue to an
 * obsolete rendezvous.
 *
 * The conditional status update is the arbitration point with an arrival worker.
 * A run that has already reached contact wins that race and is left alone; once
 * this update wins, its old arrival event becomes the usual idempotent no-op.
 */
async function turnRunsFromExhaustedAsteroid(
  tx: Tx,
  seasonId: string,
  asteroidIndex: number,
  now: Date,
): Promise<void> {
  const candidates = await tx
    .select()
    .from(miningRuns)
    .where(and(
      eq(miningRuns.seasonId, seasonId),
      eq(miningRuns.asteroidIndex, asteroidIndex),
      eq(miningRuns.status, 'outbound'),
      gt(miningRuns.arriveAt, now),
    ));

  let turned = false;
  for (const run of candidates) {
    const [home] = await tx.select().from(planets).where(eq(planets.id, run.planetId));
    if (!home) throw new Error(`mining run ${run.id} references a missing planet`);

    const [buildings, orbit] = await Promise.all([
      buildingLevelsOf(tx, run.planetId),
      orbitOf(tx, run.planetId),
    ]);
    const outbound = visualLeg(
      home,
      { x: run.interceptX, y: run.interceptY, z: run.interceptZ },
      surfaceStandoff(worldRadius(buildings.CORE)),
      0,
    );
    const duration = run.arriveAt.getTime() - run.departAt.getTime();
    const progress = duration <= 0
      ? 0
      : Math.max(0, Math.min(1, (now.getTime() - run.departAt.getTime()) / duration));
    const turn = {
      x: outbound.from.x + (outbound.to.x - outbound.from.x) * progress,
      y: outbound.from.y + (outbound.to.y - outbound.from.y) * progress,
      z: outbound.from.z + (outbound.to.z - outbound.from.z) * progress,
    };
    const homeAt = addMinutes(
      now,
      travelExact(
        distance(turn, outbound.from),
        prospectorReturnSpeed(orbit, false),
      ),
    );

    const claimed = await tx
      .update(miningRuns)
      .set({
        status: 'returning',
        interceptX: turn.x,
        interceptY: turn.y,
        interceptZ: turn.z,
        // Returning projections already treat arriveAt as the return leg's start.
        arriveAt: now,
        homeAt,
      })
      .where(and(
        eq(miningRuns.id, run.id),
        eq(miningRuns.status, 'outbound'),
        gt(miningRuns.arriveAt, now),
      ))
      .returning({ id: miningRuns.id });
    if (!claimed[0]) continue;

    turned = true;
    if (home.controllerPlayerId) {
      await notify(tx, {
        playerId: home.controllerPlayerId,
        kind: 'target_gone',
        payload: { targetKind: 'ASTEROID', craft: run.craft },
        at: now,
        refId: run.id,
      });
      await publish(tx, home.controllerPlayerId, 'private:mining');
    }
    await schedule(tx, {
      seasonId: run.seasonId,
      kind: 'mining_return',
      refId: run.id,
      resolveAt: homeAt,
    });
  }

  if (turned) await publishShard(tx, seasonId, 'mining');
}

/**
 * A squadron reaches the rock.
 *
 * Claims what it can carry and turns for home. Idempotent by the same mechanism
 * every other handler uses: the status transition is the claim, so an event
 * delivered twice does nothing the second time.
 */
export async function resolveMiningArrival(tx: Tx, runId: string, now: Date): Promise<void> {
  const claimed = await tx
    .update(miningRuns)
    .set({ status: 'returning' })
    .where(and(eq(miningRuns.id, runId), eq(miningRuns.status, 'outbound')))
    .returning();
  const run = claimed[0];
  if (!run) return; // already resolved by another worker

  /**
   * THE GALAXY SEES THE DRILL TURN FOR HOME. D53.
   *
   * Published from HERE rather than from the worker handler, because the claim
   * above is the thing that decides whether any work happened at all: a redelivered
   * event finds the row already `returning`, claims nothing, and must not send
   * three hundred clients to refetch a world that has not moved.
   */
  await publishShard(tx, run.seasonId, 'mining');

  let mined = { alloy: 0, crystal: 0, deuterium: 0 };

  /**
   * Branch on the COLUMN, never on `targetKind`.
   *
   * `mining_one_target` is a CHECK constraint, so `debrisFieldId is not null` is a
   * fact the database guarantees about this row. `targetKind` is a denormalised
   * label beside it that nothing enforces — and a row where the two disagreed
   * would fall through both arms here and silently mine nothing, which is the
   * quietest possible failure. The label exists for the wire (the client wants a
   * discriminant); the constraint decides what actually happens.
   */
  if (run.debrisFieldId !== null) {
    mined = await claimFromDebris(tx, run.debrisFieldId, run.holdEach * run.craft, now);
  }

  const { asteroids } = await fieldOf(tx, run.seasonId, now);
  const rockIndex = run.asteroidIndex;
  const rock = rockIndex === null ? undefined : asteroids.find((a) => a.index === rockIndex);

  if (rock && rockIndex !== null) {
    /**
     * Seed the claim row BEFORE locking it, like pirate_state (D150).
     *
     * FOR UPDATE cannot lock an absent row. Two first arrivals could both claim
     * the untouched ore, then overwrite each other's ledger total. The initial
     * insert serialises that first hit; the row lock serialises all later hits.
     */
    await tx.insert(asteroidClaims).values({
      seasonId: run.seasonId, index: rockIndex, oreTaken: 0, updatedAt: now,
    }).onConflictDoNothing({ target: [asteroidClaims.seasonId, asteroidClaims.index] });
    const [existing] = await tx
      .select()
      .from(asteroidClaims)
      .where(
        and(
          eq(asteroidClaims.seasonId, run.seasonId),
          eq(asteroidClaims.index, rockIndex),
        ),
      )
      .for('update');

    if (!existing) throw new Error('seeded asteroid claim row disappeared');
    const alreadyTaken = existing.oreTaken;
    const remaining = Math.max(0, rock.ore - alreadyTaken);
    const claim = claimOre(
      remaining,
      run.holdEach * run.craft,
      rock.crystalShare,
      rock.deuteriumShare,
    );
    mined = { alloy: claim.alloy, crystal: claim.crystal, deuterium: claim.deuterium };

    if (claim.taken > 0) {
      await tx
        .update(asteroidClaims)
        .set({ oreTaken: alreadyTaken + claim.taken, updatedAt: now })
        .where(and(eq(asteroidClaims.seasonId, run.seasonId), eq(asteroidClaims.index, rockIndex)));
      if (remaining - claim.taken <= 0) {
        if (rock.isotopeRich) {
          await recordGalaxyEvent(tx, {
            seasonId: run.seasonId,
            kind: 'isotope_exhausted',
            refId: `${run.seasonId}:${String(rockIndex)}`,
            subjectPlanetId: null,
            payload: {},
            occurredAt: now,
          });
        }
        await turnRunsFromExhaustedAsteroid(tx, run.seasonId, rockIndex, now);
      }
    }
  }

  // Home the way they came. The rock has moved on, so the trip back is measured
  // from the meeting point rather than from wherever the rock is now.
  const [home] = await tx.select().from(planets).where(eq(planets.id, run.planetId));
  if (!home) throw new Error(`mining run ${runId} references a missing planet`);
  if (home.controllerPlayerId) {
    // The shard event refreshes only public field/traffic data at D99 scale. The
    // owner gets a private wake as well so their own run turns around on the same
    // committed instant, without making every other commander query private rows.
    await publish(tx, home.controllerPlayerId, 'mining_arrival');
  }

  /**
   * A LADEN CRAFT FLIES HOME AT A THIRD OF ITS OUTBOUND SPEED. D117.
   *
   * This is the only line that decides the return leg, and everything downstream
   * reads the `homeAt` it produces rather than recomputing a speed: the owner's
   * craft interpolates `arriveAt → homeAt` (`runPosition`), the public contact is
   * built from the same two instants (`projectGalaxyTraffic`), the countdown comes
   * off the instant, and the `mining_return` event is scheduled at it. So the
   * factor belongs here and nowhere else — the two guards that also mention the
   * trip home are proving a run can FINISH, not deciding when it does.
   *
   * Both kinds of run come through here. An empty craft did not win the race and
   * carries no load to slow it down (owner correction, 2026-09-13).
   */
  const took = mined.alloy + mined.crystal + mined.deuterium;
  const back = travelExact(
    Math.hypot(run.interceptX - home.x, run.interceptY - home.y, run.interceptZ - home.z),
    // Re-read from what is CURRENTLY in orbit on purpose: the craft is a real
    // object being flown home, and a Derrick that lands while it is out
    // legitimately gets it back sooner. Only the aim point is frozen.
    prospectorReturnSpeed(await orbitOf(tx, run.planetId), took > 0),
  );
  const homeAt = addMinutes(now, back);

  await tx
    .update(miningRuns)
    .set({
      minedAlloy: mined.alloy,
      minedCrystal: mined.crystal,
      minedDeuterium: mined.deuterium,
      homeAt,
    })
    .where(eq(miningRuns.id, runId));

  /**
   * THE TRIP THAT ARRIVED AT NOTHING. D177, and the same fact as the pirate lane's.
   *
   * A drill that reaches this handler has crossed the no-recall boundary and flies
   * the whole remaining trip home, so the only question is WHEN the commander finds out that
   * somebody emptied the rock, or that the rock is no longer in the disc at all.
   * It used to be when the craft landed, one full return leg after the answer
   * existed, in a haul row that said "empty-handed" without saying why.
   *
   * ZERO IS THE WHOLE TEST, and it is the honest one: `claimOre` takes what is
   * left, so nothing taken means nothing was there — an exhausted rock, a wreck
   * field already picked clean, or an index the current field no longer carries.
   * A rock that still had ore in it says nothing, because that trip paid.
   *
   * IT NAMES NO RIVAL. Who emptied it is their run, not this one's news (D127).
   */
  if (took === 0 && home.controllerPlayerId) {
    await notify(tx, {
      playerId: home.controllerPlayerId,
      kind: 'target_gone',
      payload: {
        targetKind: run.debrisFieldId !== null ? 'DEBRIS' : 'ASTEROID',
        craft: run.craft,
      },
      at: now,
      refId: runId,
    });
  }

  await schedule(tx, {
    seasonId: run.seasonId,
    kind: 'mining_return',
    refId: runId,
    resolveAt: homeAt,
  });
}


export interface MiningDelivery {
  runId: string;
  craft: number;
  /** Where it came down and whose it was; null when there was nobody left to land for. */
  planetId: string | null;
  playerId: string | null;
  /** What actually reached the store. */
  delivered: { alloy: number; crystal: number; deuterium: number };
  /** What was mined but would not fit — the store was already full. */
  wasted: { alloy: number; crystal: number; deuterium: number };
}

/**
 * WHERE A RUN COMES DOWN, decided under the locks. Owner report, 2026-09-24: a colony
 * that seceded left its Prospectors in the air for ever ("bir kullanıcıda 6 tane birikmiş").
 *
 * The landing read the owner off the launch world, and a world that fell to nobody has
 * none — `setUnits` threw, the transaction rolled back, the run stayed `returning`, and
 * the recovery path made the same call and failed the same way.
 *
 * The rule is secession's own: a fleet in the air still belongs to its commander and
 * lands somewhere that is still theirs. So the run comes down on the world it left
 * while that world has a commander — its own, or the one who TOOK it, who takes its
 * drills with it (`transferPlanetControl`, tested as "belongs to the current controller
 * when its launch world changes hands") — and at its commander's capital when the world
 * went neutral. Null only when there is no commander left to land for.
 *
 * Both possible worlds are locked in sorted order, as launches take them, and the
 * choice is made after the locks: control may change while a return waits its turn.
 * The capital is read here rather than through `ownership.capitalPlanet` for the same
 * reason `loyalty.ts` gives: that module's imports lead back through the war code.
 */
export async function landRunLocked(
  tx: Tx,
  run: Pick<typeof miningRuns.$inferSelect, 'planetId' | 'ownerPlayerId'>,
): Promise<{ planetId: string; playerId: string } | null> {
  const [capital] = run.ownerPlayerId === null
    ? []
    : await tx.select({ id: planets.id }).from(planets)
      .where(and(eq(planets.controllerPlayerId, run.ownerPlayerId), eq(planets.kind, 'CAPITAL')));
  for (const id of [...new Set([run.planetId, ...(capital ? [capital.id] : [])])].sort()) {
    await tx.select({ id: planets.id }).from(planets).where(eq(planets.id, id)).for('update');
  }
  const [origin] = await tx.select({ controller: planets.controllerPlayerId }).from(planets)
    .where(eq(planets.id, run.planetId));
  if (origin?.controller) return { planetId: run.planetId, playerId: origin.controller };
  if (!capital || run.ownerPlayerId === null) return null;
  return { planetId: capital.id, playerId: run.ownerPlayerId };
}

/**
 * The squadron gets home and unloads.
 *
 * Ore goes STRAIGHT INTO STORAGE, not into the works: it was mined, not produced,
 * so the collector has nothing to do with it and a player who flew a mission
 * should not have to press a second button to be paid for it.
 *
 * Storage still caps. Anything over the ceiling is lost and reported as lost —
 * "the honest version shows the waste" — which is what makes emptying the store
 * before a big haul lands a real thing to think about.
 */
export async function resolveMiningReturn(
  tx: Tx,
  runId: string,
  clock: Clock,
): Promise<MiningDelivery | null> {
  const claimed = await tx
    .update(miningRuns)
    .set({ status: 'done' })
    .where(and(eq(miningRuns.id, runId), eq(miningRuns.status, 'returning')))
    .returning();
  const run = claimed[0];
  if (!run) return null;

  /** And again when it lands, for the same reason and on the same claim. D53. */
  await publishShard(tx, run.seasonId, 'mining');

  const mined = { alloy: run.minedAlloy, crystal: run.minedCrystal, deuterium: run.minedDeuterium };
  const landing = await landRunLocked(tx, run);
  if (!landing) {
    // Nobody to land for: the craft leave the sky, and no caretaker is handed them.
    await tx.delete(units)
      .where(and(eq(units.planetId, run.planetId), eq(units.location, `mine:${runId}`)));
    return {
      runId, craft: run.craft, planetId: null, playerId: null,
      delivered: { alloy: 0, crystal: 0, deuterium: 0 }, wasted: mined,
    };
  }
  const planet = await loadLocked(tx, landing.planetId, clock);

  /**
   * ORE COMES HOME INTO THE WORKS, NOT INTO STORAGE. D31.
   *
   * Measured with the real interception solver, one Prospector returns 589/h and
   * about eleven craft lift the galaxy's entire 6,393/h ore supply — with no
   * exposure of any kind, because mining sets no fleet status and craft in flight
   * cannot be raided. Income decoupled from the war economy is precisely what
   * emptied OGame's PvP layer through expeditions, and it was doing the same here.
   *
   * Landing it in the works fixes three things at once, all with rules that already
   * exist:
   *
   *   · THROUGHPUT RE-COUPLES TO THE PLANET. What you can absorb between
   *     collections is `collectorCap`, which scales with the Refinery and the
   *     Extractor — not with how many craft you own.
   *   · MINED ORE BECOMES RAIDABLE at `COMBAT.lootBufferShare`, and the vault does
   *     not cover the works at all. A miner is finally a target.
   *   · IT HAS TO BE COLLECTED, so a miner takes the same discipline as everyone
   *     else rather than banking straight to spendable stock.
   *
   * D19's race, D24's public mining runs and the telescope's fleet signal are all
   * untouched.
   *
   * THE TWO CEILINGS ARE INDEPENDENT, deliberately. A single shared factor — the
   * shape `computeLoot` uses for cargo — would throttle the alloy delivery because
   * the CRYSTAL works were full, and a player whose alloy works were half empty
   * cannot be told why they lost alloy. The crystal share of a rock runs as high as
   * 0.65 while the crystal works are roughly a third the size of the alloy ones, so
   * that case is common rather than exotic. Losing only the pile that had nowhere
   * to go is both smaller and explainable.
   */
  const boost = productionMult(planet.orbit);
  const roomAlloy = Math.max(
    0,
    collectorCap(alloyRate(planet.buildings.REFINERY) * boost) - planet.bufferAlloy,
  );
  const roomCrystal = Math.max(
    0,
    collectorCap(crystalRate(planet.buildings.EXTRACTOR) * boost) - planet.bufferCrystal,
  );
  const roomDeuterium = Math.max(
    0,
    deuteriumCollectorCap(
      deuteriumRate(planet.buildings.DEUTERIUM_PLANT) * boost,
      crystalRate(planet.buildings.EXTRACTOR) * boost,
    )
      - planet.bufferDeuterium,
  );
  const gotAlloy = Math.min(run.minedAlloy, roomAlloy);
  const gotCrystal = Math.min(run.minedCrystal, roomCrystal);
  const gotDeuterium = Math.min(run.minedDeuterium, roomDeuterium);

  await saveResources(tx, landing.planetId, {
    alloy: planet.alloy,
    crystal: planet.crystal,
    deuterium: planet.deuterium,
    bufferAlloy: planet.bufferAlloy + gotAlloy,
    bufferCrystal: planet.bufferCrystal + gotCrystal,
    bufferDeuterium: planet.bufferDeuterium + gotDeuterium,
  });

  // The craft rejoin the garrison, and their in-flight row goes away. Read the
  // home count fresh rather than trusting the launch-time figure: other runs may
  // have landed while this one was out.
  const carried = await tx.select({ damage: units.damage }).from(units)
    .where(and(eq(units.planetId, run.planetId), eq(units.location, `mine:${runId}`)));
  await landHpShips(tx, { planetId: landing.planetId, ownerPlayerId: landing.playerId,
    fleet: { PROSPECTOR: run.craft }, damage: carried.flatMap(row => row.damage), at: planet.now });
  await tx
    .delete(units)
    .where(and(eq(units.planetId, run.planetId), eq(units.location, `mine:${runId}`)));

  return {
    runId,
    craft: run.craft,
    planetId: landing.planetId,
    playerId: landing.playerId,
    delivered: { alloy: gotAlloy, crystal: gotCrystal, deuterium: gotDeuterium },
    wasted: {
      alloy: run.minedAlloy - gotAlloy,
      crystal: run.minedCrystal - gotCrystal,
      deuterium: run.minedDeuterium - gotDeuterium,
    },
  };
}

/** Runs still out, for the pending strip and the galaxy view. */
export async function activeMiningRuns(db: Queryable, planetId: string) {
  return db
    .select()
    .from(miningRuns)
    .where(
      and(eq(miningRuns.planetId, planetId), inArray(miningRuns.status, ['outbound', 'returning'])),
    );
}

/** Every live run whose origin is currently controlled by this commander. */
export async function activePlayerMiningRuns(db: Queryable, playerId: string) {
  return db
    .select({ run: miningRuns })
    .from(miningRuns)
    .innerJoin(planets, eq(planets.id, miningRuns.planetId))
    .where(and(
      eq(planets.controllerPlayerId, playerId),
      inArray(miningRuns.status, ['outbound', 'returning']),
    ))
    .then((rows) => rows.map((row) => row.run));
}

/*
 * TWO EXPORTS USED TO LIVE HERE AND NOTHING EVER CALLED EITHER. D52a.
 *
 * `asteroidAt` documented itself as "exported so the galaxy route can answer 'is
 * this still worth chasing'" — a caller that has never existed. `pruneAsteroidClaims`
 * was labelled housekeeping and was never scheduled, so the rows it existed to
 * remove were never removed; they are bounded by the number of rocks in a season,
 * never read again once a rock expires (`visibleAsteroids` filters to LIVE indexes)
 * and cleared by the wipe, so nothing was leaking but the reader's attention.
 *
 * A public surface a future reader has to assume is load-bearing costs more than a
 * function is worth. If either is wanted, it is four lines and a test.
 */

/* ── wreckage ───────────────────────────────────────────────── */

/**
 * Take what a squadron can carry out of a wreck field. D32.
 *
 * The same first-come-first-served race as an asteroid, and the same locking: the
 * row is taken `FOR UPDATE` so two harvesters landing in the same second block on
 * each other rather than both reading the pre-claim total. Decay is applied at read
 * time from the clock, so nothing about the field's current value is stored.
 */
export async function claimFromDebris(
  tx: Tx,
  fieldId: string,
  hold: number,
  now: Date,
): Promise<{ alloy: number; crystal: number; deuterium: number }> {
  const [field] = await tx
    .select()
    .from(debrisFields)
    .where(eq(debrisFields.id, fieldId))
    .for('update');
  if (!field) return { alloy: 0, crystal: 0, deuterium: 0 };

  const age = (now.getTime() - field.createdAt.getTime()) / 60_000;
  const alloyLeft = debrisRemaining(field.alloy, field.takenAlloy, age);
  const crystalLeft = debrisRemaining(field.crystal, field.takenCrystal, age);
  const deuteriumLeft = debrisRemaining(field.deuterium, field.takenDeuterium, age);
  const claim = claimDebris(alloyLeft, crystalLeft, deuteriumLeft, hold);

  if (claim.alloy > 0 || claim.crystal > 0 || claim.deuterium > 0) {
    await tx
      .update(debrisFields)
      .set({
        takenAlloy: field.takenAlloy + claim.alloy,
        takenCrystal: field.takenCrystal + claim.crystal,
        takenDeuterium: field.takenDeuterium + claim.deuterium,
      })
      .where(eq(debrisFields.id, fieldId));

    /**
     * EXHAUSTED IS PER COLUMN, NOT A SINGLE TOTAL — and the total was a latent bug.
     *
     * `claimDebris` floors each resource separately, so a fully drained field can
     * still show a fractional residue in every column at once: up to just under
     * three in total, against a threshold of one. The event therefore fired only
     * when the decay arithmetic happened to land favourably, and a two-column field
     * that had been swept clean routinely announced nothing.
     *
     * A column holding less than one whole unit can never be claimed again, because
     * the floor takes it to zero. So "every column is under one" is the exact
     * statement of finished, and it cannot be knocked out by rounding.
     */
    const leftAfter = Math.max(
      alloyLeft - claim.alloy,
      crystalLeft - claim.crystal,
      deuteriumLeft - claim.deuterium,
    );
    if (leftAfter < 1) {
      /*
        A VOID WRECK EXHAUSTING NAMES NO WORLD, SO IT IS NOT A CHRONICLE LINE. D96.

        The chronicle records public transitions and identifies them by the world
        they happened to; a pirate battle's wreckage happened at a rendezvous with
        no address. Rather than invent a subject, the stripped field simply passes
        without an entry — which is also what `subjectPlanetId` being non-null in
        that payload has always meant.
      */
      const identity = field.planetId === null
        ? null
        : await publicPlanetIdentity(tx, field.planetId);
      if (identity && field.planetId !== null) {
        await recordGalaxyEvent(tx, {
          seasonId: field.seasonId,
          kind: 'wreck_exhausted',
          refId: field.id,
          subjectPlanetId: field.planetId,
          payload: identity,
          occurredAt: now,
        });
      }
    }
  }
  return claim;
}

/** Every wreck field still worth flying to, for the whole galaxy. Public. */
export async function visibleDebris(db: Queryable, seasonId: string, now: Date) {
  /**
   * Pruned in SQL, not in JS.
   *
   * A field older than its decay life is empty by arithmetic — `debrisRemaining`
   * can only return 0 for it — so there is no reading in which those rows matter.
   * Selecting them anyway made this an UNBOUNDED query: nothing ever deletes a
   * debris row, so by the end of a season this would pull every battle the galaxy
   * has ever fought on every read of the disc. `debris_season_idx` is
   * `(season_id, created_at)` and serves this exactly.
   */
  return projectVisibleDebris(await loadMiningSnapshot(db, seasonId, now), now);
}

/**
 * Independent cooldowns earned by this world's landed short debris runs. D183.
 *
 * A raid resolved over a commander's own world leaves its wreckage AT that world,
 * so the salvage leg is zero units long — and every brake mining has is written
 * against a distance (`returnSpeedFactor` scales one, the flight bay is held for
 * the length of one, `PROSPECTOR.max` rations craft that are away for one). At
 * zero all three are free and the field is emptied by tapping. This is the fourth
 * brake, and the only one that does not read a distance.
 *
 * DERIVED, NEVER STORED. The run rows already carry everything the answer needs —
 * the leg is `arriveAt - departAt` and the landing is `homeAt` — and A5 forbids
 * storing what a formula produces. The row is also the only place the fact can
 * live without a migration that every replica has to be ahead of.
 *
 * ONLY DEBRIS RUNS EARN A REST (owner correction, 2026-09-13), using the
 * constrained target column rather than the denormalised wire label.
 *
 * Each row reserves only its own craft until its own ready instant. Because a
 * resting craft cannot relaunch, recent eligible rows cannot count that craft
 * twice; no hull identity or stored timer is needed. The launch reads these rows
 * under the origin lock, alongside the home inventory. Other home craft and
 * other worlds stay available (owner correction, 2026-09-13).
 */
export interface ProspectorCooldown { runId: string; craft: number; readyAt: Date }

export async function prospectorCooldowns(
  tx: Queryable,
  planetId: string,
  now: Date,
): Promise<ProspectorCooldown[]> {
  const landed = await tx
    .select({ id: miningRuns.id, craft: miningRuns.craft, departAt: miningRuns.departAt, arriveAt: miningRuns.arriveAt, homeAt: miningRuns.homeAt })
    .from(miningRuns)
    .where(and(
      eq(miningRuns.planetId, planetId),
      eq(miningRuns.status, 'done'),
      isNotNull(miningRuns.debrisFieldId),
      // A recalled squadron never reached the debris field, so its shortened
      // outbound span cannot earn the landing rest this query derives.
      sql`${miningRuns.recalledAt} is null`,
      /*
        ONLY A LANDING INSIDE THE WINDOW CAN SET A REST, and saying so here is what
        keeps this cheap. This function runs on every launch AND on every read of
        `/api/mining/status`, which is a poll — asked as "the latest short run this
        world ever flew" it sorts every finished run the world owns, hundreds of
        them by the end of a season, on a query nobody notices getting slower.

        It changes no answer: a landing older than the cooldown produces a `readyAt`
        already in the past, which the comparison below discards anyway. What it
        changes is how many rows ever reach the sort. `debris.test.ts` holds the
        behaviour from the outside so the bound cannot quietly become a rule.
      */
      gt(
        miningRuns.homeAt,
        new Date(now.getTime() - PROSPECTOR.shortTripCooldownMinutes * 60_000),
      ),
      // The outbound leg, in minutes, against the rule's own figure. Written in
      // SQL rather than filtered in JS so the index does the work and a season's
      // worth of finished runs never has to come back over the wire.
      sql`extract(epoch from (${miningRuns.arriveAt} - ${miningRuns.departAt}))
          < ${PROSPECTOR.shortTripMinutes * 60}`,
    ))
    .orderBy(asc(miningRuns.homeAt));
  return landed.flatMap((run) => {
    if (!run.homeAt) return [];
    const readyAt = prospectorReadyAt(
      (run.arriveAt.getTime() - run.departAt.getTime()) / 60_000,
      run.homeAt.getTime(), 'debris',
    );
    return readyAt !== null && readyAt > now.getTime()
      ? [{ runId: run.id, craft: run.craft, readyAt: new Date(readyAt) }] : [];
  });
}

/** Legacy aggregate clock only; dispatch must count independent batches. */
export async function prospectorsRestingUntil(tx: Queryable, planetId: string, now: Date): Promise<Date | null> {
  return (await prospectorCooldowns(tx, planetId, now)).at(-1)?.readyAt ?? null;
}

/**
 * The refusal, stated once so both mining lanes make the same one.
 *
 * NAMES THE INSTANT. D124 — a rule the player cannot see is not a usable rule, and
 * a lockout with no clock on it is the exact "timer with nothing on screen" that
 * `PROSPECTOR.returnSpeedFactor` refuses. The client draws the countdown from
 * `params.readyAt`; the same instant is published on `/api/mining/status` so the
 * control is disabled before it is ever pressed.
 */
export async function assertProspectorsRested(tx: Tx, planetId: string, now: Date, homeCraft: number, requested: number): Promise<void> {
  // Non-mining fleets need no query. A home-inventory shortage belongs to each
  // lane's existing stock validator; this guard only prices resting HOME craft.
  if (requested === 0 || requested > homeCraft) return;
  const cooldowns = await prospectorCooldowns(tx, planetId, now);
  const { available } = prospectorAvailability(homeCraft,
    cooldowns.map((rest) => ({ craft: rest.craft, readyAtMs: rest.readyAt.getTime() })), now.getTime());
  if (requested > available) {
    let ready = available;
    // Name the first instant when the REQUESTED count can launch, not when every
    // craft is ready. The ordered batches expire independently.
    const enough = cooldowns.find((rest) => { ready += rest.craft; return ready >= requested; });
    throw new GameError(
      'PROSPECTORS_RESTING',
      'Those craft only just landed. They are ready again shortly.',
      409,
      // An ISO string, like `WORLD_RECOVERING`'s: `ErrorParams` carries scalars,
      // and every clock that crosses this boundary crosses it the same way.
      { available, readyAt: enough?.readyAt.toISOString() ?? now.toISOString() },
    );
  }
}

/**
 * Send craft to a wreck field. D32.
 *
 * Deliberately NOT `interceptAsteroid`: a field does not move, so this is a plain
 * flight to a fixed point and the solver would be answering a question nobody
 * asked. Everything else — the bay, the parked craft, the claim race on arrival,
 * the trip home — is the mining path, because a harvest is the same shape as a
 * mining run and duplicating it would mean maintaining two of everything.
 */
export async function launchHarvest(
  db: Db,
  planetId: string,
  fieldId: string,
  craft: number,
  clock: Clock,
  expectedPlayerId?: string,
): Promise<MiningLaunch> {
  if (!Number.isInteger(craft) || craft < 1) {
    throw new GameError('BAD_COUNT', 'Send at least one craft', 400, { context: 'craft' });
  }

  return db.transaction(async (tx) => {
    const origin = await loadLocked(tx, planetId, clock, { expectedPlayerId });
    assertWorldOperational(origin);
    assertOutsideSilentSpace(origin);

    const available = origin.homeFleet.PROSPECTOR ?? 0;
    if (available < craft) {
      throw new GameError('NOT_ENOUGH_CRAFT', `Only ${String(available)} Prospectors at home`, 400, {
        available,
      });
    }

    assertProspectorsUsable(origin.faults, planetId);
    await assertFreeBay(tx, planetId, origin.buildings.CORE, origin.faults);
    /*
      THE LANE THIS RULE EXISTS FOR. D183. A field over the commander's own world
      is a zero-length leg, so it is the salvage run that turns into tapping — but
      a rest earned there holds only the craft that flew it. Asteroid runs
      never earn a rest, regardless of their leg's length.
    */
    await assertProspectorsRested(tx, planetId, origin.now, available, craft);

    const [field] = await tx
      .select()
      .from(debrisFields)
      .where(and(eq(debrisFields.id, fieldId), eq(debrisFields.seasonId, origin.seasonId)));
    if (!field) throw new GameError('NO_SUCH_FIELD', 'No such wreck field', 404);

    const age = (origin.now.getTime() - field.createdAt.getTime()) / 60_000;
    if (
      !debrisAlive(
        field.alloy,
        field.crystal,
        field.deuterium,
        field.takenAlloy,
        field.takenCrystal,
        field.takenDeuterium,
        age,
      )
    ) {
      throw new GameError('FIELD_GONE', 'There is nothing left of it', 409);
    }

    /*
      THE FIELD'S OWN POSITION, NOT ITS WORLD'S. D150.

      This used to dereference `planetId` and read the coordinates off the planet
      row, which stopped being possible the moment a battle could happen in open
      space. The column is on the field for every kind of wreck, so this is one
      lookup fewer as well as one branch fewer.
    */
    const target = { x: field.x, y: field.y, z: field.z };

    const speed = prospectorSpeed(origin.orbit);
    const dist = distance(origin, target);
    // A harvest is the same craft on a different errand, so it flies by the same
    // rule as a mining run — mining's own launch overhead, not a warship's. D48.
    // Budget a laden return conservatively; arrival selects the actual speed
    // from the haul, so an empty craft flies home at normal speed. D117.
    const outbound = travelExact(dist, speed);
    const homeMinutes = travelExact(dist, prospectorReturnSpeed(origin.orbit, true));
    const arriveAt = addMinutes(origin.now, outbound);
    assertSeasonOpenThrough(origin, addMinutes(arriveAt, homeMinutes));
    const holdEach = prospectorHold(origin.orbit, await techOf(tx, origin.playerId));

    const [run] = await tx
      .insert(miningRuns)
      .values({
        seasonId: origin.seasonId,
        planetId,
        ownerPlayerId: origin.playerId,
        targetKind: 'debris',
        debrisFieldId: fieldId,
        craft,
        holdEach,
        interceptX: target.x,
        interceptY: target.y,
        interceptZ: target.z,
        departAt: origin.now,
        arriveAt,
      })
      .returning();

    const damage = await takeHomeHealth(tx, planetId, { PROSPECTOR: craft });
    const remaining = { ...origin.homeFleet, PROSPECTOR: available - craft };
    await setUnits(tx, planetId, remaining, 'home');
    await setUnits(tx, planetId, { PROSPECTOR: craft }, `mine:${run!.id}`);
    await tx.update(units).set({ damage }).where(and(eq(units.planetId, planetId), eq(units.location, `mine:${run!.id}`)));

    await schedule(tx, {
      seasonId: origin.seasonId,
      kind: 'mining_arrival',
      refId: run!.id,
      resolveAt: arriveAt,
    });

    /** A salvage run is a race for a public landmark, exactly like a rock. D53. */
    await publishShard(tx, origin.seasonId, 'mining');
    await publish(tx, origin.playerId, 'private:mining');

    return {
      runId: run!.id,
      craft,
      arriveAt,
      flightMinutes: outbound,
      intercept: { x: target.x, y: target.y, z: target.z },
      capacity: holdEach * craft,
      ...await launchViews(tx, origin, clock),
    };
  }).then(buildPlanetResult);
}

/**
 * KAZICI MERKEZİNDE ARIZA: THE PROSPECTORS STAY ON THE PAD. `PROSPECTOR_FAULT`.
 *
 * Guarded at the two LAUNCHES — a run at a rock and a run at a field — and at neither
 * of the two things that bring craft home. `recallMining` turns an outbound run round
 * and is deliberately left alone: calling your own craft back is not what a fault in
 * the pit should be able to prevent, and refusing it would strand them until a repair
 * finished.
 *
 * It sits BEFORE `assertFreeBay` on purpose. Both refuse the same launch, and the
 * first refusal is the one the player reads; "the pit is out" is the fact they can act
 * on, where "no free bay" would send them looking at a flight board that is fine.
 */
function assertProspectorsUsable(faults: FaultSet, planetId: string): void {
  if (!hasFault(faults, 'PROSPECTOR_FAULT')) return;
  throw new GameError(
    'FAULT_PROSPECTOR',
    'The prospecting pit is out. No craft can be worked until it is put right.',
    409,
    { planetId },
  );
}

sources.apps/server/src/services/mission.ts:
import { and, eq, gt, sql } from 'drizzle-orm';
import {
  ABUSE,
  MULTI_WORLD,
  canAttack,
  distance,
  allowedPaces,
  exposureMinutes,
  isMissionPace,
  engagementEndsAt,
  fleetCount,
  UNAIDED,
  fleetSpeed,
  fleetSpeedMult,
  fleetTravelExact,
  maxRadarRange,
  missionFuel,
  type Fleet,
  type HullId,
  HULLS,
  COMBAT_HULLS,
  splitHealthFleet,
} from '@astera/rules';
import { addMinutes, type Clock } from '../clock.js';
import type { Db, Tx } from '../db/client.js';
import {
  battleReports,
  buildings,
  missions,
  planets,
  players,
  seasons,
  units,
} from '../db/schema.js';
import { assertFreeBay } from './flight.js';
import { assertFuel } from './fuel.js';
import { assertPersonalRaidAvailable } from './personalRaid.js';
import {
  assertSeasonOpenThrough,
  assertWorldOperational,
  GameError,
  loadLocked,
  saveResources,
  setUnits,
} from './planet.js';
import {
  TIER_BAND_REFUSAL,
  assertAttackProtections,
  assertTierBand,
  assertWorldAttackable,
} from './attackProtection.js';
import { techOf } from './researchState.js';
import { schedule } from '../worker/queue.js';
import { publishReward, publishShard } from '../stream/bus.js';
import { pendingThreads, type PendingThread } from './session.js';
import { inboundRadarLead } from './radar.js';
import { loadPlanetViewData, buildPlanetResult, type PlanetView } from './planetView.js';
import { lockWorlds } from './ownership.js';
import { prepareClanAttack, recordClanAttack } from './clanCombat.js';
import { fleetChangesWatch, publishWatchChanges } from './watchEvents.js';
import { assertRadiationSafe } from './radiation.js';
import { assertOutsideSilentSpace, markProgress } from './waitingRoom.js';
import { takeHomeHealth } from './homeHealth.js';
import { commitHonor } from './honorCommitment.js';

export interface LaunchResult {
  missionId: string;
  arriveAt: Date;
  /** Minutes the origin planet is left weakened — the line the UI leads with. */
  exposureMinutes: number;
  homeDefenceAfter: number;
  /**
   * THE FLEET IS DRAWN ON THE FRAME THE ANSWER LANDS. D53.
   *
   * A launch used to answer with four numbers, and the squadron did not appear on
   * the disc until a second request came back with it — so the most committed act
   * in the game, the one thing that cannot be recalled, was followed by the disc
   * doing nothing for a round trip.
   *
   * Both lists come back instead, built inside the launching transaction and so
   * identical in shape to the payloads they replace in the cache: `pending`
   * because it holds the new flight, `planet` because the ships have left the home
   * stack and a bay is now in use.
   */
  pending: PendingThread[];
  planet: PlanetView;
}

/**
 * Launch an attack. IRREVERSIBLE — there is no recall.
 *
 * Units move from `home` to a row keyed by the mission id, so they are still
 * owned by the planet (and still counted in Wealth) but are demonstrably not
 * defending it. The mission's `fleet` jsonb is a snapshot for the battle report;
 * the `units` rows remain the single source of truth for ownership.
 */
export async function launchAttack(
  db: Db,
  originPlanetId: string,
  targetPlanetId: string,
  requested: Fleet,
  clock: Clock,
  expectedPlayerId?: string,
  /**
   * THE COMMANDER HAS BEEN TOLD THIS SPENDS THEIR OWN SHIELD, AND SAID YES. D183.
   *
   * Owner instruction: *"Kişi kendisi saldırı yapmak isterse uyarı verilir ve kabul
   * ederse kalkanı kalkar."* The shield is a POSITION rather than a gift — firing
   * gives it up — and a position spent without being offered is a position the
   * player did not choose to spend. So the launch refuses once with
   * `SHIELD_WOULD_DROP`, the surface asks, and the answer comes back here.
   *
   * It is not client-authored state: it grants nothing and decides nothing. It is
   * the player saying they have read the price.
   */
  acknowledgeShieldLoss?: boolean,
  /**
   * HOW FAST THE COMMANDER WANTS THIS TO ARRIVE. Owner decision, 2026-09-21.
   *
   * Omitted is full speed, which is what every launch flew before the choice existed. It is
   * validated against `allowedPaces` rather than merely against the ladder, because the ceiling
   * depends on THIS flight: the slowest rung is a legal choice for a neighbour and an illegal one
   * for a world across the disc.
   */
  pace?: number,
  /** The commander has read what radiation on this route would take (plan D10). */
  acknowledgeRadiation = false,
  adminUsernames: ReadonlySet<string> = new Set(),
): Promise<LaunchResult> {
  if (originPlanetId === targetPlanetId) {
    throw new GameError('SELF_ATTACK', 'You cannot attack your own planet');
  }
  // Structure first, semantics second: fleetCount() drops non-positive entries,
  // so checking it first would report a malformed request as an empty one.
  for (const [hull, n] of Object.entries(requested) as [HullId, number][]) {
    if (!Number.isInteger(n) || n < 0) {
      throw new GameError('BAD_FLEET', `Bad ship count for ${hull}`, 400, { hull });
    }
  }
  if (fleetCount(requested) === 0) {
    throw new GameError('EMPTY_FLEET', 'Send at least one ship');
  }

  // Reject role violations before opening a transaction. Besides preserving the
  // specific client-facing error, this makes malformed service calls as cheap as
  // route-level schema failures and keeps support-only checks away from storage.
  for (const [hull, n] of Object.entries(requested) as [HullId, number][]) {
    if (n === 0) continue;
    if (HULLS[hull].ground) {
      throw new GameError('GROUND_UNIT', `${HULLS[hull].name}s cannot travel`, 400, { hull });
    }
    if (hull === 'PROSPECTOR') {
      throw new GameError('NOT_A_WARSHIP', 'Prospectors mine; they do not raid');
    }
  }
  if (!COMBAT_HULLS.some((hull) => (requested[hull] ?? 0) > 0)) {
    throw new GameError('NOT_A_WARSHIP', 'An attack needs at least one combat hull', 400);
  }

  return db.transaction(async (tx) => {
    await lockWorlds(tx, [originPlanetId, targetPlanetId]);
    const origin = await loadLocked(tx, originPlanetId, clock, { expectedPlayerId });
    assertWorldOperational(origin);
    assertOutsideSilentSpace(origin);

    for (const [hull, n] of Object.entries(requested) as [HullId, number][]) {
      if ((origin.homeFleet[hull] ?? 0) < n) {
        throw new GameError('NOT_ENOUGH_SHIPS', `Not enough ${hull} at home`, 400, { hull });
      }
    }
    try { splitHealthFleet(origin.homeFleet, origin.homeDamage, requested, true); }
    catch (error) {
      if (!(error instanceof RangeError)) throw error;
      throw new GameError('NOT_ENOUGH_COMBAT_READY_SHIPS', 'Ships at 5% HP or below cannot join a combat mission', 409);
    }
    /*
      CAN THIS WING MOVE AT ALL — a question research cannot answer. D180.

      `UNAIDED.tech` deliberately: propulsion is a MULTIPLIER, so it can never lift
      a zero, and a ground-only or empty fleet is immobile at every rung of the
      ladder. Asked before the commander's research is loaded, and correct there.
      The pace that the arrival is actually built from reads the real tech below.
    */
    if (fleetSpeed(requested, UNAIDED.tech) <= 0) {
      throw new GameError('IMMOBILE_FLEET', 'That fleet cannot travel');
    }

    const [target] = await tx.select().from(planets).where(eq(planets.id, targetPlanetId));
    if (!target) throw new GameError('PLANET_NOT_FOUND', 'No such planet', 404);
    if (target.seasonId !== origin.seasonId) {
      throw new GameError('CROSS_SEASON', 'That planet is in another galaxy');
    }

    /**
     * ONE FLEET PER TARGET AT A TIME. Owner decision.
     *
     * Counted under the origin planet's lock, so two launches racing each other
     * cannot both see a clear board.
     *
     * Both legs count, and that is the point: sending a second wave while the first
     * is still in the air — or still coming home — turns a raid into a stream, which
     * defeats the bash limit (three hits per twelve hours is meaningless if all
     * three land in the same minute) and removes the decision the exposure window
     * exists to create. Commit, then wait to find out. That is the game.
     */
    // Bays first: "you have nothing free" is a truer refusal than "not at that
    // target", and it is the one the player can act on. D28.
    await assertFreeBay(tx, originPlanetId, origin.buildings.CORE, origin.faults);

    const alreadyOut = await tx
      .select({ id: missions.id })
      .from(missions)
      .where(
        and(
          eq(missions.status, 'in_flight'),
          eq(missions.kind, 'attack'),
          eq(missions.originPlanetId, originPlanetId),
          eq(missions.targetPlanetId, targetPlanetId),
        ),
      )
      .limit(1);

    const comingBack = await tx
      .select({ id: missions.id })
      .from(missions)
      .where(
        and(
          eq(missions.status, 'in_flight'),
          eq(missions.kind, 'return'),
          // A return leg flies backwards: its origin is the planet that was raided.
          eq(missions.originPlanetId, targetPlanetId),
          eq(missions.targetPlanetId, originPlanetId),
        ),
      )
      .limit(1);

    if (alreadyOut.length > 0 || comingBack.length > 0) {
      throw new GameError(
        'FLEET_ALREADY_COMMITTED',
        'You already have a fleet committed to that planet',
        409,
      );
    }

    const [me] = await tx.select().from(players).where(eq(players.id, origin.playerId));
    if (!me) throw new GameError('PLAYER_NOT_FOUND', 'No such player', 404);
    assertWorldAttackable(target, origin.now);
    const [them] = target.controllerPlayerId
      ? await tx.select().from(players).where(eq(players.id, target.controllerPlayerId))
      : [];
    if (target.kind !== 'NEUTRAL' && !them) {
      throw new GameError('PLAYER_NOT_FOUND', 'No such player', 404);
    }

    /**
     * THE FIRST DAY IS SAFE, AND SO IS THE HOUR AFTER A BEATING. D183 · 2026-09-14.
     *
     * TWO REFUSALS, AND THE TARGET'S COMES FIRST. Accepting the loss of your own
     * shield to hit somebody who cannot be hit would spend a day of protection for
     * nothing: the launch is refused either way, and the honest refusal is the one
     * about them.
     *
     * BOTH ARE RAISED BEFORE ANYTHING IS SPENT — no fuel debited, no bay taken, no
     * ships off the stack — for the same reason D168's band is: a refusal that costs
     * something is a punishment for asking a question.
     *
     * THE SHIELD IS SPENT, NOT PAUSED, AND BOTH ARE SPENT TOGETHER. Writing null
     * rather than a past instant is what makes "has this commander committed to the
     * war" a presence rather than a date comparison, and it is why the first day
     * never comes back. The recovery window goes with it in the same update: a
     * commander who fires has committed, and keeping half a shield by owning two
     * kinds of it is not a position anybody should be able to hold.
     *
     * NEUTRAL WORLDS ARE OUTSIDE IT ENTIRELY. There is no commander to protect and
     * none to charge — a caretaker world is scenery with a garrison, and settling
     * is not the reaching-out this rule is about.
     */
    await assertAttackProtections(tx, {
      attackerPlayerId: me.id,
      defenderPlayerId: target.kind === 'NEUTRAL' ? null : (them?.id ?? null),
      now: origin.now,
      acknowledgeShieldLoss: acknowledgeShieldLoss ?? false,
    });

    /**
     * THE BAND IS MEASURED ON THE TWO COMMANDERS, AND IT IS ASKED FIRST. D168.
     *
     * Not on the pad and not on the target: `peakCoreLevels` reads the tallest
     * Core each side holds anywhere, because a planet-measured band is bought off
     * with an undeveloped colony (see `canAttack`). Both readings are UNLOCKED on
     * purpose — a Core upgrade landing in the same instant can only move a
     * commander one level, the tier is a three-level bucket, and locking another
     * commander's worlds here would introduce exactly the two-planet lock ordering
     * the architecture rules forbid.
     *
     * IT RUNS BEFORE `prepareClanAttack` FOR TWO REASONS. The refusal it produces
     * is permanent, and `prepareClanAttack` raises the temporary one — a player
     * told to wait out a twelve-hour bash window that will not make the fight
     * legal is sent away and comes back for the same no. And it takes advisory
     * locks on both commanders and both clans, which is work nobody should pay for
     * on a launch that was never going to be allowed.
     *
     * WHAT THIS COSTS, STATED BECAUSE D127 REMOVED THE BAND FOR IT: development is
     * private, so this is a rule the player cannot fully check before committing.
     * The refusal is therefore raised BEFORE anything is spent — no fuel is
     * debited, no bay is taken, no ships leave the stack — and the client is told
     * which rule refused. The surface half lives in the client: the dossier's
     * development row states the caller's own tier and the range it reaches, and
     * `lib/band.ts` disables the launch when the disc already proves the refusal.
     */
    let preparedClanAttack: Awaited<ReturnType<typeof prepareClanAttack>> | null = null;
    if (target.kind !== 'NEUTRAL' && them) {
      const { attackerPeak, defenderPeak } = await assertTierBand(tx, me.id, them.id);
      await assertPersonalRaidAvailable(tx, {
        attackerPlayerId: me.id, defenderPlayerId: them.id,
        attackerPeak, defenderPeak, now: origin.now,
      });

      const [ruleset] = await tx.select({ version: seasons.rulesetVersion })
        .from(seasons).where(eq(seasons.id, origin.seasonId));
      let personalRecent: number;
      if ((ruleset?.version ?? 0) >= MULTI_WORLD.clanRulesetVersion) {
        preparedClanAttack = await prepareClanAttack(tx, {
          seasonId: origin.seasonId,
          attackerPlayerId: me.id,
          targetPlayerId: them.id,
          now: origin.now,
        });
        personalRecent = preparedClanAttack.personalRecent;
      } else {
        // Ruleset-v2 seasons retain their report-time bash semantics. D114 is a
        // fresh-season boundary and must not alter fights already under way.
        const since = addMinutes(origin.now, -ABUSE.bashWindowMinutes);
        const [recent] = await tx
          .select({ n: sql<number>`count(*)::int` })
          .from(battleReports)
          .where(and(
            eq(battleReports.attackerPlayerId, me.id),
            eq(battleReports.defenderPlayerId, them.id),
            gt(battleReports.createdAt, since),
          ));
        personalRecent = recent?.n ?? 0;
      }
      /*
        THE SAME FUNCTION AGAIN, NOW THAT THE COUNT IS KNOWN. The band is asked
        twice and answers the same both times; what this call adds is the bash
        limit, and it is asked THROUGH `canAttack` rather than compared here so
        the rule keeps one statement. `prepareClanAttack` raises its own
        `BASH_LIMIT` on the clan path before this is reached.
      */
      const gate = canAttack(
        { playerId: me.id, peakCoreLevel: attackerPeak },
        { playerId: them.id, peakCoreLevel: defenderPeak },
        personalRecent,
      );
      if (!gate.ok) {
        throw new GameError(gate.reason ?? 'FORBIDDEN', describeRefusal(gate.reason), 403);
      }
    }

    const dist = distance(origin, target);
    /**
     * THE ROUND TRIP, PAID BEFORE IT LEAVES. T6 — owner instruction.
     *
     * Both legs, at launch, because a fleet in the air has no access to a store.
     * A one-way budget is not a cheaper raid, it is a stranded fleet — and P3 says
     * a launched fleet cannot be recalled, so there is no way back out of that.
     *
     * NO SYSTEM PATH EVER ASKS FOR MORE AND NO CANCELLATION EVER GIVES ANY BACK.
     * A rerouted leg may fly further than the one that was paid for, and
     * `abandon()` hands back units without a refund; both are system faults rather
     * than player decisions, and charging or refunding for them would make the
     * quote on this screen a lie. Written here because it is the kind of asymmetry
     * somebody tidies up later without knowing why it was chosen.
     */
    /**
     * THE PACE IS CHECKED AGAINST THIS FLIGHT, NOT AGAINST THE LADDER, AND BEFORE THE TANK.
     *
     * `allowedPaces` answers both questions at once — is this a rung at all, and does it land
     * inside the ceiling — so the two refusals stay distinguishable to the surface while sharing
     * one source of truth. It runs ahead of `assertFuel` because an order that was never legal
     * should not come back as "you cannot afford it": the commander would go and buy deuterium.
     */
    const mods = { boost: fleetSpeedMult(origin.orbit), tech: await techOf(tx, origin.playerId) };
    const chosenPace = pace ?? 1;
    if (!isMissionPace(chosenPace)) {
      throw new GameError('BAD_PACE', 'that is not a flight speed this fleet can be set to', 400);
    }
    if (!allowedPaces(dist, requested, mods).includes(chosenPace)) {
      throw new GameError(
        'PACE_TOO_SLOW',
        'at that speed the fleet would be in the air past the twelve-hour ceiling',
        400,
      );
    }

    const fuel = missionFuel(requested, dist, 2, 'HOSTILE', chosenPace);
    // A raid carries no hold on the way out, so the whole store is the tank.
    assertFuel(fuel, origin.deuterium);
    // The Beacon in orbit, if there is one. D25.
    const tech = mods.tech;
    const oneWay = fleetTravelExact(dist, requested, { ...mods, pace: chosenPace });
    const arriveAt = addMinutes(origin.now, oneWay);
    const resolveAt = new Date(engagementEndsAt(arriveAt.getTime()));
    // Home at the same pace it went out (owner, 2026-10-06): the round trip is two equal legs.
    const homeward = fleetTravelExact(dist, requested, { ...mods, pace: chosenPace });
    const homeAt = addMinutes(resolveAt, homeward);
    await assertRadiationSafe(tx, {
      seasonId: origin.seasonId, from: origin, to: target, departAt: origin.now, arriveAt,
      fleet: requested, tech, acknowledged: acknowledgeRadiation,
      damage: splitHealthFleet(origin.homeFleet, origin.homeDamage, requested, true).selectedDamage,
      path: [
        { from: origin, to: target, startMs: origin.now.getTime(), endMs: arriveAt.getTime() },
        { from: target, to: target, startMs: arriveAt.getTime(), endMs: resolveAt.getTime() },
        { from: target, to: origin, startMs: resolveAt.getTime(), endMs: homeAt.getTime() },
      ],
    });
    /**
     * THE ENGAGEMENT. D44.
     *
     * The fleet is over the target at `arriveAt`; the battle is settled ten
     * seconds later. Only the RESOLUTION moves — `arriveAt` is what both sides
     * read, what the radar counts down to, and what the client flies the craft
     * against, and moving it would have quietly rewritten the ETA of every raid
     * in the game to pay for a piece of theatre.
     *
     * The mission stays `in_flight` across the window, which is the honest state:
     * the ships are committed, nothing is decided, and every guard that reads
     * `in_flight` — one fleet per target, the flight bay, the reaper — keeps
     * holding for exactly as long as the fleet is actually there.
     */
    // The survivors fly home at the pace that went out (owner, 2026-10-06), so the season's end
    // is measured on that same slow way back.
    assertSeasonOpenThrough(origin, homeAt);

    const [mission] = await tx
      .insert(missions)
      .values({
        fuelPaid: fuel,
        seasonId: origin.seasonId,
        kind: 'attack',
        /*
          FROZEN HERE, READ AT THE BATTLE. T9.

          What this commander had researched when they committed, never what they
          finished while the fleet was in the air. The defender's doctrines are
          read at the moment of the fight instead — the same asymmetry the radar
          already has, and the same reason: every figure belongs to the moment its
          own decision was made.
        */
        tech,
        ownerPlayerId: origin.playerId,
        originPlanetId,
        targetPlanetId,
        fleet: requested,
        distance: dist,
        pace: chosenPace,
        departAt: origin.now,
        arriveAt,
      })
      .returning();
    await markProgress(tx, origin.playerId, origin.now); // D212

    if (them && preparedClanAttack) {
      await recordClanAttack(tx, {
        ...preparedClanAttack,
        missionId: mission!.id,
        seasonId: origin.seasonId,
        attackerPlayerId: me.id,
        targetPlayerId: them.id,
        now: origin.now,
      });
    }

    // Move the ships off the home stack, in the same transaction.
    const carriedDamage = await takeHomeHealth(tx, originPlanetId, requested, true);
    await tx.update(missions).set({ damage: carriedDamage.length ? carriedDamage : null }).where(eq(missions.id, mission!.id));
    const remaining: Fleet = { ...origin.homeFleet };
    for (const [hull, n] of Object.entries(requested) as [HullId, number][]) {
      remaining[hull] = (remaining[hull] ?? 0) - n;
    }
    await setUnits(tx, originPlanetId, remaining, 'home');
    await setUnits(tx, originPlanetId, requested, mission!.id);
    // Burned in the same transaction the ships leave in. T6.
    if (fuel > 0) {
      await saveResources(tx, originPlanetId, {
        alloy: origin.alloy,
        crystal: origin.crystal,
        deuterium: origin.deuterium - fuel,
      });
    }

    await schedule(tx, {
      seasonId: origin.seasonId,
      kind: 'mission_arrival',
      refId: mission!.id,
      resolveAt,
    });

    /**
     * THE RADAR WARNING IS SCHEDULED FOR EVERY RAID, AND ITS LEVEL IS READ LATER. D45.
     *
     * D9 is unchanged: the warning fires at `arriveAt − lead`, never at launch.
     * What changed is WHOSE LEVEL decides the lead, and when it is read.
     *
     * This used to read the target's radar here and freeze the answer into the
     * event's payload, which was wrong in both directions and measurably so. A
     * defender with no radar got no event at all, so buying one while a fleet was
     * in the air bought nothing — while `pendingThreads`, which reads the live
     * level, put "inbound fleet" on their strip. Two surfaces, one fact, opposite
     * answers. And a defender who raised Radar 3 → 5 mid-flight was warned with an
     * L3 payload: no size estimate, no composition, for a ladder rung they had
     * already paid for.
     *
     * So the event is now scheduled at the earliest instant ANY radar could fire —
     * the moment the drawn fleet crosses inside the WIDEST reach the ladder sells — and
     * `onRadarWarning` reads the level at the moment it runs, hopping down
     * `RADAR_RANGES` if the defender has not earned the reach it is holding. One
     * event per raid instead of one per radar-equipped target; at 351 worlds that
     * distinction is load-bearing.
     *
     * D49 MADE THAT INSTANT DEPEND ON THIS FLEET. A radar is a circle now, so when
     * a raid crosses it is a function of the leg and of the speed the attacker
     * chose — which is the entire point, and why the widest crossing is computed
     * here rather than being one constant subtracted from every arrival.
     */
    const [radarTargetCore] = await tx
      .select({ level: buildings.level })
      .from(buildings)
      .where(and(eq(buildings.planetId, targetPlanetId), eq(buildings.type, 'CORE')))
      .limit(1);
    const warnAt = addMinutes(arriveAt, -inboundRadarLead(maxRadarRange(), {
      from: origin,
      to: target,
      originCoreLevel: origin.buildings.CORE,
      targetCoreLevel: radarTargetCore?.level ?? 1,
      oneWayMinutes: oneWay,
    }));
    await schedule(tx, {
      seasonId: origin.seasonId,
      kind: 'radar_warning',
      refId: mission!.id,
      resolveAt: warnAt > origin.now ? warnAt : origin.now,
    });

    /**
     * AND THE GALAXY IS TOLD, THE MOMENT IT LEAVES. D53.
     *
     * A departure is public — it has been since D24 — and until now it reached
     * everybody else on a twenty-second poll. A short hop had covered a fifth of
     * its leg before anybody but its owner knew it existed, which is precisely how
     * a galaxy of fifty real people comes to read as empty.
     *
     * The payload names no world, no owner and no heading; it says a launch
     * happened here, and every client goes and reads `/api/traffic` — the same
     * fog-enforced query the poll was going to read anyway, sooner.
     */
    await publishShard(tx, origin.seasonId, 'launch');
    await publishReward(tx, origin.playerId);
    if (fleetChangesWatch(requested)) await publishWatchChanges(tx, [originPlanetId]);

    await commitHonor(tx, { seasonId: origin.seasonId, source: 'WORLD', id: mission!.id,
      attack: [me.id], defence: them ? [them.id] : [], at: origin.now, adminUsernames });

    const homeDefenceAfter =
      fleetCount(remaining) + fleetCount(origin.ground);

    return {
      missionId: mission!.id,
      arriveAt,
      // Out and home at the chosen pace: two equal legs (owner, 2026-10-06).
      exposureMinutes: exposureMinutes(oneWay, homeward),
      homeDefenceAfter,
      /**
       * Built by the SAME function the GET route uses, deliberately. A hand-rolled
       * thread here would be a second definition of a shape the disc interpolates
       * against, and the first time the two drifted the squadron would jump the
       * moment the next refetch landed.
       */
      pending: await pendingThreads(tx, originPlanetId, origin.now),
      planet: await loadPlanetViewData(tx, originPlanetId, clock),
    };
  }).then(buildPlanetResult);
}

function describeRefusal(reason?: string): string {
  switch (reason) {
    case 'BASH_LIMIT':
      return 'You have hit this planet too many times recently';
    case 'SELF':
      return 'You cannot attack your own planet';
    case 'TIER_BAND':
    case 'TIER_BAND_WEAK':
      return TIER_BAND_REFUSAL[reason];
    default:
      return 'You cannot attack that planet';
  }
}

/** Ships belonging to a mission, read from the authoritative units rows. */
export async function fleetOfMission(tx: Tx, planetId: string, missionId: string): Promise<Fleet> {
  const rows = await tx
    .select()
    .from(units)
    .where(and(eq(units.planetId, planetId), eq(units.location, missionId)));
  const fleet: Fleet = {};
  for (const r of rows) if (r.count > 0) fleet[r.hull] = r.count;
  return fleet;
}

export async function clearMissionUnits(tx: Tx, planetId: string, missionId: string): Promise<void> {
  await tx.delete(units).where(and(eq(units.planetId, planetId), eq(units.location, missionId)));
}

