import { MONUMENT_BALANCE, RADIATION_SHIELDING_RULESET } from '@astera/rules';

interface RadiationSeason {
  rulesetVersion: number;
  startsAt: Date;
  monumentRadiationStartsAt?: Date | null;
}

export const monumentRadiationStart = (season: RadiationSeason): Date | undefined =>
  season.monumentRadiationStartsAt ?? (season.rulesetVersion >= RADIATION_SHIELDING_RULESET ? season.startsAt : undefined);

export const LEGACY_MONUMENT_HP_PER_MINUTE = { EASY: 2, HARD: 5 } as const;

/** Only explicit old-season seeding retains the original 2/5 HP/min source rates. */
export const monumentBaseRadiation = (difficulty: 'EASY' | 'HARD', season: RadiationSeason) => ({
  radiationLevel: MONUMENT_BALANCE[difficulty].radiationLevel,
  intensityHpPerMinute: monumentRadiationStart(season)
    ? MONUMENT_BALANCE[difficulty].intensityHpPerMinute : LEGACY_MONUMENT_HP_PER_MINUTE[difficulty],
});

import { and, eq, gt, inArray, isNull, or } from 'drizzle-orm';
import { hpRadiationApplies, MONUMENT_BALANCE } from '@astera/rules';
import type { Clock } from '../clock.js';
import type { Db } from '../db/client.js';
import { clanWarOperations, hpRadiationSources, monumentProbes, monuments, monumentWaves, seasons } from '../db/schema.js';
import { publishShard } from '../stream/bus.js';
import { GameError } from './planet.js';
import { monumentMotionStart } from './monumentMotion.js';
import { LEGACY_MONUMENT_HP_PER_MINUTE, monumentRadiationStart } from './monumentRadiation.js';

/** Same season barrier as dispatch; historical windows and unrelated emitters stay intact. */
export async function activateMonumentRadiation(db: Db, input: { seasonId: string; clock: Clock; apply: boolean }) {
  return db.transaction(async tx => {
    const [season] = await tx.select().from(seasons).where(eq(seasons.id, input.seasonId)).for('update');
    const now = input.clock.now();
    if (season?.status !== 'live' || now < season.startsAt || now >= season.endsAt || season.closedAt
      || !hpRadiationApplies(season.rulesetVersion)) throw new GameError('SEASON_FROZEN', 'An open monument season is required', 409);
    if (!monumentMotionStart(season)) throw new GameError('MONUMENT_MOTION_REQUIRED', 'Activate monument motion and entity radiation first', 409);
    const start = monumentRadiationStart(season);
    const emptyCounts = { fleets: 0, probes: 0, operations: 0, monuments: 0 };
    if (start) return { status: 'ALREADY_ACTIVE' as const, applied: false, startsAt: start, ...emptyCounts };
    const [fleets, probes, operations] = await Promise.all([
      tx.select({ id: monumentWaves.id }).from(monumentWaves).where(and(eq(monumentWaves.seasonId, season.id), inArray(monumentWaves.status, ['OUTBOUND', 'HOLD', 'RETURNING']))),
      tx.select({ id: monumentProbes.id }).from(monumentProbes).where(and(eq(monumentProbes.seasonId, season.id), inArray(monumentProbes.status, ['OUTBOUND', 'RETURNING']))),
      tx.select({ id: clanWarOperations.id }).from(clanWarOperations).where(and(eq(clanWarOperations.seasonId, season.id), eq(clanWarOperations.targetKind, 'MONUMENT'),
        inArray(clanWarOperations.status, ['ASSEMBLING', 'ATTACKING', 'RETURNING']))),
    ]);
    const counts = { ...emptyCounts, fleets: fleets.length, probes: probes.length, operations: operations.length };
    if (fleets.length || probes.length || operations.length) return { status: 'BUSY' as const, applied: false, startsAt: now, ...counts };
    const targets = await tx.select().from(monuments).where(eq(monuments.seasonId, season.id));
    const sources = await tx.select().from(hpRadiationSources).where(and(eq(hpRadiationSources.seasonId, season.id),
      eq(hpRadiationSources.anchorKind, 'MONUMENT'), or(isNull(hpRadiationSources.activeUntil), gt(hpRadiationSources.activeUntil, now))));
    if (targets.length === 0) throw new GameError('MONUMENT_NOT_FOUND', 'This galaxy has no monuments', 409);
    const replacements = targets.map(target => {
      if (target.difficulty === 'LEGACY') throw new GameError('MONUMENT_RADIATION_INVALID', 'Adopt the Easy/Hard monument layout first', 409);
      const difficulty = target.difficulty;
      const balance = MONUMENT_BALANCE[difficulty];
      // A still-running old image may have seeded after the metadata migration.
      // Recognize only the authored legacy identity AND its old rate, not arbitrary auras.
      const base = sources.filter(source => source.anchorId === target.id && (source.radiationLevel !== null
        || (source.mode === 'EMIT' && source.label === `Monument ${String(target.ordinal)} cloud`
          && source.intensityHpPerMinute === LEGACY_MONUMENT_HP_PER_MINUTE[difficulty])));
      if (base.length !== 1 || (base[0]!.radiationLevel !== null && base[0]!.radiationLevel !== balance.radiationLevel) || base[0]!.activeFrom > now) {
        throw new GameError('MONUMENT_RADIATION_INVALID', 'Each monument requires exactly one current base radiation source', 409);
      }
      return { source: base[0]!, rate: balance.intensityHpPerMinute, radiationLevel: balance.radiationLevel };
    });
    if (input.apply) {
      for (const { source, rate, radiationLevel } of replacements) {
        await tx.update(hpRadiationSources).set({ activeUntil: now }).where(eq(hpRadiationSources.id, source.id));
        await tx.insert(hpRadiationSources).values({ seasonId: source.seasonId, anchorKind: source.anchorKind, anchorId: source.anchorId,
          x: source.x, y: source.y, z: source.z, radius: source.radius, mode: source.mode, radiationLevel,
          intensityHpPerMinute: rate, activeFrom: now, activeUntil: null, label: source.label });
      }
      await tx.update(seasons).set({ monumentRadiationStartsAt: now }).where(eq(seasons.id, season.id));
      await publishShard(tx, season.id, 'control');
    }
    return { status: 'READY' as const, applied: input.apply, startsAt: now, ...counts, monuments: targets.length };
  });
}

import { randomUUID } from 'node:crypto';
import type { MonumentShipLot } from '@astera/rules';
import type { Tx } from '../db/client.js';
import { publish } from '../stream/bus.js';
import { notify } from './notifications.js';

/** Only newly destroyed physical cohorts enter this function; the paid cursor prevents replay. */
export async function tellMonumentRadiationLoss(tx: Tx, target: { id: string; ordinal: number },
  wave: { id: string; playerId: string }, destroyed: readonly MonumentShipLot[], survivors: readonly MonumentShipLot[], at: Date,
  silentFrom?: Date | null) {
  if (destroyed.length === 0) return;
  if (silentFrom && at >= silentFrom) {
    await publish(tx, wave.playerId, 'private:monument');
    return;
  }
  await notify(tx, { playerId: wave.playerId, kind: 'radiation_lost', refId: randomUUID(), at,
    payload: { targetKind: 'MONUMENT', monumentId: target.id, monumentOrdinal: target.ordinal, waveId: wave.id,
      lost: destroyed.reduce((sum, lot) => sum + lot.count, 0), left: survivors.reduce((sum, lot) => sum + lot.count, 0),
      lostDeuterium: destroyed.reduce((sum, lot) => sum + lot.deuterium, 0),
      lostFuel: destroyed.reduce((sum, lot) => sum + (lot.returnFuelReserve ?? 0) + (lot.fuelRefund ?? 0), 0) } });
  await publish(tx, wave.playerId, 'private:monument');
}

import { and, eq, inArray } from 'drizzle-orm';
import type { Clock } from '../clock.js';
import type { Db } from '../db/client.js';
import { clanWarOperations, monumentProbes, monuments, monumentWaves, seasons } from '../db/schema.js';
import { GameError, recomputePlayerWealth } from './planet.js';
import { landMonumentFleets } from './monumentSeasonClose.js';
import { scheduleHoldBoundary } from './monumentBoundaries.js';
import { publishShard } from '../stream/bus.js';

/**
 * OWNER-AUTHORIZED MAINTENANCE RECALL IN A LIVE SEASON (2026-10-16).
 *
 * The idle monument cutovers refuse while any fleet is out at a monument, and a held fleet never
 * comes home on its own. Under maintenance this lands every monument fleet at its owner's safe
 * home through the same delivery the season close uses: ships keep their health, carried
 * Deuterium and the unspent return reserve go into stock, and the owner gets the ordinary
 * "fleet returned" receipt. The SEASON STAYS OPEN: nothing is frozen and no lifecycle event is
 * deleted — the generation bump turns the old arrival/loss events into no-ops, and a vacated
 * monument follows the ordinary empty → 24 h garrison rule.
 *
 * Probes and clan operations are not recalled: their presence refuses the run without writes.
 */
export async function recallMonumentFleets(db: Db, input: {
  seasonId: string; clock: Clock; apply: boolean; adminUsernames: readonly string[];
}) {
  return db.transaction(async tx => {
    const [season] = await tx.select().from(seasons).where(eq(seasons.id, input.seasonId)).for('update');
    const now = input.clock.now();
    if (season?.status !== 'live' || season.closedAt || now < season.startsAt || now >= season.endsAt) {
      throw new GameError('SEASON_FROZEN', 'An open season is required', 409);
    }
    const fleets = await tx.select({ id: monumentWaves.id }).from(monumentWaves).where(and(eq(monumentWaves.seasonId, season.id),
      inArray(monumentWaves.status, ['OUTBOUND', 'HOLD', 'RETURNING'])));
    const probes = await tx.select({ id: monumentProbes.id }).from(monumentProbes).where(and(eq(monumentProbes.seasonId, season.id),
      inArray(monumentProbes.status, ['OUTBOUND', 'RETURNING'])));
    const operations = await tx.select({ id: clanWarOperations.id }).from(clanWarOperations).where(and(eq(clanWarOperations.seasonId, season.id),
      eq(clanWarOperations.targetKind, 'MONUMENT'), inArray(clanWarOperations.status, ['ASSEMBLING', 'ATTACKING', 'RETURNING'])));
    const counts = { fleets: fleets.length, probes: probes.length, operations: operations.length };
    if (probes.length || operations.length) return { status: 'BUSY' as const, applied: false, at: now, ...counts };
    if (fleets.length === 0) return { status: 'IDLE' as const, applied: false, at: now, ...counts };
    if (!input.apply) return { status: 'READY' as const, applied: false, at: now, ...counts };

    const landed = await landMonumentFleets(tx, { seasonId: season.id, cutoff: now, observedAt: now,
      adminUsernames: input.adminUsernames, closing: false });
    for (const target of landed?.locked ?? []) {
      const m = target.monument;
      if (m.controllerPlayerId === null && m.controllerClanId === null) continue;
      m.controllerPlayerId = null;
      m.controllerClanId = null;
      m.emptySince = now;
      m.generation += 1;
      await tx.update(monuments).set({ controllerPlayerId: null, controllerClanId: null, emptySince: now, generation: m.generation })
        .where(eq(monuments.id, m.id));
      await scheduleHoldBoundary(tx, target, null);
    }
    for (const playerId of landed?.owners ?? []) await recomputePlayerWealth(tx, playerId, now);
    await publishShard(tx, season.id, 'control');
    return { status: 'READY' as const, applied: true, at: now, ...counts };
  });
}

