import { createHmac, timingSafeEqual } from 'node:crypto';
import { eq } from 'drizzle-orm';
import {
  MULTI_WORLD,
  activePirates,
  dynamicPirateHourOf,
  generatePirateHour,
  generatePirateSchedule,
  pirateDiscovered,
  remainingPirateLoot,
  type Fleet,
  type PirateHourLane,
  type HullId,
  type PirateLaneStage,
  type PirateSpec,
  type SensorEpoch,
  type Resources,
} from '@astera/rules';
import { minutesSince } from '../clock.js';
import { GameError } from './planet.js';
import { pirateState, seasons } from '../db/schema.js';
import { applySpawnGate } from './spawnGateRead.js';
import type { Queryable } from '../db/client.js';
import { loadPirateHour, loadPirateHours } from './asteroidSpawn.js';

/**
 * THE SEASON'S PIRATE LANE, KEYED BY A SECRET THAT NEVER CROSSES THE API. D150.
 *
 * The mirror of `asteroidField.ts`, and the mirroring is deliberate: both are
 * derived server-private schedules addressed through opaque handles, so a second
 * shape here would be a second set of leaks to find. `packages/rules` may not
 * import `crypto` (A1), so the keyed determinism is injected from this side and
 * the pure generator is handed an ordinary function.
 *
 * AND SINCE D158 THE MIRRORING GOES ALL THE WAY. A rock is REMEMBERED once seen
 * (`sensor_epochs`, D143) and a pirate now is too, on the owner's instruction and
 * reversing D150's refusal — which used to be written in this very paragraph. The
 * memory is the SAME rows and the same solve (`discoveredPirateIndexes` below), so
 * the two lanes cannot answer the discovery question differently.
 *
 * AND SINCE D160 IT BUYS THE MANIFEST TOO. `pirateZone` floors a discovered pirate
 * at IDENTIFIED, not at CONTACT — this paragraph said the opposite until the floor
 * moved, and a stale docblock about fog is worse than none. It is safe because
 * `sensor_epochs.reach` is the TELESCOPE radius alone (`refreshSensorEpoch`): a
 * discovered pirate is one this commander already counted the crew of, so memory
 * hands back a reading they bought. A pirate no telescope ever held is untouched —
 * CONTACT inside a radar circle, nothing outside every circle.
 *
 * THE LANE IS DERIVED FROM THE SEASON'S EXISTING SECRET under its own HMAC
 * labels. A separate key column would have been a migration for no gain: distinct
 * labels already give each lane independent draws, so raising the pirate rate
 * cannot move a single rock — or a single already-drawn pirate — and vice versa.
 */

function keyedRng(key: string, label = 'pirate:draw'): () => number {
  let counter = 0;
  return () => {
    const value = createHmac('sha256', key)
      .update(`${label}:${String(counter)}`)
      .digest()
      .readUInt32BE(0);
    counter += 1;
    return value / 0x1_0000_0000;
  };
}

const fieldCache = new Map<string, PirateSpec[]>();
const idCache = new Map<string, Map<string, number>>();
const CACHE_MAX = 32;

function trim<K, V>(cache: Map<K, V>): void {
  while (cache.size > CACHE_MAX) {
    const oldest = cache.keys().next().value;
    if (oldest === undefined) return;
    cache.delete(oldest);
  }
}

/**
 * The whole lane for this season key. LRU-32, because generation is not free.
 *
 * ONE KEYED STREAM PER LANE, under its own HMAC label. Distinct labels are what
 * make the three lanes independent: raising density appends draws that no earlier
 * lane can see, so a live pirate's orbit, roster and hoard cannot move.
 */
export function privatePirateField(
  key: string,
  stage: PirateLaneStage = 'ALL',
): PirateSpec[] {
  const cacheKey = `${key}:${stage}`;
  const cached = fieldCache.get(cacheKey);
  if (cached) {
    fieldCache.delete(cacheKey);
    fieldCache.set(cacheKey, cached);
    return cached;
  }
  const field = generatePirateSchedule(keyedRng(key), undefined, 0, 0, {
    rngForIncrease: keyedRng(key, 'pirate:spawn-increase:v1'),
    rngForSurge: keyedRng(key, 'pirate:spawn-surge:v1'),
    stage,
  });
  fieldCache.set(cacheKey, field);
  trim(fieldCache);
  return field;
}

const hourCache = new Map<string, PirateSpec[]>();

/**
 * THE PIRATES OF ONE STORED HOUR (ruleset 9). Keyed by the season secret, the hour
 * and its lane — the complete input — under a label no derived lane uses, so a
 * dynamic pirate cannot share a draw with anything else in the season.
 */
export function privatePirateHour(
  key: string,
  hour: { hourOrdinal: number; lane: PirateHourLane },
): PirateSpec[] {
  const cacheKey = `${key}:${String(hour.hourOrdinal)}:${JSON.stringify(hour.lane)}`;
  const cached = hourCache.get(cacheKey);
  if (cached) {
    hourCache.delete(cacheKey);
    hourCache.set(cacheKey, cached);
    return cached;
  }
  const pirates = generatePirateHour({
    hourOrdinal: hour.hourOrdinal,
    lane: hour.lane,
    rng: keyedRng(key, `pirate:dynamic:v1:${String(hour.hourOrdinal)}`),
  });
  hourCache.set(cacheKey, pirates);
  while (hourCache.size > 256) {
    const oldest = hourCache.keys().next().value;
    if (oldest === undefined) break;
    hourCache.delete(oldest);
  }
  return pirates;
}

/** Does this season spawn pirates per active commander rather than per seat? */
export const dynamicPirates = (season: { rulesetVersion: number }): boolean =>
  season.rulesetVersion >= MULTI_WORLD.dynamicPirateRulesetVersion;

/**
 * ONE PIRATE BY ITS INDEX, WHEREVER IT CAME FROM. For the reads that hold a raid's
 * `pirate_index` and nothing else — a report, the flight strip, a raid resolving
 * long after the snapshot moved on. A derived index is a position in the season's
 * lane; a dynamic one names its hour, and only that hour's row is read.
 */
export async function pirateSpecAt(
  db: Queryable,
  seasonId: string,
  index: number,
): Promise<PirateSpec | undefined> {
  const [season] = await db.select().from(seasons).where(eq(seasons.id, seasonId));
  if (!season) return undefined;
  const hourOrdinal = dynamicPirateHourOf(index);
  if (hourOrdinal === null) {
    return dynamicPirates(season) ? undefined : privatePirateField(season.asteroidKey)[index];
  }
  if (!dynamicPirates(season)) return undefined;
  const lane = await loadPirateHour(db, season, hourOrdinal);
  if (lane === null) return undefined;
  return privatePirateHour(season.asteroidKey, { hourOrdinal, lane })
    .find((spec) => spec.index === index);
}

/** Stable 128-bit public handle; the raw lane index is never serialised. */
export function pirateId(key: string, index: number): string {
  return createHmac('sha256', key)
    .update(`pirate:id:${String(index)}`)
    .digest()
    .subarray(0, 16)
    .toString('base64url');
}

/**
 * A SHORT NAME A PLAYER CAN SAY OUT LOUD, taken from the opaque id.
 *
 * "Korsan L3-7" would read better and would also be a running count of how many
 * level 3 pirates the season has produced — the schedule leaking through the copy
 * rather than through the payload. Four characters of the handle are unique in
 * practice, disclose nothing, and are stable for the life of the pirate.
 */
export const pirateCallsign = (key: string, index: number): string =>
  pirateId(key, index).slice(0, 4);

/**
 * KEYED BY THE FIELD'S EXTENT, NOT ITS LENGTH ALONE. The derived lane never changes
 * shape, but the dynamic field is a window that slides every hour, and two windows
 * of equal length would have shared one map and resolved a handle to a pirate the
 * current field does not hold — the bug `asteroidIndexFromId` was rewritten for.
 * Each hour's indices are a contiguous run, so length plus both ends names the set.
 */
function idsFor(key: string, field: readonly PirateSpec[]): Map<string, number> {
  const cacheKey = `${key}:${String(field.length)}:${String(field[0]?.index ?? -1)}:${String(field.at(-1)?.index ?? -1)}`;
  const cached = idCache.get(cacheKey);
  if (cached) return cached;
  const ids = new Map(field.map((spec) => [pirateId(key, spec.index), spec.index]));
  idCache.set(cacheKey, ids);
  trim(idCache);
  return ids;
}

/** Resolve only a canonical id for this exact season key. */
export function pirateIndexFromId(
  key: string,
  field: readonly PirateSpec[],
  id: string,
): number | null {
  if (!/^[A-Za-z0-9_-]{22}$/.test(id)) return null;
  const index = idsFor(key, field).get(id);
  if (index === undefined) return null;
  // Fixed-time on the final comparison even though the map lookup already avoids
  // an O(n) walk of the lane on every launch.
  const expected = Buffer.from(pirateId(key, index));
  const supplied = Buffer.from(id);
  return expected.length === supplied.length && timingSafeEqual(expected, supplied) ? index : null;
}

/**
 * WHAT IS STILL FLYING: the roster it entered with, minus what has been shot off.
 *
 * Never negative, and never resurrects. A missing row means untouched, which is
 * why the losses argument is optional rather than the caller having to invent an
 * empty fleet at every site.
 */
export function livingRoster(roster: Fleet, losses: Fleet | undefined): Fleet {
  if (!losses) return { ...roster };
  const alive: Fleet = {};
  for (const [id, count] of Object.entries(roster) as [HullId, number][]) {
    const left = count - (losses[id] ?? 0);
    if (left > 0) alive[id] = left;
  }
  return alive;
}

/**
 * EVERY PIRATE THIS COMMANDER HAS EVER HAD INSIDE ONE OF THEIR POSTS. D158.
 *
 * The mirror of `discoveredAsteroidIndexes`. The expiry clamp — a pirate that has
 * just left the lane may still be the subject of a raid in the air, so discovery is
 * tested at the last instant it existed — now lives inside `pirateDiscovered`,
 * which `pirateZone` also calls. It was written here alone at first, so the disc
 * and the launch gate could answer the boundary differently.
 *
 * Indexes, not ids, because every caller is inside the server and the raw lane
 * index is exactly what must never be serialised.
 */
export function discoveredPirateIndexes(
  snapshot: PirateSnapshot,
  epochs: readonly SensorEpoch[],
  now: Date,
): ReadonlySet<number> {
  if (epochs.length === 0) return new Set();
  const nowMinutes = minutesSince(snapshot.startsAt, now);
  return new Set(snapshot.pirates
    .filter((spec) => pirateDiscovered(spec, epochs, nowMinutes))
    .map((spec) => spec.index));
}

export interface PirateStateRow {
  losses: Fleet;
  destroyedAt: Date | null;
  destroyedByPlayerId: string | null;
  lootPaid: Resources;
}

/**
 * The caller-independent season snapshot behind every pirate read. D99.
 *
 * Carries raw lane facts rather than a response: activity, damage and — above all
 * — FOG are applied at request time, per caller. A shared snapshot that had
 * already filtered for somebody would be a cache that leaks between commanders.
 */
export interface PirateSnapshot {
  pirates: PirateSpec[];
  startsAt: Date;
  key: string;
  state: ReadonlyMap<number, PirateStateRow>;
  /** Pirate `index` if this snapshot holds it — by INDEX, never by array position. */
  spec: (index: number) => PirateSpec | undefined;
  /** The crew still aboard pirate `index`. */
  livingRosterOf: (index: number) => Fleet;
  /** Unpaid reward budget, after previous raids, for reads and bot planning. */
  remainingLootOf: (index: number) => Resources;
  destroyedAt: (index: number) => Date | null;
  /** Every pirate that is in the disc at `now` and has not been wiped out. */
  standing: (now: Date) => PirateSpec[];
}

export async function loadPirateSnapshot(
  db: Queryable,
  seasonId: string,
  now: Date,
  options: { gated?: boolean } = {},
): Promise<PirateSnapshot> {
  const [season] = await db.select().from(seasons).where(eq(seasons.id, seasonId));
  if (!season) throw new GameError('SEASON_NOT_FOUND', 'No such season', 404);
  const rows = await db.select().from(pirateState).where(eq(pirateState.seasonId, seasonId));
  const state = new Map<number, PirateStateRow>(rows.map((row) => [row.index, {
    losses: row.losses,
    destroyedAt: row.destroyedAt,
    destroyedByPlayerId: row.destroyedByPlayerId,
    lootPaid: row.lootPaid,
  }]));
  if (dynamicPirates(season)) {
    const planned = (await loadPirateHours(db, season, now))
      .flatMap((hour) => privatePirateHour(season.asteroidKey, hour));
    // Owner rule 2026-10-17: only births the spawn gate decided and kept (see `spawnGate.ts`).
    const pirates = options.gated === false ? planned : await applySpawnGate(db, season, 'PIRATE', planned, now);
    return snapshotOf(season, state, pirates, Infinity);
  }
  const pirates = privatePirateField(season.asteroidKey);
  /*
    First roll all processes with the newer contacts hidden, then open each lane.
    Even a staged API derives the FULL field, so a handle minted by an instance
    that is already ahead still resolves here; only what `standing` publishes is
    held back. The two flags nest in lane order — the older one wins, because a
    process that cannot read the +50% lane certainly cannot read the one after it.
  */
  const visibleLength = process.env.PIRATE_SPAWN_INCREASE_ENABLED === 'false'
    ? privatePirateField(season.asteroidKey, 'ESTABLISHED').length
    : process.env.PIRATE_SPAWN_SURGE_ENABLED === 'false'
      ? privatePirateField(season.asteroidKey, 'INCREASED').length
      : pirates.length;

  return snapshotOf(season, state, pirates, visibleLength);
}

function snapshotOf(
  season: { startsAt: Date; asteroidKey: string; tempoStartsAt: Date | null },
  state: ReadonlyMap<number, PirateStateRow>,
  pirates: PirateSpec[],
  visibleLength: number,
): PirateSnapshot {
  if (season.tempoStartsAt !== null && season.tempoStartsAt > season.startsAt) {
    const cutoverMinute = minutesSince(season.startsAt, season.tempoStartsAt);
    pirates = pirates.filter(spec => spec.appearsAt > cutoverMinute);
  }
  const byIndex = new Map(pirates.map((spec) => [spec.index, spec]));
  return {
    pirates,
    startsAt: season.startsAt,
    key: season.asteroidKey,
    state,
    spec: (index) => byIndex.get(index),
    livingRosterOf: (index) => {
      const spec = byIndex.get(index);
      return spec ? livingRoster(spec.roster, state.get(index)?.losses) : {};
    },
    destroyedAt: (index) => state.get(index)?.destroyedAt ?? null,
    remainingLootOf: (index) => {
      const spec = byIndex.get(index);
      const zero = { alloy: 0, crystal: 0, deuterium: 0 };
      return spec ? remainingPirateLoot(spec.hoard, state.get(index)?.lootPaid ?? zero) : zero;
    },
    standing: (at) => activePirates(pirates, minutesSince(season.startsAt, at))
      .filter((spec) => spec.index < visibleLength && state.get(spec.index)?.destroyedAt == null),
  };
}

