import { prepareBattleReplay, persistBattleReplay } from './battleReplay.js';
import { and, eq, gt, inArray } from 'drizzle-orm';
import {
  activeBattleFleet,
  ENGAGEMENT_STANDOFF,
  HULLS,
  MOBILE_HULLS,
  PIRATE,
  distance,
  engagementEndsAt,
  fleetCargo,
  fleetCount,
  fleetEntries,
  fleetSpeed,
  fleetSpeedMult,
  fleetTravelExact,
  claimPirateLoot,
  interceptOrbit,
  missionFuel,
  pirateActive,
  pirateCapture,
  piratePosition,
  pirateOverrun,
  pirateBattleWreck,
  pirateStats,
  partitionCombatFleet,
  resolveBattle,
  soloStack,
  hpRadiationApplies,
  capLoadToSurvivors,
  seededFrom,
  settleWreck,
  surfaceStandoff,
  toGame,
  toWorld,
  visualLeg,
  worldRadius,
  pirateZone,
  type Fleet,
  type HullId,
  type PirateLevel,
  type PirateSpec,
  type Resources,
  type Vec3,
  shipDamageApplies,
  type HpDamageLots,
} from '@astera/rules';
import { dockNotice, landShips, shipsIn } from './shipDamage.js';
import { selectHomeDispatch, takeHomeHealth } from './homeHealth.js';
import type { Db, Tx } from '../db/client.js';
import type { Clock } from '../clock.js';
import { addMinutes, atMinute, minutesSince } from '../clock.js';
import { battleReports, debrisFields, pirateRaids, pirateState, planets, seasons, units } from '../db/schema.js';
import { publish, publishShard } from '../stream/bus.js';
import { assertFreeBay } from './flight.js';
import { assertFuel } from './fuel.js';
import { notify } from './notifications.js';
