import { commanderPvpBalance } from './pvpBalance.js';
import { and, asc, desc, eq, gt, inArray, isNull, lte, ne, or } from 'drizzle-orm';
import {
  faultsPossible,
  hasFault,
  minutesUntilLoyaltyZero,
  repairCost,
  radiationBombLevel,
  partitionCombatFleet,
  INSTRUMENT_IDS,
  SHIELD,
  SATELLITE_IDS,
  buildingCost,
  alloyRate,
  collectorCap,
  crystalRate,
  deuteriumCollectorCap,
  deuteriumRate,
  deuteriumStorageCap,
  dominion,
  groundLoad,
  groundSlots,
  hangarCapacity,
  hangarCeiling,
  hangarLoad,
  instrumentCost,
  productionMult,
  planetSkinById,
  satelliteCost,
  satelliteSlots,
  shieldHp,
  storageCap,
  vaultProtects,
  SILENT_SPACE,
  silentSpaceDueAt,
  type BuildingId,
  type Fleet,
  dockLocation,
  clanDefenseApplies,
} from '@astera/rules';
import type { Clock } from '../clock.js';
import type { Tx } from '../db/client.js';
import { buildOrders, galaxyEventOccurrences, intergalacticConvoyRuns, players, strategicAssets } from '../db/schema.js';
import { baysOf } from './flight.js';
import { loadPlanetViewState, GameError, type LockedPlanet } from './planet.js';
import { asTech, buildResearchView, loadResearchViewData } from './researchState.js';
import { dockLotsOf, dockView, shipsOfLots } from './shipDamage.js';
import { colonyStanding } from './ownership.js';
import { buildDefencePostureView } from './defencePosture.js';
import { activeClanMembership } from './clanCombat.js';
import { clanSupportBayView } from './clanSupportView.js';
import { workshopRadiation } from './workshop.js';
import { readHonorPlayerPolicy } from './honorBenefits.js';
import {
  activeResearchOrders,
  researchOrderView,
} from './researchQueue.js';

/**
 * Capture private response facts under the existing transaction locks, then render
 * without a database handle. Mutation callers must capture AFTER their writes;
 * reusing their arithmetic LockedPlanet can omit changed units or queue rows.
 */
type StrategicRow = typeof strategicAssets.$inferSelect;

const PAD_RANK: Record<StrategicRow['status'], number> = {
  READY: 0,
  BUILDING: 1,
  PAUSED: 2,
  LAUNCHED: Number.MAX_SAFE_INTEGER,
  CONSUMED: Number.MAX_SAFE_INTEGER,
};

/**
 * THE ORDER A PAD FLIES IN. T11.
 *
 * What can launch first, then what finishes first: READY before BUILDING before
 * PAUSED, each by the instant it became (or will become) ready. The stockpile
 * puts two weapons on one pad, so "the weapon" is no longer a single row — and
 * the NEWEST row, which is what this used to report, is exactly the wrong one:
 * a second weapon queued behind a ready one hid it from its owner and from the
 * strike control that reads the head of this list.
 */
function padOrder(a: StrategicRow, b: StrategicRow): number {
  const rank = (row: StrategicRow) => PAD_RANK[row.status];
  const when = (row: StrategicRow) => row.status === 'PAUSED'
    ? row.remainingSeconds ?? 0
    : (row.readyAt ?? row.startedAt).getTime();
  return rank(a) - rank(b) || when(a) - when(b) || a.id.localeCompare(b.id);
}

const strategicView = (row: StrategicRow) => ({
  id: row.id,
  status: row.status,
  readyAt: row.readyAt,
  remainingSeconds: row.remainingSeconds,
});

function departureOf(
  player: Pick<typeof players.$inferSelect, 'lastProgressAt' | 'joinedAt' | 'mainEnteredAt' | 'silentSpaceResetAt'> | undefined,
  p: Pick<LockedPlanet, 'silentSpace' | 'seasonEndsAt' | 'vacationUntil'>,
): Date | null {
  if (!player || p.silentSpace || p.vacationUntil) return null;
  const at = silentSpaceDueAt({
    lastProgressAt: player.lastProgressAt?.getTime() ?? null,
    resetAt: player.silentSpaceResetAt?.getTime(),
    joinedAt: player.joinedAt.getTime(),
    mainEnteredAt: (player.mainEnteredAt ?? player.joinedAt).getTime(),
  });
  return at < p.seasonEndsAt.getTime() ? new Date(at) : null;
}

/** Shared only across worlds in one transaction, never across requests or writes. */
async function loadCommanderViewData(tx: Tx, p: LockedPlanet) {
  const [[player], researchData, researchQueue, colonies, membership, honor, pvpBalance] = await Promise.all([
    tx.select().from(players).where(eq(players.id, p.playerId)),
    loadResearchViewData(tx, p.playerId),
    activeResearchOrders(tx, p.playerId),
    colonyStanding(tx, p.playerId),
    clanDefenseApplies(p.rulesetVersion) ? activeClanMembership(tx, p.playerId) : null,
    readHonorPlayerPolicy(tx, p.seasonId, p.playerId),
    commanderPvpBalance(tx, p.playerId),
  ]);
  const queuedResearch = new Map(researchData.rows.map(row => [row.projectId, row.level]));
  for (const order of researchQueue) {
    queuedResearch.set(order.projectId, Math.max(queuedResearch.get(order.projectId) ?? 0, order.level));
  }
  return { playerId: p.playerId, seasonId: p.seasonId, player, researchData, researchQueue,
    colonies, pvpBalance, hasMembership: membership !== null, queuedResearch, benefits: honor.benefits, honorTacticalCredit: honor.tacticalCredit };
}

export async function loadPlanetViewData(
  tx: Tx, planetId: string, clock: Clock,
  shared?: Awaited<ReturnType<typeof loadCommanderViewData>>,
  options: { readOnly?: boolean } = {},
) {
  const { planet: p, unitRows, faultRows } = await loadPlanetViewState(tx, planetId, clock, options);
  if (shared && (shared.playerId !== p.playerId || shared.seasonId !== p.seasonId)) {
    throw new GameError('PLACEMENT_CHANGED', 'World ownership changed; refresh and try again', 409);
  }
  /*
    ONE PASS, NOT FIVE. Resource analysis follow-up 2026-10-14.

    Everything below reads the same snapshot and depends only on the world state
    above, so it is issued together and pipelined on this transaction's connection
    instead of waiting for each answer in turn.
  */
  const [commander, assets, queued, [activeConvoy], [spentConvoy], dockLots, flight, clanSupport, workshopIrradiated] = await Promise.all([
    shared ?? loadCommanderViewData(tx, p),
    tx.select().from(strategicAssets).where(and(
      eq(strategicAssets.planetId, planetId),
      or(
        and(inArray(strategicAssets.type, ['DEATH_STAR', 'INTERCEPTOR']),
          inArray(strategicAssets.status, ['BUILDING', 'PAUSED', 'READY'])),
        and(inArray(strategicAssets.type, ['RADIATION_BOMB_L1', 'RADIATION_BOMB_L2', 'RADIATION_BOMB_L3']),
          inArray(strategicAssets.status, ['BUILDING', 'PAUSED', 'READY', 'LAUNCHED'])),
      ),
    )).orderBy(desc(strategicAssets.startedAt), desc(strategicAssets.id)),
    tx.select().from(buildOrders)
      .where(and(eq(buildOrders.planetId, planetId), eq(buildOrders.status, 'BUILDING')))
      .orderBy(asc(buildOrders.queue), asc(buildOrders.slot)),
    tx.select({ id: intergalacticConvoyRuns.id })
      .from(intergalacticConvoyRuns)
      .where(and(
        eq(intergalacticConvoyRuns.planetId, planetId),
        ne(intergalacticConvoyRuns.status, 'done'),
      ))
      .limit(1),
    /**
     * THIS WORLD HAS ALREADY SPENT ITS ONE STRIKE AT THE CONVOY THAT IS UP. D201.
     *
     * A world may strike each occurrence exactly once, ever — the DB says so with a
     * unique index on `(planet_id, occurrence_id)` — and a crossing lasts three hours
     * while a round trip rarely lasts one. So the ordinary case is a commander whose
     * fleet is safely home, inside the same window, looking at a control that has
     * nothing left to spend. Publishing only `convoyLaunchLocked` (which clears the
     * moment the fleet lands) re-armed that control and let them pick a wing, read a
     * quote and commit, to be answered with `CONVOY_ALREADY_RAIDED`.
     *
     * A rule the player cannot SEE is not a usable rule (D124), so the state travels
     * with the world rather than living only in the refusal. It names no occurrence
     * and no run: it is one boolean about the convoy that is public right now.
     */
    tx.select({ id: intergalacticConvoyRuns.id })
      .from(intergalacticConvoyRuns)
      .innerJoin(
        galaxyEventOccurrences,
        eq(galaxyEventOccurrences.id, intergalacticConvoyRuns.occurrenceId),
      )
      .where(and(
        eq(intergalacticConvoyRuns.planetId, planetId),
        // An abandoned outbound run released its ration; the control stays live.
        isNull(intergalacticConvoyRuns.abandonedAt),
        lte(galaxyEventOccurrences.startsAt, p.now),
        gt(galaxyEventOccurrences.endsAt, p.now),
      ))
      .limit(1),
    dockLotsOf(tx, planetId, unitRows),
    baysOf(tx, planetId, p.buildings.CORE),
    clanSupportBayView(tx, { planetId, rulesetVersion: p.rulesetVersion, at: p.now }),
    workshopRadiation(tx, p),
  ]);
  return { p, commander, assets, queued, activeConvoy, spentConvoy, unitRows, faultRows,
    dockLots, flight, clanSupport, workshopIrradiated };
}

export type PlanetViewData = Awaited<ReturnType<typeof loadPlanetViewData>>;

/** Apply to the transaction promise, so rendering never prolongs its world locks. */
export function buildPlanetResult<T extends { planet: PlanetViewData }>(result: T) {
  const { planet, ...rest } = result;
  return { ...rest, planet: buildPlanetView(planet) };
}

/** No queries or writes: safe to run after the capturing transaction commits. */
export function buildPlanetView(data: PlanetViewData) {
  const { p, commander, assets, queued, activeConvoy, spentConvoy, unitRows, faultRows,
    dockLots, flight, clanSupport, workshopIrradiated } = data;
  const { player, researchData, researchQueue, colonies, hasMembership, queuedResearch, benefits, honorTacticalCredit } = commander;
  const pad = assets.filter(row => row.type === 'DEATH_STAR').toSorted(padOrder);
  const interceptors = assets.filter(row => row.type === 'INTERCEPTOR').toSorted(padOrder);
  const owned: Fleet = {};
  const fleetAway: Fleet = {};
  for (const row of unitRows) {
    owned[row.hull] = (owned[row.hull] ?? 0) + row.count;
    if (row.count > 0 && row.location !== 'home' && !row.location.startsWith(dockLocation(''))) {
      fleetAway[row.hull] = (fleetAway[row.hull] ?? 0) + row.count;
    }
  }
  const research = buildResearchView(p, researchData, queuedResearch);
  /**
   * THE RATES THE ECONOMY ACTUALLY RUNS AT — Foundry included. D52a.
   *
   * `advanceEconomy` fills the works to `collectorCap(rate × productionMult)` and
   * `collect` fills storage to `storageCap(rate × productionMult)`, and every
   * figure below used to be computed from the BARE rate. With a Foundry in orbit
   * (×1.06) the real ceiling is six per cent above the published one, so
   * `bufferAlloy` legitimately exceeded `bufferAlloyCap` — the Works widget pinned
   * at 100% and Signals announced "the works have stopped, production is being
   * thrown away" while production was in fact still running. Storage read over
   * 100% of its stated cap after a collect, for the same reason.
   *
   * It also under-sold the satellite it exists to price: a player who had just
   * bought a Foundry saw the same per-hour figure they had before.
   *
   * One boosted rate, used for all six. `productionMult` is the single source —
   * anything that derives a cap or a rate from a level must go through it.
   */
  const boost = productionMult(p.orbit);
  const nominalPerHourAlloy = alloyRate(p.buildings.REFINERY) * boost;
  const nominalPerHourCrystal = crystalRate(p.buildings.EXTRACTOR) * boost;
  /**
   * The floor is HOURS OF PRODUCTION, so it needs the producing levels as well as
   * the Vault's. It reads the unboosted rate on purpose: a Foundry lifts the store
   * without lifting the floor, so a bigger planet is slightly more exposed.
   */
  // What the plant makes, boosted like everything else the works produce. T5.
  const nominalPerHourDeuterium = deuteriumRate(p.buildings.DEUTERIUM_PLANT) * boost;
  /*
    THE VIEW PUBLISHES WHAT IS RUNNING, NOT WHAT THE HARDWARE COULD MAKE.

    `advanceEconomy` has always applied the outage, but these three figures stayed
    nominal. The browser projects the Works from them between reads, so it visibly
    manufactured ore the server would never credit and kept the inflow animation
    running over a dark refinery. Capacity remains nominal below: repairing a plant
    resumes the same vessels; an outage does not shrink them.
  */
  // D212: Silent Space halves what runs; every ceiling below keeps reading the rated figure.
  const pace = p.vacationUntil ? 0 : p.silentSpace ? SILENT_SPACE.productionPace : 1;
  const perHourAlloy = hasFault(p.faults, 'REFINERY_OUTAGE') ? 0 : nominalPerHourAlloy * pace;
  const perHourCrystal = hasFault(p.faults, 'EXTRACTOR_OUTAGE') ? 0 : nominalPerHourCrystal * pace;
  const perHourDeuterium = hasFault(p.faults, 'PLANT_OUTAGE') ? 0 : nominalPerHourDeuterium * pace;

  const vaultCapacity = vaultProtects(
    p.buildings.VAULT,
    p.buildings.REFINERY,
    p.buildings.EXTRACTOR,
    p.buildings.DEUTERIUM_PLANT,
  );
  const vaultProtected = {
    alloy: Math.min(Math.floor(p.alloy), vaultCapacity.alloy),
    crystal: Math.min(Math.floor(p.crystal), vaultCapacity.crystal),
    deuterium: Math.min(Math.floor(p.deuterium), vaultCapacity.deuterium),
  };
  const shieldMax = shieldHp(p.effectiveInstruments.AEGIS ?? 0);
  const aegisLevel = p.faults.includes('CORE_OUTAGE') ? 0 : p.effectiveInstruments.AEGIS ?? 0;
  const blockedUntil = Math.max(p.empUntil?.getTime() ?? 0, p.shieldRegenAt?.getTime() ?? 0);
  const protection = aegisLevel > 0 && p.shield >= 1 && blockedUntil <= p.now.getTime() ? aegisLevel : 0;
  const restoresAt = protection > 0 || aegisLevel === 0 ? null : new Date(Math.max(p.now.getTime(), blockedUntil,
    p.recoveryUntil?.getTime() ?? 0, p.vacationUntil?.getTime() ?? 0)
    + Math.ceil(Math.max(0, 1 - p.shield) / (shieldMax * SHIELD.regenPerHour) * 3600000));
  return {
    planet: {
      id: p.planetId,
      // The economy was advanced under this world's lock at this instant.
      snapshotAt: p.now,
      name: p.name,
      skinId: p.equippedSkinId ? planetSkinById(p.equippedSkinId)?.id ?? null : null,
      kind: p.kind,
      position: { x: p.x, y: p.y, z: p.z },
      alloy: Math.floor(p.alloy),
      crystal: Math.floor(p.crystal),
      deuterium: Math.floor(p.deuterium),
      alloyCap: storageCap(nominalPerHourAlloy, p.buildings.VAULT),
      crystalCap: storageCap(nominalPerHourCrystal, p.buildings.VAULT),
      deuteriumCap: deuteriumStorageCap(
        nominalPerHourDeuterium,
        nominalPerHourCrystal,
        p.buildings.VAULT,
      ),
      alloyPerHour: Math.round(perHourAlloy),
      nominalAlloyPerHour: Math.round(nominalPerHourAlloy),
      /*
        THE RATE THE HUD WAS HARD-CODING TO ZERO. T5.

        `StatusBar` printed `rate={0}` for deuterium because the resource had no
        production — true then, false since the refinery. Left alone, a commander
        with a plant watches the figure climb while the readout beside it says
        nothing is being made, and the "full in ..." warning every other resource
        gets can never fire.
      */
      deuteriumPerHour: Math.round(perHourDeuterium),
      crystalPerHour: Math.round(perHourCrystal),
      nominalCrystalPerHour: Math.round(nominalPerHourCrystal),
      nominalDeuteriumPerHour: Math.round(nominalPerHourDeuterium),
      /**
       * The works: what is waiting to be collected, and the ceiling it stops at
       * (D16). Both are needed on the client, because the interface has to say
       * "full in 3h 20m" before it can say "FULL — you are wasting 160/h", and
       * only the second of those is a reason to open the game right now.
       */
      bufferAlloy: Math.floor(p.bufferAlloy),
      bufferCrystal: Math.floor(p.bufferCrystal),
      bufferDeuterium: Math.floor(p.bufferDeuterium),
      bufferAlloyCap: collectorCap(nominalPerHourAlloy),
      bufferCrystalCap: collectorCap(nominalPerHourCrystal),
      bufferDeuteriumCap: deuteriumCollectorCap(
        nominalPerHourDeuterium,
        nominalPerHourCrystal,
      ),
      /**
       * WHAT IS ACTUALLY SAFE, AS ONE FIGURE. D61.
       *
       * The floor is a pair now, and the screen asks a single question: how much of
       * what I am holding can nobody take. That is `min(held, floor)` on each side
       * added together — not the floor itself, which would claim protection over
       * crystal a planet does not have.
       *
       * It also makes the arithmetic the interface was already doing correct.
       * `PlanetHero` reads `alloy + crystal - vaultFloor` as the exposed amount;
       * against a single flat floor that OVERSTATED the risk, because the rule
       * deducted that floor from each resource and the screen deducted it once.
       */
      vaultFloor:
        vaultProtected.alloy + vaultProtected.crystal + vaultProtected.deuterium,
      /** Exact per-resource protection. The aggregate above remains for old verdict logic. */
      vaultProtected,
      vaultCapacity,
      shield: Math.floor(p.shield),
      shieldMax,
      shieldRegenAt: p.shieldRegenAt,
      radiationProtectionHpPerMinute: protection,
      radiationProtectionLevel: aegisLevel,
      radiationProtectionRestoresAt: restoresAt,
      shieldPerHour: p.vacationUntil ? 0 : Math.round(shieldMax * SHIELD.regenPerHour),
      disruptedUntil: p.disruptedUntil,
      recoveryUntil: p.recoveryUntil,
      empUntil: p.empUntil,
      protectedUntil: p.protectedUntil,
      /**
       * THE STRUCK WORLD WORKS DOUBLE UNTIL THIS INSTANT. 2026-09-16.
       *
       * Null the moment it has passed, so a surface never has to compare it to a
       * clock to decide whether to draw the boost — and the works projection on the
       * client reads the same instant to fill the vessels at the boosted pace.
       */
      productionBoostUntil: p.recoveryBoostUntil !== null && p.recoveryBoostUntil > p.now
        ? p.recoveryBoostUntil
        : null,
      signalBoostUntil: p.signalBoostUntil !== null && p.signalBoostUntil > p.now ? p.signalBoostUntil : null,
      /**
       * NO TRANSFER MAY LEAVE THIS WORLD UNTIL THIS INSTANT. Faz 2A.3.
       *
       * Published so the transfer sheet can say so BEFORE the commander packs a squadron. A rule
       * that only ever appears as a refusal on commit is a rule the player learns by losing a
       * decision to it, and this one fires at exactly the moment they are in a hurry.
       *
       * Null once it has passed, like the boost above it, so no surface compares it to a clock.
       */
      transferReadyAt: p.transferReadyAt !== null && p.transferReadyAt > p.now
        ? p.transferReadyAt
        : null,
    },
    pvpBalance: commander.pvpBalance,
    buildings: p.buildings,
    nextCosts: Object.fromEntries(
      (Object.keys(p.buildings) as BuildingId[]).map((b) => [b, buildingCost(b, p.buildings[b])]),
    ),
    /** The four on the ground, with their levels. D25. */
    instruments: p.instruments,
    effectiveInstruments: p.effectiveInstruments,
    /**
     * What the next level of each instrument costs, priced by the server.
     *
     * The client could compute this — `instrumentCost` is a pure function it
     * already imports — but every other price on this payload is authoritative
     * and a screen that mixes the two is one modifier away from showing a number
     * the purchase endpoint will refuse.
     */
    instrumentCosts: Object.fromEntries(
      INSTRUMENT_IDS.map((i) => [i, instrumentCost(i, p.instruments[i] ?? 0)]),
    ),
    /** What is in orbit, and how much room there is. D25. */
    orbit: p.storedOrbit,
    effectiveOrbit: p.orbit,
    orbitSlots: satelliteSlots(p.buildings.CORE),
    satelliteCosts: Object.fromEntries(SATELLITE_IDS.map((sat) => [sat, satelliteCost(sat)])),
    /** Two immediate seasonal projects; discovery is derived, never stored. D93/D94. */
    research,
    /** The Core that gates and times research on EVERY world: the capital's. D209. */
    researchCore: colonies.capitalCore,
    /** One commander lane, identical whichever controlled world funded the view. */
    researchQueue: researchQueue.map(order => ({ ...researchOrderView(order), pausedAt: p.vacationUntil ?? undefined })),
    /**
     * WHAT IS BROKEN, AND WHAT PUTTING IT RIGHT COSTS. Koloni arızaları.
     *
     * Reuse the rows captured while advancing the economy under the world lock.
     *
     * THE PRICE IS SERVER-SIDE, like every other price on this payload. The client
     * imports `repairCost` and could work it out, but a surface that mixes computed
     * and authoritative figures is one modifier away from quoting a number the repair
     * endpoint will refuse.
     */
    faultProtectedUntil: p.kind === 'COLONY' ? p.faultProtectedUntil : null,
    faults: faultRows
      .map((fault) => ({
        id: fault.id,
        kind: fault.kind,
        startedAt: fault.startedAt,
        cost: repairCost(fault.kind, p.buildings.CORE),
        /**
         * NULL UNTIL SOMEBODY PAYS, and it never goes back to null. There is no cancel:
         * the strip draws three lanes and none of them carries a way out.
         */
        repair: fault.repairReadyAt && fault.repairSlot !== null
          ? { slot: fault.repairSlot, readyAt: fault.repairReadyAt }
          : null,
      })),
    /**
     * HOW MUCH OF THIS WORLD IS STILL YOURS, and how long that lasts.
     *
     * Capitals have no loyalty. Every colony may lose it in battle, including those
     * below the Core fault gate.
     *
     * `minutesLeft` is the half that makes it a DECISION rather than a readout. The
     * commander does not need to know they are at 34%; they need to know they have
     * eleven hours, because that is the figure "do I fix this now or after work" is
     * answered with. Null while nothing is falling.
     */
    loyalty: p.kind === 'COLONY'
      ? {
          value: p.loyalty,
          minutesLeft: p.vacationUntil ? null : minutesUntilLoyaltyZero(p.loyalty, faultsPossible({
            kind: p.kind,
            coreLevel: p.buildings.CORE,
            plantLevel: p.buildings.DEUTERIUM_PLANT,
          }) ? p.faults.length : 0),
        }
      : null,
    /** Absolute instants keep every client on the same queue clock. D4. */
    queues: {
      CONSTRUCTION: queued
        .filter((order) => order.queue === 'CONSTRUCTION' && order.kind !== 'RESEARCH')
        .map(order => buildOrderView(order, p.vacationUntil)),
      YARD: queued.filter((order) => order.queue === 'YARD').map(order => buildOrderView(order, p.vacationUntil)),
      /** The Repair Station's own lane, beside the yard. Kalıcı gemi hasarı. */
      REPAIR: queued.filter((order) => order.queue === 'REPAIR').map(order => buildOrderView(order, p.vacationUntil)),
    },
    /** The head of `deathStars`: the weapon that can fly soonest. */
    strategic: pad[0] ? strategicView(pad[0]) : null,
    /** Every weapon on this world's pad, in `padOrder`. Up to the stockpile's two. T11. */
    deathStars: pad.map(strategicView),
    /** Compatibility head plus the complete two-charge battery. */
    interceptor: interceptors[0] ? strategicView(interceptors[0]) : null,
    interceptors: interceptors.map(strategicView),
    radiationBombsAvailable: !!p.radiationBombStartsAt && p.radiationBombStartsAt <= p.now,
    radiationBombs: assets.flatMap(row => {
      const level = radiationBombLevel(row.type);
      return level === null ? [] : [{ ...strategicView(row), level }];
    }),
    colonies,
    fleet: p.homeFleet,
    fleetDamage: p.homeDamage,
    workshopRadiation: workshopIrradiated,
    fleetCombatReady: partitionCombatFleet(p.homeFleet, p.homeDamage).eligible,
    ground: p.ground,
    /**
     * Your own craft that are currently off the planet.
     *
     * `fleet` is what is standing on the ground, so it is the wrong number to
     * count anything a player OWNS against — and `PROSPECTOR.max` is a rule about
     * ownership. Without this the build sheet would offer another Prospector to
     * somebody whose two were away mining, and the server would refuse it: a
     * control that lies about what it will do.
     *
     * Yours only, and no fog question arises — it is your own planet's units.
     */
    fleetAway,
    /**
     * Your own ships waiting in the Repair Station. Kalıcı gemi hasarı.
     *
     * Owned, so every ownership count on the client (the Hangar room, the Prospector
     * cap) must add them — but neither standing at home nor away, so they are in
     * neither of the two fields above.
     */
    fleetDocked: shipsOfLots(dockLots),
    /**
     * THE REPAIR STATION: what waits in the dock and what repairing it costs. Priced
     * here, like the fault repairs above, so the screen never quotes a figure the repair
     * endpoint would refuse.
     */
    dock: dockView(dockLots, p.buildings.SHIPYARD, asTech(new Map(research.map((row) => [row.id, row.level])))),
    /**
     * How much this planet has in the air, and how much it may. D28.
     *
     * Counted here rather than derived on the client, because the client cannot
     * see other people's craft and would have to guess — and because the count is
     * captured under the same planet lock that `assertFreeBay` reads under.
     */
    flight,
    convoyLaunchLocked: activeConvoy !== undefined,
    convoyOccurrenceSpent: spentConvoy !== undefined,
    /**
     * SILENT SPACE, FROM BOTH SIDES OF THE DOOR. D212.
     *
     * `silentSpace` closes the fight and farm controls before they are pressed and explains
     * the halved rates above. `silentSpaceAt` is when a main-galaxy commander leaves if they
     * order nothing until then; null inside Silent Space and when the season closes first.
     */
    silentSpace: p.silentSpace,
    vacationUntil: p.vacationUntil,
    silentSpaceAt: departureOf(player, p),
    /**
     * BOTH CEILINGS AND BOTH LOADS. T4 · T4b.
     *
     * Sent so the order screen can refuse a hull BEFORE it is pressed. A control
     * that offers a ship the server will reject is a control that lies about what
     * it does, and the Prospector cap already established the shape: the client
     * greys the option and prints the figures rather than discovering the rule
     * through a toast.
     *
     * The load is counted over every unit row this world owns — `fleet` is only
     * what is standing on the ground, and the ceiling is a rule about ownership.
     * Without that, a world whose guns were somehow away would be offered room it
     * does not have. `hangarCeiling` is the tallest Hangar this Core allows, so the
     * screen can tell "raise the Hangar" from "raise the Core first".
     */
    capacity: {
      hangar: hangarCapacity(p.buildings.HANGAR),
      hangarUsed: hangarLoad(owned),
      hangarCeiling: hangarCeiling(p.buildings.CORE),
      ground: groundSlots(p.buildings.CORE),
      groundUsed: groundLoad(owned),
    },
    /**
     * WHETHER THE COMMANDER HOLDING THIS WORLD IS NEW. Owner instruction.
     *
     * A world claimed through the Academy carries the step it was claimed at;
     * every world that existed before onboarding, and every established
     * commander's, carries null. The client uses it for one thing — whether the
     * written coaching card applies at all (`SituationGuide`) — and it has to come
     * from here rather than from the device, because a device flag would put the
     * beginner's card in front of a season-old commander on a new phone.
     */
    academyStep: p.academyStep,
    /**
     * THE RULE SET THIS WORLD'S SEASON WAS DEALT. Taktik geri çekilme, 2026-09-23.
     *
     * The Defend tab states the fleet-escape threshold only in a season that has the
     * rule, and it reads that here — off its own world — rather than asking for a
     * second payload the planet screen otherwise never needs.
     */
    rulesetVersion: p.rulesetVersion,
    /**
     * THE TWO DEFENCE TOGGLES. Klan Savunma Desteği, owner K4 · 2026-10-01.
     *
     * Null in a season dealt before the rule — the retreat there is automatic and
     * there is nothing to choose. `supportLocked` says why the support toggle is
     * greyed, so the page can tell the commander rather than just refuse.
     */
    defencePosture: buildDefencePostureView({
      posture: p.defencePosture,
      rulesetVersion: p.rulesetVersion,
    }, hasMembership),
    /**
     * THE HANGAR'S "KLAN DESTEĞİ" BAY: what clanmates have standing here or flying in,
     * and the room it has (the world's own Hangar room, owner K1). Null before ruleset 15.
     */
    clanSupport,
    score: {
      wealth: player?.wealth ?? 0,
      dominion: dominion({
        taken: player?.dominionTaken ?? 0,
        lost: player?.dominionLost ?? 0,
      }),
    },
    honorBenefits: benefits,
    honorTacticalCredit,
  };
}

/** Transaction-supplied callers (including durable idempotent responses) render inside their transaction. */
export async function planetView(tx: Tx, planetId: string, clock: Clock) {
  return buildPlanetView(await loadPlanetViewData(tx, planetId, clock));
}

function buildOrderView(order: typeof buildOrders.$inferSelect, pausedAt: Date | null = null) {
  return {
    id: order.id,
    queue: order.queue,
    slot: order.slot,
    kind: order.kind,
    subject: order.subject,
    count: order.count,
    startedAt: order.startedAt,
    finishesAt: order.readyAt,
    pausedAt: pausedAt ?? undefined,
    cost: order.cost,
  };
}

export type PlanetView = Awaited<ReturnType<typeof planetView>>;

sources.apps/server/src/services/player.ts:
import { and, eq, gt, inArray, isNull, sql } from 'drizzle-orm';
import { BUILDING_IDS, MULTI_WORLD, PLANET_START, START_BUILDINGS, academyExitCheckpoint, fleetEntries, findRewardTier, newcomerShieldUntil, pickSpawnSlot } from '@astera/rules';
import type { Db, Tx } from '../db/client.js';
import type { Clock } from '../clock.js';
import { accounts, buildings, planets, players, seasons, shards, satellites, units, rewardGrants, mainVacancies, returnApplications } from '../db/schema.js';
import { lockAdmission } from './returnQueue.js';
import { galaxyOf } from './season.js';
import { GameError, loadLocked, recomputeWealth } from './planet.js';
import { placeBuildingUpgrade } from './build.js';
import { publishShard } from '../stream/bus.js';
import { refreshSensorEpoch } from './sensorHistory.js';
import { peopleIn } from './people.js';
import { equipAdminCapital } from './adminCapital.js';
import { ensureUnknownSignalSchedule } from './unknownSignalSchedule.js';
import {
  lockGalaxyEventAudience,
  notifyActiveGalaxyEventsForPlayer,
} from './galaxyEvents.js';
import {
  deliverSeasonRankReward,
  deliveredSeasonRankReward,
  type DeliveredSeasonRankReward,
} from './seasonRankRewards.js';

/**
 * The rows a fresh planet is written with, from the one table that decides it.
 *
 * `START_BUILDINGS` is in the rules package because the rehearsal shows a visitor
 * this same planet before it exists (D56), and a client that starts a level apart
 * from the server would show a first upgrade the claim then refuses.
 */
const STARTING_BUILDINGS = BUILDING_IDS.map((type) => ({
  type,
  level: START_BUILDINGS[type],
}));

const NAMES = [
  'Kestrel', 'Vantage', 'Halcyon', 'Tessellate', 'Orrery', 'Bellwether',
  'Cinder', 'Lodestar', 'Quillon', 'Marrow', 'Vesper', 'Thistle',
];

/**
 * What the world in a given slot is called.
 *
 * EXPORTED BECAUSE TWO PLACES NAME IT NOW. `joinSeason` names it when the row is
 * written, and `/api/preview` names it before the row exists — the rehearsal shows
 * a visitor the world they are about to be given, by name, and a preview that says
 * `Vesper-31` for a planet that turns out to be `Marrow-31` is the interface
 * contradicting itself at the one moment the player is deciding to trust it.
 * One function, so the two cannot drift.
 */
/**
 * THE NUMBER A CAPITAL IS CALLED BY, SCRAMBLED ACROSS EVERY SEATED ADDRESS.
 *
 * People stand on addresses below `capitalSlots` and the server's commanders on the
 * `botSlots` after them, so naming a world by its raw address made every bot a
 * four-digit "10xx" — readable at a glance, which is the one thing the roster may
 * never be (D159). A fixed stride coprime to the reserved range maps it onto itself
 * one-to-one: names stay unique and stable, and a bot's number is drawn from the
 * same spread as everyone else's. Addresses past the range keep their own number.
 */
const NAMED_ADDRESSES = MULTI_WORLD.capitalSlots + MULTI_WORLD.botSlots;
const NAME_STRIDE = 677;
const NAME_OFFSET = 131;
const nameNumber = (slotIndex: number): number =>
  slotIndex >= 0 && slotIndex < NAMED_ADDRESSES
    ? (slotIndex * NAME_STRIDE + NAME_OFFSET) % NAMED_ADDRESSES
    : slotIndex;

export const planetNameFor = (slotIndex: number): string => {
  const number = nameNumber(slotIndex);
  return `${NAMES[number % NAMES.length] ?? 'World'}-${String(number)}`;
};

export interface JoinResult {
  playerId: string;
  planetId: string;
  slotIndex: number;
  seasonId: string;
  /** Present on both the winning response and safe retries after a payout. */
  seasonReward: DeliveredSeasonRankReward | null;
}

/**
 * Two joins raced for the same slot. Thrown to roll the transaction back, caught
 * by the retry loop, and never seen outside this file — which is exactly why it is
 * a class of its own rather than a bare `Error`: a `catch` that retries on
 * *anything* also retries on a bug, and hides it.
 */
class SlotTaken extends Error {}

/**
 * This account acquired a player row while we were building one.
 *
 * Distinct from `SlotTaken` because the answer is the opposite: a lost slot is
 * retried, a lost account race must never be — retrying would lose it again, for
 * the same reason, forever. The winner is read back outside the transaction and
 * decides between "here is your planet" and ALREADY_PLACED.
 */
class PlayerExists extends Error {}

/** How many times a join will re-pick a slot before giving up. */
const MAX_ATTEMPTS = 6;

/**
 * Where this account already stands, if anywhere.
 *
 * The join to `planets` is an inner one on purpose: a player row without a planet
 * is a half-finished join, and treating it as a placement would hand the caller a
 * planet id that does not exist. There is no path that creates one — both rows are
 * written in the same transaction — and this is what keeps that true if one ever
 * appears.
 */
async function readPlacement(db: Db, accountId: string): Promise<JoinResult | null> {
  const [found] = await db
    .select({ player: players, planet: planets })
    .from(players)
    .innerJoin(planets, and(eq(planets.controllerPlayerId, players.id), eq(planets.kind, 'CAPITAL')))
    .where(eq(players.accountId, accountId))
    .limit(1);

  if (!found) return null;
  const seasonReward = await deliveredSeasonRankReward(db, accountId, found.player.seasonId);
  return {
    playerId: found.player.id,
    planetId: found.planet.id,
    slotIndex: found.planet.slotIndex,
    seasonId: found.player.seasonId,
    seasonReward,
  };
}

/**
 * Turn an existing placement into either an idempotent success or a refusal.
 *
 * SAME GALAXY IS A SUCCESS. A retried request, a reinstall, or a double-tapped
 * button on a slow phone connection must land on the same planet rather than
 * acquiring a second one or being told off for something it did itself. A
 * DIFFERENT galaxy is the one-commander rule, and the caller has to be told rather
 * than silently redirected — being moved to a galaxy you did not choose is worse
 * than being refused the one you did.
 */
function settle(placement: JoinResult, seasonId: string): JoinResult {
  if (placement.seasonId !== seasonId) {
    throw new GameError('ALREADY_PLACED', 'You already command a planet in another galaxy', 409);
  }
  return placement;
}

/** Who is taking the seat: a person, or one of the server's own commanders. */
export type JoinSeat = 'COMMANDER' | 'SERVER';

/**
 * Place a player on a galaxy.
 *
 * THREE RACES, ALL SETTLED BY THE DATABASE RATHER THAN BY A PRIOR CHECK:
 *
 *   · Two accounts pick the same free slot. `planets_season_slot_idx` rejects the
 *     loser, who re-picks against the now-smaller free set.
 *   · One account joins two galaxies at once from two tabs. `players_account_idx`
 *     rejects the second — this is the one-commander rule, and it is a real race, not
 *     a theoretical one, because a double-tap on a slow connection sends two
 *     requests before either reply lands.
 *   · The final two contenders for one seat join together. Both pass the capacity
 *     read; the slot index then rejects one of them, and the retry finds no free
 *     slot and reports SHARD_FULL.
 *
 * Every one of those is expressed as `onConflictDoNothing` returning no row, so
 * the failure is a value to test and not an exception to classify. Nothing in this
 * file inspects a driver error code.
 *
 * `seat: 'SERVER'` IS THE BOT'S DOOR, and differs only in WHERE. A server commander
 * stands on its own band of addresses (`GALAXY.strata.bot`, the `botSlots` after the
 * capitals), one layer inside the people, and takes the free one furthest from the
 * other bots so the roster scatters all the way round the galaxy. It still costs a
 * seat against `playerCap` and gets exactly the opening a person gets.
 */
export async function joinSeason(
  db: Db,
  accountId: string,
  seasonId: string,
  clock: Clock,
  academyStep?: number,
  seat: JoinSeat = 'COMMANDER',
  adminUsernames: ReadonlySet<string> = new Set(),
): Promise<JoinResult> {
  // Validate before even looking for a placement. Only creation consumes it.
  const academy = academyStep === undefined ? null : academyExitCheckpoint(academyStep);
  const existing = await readPlacement(db, accountId);
  if (existing) return settle(existing, seasonId);

  const [season] = await db.select().from(seasons).where(eq(seasons.id, seasonId));
  if (!season) throw new GameError('SEASON_NOT_FOUND', 'No such season', 404);
  const [shard] = await db.select().from(shards).where(eq(shards.id, season.shardId));
  if (!shard) throw new GameError('SEASON_NOT_FOUND', 'No such season', 404);
  if (shard.role !== 'MAIN') {
    throw new GameError('WAITING_JOIN_FORBIDDEN', 'Join an available main galaxy', 403);
  }

  const spec = seat === 'SERVER'
    ? { slots: galaxyOf(seasonId, season.seed, MULTI_WORLD.capitalSlots + MULTI_WORLD.botSlots).slots
      .filter((slot) => slot.index >= MULTI_WORLD.capitalSlots) }
    : galaxyOf(seasonId, season.seed, shard.playerCap);
  const [account] = await db.select().from(accounts).where(eq(accounts.id, accountId));
  for (let attempt = 0; attempt < MAX_ATTEMPTS; attempt++) {
    try {
      return await db.transaction(async (tx) => {
        await lockAdmission(tx, season.cycleId, shard.id);
        await lockGalaxyEventAudience(tx, seasonId, 'membership');
        // Read after the audience lock. If a lifecycle transition won the race,
        // backfill is evaluated on its side of the exact boundary, never before it.
        const now = clock.now();
        const [current] = await tx.select().from(seasons).where(eq(seasons.id, seasonId));
        if (current?.status !== 'live' || now >= current.endsAt) {
          throw new GameError('SEASON_ENDED', 'This season has ended', 409);
        }
        const occupied = await tx.select({ slot: planets.slotIndex }).from(planets).where(eq(planets.seasonId, seasonId));
        const capitalIndices = new Set(spec.slots.map(row => row.index));
        const taken = new Set(occupied.map(row => row.slot).filter(index => capitalIndices.has(index)));
        const [queued] = await tx.select({ id: returnApplications.id }).from(returnApplications)
          .where(and(eq(returnApplications.cycleId, season.cycleId), eq(returnApplications.targetShardId, shard.id),
            eq(returnApplications.status, 'QUEUED'), gt(returnApplications.expiresAt, now))).limit(1);
        if (queued) {
          const reserved = await tx.select({ slot: mainVacancies.slotIndex }).from(mainVacancies)
            .where(and(eq(mainVacancies.seasonId, seasonId), isNull(mainVacancies.consumedAt)));
          for (const row of reserved) taken.add(row.slot);
        }
        const slot = pickSpawnSlot(spec.slots, taken);
        // The cap is PEOPLE (`people.ts`); a bot's seat is bounded by its own band.
        const full = seat === 'COMMANDER' && await peopleIn(tx, seasonId) >= shard.playerCap;
        if (!slot || full) throw new GameError('SHARD_FULL', 'This galaxy is full', 409);
        await tx.update(mainVacancies).set({ consumedAt: now, consumedReason: 'NEW_JOIN' })
          .where(and(eq(mainVacancies.seasonId, seasonId), eq(mainVacancies.slotIndex, slot.index), isNull(mainVacancies.consumedAt)));

        // The conditional UPDATE locks the account across concurrent galaxy joins.
        // A failed placement rolls it back; wipes leave the account entitlement consumed.
        const firstGame = seat === 'COMMANDER'
          ? await tx.update(accounts).set({ firstGameShieldAvailable: false })
            .where(and(eq(accounts.id, accountId), eq(accounts.firstGameShieldAvailable, true)))
            .returning({ id: accounts.id })
          : [];

        const [player] = await tx
          .insert(players)
          .values({
            accountId,
            seasonId,
            homeShardId: shard.id,
            mainEnteredAt: now,
            name: account?.displayName ?? 'Commander',
            joinedAt: now,
            lastSeenAt: now,
            lastActiveAt: now,
            // First game: 72h once. Every other season join: the existing 24h.
            // Taking a shot still gives it up after `SHIELD_WOULD_DROP` consent.
            newcomerShieldUntil: new Date(newcomerShieldUntil(now.getTime(), firstGame.length > 0)),
          })
          .onConflictDoNothing({ target: players.accountId })
          .returning();

        if (!player) throw new PlayerExists();

        const planetName = planetNameFor(slot.index);
        const [planet] = await tx
          .insert(planets)
          .values({
            controllerPlayerId: player.id,
            kind: 'CAPITAL',
            seasonId,
            name: planetName,
            slotIndex: slot.index,
            x: slot.x, y: slot.y, z: slot.z,
            /**
             * The opening grant, from the rules package rather than the column
             * default. D22 makes `START` derived arithmetic — exactly the cost of
             * the first four things a commander does — so it has to come from the
             * one place that can be tested against those prices.
             *
             * `PLANET_START` is that arithmetic PLUS the cushion the owner added at
             * D58, because the arithmetic alone is spent to the last crystal by the
             * time onboarding ends and leaves nothing to press.
             */
            alloy: academy ? academy.resources.alloy + (academy.queue?.cost.alloy ?? 0) : PLANET_START.alloy,
            crystal: academy ? academy.resources.crystal + (academy.queue?.cost.crystal ?? 0) : PLANET_START.crystal,
            // The starting tank. T6: a world opens able to fly and unable to make
            // more fuel, which is the chain the opening has to teach.
            deuterium: academy ? academy.resources.deuterium + (academy.queue?.cost.deuterium ?? 0) : PLANET_START.deuterium,
            academyStep: academyStep ?? null,
            builtEver: academy?.builtEver ?? {},
            statsOwnerPlayerId: player.id,
            seasonTelemetry: {
              produced: { alloy: 0, crystal: 0, deuterium: 0 },
              productiveSeconds: 0,
              shipsBuilt: academy?.builtEver ?? {},
            },
            bufferAlloy: academy?.buffer.alloy ?? 0,
            bufferCrystal: academy?.buffer.crystal ?? 0,
            bufferDeuterium: academy?.buffer.deuterium ?? 0,
            lastTickAt: now,
          })
          .onConflictDoNothing({ target: [planets.seasonId, planets.slotIndex] })
          .returning();

        if (!planet) throw new SlotTaken();

        await tx
          .insert(buildings)
          .values(STARTING_BUILDINGS.map((b) => ({ planetId: planet.id, ...b,
            level: academy?.buildings[b.type] ?? b.level })));

        if (academy) {
          const hardware = [
            ...academy.satellites.map((type) => ({ type, level: 1 })),
            ...Object.entries(academy.instruments).filter(([, level]) => level > 0)
              .map(([type, level]) => ({ type, level })),
          ];
          if (hardware.length) await tx.insert(satellites).values(hardware.map((item, slot) => ({
            planetId: planet.id, slot, ...item,
          })));
          const fleet = fleetEntries(academy.fleet);
          if (fleet.length) await tx.insert(units).values(fleet.map(([hull, count]) => ({
            planetId: planet.id, ownerPlayerId: player.id, hull, count, location: 'home',
          })));
          for (const id of academy.claimedRewards) {
            const reward = findRewardTier(id);
            if (!reward) throw new Error(`Missing Academy reward ${id}`);
            await tx.insert(rewardGrants).values({ playerId: player.id, rewardId: id,
              ...reward.tier.reward, claimedAt: now });
          }
          if (academy.queue) {
            // Ordinary paid queue, in this same creation transaction. No instant build.
            await placeBuildingUpgrade(tx, await loadLocked(tx, planet.id, clock), academy.queue.building);
          }
        }

        if (account && adminUsernames.has(account.username)) await equipAdminCapital(tx, planet.id, clock);

        const seasonReward = await deliverSeasonRankReward(tx, {
          accountId,
          targetCycleId: current.cycleId,
          deliveredSeasonId: seasonId,
          planetId: planet.id,
          deliveredAt: now,
        });

        /**
         * NO STARTING FLEET. D22.
         *
         * A commander used to be handed twelve Wasps, which answered the only
         * question the opening asks — what do you spend on — before they had a
         * chance to. They are given the alloy for two instead, and whether that
         * alloy becomes ships, production or an instrument is the first real
         * decision in the game.
         *
         * No `units` rows are written at all: a fleet of zero is the absence of
         * rows, and `loadLocked` already reads a missing row as none.
         */

        // Without this a fresh commander's Wealth stays at the column default of
        // zero, and the rank floor then protects them from every attacker forever.
        await recomputeWealth(tx, planet.id, clock.now());
        await refreshSensorEpoch(tx, planet.id, now);
        if (seat === 'COMMANDER') await ensureUnknownSignalSchedule(tx, player.id, seasonId, now, false, firstGame.length > 0);
        await notifyActiveGalaxyEventsForPlayer(tx, {
          playerId: player.id,
          seasonId,
          at: now,
        });

        // A capital has appeared in the public galaxy and leaderboard. Publish
        // inside the transaction so every API replica invalidates only on commit.
        await publishShard(tx, seasonId, 'world');

        return {
          playerId: player.id,
          planetId: planet.id,
          slotIndex: slot.index,
          seasonId,
          seasonReward,
        };
      });
    } catch (err) {
      if (err instanceof SlotTaken) continue;
      if (err instanceof PlayerExists) {
        // The other request has committed by the time ON CONFLICT DO NOTHING
        // returns nothing, so the winner is readable now. Whether this is a
        // success or a refusal depends on which galaxy it landed in.
        const winner = await readPlacement(db, accountId);
        if (winner) return settle(winner, seasonId);
        // The winner rolled back after taking the row. Nothing is placed, so the
        // honest thing is to try again rather than to report a planet nobody has.
        continue;
      }
      throw err;
    }
  }

  throw new GameError('SHARD_FULL', 'This galaxy is full', 409);
}

export async function touchLastSeen(db: Db, playerId: string, clock: Clock): Promise<void> {
  await db.update(players).set({ lastSeenAt: clock.now() }).where(eq(players.id, playerId));
}

/**
 * THE TALLEST COMMAND CORE EACH OF THESE COMMANDERS HOLDS. D168.
 *
 * The band `canAttack` enforces is a statement about two PEOPLE, not about the two
 * worlds in a launch, so this is the reading it takes: max Core over everything
 * the commander controls, capital and colonies alike. Owner instruction —
 * *"user'ın tüm gezegenlerinden en yüksek tier'ı seçilir"*.
 *
 * ONE QUERY FOR THE WHOLE LIST, because both sides of a launch are asked at once
 * and this sits on the hot path of every raid. It is a `max` in the database
 * rather than rows fetched and reduced here: a commander with four worlds is four
 * rows, and there is no reason to move them.
 *
 * A COMMANDER WHO HOLDS NOTHING READS 1, NOT `undefined`. `coreTier` floors at 1
 * anyway, but the caller of this feeds arithmetic — a missing entry would arrive
 * as `NaN` inside `Math.abs`, and `NaN <= 1` is false, which would silently
 * become "refuse every launch" rather than an error anyone could see. The same
 * floor covers a world with no CORE row at all.
 *
 * IT IS DELIBERATELY NOT LOCKED. A Core upgrade landing in the same instant as a
 * launch can only move a commander one level, the tier is a three-level bucket,
 * and taking a row lock on the defender's worlds here would introduce exactly the
 * two-planet lock ordering the architecture rules forbid.
 */
export async function peakCoreLevels(
  db: Db | Tx,
  playerIds: readonly string[],
): Promise<Map<string, number>> {
  const peaks = new Map<string, number>();
  if (playerIds.length === 0) return peaks;
  for (const id of playerIds) peaks.set(id, 1);

  const rows = await db
    .select({
      playerId: planets.controllerPlayerId,
      peak: sql<number>`max(${buildings.level})::int`,
    })
    .from(planets)
    .innerJoin(buildings, and(
      eq(buildings.planetId, planets.id),
      eq(buildings.type, 'CORE'),
    ))
    .where(inArray(planets.controllerPlayerId, [...playerIds]))
    .groupBy(planets.controllerPlayerId);

  for (const row of rows) {
    if (row.playerId === null) continue;
    peaks.set(row.playerId, Math.max(1, row.peak));
  }
  return peaks;
}


/**
 * THE TWO ATTACK SHIELDS LIVE IN `attackProtection.ts`.
 *
 * `assertNewcomerShields` stood here while there was one column to read. The
 * 2026-09-14 recovery shield adds a second, and the composition of the two — plus
 * the storage reading and the outbound-raid refusal that decide when one is EARNED
 * — is a subject of its own rather than a paragraph in the join/placement service.
 * `assertAttackProtections` is what `mission.ts` and `strategic.ts` call now.
 */

