import type { Db, Queryable } from '../db/client.js';
import type { SensorEpoch } from '@astera/rules';
import { sensorHistoryForPlayer } from './sensorHistory.js';
import { PRIVATE_PREFIX, type EventBus, type StreamEvent } from '../stream/bus.js';
import { AsyncCache, type AsyncCacheStats } from './asyncCache.js';
import { publicWorlds, type PublicWorld } from './publicGalaxy.js';
import { loadTrafficSnapshot, sensorPosts, type SensorPost, type TrafficSnapshot } from './traffic.js';
import { rememberedWorlds, type RememberedWorlds } from './intel.js';
import { loadMiningSnapshot, type MiningSnapshot } from './mining.js';
import { loadPirateSnapshot, type PirateSnapshot } from './pirateField.js';
import {
  commanderTopology,
  type CommanderTopology,
} from './ownership.js';

export interface ProjectionConfig {
  enabled: boolean;
  maxSeasons: number;
  maxAccounts: number;
  commanderTtlMs: number;
  publicTtlMs: number;
  trafficTtlMs: number;
  miningTtlMs: number;
}

export interface ProjectionStatus {
  enabled: boolean;
  commander: AsyncCacheStats;
  sensors: AsyncCacheStats;
  remembered: AsyncCacheStats;
  sensorHistory: AsyncCacheStats;
  publicGalaxy: AsyncCacheStats;
  traffic: AsyncCacheStats;
  mining: AsyncCacheStats;
  pirates: AsyncCacheStats;
}

/**
 * Replica-local shared projections. D99.
 *
 * The bus is the correctness boundary: when LISTEN is down, reads bypass every
 * cache. A committed shard event invalidates before the same process writes the
 * SSE line, and single-flight turns the resulting fan-out into one rebuild on
 * each API replica. Shared world/traffic/mining entries contain no caller field;
 * separate account/player-keyed entries hold only that caller's private topology.
 */
export class Projections {
  private readonly publicGalaxy: AsyncCache<PublicWorld[]>;
  private readonly traffic: AsyncCache<TrafficSnapshot>;
  private readonly mining: AsyncCache<MiningSnapshot>;
  /**
   * THE SEASON'S PIRATE LANE AND ITS STORED DAMAGE. D150.
   *
   * Season-keyed and caller-free, exactly like `mining`: the snapshot holds raw
   * lane facts and every commander's fog is applied afterwards, per request. A
   * shared entry that had already been filtered for somebody would be a cache
   * that leaks one commander's sight to the next caller.
   *
   * It shares `miningTtlMs` because it is the same kind of thing — a derived
   * field plus a small mutation table — and a second knob for the same decision
   * is one more number that can be set wrong.
   */
  private readonly pirates: AsyncCache<PirateSnapshot>;
  private readonly commanders: AsyncCache<CommanderTopology>;
  /**
   * WHAT EACH COMMANDER CAN SEE MOVING. D123.
   *
   * Player-keyed and cleared in exactly the branches that clear `commanders`,
   * because the two have to agree: a captured colony brings both a world id and
   * that world's eyes, and a horizon computed from a fresher world list than the
   * one the caller is filtering with would publish contacts around a planet the
   * same request says they do not hold.
   *
   * A completed build invalidates its owner's exact entry before the waking client
   * can reuse it. An impact has no player id by design, so the rare destructive
   * event clears the bounded set: a lowered Core may shrink a Telescope or Radar,
   * and serving the old wider horizon even briefly would reveal unearned data.
   * TTL remains only a repair net; it is never the correctness mechanism.
   */
  private readonly sensors: AsyncCache<SensorPost[]>;
  /**
   * WHAT EACH COMMANDER REMEMBERS ABOUT WORLDS THEY CANNOT SEE. D127.
   *
   * Player-keyed and cleared with `commanders`, for the same reason: a captured
   * colony changes both what a caller controls and what they can resolve without
   * a probe, and the two may never be read from different generations.
   *
   * A new probe report invalidates its player's entry on the private event. TTL is
   * only the fallback if caching is disabled or a listener reconnect forces all
   * reads to bypass; the waking client must see the committed report immediately.
   */
  private readonly remembered: AsyncCache<RememberedWorlds>;
  private readonly sensorHistory: AsyncCache<SensorEpoch[]>;
  private readonly stopObserving: () => void;
  private readonly stopObservingResets: () => void;

  constructor(
    private readonly db: Db,
    private readonly bus: EventBus,
    private readonly config: ProjectionConfig,
  ) {
    const usable = (): boolean => this.config.enabled && this.bus.status().listening;
    this.commanders = new AsyncCache<CommanderTopology>(
      config.maxAccounts,
      config.commanderTtlMs,
      usable,
    );
    this.sensors = new AsyncCache<SensorPost[]>(
      config.maxAccounts,
      config.commanderTtlMs,
      usable,
    );
    this.remembered = new AsyncCache<RememberedWorlds>(
      config.maxAccounts,
      config.commanderTtlMs,
      usable,
    );
    this.sensorHistory = new AsyncCache<SensorEpoch[]>(config.maxAccounts, config.commanderTtlMs, usable);
    this.publicGalaxy = new AsyncCache<PublicWorld[]>(
      config.maxSeasons,
      config.publicTtlMs,
      usable,
    );
    this.traffic = new AsyncCache<TrafficSnapshot>(
      config.maxSeasons,
      config.trafficTtlMs,
      usable,
    );
    this.mining = new AsyncCache<MiningSnapshot>(
      config.maxSeasons,
      config.miningTtlMs,
      usable,
    );
    this.pirates = new AsyncCache<PirateSnapshot>(
      config.maxSeasons,
      config.miningTtlMs,
      usable,
    );
    this.stopObserving = bus.observe((event) => {
      this.onEvent(event);
    });
    this.stopObservingResets = bus.observeReset(() => {
      this.clear();
    });
  }

  private readonly placements = new Map<string, string>();

  /** The database placement check is authoritative even if NOTIFY arrives late. */
  reconcilePlacement(accountId: string, placement: string): void {
    if (this.placements.get(accountId) === placement) return;
    // A first request from an unmoved commander must not flush shared public data.
    if (this.placements.has(accountId) || !placement.endsWith(':0')) this.clear();
    if (this.placements.size >= this.config.maxAccounts) this.placements.clear();
    this.placements.set(accountId, placement);
  }

  async worlds(seasonId: string, now: Date): Promise<PublicWorld[]> {
    const load = () => publicWorlds(this.db, seasonId, now);
    const worlds = await this.publicGalaxy.get(seasonId, load);
    // EMP is a timed public state. A cached snapshot can outlive its end without
    // another database mutation to publish; refresh it at the boundary.
    if (worlds.some((world) => world.state.kind === 'EMP' && world.state.until <= now)) {
      this.publicGalaxy.invalidate(seasonId);
      return this.publicGalaxy.get(seasonId, load);
    }
    return worlds;
  }

  commander(accountId: string): Promise<CommanderTopology> {
    return this.commanders.get(accountId, () => commanderTopology(this.db, accountId));
  }

  /** The caller's own sensor posts, for the traffic horizon. D123. */
  sensorsFor(playerId: string, planetIds: readonly string[]): Promise<SensorPost[]> {
    return this.sensors.get(playerId, () => sensorPosts(this.db, planetIds));
  }

  /** The caller's own probe memory, for the three galaxy intel states. D127. */
  rememberedFor(playerId: string): Promise<RememberedWorlds> {
    return this.remembered.get(playerId, () => rememberedWorlds(this.db, playerId));
  }

  historyFor(playerId: string, seasonId: string): Promise<SensorEpoch[]> {
    return this.sensorHistory.get(`${playerId}:${seasonId}`,
      () => sensorHistoryForPlayer(this.db, playerId, seasonId));
  }

  trafficSnapshot(seasonId: string, now: Date = new Date()): Promise<TrafficSnapshot> {
    return this.traffic.get(seasonId, () => loadTrafficSnapshot(this.db, seasonId, now));
  }

  miningSnapshot(
    seasonId: string,
    now: Date,
    source: Queryable = this.db,
  ): Promise<MiningSnapshot> {
    // A transactional caller may supply its already-acquired connection. This is
    // important for mutations that assemble a view before commit: a cold fan-out
    // must not hold every pool slot while its shared fill waits for another one.
    return this.mining.get(seasonId, () => loadMiningSnapshot(source, seasonId, now));
  }

  pirateSnapshot(
    seasonId: string,
    now: Date,
    source: Queryable = this.db,
  ): Promise<PirateSnapshot> {
    // A transactional caller may supply its already-acquired connection, for the
    // same reason `miningSnapshot` does: a cold fan-out must not hold every pool
    // slot while its shared fill waits for another one.
    return this.pirates.get(seasonId, () => loadPirateSnapshot(source, seasonId, now));
  }

  invalidate(seasonId: string): void {
    this.publicGalaxy.invalidate(seasonId);
    this.traffic.invalidate(seasonId);
    this.mining.invalidate(seasonId);
    this.pirates.invalidate(seasonId);
  }

  status(): ProjectionStatus {
    return {
      enabled: this.config.enabled && this.bus.status().listening,
      commander: this.commanders.status(),
      sensors: this.sensors.status(),
      remembered: this.remembered.status(),
      sensorHistory: this.sensorHistory.status(),
      publicGalaxy: this.publicGalaxy.status(),
      traffic: this.traffic.status(),
      mining: this.mining.status(),
      pirates: this.pirates.status(),
    };
  }

  close(): void {
    this.stopObserving();
    this.stopObservingResets();
    this.clear();
  }

  /**
   * EVERY CACHE, AND THE LIST HAS TO STAY COMPLETE.
   *
   * Called when the bus resets, which means this process may have MISSED events.
   * `remembered` was left out of it and that broke the contract its own docblock
   * states — it is cleared with `commanders`, always, because the two are read in
   * the same request and may never come from different generations. A reset that
   * refreshed every projection but one would go on serving pre-reset probe memory
   * against a freshly-read world list.
   */
  private clear(): void {
    this.commanders.clear();
    this.sensors.clear();
    this.remembered.clear();
    this.sensorHistory.clear();
    this.publicGalaxy.clear();
    this.traffic.clear();
    this.mining.clear();
    this.pirates.clear();
  }

  private onEvent(event: StreamEvent): void {
    // Global operator content has no bearing on game projections.
    if ('global' in event) return;
    if ('playerId' in event) {
      if (event.kind === 'private:sensors') {
        this.sensors.invalidate(event.playerId);
        this.sensorHistory.invalidatePrefix(`${event.playerId}:`);
      }
      /**
       * A PROBE CAME HOME, SO ONE COMMANDER'S MAP JUST CHANGED. D127.
       *
       * One of the private events a caller projection depends on, and it had to be
       * handled or the feature contradicted itself for half a minute: the report
       * lands, `probe_report` wakes the client, the client refetches — and
       * `/api/galaxy` answers out of a cache that still says UNKNOWN, so the Intel
       * centre holds a report about a world the disc is still drawing as an
       * unmarked point.
       *
       * It is on the same channel every replica already listens to, and it carries
       * a player id and a kind and nothing else, so acting on it discloses nothing
       * that was not already addressed to that one commander.
       */
      if (event.kind === 'probe_report') this.remembered.invalidate(event.playerId);
      /**
       * AND A FLEET IS EYES TOO. D151.
       *
       * The same invalidation for the same reason, through the other door: an
       * arrival writes the record inside its own transaction and publishes this on
       * commit, so the raid's own `raid_result` wake finds a map that has already
       * caught up. `rememberWorld` is the only writer and the only publisher, so
       * a craft added later cannot forget to say so.
       */
      if (event.kind === `${PRIVATE_PREFIX}memory`) this.remembered.invalidate(event.playerId);
      // Ground instruments are private hardware, so their completion deliberately
      // has no shard event. The addressed event is enough to refresh this owner's
      // reach without advertising to the rest of the galaxy what they just built.
      if (event.kind === 'build_complete' || event.kind === 'colony_fault' || event.kind === 'fault_repair_complete') {
        this.sensors.invalidate(event.playerId);
        // Older worker images do not emit private:sensors yet. These addressed
        // wakes keep the new cache correct throughout a compatible rolling deploy.
        this.sensorHistory.invalidatePrefix(`${event.playerId}:`);
      }
      // The row is shared by season but the launch instant is private to the two
      // participants and commanders whose effective Telescope covers it. The
      // event therefore cannot carry a shard id; clearing this bounded cache is
      // the safe price of keeping hidden launch timing off the shard channel.
      if (event.kind === 'private:strategic-sight') this.traffic.clear();
      return;
    }

    // Invalidate only the shared payload the event can actually move. Chat and
    // chat traffic is deliberately absent. Score is present because the public
    // galaxy now carries the three podium badges; a rank-changing battle moves
    // that projection even though it moves no planet hardware.
    const kind = event.kind;
    if (
      kind === 'shard:world'
      || kind === 'shard:control'
      || kind === 'shard:season'
      || kind === 'shard:rollover'
    ) {
      // Keyed by account/player rather than shard, so an ownership mutation clears
      // the small bounded sets. These events are rare; stale ownership is not allowed.
      // The sensor posts go with them: they are derived from the same world list
      // and the two may never be read from different generations.
      this.commanders.clear();
      this.sensors.clear();
      this.remembered.clear();
      this.sensorHistory.clear();
    }
    if (kind === 'shard:impact') {
      // The event intentionally names no target. An impact can lower Core and
      // therefore clamp either sensor, so clearing the small player-keyed cache is
      // the only safe invalidation that does not add information to the event.
      this.sensors.clear();
      this.sensorHistory.clear();
    }
    if (
      kind === 'shard:world'
      || kind === 'shard:impact'
      || kind === 'shard:control'
      || kind === 'shard:recovery'
      || kind === 'shard:protection'
      || kind === 'shard:clan'
      || kind === 'shard:score'
      || kind === 'shard:season'
      || kind === 'shard:rollover'
    ) {
      this.publicGalaxy.invalidate(event.shard);
    }
    if (
      kind === 'shard:launch'
      || kind === 'shard:arrival'
      || kind === 'shard:mining'
      || kind === 'shard:pirate'
      || kind === 'shard:impact'
      || kind === 'shard:control'
      || kind === 'shard:transfer'
      || kind === 'shard:season'
      || kind === 'shard:rollover'
    ) {
      this.traffic.invalidate(event.shard);
    }
    /*
      THE DEBRIS LIST LIVES IN THIS SNAPSHOT, AND A PIRATE BATTLE CREATES ONE. D150.

      `shard:pirate` was the one kind that could write a `debris_fields` row and
      leave this projection warm. The engagement is ten seconds by design; the
      wreck then took up to `MINING_CACHE_TTL_MS` longer to appear, because the
      read provoked by the commander's own `raid_result` wake was answered from a
      snapshot loaded before the battle committed. The field at the rendezvous is
      the entire payoff of the target class and the public race to collect it is
      half of what makes the fight worth watching (D32) — it may not arrive on a
      cache expiry.
    */
    if (
      kind === 'shard:mining'
      || kind === 'shard:arrival'
      || kind === 'shard:pirate'
      || kind === 'shard:impact'
      || kind === 'shard:control'
      || kind === 'shard:season'
      || kind === 'shard:rollover'
    ) {
      this.mining.invalidate(event.shard);
    }
    /*
      A raid is what changes `pirate_state`, and a season boundary is what replaces
      the lane. Nothing else moves this projection: the orbit, the roster and the
      hoard are all derived, so a build, a capture or a score change cannot touch it.
    */
    if (
      kind === 'shard:pirate'
      || kind === 'shard:season'
      || kind === 'shard:rollover'
    ) {
      this.pirates.invalidate(event.shard);
    }
  }
}

sources.apps/server/src/services/publicGalaxy.ts:
import { accountCosmeticEquipment } from './cosmeticEquipment.js';
import { and, eq, inArray, isNull } from 'drizzle-orm';
import {
  SATELLITE_IDS,
  alloyRate,
  coreTier,
  crystalRate,
  neutralReserve,
  neutralThreat,
  storageCap,
  planetSkinById,
  planetSkinStatus,
  type PlanetSkinId,
  type PlanetSkinStatus,
  type NeutralReserve,
  type NeutralThreat,
  type SatelliteId,
  type Vec3,
  type CountryCode,
} from '@astera/rules';
import type { Queryable } from '../db/client.js';
import {
  accounts,
  buildings,
  clanMemberships,
  clans,
  neutralPlanetState,
  planetFaults,
  planets,
  players,
  satellites,
} from '../db/schema.js';
import { protectionFrom } from './attackProtection.js';
import {
  compareDominionScoresDescending,
  dominionPodium,
  playerDominionSql,
} from './dominion.js';

/**
 * EVERY WORLD IN A SEASON, AT THE DETAIL EVERYBODY IS ENTITLED TO.
 *
 * THIS IS THE FOG'S FLOOR, AND IT LIVES IN ONE PLACE ON PURPOSE. Two surfaces read
 * it now — `/api/galaxy`, which adds what the caller has EARNED on top (their own
 * world, and a fleet reading for anything they are watching), and `/api/preview`,
 * which is public and adds nothing at all. A second copy of this projection is a
 * second place a private column can be added by accident, and the one that is
 * unauthenticated is the copy nobody would think to check.
 *
 * CORE LEVEL IS PUBLIC AS OF THE DYSON RINGS, and it did not used to be. This
 * projection published only a coarse TIER, on the argument that knowing a world's
 * exact development is what a probe is for and that giving it away undercuts the
 * cheapest tier of intel. That argument still stands on its own terms — what
 * changed is the owner's decision that the disc should SHOW development at every
 * Core level rather than every third one: the ring count steps every three levels
 * and the colour steps every one, and there is no way to draw that from a tier.
 *
 * WHAT IT COSTS, stated rather than glossed: a probe's development reading is now
 * confirmation rather than news. What a probe still sells alone — and what decides
 * whether a raid pays — is the fleet, the ground defence, the shield strength and
 * the stores, none of which are here or anywhere near here.
 *
 * The tier stays, and is still what D49's ±2 attack band is defined on, so the
 * combat rule is unchanged and remains readable off the map before a fleet is
 * packed.
 *
 * TWO QUERIES FOR EVERY CORE LEVEL AND EVERY SATELLITE, never one per planet, and
 * both SCOPED TO THE SEASON. With multiple galaxies live in one database (D21/D100) an
 * unscoped read is ten times the rows to fetch and discard on the most frequent
 * read in the game.
 */
export interface PublicWorld {
  id: string;
  ringId?: string;
  /** Equipped cosmetic only; no ownership rights or payment data. */
  skin?: { id: PlanetSkinId; status: PlanetSkinStatus };
  name: string;
  owner: string;
  /** Public commander identity; omitted for neutral worlds. */
  country?: CountryCode;
  kind: 'CAPITAL' | 'COLONY' | 'NEUTRAL';
  controller:
    | { kind: 'PLAYER'; playerId: string; displayName: string }
    | { kind: 'NEUTRAL'; tier: 1 | 2 | 3 };
  position: Vec3;
  coreTier: number;
  /**
   * The exact Command Core level. Public since the dyson rings — see the note
   * above for what that trades away. `coreTier` is derived from this and kept
   * because D49's attack band is defined on the tier, not on the level.
   */
  coreLevel: number;
  /** Types only. Never levels — see the note on `publicOrbit`. */
  satellites: SatelliteId[];
  /** Is there a dome. Never how strong it is. */
  shielded: boolean;
  /** Independent of EMP: a protected world still refuses attack launches. */
  attackProtectedUntil: Date | null;
  vacation: boolean;
  state:
    | { kind: 'NORMAL' }
    | { kind: 'EMP'; until: Date; hits?: number }
    | { kind: 'RECOVERY'; until: Date }
    | { kind: 'PROTECTED'; until: Date };
  neutral?: {
    tier: 1 | 2 | 3;
    threat: NeutralThreat;
    reserve: NeutralReserve;
    claimUntil: Date | null;
    /**
     * When the raider's first hour ends (owner, 2026-10-07) — the clock only. WHO holds it
     * is never in this shared projection: the galaxy route tells the raider alone.
     */
    claimPriorityUntil: Date | null;
    nextReinforcementAt: Date | null;
  };
  clan?: { id: string; name: string; tag: string };
  /** Only the public podium; lower exact ranks stay on the leaderboard surface. */
  dominionRank?: 1 | 2 | 3;
}

/**
 * HARDWARE IS PUBLIC; READINGS ARE NOT. D15.
 *
 * Which satellites a planet carries is visible to everyone — they are physical
 * objects in orbit and the 3D galaxy draws them. Their LEVELS never leave the
 * owner's own planet payload: an Aegis is visible, its shield strength is not, and
 * shield strength is what decides whether a raid pays.
 *
 * Only SATELLITES are published. The four ground instruments — Telescope, Radar,
 * Aegis, Veil — are on the surface and are nobody else's business (D25): whether a
 * world can see you, and whether it can tell you are looking, is exactly what the
 * information game is about.
 */
const publicOrbit = (rows: readonly { planetId: string; type: string }[]) => {
  const known = new Set<string>(SATELLITE_IDS);
  const map = new Map<string, SatelliteId[]>();
  for (const row of rows) {
    if (!known.has(row.type)) continue;
    const list = map.get(row.planetId);
    if (list) list.push(row.type as SatelliteId);
    else map.set(row.planetId, [row.type as SatelliteId]);
  }
  return map;
};

/**
 * Who has a dome up. The one instrument fact that is public, and only as a boolean.
 *
 * A shielded world must read as shielded: a dome is a physical object like any
 * other, deterrence is meant to be legible, and a raider who cannot tell an
 * armoured world from a bare one is not making a decision. What stays private is
 * the LEVEL behind it, which is what actually decides the raid.
 */
const publicShields = (rows: readonly { planetId: string; type: string }[]) =>
  new Set(rows.filter((r) => r.type === 'AEGIS').map((r) => r.planetId));

/**
 * ONE WORLD'S OUTSIDE, AS A PROBE RECORDS IT. D127.
 *
 * Derived from the SAME `PublicWorld` the galaxy is built from rather than from a
 * second query of its own, because the two would drift the first time one of them
 * was edited — the failure `packages/rules/src/view.ts` exists to prevent, in a
 * different place. What a probe brings home and what a Telescope shows live have
 * to be the same shape or the interface tells two stories about one world.
 */
export const silhouetteOf = (world: PublicWorld): {
  skin?: { id: PlanetSkinId; status: PlanetSkinStatus };
  owner: string;
  country?: CountryCode;
  controllerPlayerId: string | null;
  clan: { id: string; name: string; tag: string } | null;
  kind: 'CAPITAL' | 'COLONY' | 'NEUTRAL';
  coreLevel: number;
  satellites: string[];
  shielded: boolean;
} => ({
  ...(world.skin ? { skin: world.skin } : {}),
  owner: world.owner,
  ...(world.country ? { country: world.country } : {}),
  controllerPlayerId:
    world.controller.kind === 'PLAYER' ? world.controller.playerId : null,
  clan: world.clan ?? null,
  kind: world.kind,
  coreLevel: world.coreLevel,
  satellites: [...world.satellites],
  shielded: world.shielded,
});

export async function publicWorlds(
  db: Queryable,
  seasonId: string,
  now = new Date(),
  /**
   * Narrow to specific worlds. Used by the probe, which needs exactly one and must
   * not pay for the whole disc — and must not compute it a second way either.
   */
  planetIds?: readonly string[],
): Promise<PublicWorld[]> {
  const rows = await db
    .select({
      planet: planets,
      ownerAccountId: accounts.id,
      ownerName: accounts.displayName,
      ownerCountry: accounts.countryCode,
      neutral: neutralPlanetState,
      clanId: clans.id,
      clanName: clans.name,
      clanTag: clans.tag,
      // Left-joined, so a neutral world genuinely answers NULL here.
      playerScore: playerDominionSql,
      playerJoinedAt: players.joinedAt,
      /**
       * THE COMMANDER'S FIRST-DAY SHIELD, AS A PROPERTY OF EVERY WORLD THEY HOLD.
       * D183.
       *
       * PUBLIC ON PURPOSE, and it is the only way the rule can work: D124 —
       * "a rule the player cannot see is not a usable rule". A raider who cannot
       * tell a shielded commander from a reachable one discovers the rule by
       * committing a fleet and being refused, which is an error message rather
       * than a rule.
       *
       * IT REVEALS NOTHING ELSE. That a commander joined recently is already
       * readable from the ladder and from an undeveloped Core; what this adds is
       * the one fact a launch decision turns on, and it expires on its own.
       */
      playerShieldUntil: players.newcomerShieldUntil,
      /** The other half of the same fact since 2026-09-14. See `protectionFrom`. */
      playerRecoveryShieldUntil: players.recoveryShieldUntil,
    })
    .from(planets)
    .leftJoin(players, eq(planets.controllerPlayerId, players.id))
    .leftJoin(accounts, eq(players.accountId, accounts.id))
    .leftJoin(
      clanMemberships,
      and(eq(clanMemberships.playerId, players.id), isNull(clanMemberships.leftAt)),
    )
    .leftJoin(
      clans,
      and(eq(clans.id, clanMemberships.clanId), isNull(clans.disbandedAt)),
    )
    .leftJoin(neutralPlanetState, eq(neutralPlanetState.planetId, planets.id))
    .where(planetIds === undefined
      ? eq(planets.seasonId, seasonId)
      : and(eq(planets.seasonId, seasonId), inArray(planets.id, [...planetIds])));

  const ids = rows.map((r) => r.planet.id);
  if (ids.length === 0) return [];

  const [buildingRows, satelliteRows, coreOutageRows] = await Promise.all([
    db
      .select({ planetId: buildings.planetId, type: buildings.type, level: buildings.level })
      .from(buildings)
      .where(and(inArray(buildings.type, ['CORE', 'REFINERY', 'EXTRACTOR']), inArray(buildings.planetId, ids))),
    db
      .select({ planetId: satellites.planetId, type: satellites.type })
      .from(satellites)
      .where(inArray(satellites.planetId, ids)),
    db
      .select({ planetId: planetFaults.planetId })
      .from(planetFaults)
      .where(and(
        inArray(planetFaults.planetId, ids),
        eq(planetFaults.kind, 'CORE_OUTAGE'),
      )),
  ]);

  const cosmeticEquipment = await accountCosmeticEquipment(db, [...new Set(rows.flatMap(row => row.ownerAccountId ? [row.ownerAccountId] : []))]);
  const levels = new Map(buildingRows.map((r) => [`${r.planetId}:${r.type}`, r.level]));
  const installed = publicOrbit(satelliteRows);
  const shielded = publicShields(satelliteRows);
  const darkCores = new Set(coreOutageRows.map((row) => row.planetId));
  const commanders = new Map<string, { score: number; joinedAt: Date }>();
  for (const row of rows) {
    const playerId = row.planet.controllerPlayerId;
    if (!playerId || !row.playerJoinedAt) continue;
    commanders.set(playerId, { score: row.playerScore, joinedAt: row.playerJoinedAt });
  }
  const dominionRanks = planetIds === undefined
    ? new Map(
        [...commanders]
          .sort(([leftId, left], [rightId, right]) =>
            compareDominionScoresDescending(left.score, right.score)
            || left.joinedAt.getTime() - right.joinedAt.getTime()
            || leftId.localeCompare(rightId))
          .slice(0, 3)
          .map(([playerId], index) => [playerId, (index + 1) as 1 | 2 | 3] as const),
      )
    : await dominionPodium(db, seasonId, new Set());

  return rows.map((r) => {
    const core = levels.get(`${r.planet.id}:CORE`) ?? 0;
    const refinery = levels.get(`${r.planet.id}:REFINERY`) ?? 0;
    const extractor = levels.get(`${r.planet.id}:EXTRACTOR`) ?? 0;
    const vault = levels.get(`${r.planet.id}:VAULT`) ?? 0;
    const tier = (r.neutral?.tier ?? 1) as 1 | 2 | 3;
    const controller = r.planet.kind === 'NEUTRAL'
      ? { kind: 'NEUTRAL' as const, tier }
      : {
          kind: 'PLAYER' as const,
          playerId: r.planet.controllerPlayerId!,
          displayName: r.ownerName ?? 'Unknown commander',
        };
    /*
      THE THREE STATES A WORLD CAN BE IN, AND THE ORDER IS THE SEVERITY.

      RECOVERY is a world that has been struck and is dark; PROTECTED is a world
      that cannot be raided. The second now has THREE sources — an occupation window
      on one captured world (`protectedUntil`), its commander's first-day shield
      (D183), and since 2026-09-14 their recovery shield — and all three mean the
      same thing to a raider, so they wear the same badge and the latest of them is
      the one that is drawn. The two commander shields are composed by
      `protectionFrom`, which is the only place either column is interpreted.
    */
    const commanderProtection = r.planet.kind === 'NEUTRAL'
      ? null
      : protectionFrom(r.playerShieldUntil, r.playerRecoveryShieldUntil, now);
    const shieldedUntil = [
      r.planet.protectedUntil,
      commanderProtection === null ? null : new Date(commanderProtection.until),
    ].filter((at): at is Date => at !== null && at > now)
      .sort((a, b) => b.getTime() - a.getTime())[0] ?? null;
    const empActive = r.planet.empUntil !== null && r.planet.empUntil > now;
    const state = empActive
      ? { kind: 'EMP' as const, until: r.planet.empUntil!, hits: Math.max(1, r.planet.empHits) }
      : r.planet.recoveryUntil && r.planet.recoveryUntil > now
        ? { kind: 'RECOVERY' as const, until: r.planet.recoveryUntil }
      : shieldedUntil
        ? { kind: 'PROTECTED' as const, until: shieldedUntil }
        : { kind: 'NORMAL' as const };
    const skin = r.planet.controllerPlayerId && r.planet.equippedSkinId
      ? planetSkinById(r.planet.equippedSkinId)
      : null;
    return {
      id: r.planet.id,
      ...(r.ownerAccountId && cosmeticEquipment.get(r.ownerAccountId)?.RING
        ? { ringId: cosmeticEquipment.get(r.ownerAccountId)!.RING } : {}),
      ...(skin
        ? { skin: { id: skin.id, status: planetSkinStatus(r.planet.recoveryBoostUntil, now) } }
        : {}),
      name: r.planet.name,
      owner: r.ownerName ?? `Neutral T${String(tier)}`,
      ...(controller.kind === 'PLAYER' && r.ownerCountry ? { country: r.ownerCountry } : {}),
      kind: r.planet.kind,
      controller,
      position: { x: r.planet.x, y: r.planet.y, z: r.planet.z },
      coreTier: coreTier(core),
      coreLevel: core,
      satellites: installed.get(r.planet.id) ?? [],
      // A dome is public hardware, and a dark dome is a public physical state too.
      // Keep the fault itself private; publish only the observable consequence.
      shielded: shielded.has(r.planet.id) && !darkCores.has(r.planet.id) && !empActive,
      attackProtectedUntil: shieldedUntil,
      vacation: r.planet.vacationUntil !== null && r.planet.vacationUntil > now,
      state,
      ...(r.clanId && r.clanName && r.clanTag
        ? { clan: { id: r.clanId, name: r.clanName, tag: r.clanTag } }
        : {}),
      ...(r.planet.controllerPlayerId && dominionRanks.has(r.planet.controllerPlayerId)
        ? { dominionRank: dominionRanks.get(r.planet.controllerPlayerId)! }
        : {}),
      ...(r.planet.kind === 'NEUTRAL' && r.neutral
        ? {
            neutral: {
              tier,
              threat: neutralThreat(tier),
              reserve: neutralReserve(
                { alloy: r.planet.alloy, crystal: r.planet.crystal, deuterium: 0 },
                {
                  alloy: storageCap(alloyRate(refinery), vault),
                  crystal: storageCap(crystalRate(extractor), vault),
                  deuterium: 0,
                },
              ),
              claimUntil: r.neutral.claimUntil,
              // An hour nobody holds is no hour: a deleted raider's column is SET NULL and the
              // server refuses nobody, so the map must not say it does.
              claimPriorityUntil: r.neutral.claimPriorityPlayerId === null ? null : r.neutral.claimPriorityUntil,
              nextReinforcementAt: r.neutral.nextReinforcementAt,
            },
          }
        : {}),
    };
  });
}

