import { planetRadiationPath } from './planetAegis.js';
import { asc, eq } from 'drizzle-orm';
import { hpRadiationApplies, segmentsExposureHp } from '@astera/rules';
import type { Clock } from '../clock.js';
import type { Db } from '../db/client.js';
import { planets, seasons } from '../db/schema.js';
import { publishShard } from '../stream/bus.js';
import { GameError } from './planet.js';
import { monumentMotionStart } from './monumentMotion.js';
import { schedulePlanetRadiation } from './planetRadiation.js';
import { cancelRepairsForRadiation } from './buildQueue.js';
import { hpSourcesForTarget } from './radiationSources.js';

/** Explicit active-season cutover: never a ruleset bump or a rewrite of old dose. */
export async function activateRadiationBombs(db: Db, input: { seasonId: string; clock: Clock; apply: boolean }) {
  return db.transaction(async tx => {
    const [season] = await tx.select().from(seasons).where(eq(seasons.id, input.seasonId)).for('update');
    const now = input.clock.now();
    if (season?.status !== 'live' || season.closedAt || now < season.startsAt || now >= season.endsAt
      || !hpRadiationApplies(season.rulesetVersion)) {
      throw new GameError('SEASON_FROZEN', 'An open HP radiation season is required', 409);
    }
    if (!monumentMotionStart(season)) {
      throw new GameError('MONUMENT_MOTION_REQUIRED', 'Activate entity radiation first', 409);
    }
    if (season.radiationBombStartsAt) return { status: 'ALREADY_ACTIVE' as const, applied: false,
      startsAt: season.radiationBombStartsAt, planets: 0 };
    const worlds = await tx.select().from(planets).where(eq(planets.seasonId, season.id)).orderBy(asc(planets.id)).for('update');
    if (input.apply) {
      await tx.update(seasons).set({ radiationBombStartsAt: now }).where(eq(seasons.id, season.id));
      await tx.update(planets).set({ radiationSettledAt: now }).where(eq(planets.seasonId, season.id));
      const active = { ...season, radiationBombStartsAt: now };
      for (const world of worlds) {
        const sources = await hpSourcesForTarget(tx, active, { kind: 'PLANET', id: world.id }, now, season.endsAt);
        if (segmentsExposureHp(await planetRadiationPath(tx, world, now.getTime(), now.getTime() + 1), sources) > 0) {
          await cancelRepairsForRadiation(tx, world.id, now);
        }
        if (sources.length > 0) await schedulePlanetRadiation(tx, { ...world, radiationSettledAt: now }, active, now);
      }
      await publishShard(tx, season.id, 'world');
    }
    return { status: 'READY' as const, applied: input.apply, startsAt: now, planets: worlds.length };
  });
}

sources.apps/server/src/services/radiationBombIn:
import { and, eq } from 'drizzle-orm';
import { ANTI_STRATEGIC, pointAlong } from '@astera/rules';
import type { Tx } from '../db/client.js';
import { radiationBombFlights, strategicAssets } from '../db/schema.js';
import { schedule } from '../worker/queue.js';
import { firstShotSince, interceptionLeg, nextCheckAt, publishInterceptionSight, triggerAt, type InterceptionLeg } from './strategicInterception.js';
import { noteRadiationInventoryChange } from './planetRadiation.js';
import { ownedHonorNavy } from './honorNavy.js';
import { strategicHonorIntent, settleStrategicInterceptionHonor } from './honorStrategic.js';
import { honorStrategicValue, RADIATION_BOMB } from '@astera/rules';

type Flight = typeof radiationBombFlights.$inferSelect;

export async function bombInterceptionLeg(tx: Tx, flight: Flight): Promise<InterceptionLeg | null> {
  if (flight.targetPlanetId === null) return null;
  return interceptionLeg(tx, { id: flight.id, seasonId: flight.seasonId, ownerPlayerId: flight.ownerPlayerId,
    originPlanetId: flight.originPlanetId, targetPlanetId: flight.targetPlanetId,
    departAt: flight.departAt, arriveAt: flight.arriveAt }, { from: flight.originPosition, to: flight.targetPosition });
}

/** Caller holds season → sorted worlds → flight locks, shared with Death Star charge claims. */
export async function interceptRadiationBomb(tx: Tx, flight: Flight, now: Date, observedAt = now): Promise<boolean> {
  const leg = await bombInterceptionLeg(tx, flight);
  if (!leg) return false;
  const honor = await strategicHonorIntent(tx, flight.seasonId, `bomb:${flight.id}`);
  const defenceNavy = honor ? await ownedHonorNavy(tx, leg.target.controllerPlayerId, honor.config) : 0;
  const charges = await tx.select().from(strategicAssets).where(and(
    eq(strategicAssets.planetId, leg.target.id), eq(strategicAssets.type, 'INTERCEPTOR'),
    eq(strategicAssets.status, 'READY'))).for('update');
  const readySince = (charge: typeof strategicAssets.$inferSelect) => charge.readyAt ?? charge.startedAt;
  const ordered = charges.toSorted((a, b) => readySince(a).getTime() - readySince(b).getTime());
  for (const charge of ordered) {
    let shot = firstShotSince(leg, readySince(charge));
    if (shot && shot.at > now && readySince(charge) <= now) {
      const trigger = triggerAt(leg, now);
      if (trigger) shot = { at: now, trigger };
    }
    if (!shot || shot.at > now) continue;
    const spent = await tx.update(strategicAssets).set({ status: 'CONSUMED' })
      .where(and(eq(strategicAssets.id, charge.id), eq(strategicAssets.status, 'READY'))).returning({ id: strategicAssets.id });
    if (!spent[0]) continue;
    if (honor) {
      const catalogue = honor.config.strategicCatalogue;
      if (!catalogue) throw new Error('Missing strategic Honor catalogue');
      await settleStrategicInterceptionHonor(tx, { seasonId: flight.seasonId, commitmentId: `bomb:${flight.id}`,
        sourceId: `bomb:${flight.id}`, defender: leg.target.controllerPlayerId, at: shot.at,
        weaponValue: honorStrategicValue(catalogue, RADIATION_BOMB.levels[flight.level].type),
        chargeValue: catalogue.INTERCEPTOR, defenderNavy: defenceNavy });
    }
    const impactAt = new Date(Math.min(flight.arriveAt.getTime(), shot.at.getTime() + ANTI_STRATEGIC.flightSeconds * 1000));
    const positionAt = (at: Date) => pointAlong(leg.drawn.from, leg.drawn.to,
      (at.getTime() - flight.departAt.getTime()) / leg.totalMs);
    const claimed = await tx.update(radiationBombFlights).set({ status: 'INTERCEPTED', resolvedAt: shot.at,
      chargeId: charge.id, interception: { defenderPlayerId: leg.target.controllerPlayerId, trigger: shot.trigger,
        launchAt: shot.at.toISOString(), impactAt: impactAt.toISOString(), launchPosition: { x: leg.target.x, y: leg.target.y, z: leg.target.z },
        weaponPosition: positionAt(shot.at), collisionPosition: positionAt(impactAt) } })
      .where(and(eq(radiationBombFlights.id, flight.id), eq(radiationBombFlights.status, 'OUTBOUND'))).returning({ id: radiationBombFlights.id });
    if (!claimed[0]) throw new Error('bomb interception lost its locked flight after claiming ammunition');
    await tx.update(strategicAssets).set({ status: 'CONSUMED' }).where(eq(strategicAssets.id, flight.assetId));
    for (const playerId of [flight.ownerPlayerId, leg.target.controllerPlayerId]) {
      noteRadiationInventoryChange(tx, playerId, observedAt);
    }
    await schedule(tx, { seasonId: flight.seasonId, kind: 'radiation_bomb_intercept_impact', refId: flight.id,
      dedupeKey: `radiation-bomb-intercept-impact:${flight.id}`, resolveAt: impactAt });
    await publishInterceptionSight(tx, flight.seasonId, positionAt(impactAt), [flight.ownerPlayerId, leg.target.controllerPlayerId]);
    return true;
  }
  return false;
}

export async function scheduleBombInterception(tx: Tx, flight: Flight, now: Date, immediate = true): Promise<void> {
  const leg = await bombInterceptionLeg(tx, flight);
  if (!leg) return;
  const next = immediate && triggerAt(leg, now) !== null ? now : nextCheckAt(leg, now);
  if (next) await schedule(tx, { seasonId: flight.seasonId, kind: 'radiation_bomb_intercept', refId: flight.id,
    dedupeKey: `radiation-bomb-intercept:${flight.id}:${String(next.getTime())}`, resolveAt: next });
}

sources.apps/server/src/services/radiationBombWa:
import { eq } from 'drizzle-orm';
import { maxRadarRange, radarRange, sphereEntryFraction } from '@astera/rules';
import type { Tx } from '../db/client.js';
import { planets, radiationBombFlights } from '../db/schema.js';
import { schedule } from '../worker/queue.js';
import { instrumentLevels, levelOf } from './intel.js';
import { notify } from './notifications.js';
import { lockSeason } from './planet.js';
import { lockWorlds } from './ownership.js';
import { publish } from '../stream/bus.js';

type Flight = typeof radiationBombFlights.$inferSelect;
const entryAt = (flight: Flight, centre: typeof flight.targetPosition, reach: number) => {
  if (reach <= 0) return null;
  const fraction = sphereEntryFraction(flight.originPosition, flight.targetPosition, centre, reach);
  return fraction === null ? null : new Date(Math.ceil(flight.departAt.getTime()
    + fraction * (flight.arriveAt.getTime() - flight.departAt.getTime())));
};
const arm = (tx: Tx, flight: Flight, at: Date) => schedule(tx, {seasonId:flight.seasonId,kind:'radar_warning',
  refId:flight.id,dedupeKey:`radiation-bomb-warning:${flight.id}:${String(at.getTime())}`,resolveAt:at});

/** Uses the existing generic warning clock; an upgrade wakes this same live projection. */
export async function scheduleBombWarning(tx: Tx, flight: Flight): Promise<void> {
  if (!flight.targetPlanetId) return;
  const first = entryAt(flight, flight.targetPosition, maxRadarRange());
  if (first) await arm(tx, flight, first);
}

/** The flight and target world are already locked. One addressed warning, no route disclosure. */
export async function warnRadiationBombInTx(tx: Tx, flight: Flight, now: Date): Promise<void> {
  if (flight.status !== 'OUTBOUND' || !flight.targetPlanetId || now >= flight.arriveAt) return;
  const [target] = await tx.select().from(planets).where(eq(planets.id,flight.targetPlanetId));
  if (!target?.controllerPlayerId) return;
  const levels = await instrumentLevels(tx,[target.id]);
  const reach = radarRange(levelOf(levels,target.id,'RADAR'));
  const crossing = entryAt(flight,target,reach);
  if (!crossing) return;
  if (crossing > now) { await arm(tx,flight,crossing);return; }
  await notify(tx,{playerId:target.controllerPlayerId,kind:'incoming_fleet',refId:flight.id,at:now,
    payload:{arriveAt:flight.arriveAt.toISOString(),etaMinutes:Math.max(0,Math.round((flight.arriveAt.getTime()-now.getTime())/60000)),
      targetPlanetId:target.id,targetPlanetName:target.name,range:reach,contactId:flight.id}});
  await publish(tx,target.controllerPlayerId,'fleet');
}

export async function warnRadiationBombById(tx: Tx, id: string, now: Date): Promise<void> {
  const [identity] = await tx.select().from(radiationBombFlights).where(eq(radiationBombFlights.id,id));
  if (identity?.status !== 'OUTBOUND' || !identity.targetPlanetId) return;
  const season = await lockSeason(tx,identity.seasonId,false);
  if (season.status !== 'live') return;
  await lockWorlds(tx,[identity.originPlanetId,identity.targetPlanetId],{requireLive:false});
  const [flight] = await tx.select().from(radiationBombFlights).where(eq(radiationBombFlights.id,id)).for('update');
  if (flight) await warnRadiationBombInTx(tx,flight,now);
}

