import { and, asc, eq, gt, gte, isNull, lt, lte, or } from 'drizzle-orm';
import { hpRadiationApplies, TRAVEL, type HpRadiationSource } from '@astera/rules';
import type { Queryable } from '../db/client.js';
import { hpRadiationSources, monuments, seasons } from '../db/schema.js';
import { monumentMotionStart, motionOfMonument } from './monumentMotion.js';

/** A cutover clips old spatial history; it never rewrites already-travelled time. */
function sourceWindows(row: typeof hpRadiationSources.$inferSelect, cutover?: Date, capFrom?: Date | null): HpRadiationSource[] {
  const source: HpRadiationSource = { id: row.id, center: { x: row.x, y: row.y, z: row.z }, radius: row.radius,
    intensityHpPerMinute: row.intensityHpPerMinute, mode: row.mode, origin: row.origin,
    activeFromMs: row.activeFrom.getTime(), activeUntilMs: row.activeUntil?.getTime() ?? null,
    ...(capFrom ? { totalCapFromMs: capFrom.getTime() } : {}) };
  if (!cutover) return [source];
  const at = cutover.getTime();
  const windows: HpRadiationSource[] = [];
  const oldEnd = Math.min(source.activeUntilMs ?? Infinity, at);
  if (source.activeFromMs < oldEnd) windows.push({ ...source, id: `${source.id}:history`, activeUntilMs: oldEnd });
  const start = Math.max(source.activeFromMs, at);
  if (row.anchorKind !== 'ZONE' && row.anchorId && (source.activeUntilMs === null || source.activeUntilMs > start)) {
    windows.push({ ...source, target: { kind: row.anchorKind, id: row.anchorId }, activeFromMs: start });
  }
  return windows;
}

/** Parked fleets only need their own target's overlapping history, served by its index. */
export async function hpSourcesForTarget(tx: Queryable, season: typeof seasons.$inferSelect,
  target: { kind: 'PLANET' | 'MONUMENT'; id: string }, from: Date, until: Date): Promise<HpRadiationSource[]> {
  const rows = await tx.select().from(hpRadiationSources).where(and(eq(hpRadiationSources.seasonId, season.id),
    eq(hpRadiationSources.anchorKind, target.kind), eq(hpRadiationSources.anchorId, target.id),
    lt(hpRadiationSources.activeFrom, until), or(isNull(hpRadiationSources.activeUntil), gt(hpRadiationSources.activeUntil, from))));
  return rows.flatMap(row => sourceWindows(row, monumentMotionStart(season) ?? season.radiationBombStartsAt ?? undefined,
    season.radiationBombStartsAt));
}

interface HpSourceScope {
  from?: Date;
  until?: Date;
  /** Empty for transit; entity bombs cannot irradiate an ordinary flight. */
  targets?: readonly NonNullable<HpRadiationSource['target']>[];
}

export async function hpSourcesForSeason(tx: Queryable, seasonId: string, scope: HpSourceScope = {}): Promise<HpRadiationSource[]> {
  const [season] = await tx.select().from(seasons).where(eq(seasons.id, seasonId));
  if (!season) return [];
  const rows = await tx.select().from(hpRadiationSources).where(and(eq(hpRadiationSources.seasonId, seasonId),
    scope.from === undefined ? undefined : or(isNull(hpRadiationSources.activeUntil), gt(hpRadiationSources.activeUntil, scope.from)),
    scope.until === undefined ? undefined : lt(hpRadiationSources.activeFrom, scope.until),
    scope.targets === undefined ? undefined : or(eq(hpRadiationSources.origin, 'ENVIRONMENT'),
      ...scope.targets.map(target => and(eq(hpRadiationSources.anchorKind, target.kind), eq(hpRadiationSources.anchorId, target.id)))),
  ))
    .orderBy(asc(hpRadiationSources.activeFrom), asc(hpRadiationSources.id));
  return rows.flatMap(row => sourceWindows(row, monumentMotionStart(season), season.radiationBombStartsAt));
}

/** Current availability never needs the ended source history used by flight settlement. */
export async function activeHpSourcesForSeason(tx: Queryable, seasonId: string, now: Date): Promise<HpRadiationSource[]> {
  const [season] = await tx.select().from(seasons).where(eq(seasons.id, seasonId));
  if (!season || !hpRadiationApplies(season.rulesetVersion)) return [];
  const rows = await tx.select().from(hpRadiationSources).where(and(eq(hpRadiationSources.seasonId, seasonId),
    lte(hpRadiationSources.activeFrom, now), or(isNull(hpRadiationSources.activeUntil), gt(hpRadiationSources.activeUntil, now))));
  const at = now.getTime();
  return rows.flatMap(row => sourceWindows(row, monumentMotionStart(season), season.radiationBombStartsAt))
    .filter(source => source.activeFromMs <= at && (source.activeUntilMs === null || source.activeUntilMs > at));
}

/** Entity auras are cosmetic; their damage projection contains no motion geometry. */
export async function hpRadiationForGalaxy(db: Queryable, seasonId: string, now: Date) {
  const [season] = await db.select().from(seasons).where(eq(seasons.id, seasonId));
  if (!season || !hpRadiationApplies(season.rulesetVersion)) return [];
  const cutoff = new Date(now.getTime() - 2 * TRAVEL.pacedFlightCapMinutes * 60_000);
  const rows = await db.select().from(hpRadiationSources).where(and(eq(hpRadiationSources.seasonId, seasonId),
    or(isNull(hpRadiationSources.activeUntil), gte(hpRadiationSources.activeUntil, cutoff)),
    // Bomb history is server-only: target auras never irradiate a travelling fleet.
    or(eq(hpRadiationSources.origin, 'ENVIRONMENT'), gt(hpRadiationSources.activeUntil, now)),
  )).orderBy(hpRadiationSources.id);
  const cutover = monumentMotionStart(season);
  const bodies = cutover ? await db.select({ id: monuments.id, x: monuments.x, y: monuments.y, z: monuments.z }).from(monuments)
    .where(eq(monuments.seasonId, seasonId)) : [];
  const byId = new Map(bodies.map(body => [body.id, body]));
  return rows.flatMap(row => sourceWindows(row, cutover, season.radiationBombStartsAt).map(source => {
    const body = source.target?.kind === 'MONUMENT' ? byId.get(source.target.id) : undefined;
    const motion = body ? motionOfMonument(body, season) : undefined;
    const level = row.radiationLevel ?? undefined;
    return { id: source.id, mode: source.mode, origin: row.origin, center: source.center, radius: source.radius,
      intensityHpPerMinute: source.intensityHpPerMinute, activeFrom: new Date(source.activeFromMs).toISOString(),
      activeUntil: source.activeUntilMs === null ? null : new Date(source.activeUntilMs).toISOString(),
      ...(source.target ? { target: source.target } : {}), ...(motion ? { motion } : {}), ...(level === undefined ? {} : { level }),
      ...(season.radiationBombStartsAt ? { totalCapFrom: season.radiationBombStartsAt.toISOString() } : {}) };
  }));
}

sources.apps/server/src/services/raidLedger.ts:
import { eq } from 'drizzle-orm';
import { raidLedger, type Fleet, type RaidLedger, type Resources } from '@astera/rules';
import { battleReports, missions } from '../db/schema.js';
import type { Db } from '../db/client.js';

/**
 * WHAT A SETTLED RAID ACTUALLY DID, READ BACK OUT OF WHAT IT SETTLED.
 *
 * IT DERIVES, IT NEVER PREDICTS. Every term here is a fact the battle already wrote down; there is
 * deliberately no second model of the combat, loot or salvage rules beside the server's own. A
 * predictor would drift from the settlement it claims to describe, and its number is the one people
 * would quote.
 *
 * WHY IT HAD TO EXIST. Nothing in the game could answer "did that raid pay?". The pieces were
 * spread across the report — loot here, permanent losses there, the collectors' haul in a third
 * column — and the one term nobody kept at all was the fuel, which is charged at launch and never
 * refunded. Asked three times in one afternoon, the question gave three different answers, each
 * time because a different piece had been left out: once the wreck was counted as free income when
 * lifting it needs two dozen collectors, once the loot was counted past what the survivors could
 * carry, and once the losses were priced on `fleetValue` (A+C+D) while the fuel was priced on
 * `resourceValue` (A+2C+32D).
 *
 * THE PvP LANE ONLY, AND IT IS THE REPORT THAT SAYS SO — not the mission. A NEUTRAL raid is a
 * `kind: 'attack'` mission exactly like a PvP one, so the mission row cannot tell the two apart;
 * the first version of this file checked only the kind and happily priced a caretaker world's
 * garrison as Dominion denied to a commander. `battleReports.targetKind` is the field that knows,
 * and a PvP report always names its defender. Both are checked.
 *
 * A pirate raid is a `pirate_raids` row with its own flight, loot, salvage and `capturedHull` —
 * not a mission — and it records no fuel of its own yet. The neutral lane grades its loot on its
 * own tier table. Each needs its own reader; answering for either from here would mean inventing
 * rules. `raidLedger`'s `captured` field is ready for the pirate lane and is deliberately unused
 * until it exists.
 *
 * PRE-MIGRATION MISSIONS ARE REFUSED. `missions.fuelPaid` backfilled historical rows with zero
 * because their fuel was never recorded and cannot be recovered (see the column's note). A raid
 * that crossed real distance with a real fleet never legitimately paid nothing, so a zero on an
 * attack or a pirate raid is that backfill — and pricing an unmeasured raid as a free one is the
 * single reading this whole ledger exists to prevent.
 */
export interface SettledRaidLedger extends RaidLedger {
  /** Echoed so a caller can show the arithmetic rather than assert it. */
  loot: Resources;
  salvage: Resources;
  fuelPaid: number;
}

export async function ledgerForMission(db: Db, missionId: string): Promise<SettledRaidLedger | null> {
  const [mission] = await db.select().from(missions).where(eq(missions.id, missionId)).limit(1);
  if (!mission) return null;
  if (mission.kind !== 'attack') return null;

  const [report] = await db.select().from(battleReports)
    .where(eq(battleReports.missionId, missionId)).limit(1);
  if (!report) return null;

  /*
    THE LANE IS THE REPORT'S, NOT THE MISSION'S. Owner review, 2026-09-21.

    `mission.kind === 'attack'` is true of a neutral raid as well, so the mission row cannot say
    which fight this was. `targetKind` can, and a PvP report always names the commander on the
    other side. Without both checks a caretaker garrison's losses came back as Dominion denied to
    a PLAYER, which merges the two accounting lanes this file exists to keep apart.

    The neutral and pirate lanes each need their own reader: their loot is graded differently, a
    pirate raid is not a `missions` row at all, and neither has a defender whose loss is anybody's
    Dominion.
  */
  if (report.targetKind !== 'PLAYER' || report.defenderPlayerId === null) return null;

  /*
    A raid that flew a real distance with a real fleet paid something. Zero here is the historical
    backfill, not a free flight — see this file's header.
  */
  if (!(mission.fuelPaid > 0)) return null;

  const loot: Resources = report.loot;
  const salvage: Resources = report.salvage;

  return {
    ...raidLedger({
      attackerLosses: report.attackerLosses,
      /*
        NET OF WHAT THE GROUND REBUILT. `defenceSalvage` is the share of destroyed emplacements
        that comes back free from its own wreckage, so counting the gross would credit the attacker
        with denying something the defender still owns.
      */
      defenderLosses: withoutRebuilt(report.defenderLosses, report.defenceSalvage),
      loot,
      salvage,
      fuelPaid: mission.fuelPaid,
    }),
    loot,
    salvage,
    fuelPaid: mission.fuelPaid,
  };
}

/** Ground units that rebuilt from their own wreckage were never permanently denied. */
function withoutRebuilt(lost: Fleet, rebuilt: Fleet): Fleet {
  const out: Fleet = {};
  for (const [id, n] of Object.entries(lost) as [keyof Fleet, number][]) {
    const left = n - (rebuilt[id] ?? 0);
    if (left > 0) out[id] = left;
  }
  return out;
}

sources.apps/server/src/services/rateLimitBacken:
import { Redis } from 'ioredis';

export interface RateLimitBackendStatus {
  mode: 'memory' | 'shared';
  status: string;
}

/** Optional shared store; local development keeps the plugin's in-memory store. */
export class RateLimitBackend {
  readonly client: Redis | null;

  constructor(url: string | undefined) {
    this.client = url
      ? new Redis(url, {
          connectionName: 'astera-rate-limit',
          lazyConnect: true,
          connectTimeout: 1000,
          maxRetriesPerRequest: 1,
          enableOfflineQueue: false,
        })
      : null;
    // ioredis emits `error`; a listener prevents an outage becoming an uncaught
    // EventEmitter error. Request failures still reach fastify-rate-limit.
    this.client?.on('error', () => undefined);
  }

  async start(): Promise<void> {
    if (this.client?.status === 'wait') await this.client.connect();
  }

  async stop(): Promise<void> {
    if (!this.client) return;
    if (this.client.status === 'ready') {
      await this.client.quit();
      return;
    }
    this.client.disconnect(false);
  }

  status(): RateLimitBackendStatus {
    return this.client
      ? { mode: 'shared', status: this.client.status }
      : { mode: 'memory', status: 'ready' };
  }
}

sources.apps/server/src/services/reclaim.ts:
import { and, eq, inArray, lt, ne, or, sql } from 'drizzle-orm';
import { SERVERS } from '@astera/rules';
import type { Clock } from '../clock.js';
import type { Db, Tx } from '../db/client.js';
import { publishShard } from '../stream/bus.js';
import {
  accounts,
  attackCommitments,
  battleReports,
  clanSupportBattleResults,
  clanSupportWaves,
  buildOrders,
  buildings,
  chatMessages,
  clanAidCommitments,
  clanCeasefires,
  clanLootShares,
  clanMemberships,
  clanMessages,
  clanRaidRoster,
  clanTreasuryEvents,
  clanWarContributions,
  clanWarDominionEvents,
  clanWarMissions,
  clanWarOperations,
  clanWarParticipantResults,
  clanRequests,
  debrisFields,
  intergalacticConvoyRuns,
  miningRuns,
  pirateRaids,
  pirateState,
  missions,
  notifications,
  neutralPlanetState,
  planetFaults,
  planets,
  planetResearch,
  playerResearch,
  playerRivals,
  players,
  probeReports,
  probeWorldMemories,
  requestLog,
  researchOrders,
  rewardGrants,
  satellites,
  sensorEpochs,
  scanEvents,
  scheduledEvents,
  seasonTelemetrySegments,
  seasons,
  strategicAssets,
  strategicImpacts,
  strategicInterceptions,
  tradeRuns,
  units,
  watches,
  shipDamageLots,
  radiationBombFlights,
  hpRadiationSources,
  unknownSignals,
} from '../db/schema.js';
import { prepareClanReclaimMonuments, reconcileClanPlayerReclaim } from './clan.js';
import { addDominionCounters } from './dominion.js';
import { hasMonumentActivity, removeTerminalMonumentWaves } from './monumentLifecycle.js';

/**
 * RECLAIMING THE SEAT OF A COMMANDER WHO STOPPED COMING BACK. Owner instruction.
 *
 * *"Bir oyuncu 3 gün boyunca oyuna girmezse gezegeni silinsin ve böylece
 * serverlarda yer açılır. Pasif hesaplar birikmez."*
 *
 * WHY THIS IS WORTH THE RISK IT CARRIES. A galaxy holds three hundred seats and galaxies
 * fill strictly in order — that ordering is the ONLY mitigation the empty-shard
 * risk has, and it inverts completely once seats are held by people who signed up
 * and never returned. Three hundred inert commanders are not a full
 * galaxy; it is an empty one that nobody can join. The live shard already looks
 * like this: a hundred accounts created in two days, and worlds that read as bots
 * to the owner because nothing has happened on them since.
 *
 * ── WHAT IS DESTROYED, AND WHAT IS NOT ──────────────────────────────────────
 *
 * The SEASON PRESENCE goes: the planet, its buildings, its units, its orbit, and
 * every row in the world that could only exist because that planet did. The
 * ACCOUNT survives — owner decision — and its record folds into
 * `accounts.lifetime` exactly as a wipe folds it, so the commander signs back in,
 * finds no planet, and is taken to the server list to join whichever galaxy is
 * open. That path is why the front door had to learn who is a returning player
 * first: without it, a reclaimed commander would have been offered onboarding.
 *
 * IT TAKES OTHER PEOPLE'S HISTORY WITH IT, and that is stated rather than hidden.
 * `battle_reports` carries foreign keys to both players and to the mission, so a
 * raid an ACTIVE commander flew against a reclaimed world cannot be kept. They
 * lose that line of their report list. It is the same trade a wipe makes, it is
 * the only one the schema allows, and it is worth less than the seat.
 *
 * ── THE THREE THINGS THAT MAKE IT SAFE ──────────────────────────────────────
 *
 *   1. IT NEVER TOUCHES A WORLD THAT SOMETHING IS HAPPENING TO. If any flight is
 *      in the air that names this planet — including a raid an active player
 *      launched at it thirty seconds ago — the planet is DEFERRED to a later
 *      sweep. Deleting a mission out from under a live fleet is not theoretical:
 *      it has happened on this database once already, and it left a real player's
 *      Wasps pointing at a mission id that no longer existed, where no safety net
 *      could reach them.
 *   2. IT RE-CHECKS UNDER A LOCK. The candidate list is read outside the
 *      transaction, so a commander who opens the game in the second between the
 *      read and the delete must not lose their world. The player row is locked and
 *      `lastActiveAt` is read again inside.
 *   3. ONE TRANSACTION PER PLANET. A failure on one world rolls that world back
 *      and leaves every other one alone, and the caller keeps going.
 */

/** Milliseconds of absence before a seat is reclaimed. */
const IDLE_MS = SERVERS.idleDays * 24 * 60 * 60_000;

export interface ReclaimResult {
  /** Planet names whose seats were freed. */
  reclaimed: string[];
  /** Idle worlds left alone this time because something was still in the air. */
  deferred: number;
  /** Worlds that threw. The sweep carries on; the count is for `/health`. */
  failed: number;
}

/**
 * EVERY ROW IN THE WORLD THAT THIS PLANET IS THE REASON FOR.
 *
 * ONE FUNCTION, TWO CALLERS, AND THEY MUST NOT DISAGREE. `busy()` asks whether
 * anything here is still in the air and `demolish()` deletes it; if they compute
 * different sets, the sweep can delete something it never checked was quiet. They
 * did, in the first draft, and the hole was exact: `busy()` looked only at debris
 * AT this planet, while `demolish()` also deleted debris this planet's RAIDS left
 * at other worlds — so a third party's harvest run, in the air toward wreckage
 * that this commander made somewhere else, would have been deleted out from under
 * its craft. That is the same failure that stranded a real player's Wasps on this
 * project's production database once.
 *
 * Debris sits at the DEFENDER's planet. So the fields this world is responsible
 * for are the ones standing over it, plus the ones its own battles created
 * elsewhere — and a harvest run pointed at either is a flight that must be left
 * alone.
 */
export async function commanderRows(
  tx: Tx,
  planetIds: string[],
  playerId: string,
): Promise<{
  missionIds: string[];
  fieldIds: string[];
  runIds: string[];
  raidIds: string[];
  tradeIds: string[];
  convoyIds: string[];
  bombIds: string[];
}> {
  const bombIds = (await tx.select({ id: radiationBombFlights.id }).from(radiationBombFlights).where(or(
    eq(radiationBombFlights.ownerPlayerId, playerId), inArray(radiationBombFlights.originPlanetId, planetIds),
    inArray(radiationBombFlights.targetPlanetId, planetIds),
  ))).map(row => row.id);
  const missionIds = (
    await tx
      .select({ id: missions.id })
      .from(missions)
      .where(or(
        eq(missions.ownerPlayerId, playerId),
        inArray(missions.originPlanetId, planetIds),
        inArray(missions.targetPlanetId, planetIds),
      ))
  ).map((r) => r.id);

  /**
   * AND THE RAIDS THIS SEAT HAS OUT AT PIRATES. D150 — gap G5.
   *
   * `pirate_raids` has foreign keys to `planets` and `seasons` with `ON DELETE no
   * action`, so a reclaimed seat with a raid row would fail on the `delete(planets)`
   * below and the seat would never come back — the exact shape of the
   * `debris_fields` outage this function has already had once.
   */
  const raidIds = (
    await tx
      .select({ id: pirateRaids.id })
      .from(pirateRaids)
      .where(or(inArray(pirateRaids.planetId, planetIds), eq(pirateRaids.ownerPlayerId, playerId)))
  ).map((r) => r.id);

  /**
   * AND THE CONVOYS THIS SEAT HAS OUT AT THE MERCHANT. D156.
   *
   * `trade_runs` has foreign keys to `planets`, `players`, `seasons` and
   * `galaxy_event_occurrences`, all `ON DELETE no action`, so a reclaimed seat with
   * a convoy row would fail on the `delete(planets)` below and the seat would never
   * come back — the exact shape of the `debris_fields` outage this function has
   * already had once.
   *
   * BY PAD **OR** BY COMMANDER, AND THE SECOND HALF WAS MISSING FROM BOTH LANES.
   * D150 gave a raid an `owner_player_id` because *"a raid's return follows its
   * commander, never the pad"*, and D156 copied that onto a convoy — but this sweep
   * gathered rows by pad alone. A world that changed hands after the flight came
   * home leaves a row whose `planet_id` now belongs to somebody else and whose
   * `owner_player_id` is the commander being reclaimed, so `delete(players)`
   * violates the owner key and the seat can never be freed again. `units` below has
   * always read both; these two now do too.
   */
  const tradeIds = (
    await tx
      .select({ id: tradeRuns.id })
      .from(tradeRuns)
      .where(or(inArray(tradeRuns.planetId, planetIds), eq(tradeRuns.ownerPlayerId, playerId)))
  ).map((r) => r.id);

  const convoyIds = (
    await tx
      .select({ id: intergalacticConvoyRuns.id })
      .from(intergalacticConvoyRuns)
      .where(or(
        inArray(intergalacticConvoyRuns.planetId, planetIds),
        eq(intergalacticConvoyRuns.ownerPlayerId, playerId),
      ))
  ).map((r) => r.id);

  const fieldIds = (
    await tx
      .select({ id: debrisFields.id })
      .from(debrisFields)
      /*
        THREE DOORS NOW, AND THE THIRD IS THE ONE WITH NO ADDRESS. D150.

        A pirate battle's wreckage hangs in open space: `planet_id` is NULL and
        there is no mission, so neither of the original two clauses could ever
        reach it and the row would survive its own season as an orphan. It is
        found through the raid that made it.
      */
      .where(
        or(
          inArray(debrisFields.planetId, planetIds),
          ...(missionIds.length > 0
            ? [inArray(debrisFields.missionId, missionIds)]
            : []),
          ...(raidIds.length > 0
            ? [inArray(debrisFields.pirateRaidId, raidIds)]
            : []),
        ),
      )
  ).map((r) => r.id);

  /**
   * AND THE DRILLS THIS SEAT SENT OUT, BY PAD **OR** BY COMMANDER. D150 · D156,
   * and this lane joined them the day `mining_runs` learned who launched it.
   *
   * The season archive gave the table an `owner_player_id` so a run's output is
   * attributed to whoever flew it rather than to whoever happens to own the pad at
   * freeze — and that column is a foreign key to `players` with `ON DELETE no
   * action`, exactly like the raid and convoy keys above. Gathering by pad alone
   * therefore leaves the same landmine those two docblocks describe: a colony that
   * changed hands after a drill came home keeps a row whose `planet_id` now belongs
   * to somebody else and whose `owner_player_id` is the commander being reclaimed,
   * so `delete(players)` violates the owner key and the seat can never be freed
   * again. `units`, `pirate_raids`, `trade_runs` and `intergalactic_convoy_runs`
   * all read both doors; this one now does too.
   */
  const runIds = (
    await tx
      .select({ id: miningRuns.id })
      .from(miningRuns)
      .where(
        or(
          inArray(miningRuns.planetId, planetIds),
          eq(miningRuns.ownerPlayerId, playerId),
          ...(fieldIds.length > 0 ? [inArray(miningRuns.debrisFieldId, fieldIds)] : []),
        ),
      )
  ).map((r) => r.id);

  return { missionIds, fieldIds, runIds, raidIds, tradeIds, convoyIds, bombIds };
}

/**
 * Is anything still happening here?
 *
 * DELIBERATELY BROAD. A false positive costs one sweep's delay — ten minutes, on a
 * commander who has been gone three days. A false negative costs somebody their
 * fleet.
 */
export async function busy(
  tx: Tx,
  planetIds: string[],
  playerId: string,
  rows: { runIds: string[]; raidIds: string[]; tradeIds: string[]; convoyIds: string[]; bombIds: string[] },
  now: Date,
): Promise<boolean> {
  const [signal] = await tx.select({ id: unknownSignals.id }).from(unknownSignals).where(and(
    inArray(unknownSignals.status, ['outbound', 'returning', 'recalled']),
    or(eq(unknownSignals.playerId, playerId), inArray(unknownSignals.originPlanetId, planetIds)),
  )).limit(1);
  if (signal) return true;
  if (rows.bombIds.length > 0) {
    const [bomb] = await tx.select({ id: radiationBombFlights.id }).from(radiationBombFlights).where(and(
      inArray(radiationBombFlights.id, rows.bombIds),
      or(eq(radiationBombFlights.status, 'OUTBOUND'), and(eq(radiationBombFlights.status, 'INTERCEPTED'),
        sql`(${radiationBombFlights.interception}->>'impactAt')::timestamptz > ${now.toISOString()}::timestamptz`)),
    )).limit(1);
    if (bomb) return true;
  }
  if (await hasMonumentActivity(tx, playerId, planetIds)) return true;
  const [flight] = await tx
    .select({ id: missions.id })
    .from(missions)
    .where(
      and(
        eq(missions.status, 'in_flight'),
        or(
          eq(missions.ownerPlayerId, playerId),
          inArray(missions.originPlanetId, planetIds),
          inArray(missions.targetPlanetId, planetIds),
        ),
      ),
    )
    .limit(1);
  if (flight) return true;

  // A marked target and a staged wave have no in-flight mission. Removing any
  // coordinator, target or contributor here would break the operation's foreign
  // keys or erase an escrowed fleet. Account deletion shares this predicate.
  const [jointWar] = await tx
    .select({ id: clanWarOperations.id })
    .from(clanWarOperations)
    .leftJoin(clanWarContributions,
      eq(clanWarContributions.operationId, clanWarOperations.id))
    .where(and(
      inArray(clanWarOperations.status, ['ASSEMBLING', 'ATTACKING', 'RETURNING']),
      or(
        eq(clanWarOperations.leaderPlayerId, playerId),
        eq(clanWarOperations.targetPlayerId, playerId),
        inArray(clanWarOperations.stagingPlanetId, planetIds),
        inArray(clanWarOperations.targetPlanetId, planetIds),
        eq(clanWarContributions.playerId, playerId),
        inArray(clanWarContributions.originPlanetId, planetIds),
      ),
    ))
    .limit(1);
  if (jointWar) return true;

  /*
    KLAN SAVUNMA DESTEĞİ. A wave standing at a world has no mission in the air, and its
    ships' rows sit under the sender's world: taking either seat would delete a fleet or
    strand one. A wave lives at most twelve hours, so this costs a sweep or two.
  */
  const [support] = await tx
    .select({ id: clanSupportWaves.id })
    .from(clanSupportWaves)
    .where(and(
      inArray(clanSupportWaves.status, ['OUTBOUND', 'STATIONED', 'RETURNING']),
      or(
        eq(clanSupportWaves.senderPlayerId, playerId),
        eq(clanSupportWaves.hostPlayerId, playerId),
        inArray(clanSupportWaves.originPlanetId, planetIds),
        inArray(clanSupportWaves.hostPlanetId, planetIds),
      ),
    ))
    .limit(1);
  if (support) return true;

  if (rows.raidIds.length > 0) {
    // A world with a raid in the air is never reclaimed: the fleet is real, and
    // taking the seat would delete it mid-flight.
    const [raid] = await tx
      .select({ id: pirateRaids.id })
      .from(pirateRaids)
      .where(and(inArray(pirateRaids.id, rows.raidIds), ne(pirateRaids.status, 'done')))
      .limit(1);
    if (raid) return true;
  }

  if (rows.tradeIds.length > 0) {
    /*
      A world with a convoy in the air is never reclaimed, for the reason every
      other clause here exists: the transports are real, the goods aboard them are
      real, and taking the seat would delete both mid-flight. "Never reclaim a world
      referenced by an airborne mission" does not have a merchant exception.
    */
    const [convoy] = await tx
      .select({ id: tradeRuns.id })
      .from(tradeRuns)
      .where(and(inArray(tradeRuns.id, rows.tradeIds), ne(tradeRuns.status, 'done')))
      .limit(1);
    if (convoy) return true;
  }

  if (rows.convoyIds.length > 0) {
    const [convoy] = await tx
      .select({ id: intergalacticConvoyRuns.id })
      .from(intergalacticConvoyRuns)
      .where(and(
        inArray(intergalacticConvoyRuns.id, rows.convoyIds),
        ne(intergalacticConvoyRuns.status, 'done'),
      ))
      .limit(1);
    if (convoy) return true;
  }

  if (rows.runIds.length === 0) return false;
  const [run] = await tx
    .select({ id: miningRuns.id })
    .from(miningRuns)
    .where(and(inArray(miningRuns.id, rows.runIds), ne(miningRuns.status, 'done')))
    .limit(1);
  return run !== undefined;
}

/** Fold this season into the account's permanent record, exactly as a wipe does. */
async function foldRecord(
  tx: Tx,
  accountId: string,
  row: { taken: number; lost: number; wealth: number },
): Promise<void> {
  const [account] = await tx
    .select({ lifetime: accounts.lifetime })
    .from(accounts)
    .where(eq(accounts.id, accountId));
  const prior = account?.lifetime ?? {};
  await tx
    .update(accounts)
    .set({
      lifetime: {
        ...prior,
        seasons: (prior.seasons ?? 0) + 1,
        dominionTaken: addDominionCounters(prior.dominionTaken ?? 0, row.taken),
        dominionLost: addDominionCounters(prior.dominionLost ?? 0, row.lost),
        bestWealth: Math.max(prior.bestWealth ?? 0, row.wealth),
      },
    })
    .where(eq(accounts.id, accountId));
}

/**
 * Take one world apart, child rows first.
 *
 * THE ORDER IS THE WHOLE FUNCTION. Every foreign key here is `ON DELETE no
 * action`, so a row deleted out of order raises and rolls the transaction back —
 * which is the good outcome, and it is still an outage for that sweep. The chain
 * that is easy to miss is `mining_runs → debris_fields → missions`: a harvest run
 * points at the field it was sent to, and a field points at the battle that made
 * it. `wipeAllServers` learned this the hard way and could not reset any galaxy
 * where a battle had ever happened.
 */
export async function demolish(
  tx: Tx,
  planetIds: string[],
  playerId: string,
  rows: {
    missionIds: string[];
    fieldIds: string[];
    runIds: string[];
    raidIds: string[];
    tradeIds: string[];
    convoyIds: string[];
    bombIds: string[];
  },
): Promise<void> {
  let { missionIds } = rows;
  const { fieldIds, runIds, raidIds, tradeIds, convoyIds, bombIds } = rows;
  // A consumed weapon no longer requires its commander's identity. Its source
  // keeps running and retains historical dose through ON DELETE SET NULL.
  if (bombIds.length > 0) await tx.delete(radiationBombFlights).where(inArray(radiationBombFlights.id, bombIds));
  await tx.delete(hpRadiationSources).where(and(eq(hpRadiationSources.anchorKind, 'PLANET'),
    inArray(hpRadiationSources.anchorId, planetIds)));
  await removeTerminalMonumentWaves(tx, playerId, planetIds);

  /*
    TERMINAL JOINT WARS ARE SEASON HISTORY, BUT THEIR LIVE FOREIGN KEYS ARE NOT.

    Active operations were refused by `busy`; anything reaching here is terminal.
    Remove the whole operation graph because its report and combined mission are
    shared by every participant and cannot be cut into one commander's fragment.
    The same trade already applies to ordinary reports during reclaim.
  */
  const relatedOperations = await tx
    .select({ id: clanWarOperations.id })
    .from(clanWarOperations)
    .leftJoin(clanWarContributions,
      eq(clanWarContributions.operationId, clanWarOperations.id))
    .where(or(
      eq(clanWarOperations.leaderPlayerId, playerId),
      eq(clanWarOperations.targetPlayerId, playerId),
      inArray(clanWarOperations.stagingPlanetId, planetIds),
      inArray(clanWarOperations.targetPlanetId, planetIds),
      eq(clanWarContributions.playerId, playerId),
      inArray(clanWarContributions.originPlanetId, planetIds),
    ));
  const operationIds = [...new Set(relatedOperations.map((row) => row.id))];
  if (operationIds.length > 0) {
    const warMissionIds = (await tx.select({ id: clanWarMissions.missionId })
      .from(clanWarMissions)
      .where(inArray(clanWarMissions.operationId, operationIds))).map((row) => row.id);
    missionIds = [...new Set([...missionIds, ...warMissionIds])];
    await tx.delete(clanWarDominionEvents)
      .where(inArray(clanWarDominionEvents.operationId, operationIds));
    await tx.delete(clanWarParticipantResults)
      .where(inArray(clanWarParticipantResults.operationId, operationIds));
    await tx.delete(clanWarMissions)
      .where(inArray(clanWarMissions.operationId, operationIds));
    await tx.delete(clanWarContributions)
      .where(inArray(clanWarContributions.operationId, operationIds));
    // A joint war against a supported world also wrote per-defender rows on its report.
    await tx.delete(clanSupportBattleResults).where(inArray(
      clanSupportBattleResults.reportId,
      tx.select({ id: battleReports.id }).from(battleReports)
        .where(inArray(battleReports.clanWarOperationId, operationIds)),
    ));
    await tx.delete(battleReports)
      .where(inArray(battleReports.clanWarOperationId, operationIds));
    await tx.delete(clanWarOperations)
      .where(inArray(clanWarOperations.id, operationIds));
  }

  /*
    TERMINAL SUPPORT WAVES, AND THE REPORT ROWS THAT NAME THIS SEAT. Live waves were
    refused by `busy`. The waves go before the missions they point at; the per-commander
    results go before the reports this function deletes. The score journal stays, like
    `dominion_events`.
  */
  const relatedWaves = await tx
    .select({
      id: clanSupportWaves.id,
      outbound: clanSupportWaves.outboundMissionId,
      homeward: clanSupportWaves.returnMissionId,
    })
    .from(clanSupportWaves)
    .where(or(
      eq(clanSupportWaves.senderPlayerId, playerId),
      eq(clanSupportWaves.hostPlayerId, playerId),
      inArray(clanSupportWaves.originPlanetId, planetIds),
      inArray(clanSupportWaves.hostPlanetId, planetIds),
    ));
  if (relatedWaves.length > 0) {
    missionIds = [...new Set([
      ...missionIds,
      ...relatedWaves.flatMap((wave) => [wave.outbound, ...(wave.homeward ? [wave.homeward] : [])]),
    ])];
    await tx.delete(clanSupportWaves).where(inArray(clanSupportWaves.id, relatedWaves.map((wave) => wave.id)));
  }

  /**
   * Season-scoped only, and `account_rewards` is deliberately absent from this
   * function. Rewards claimed for what happened on THIS world die with it — the
   * progress they were counted from is about to stop existing — but the
   * @JoinAstera bonus is paid once per person for ever, and deleting its row here
   * would hand the same commander a fresh one in whichever galaxy they join next.
   */
  await tx.delete(rewardGrants).where(eq(rewardGrants.playerId, playerId));
  await tx.delete(requestLog).where(eq(requestLog.playerId, playerId));
  await tx.delete(notifications).where(eq(notifications.playerId, playerId));

  // Clan receipts and score audits deliberately survive their source mission,
  // but personal rows cannot survive their player. Everything else below is a
  // live reservation or a player-owned projection and is removed child-first.
  await tx.delete(clanLootShares).where(eq(clanLootShares.playerId, playerId));
  await tx.delete(clanTreasuryEvents).where(or(
    eq(clanTreasuryEvents.actorPlayerId, playerId),
    inArray(clanTreasuryEvents.sourcePlanetId, planetIds),
  ));
  if (missionIds.length > 0) {
    await tx.delete(clanRaidRoster).where(inArray(clanRaidRoster.missionId, missionIds));
  }
  await tx.delete(attackCommitments).where(or(
    eq(attackCommitments.attackerPlayerId, playerId),
    eq(attackCommitments.targetPlayerId, playerId),
    ...(missionIds.length > 0 ? [inArray(attackCommitments.missionId, missionIds)] : []),
  ));
  await tx.delete(clanAidCommitments).where(or(
    eq(clanAidCommitments.senderPlayerId, playerId),
    eq(clanAidCommitments.recipientPlayerId, playerId),
    ...(missionIds.length > 0 ? [inArray(clanAidCommitments.missionId, missionIds)] : []),
  ));
  await tx.delete(clanMessages).where(eq(clanMessages.authorPlayerId, playerId));
  await tx.delete(clanCeasefires).where(or(
    eq(clanCeasefires.playerLowId, playerId),
    eq(clanCeasefires.playerHighId, playerId),
  ));
  await tx.delete(clanRequests).where(or(
    eq(clanRequests.playerId, playerId),
    eq(clanRequests.createdByPlayerId, playerId),
  ));
  await tx.delete(clanMemberships).where(eq(clanMemberships.playerId, playerId));
  /**
   * Somebody else's telescope may be pointed at this world. The row goes and their
   * slot comes free, which is the honest outcome — a watch on a world that no
   * longer exists would report nothing for the rest of the season.
   */
  await tx
    .delete(watches)
    .where(or(eq(watches.observerPlayerId, playerId), inArray(watches.targetPlanetId, planetIds)));
  await tx
    .delete(probeWorldMemories)
    .where(or(
      eq(probeWorldMemories.observerPlayerId, playerId),
      inArray(probeWorldMemories.targetPlanetId, planetIds),
    ));
  await tx
    .delete(probeReports)
    .where(
      or(eq(probeReports.observerPlayerId, playerId), inArray(probeReports.targetPlanetId, planetIds)),
    );
  await tx
    .delete(scanEvents)
    .where(or(inArray(scanEvents.targetPlanetId, planetIds), inArray(scanEvents.originPlanetId, planetIds)));
  await tx
    .delete(strategicInterceptions)
    .where(or(
      eq(strategicInterceptions.attackerPlayerId, playerId),
      eq(strategicInterceptions.defenderPlayerId, playerId),
    ));
  await tx
    .delete(strategicImpacts)
    .where(
      or(
        eq(strategicImpacts.attackerPlayerId, playerId),
        eq(strategicImpacts.defenderPlayerId, playerId),
      ),
    );
  /**
   * BY PLAYER **OR** BY WORLD **OR** BY MISSION, AND THE LAST TWO WERE MISSING.
   *
   * A raid on a CARETAKER world writes a report with an attacker and NO defender,
   * bound to the world and to the mission that flew there. Capture that world
   * afterwards — which is the ordinary way a colony is acquired — and the report
   * now names a planet and a mission this function deletes while matching neither
   * player key. `missions` then fails on `battle_reports_mission_id_missions_id_fk`
   * and the seat can never be reclaimed again. Found on the live EU-1 database:
   * three reports of that exact shape stood over one commander's colony.
   */
  const reportScope = or(
    eq(battleReports.attackerPlayerId, playerId),
    eq(battleReports.defenderPlayerId, playerId),
    inArray(battleReports.targetPlanetId, planetIds),
    ...(missionIds.length > 0 ? [inArray(battleReports.missionId, missionIds)] : []),
  );
  await tx.delete(clanSupportBattleResults).where(inArray(
    clanSupportBattleResults.reportId,
    tx.select({ id: battleReports.id }).from(battleReports).where(reportScope),
  ));
  await tx
    .delete(battleReports)
    .where(reportScope);
  await tx.delete(chatMessages).where(eq(chatMessages.authorPlayerId, playerId));

  /**
   * Scheduled events point at a mission or a run by `refId` and carry NO foreign
   * key, so nothing would stop these being orphaned. An orphan is not harmless: it
   * wakes the worker, finds nothing, and — depending on the handler — either logs
   * or retries until its budget runs out.
   */
  const assetIds = (await tx
    .select({ id: strategicAssets.id })
    .from(strategicAssets)
    .where(or(
      inArray(strategicAssets.planetId, planetIds),
      ...(missionIds.length > 0 ? [inArray(strategicAssets.missionId, missionIds)] : []),
    ))).map((asset) => asset.id);
  const buildOrderIds = (await tx
    .select({ id: buildOrders.id })
    .from(buildOrders)
    .where(inArray(buildOrders.planetId, planetIds))).map((order) => order.id);
  const refs = [
    ...missionIds, ...runIds, ...raidIds, ...tradeIds, ...convoyIds,
    ...planetIds, ...assetIds, ...buildOrderIds, ...bombIds,
    playerId,
    ...(await tx.select({ id: unknownSignals.id }).from(unknownSignals).where(eq(unknownSignals.playerId, playerId))).map(row => row.id),
  ];
  if (refs.length > 0) {
    await tx.delete(scheduledEvents).where(inArray(scheduledEvents.refId, refs));
  }

  if (runIds.length > 0) await tx.delete(miningRuns).where(inArray(miningRuns.id, runIds));
  /*
    DEBRIS BEFORE RAIDS, AND THE ORDER IS A FOREIGN KEY RATHER THAN A PREFERENCE.

    Since D150 a wreck field left in open space points at the raid that made it, so
    deleting the raid first leaves the field referencing a row that is gone and the
    whole seat fails to come back. The runs above are already cleared, so nothing is
    pointing at these fields either.
  */
  if (fieldIds.length > 0) await tx.delete(debrisFields).where(inArray(debrisFields.id, fieldIds));
  // After the reports above, which reference the raid, and before the planets below.
  if (raidIds.length > 0) await tx.delete(pirateRaids).where(inArray(pirateRaids.id, raidIds));
  /*
    Convoys before the occurrences they point at — which are season rows this
    function never touches — and before the planets and the player below.
  */
  if (tradeIds.length > 0) await tx.delete(tradeRuns).where(inArray(tradeRuns.id, tradeIds));
  if (convoyIds.length > 0) {
    await tx.delete(intergalacticConvoyRuns).where(inArray(intergalacticConvoyRuns.id, convoyIds));
  }
  // Damage this commander did to a pirate outlives them as anonymous world state,
  // but the row's `destroyed_by_player_id` points at a commander about to vanish.
  await tx
    .update(pirateState)
    .set({ destroyedByPlayerId: null })
    .where(eq(pirateState.destroyedByPlayerId, playerId));
  if (assetIds.length > 0) await tx.delete(strategicAssets).where(inArray(strategicAssets.id, assetIds));
  // A dock lot points at the repair order working on it, so it goes before the orders.
  await tx.delete(shipDamageLots).where(inArray(shipDamageLots.planetId, planetIds));
  if (buildOrderIds.length > 0) {
    await tx.delete(buildOrders).where(inArray(buildOrders.id, buildOrderIds));
  }
  /**
   * AND THE COMMANDER-WIDE QUEUE, WHICH THIS SWEPT NEITHER HALF OF. T7/D134.
   *
   * `research_orders` points at the commander AND at the world that paid for the
   * project, both `ON DELETE no action`. Research moved off the planet when D134
   * made it commander-wide and this function was never taught the new table, so
   * every seat with a single completed project would have failed on
   * `research_orders_player_id_players_id_fk` — the same never-reclaimable outage
   * `debris_fields` and `trade_runs` each caused once. It has not fired only
   * because the sweep is switched off in production.
   */
  await tx.delete(researchOrders).where(or(
    eq(researchOrders.playerId, playerId),
    inArray(researchOrders.fundingPlanetId, planetIds),
  ));
  if (missionIds.length > 0) await tx.delete(missions).where(inArray(missions.id, missionIds));

  await tx.delete(units).where(or(
    inArray(units.planetId, planetIds),
    eq(units.ownerPlayerId, playerId),
  ));
  await tx.delete(satellites).where(inArray(satellites.planetId, planetIds));
  /*
    BY WORLD **OR** BY OBSERVER — PRE-EXISTING, AND THE THIRD TABLE IN THIS FAMILY.

    An epoch is a commander's sight of a world, so it carries both keys. This swept
    by world alone, which is correct only while the two never diverge: capture a
    world this commander once had eyes on and the row keeps a `player_id` that is
    about to be deleted while its `planet_id` now belongs to somebody else. The
    seat then fails on `sensor_epochs_player_id_players_id_fk` and can never be
    reclaimed again.

    `watches`, `probe_reports`, `probe_world_memories`, `attack_commitments` and
    `units` all already read both keys; this was the one that did not.
  */
  await tx
    .delete(sensorEpochs)
    .where(or(inArray(sensorEpochs.planetId, planetIds), eq(sensorEpochs.playerId, playerId)));
  await tx.delete(buildings).where(inArray(buildings.planetId, planetIds));
  /*
    THE FAULT ROWS, AND THEY BELONG IN THIS LIST FOR THE REASON THE WHOLE LIST EXISTS.

    `planet_faults` references `planets`, so a seat whose colony happened to be broken
    would fail on the `delete(planets)` below and could never be reclaimed again — the
    same shape as the `sensor_epochs` outage recorded above it, and the same shape as the
    pirate-raid and convoy notes at the top of this file. Faults are the newest table to
    carry a planet key and were the newest way to strand a seat.
  */
  await tx.delete(planetFaults).where(inArray(planetFaults.planetId, planetIds));
  await tx.delete(planetResearch).where(inArray(planetResearch.planetId, planetIds));
  await tx.delete(neutralPlanetState).where(inArray(neutralPlanetState.planetId, planetIds));
  await tx.delete(planets).where(inArray(planets.id, planetIds));
  /*
    BEFORE THE PLAYER ROW, AND THAT ORDER IS THE WHOLE POINT. T7.

    `player_research` references `players.id`, so deleting the commander first is a
    foreign-key violation — and this function is what reclaims an idle seat, so the
    failure mode is a galaxy that can never be reopened. The row above it is keyed
    on the planet and the one below is the commander themself; this belongs between.
  */
  await tx.delete(seasonTelemetrySegments).where(eq(seasonTelemetrySegments.playerId, playerId));
  /*
    AND THE ACTOR NAME LEFT ON A WORLD THIS COMMANDER NO LONGER HOLDS.

    `planets.stats_owner_player_id` is a season-stats memory, but it is a real
    foreign key to `players` with `ON DELETE no action` — so a world that names
    this commander and is NOT in `planetIds` (because somebody else controls it
    now) makes `delete(players)` throw and the seat can never be freed again. That
    is the `sensor_epochs` failure one screen up, on a column added the day the
    season archive landed.

    The ordinary conquest path moves the actor with the controller, so the
    divergence should not arise; `loadLocked` also repairs it on the next advance.
    This is the third line of defence and it costs one statement, which is the
    trade every key above this one was re-learned the hard way.
  */
  await tx
    .update(planets)
    .set({ statsOwnerPlayerId: null })
    .where(eq(planets.statsOwnerPlayerId, playerId));
  await tx.delete(playerResearch).where(eq(playerResearch.playerId, playerId));
  /*
    THE RIVAL MARKS, BOTH DIRECTIONS, AND ONLY ONE OF THEM IS A CONSTRAINT. D183.

    `player_rivals.player_id` references `players.id`, so a commander who was
    KEEPING a mark cannot be deleted while it stands — exactly the trap the note
    above `player_research` records, with exactly the same consequence: the sweep
    throws, the seat is never freed, and the galaxy fills with worlds nobody plays.

    `target_player_id` has NO foreign key, deliberately — a mark is a memory rather
    than a reference (D91) — so nothing would stop marks pointing AT this commander
    from outliving them. They have to go too, and for a reason the constraint would
    never have caught: the disc matches a mark by commander id, so a mark on a
    commander who no longer exists is never drawn, while `RIVAL.max` keeps counting
    it. An invisible row would quietly cost its owner one of five slots for the rest
    of the season.
  */
  await tx.delete(playerRivals).where(or(
    eq(playerRivals.playerId, playerId),
    eq(playerRivals.targetPlayerId, playerId),
  ));
  await tx.delete(players).where(eq(players.id, playerId));
}

/**
 * Reclaim every seat whose commander has been away too long.
 *
 * Returns rather than throws on a per-world failure: this runs inside the worker,
 * and *housekeeping may never stop the event queue*. One world that cannot be
 * taken apart must not stop the other forty-nine from being.
 */
export async function reclaimIdleSeats(
  db: Db,
  clock: Clock,
  idleMs: number = IDLE_MS,
  options: { adminUsernames?: readonly string[] } = {},
): Promise<ReclaimResult> {
  const now = clock.now();
  const cutoff = new Date(now.getTime() - idleMs);

  /**
   * LIVE SEASONS ONLY. A frozen or wiped season is not handing out seats, and
   * taking worlds apart inside one would destroy the record of a finished game.
   *
   * `joinedAt` is checked as well as `lastActiveAt`, and it is not redundant: it
   * is the guard against a clock skew or a bad backfill making a commander who
   * joined an hour ago look three days idle.
   */
  const candidates = await db
    .select({
      playerId: players.id,
      accountId: players.accountId,
      seasonId: players.seasonId,
      displayName: accounts.displayName,
      planetId: planets.id,
      planetName: planets.name,
      taken: players.dominionTaken,
      lost: players.dominionLost,
      wealth: players.wealth,
    })
    .from(players)
    .innerJoin(accounts, eq(players.accountId, accounts.id))
    .innerJoin(planets, eq(planets.controllerPlayerId, players.id))
    .innerJoin(seasons, eq(seasons.id, players.seasonId))
    .where(
      and(
        eq(seasons.status, 'live'),
        eq(planets.kind, 'CAPITAL'),
        lt(players.lastActiveAt, cutoff),
        lt(players.joinedAt, cutoff),
      ),
    );

  const out: ReclaimResult = { reclaimed: [], deferred: 0, failed: 0 };

  for (const row of candidates) {
    try {
      const done = await db.transaction(async (tx) => {
        // Discovery is repeated below under the prepared target/player locks.
        // A busy commander cannot be reclaimed or have their fleets recalled.
        const initialWorlds = await tx.select({ id: planets.id }).from(planets).where(eq(planets.controllerPlayerId, row.playerId));
        const initialIds = initialWorlds.map((world) => world.id);
        if (await busy(tx, initialIds, row.playerId, await commanderRows(tx, initialIds, row.playerId), now)) return 'busy' as const;
        const monumentTargets = await prepareClanReclaimMonuments(tx, { playerId: row.playerId, now,
          activeCutoff: cutoff, adminUsernames: options.adminUsernames });
        /**
         * RE-READ UNDER A LOCK. The list above was taken outside any transaction,
         * and a commander who opens the game in the seconds between that read and
         * this delete must keep their world. `Presence` writes `lastActiveAt` on
         * their first authenticated request, so this is the check that sees it.
         */
        const [fresh] = await tx
          .select({ lastActiveAt: players.lastActiveAt })
          .from(players)
          .where(eq(players.id, row.playerId))
          .for('update');
        if (!fresh || fresh.lastActiveAt >= cutoff) return 'came-back' as const;

        /**
         * Read ONCE and used by both, so what is checked for quiet and what is
         * deleted can never be different sets. See `worldRows`.
         */
        const controlled = await tx
          .select({ id: planets.id })
          .from(planets)
          .where(eq(planets.controllerPlayerId, row.playerId));
        const planetIds = controlled.map((world) => world.id);
        if (planetIds.length === 0) return 'came-back' as const;
        const rows = await commanderRows(tx, planetIds, row.playerId);
        if (await busy(tx, planetIds, row.playerId, rows, now)) return 'busy' as const;

        await reconcileClanPlayerReclaim(tx, {
          playerId: row.playerId,
          seasonId: row.seasonId,
          displayName: row.displayName,
          now,
          activeCutoff: cutoff,
          monumentTargets,
          adminUsernames: options.adminUsernames,
        });
        await foldRecord(tx, row.accountId, row);
        await demolish(tx, planetIds, row.playerId, rows);
        // Reclaim removes a public world, its ladder row, its authored chat and
        // any dormant wreck fields. Those are distinct query families; the
        // client's 250ms coalescer turns the transactional broadcasts into one
        // visible refresh without making one event kind lie about what changed.
        await publishShard(tx, row.seasonId, 'world');
        await publishShard(tx, row.seasonId, 'mining');
        await publishShard(tx, row.seasonId, 'chat');
        return 'reclaimed' as const;
      });

      if (done === 'reclaimed') out.reclaimed.push(row.planetName);
      else if (done === 'busy') out.deferred += 1;
    } catch {
      out.failed += 1;
    }
  }

  return out;
}

/** How many seats are eligible right now, without touching any of them. For `/health`. */
export async function idleSeatCount(db: Db, clock: Clock, idleMs: number = IDLE_MS): Promise<number> {
  const cutoff = new Date(clock.now().getTime() - idleMs);
  const [row] = await db
    .select({ n: sql<number>`count(*)::int` })
    .from(players)
    .innerJoin(seasons, eq(seasons.id, players.seasonId))
    .where(
      and(
        eq(seasons.status, 'live'),
        lt(players.lastActiveAt, cutoff),
        lt(players.joinedAt, cutoff),
      ),
    );
  return row?.n ?? 0;
}

