import { and, asc, eq, gte, inArray, sql } from 'drizzle-orm';
import { SEASON, SERVERS } from '@astera/rules';
import type { Db, Tx } from '../db/client.js';
import type { Clock } from '../clock.js';
import { addMinutes } from '../clock.js';
import {
  accounts,
  asteroidClaims,
  asteroidSpawnHours,
  attackCommitments,
  battleReports,
  buildOrders,
  buildings,
  chatMessages,
  clanAidCommitments,
  clanCeasefires,
  clanEvents,
  clanLootShares,
  clanMemberships,
  clanMessages,
  clanRaidRoster,
  clanRequests,
  clanScoreEvents,
  clanTreasuryEvents,
  clanWarContributions,
  clanSupportBattleResults,
  clanSupportDominionEvents,
  clanSupportWaves,
  clanWarDominionEvents,
  clanWarMissions,
  clanWarOperations,
  clanWarParticipantResults,
  clans,
  debrisFields,
  dominionEvents,
  galaxyEvents,
  galaxyEventOccurrences,
  intergalacticConvoyRuns,
  miningRuns,
  pirateRaids,
  pirateState,
  missions,
  neutralPlanetState,
  notifications,
  planets,
  planetFaults,
  planetResearch,
  playerResearch,
  playerRivals,
  researchOrders,
  returnApplications,
  players,
  probeReports,
  probeWorldMemories,
  requestLog,
  rewardGrants,
  satellites,
  sensorEpochs,
  scanEvents,
  scheduledEvents,
  seasonTelemetrySegments,
  seasons,
  shards,
  tradeRuns,
  units,
  strategicAssets,
  strategicImpacts,
  strategicInterceptions,
  watches,
  radiationSources,
  shipDamageLots,
  hpRadiationSources,
  radiationBombFlights,
  monuments,
  monumentShipLots,
  monumentWaves,
  monumentBattles,
  monumentBattleParticipants,
} from '../db/schema.js';
import { createSeasonIn } from './season.js';
import { GameError } from './planet.js';
import { isPerson } from './people.js';
import { publishShard } from '../stream/bus.js';
import { addDominionCounters } from './dominion.js';
import { archiveSeasonChat } from './chatArchive.js';
import {
  bindSeasonRankRewardsToSuccessor,
  expireSeasonRankRewardsForCycles,
} from './seasonRankRewards.js';

/**
 * THE GALAXIES, AS A PLACE YOU CHOOSE. D21.
 *
 * At most two live ones, three hundred commander seats each, filled strictly in order. Every rule about which
 * one a player may enter lives in this file, and there is exactly one function that
 * decides it — `frontierOrdinal` — so the list the player reads and the check that
 * admits them can never disagree about which galaxy is open.
 */

/** What one row of the server list says. */
export interface ServerSummary {
  code: string;
  name: string;
  ordinal: number;
  /** Planets taken. The whole point of the list. */
  planets: number;
  capacity: number;
  /** Commanders whose last authenticated request was inside the online window. */
  online: number;
  status: ServerStatus;
  seasonEndsAt: Date | null;
}

/**
 * Why a galaxy can or cannot be entered.
 *
 * `locked` is the sequential-fill rule made visible: the galaxy is fine, it simply
 * is not this one's turn. Saying so is deliberate — a list of ten identical closed
 * doors reads as a broken game, while a list where one door is open and the rest
 * say "opens when Vantage fills" reads as a world with a shape.
 */
export type ServerStatus = 'open' | 'full' | 'locked' | 'closed';

/** Names, so a galaxy is somewhere rather than a row number. */
const SHARD_NAMES = [
  'Vantage', 'Kestrel', 'Halcyon', 'Orrery', 'Lodestar',
  'Bellwether', 'Quillon', 'Tessellate', 'Marrow', 'Vesper',
];

export const shardCodeFor = (ordinal: number): string => `EU-${String(ordinal)}`;
export const shardNameFor = (ordinal: number): string =>
  SHARD_NAMES[(ordinal - 1) % SHARD_NAMES.length] ?? `Galaxy ${String(ordinal)}`;

/** A disposable ruleset-16 door for the local visual/gameplay rehearsal only. */
const DEVELOPMENT_MONUMENT_SHARD = 'MONUMENT-LOCAL';
const developmentLobby = (): boolean => process.env.NODE_ENV !== 'production' && process.env.NODE_ENV !== 'test';

/* ── reading the list ───────────────────────────────────────── */

/**
 * Every galaxy, with its population and whether it will take anyone.
 *
 * THREE QUERIES, NEVER THIRTY. The shards, then one grouped count of planets per
 * season, then one grouped count of active players — rather than a pair of counts
 * per shard. Two servers can still make an N+1 here look harmless; it is the same mistake at
 * fifty, and this endpoint is the one every player hits before they can play.
 */
export async function listServers(db: Db, clock: Clock): Promise<ServerSummary[]> {
  const rows = await db
    .select({ shard: shards, season: seasons })
    .from(shards)
    .leftJoin(seasons, and(eq(seasons.shardId, shards.id), eq(seasons.status, 'live')))
    .where(eq(shards.role, 'MAIN'))
    .orderBy(asc(shards.ordinal));

  // The supported official range wins whenever it exists. A scratch database
  // may contain only one-off codes (EU-TEST, EU-MULTI); keep up to two of those
  // usable in isolation without creating a production escape hatch where a
  // renamed third shard becomes publicly admissible.
  const official = rows.filter(({ shard }) => (
    shard.ordinal >= 1 && shard.ordinal <= SERVERS.count
  ));
  const primaryRows = (official.length > 0 ? official : rows).slice(0, SERVERS.count);
  const localMonument = developmentLobby()
    ? rows.find(({ shard }) => shard.code === DEVELOPMENT_MONUMENT_SHARD)
    : undefined;
  // Production keeps the sequential official frontier. Local development also
  // exposes the explicit monument rehearsal so a player can choose the ruleset
  // 16 season from the normal lobby instead of knowing a hidden shard code.
  const visibleRows = localMonument && !primaryRows.some(({ shard }) => shard.code === localMonument.shard.code)
    ? [...primaryRows, localMonument]
    : primaryRows;

  const since = addMinutes(clock.now(), -SERVERS.onlineWindowMinutes);

  const [taken, active] = await Promise.all([
    // People's capitals only: a bot's seat is never one a person could take (`people.ts`).
    db
      .select({ seasonId: planets.seasonId, n: sql<number>`count(*)::int` })
      .from(planets)
      .innerJoin(players, eq(players.id, planets.controllerPlayerId))
      .where(and(eq(planets.kind, 'CAPITAL'), isPerson))
      .groupBy(planets.seasonId),
    db
      .select({ seasonId: players.seasonId, n: sql<number>`count(*)::int` })
      .from(players)
      .where(gte(players.lastActiveAt, since))
      .groupBy(players.seasonId),
  ]);

  const planetsBySeason = new Map(taken.map((r) => [r.seasonId, r.n]));
  const onlineBySeason = new Map(active.map((r) => [r.seasonId, r.n]));

  // Status is deliberately not computed in this pass: whether a galaxy is `open`
  // or `locked` depends on every OTHER galaxy, so it cannot be known one row at a
  // time. Build the facts first, decide the frontier once, then label.
  const facts = visibleRows.map(({ shard, season }) => ({
    code: shard.code,
    name: shard.name === '' ? shard.code : shard.name,
    ordinal: shard.ordinal,
    planets: season ? (planetsBySeason.get(season.id) ?? 0) : 0,
    capacity: shard.playerCap,
    online: season ? (onlineBySeason.get(season.id) ?? 0) : 0,
    seasonEndsAt: season?.endsAt ?? null,
    live: season !== null,
  }));

  const frontier = frontierOrdinal(facts.filter((f) => f.live));
  return facts.map(({ live, ...rest }) => ({
    ...rest,
    status: developmentLobby() && rest.code === DEVELOPMENT_MONUMENT_SHARD && live
      ? statusOf(rest, live, rest.planets < rest.capacity ? rest.ordinal : frontier)
      : statusOf(rest, live, frontier),
  }));
}

interface Fillable {
  ordinal: number;
  planets: number;
  capacity: number;
}

/**
 * THE SEQUENTIAL-FILL RULE, IN ONE PLACE.
 *
 * The frontier is the lowest-ordinal galaxy that is live and still has a free
 * slot. It is the only galaxy anyone may join, which is what "fill them in order"
 * means when written as something a request can be checked against.
 *
 * Why a rule and not a preference: `KNOWN RISKS` puts the empty shard second on
 * the list — "async PvP with 12 players is nothing" — and its mitigation is not to
 * open a second galaxy until the first fills. Multiple galaxies offered freely on day
 * one are empty rooms, which is the failure the risk describes, arrived at by
 * giving players a choice they have no way to make well.
 *
 * Returns null when every galaxy is full, which is a real state and not an error:
 * the world is at capacity and the answer is a new season, not a bigger shard.
 */
export function frontierOrdinal(rows: readonly Fillable[]): number | null {
  const open = rows
    .filter((r) => r.planets < r.capacity)
    .sort((a, b) => a.ordinal - b.ordinal);
  return open[0]?.ordinal ?? null;
}

function statusOf(
  row: Fillable,
  live: boolean,
  frontier: number | null,
): ServerStatus {
  if (!live) return 'closed';
  if (row.planets >= row.capacity) return 'full';
  return row.ordinal === frontier ? 'open' : 'locked';
}

/* ── joining one ────────────────────────────────────────────── */

export interface JoinTarget {
  seasonId: string;
  shardCode: string;
  shardName: string;
  playerCap: number;
}

/**
 * Resolve which galaxy a request may actually enter, or say precisely why not.
 *
 * Every refusal here is a sentence the interface can show without inventing one,
 * because a player who is told "no" by a server list and not told which server to
 * try instead has been handed a dead end.
 */
export async function resolveJoinTarget(
  db: Db,
  shardCode: string,
  clock: Clock,
): Promise<JoinTarget> {
  const list = await listServers(db, clock);
  const target = list.find((s) => s.code === shardCode);
  if (!target) throw new GameError('NO_SUCH_SERVER', 'No galaxy by that name', 404);

  switch (target.status) {
    case 'closed':
      throw new GameError('NO_SEASON', `${target.name} is not open right now`, 409, {
        shard: target.name,
      });
    case 'full':
      throw new GameError('SHARD_FULL', `${target.name} is full`, 409, { shard: target.name });
    case 'locked': {
      const frontier = list.find((s) => s.status === 'open');
      throw new GameError(
        'SERVER_LOCKED',
        frontier
          ? `${target.name} opens once ${frontier.name} is full. Join ${frontier.name}.`
          : `${target.name} is not open yet`,
        409,
        {
          shard: target.name,
          ...(frontier ? { frontier: frontier.name, context: 'frontier' } : {}),
        },
      );
    }
    case 'open':
      break;
  }

  const [row] = await db
    .select({ season: seasons, shard: shards })
    .from(seasons)
    .innerJoin(shards, eq(seasons.shardId, shards.id))
    .where(and(eq(shards.code, shardCode), eq(shards.role, 'MAIN'), eq(seasons.status, 'live')))
    .limit(1);
  // Unreachable through `listServers`, which only reports 'open' for a live
  // season. Checked anyway: the alternative to this branch is a non-null
  // assertion on the row that decides where a player spends a season.
  if (!row) {
    throw new GameError('NO_SEASON', `${target.name} is not open right now`, 409, {
      shard: target.name,
    });
  }

  return {
    seasonId: row.season.id,
    shardCode: row.shard.code,
    shardName: target.name,
    playerCap: row.shard.playerCap,
  };
}

export interface Placement {
  shardCode: string;
  shardName: string;
  seasonId: string;
  planetId: string;
  /** Carried so the client can name the world it is returning to without a second call. */
  planetName: string;
}

/** Where an account already is, if anywhere. Null means free to choose. */
export async function currentPlacement(db: Db, accountId: string): Promise<Placement | null> {
  const [row] = await db
    .select({
      shard: shards,
      seasonId: players.seasonId,
      planetId: planets.id,
      planetName: planets.name,
    })
    .from(players)
    .innerJoin(planets, and(eq(planets.controllerPlayerId, players.id), eq(planets.kind, 'CAPITAL')))
    .innerJoin(seasons, eq(players.seasonId, seasons.id))
    .innerJoin(shards, eq(seasons.shardId, shards.id))
    .where(eq(players.accountId, accountId))
    .limit(1);

  if (!row) return null;
  return {
    shardCode: row.shard.code,
    shardName: row.shard.name === '' ? row.shard.code : row.shard.name,
    seasonId: row.seasonId,
    planetId: row.planetId,
    planetName: row.planetName,
  };
}

/* ── opening and ending galaxies ────────────────────────────── */

export interface BootstrapOptions {
  count?: number;
  capacity?: number;
  days?: number;
  /** Seeds are derived from this so a bootstrap is reproducible when it needs to be. */
  seedBase?: number;
  /** Explicit season ruleset; omitted keeps the current production default. */
  rulesetVersion?: number;
}

export interface BootstrapResult {
  created: string[];
  existing: string[];
}

/**
 * Bring the whole world into existence, or top it up.
 *
 * IDEMPOTENT BY CONSTRUCTION. Running it twice creates nothing the second time,
 * because the shard code is unique and a shard that already has a live season is
 * left alone. That matters more than it looks: this is the command that runs on a
 * fresh box, and a deploy script that cannot be re-run safely is a deploy script
 * that will be run twice by accident.
 */
export async function bootstrapServers(
  db: Db,
  clock: Clock,
  opts: BootstrapOptions = {},
): Promise<BootstrapResult> {
  const result = await db.transaction((tx) => bootstrapServersIn(tx, clock, opts));
  return { created: result.created, existing: result.existing };
}

interface BootstrapInResult extends BootstrapResult {
  /** The shared cycle opened by this call; private rollover coordination data. */
  cycleId: string | null;
}

/** The same idempotent bootstrap, composable inside the atomic wipe. D88. */
async function bootstrapServersIn(
  tx: Tx,
  clock: Clock,
  opts: BootstrapOptions = {},
): Promise<BootstrapInResult> {
  const count = opts.count ?? SERVERS.count;
  const capacity = opts.capacity ?? SERVERS.capacity;
  const days = opts.days ?? SEASON.days;
  const seedBase = opts.seedBase ?? Math.floor(Math.random() * 1_000_000);

  // One period for every new galaxy in this bootstrap, even while I/O advances time.
  const startsAt = clock.now();
  const created: string[] = [];
  const existing: string[] = [];
  let cycleId: string | null = null;

  for (let ordinal = 1; ordinal <= count; ordinal++) {
    const code = shardCodeFor(ordinal);
    const [live] = await tx
      .select({ id: seasons.id })
      .from(seasons)
      .innerJoin(shards, eq(seasons.shardId, shards.id))
      .where(and(eq(shards.code, code), eq(seasons.status, 'live')))
      .limit(1);

    if (live) {
      existing.push(code);
      continue;
    }

    const opened = await createSeasonIn(tx, {
      shardCode: code,
      shardName: shardNameFor(ordinal),
      ordinal,
      // Distinct per galaxy, so two servers are two different places rather than
      // the same map twice. Derived rather than random so a seedBase reproduces
      // the whole world for a bug report.
      seed: seedBase + ordinal * 7919,
      startsAt,
      days,
      playerCap: capacity,
      spawnGate: true,
      ...(opts.rulesetVersion === undefined ? {} : { rulesetVersion: opts.rulesetVersion }),
    });
    if (cycleId !== null && cycleId !== opened.season.cycleId) {
      throw new Error('One bootstrap opened seasons in different cycles');
    }
    cycleId = opened.season.cycleId;
    created.push(code);
  }

  return { created, existing, cycleId };
}

export interface WipeResult {
  seasonsWiped: number;
  playersCleared: number;
  serversOpened: string[];
  /** Automatic rollover waits rather than ending a galaxy whose snapshot is late. */
  deferred: boolean;
}

/**
 * THE WIPE. Every galaxy, at once, and everybody starts again. D21.
 *
 * Order matters and is the whole of the correctness here:
 *
 *   1. Fold each player's season into the permanent account record FIRST. After
 *      step 3 the numbers are gone and no amount of care recovers them.
 *   2. Mark the old seasons `wiped` before deleting anything, so a crash halfway
 *      leaves seasons that are visibly finished rather than live seasons with no
 *      planets in them — which is what a player would otherwise log in to.
 *   3. Delete every controlled world. `players` going is what releases the one-commander
 *      unique index, and therefore what lets everyone choose a galaxy again.
 *   4. Open the new seasons.
 *
 * Deletion is ordered child-before-parent by hand rather than left to a cascade,
 * because none of these foreign keys declare one — a cascade that does not exist
 * is the sort of thing that works in review and fails at 3am.
 */
export async function wipeAllServers(
  db: Db,
  clock: Clock,
  opts: BootstrapOptions = {},
  guard?: { eventSeasonId: string; requireAllFrozen: true },
): Promise<WipeResult> {
  const wiped = await db.transaction(async (tx) => {
    // One world transition across every worker replica. The event's old season is
    // the idempotency guard after the first transaction opens its successors.
    await tx.execute(sql`select pg_advisory_xact_lock(83202488)`);
    if (guard) {
      const [source] = await tx
        .select({ status: seasons.status })
        .from(seasons)
        .where(eq(seasons.id, guard.eventSeasonId))
        .limit(1);
      if (!source || source.status === 'wiped') {
        return { seasonsWiped: 0, playersCleared: 0, serversOpened: [], deferred: false };
      }
    }
    const [stillLive] = await tx
      .select({ n: sql<number>`count(*)::int` })
      .from(seasons)
      .where(eq(seasons.status, 'live'));
    if ((stillLive?.n ?? 0) > 0) {
      if (!guard) {
        throw new Error('live seasons must be sealed before wipe');
      }
      const [failedEnd] = await tx
        .select({ n: sql<number>`count(*)::int` })
        .from(scheduledEvents)
        .where(and(
          eq(scheduledEvents.kind, 'season_end'),
          eq(scheduledEvents.status, 'failed'),
        ));
      if ((failedEnd?.n ?? 0) > 0) {
        throw new Error('season rollover blocked by a failed season_end event');
      }
      return { seasonsWiped: 0, playersCleared: 0, serversOpened: [], deferred: true };
    }

    const ending = await tx
      .select({ id: seasons.id, cycleId: seasons.cycleId })
      .from(seasons)
      .where(inArray(seasons.status, ['live', 'frozen']));
    const endingCycleIds = [...new Set(ending.map((season) => season.cycleId))];
    const roster = await tx
      .select({
        id: players.id,
        accountId: players.accountId,
        taken: players.dominionTaken,
        lost: players.dominionLost,
        wealth: players.wealth,
      })
      .from(players);

    /**
     * The record, merged in JavaScript rather than in SQL.
     *
     * A `jsonb_build_object` with four `coalesce(... ->> ...)` casts would do this
     * in one statement and would be unreadable and untestable. This runs once per
     * season across the whole world, offline, on a few hundred rows — the clarity
     * is worth more than the round trips, and every number in it is a fact a
     * player may one day be shown.
     */
    if (roster.length > 0) {
      const ids = [...new Set(roster.map((r) => r.accountId))];
      const before = await tx
        .select({ id: accounts.id, lifetime: accounts.lifetime })
        .from(accounts)
        .where(inArray(accounts.id, ids));
      const priorOf = new Map(before.map((a) => [a.id, a.lifetime]));

      for (const row of roster) {
        const prior = priorOf.get(row.accountId) ?? {};
        await tx
          .update(accounts)
          .set({
            lifetime: {
              ...prior,
              seasons: (prior.seasons ?? 0) + 1,
              dominionTaken: addDominionCounters(prior.dominionTaken ?? 0, row.taken),
              dominionLost: addDominionCounters(prior.dominionLost ?? 0, row.lost),
              bestWealth: Math.max(prior.bestWealth ?? 0, row.wealth),
            },
          })
          .where(eq(accounts.id, row.accountId));
      }
    }

    await expireSeasonRankRewardsForCycles(tx, endingCycleIds, clock.now());
    await tx.update(seasons).set({ status: 'wiped' }).where(eq(seasons.status, 'live'));
    await tx.update(seasons).set({ status: 'wiped' }).where(eq(seasons.status, 'frozen'));
    for (const season of ending) await publishShard(tx, season.id, 'rollover');

    /**
     * Child rows first. Every one of these references something below it.
     *
     * `debris_fields` WAS MISSING, and it is the only table here whose absence is a
     * hard failure rather than a leak: its foreign keys to `missions`, `planets` and
     * `seasons` are all `ON DELETE no action`, so the `delete(missions)` below raised
     * a constraint violation and the whole wipe rolled back. Any galaxy where a
     * battle had produced wreckage — which is every galaxy that has been played —
     * could not be reset at all. It went unnoticed because the three wipe tests
     * never fought a battle.
     *
     * It goes before `mining_runs` as well as before `missions`: a harvest run
     * points at the field it was sent to.
     */
    // Rewards claimed in a season die with it: the table's only foreign key is to
    // `players`, which is deleted below, and a season's record is folded into the
    // account rather than carried over as an unclaimed grant.
    //
    // `account_rewards` IS NOT TOUCHED, AND THAT IS THE FEATURE. It records what a
    // PERSON has been paid once and for ever — the @JoinAstera bonus — so a wipe
    // clearing it would pay every follower again on the first day of every new
    // galaxy. Its only foreign key is to `accounts`, which this wipe keeps.
    //
    // The conversation is kept the same way, and it must be copied FIRST: both chat
    // tables and the clans they name are deleted below. 2026-09-27.
    await archiveSeasonChat(tx, clock.now());
    await tx.delete(rewardGrants);
    await tx.delete(monumentBattleParticipants);
    await tx.delete(monumentBattles);
    await tx.delete(monumentShipLots);
    await tx.delete(monumentWaves);
    await tx.delete(hpRadiationSources);
    await tx.delete(radiationBombFlights);
    // Clan rows form their own child graph around missions, players and clans.
    // Personal shares go first; immutable score/event history is kept only until
    // this seasonal wipe, never into the next galaxy.
    await tx.delete(clanLootShares);
    await tx.delete(clanScoreEvents);
    /*
      THE JOINT WAR UNWINDS INNERMOST FIRST, AND IT DRAGS `battle_reports` UP WITH
      IT. 2026-09-20.

      Every foreign key here is `no action`, so the order is forced end to end:
      a joint report carries `clan_war_operation_id`, an operation points at
      `clans`, and this wipe has always taken `clans` down before the reports. One
      of those three had to move, and the report is the only one with nothing
      pointing at it once the participant rows are gone — `dominion_events` and
      `strategic_impacts` are independent of it, so nothing downstream notices.

      `clan_war_missions` also points at `missions`, which is why it cannot wait
      for the generic mission sweep further down.
    */
    await tx.delete(clanWarDominionEvents);
    await tx.delete(clanWarParticipantResults);
    await tx.delete(clanWarMissions);
    await tx.delete(clanWarContributions);
    // Klan Savunma Desteği: results point at reports, waves at missions and clans.
    await tx.delete(clanSupportBattleResults);
    await tx.delete(clanSupportDominionEvents);
    await tx.delete(clanSupportWaves);
    await tx.delete(battleReports);
    await tx.delete(clanWarOperations);
    // A monument preparation owns a real target FK; delete its history before the target.
    await tx.delete(monuments);
    await tx.delete(clanTreasuryEvents);
    await tx.delete(clanRaidRoster);
    await tx.delete(attackCommitments);
    await tx.delete(clanAidCommitments);
    await tx.delete(clanMessages);
    await tx.delete(clanEvents);
    await tx.delete(clanRequests);
    await tx.delete(clanCeasefires);
    await tx.delete(clanMemberships);
    await tx.delete(clans);
    // Presence takes player → application. Acquire the same order before clearing
    // worlds/applications so rollover cannot deadlock with an activity refresh.
    await tx.select({ id: players.id }).from(players).orderBy(asc(players.id)).for('update');
    await tx.delete(chatMessages);
    /*
      CONVOYS BEFORE THE OCCURRENCES THEY POINT AT. D156.

      `trade_runs.occurrence_id` is a foreign key to `galaxy_event_occurrences`
      with `ON DELETE no action`, so wiping the calendar first raises — the same
      ordering lesson the pirate rows and the debris fields both taught this
      function.
    */
    await tx.delete(tradeRuns);
    await tx.delete(intergalacticConvoyRuns);
    await tx.delete(galaxyEvents);
    await tx.delete(galaxyEventOccurrences);
    await tx.delete(requestLog);
    await tx.delete(notifications);
    await tx.delete(scanEvents);
    await tx.delete(probeWorldMemories);
    await tx.delete(probeReports);
    await tx.delete(watches);
    await tx.delete(strategicInterceptions);
    await tx.delete(strategicImpacts);
    await tx.delete(dominionEvents);
    // `battle_reports` came down with the clan-war block above; see the note there.
    /*
      THE WRECKAGE COMES DOWN BEFORE THE RAID THAT MADE IT. D150.

      A void field carries `pirate_raid_id`, so it is the SECOND thing pointing at
      a raid and the comment below only ever accounted for the first. Deleting the
      raid first failed on `debris_fields_pirate_raid_id_pirate_raids_id_fk` and
      rolled the whole rollover back — a galaxy that can never be reset, which is
      exactly the outage `debris_fields` has now caused here twice.

      `mining_runs` points at a debris field, so the three unwind innermost first.
    */
    await tx.delete(miningRuns);
    await tx.delete(debrisFields);
    // After the reports and the wreckage that reference a raid, before the planets
    // and seasons it references. `pirate_state` is anonymous world damage and goes
    // with the season.
    await tx.delete(pirateRaids);
    await tx.delete(pirateState);
    await tx.delete(scheduledEvents);
    // A dock lot points at the repair order working on it, so it goes first.
    await tx.delete(shipDamageLots);
    // Test clouds die with the galaxy they were placed in (K4); nothing references them.
    await tx.delete(radiationSources);
    await tx.delete(buildOrders);
    await tx.delete(strategicAssets);
    await tx.delete(missions);
    await tx.delete(asteroidClaims);
    await tx.delete(asteroidSpawnHours);
    await tx.delete(units);
    await tx.delete(satellites);
    await tx.delete(sensorEpochs);
    await tx.delete(buildings);
    /*
      THE COMMANDER-WIDE RESEARCH QUEUE, AND IT WAS MISSING. D134 added
      `research_orders` with a foreign key to the FUNDING WORLD, and this list was
      never told — so `delete(planets)` failed on the key and a wipe was impossible
      on any galaxy where somebody had ever ordered research. Found on the D169
      release, against 276 live rows.
    */
    await tx.delete(researchOrders);
    await tx.delete(planetResearch);
    await tx.delete(neutralPlanetState);
    await tx.delete(seasonTelemetrySegments);
    // Faults and in-progress repairs retain a NO ACTION FK to their seasonal world.
    await tx.delete(planetFaults);
    await tx.delete(planets);
    /*
      THE RIVAL MARKS, AND IT IS THE SAME LESSON A FOURTH TIME. D183 added
      `player_rivals` with `player_id` referencing `players` at `ON DELETE no
      action` — deliberately, so a reclaim throws rather than silently orphaning a
      mark — and this list was never told. `delete(players)` below then fails on
      the key, so a galaxy where ANYBODY has marked a rival cannot be reset at all:
      the same outage `debris_fields` and `research_orders` each caused once.

      `target_player_id` is NOT a foreign key (D183, so an invisible mark cannot
      hold a slot for the season), so only the owning side constrains the order.
    */
    await tx.delete(playerRivals);
    // Before the commanders it points at, or the wipe fails on the foreign key. T7.
    await tx.delete(playerResearch);
    await tx.update(returnApplications).set({
      status: 'SEASON_ENDED', closedAt: clock.now(), updatedAt: clock.now(), closedReason: 'SEASON_ENDED',
    }).where(eq(returnApplications.status, 'QUEUED'));
    await tx.delete(players);

    const opened = await bootstrapServersIn(tx, clock, opts);
    await bindSeasonRankRewardsToSuccessor(tx, endingCycleIds, opened.cycleId);
    return {
      seasonsWiped: ending.length,
      playersCleared: roster.length,
      serversOpened: opened.created,
      deferred: false,
    };
  });

  return wiped;
}

