import { and, eq, inArray, sql } from 'drizzle-orm';
import { resolveUnknownSignalSpawn } from '../services/unknownSignal.js';
import { deuteriumOf, fleetCount, fleetEntries } from '@astera/rules';
import type { Clock } from '../clock.js';
import type { Db, Tx } from '../db/client.js';
import { miningRuns, missions, planets, units } from '../db/schema.js';
import type { EventRow } from './queue.js';
import { clearMissionUnits, fleetOfMission } from '../services/mission.js';
import { notify } from '../services/notifications.js';
import {
  lockSeason,
  recomputePlayerWealth,
  recomputeWealth,
} from '../services/planet.js';
import { landShips } from '../services/shipDamage.js';
import { publishShard } from '../stream/bus.js';
import { fleetChangesWatch, publishWatchChanges } from '../services/watchEvents.js';
import { abandonBuildOrder } from '../services/buildQueue.js';
import { abandonResearchOrder } from '../services/research.js';
import { abandonDeathStarBuild } from '../services/strategic.js';
import { abandonTradeRun } from '../services/trade.js';
import { abandonIntergalacticConvoyRun } from '../services/intergalacticConvoyRaid.js';
import { allocateClanLoot } from '../services/clanLoot.js';
import { capitalPlanet } from '../services/ownership.js';
import { landRunLocked } from '../services/mining.js';
import { abandonClanWarLeg, clanWarEscrowPlanetIds } from '../services/clanWar.js';
import { abandonClanSupportLeg } from '../services/clanSupport.js';
import { resolveRadiationBomb } from '../services/radiationBomb.js';

/**
 * WHAT HAPPENS WHEN AN EVENT GIVES UP FOR GOOD. D28.
 *
 * `fail()` retries an event five times and then parks it as `failed`, and until
 * now **nothing in the codebase ever read a `failed` row again**. That was already
 * a leak: `claimMission` flips a mission to `resolved` inside the same transaction
 * that can throw, so a permanently failing handler rolls the mission back to
 * `in_flight` on every attempt and leaves it there — blocking that origin→target
 * pair forever, stranding its units under `location = <missionId>`, and sitting in
 * the pending strip at "0 minutes" for the rest of the season.
 *
 * Flight bays turn that from a slow bleed into a wall: a stranded mission also
 * holds a bay with no path back, so a player can be permanently unable to launch.
 * That is why this is being fixed here rather than left for later.
 *
 * The craft come HOME rather than being destroyed. A handler that cannot run is
 * the server's failure, not the player's, and the conservative reading of an
 * unresolvable flight is that it never happened. `mission_status.cancelled` has
 * existed in the enum since the first migration and has never been written; this
 * is what it was for.
 */

/** Which planet's bay a leg occupies — outbound belongs to its origin, a return to its target. */
const ownerOf = (m: typeof missions.$inferSelect): string =>
  m.kind === 'return' || m.parentMissionId !== null ? m.targetPlanetId : m.originPlanetId;

/**
 * A CRAFT THAT COMES HOME FOR NO REASON THE PLAYER CAN SEE IS A BUG REPORT. D45.
 *
 * Abandoning is the server admitting it could not resolve a flight, and it used to
 * happen in complete silence: units reappeared in the garrison, a bay freed up, the
 * pending strip lost a line, and nothing anywhere said why. From the player's seat
 * that is indistinguishable from a fleet being eaten.
 *
 * It is rare — `/health` reports `failedEvents` and anything above zero is a bug
 * that has already happened — which is exactly why the one person it happened to
 * deserves a sentence.
 */
/**
 * `craftKind` is what the sentence is ABOUT, and a probe is the reason it exists.
 *
 * A probe carries no unit rows — it is built on demand and nothing comes home — so
 * `fleetCount` was 0 and the player was told "0 craft returned · that flight could
 * not be completed": a recall notice reporting the loss of nothing, for a scout
 * that was genuinely lost. The count is the right number and the wrong subject.
 */
async function tellThemItCameBack(
  tx: Tx,
  planetId: string,
  craft: number,
  refId: string,
  at: Date,
  craftKind: 'fleet' | 'probe' = 'fleet',
): Promise<void> {
  const [planet] = await tx
    .select({ playerId: planets.controllerPlayerId })
    .from(planets)
    .where(eq(planets.id, planetId));
  if (!planet?.playerId) return;
  await notify(tx, {
    playerId: planet.playerId,
    kind: 'fleet_returned',
    payload: { trip: 'recalled', craft, craftKind },
    at,
    refId,
  });
}

async function abandonMission(db: Db, missionId: string, at: Date): Promise<boolean> {
  return db.transaction(async (tx) => {
    // Discover the parent lock without treating an unlocked read as authority.
    // The live row is claimed again below, after the season lock, exactly like
    // the ordinary arrival path.
    const [candidate] = await tx
      .select({ seasonId: missions.seasonId })
      .from(missions)
      .where(eq(missions.id, missionId));
    if (!candidate) return false;
    await lockSeason(tx, candidate.seasonId);
    const [mission] = await tx
      .update(missions)
      .set({ status: 'cancelled' })
      .where(and(eq(missions.id, missionId), eq(missions.status, 'in_flight')))
      .returning();
    // Already resolved by a retry that won, or already abandoned. Nothing to undo.
    if (!mission) return false;

    if (mission.kind === 'clan_war') {
      const capital = await capitalPlanet(tx, mission.ownerPlayerId);
      const escrowPlanetIds = await clanWarEscrowPlanetIds(tx, mission.id);
      for (const planetId of [...new Set([
        mission.originPlanetId,
        mission.targetPlanetId,
        capital.id,
        ...escrowPlanetIds,
      ])].sort()) {
        await tx.select({ id: planets.id }).from(planets)
          .where(eq(planets.id, planetId)).for('update');
      }
      await abandonClanWarLeg(tx, mission, at);
      await publishShard(tx, mission.seasonId, 'arrival');
      return true;
    }

    if (mission.kind === 'clan_support') {
      const capital = await capitalPlanet(tx, mission.ownerPlayerId);
      for (const planetId of [...new Set([mission.originPlanetId, mission.targetPlanetId, capital.id])].sort()) {
        await tx.select({ id: planets.id }).from(planets).where(eq(planets.id, planetId)).for('update');
      }
      await abandonClanSupportLeg(tx, mission, at);
      await publishShard(tx, mission.seasonId, 'arrival');
      return true;
    }

    const storagePlanetId = ownerOf(mission);
    const capital = await capitalPlanet(tx, mission.ownerPlayerId);
    // A recall is the same read/merge/write as a normal landing. Without these
    // locks a concurrent build or return can commit between the read and upsert,
    // and one of the two fleets disappears. Lock both possible destinations in
    // the same sorted-world order launches already use; taking the player first
    // would invert that order and deadlock a launch.
    for (const planetId of [...new Set([storagePlanetId, capital.id])].sort()) {
      const [world] = await tx
        .select({ id: planets.id })
        .from(planets)
        .where(eq(planets.id, planetId))
        .for('update');
      if (!world) throw new Error('mission world vanished before abandonment');
    }
    // Revalidate after the locks. A colony may have changed hands while the leg
    // was airborne; the capital cannot, and is the deterministic safe fallback.
    const [preferred] = await tx
      .select({ id: planets.id })
      .from(planets)
      .where(and(
        eq(planets.id, storagePlanetId),
        eq(planets.controllerPlayerId, mission.ownerPlayerId),
      ));
    const destinationPlanetId = preferred?.id ?? capital.id;
    const stranded = await fleetOfMission(tx, storagePlanetId, mission.id);
    if (fleetEntries(stranded).length > 0) {
      await clearMissionUnits(tx, storagePlanetId, mission.id);
      // A leg the server gives up on is still a landing: the damage aboard is judged,
      // never dropped — dropping it would be a free repair. Kalıcı gemi hasarı.
      await landShips(tx, {
        planetId: destinationPlanetId,
        ownerPlayerId: mission.ownerPlayerId,
        fleet: stranded,
        damage: mission.damage,
        at,
      });
    }
    // A return leg carries loot that was already removed from the defender and
    // priced into Dominion. A server-side abandonment is still a safe landing:
    // preserve the ordinary clan split and deposit the remainder instead of
    // deleting the economic half of an already-recorded exchange.
    // And the wreck its Garbage Collectors lifted, which rides the same leg and is
    // the commander's whole — never the clan's share (D200, see `settleReturn`).
    if (mission.kind === 'return' && (mission.loot || mission.salvage)) {
      const landedLoot = mission.loot ? await allocateClanLoot(tx, mission, at) : null;
      const salvage = mission.salvage;
      await tx.update(planets).set({
        alloy: sql`${planets.alloy} + ${(landedLoot?.alloy ?? 0) + (salvage?.alloy ?? 0)}`,
        crystal: sql`${planets.crystal} + ${(landedLoot?.crystal ?? 0) + (salvage?.crystal ?? 0)}`,
        deuterium: sql`${planets.deuterium} + ${
          (landedLoot ? deuteriumOf(landedLoot) : 0) + (salvage ? deuteriumOf(salvage) : 0)
        }`,
      }).where(eq(planets.id, destinationPlanetId));
    }
    await recomputePlayerWealth(tx, mission.ownerPlayerId, at);
    if (destinationPlanetId !== storagePlanetId) await recomputeWealth(tx, storagePlanetId, at);
    await tellThemItCameBack(
      tx,
      destinationPlanetId,
      fleetCount(stranded),
      mission.id,
      at,
      mission.kind === 'probe' ? 'probe' : 'fleet',
    );
    /**
     * AND THE GALAXY IS TOLD THE CRAFT IS GONE. D53.
     *
     * A cancelled mission leaves `in_flight`, so it drops out of `galaxyTraffic` —
     * which means every other client is drawing a contact that no longer exists.
     * That used to correct itself on a twenty-second poll; the poll is now a
     * sixty-second net under the broadcast, so leaving this out would have made the
     * rarest failure in the game three times more visible than it was before.
     *
     * `arrival` rather than a kind of its own: from every screen but the owner's,
     * a flight ending because it was abandoned and a flight ending because it
     * landed are the same event — a contact that is no longer there.
     */
    await publishShard(tx, mission.seasonId, 'arrival');
    if (fleetChangesWatch(mission.fleet)) {
      await publishWatchChanges(tx, [mission.originPlanetId, mission.targetPlanetId]);
    }
    return true;
  });
}

async function abandonMiningRun(
  db: Db,
  runId: string,
  at: Date,
  expectedStatus?: 'outbound' | 'returning',
): Promise<boolean> {
  return db.transaction(async (tx) => {
    const [candidate] = await tx.select({ seasonId: miningRuns.seasonId })
      .from(miningRuns).where(eq(miningRuns.id, runId));
    if (!candidate) return false;
    await lockSeason(tx, candidate.seasonId);
    const [run] = await tx
      .update(miningRuns)
      .set({ status: 'done' })
      .where(and(
        eq(miningRuns.id, runId),
        expectedStatus
          ? eq(miningRuns.status, expectedStatus)
          : inArray(miningRuns.status, ['outbound', 'returning']),
      ))
      .returning();
    if (!run) return false;

    // This is the same read/merge/write as an ordinary landing, on the same world
    // (`landRunLocked`: the launch world while it has a commander, the commander's
    // capital once it fell to nobody). Serialized against construction, launches and
    // other returns, or a stale home count can erase the recalled craft.
    const landing = await landRunLocked(tx, run);
    if (landing) {
      const carried = await tx.select({ damage: units.damage }).from(units)
        .where(and(eq(units.planetId, run.planetId), eq(units.location, `mine:${runId}`)));
      await landShips(tx, { planetId: landing.planetId, ownerPlayerId: landing.playerId,
        fleet: { PROSPECTOR: run.craft }, damage: carried.flatMap(row => row.damage), at });
    }
    await tx
      .delete(units)
      .where(and(eq(units.planetId, run.planetId), eq(units.location, `mine:${runId}`)));
    if (landing) await tellThemItCameBack(tx, landing.planetId, run.craft, runId, at);
    /** Same reason: the drill is out of the sky, and the disc has to stop drawing it. */
    await publishShard(tx, run.seasonId, 'mining');
    return true;
  });
}

/**
 * Undo whatever a permanently failed event was going to resolve.
 *
 * Returns true if something was actually released, so the caller can say so in the
 * log — a silent abandonment is how this went unnoticed in the first place.
 */
export async function abandon(db: Db, event: EventRow, clock: Clock): Promise<boolean> {
  if (!event.refId) return false;
  switch (event.kind) {
    case 'unknown_signal_spawn':
      await db.transaction(tx => resolveUnknownSignalSpawn(tx, event.refId!, event.resolveAt, clock, true));
      return true;
    case 'mission_arrival':
      return abandonMission(db, event.refId, clock.now());
    case 'mining_arrival':
      // The old contact event survives a manual turn. A failed obsolete arrival
      // must not release craft that still have a real return leg ahead of them.
      return abandonMiningRun(db, event.refId, clock.now(), 'outbound');
    case 'mining_return':
      return abandonMiningRun(db, event.refId, clock.now(), 'returning');
    /**
     * A CONVOY THAT CANNOT BE RESOLVED COMES HOME WITH WHATEVER NEVER CHANGED
     * HANDS. D156.
     *
     * MATCHED ON THE EVENT'S OWN KIND, and here that is not merely hygiene (D46) —
     * it is the whole answer. One run has two moments and they owe the commander
     * two different piles: on the way out the OFFER is still aboard, on the way
     * back the HAUL is. A single `refId` cannot tell them apart, and getting it
     * wrong would either invent goods the merchant never sold or delete goods the
     * commander already paid for. Fuel is refunded on neither (D136).
     */
    case 'trade_arrival':
      return (await abandonTradeRun(db, event.refId, 'outbound', clock)) !== null;
    case 'trade_return':
      return (await abandonTradeRun(db, event.refId, 'returning', clock)) !== null;
    case 'convoy_arrival':
      return (await abandonIntergalacticConvoyRun(db, event.refId, 'outbound', clock)) !== null;
    case 'convoy_return':
      return (await abandonIntergalacticConvoyRun(db, event.refId, 'returning', clock)) !== null;
    case 'build_complete':
      // Migrated legacy research rows keep their old event kind because PostgreSQL
      // cannot use a newly-added enum value in the same migration transaction.
      return (await abandonBuildOrder(db, event.refId, clock))
        || abandonResearchOrder(db, event.refId, clock);
    case 'research_complete':
      return abandonResearchOrder(db, event.refId, clock);
    case 'radiation_bomb_arrival':
      await resolveRadiationBomb(db, event.refId, clock);
      return true;
    case 'death_star_ready':
      return abandonDeathStarBuild(db, event.refId, clock);
    default:
      // A radar warning or a season end strands nothing; letting it die is correct.
      return false;
  }
}

/* ── flights with no event at all ───────────────────────────── */

/**
 * How far past its own arrival a flight must be before it counts as stranded.
 *
 * Generous on purpose. A flight is only ever swept when it has NO live event, and
 * the window has to clear every legitimate reason a resolution can be a little
 * late: the worker's poll interval, a five-attempt retry budget, a reaped claim
 * from a killed worker, and a server that was simply down for a moment. Five
 * minutes is far past all of them and far short of a season.
 */
const STRANDED_GRACE_MINUTES = 5;

/**
 * A flight that is past its arrival and has NO live event pointing at it.
 *
 * THE HOLE D28 DID NOT COVER, found in a live galaxy. D46.
 *
 * D28 fixed what happens when an event fails permanently: `abandon()` releases
 * what it held. Every safety net in the system is built on the same assumption —
 * that a flight in the air has an event somewhere. `reap` requeues a claim whose
 * worker died; `fail` retries and then abandons; `/health` counts `failed` rows.
 * All three read the EVENT.
 *
 * So a mission whose event row is simply GONE is invisible to all of them. It sits
 * `in_flight` for the rest of the season, holding a flight bay that can never be
 * freed, its units parked off-planet, blocking its origin-target pair — and
 * `/health` says `ok`, because there is no failed event to count. One was found on
 * a development galaxy thirteen hours past its arrival, and nothing in the running
 * system could have noticed or repaired it.
 *
 * Rows can go missing for boring reasons — a harness that rewrote the queue, a
 * partial restore, a migration run against a live database — and the product
 * answer is the same in every case: the server could not resolve this flight, so
 * the conservative reading is that it never happened. That is exactly what
 * `abandon` already means, so this reuses it rather than inventing a second way
 * for a craft to come home.
 *
 * MATCHED ON THE EVENT'S OWN KIND, not just on `ref_id`. A mission has a
 * `radar_warning` pointing at it as well as its arrival, and a run that has turned
 * for home has a spent `mining_arrival` behind it — either would look like a live
 * event and keep a genuinely stranded flight invisible.
 */
export async function sweepStranded(db: Db, clock: Clock): Promise<number> {
  const now = clock.now();
  const {
    missions: strandedMissions,
    runs: strandedRuns,
    trades: strandedTrades,
    convoys: strandedConvoys,
    builds: strandedBuilds,
    research: strandedResearch,
    deathStars: strandedDeathStars,
    bombs: strandedBombs,
  } = await strandedState(db, now);

  let released = 0;
  for (const id of strandedMissions) if (await abandonMission(db, id, now)) released += 1;
  for (const id of strandedRuns) if (await abandonMiningRun(db, id, now)) released += 1;
  /*
    A CONVOY WHOSE EVENT ROW IS SIMPLY GONE HOLDS A BAY FOR THE REST OF THE SEASON.

    D46's hole, and a trade run falls into it the same way a mission does: `reap`,
    `fail` and `/health` all read the EVENT, so a flight with no event is invisible
    to every safety net there is. The leg is read off the row rather than guessed,
    because which pile comes home depends on it.
  */
  for (const { id, leg } of strandedTrades) {
    if (await abandonTradeRun(db, id, leg, clock)) released += 1;
  }
  for (const { id, leg } of strandedConvoys) {
    if (await abandonIntergalacticConvoyRun(db, id, leg, clock)) released += 1;
  }
  for (const id of strandedBuilds) if (await abandonBuildOrder(db, id, clock)) released += 1;
  for (const id of strandedResearch) {
    if (await abandonResearchOrder(db, id, clock)) released += 1;
  }
  for (const id of strandedDeathStars) {
    if (await abandonDeathStarBuild(db, id, clock)) released += 1;
  }
  for (const id of strandedBombs) {
    await resolveRadiationBomb(db, id, clock);
    released += 1;
  }
  return released;
}

/**
 * The two queries, in one place, so the sweep and the health check can never
 * disagree about what "stranded" means.
 *
 * RAW SQL WITH AN ISO STRING AND AN EXPLICIT CAST, and that is not a style choice:
 * `architecture.md` records that **Drizzle's `sql` template cannot bind a JS
 * `Date` through postgres.js**. The driver is handed the object and throws
 * `The "string" argument must be of type string`. Writing the instant out and
 * casting it is the shape that works.
 *
 * MATCHED ON THE EVENT'S OWN KIND, not just on `ref_id`. A mission has a
 * `radar_warning` pointing at it as well as its arrival, and a run that has turned
 * for home has a spent `mining_arrival` behind it — either would look like a live
 * event and keep a genuinely stranded flight invisible.
 */
async function strandedState(
  db: Db,
  now: Date,
): Promise<{
  missions: string[];
  runs: string[];
  trades: { id: string; leg: 'outbound' | 'returning' }[];
  convoys: { id: string; leg: 'outbound' | 'returning' }[];
  builds: string[];
  research: string[];
  deathStars: string[];
  bombs: string[];
}> {
  const cutoff = new Date(now.getTime() - STRANDED_GRACE_MINUTES * 60_000).toISOString();

  const missionRows = await db.execute<{ id: string }>(sql`
    select m.id from missions m
    where m.status = 'in_flight'
      and m.arrive_at < ${cutoff}::timestamptz
      and not exists (
        select 1 from scheduled_events e
        where e.ref_id = m.id and e.kind = 'mission_arrival'
          and e.status in ('pending', 'processing'))
  `);

  /**
   * A run is due at `arrive_at` on the way out and at `home_at` on the way back,
   * and `home_at` is NULL until it turns — so `coalesce` picks whichever leg it is
   * actually on rather than measuring an outbound run against a time it has not
   * been given yet.
   */
  const runRows = await db.execute<{ id: string }>(sql`
    select r.id from mining_runs r
    where r.status in ('outbound', 'returning')
      and coalesce(r.home_at, r.arrive_at) < ${cutoff}::timestamptz
      and not exists (
        select 1 from scheduled_events e
        where e.ref_id = r.id
          and ((r.status = 'outbound' and e.kind = 'mining_arrival')
            or (r.status = 'returning' and e.kind = 'mining_return'))
          and e.status in ('pending', 'processing'))
  `);

  /** Same `coalesce` shape as a mining run: `home_at` is NULL until it turns. */
  const tradeRows = await db.execute<{ id: string; status: 'outbound' | 'returning' }>(sql`
    select t.id, t.status from trade_runs t
    where t.status in ('outbound', 'returning')
      and coalesce(t.home_at, t.arrive_at) < ${cutoff}::timestamptz
      and not exists (
        select 1 from scheduled_events e
        where e.ref_id = t.id and e.kind in ('trade_arrival', 'trade_return')
          and e.status in ('pending', 'processing'))
  `);

  const convoyRows = await db.execute<{ id: string; status: 'outbound' | 'returning' }>(sql`
    select c.id, c.status from intergalactic_convoy_runs c
    where c.status in ('outbound', 'returning')
      and case when c.status = 'outbound' then c.engagement_ends_at else c.home_at end
          < ${cutoff}::timestamptz
      and not exists (
        select 1 from scheduled_events e
        where e.ref_id = c.id
          and ((c.status = 'outbound' and e.kind = 'convoy_arrival')
            or (c.status = 'returning' and e.kind = 'convoy_return'))
          and e.status in ('pending', 'processing'))
  `);

  const buildRows = await db.execute<{ id: string }>(sql`
    select b.id from build_orders b
    where b.status = 'BUILDING'
      and b.ready_at < ${cutoff}::timestamptz
      and not exists (
        select 1 from scheduled_events e
        where e.ref_id = b.id and e.kind = 'build_complete'
          and e.status in ('pending', 'processing'))
  `);

  const researchRows = await db.execute<{ id: string }>(sql`
    select r.id from research_orders r
    where r.status = 'BUILDING'
      and r.ready_at < ${cutoff}::timestamptz
      and not exists (
        select 1 from scheduled_events e
        where e.ref_id = r.id and e.kind in ('research_complete', 'build_complete')
          and e.status in ('pending', 'processing'))
  `);

  const deathStarRows = await db.execute<{ id: string }>(sql`
    select a.id from strategic_assets a
    where a.status = 'BUILDING'
      and a.ready_at < ${cutoff}::timestamptz
      and not exists (
        select 1 from scheduled_events e
        where e.ref_id = a.id and e.kind = 'death_star_ready'
          and e.status in ('pending', 'processing'))
  `);

  const bombRows = await db.execute<{ id: string }>(sql`
    select b.id from radiation_bomb_flights b
    where b.status = 'OUTBOUND' and b.arrive_at < ${cutoff}::timestamptz
      and not exists (select 1 from scheduled_events e where e.ref_id = b.id
        and e.kind = 'radiation_bomb_arrival' and e.status in ('pending', 'processing'))
  `);

  return {
    missions: missionRows.map((row) => row.id),
    bombs: bombRows.map(row => row.id),
    runs: runRows.map((row) => row.id),
    trades: tradeRows.map((row) => ({ id: row.id, leg: row.status })),
    convoys: convoyRows.map((row) => ({ id: row.id, leg: row.status })),
    builds: buildRows.map((row) => row.id),
    research: researchRows.map((row) => row.id),
    deathStars: deathStarRows.map((row) => row.id),
  };
}

/**
 * How many flights are stranded right now, for `/health` to shout about.
 *
 * A separate read rather than a by-product of the sweep, because health must be
 * able to report the number on an API-only process that runs no worker at all.
 */
export async function strandedFlightCount(db: Db, now: Date): Promise<number> {
  const { missions: m, runs: r, trades: t, convoys: c, bombs: b } = await strandedState(db, now);
  return m.length + r.length + t.length + c.length + b.length;
}

/** Ordinary and strategic builds whose completion event has disappeared. */
export async function strandedBuildCount(db: Db, now: Date): Promise<number> {
  const { builds, research, deathStars } = await strandedState(db, now);
  return builds.length + research.length + deathStars.length;
}

