export interface HandlerContext {
  db: Db;
  clock: Clock;
  /** Out-of-band operator identities never participate in the competitive ledger. */
  adminUsernames?: ReadonlySet<string>;
}

export type Handler = (ctx: HandlerContext, event: EventRow) => Promise<void>;

/**
 * Claim a mission for resolution, exactly once.
 *
 * Returns null if another worker already resolved it. This is what makes event
 * handling idempotent: an event delivered twice does nothing the second time,
 * so a crashed-and-retried worker cannot double-resolve a battle.
 */
async function claimMission(tx: Tx, missionId: string, eventResolveAt: Date) {
  const rows = await tx
    .update(missions)
    .set({ status: 'resolved' })
    .where(and(
      eq(missions.id, missionId),
      eq(missions.status, 'in_flight'),
      /*
        A CLAIMED ARRIVAL CAN OUTLIVE THE ETA IT WAS CLAIMED FOR. A transfer recall
        replaces its queue row, but the worker may already hold the deleted row in
        memory. The persisted ETA is authoritative: an event from before that ETA
        cannot settle the mission, even after its transaction resumes.
      */
      lte(missions.arriveAt, eventResolveAt),
    ))
    .returning();
  return rows[0] ?? null;
}

/** Lock every Dominion ledger in one stable player-id order. */
/* ── mission arrival ────────────────────────────────────────── */

/**
 * An attacking fleet lands.
 *
 * Everything below happens in ONE transaction: combat, loot, disruption, both
 * ledgers, the report, and the return leg. Either all of it happened or none of
 * it did — there is no state in which a fleet has fought but not come home.
 */
export const onMissionArrival: Handler = async ({ db, clock, adminUsernames = new Set() }, event) => {
  const missionId = event.refId;
  if (!missionId) throw new Error('mission_arrival without refId');

  await db.transaction(async (tx) => {
    const season = await lockSeason(tx, event.seasonId);
    const mission = await claimMission(tx, missionId, event.resolveAt);
    if (!mission) return; // already resolved, or this queue row was superseded

    /**
     * THE WHOLE GALAXY WATCHES A FLIGHT END. D53.
     *
     * Every branch below ends a leg that somebody else could see: a raid resolving
     * into a debris field, a probe going home, a squadron landing. All of it is
     * public and all of it used to arrive on a twenty-second poll — which, for a
     * raid, meant the bombardment finished and the squadron then hung over the
     * world it had already destroyed until a timer happened along.
     *
     * Published on the CLAIM rather than at the end, for the reason the claim
     * exists: a redelivered event finds the mission already resolved, claims
     * nothing, returns here, and must not send three hundred clients to refetch a galaxy
     * that has not changed. And it is inside the transaction, so a resolution that
     * rolls back is never announced.
     */
    await publishShard(tx, mission.seasonId, 'arrival');
    if (fleetChangesWatch(mission.fleet)) {
      await publishWatchChanges(tx, [mission.originPlanetId, mission.targetPlanetId]);
    }

    // Every arrival may touch both endpoints; an acquisition also serializes on
    // its commander's immutable capital. Take all of them in one stable order.
    const [ownerCapital] = await tx
      .select({ id: planets.id })
      .from(planets)
      .where(and(
        eq(planets.controllerPlayerId, mission.ownerPlayerId),
        eq(planets.kind, 'CAPITAL'),
      ));
    const jointEscrowPlanetIds = mission.kind === 'clan_war'
      ? await clanWarEscrowPlanetIds(tx, mission.id)
      : [];
    const [originChangeTarget] = mission.kind === 'death_star'
      ? await tx.select({ kind: planets.kind }).from(planets).where(eq(planets.id, mission.targetPlanetId)) : [];
    const preparesMonumentOrigin = originChangeTarget?.kind === 'COLONY';
    const monumentCapitals = preparesMonumentOrigin
      ? await monumentOriginCapitals(tx, mission.targetPlanetId) : [];
    const lockedPlanetIds = [...new Set([
      mission.originPlanetId,
      mission.targetPlanetId,
      ...(ownerCapital ? [ownerCapital.id] : []),
      ...jointEscrowPlanetIds,
      ...monumentCapitals,
    ])].sort();
    for (const id of lockedPlanetIds) {
      await tx.select({ id: planets.id }).from(planets).where(eq(planets.id, id)).for('update');
    }
    if (preparesMonumentOrigin) await prepareMonumentOriginChange(tx, mission.targetPlanetId);

    /*
      A JOINT WAR LEG IS DISPATCHED BEFORE EVERY GENERIC BRANCH. Klan Ortak Savaşı.

      `mission_kind` carries one value for all four legs — which leg this actually
      is lives in `clan_war_missions` — so the relation is consulted first and the
      operation's own resolver takes it from there. Placed ahead of the ordinary
      branches deliberately: a clan-war mission must never fall through into the
      generic attack, transfer or return handling, each of which would settle it
      as something it is not.
    */
    if (mission.kind === 'clan_war') {
      await resolveClanWarLeg(tx, mission, clock.now(), adminUsernames);
      return;
    }
    /*
      KLAN SAVUNMA DESTEĞİ: both legs of a support wave, ahead of every generic branch
      for the same reason as the joint war — neither is a transfer, a raid or a return.
    */
    if (mission.kind === 'clan_support') {
      await resolveClanSupportLeg(tx, mission, clock.now());
      return;
    }

    if (mission.kind === 'death_star') {
      const [earlierImpact] = await tx
        .select({ id: missions.id })
        .from(missions)
        .where(and(
          eq(missions.kind, 'death_star'),
          eq(missions.status, 'in_flight'),
          eq(missions.targetPlanetId, mission.targetPlanetId),
          eq(missions.arriveAt, mission.arriveAt),
          sql`${missions.id} < ${mission.id}`,
        ))
        .limit(1);
      if (earlierImpact) {
        throw new Error(`death star ${mission.id} is waiting for ${earlierImpact.id}`);
      }
    }

    if (mission.kind === 'death_star') {
      /*
        A SHOT A LATE QUEUE STILL OWES COMES FIRST. If the weapon stood in a ring
        or a Telescope's sight with a charge ready before this instant, it died
        there and never arrives — see `interceptOwedShot`. On a punctual worker
        the event already fired and this mission never reached here in flight.
      */
      if (await interceptOwedShot(tx, mission, clock.now())) return;
      const result = await applyDeathStarStrike(tx, mission, clock.now());
      const outcome = result.outcome;
      await tx.insert(strategicImpacts).values({
        seasonId: mission.seasonId,
        missionId: mission.id,
        attackerPlayerId: mission.ownerPlayerId,
        defenderPlayerId: result.previousPlayerId,
        targetPlanetId: mission.targetPlanetId,
        outcome,
        damage: result.damage,
        destroyedFleet: result.destroyedFleet,
        destroyedResources: result.destroyedResources,
        levelChanges: result.levelChanges,
        destroyedOrders: result.destroyedOrders,
        shieldDestroyed: result.shieldDestroyed,
        loyaltyBefore: result.loyaltyBefore,
        loyaltyAfter: result.loyaltyAfter,
        createdAt: clock.now(),
      }).onConflictDoNothing({ target: strategicImpacts.missionId });
      await tx
        .update(strategicAssets)
        .set({ status: 'CONSUMED' })
        .where(and(
          eq(strategicAssets.missionId, mission.id),
          eq(strategicAssets.status, 'LAUNCHED'),
        ));
      await observeHonorOwner(tx, mission.ownerPlayerId, clock.now());
      /*
        A COLONY'S LOYALTY RIDES ON THE NEWS (owner, 2026-10-01), so a commander who never
        opens the report still learns their colony is slipping — or gone — from the bell.
      */
      const loyalty = result.loyaltyBefore === null || result.loyaltyAfter === null
        ? {}
        : { loyalty: { before: result.loyaltyBefore, after: result.loyaltyAfter } };
      await notify(tx, {
        playerId: mission.ownerPlayerId,
        kind: 'death_star_result',
        payload: { outcome, targetPlanetId: mission.targetPlanetId, ...loyalty },
        at: clock.now(),
        refId: mission.id,
      });
      if (outcome === 'CAPTURED') {
        await notify(tx, {
          playerId: mission.ownerPlayerId,
          kind: 'colony_captured',
          payload: { targetPlanetId: mission.targetPlanetId },
          at: clock.now(),
          refId: mission.id,
        });
      }
      if (result.previousPlayerId && result.previousPlayerId !== mission.ownerPlayerId) {
        await notify(tx, {
          playerId: result.previousPlayerId,
          kind: outcome === 'CAPTURED' ? 'colony_lost' : 'death_star_result',
          payload: { outcome, targetPlanetId: mission.targetPlanetId, ...loyalty },
          at: clock.now(),
          refId: mission.id,
        });
      }
      const [impactWorld] = await tx
        .select({ name: planets.name, kind: planets.kind })
        .from(planets)
        .where(eq(planets.id, mission.targetPlanetId));
      if (impactWorld) {
        await recordGalaxyEvent(tx, {
          seasonId: mission.seasonId,
          kind: 'death_star_impact',
          refId: mission.id,
          subjectPlanetId: mission.targetPlanetId,
          payload: {
            planetName: impactWorld.name,
            outcome,
            capturable: impactWorld.kind !== 'CAPITAL',
          },
          occurredAt: clock.now(),
        });
      }
      if (outcome === 'CAPTURED') {
        const captured = await publicPlanetIdentity(tx, mission.targetPlanetId);
        if (captured) {
          await recordGalaxyEvent(tx, {
            seasonId: mission.seasonId,
            kind: 'control_transfer',
            refId: mission.id,
            subjectPlanetId: mission.targetPlanetId,
            payload: captured,
            occurredAt: clock.now(),
          });
        }
      }

      /**
       * AND THE CRAFT SAW THE WORLD IT REACHED. D151.
       *
       * Written after the strike so the attacker remembers the world with its
       * Aegis drained. No ownership or sensor topology changes on EMP impact.
       */
      await rememberVisitedWorld(tx, {
        observerPlayerId: mission.ownerPlayerId,
        targetPlanetId: mission.targetPlanetId,
        seasonId: mission.seasonId,
        seenAt: clock.now(),
      });

      await publishShard(tx, mission.seasonId, outcome === 'CAPTURED' ? 'control' : 'impact');
      return;
    }

    if (mission.kind === 'transfer') {
      const outcome = await resolveTransfer(tx, mission, clock.now(), season.rulesetVersion);
      // A cloud took every ship: `radiation_lost` said so, and nothing was rerouted.
      if (outcome === 'REROUTED_CAPACITY' || outcome === 'REROUTED_OWNERSHIP') {
        // The world that closed its doors: a recalled flight was landing where it LEFT from.
        // Self-review 2026-09-23, R8.
        const landingPlanetId = mission.recalledAt !== null
          ? mission.originPlanetId
          : mission.targetPlanetId;
        const [target] = await tx
          .select({ name: planets.name })
          .from(planets)
          .where(eq(planets.id, landingPlanetId));
        await notify(tx, {
          playerId: mission.ownerPlayerId,
          kind: 'fleet_returned',
          payload: {
            trip: 'transfer_rerouted',
            reason: outcome === 'REROUTED_CAPACITY' ? 'CAPACITY' : 'OWNERSHIP',
            craft: fleetCount(mission.fleet),
            targetPlanetId: landingPlanetId,
            targetPlanetName: target?.name ?? 'an unknown world',
          },
          at: clock.now(),
          refId: mission.id,
        });
      }
      await publishShard(tx, mission.seasonId, 'transfer');
      return;
    }

    if (mission.kind === 'clan_transfer') {
      await resolveClanAid(tx, mission, clock.now(), season.rulesetVersion);
      await publishShard(tx, mission.seasonId, 'transfer');
      return;
    }

    if (mission.kind === 'settlement') {
      const outcome = await resolveSettlement(tx, mission, clock.now(), season.rulesetVersion);
      // Settlers a cloud finished are not a lost race: nothing is returning and the charge is
      // already home, so `radiation_lost` is the only word (plan F9).
      if (outcome !== 'LOST') {
        await notify(tx, {
          playerId: mission.ownerPlayerId,
          kind: outcome === 'CAPTURED' ? 'settlement_success' : 'settlement_lost',
          payload: { targetPlanetId: mission.targetPlanetId },
          at: clock.now(),
          refId: mission.id,
        });
      }
      if (outcome === 'CAPTURED') {
        const captured = await publicPlanetIdentity(tx, mission.targetPlanetId);
        if (captured) {
          await recordGalaxyEvent(tx, {
            seasonId: mission.seasonId,
            kind: 'control_transfer',
            refId: mission.id,
            subjectPlanetId: mission.targetPlanetId,
            payload: captured,
            occurredAt: clock.now(),
          });
        }
      }
      /**
       * AND THE SETTLERS SAW THE ROCK THEY REACHED. D151.
       *
       * The interesting outcome here is the one that FAILED. A settlement whose
       * claim window closed under it is rerouted home having flown all the way to
       * a world somebody else now holds — and "who beat me to it" is precisely the
       * question the commander is left with. On a capture this is inert, because a
       * world you hold resolves without any record at all.
       *
       * A `transfer` and a `clan_transfer` are deliberately NOT here: one lands on
       * your own world and the other on a teammate's, whose identity and worlds
       * D114 already publishes live to the whole clan. Neither is a look at
       * anything the fog was hiding.
       */
      // Settlers a cloud finished never reached the rock, so they saw nothing of it.
      if (outcome !== 'LOST') {
        await rememberVisitedWorld(tx, {
          observerPlayerId: mission.ownerPlayerId,
          targetPlanetId: mission.targetPlanetId,
          seasonId: mission.seasonId,
          seenAt: clock.now(),
        });
      }

      await publishShard(tx, mission.seasonId, outcome === 'CAPTURED' ? 'control' : 'transfer');
      return;
    }

    if (mission.kind === 'return') {
      // A return leg travels BACKWARDS: its origin is the planet that was raided
      // and its target is the attacker's home, which is where the ships live.
      await settleReturn(tx, mission, mission.targetPlanetId, clock.now(), season.rulesetVersion);
      return;
    }

    /*
      A RAID THAT TURNED LANDS AT HOME AND FIGHTS NOTHING. K8.

      Stored forwards — origin home, target the world it was flying at — and its ships still
      parked under the mission at home, so it settles exactly like a return leg with nothing in
      the hold. No battle, no report, no loot; the owner is told it is back from the world it
      turned away from.
    */
    if (mission.kind === 'attack' && mission.recalledAt !== null) {
      await settleReturn(tx, mission, mission.originPlanetId, clock.now(), season.rulesetVersion, mission.targetPlanetId);
      return;
    }

    if (mission.kind === 'probe') {
      /**
       * A probe coming home.
       *
       * Nothing is measured on this leg — the snapshot was taken when it arrived.
       * All that happens here is that the answer becomes readable, which is the
       * point of making it fly back at all: the intel is a round trip, so scouting
       * is a commitment rather than a purchase.
       */
      if (mission.parentMissionId) {
        const deliveredAt = clock.now();
        const [delivered] = await tx
          .update(probeReports)
          .set({ deliveredAt })
          .where(and(
            eq(probeReports.missionId, mission.parentMissionId),
            isNull(probeReports.deliveredAt),
          ))
          .returning();
        // Nothing came back means a redelivery of an event already handled; the
        // report was marked delivered the first time and its owner already told.
        if (!delivered) return;

        if (delivered.silhouette) {
          await rememberWorld(tx, {
            observerPlayerId: delivered.observerPlayerId,
            targetPlanetId: delivered.targetPlanetId,
            seasonId: mission.seasonId,
            source: 'PROBE',
            reportId: delivered.id,
            silhouette: delivered.silhouette,
            // The record is what the probe SAW at the far world, not when the
            // return craft finally reached home. `createdAt` is that observation
            // instant; `deliveredAt` only gates when the player may read it.
            seenAt: delivered.createdAt,
          });
        }

        /**
         * THE INTEL HAS LANDED, AND SAYING SO IS THE POINT. D45.
         *
         * This branch used to set a timestamp and stop. A probe is the most
         * deliberate purchase in the game — alloy, a flight bay, a round trip, and
         * the risk of being caught — and the moment its answer became readable was
         * the one moment nothing was published: no notification, no stream event,
         * so not even the intel panel refreshed for a player who had it open.
         * "The information is the game", and the information arrived in silence.
         */
        const scouted = await identityOfPlanet(tx, delivered.targetPlanetId);
        await notify(tx, {
          playerId: delivered.observerPlayerId,
          kind: 'probe_report',
          payload: {
            targetPlanetId: delivered.targetPlanetId,
            targetUsername: scouted?.username ?? 'someone',
            targetPlanetName: scouted?.planetName ?? 'an unknown world',
            ...(scouted?.clanTag ? { targetClanTag: scouted.clanTag } : {}),
            // Their radar caught it. The intel screen says so too; this is the
            // first time the player finds out, and it decides whether they are
            // expected.
            detected: delivered.detected,
          },
          at: deliveredAt,
          refId: mission.parentMissionId,
        });
        return;
      }

      /*
        Seeded from the mission id like combat, so a report — and whether it was
        detected — can be re-derived from its inputs.

        The BEARING is not read here any more. `resolveProbe` writes it to
        `scan_events`, which is the row `readRadarLog` gates from Radar L2; it used
        to be copied into the notification payload as well, where nothing gated it
        at all. One fact, one surface, one gate.
      */
      const { detected } = await resolveProbe(
        tx,
        mission,
        clock.now(),
        seededFrom(missionId),
      );
      if (detected) {
        const [target] = await tx
          .select()
          .from(planets)
          .where(eq(planets.id, mission.targetPlanetId));
        if (target?.controllerPlayerId) {
          /**
           * THE BEARING IS NOT IN THIS PAYLOAD, AND IT USED TO BE.
           *
           * The comment here said the bearing was carried and "what the player is
           * shown is decided at read time by their radar level". The read-time
           * gate was never written: `/api/notifications` returns `payload` raw, so
           * a Radar 1 defender could read the compass direction straight off the
           * API while `readRadarLog` — the surface that SELLS it from L2 — was
           * carefully returning null. Fog enforced in the UI is not enforced.
           *
           * It is not redacted here either, because there is nothing to redact:
           * the bearing belongs to the radar log, which is gated correctly and is
           * where the notification already sends the reader. One fact, one surface,
           * one gate. `scan_events` still records it for that log.
           */
          await notify(tx, {
            playerId: target.controllerPlayerId,
            kind: 'scan_detected',
            payload: {},
            at: clock.now(),
            refId: missionId,
          });
          // "Was someone poking at me?" — the feeling that opens the Radar, and
          // the one that opens the Veil. Design Law #2.
          await announceUnlocks(tx, target.controllerPlayerId, clock.now());
        }
      }

      // The trip home. Symmetric, because a probe is the same craft going the
      // other way — and it is scheduled inside the same transaction as the
      // snapshot, so a report can never exist with no way to reach its owner.
      const home = travelExact(mission.distance, PROBE.speed);
      const backAt = addMinutes(clock.now(), home);
      const [ret] = await tx
        .insert(missions)
        .values({
          // A return leg is already paid for: fuel is charged in full at the outbound launch.
          fuelPaid: 0,
          seasonId: mission.seasonId,
          kind: 'probe',
          ownerPlayerId: mission.ownerPlayerId,
          originPlanetId: mission.targetPlanetId,
          targetPlanetId: mission.originPlanetId,
          fleet: {},
          distance: mission.distance,
          departAt: clock.now(),
          arriveAt: backAt,
          parentMissionId: mission.id,
        })
        .returning();
      await schedule(tx, {
        seasonId: mission.seasonId,
        kind: 'mission_arrival',
        refId: ret!.id,
        resolveAt: backAt,
      });
      return;
    }

    /*
      RADYASYON FIRST. Plan §3.5.4.

      The dose the wing took on the way in is settled before it does anything here — before
      it fights, before it finds a shield and turns round — so it arrives as what it is.
      A wing leaves home whole (I1) and takes one dose, so a cloud finishes all of it or
      none of it: one it finished never struck (D13), and nobody but its commander hears.
    */
    const dosed = await settleMissionRadiation(tx, mission, {
      storagePlanetId: mission.originPlanetId,
      observedAt: clock.now(),
      rulesetVersion: season.rulesetVersion,
    });
    const flown = dosed.mission;
    await tellRadiationLoss(tx, flightWitness(flown), dosed, clock.now());
    if (fleetCount(dosed.destroyed) > 0 && fleetCount(dosed.fleet) === 0) {
      await releaseStrike(tx, mission.id);
      return;
    }

    const [targetWorld] = await tx
      .select({
        kind: planets.kind,
        controllerPlayerId: planets.controllerPlayerId,
        recoveryUntil: planets.recoveryUntil,
        protectedUntil: planets.protectedUntil,
      })
      .from(planets)
      .where(eq(planets.id, mission.targetPlanetId));
    if (!targetWorld) throw new Error('attack target vanished');
    // Ownership can change after launch. A fleet that reaches a world its own
    // commander now controls has no opponent and therefore no score exchange;
    // send it home intact instead of fighting itself or poisoning the retry queue.
    if (targetWorld.controllerPlayerId === mission.ownerPlayerId) {
      await returnAttackUntouched(tx, flown, clock);
      return;
    }
    if (
      (targetWorld.recoveryUntil !== null && targetWorld.recoveryUntil > clock.now())
      || (targetWorld.protectedUntil !== null && targetWorld.protectedUntil > clock.now())
    ) {
      await returnAttackUntouched(tx, flown, clock);
      /**
       * AND THE CRAFT SAW THE WORLD IT REACHED. D151.
       *
       * A squadron that finds a shield standing and turns round still CROSSED the
       * distance and still sat in that orbit. It is also the arrival where the
       * record matters most: "it was protected" is the answer to "why did nothing
       * happen", and a map that went on showing a pre-flight snapshot would leave
       * the commander with no way to reach it.
       */
      await rememberVisitedWorld(tx, {
        observerPlayerId: mission.ownerPlayerId,
        targetPlanetId: mission.targetPlanetId,
        seasonId: mission.seasonId,
        seenAt: clock.now(),
      });
      return;
    }
    if (targetWorld.kind === 'NEUTRAL') {
      await resolveNeutralBattle(tx, flown, clock, season.rulesetVersion);
      /**
       * AND THE CRAFT SAW THE WORLD IT REACHED. D151.
       *
       * A rock is a world like any other here: the fleet was there, and what it
       * found — the tier's development, the claim window it may just have opened —
       * is what the disc has to draw until somebody looks again.
       */
      await rememberVisitedWorld(tx, {
        observerPlayerId: mission.ownerPlayerId,
        targetPlanetId: mission.targetPlanetId,
        seasonId: mission.seasonId,
        seenAt: clock.now(),
      });
      return;
    }

    if (!targetWorld.controllerPlayerId) {
      throw new Error('player attack target has no controller');
    }
    /*
      KLAN SAVUNMA DESTEĞİ: the clanmates' waves standing at this world, locked after the
      world and before any clan or player row — the one order (`defenderLine.ts`). An admin
      among their commanders makes the battle unscored: their ships set the host's factor.
    */
    const stationWaves = await lockStationsAt(tx, {
      hostPlanetId: mission.targetPlanetId,
      rulesetVersion: season.rulesetVersion,
    });
    const supporterIds = supporterIdsOf(stationWaves);
    const adminPlayerIds = await adminPlayerIdsInSeason(
      tx,
      mission.seasonId,
      adminUsernames,
    );
    const scoreEligible =
      !adminPlayerIds.has(mission.ownerPlayerId)
      && !adminPlayerIds.has(targetWorld.controllerPlayerId)
      && supporterIds.every((id) => !adminPlayerIds.has(id));
    // Clan management takes a clan row before its player rows. Pre-lock the
    // score snapshots in stable order, then take player ledgers, so the shared
    // cross-system rows follow season→planet→clan→player and cannot form a cycle.
    if (scoreEligible) await lockClanBattleScore(tx, mission.id);
    // Launches already hold their sorted planet rows before player state. This
    // remains after every clan row above, and every player is locked by id, so a
    // launch cannot hold one half of the order while settlement holds the other.
    // Different colonies of one defender meet here and cannot overwrite scores.
    // A supporter's ledger never moves (owner, 2026-10-02), but `settleStations` writes their
    // row (wealth): it is taken here, in the one id order, never late after the attacker's.
    const lockedLedgers = await lockLedgers(tx, [
      mission.ownerPlayerId,
      targetWorld.controllerPlayerId,
      ...supporterIds,
    ]);
    const attackerLedger = lockedLedgers.get(mission.ownerPlayerId);
    const defenderLedger = lockedLedgers.get(targetWorld.controllerPlayerId);
    if (!attackerLedger || !defenderLedger) {
      throw new Error('battle controller changed before its player lock');
    }
    const leaderBefore = await publicDominionLeader(tx, mission.seasonId, adminPlayerIds);
    const before = attackerLedger.taken - attackerLedger.lost;
    const defenderBefore = defenderLedger.taken - defenderLedger.lost;

    const defender = await loadLocked(tx, mission.targetPlanetId, clock);
    const pvpBalance = await commanderPvpBalance(tx, defender.playerId);
    const attackerHomeId = await safeHomePlanet(tx, mission.ownerPlayerId, mission.originPlanetId);
    const attackerOrbit = await orbitOf(tx, attackerHomeId);

    const attackingFleet = await fleetOfMission(tx, mission.originPlanetId, missionId);
    if (fleetCount(attackingFleet) === 0) return;

    // Fighting hulls at home plus the emplacements, and the mining craft in
    // neither. `garrisonOf` is the single definition every battle surface reads.
    /*
      TWO SIDES, TWO MOMENTS. T8 · T9.

      The attacker's ladders were snapshotted onto the mission when they committed
      it; the defender's are read now, at the fight. An attacker who finished a
      doctrine mid-flight does not get it, and a defender who did does — which is
      the only reading under which each figure belongs to a decision somebody
      actually made.
    */
    const attackerTech = mission.tech ?? {};
    const defenderTech = await techOf(tx, defender.playerId);
    /*
      KOMUTA MERKEZİNDE KESİNTİ: THE DOME IS DARK AND THE GUNS DO NOT FIRE.
      Koloni arızaları, `CORE_OUTAGE`.

      The ships standing at home still fight — a crew does not need the Core to fly.
      What the Core runs is the Aegis and the fire control on the emplacements, and
      with it out both are simply absent from the line.

      THE GROUND GOES BACK AS IT CAME, and the block below is where that is done.
      `defenderSurvivors[hull] ?? 0` reads "not in the battle" as "annihilated", which
      is right for a gun that fought and lost and catastrophic for one that never
      fired: an outage would DESTROY a world's whole defensive line rather than
      silence it for one raid. `NON_COMBATANT_HULLS` pays for exactly the same branch
      one line up, for exactly the same reason.
    */
    const defenceDark = !defenceOnline(defender.faults, defender.empUntil, defender.now);
    const homePartition = partitionCombatFleet(defender.homeFleet, defender.homeDamage);
    const defenders = garrisonOf(homePartition.eligible, defenceDark ? {} : defender.ground);
    /*
      TAKTİK GERİ ÇEKİLME. Owner decision, 2026-09-23 (`escape.ts`).

      Seeded from the mission id: any report can be re-derived from its inputs, which
      makes battles auditable and bug reports reproducible — and a raid the ships ran
      from is resolved twice from that same seed, once standing and once without them.
      The tank read here is the one the lift burns from; a season dealt before the
      rule never runs.
    */
    const stations = await standStations(tx, {
      waves: stationWaves,
      host: defender,
      rulesetVersion: season.rulesetVersion,
      now: defender.now,
    });
    const defenceNavy = await honorDefenceNavy(tx, mission.seasonId, [defender.playerId, ...supporterIds]);
    const replayAttackers = [{ ...soloStack(attackingFleet, { tech: attackerTech }, flown.damage ?? undefined), contributionId: missionId, playerId: mission.ownerPlayerId }];
    const replayCapture = prepareBattleReplay(replayAttackers, [{ stackId: 'host', playerId: defender.playerId, fleet: defenders,
      tech: { tech: defenderTech }, damage: homePartition.damage.filter(lot => !NON_COMBATANT_HULLS.includes(lot.hull)) }, ...stations.map(station => station.stack)]);
    const raid = resolveRaid({
      recording: replayCapture.recording,
      // What the wing arrived with in damage (radiation on the way in); null when whole.
      stacks: replayAttackers,
      line: defenders,
      homeDamage: homePartition.damage.filter((lot) => !NON_COMBATANT_HULLS.includes(lot.hull)),
      maintenance: true,
      shield: defenceDark ? 0 : defender.shield,
      rng: () => seededFrom(missionId),
      defender: { tech: defenderTech },
      deuterium: defender.deuterium,
      // From ruleset 15 the world's posture decides; before it, the season's rule.
      escape: escapeAllowed(season.rulesetVersion, defender.defencePosture),
      minimumCombatShips: fleetEscapeMinimumApplies(season.rulesetVersion)
        ? ESCAPE.minimumCombatShips : 0,
      support: stations.map((station) => station.stack),
      hostPlayerId: defender.playerId,
      preciseDamage: hpRadiationApplies(season.rulesetVersion),
    });
    const result = raid.result;
    /*
      THE HOST'S OWN PART OF THE LINE. With no wave standing it IS the whole line; with
      waves, the aggregate also holds clanmates' ships, which must never be written into
      the host's home or dock — each wave's survivors go back to its own row below.
    */
    const hostOutcome = result.defenders[0]!;
    const defenderCount = defenderCountOf(stations);
    const escaped: Fleet = raid.escape?.kind === 'ESCAPED' ? raid.escape.ships : {};
    const liftFuel = raid.escape?.kind === 'ESCAPED' ? raid.escape.fuel : 0;
    // The line that actually stood — the guns alone when the ships ran.
    const stood: Fleet = {};
    for (const [hull, count] of fleetEntries(defenders)) {
      if ((escaped[hull] ?? 0) === 0) stood[hull] = count;
    }

    // Defender: survivors, plus whatever salvages out of the wreckage.
    const defenderHome: Fleet = {};
    for (const [hull, standing] of fleetEntries(defender.homeFleet)) {
      /**
       * A CRAFT THAT NEVER ENTERED THE BATTLE IS CARRIED ACROSS BY HAND.
       *
       * It is absent from `defenderSurvivors` because it was absent from the
       * defending line, and `?? 0` reads that absence as annihilation — so the
       * change that stops a raid killing miners would, without this branch,
       * delete every one of them on every raid instead. The rule and its
       * bookkeeping have to move together.
       *
       * AND SO IS A SHIP THAT LIFTED OFF. The escape resolves the raid against the
       * guns alone, so the ships are exactly as absent from its survivors as a
       * Prospector — and would be deleted by the same `?? 0`.
       */
      defenderHome[hull] = NON_COMBATANT_HULLS.includes(hull) || (escaped[hull] ?? 0) > 0
        ? standing
        : (hostOutcome.survivors[hull] ?? 0) + (homePartition.excluded[hull] ?? 0);
    }
    for (const [hull, standing] of fleetEntries(defender.ground)) {
      defenderHome[hull] = defenceDark
        ? standing
        : (hostOutcome.survivors[hull] ?? 0) + (result.defenceSalvage[hull] ?? 0);
    }
    await setUnits(tx, defender.planetId, defenderHome, 'home');
    /*
      KALICI GEMİ HASARI. Owner decision K1, 2026-09-29.

      Defender survivors keep their wounds in the home hangar. Raiders carry their
      wounds through the return leg and land without healing or automatic docking.
      Seasons predating persistent damage still do not retain new battle wounds.
    */
    const damageRule = shipDamageApplies(season.rulesetVersion);
    const attackerDamage = damageRule ? result.attackerDamage : [];
    // The whole line's, for the report; host and support wounds stay with their owners.
    const defenderDamage = damageRule ? result.defenderDamage : [];
    const defenderDock = await dockDamaged(tx, {
      planetId: defender.planetId,
      ownerPlayerId: defender.playerId,
      lots: damageRule ? [...hostOutcome.survivorDamage, ...defender.homeDamage.filter((lot) =>
        NON_COMBATANT_HULLS.includes(lot.hull) || (escaped[lot.hull] ?? 0) > 0 || !shipCanFight(lot))] : [],
      at: defender.now,
    });
    await settleStations(tx, { stations, outcomes: result.defenders, damageRule, now: defender.now });

    /**
     * Two piles, two exposures (D16).
     *
     * Storage is taken in full above the vault floor; ore still uncollected in the
     * works is taken at `COMBAT.lootBufferShare` and the vault does not reach it at
     * all. `computeLoot` reports the split precisely because this code has to debit
     * two different columns — deriving one from the other would silently overdraw
     * whichever pile happened to be smaller.
     */
    /*
      THE LIFT IS BURNED BEFORE THE RAIDER LOADS. The ships took off as the wing
      arrived, so the deuterium they flew on was gone before anything reached a hold;
      what the raider can take is what the tank held after. `resolveRaid` already
      refused the lift to a tank that could not pay it, so this never goes negative.
    */
    const exposedStock = {
      alloy: defender.alloy,
      crystal: defender.crystal,
      deuterium: defender.deuterium - liftFuel,
    };
    const exposedBuffer = {
      alloy: defender.bufferAlloy,
      crystal: defender.bufferCrystal,
      deuterium: defender.bufferDeuterium,
    };
    const vaultFloor = vaultProtects(
      defender.buildings.VAULT,
      defender.buildings.REFINERY,
      defender.buildings.EXTRACTOR,
      defender.buildings.DEUTERIUM_PLANT,
    );
    const loot = computeLoot(
      exposedStock,
      exposedBuffer,
      vaultFloor,
      result.grade,
      // The ATTACKER's holds: it is their fleet carrying it home. T8.
      fleetCargo(activeBattleFleet(result.attackerSurvivors, result.attackerRetreated), attackerTech),
      pvpBalance,
    );
    /**
     * Dense Fuel Cells is discovered by a real PvP lesson, not a counter. D94.
     * Re-price the same exposed piles with effectively unlimited cargo; if more
     * was legally available than came home, cargo capacity changed the outcome.
     * This remains true even when proportional rounding leaves one unit unused.
     */
    const uncappedLoot = computeLoot(
      exposedStock,
      exposedBuffer,
      vaultFloor,
      result.grade,
      Number.MAX_SAFE_INTEGER,
      pvpBalance,
    );
    /**
     * THE CEILING THIS WORLD COULD HAVE BEEN MADE TO GIVE UP. 2026-09-14.
     *
     * DECISIVE with the hold taken out of the question — the exact figure a probe
     * reports (`intel.ts`) and the exact denominator the recovery shield is decided
     * against. Read from the SAME pre-battle snapshot the debit below uses, because
     * it cannot be recomputed afterwards: the stores have been emptied, and the
     * vault floor and the works exposure move underneath it with every tick.
     *
     * NOT `uncappedLoot`, which is quoted at the grade the battle actually reached.
     * A PARTIAL raid is supposed to sit at half of this, and measuring it against
     * its own share would make every PARTIAL look total.
     */
    const raidableBefore = raidableStock(
      exposedStock,
      exposedBuffer,
      vaultFloor,
      'DECISIVE',
      pvpBalance,
    );
    const cargoLimited =
      uncappedLoot.alloy + uncappedLoot.crystal + uncappedLoot.deuterium
      > loot.alloy + loot.crystal + loot.deuterium;
    const shieldAbsorbed = result.rounds.reduce((sum, round) => sum + round.shieldAbsorbed, 0);

    await saveResources(tx, defender.planetId, {
      alloy: defender.alloy - loot.fromStock.alloy,
      crystal: defender.crystal - loot.fromStock.crystal,
      deuterium: exposedStock.deuterium - loot.fromStock.deuterium,
      bufferAlloy: defender.bufferAlloy - loot.fromBuffer.alloy,
      bufferCrystal: defender.bufferCrystal - loot.fromBuffer.crystal,
      bufferDeuterium: defender.bufferDeuterium - loot.fromBuffer.deuterium,
      shield: result.shieldLeft,
    });

    /**
     * AND A DEFEAT HEAVY ENOUGH BUYS THE DEFENDER SIX HOURS. Owner instruction,
     * 2026-09-14.
     *
     * HERE, INSIDE THE BATTLE'S OWN TRANSACTION, with both player rows already held
     * `FOR UPDATE` by `lockLedgers` in id order — the same rows in the same order a
     * launch takes. That is what makes "attacking and protected at once" impossible
     * rather than unlikely: a commander cannot be granted a window on one connection
     * while spending it on another.
     *
     * AFTER THE DEBIT AND BEFORE THE REPORT, so the report can carry both halves of
     * the audit trail — what the loss was measured against, and what it bought.
     */
    /*
      WHAT THE DEFENDER IS ACTUALLY OUT, IN THE TWO CURRENCIES A BATTLE SPENDS.

      The ore is what flew away; the fleet is what stopped existing. Ground defence
      rebuilds most of itself from its own wreckage (`defenceSalvage`), so the
      gross loss would price Bastions the defender still owns — the shield reads
      the PERMANENT loss, which is the same figure Dominion is scored on.
    */
    // The host's own permanent loss: a clanmate's wave dying does not shield the host.
    const fleetLost = permanentFleetCost(hostOutcome.losses, result.defenceSalvage);
    const recovery = await grantRecoveryShield(tx, {
      playerId: defender.playerId,
      planetId: defender.planetId,
      balance: pvpBalance,
      lootLost: { alloy: loot.alloy, crystal: loot.crystal, deuterium: loot.deuterium },
      fleetLost,
      now: defender.now,
    });
    const recoveryShieldUntil = recovery.until;
    /*
      A DEFEAT HEAVY ENOUGH TO EARN A SHIELD ALSO BREAKS THE COLONY. Owner instruction:
      *"kalkan verilmesine sebep olmuş kadar bir saldırı yemişse ... en az 2 tane arıza
      rastgele eklensin."*

      Keyed on `earned`, not on `until`: the shield is refused to a defender with a raid of
      their own in the air and to a server-played commander, and neither refusal made the
      blow any lighter. A capital, a colony below the gate and a world with nothing left to
      break all come back silent from `breakFaults`.

      Idempotent through `claimMission` above: a redelivered arrival never gets here, and
      the draw is seeded from the mission so a replayed resolution breaks the same things.
    */
    const colonyFaults = recovery.earned
      ? await breakFaults(tx, {
        seasonId: mission.seasonId,
        planetId: defender.planetId,
        now: defender.now,
        count: FAULT.attackFaults,
        seed: `attack:${missionId}`,
        lane: 'ATTACK',
        // Told in this battle's report below rather than as notifications. Owner decision.
        announce: false,
      })
      : [];

    const loyaltyLoss = defender.kind === 'COLONY'
      ? FAULT.battleLoyaltyLoss[result.grade]
      : 0;
    if (loyaltyLoss > 0) {
      await tx.update(planets)
        .set({ loyalty: Math.max(0, defender.loyalty - loyaltyLoss) })
        .where(eq(planets.id, defender.planetId));
      await rescheduleLoyaltyWatch(tx, {
        seasonId: mission.seasonId,
        planetId: defender.planetId,
        now: defender.now,
      });
    }

    const dominionBreakdown = scoreEligible
      ? battleDominion(
          loot.alloy + loot.crystal + loot.deuterium,
          result,
          season.rulesetVersion,
        )
      : null;
    /*
      A SUPPORTED LINE MOVES ONLY ITS HOST. Klan Savunma Desteği, owner 2026-10-02.

      The base transfer is the ordinary one. The support multiplies the HOST'S OWN fight by line
      power ÷ host power, at most ×5 — a host who loses loses ×D, one who wins gains ÷D — and
      the supporters' lost ships are added at face value, never multiplied (`defendedTransfer`,
      owner decision (b)). No supporter's ledger moves. One defender is the ordinary battle,
      booked exactly as it always was.
    */
    const supportedLine = defenderCount > 1;
    const hostPower = combatValue(defenders);
    const dominionSwing = dominionBreakdown === null
      ? 0
      : supportedLine
        ? defendedTransfer(
          dominionBreakdown.transfer,
          supportLossOf(stations, result.defenders),
          1,
          supportFactorOf(hostPower, stations),
        )
        : dominionBreakdown.transfer;
    const defenderDominionSwing = -dominionSwing;
    if (scoreEligible && !supportedLine) {
      bookBattle(
        attackerLedger,
        defenderLedger,
        loot.alloy + loot.crystal + loot.deuterium,
        result,
        season.rulesetVersion,
      );
    }
    if (scoreEligible && supportedLine) {
      applyDelta(attackerLedger, dominionSwing);
      applyDelta(defenderLedger, defenderDominionSwing);
    }
    if (
      attackerLedger.taken - attackerLedger.lost - before !== dominionSwing
      || defenderLedger.taken - defenderLedger.lost - defenderBefore !== defenderDominionSwing
    ) {
      throw new Error('Dominion ledger movement disagrees with its battle breakdown');
    }
    if (scoreEligible) {
      await saveLedger(tx, attackerLedger);
      await saveLedger(tx, defenderLedger);
      await recordClanBattleScore(tx, {
        missionId: mission.id,
        seasonId: mission.seasonId,
        attackerDelta: dominionSwing,
        defenderDelta: defenderDominionSwing,
        at: defender.now,
      });
      if (
        before !== attackerLedger.taken - attackerLedger.lost
        || defenderBefore !== defenderLedger.taken - defenderLedger.lost
      ) {
        await publishShard(tx, mission.seasonId, 'score');
      }
    }

    /**
     * PRICED HERE RATHER THAN AT THE INSERT BELOW, SO THE REPORT CAN CARRY IT.
     *
     * It is a pure function of the two loss lists, so computing it early moves
     * nothing: the debris row still uses this same figure a few lines down. What
     * it buys is a report that can say what the fight left in orbit — which is
     * the one consequence of a battle that belongs to whoever gets there first.
     *
     * AND THE COLLECTORS TAKE THEIR SHARE BEFORE IT IS ANYBODY'S. D200. The
     * attacker's surviving Garbage Collectors lift from the wreck at this instant —
     * the instant their return leg departs — and `settleWreck` hands back what is
     * left as the public field. Split the way the hulls were priced, so each
     * recovered material keeps the composition of the craft that actually died.
     */
    const totalRaw = flyingValue(result.attackerLosses) + flyingValue(result.defenderLosses);
    const made = totalRaw * DEBRIS.share;
    const share = (raw: number): number => (totalRaw > 0 ? made * (raw / totalRaw) : 0);
    const { salvage, field: wreck } = settleWreck(
      {
        alloy: share(flyingAlloy(result.attackerLosses) + flyingAlloy(result.defenderLosses)),
        crystal: share(flyingCrystal(result.attackerLosses) + flyingCrystal(result.defenderLosses)),
        deuterium: share(
          flyingDeuterium(result.attackerLosses) + flyingDeuterium(result.defenderLosses),
        ),
      },
      activeBattleFleet(result.attackerSurvivors, result.attackerRetreated),
    );
    const wreckValue = wreck ? wreck.alloy + wreck.crystal + wreck.deuterium : 0;
    const lifted = salvage.alloy + salvage.crystal + salvage.deuterium > 0;

    const [reportRow] = await tx.insert(battleReports).values({
      seasonId: mission.seasonId,
      missionId,
      attackerPlayerId: mission.ownerPlayerId,
      defenderPlayerId: defender.playerId,
      targetPlanetId: defender.planetId,
      targetKind: 'PLAYER',
      defenderCount,
      grade: result.grade,
      rounds: result.rounds,
      // Totals only: the split is for debiting the defender, not for the record.
      loot: { alloy: loot.alloy, crystal: loot.crystal, deuterium: loot.deuterium },
      attackerLosses: result.attackerLosses,
      defenderLosses: result.defenderLosses,
      // The two rosters that were on the board. Each side is shown only its own.
      attackerFleet: attackingFleet,
      // The whole line that stood — the host's and every clanmate wave's.
      defenderFleet: lineOf(stood, stations),
      defenceSalvage: result.defenceSalvage,
      attackerDamage,
      defenderDamage,
      colonyFaults,
      fleetEscape: raid.escape,
      /** Historical reports retain this field, but PvP no longer stops production. */
      disruptedMinutes: 0,
      // Below `DEBRIS.minimum` no field is written at all, so the report says
      // none rather than advertising wreckage nobody can fly out and collect.
      wreckValue,
      salvage,
      cargoLimited,
      shieldAbsorbed,
      dominionSwing,
      dominionRuleVersion: dominionBreakdown?.rulesetVersion ?? null,
      dominionLootValue: dominionBreakdown?.lootValue ?? null,
      dominionAttackerLossValue: dominionBreakdown?.attackerLossValue ?? null,
      dominionDefenderLossValue: dominionBreakdown?.defenderPermanentLossValue ?? null,
      dominionRawExchange: dominionBreakdown?.rawExchange ?? null,
      dominionEligible: scoreEligible,
      /*
        THE RECOVERY SHIELD'S AUDIT TRAIL. 2026-09-14.

        `raidableBefore` is the denominator the grant was decided against and cannot
        be recomputed from a resolved battle; `recoveryShieldUntil` is what it
        bought, or null when the thresholds were not met — or when the defender had
        a raid of their own in the air. Neither reaches the API: `readBattleReports`
        builds its payload field by field, and telling an attacker how much MORE was
        there is a disclosure the fog does not make.
      */
      raidableBefore: Math.round(raidableBefore),
      recoveryLossHours: recovery.hours,
      pvpBalance,
      recoveryShieldUntil,
      createdAt: defender.now,
    }).returning({ id: battleReports.id });
    if (!reportRow) throw new Error('battle report insert returned no row');
    await persistBattleReplay(tx, { source: { kind: 'BATTLE', id: reportRow.id }, seasonId: mission.seasonId, capture: replayCapture, result,
      context: { environment: 'PLANET', aegisCapacity: shieldHp(defender.effectiveInstruments.AEGIS ?? 0), defenceOffline: defenceDark, escape: raid.escape, control: null }, at: defender.now });
    if (supportedLine) {
      /*
        A SUPPORTED LINE KEEPS ITS OWN JOURNAL. `dominion_events` holds one attacker and
        one defender and insists the transfer is the raw exchange; this battle moved
        several defenders by a corrected transfer, so each of them is a row here and the
        season's ledger audit reads both tables.
      */
      await writeDefenderResults(tx, {
        seasonId: mission.seasonId,
        reportId: reportRow.id,
        host: {
          playerId: defender.playerId,
          outcome: hostOutcome,
          power: hostPower,
          lootLost: { alloy: loot.alloy, crystal: loot.crystal, deuterium: loot.deuterium },
        },
        stations,
        outcomes: result.defenders,
        hostDelta: scoreEligible ? defenderDominionSwing : 0,
        now: defender.now,
      });
      if (scoreEligible && dominionBreakdown) {
        await tx.insert(clanSupportDominionEvents).values([
          {
            seasonId: mission.seasonId,
            missionId,
            reportId: reportRow.id,
            playerId: mission.ownerPlayerId,
            role: 'ATTACKER' as const,
            rulesetVersion: season.rulesetVersion,
            attackerCount: 1,
            defenderCount,
            baseExchange: dominionBreakdown.transfer,
            adjustedTransfer: dominionSwing,
            delta: dominionSwing,
            createdAt: defender.now,
          },
          {
            seasonId: mission.seasonId,
            missionId,
            reportId: reportRow.id,
            playerId: defender.playerId,
            role: 'DEFENDER' as const,
            rulesetVersion: season.rulesetVersion,
            attackerCount: 1,
            defenderCount,
            baseExchange: dominionBreakdown.transfer,
            adjustedTransfer: dominionSwing,
            delta: defenderDominionSwing,
            createdAt: defender.now,
          },
        ]);
      }
      await notifySupporters(tx, {
        missionId,
        reportId: reportRow.id,
        grade: result.grade,
        hostPlanetId: defender.planetId,
        hostPlanetName: defender.name,
        stations,
        outcomes: result.defenders,
        now: defender.now,
      });
    } else {
      await tx.insert(dominionEvents).values({
        seasonId: mission.seasonId,
        missionId,
        attackerPlayerId: mission.ownerPlayerId,
        defenderPlayerId: defender.playerId,
        rulesetVersion: season.rulesetVersion,
        eligible: scoreEligible,
        lootValue: dominionBreakdown?.lootValue ?? null,
        attackerLossValue: dominionBreakdown?.attackerLossValue ?? null,
        defenderLossValue: dominionBreakdown?.defenderPermanentLossValue ?? null,
        rawExchange: dominionBreakdown?.rawExchange ?? null,
        transfer: dominionSwing,
        createdAt: defender.now,
      });
    }

    // The attacking stack is gone from the origin either way; survivors become a
    // new return mission, and the dead simply cease to exist.
    /**
     * THE WRECKAGE. D32.
     *
     * A share of every non-ground hull destroyed on BOTH sides, left at the
     * defender's coordinates for anyone to come and take. Ground units are excluded
     * because they already have `defenceSalvage` — counting them here would return
     * about 85% of a defender's losses and make a fortress profit from being
     * attacked.
     *
     * `!HULLS[id].ground` rather than `MOBILE_HULLS` membership, and the filter
     * stays that way even though a Prospector no longer defends: it is the LOSSES
     * that are priced here, and a craft that was never in the line never appears
     * in them. Narrowing this to `MOBILE_HULLS` would drop a hull the day one is
     * added that is neither ground nor attack-legal.
     *
     * WEALTH, NEVER DOMINION. Nothing here touches a ledger — wreckage was not
     * taken FROM anybody, so crediting it to the ladder would create score from
     * nothing and break the zero-sum guarantee D2 rests on.
     *
     * `wreck` is priced above the battle report, which carries the same figure —
     * after the collectors, so the field and the report name the same remainder.
     */
    let wreckFieldId: string | null = null;
    if (wreck) {
      const [row] = await tx
        .insert(debrisFields)
        .values({
          seasonId: mission.seasonId,
          planetId: defender.planetId,
          // Stored beside the anchor, so a void field and a world field are read
          // through the same three columns. D150.
          x: defender.x,
          y: defender.y,
          z: defender.z,
          missionId,
          alloy: wreck.alloy,
          crystal: wreck.crystal,
          deuterium: wreck.deuterium,
          createdAt: defender.now,
        })
        .returning({ id: debrisFields.id });
      wreckFieldId = row?.id ?? null;
    }

    // The defender's own HUD counts the window down and every disc in the galaxy
    // draws their worlds as PROTECTED, so the reads move immediately rather than on
    // the next minute's poll.
    if (recoveryShieldUntil) await publishShard(tx, mission.seasonId, 'protection');

    await clearMissionUnits(tx, mission.originPlanetId, missionId);

    if (fleetCount(result.attackerSurvivors) > 0) {
      /**
       * THE BEACON APPLIES TO THE TRIP HOME TOO. D25 said "out and back".
       *
       * `launchAttack` passes `fleetSpeedMult(origin.orbit)`; this called the
       * two-argument form, so `boost` defaulted to 1 and a raid flew out 1.3× faster
       * and came home at walking pace. The satellite costs 11,000 alloy and 3,500
       * crystal, the card copy promises the round trip, and `packages/sim` already
       * prices the return leg WITH the multiplier — so the simulator was valuing a
       * benefit the server did not deliver, which is the mirror image of the
       * standing rule that it must not price what it refuses to simulate.
       *
       * It reads the ATTACKER's orbit, which is where the beacon is. Reading the
       * mission's own origin would be wrong on a return leg: a return row is stored
       * with its two ends swapped (D28), so `originPlanetId` is the world that was
       * raided.
       */
      /*
        AND AT THE PACE IT WENT OUT. Owner decision, 2026-10-06: "Bacakların eşit yarı yarıya
        bölünmesi lazım" — a slow raid comes home as slowly as it flew, so the round trip the
        launch sheet quoted is the one flown.
      */
      const home = fleetTravelExact(
        mission.distance,
        result.attackerSurvivors,
        { boost: fleetSpeedMult(attackerOrbit), tech: attackerTech, pace: missionPaceOf(mission.pace) },
      );
      const arriveAt = addMinutes(defender.now, home);
      const [ret] = await tx
        .insert(missions)
        .values({
          // A return leg is already paid for: fuel is charged in full at the outbound launch.
          fuelPaid: 0,
          seasonId: mission.seasonId,
          kind: 'return',
          ownerPlayerId: mission.ownerPlayerId,
          originPlanetId: mission.targetPlanetId,
          targetPlanetId: mission.originPlanetId,
          fleet: result.attackerSurvivors,
          loot: { alloy: loot.alloy, crystal: loot.crystal, deuterium: loot.deuterium },
          // Beside the loot, never inside it: wreck is Wealth, not an exchange. D200.
          salvage: lifted ? salvage : null,
          // Judged on landing, not in the air. Kalıcı gemi hasarı.
          damage: attackerDamage.length > 0 ? attackerDamage : null,
          tech: mission.tech,
          distance: mission.distance,
          pace: missionPaceOf(mission.pace),
          departAt: defender.now,
          arriveAt,
          // Links safely docked loot back to the immutable D114 launch roster.
          parentMissionId: mission.id,
        })
        .returning();
      await setUnits(
        tx,
        mission.originPlanetId,
        result.attackerSurvivors,
        ret!.id,
        mission.ownerPlayerId,
      );
      await schedule(tx, {
        seasonId: mission.seasonId,
        kind: 'mission_arrival',
        refId: ret!.id,
        resolveAt: arriveAt,
      });
    }

    // A raid moves stock and destroys units on both sides, so both Wealth figures
    // are stale the moment it resolves — and Wealth gates who may attack whom.
    await recomputeWealth(tx, defender.planetId, clock.now());
    await recomputePlayerWealth(tx, mission.ownerPlayerId, clock.now());

    const [attackerIdentity, defenderIdentity] = await Promise.all([
      identityOfPlanet(tx, attackerHomeId),
      identityOfPlanet(tx, defender.planetId),
    ]);

    if (defenderIdentity) {
      await recordGalaxyEvent(tx, {
        seasonId: mission.seasonId,
        kind: 'bombardment',
        refId: missionId,
        subjectPlanetId: defender.planetId,
        payload: {
          planetName: defenderIdentity.planetName,
          commanderName: defenderIdentity.username,
        },
        occurredAt: defender.now,
      });
      if (wreckFieldId) {
        await recordGalaxyEvent(tx, {
          seasonId: mission.seasonId,
          kind: 'wreck_formed',
          refId: wreckFieldId,
          subjectPlanetId: defender.planetId,
          payload: {
            planetName: defenderIdentity.planetName,
            commanderName: defenderIdentity.username,
          },
          occurredAt: defender.now,
        });
      }
    }

    const leaderAfter = await publicDominionLeader(tx, mission.seasonId, adminPlayerIds);
    if (leaderAfter && leaderAfter.planetId !== leaderBefore?.planetId) {
      await recordGalaxyEvent(tx, {
        seasonId: mission.seasonId,
        kind: 'dominion_leader',
        refId: missionId,
        subjectPlanetId: leaderAfter.planetId,
        payload: {
          planetName: leaderAfter.planetName,
          commanderName: leaderAfter.commanderName,
        },
        occurredAt: defender.now,
      });
    }

    /**
     * BOTH SIDES ARE TOLD. D45.
     *
     * Only the defender used to be. An attacker learned the outcome of their own
     * raid when the survivors got home carrying the loot — and if there were no
     * survivors there was nothing to come home, so the single most expensive thing
     * that can happen to a player produced no notification, no stream event, and
     * therefore not even a refetch: they watched the bombardment and the screen
     * simply never changed. Measured, on a fleet annihilated by ground defence.
     *
     * The battle report has always held the detail. What was missing was anybody
     * being told it exists.
     */
    await notify(tx, {
      playerId: defender.playerId,
      kind: 'raided',
      payload: {
        ...(attackerIdentity
          ? {
              originPlanetId: attackerHomeId,
              originUsername: attackerIdentity.username,
              originPlanetName: attackerIdentity.planetName,
              ...(attackerIdentity.clanTag
                ? { originClanTag: attackerIdentity.clanTag }
                : {}),
            }
          : {}),
        grade: result.grade,
        lootAlloy: loot.alloy,
        lootCrystal: loot.crystal,
        lootDeuterium: loot.deuterium,
        unitsLost: fleetCount(hostOutcome.losses),
        // What holding the line cost them. Already in the defender's own battle
        // report, so this reveals nothing new — it lets "you repelled a raid" say
        // what the raid paid, which is the difference between a fact and a result.
        theirLosses: fleetCount(result.attackerLosses),
        // Taktik geri çekilme: the ships ran, or would have and the tank was dry.
        ...(raid.escape
          ? { escape: raid.escape.kind, escapeShips: fleetCount(raid.escape.ships) }
          : {}),
        // Kalıcı gemi hasarı: what the Repair Station did with the line's part-hit ships.
        ...dockNotice(defenderDock),
        /** Kept in the payload for older clients; new raids never stop the works. */
        disruptedMinutes: 0,
      },
      at: defender.now,
      refId: missionId,
    });

    await notify(tx, {
      playerId: mission.ownerPlayerId,
      kind: 'raid_result',
      payload: {
        grade: result.grade,
        targetPlanetId: defender.planetId,
        targetUsername: defenderIdentity?.username ?? 'someone',
        targetPlanetName: defender.name,
        ...(defenderIdentity?.clanTag ? { targetClanTag: defenderIdentity.clanTag } : {}),
        lootAlloy: loot.alloy,
        lootCrystal: loot.crystal,
        lootDeuterium: loot.deuterium,
        // Only when something was lifted: a raid with no collector reads as it always did.
        ...(lifted
          ? {
              salvageAlloy: salvage.alloy,
              salvageCrystal: salvage.crystal,
              salvageDeuterium: salvage.deuterium,
            }
          : {}),
        unitsLost: fleetCount(result.attackerLosses),
        shipsHome: fleetCount(result.attackerSurvivors),
        // Flying home damaged; the Repair Station judges them when they land.
        ...(attackerDamage.length > 0 ? { damaged: shipsIn(attackerDamage) } : {}),
        dominion: dominionSwing,
        // That the line emptied, and nothing about what it held. See `reports.ts`.
        ...(raid.escape?.kind === 'ESCAPED' ? { targetFled: true } : {}),
      },
      at: defender.now,
      refId: missionId,
    });

    // "Where did his fleet go?" — the first battle, won or lost, is what opens the
    // Telescope; being on the receiving end is what opens the Radar. Design Law #2,
    // which until now was computed and never announced to anyone.
    /**
     * AND THE CRAFT SAW THE WORLD IT REACHED. D151.
     *
     * THE CASE THE WHOLE DECISION WAS ABOUT. A commander who has just fought over
     * a world knows whose flag is on it, how developed it is and what is in its
     * orbit — and until D151 the map refused to keep any of it, so the disc went
     * on drawing a probe record from three owners ago. The defender gets nothing
     * from this: sight is bought by GOING somewhere, and being attacked tells you
     * who came, never what their home looks like.
     */
    await rememberVisitedWorld(tx, {
      observerPlayerId: mission.ownerPlayerId,
      targetPlanetId: mission.targetPlanetId,
      seasonId: mission.seasonId,
      seenAt: defender.now,
    });

    await announceUnlocks(tx, mission.ownerPlayerId, defender.now);
    await announceUnlocks(tx, defender.playerId, defender.now);
    const nothing = { alloy: 0, crystal: 0, deuterium: 0 };
    await settlePlanetHonor(tx, { source: 'WORLD', seasonId: mission.seasonId, missionId,
      hostPlanetId: defender.planetId, hostPlayerId: defender.playerId, at: defender.now, adminUsernames,
      attack: [{ id: mission.ownerPlayerId, sent: attackingFleet,
        active: partitionCombatFleet(attackingFleet, flown.damage).eligible,
        losses: result.attackerLosses, rebuilt: {}, lootLost: nothing }],
      defence: result.defenders.map(outcome => {
        const host = outcome.stackId === 'host';
        const station = host ? undefined : stations.find(row => row.wave.id === outcome.stackId);
        if (!host && !station) throw new Error('Honor defender has no authoritative station');
        return { id: host ? defender.playerId : station!.wave.senderPlayerId,
          defenceNavy: defenceNavy.get(host ? defender.playerId : station!.wave.senderPlayerId),
          sent: outcome.sent, active: outcome.sent, losses: outcome.losses,
          rebuilt: host ? result.defenceSalvage : {}, lootLost: host ? loot : nothing };
      }),
      shieldCapacity: shieldHp(defender.effectiveInstruments.AEGIS ?? 0), shieldAbsorbed: result.shieldProtectedArmed ?? 0,
    });
  });
};

/** A surviving fleet reaches home: ships rejoin the garrison, loot lands in the vault. */

/**
 * Resource value of the hulls in a fleet that are NOT ground emplacements.
 *
 * Derived from `Hull.ground` rather than from `MOBILE_HULLS`, which excludes the
 * Prospector — and a Prospector at home is part of the defence and really can be
 * destroyed. A destroyed ship is wreckage whatever it was built for; the only
 * exclusion the rule wants is the one that already has a salvage mechanism.
 */
async function settleReturn(
  tx: Tx,
  mission: typeof missions.$inferSelect,
  homePlanetId: string,
  at: Date,
  rulesetVersion: number,
  /** The world the fleet is back from. A return leg flies backwards, so by default its origin. */
  fromPlanetId: string = mission.originPlanetId,
): Promise<void> {
  // The mission's original home may have changed controller while the fleet was
  // away. Ownership follows `mission.ownerPlayerId`; delivery follows that
  // commander's still-owned world, falling back to the immutable capital.
  const storagePlanetId = homePlanetId;
  const destinationPlanetId = await safeHomePlanet(tx, mission.ownerPlayerId, homePlanetId);
  /*
    RADYASYON ON THE WAY HOME, then the landing. Plan §3.5 and D9.

    A wing coming home can lose some and land the rest — the fight wore its ships down
    unevenly — and what it carried is cut to the holds that made it, BEFORE the clan is
    dealt its share, so the clan is dealt what landed. All of it lost is all of it gone.
  */
  const dosed = await settleMissionRadiation(tx, mission, { storagePlanetId, rulesetVersion, observedAt: at });
  const flown = dosed.mission;
  await tellRadiationLoss(tx, flightWitness(flown), dosed, at);
  const returning = dosed.fleet;
  const whole = (load: Resources | null): Resources | null =>
    load === null ? null : { alloy: load.alloy, crystal: load.crystal, deuterium: deuteriumOf(load) };
  const carried = fleetCount(dosed.destroyed) > 0
    ? capLoadToSurvivors({ loot: whole(flown.loot), salvage: whole(flown.salvage) }, returning, flown.tech ?? {})
    : { loot: flown.loot, salvage: flown.salvage };
  await clearMissionUnits(tx, storagePlanetId, mission.id);
  // Nothing landed: the hold went with the last ship, and `radiation_lost` said so.
  if (fleetCount(returning) === 0 && fleetCount(dosed.destroyed) > 0) return;
  // The Repair Station judges whatever the wing carried out of its battle. Kalıcı gemi hasarı.
  const dockReport = await landShips(tx, {
    planetId: destinationPlanetId,
    ownerPlayerId: mission.ownerPlayerId,
    fleet: returning,
    damage: flown.damage,
    at,
    radiationAt: mission.arriveAt,
  });

  const landedLoot = carried.loot ? await allocateClanLoot(tx, { ...flown, loot: carried.loot }, at) : null;
  /**
   * AND THE WRECK THE COLLECTORS LIFTED, WHOLE. D200.
   *
   * Never through `allocateClanLoot`. The clan's docked share is a share of what a
   * raid took FROM a commander (D114); this was lifted off a public wreck, so it is
   * the flying commander's and lands in their store beside the loot.
   */
  const salvage = carried.salvage;
  if (landedLoot || salvage) {
    await tx
      .update(planets)
      .set({
        alloy: sql`${planets.alloy} + ${(landedLoot?.alloy ?? 0) + (salvage?.alloy ?? 0)}`,
        crystal: sql`${planets.crystal} + ${(landedLoot?.crystal ?? 0) + (salvage?.crystal ?? 0)}`,
        deuterium: sql`${planets.deuterium} + ${
          (landedLoot ? deuteriumOf(landedLoot) : 0) + (salvage ? deuteriumOf(salvage) : 0)
        }`,
      })
      .where(eq(planets.id, destinationPlanetId));
  }

  await recomputeWealth(tx, destinationPlanetId, at);

  const [planet] = await tx.select().from(planets).where(eq(planets.id, destinationPlanetId));
  if (planet?.controllerPlayerId === mission.ownerPlayerId) {
    const from = await identityOfPlanet(tx, fromPlanetId);
    await notify(tx, {
      playerId: mission.ownerPlayerId,
      kind: 'fleet_returned',
      payload: {
        // THE DISCRIMINANT. D45. Three different things come home under this one
        // kind and the client has to tell them apart before it can read a single
        // field — a mining run's payload has no `ships` in it and never did.
        trip: 'raid',
        // Turned before it struck (K8): no battle was fought, so it is not "empty-handed".
        ...(mission.recalledAt !== null ? { recalled: true } : {}),
        ships: fleetCount(returning),
        fromPlanetId,
        fromUsername: from?.username ?? null,
        fromPlanetName: from?.planetName ?? null,
        ...(from?.clanTag ? { fromClanTag: from.clanTag } : {}),
        lootAlloy: landedLoot?.alloy ?? 0,
        lootCrystal: landedLoot?.crystal ?? 0,
        lootDeuterium: landedLoot ? deuteriumOf(landedLoot) : 0,
        ...(salvage
          ? {
              salvageAlloy: salvage.alloy,
              salvageCrystal: salvage.crystal,
              salvageDeuterium: deuteriumOf(salvage),
            }
          : {}),
        ...dockNotice(dockReport),
      },
      at,
      refId: mission.id,
    });
  }
}

/* ── radar warning ──────────────────────────────────────────── */

/**
 * "Incoming fleet · lands in 9 min."
 *
 * The highest-value notification in the game: it converts a passive loss into an
 * active decision, because the player can still spend their stock, launch their
 * own fleet out, or stand and fight.
 *
 * THE DEFENDER'S RADAR IS READ HERE, AT THE MOMENT OF FIRING. D45.
 *
 * It used to be read at launch and frozen into the event's payload, which broke
 * the ladder in both directions:
 *
 *   · A defender with no radar had no event scheduled at all, so installing one
 *     while a fleet was in the air bought nothing — while `pendingThreads`, which
 *     reads the live level, put "inbound fleet" on their strip. One fact, two
 *     surfaces, opposite answers.
 *   · A defender who went Radar 3 → 5 mid-flight was warned with an L3 payload:
 *     no size, no composition, for a rung they had already paid for.
 *
 * Every raid now schedules one warning at the widest crossing any radar could
 * catch it at, and this handler hops down `RADAR_RANGES` until the reach the
 * defender has actually earned matches where the fleet actually is. D9 is
 * untouched: the warning still fires when the fleet crosses in, never at launch,
 * and a wider reach can never be bought retroactively — a radar installed with the
 * fleet already four minutes out warns at four minutes.
 *
 * D49 TURNED THE RUNGS FROM MINUTES INTO DISTANCES. The conversion back to a
 * warning instant uses the exact visual leg, including surface departure and
 * orbital arrival, because that is the only way the drawn shell and alert agree.
 */
export const onRadarWarning: Handler = async ({ db, clock }, event) => {
  const missionId = event.refId;
  if (!missionId) throw new Error('radar_warning without refId');

  await db.transaction(async (tx) => {
    const [mission] = await tx.select().from(missions).where(eq(missions.id, missionId));
    if (!mission) { await warnRadiationBombById(tx, missionId, clock.now()); return; }
    // Nothing to warn about if it already landed or was somehow cancelled.
    if (mission.status !== 'in_flight') return;
    const [joint] = mission.kind === 'clan_war'
      ? await tx
          .select({ leg: clanWarMissions.leg, clanTag: clanWarOperations.clanTag })
          .from(clanWarMissions)
          .innerJoin(clanWarOperations, eq(clanWarOperations.id, clanWarMissions.operationId))
          .where(eq(clanWarMissions.missionId, mission.id))
          .limit(1)
      : [];
    if (!isHostileMission(mission, joint?.leg)) return;

    const now = clock.now();
    const remaining = (mission.arriveAt.getTime() - now.getTime()) / 60_000;
    // Already over the target: the engagement window keeps the mission in flight
    // for ten more seconds, and a warning that arrives with the fleet is noise.
    if (remaining <= 0) return;

    const [target] = await tx.select().from(planets).where(eq(planets.id, mission.targetPlanetId));
    if (!target) return;

    const [[origin], coreRows, levels] = await Promise.all([
      tx.select().from(planets).where(eq(planets.id, mission.originPlanetId)),
      tx.select({ planetId: buildings.planetId, level: buildings.level })
        .from(buildings)
        .where(and(
          inArray(buildings.planetId, [mission.originPlanetId, mission.targetPlanetId]),
          eq(buildings.type, 'CORE'),
        )),
      instrumentLevels(tx, [target.id]),
    ]);
    if (!origin) return;
    const radarLevel = levelOf(levels, target.id, 'RADAR');
    const coreByPlanet = new Map(coreRows.map((row) => [row.planetId, row.level]));
    /**
     * The whole leg, so a reach in units can be turned into minutes of notice.
     *
     * The endpoints and current public Core tiers define the same shortened leg
     * the client draws. The warning fires when the visible fleet crosses the shell.
     */
    const oneWay = (mission.arriveAt.getTime() - mission.departAt.getTime()) / 60_000;
    const leg = {
      from: { x: origin.x, y: origin.y, z: origin.z },
      to: { x: target.x, y: target.y, z: target.z },
      originCoreLevel: coreByPlanet.get(origin.id) ?? 1,
      targetCoreLevel: coreByPlanet.get(target.id) ?? 1,
      oneWayMinutes: oneWay,
    };
    const lead = inboundRadarLead(radarRange(radarLevel), leg);

    /**
     * Not yet — or never.
     *
     * `TOLERANCE` absorbs the sub-second gap between the instant this was
     * scheduled for and the instant the worker actually claimed it. Without it a
     * check armed for `arriveAt − 12` that fires 40 ms late reads 11.999 minutes
     * remaining against a 12-minute lead, decides the defender has not earned it,
     * and silently demotes a Radar 5 warning to the 8-minute rung.
     */
    if (lead <= 0 || remaining > lead + LEAD_TOLERANCE) {
      const next = nextInboundRadarCheck(remaining, leg);
      if (next !== null) {
        await schedule(tx, {
          seasonId: mission.seasonId,
          kind: 'radar_warning',
          refId: missionId,
          resolveAt: addMinutes(mission.arriveAt, -inboundRadarLead(next, leg)),
        });
      }
      return;
    }

    if (!target.controllerPlayerId) return;
    /*
      AND NEVER BOTH THINGS AT ONCE. T10.

      The interception resolves first and closes the mission, so by the time this
      runs a destroyed weapon is no longer `in_flight` — but redelivery can bring
      this handler back with a stale row in hand. Telling a defender that something
      is coming, beside the news that it is already wreckage, is the interface
      contradicting itself at the one moment it matters most.
    */
    const [live] = await tx
      .select({ status: missions.status })
      .from(missions)
      .where(eq(missions.id, missionId));
    if (live?.status !== 'in_flight') return;
    await notify(tx, {
      playerId: target.controllerPlayerId,
      kind: mission.kind === 'death_star' ? 'strategic_incoming' : 'incoming_fleet',
      payload: {
        /**
         * THE INSTANT, not only the countdown. D39, applied to a notification.
         *
         * `etaMinutes` is measured from the moment this row was written, so a
         * notification read an hour later still claimed "ETA 12 min" — a live
         * countdown frozen at the moment it stopped being true. The client reads
         * `arriveAt` against its own clock and puts the line into the past tense
         * once the fleet has landed. The defender already has this instant on
         * their pending strip; the radar ladder sells whether and how early you
         * are warned, never the precision of the clock.
         */
        arriveAt: mission.arriveAt.toISOString(),
        etaMinutes: Math.max(0, Math.round(remaining)),
        /**
         * WHICH OF THE DEFENDER'S WORLDS IT IS AIMED AT.
         *
         * Not a radar product — the radar ladder sells the ATTACKER's side, and
         * this is the recipient's own world. It was missing, so a commander with
         * four worlds got "incoming, twelve minutes" and no way to know where to
         * move the garrison. The pending strip carries the same fact.
         */
        targetPlanetName: target.name,
        // L4 buys a coarse mass band. Exact composition (and therefore any exact
        // count derivable from it) begins at L5.
        ...(radarLevel >= 4 ? { mass: massClass(mission.fleet) } : {}),
        // A NAME, never the id. Every other L5 reveal in the game sends the
        // planet's name (`readRadarLog`); this one sent a raw uuid, which is why
        // nothing ever displayed it and L5 read exactly like L4.
        ...(radarRevealsOrigin(radarLevel)
          ? {
              fleet: mission.fleet,
              ...(joint?.leg === 'COMBINED_ATTACK'
                ? { originUsername: 'Klan Filosu', originClanTag: joint.clanTag }
                : await identityOfPlanet(tx, mission.originPlanetId).then((origin) =>
                    origin
                      ? {
                          originPlanetId: mission.originPlanetId,
                          originUsername: origin.username,
                          originPlanetName: origin.planetName,
                          ...(origin.clanTag ? { originClanTag: origin.clanTag } : {}),
                        }
                      : {},
                  )),
            }
          : {}),
      },
      at: now,
      refId: missionId,
    });
  });
};


/**
 * A squadron meets its rock. D19.
 *
 * The whole claim happens inside one transaction under a lock on the claim row,
 * which is what makes the race honest: two squadrons landing in the same second
 * are serialised, and the second reads a total that already includes the first.
 */
export const onMiningArrival: Handler = async ({ db }, event) => {
  const runId = event.refId;
  if (!runId) throw new Error('mining_arrival without refId');
  await db.transaction(async (tx) => {
    await lockSeason(tx, event.seasonId);
    // Replay the meeting at the instant the queue promised, not when a delayed
    // worker happened to wake up. `resolveMiningArrival` derives ore decay,
    // claim timestamps and the whole return leg from this value; using wall time
    // here charged every minute of server downtime to the player's flight.
    await resolveMiningArrival(tx, runId, event.resolveAt);
  });
};

/** A squadron gets home and unloads into storage. */
export const onMiningReturn: Handler = async ({ db, clock }, event) => {
  const runId = event.refId;
  if (!runId) throw new Error('mining_return without refId');
  await db.transaction(async (tx) => {
    await lockSeason(tx, event.seasonId);
    const delivered = await resolveMiningReturn(tx, runId, clock);
    if (!delivered) return; // already settled by another worker

    const [run] = await tx.select().from(miningRuns).where(eq(miningRuns.id, runId));
    if (!run) return;
    // Where it came down, which is not always where it left (`landRunLocked`).
    if (delivered.planetId === null || delivered.playerId === null) return;
    await recomputeWealth(tx, delivered.planetId, clock.now());
    /**
     * Reuses `fleet_returned` rather than inventing a kind: from the player's side
     * this IS craft coming home with cargo.
     *
     * IT CARRIES `trip`, AND THAT IS NOT COSMETIC. D45. This payload named its
     * discriminant `kind`, which collided with the notification's own `kind`, and
     * it shared none of its fields with the raid payload the client parsed. So the
     * parse failed on every single mining and harvest return and the client fell
     * back to "Your fleet is home." — no ore, no waste, nothing. A drill flew for
     * forty minutes and reported a sentence.
     *
     * `wasted` is the part that matters most and the part that had never once been
     * displayed: ore mined and then thrown away because the works were already
     * full is exactly the lesson D31 exists to teach, and it was being taught in
     * silence.
     */
    await notify(tx, {
      playerId: delivered.playerId,
      kind: 'fleet_returned',
      payload: {
        trip: run.recalledAt !== null
          ? 'mining_recalled'
          : run.debrisFieldId === null ? 'mining' : 'harvest',
        craft: delivered.craft,
        alloy: Math.round(delivered.delivered.alloy),
        crystal: Math.round(delivered.delivered.crystal),
        deuterium: Math.round(delivered.delivered.deuterium),
        wastedAlloy: Math.round(delivered.wasted.alloy),
        wastedCrystal: Math.round(delivered.wasted.crystal),
        wastedDeuterium: Math.round(delivered.wasted.deuterium),
      },
      at: clock.now(),
      refId: runId,
    });
  });
};

/** Publish an act at its scheduled instant, even if a worker claims it slightly late. */
export const onSeasonAct: Handler = async ({ db }, event) => {
  const act = SEASON.actBoundaries.find(
    (candidate) => event.payload?.act === candidate.id,
  );
  if (!act || event.refId !== event.seasonId) throw new Error('season_act has invalid input');
  await db.transaction(async (tx) => {
    await lockSeason(tx, event.seasonId);
    await recordGalaxyEvent(tx, {
      seasonId: event.seasonId,
      kind: 'season_act',
      refId: `${event.seasonId}:${act.id}`,
      subjectPlanetId: null,
      payload: { act: act.id },
      occurredAt: event.resolveAt,
    });
  });
};

/* ── season freeze ─────────────────────────────────────────── */

/** Freeze one galaxy and preserve the identity/story that survives its world. D85. */
async function freezeSeason(
  { db, clock, adminUsernames = new Set() }: HandlerContext,
  seasonId: string,
  event: EventRow | null,
): Promise<void> {
  await db.transaction(async (tx) => {
    const [season] = await tx
      .select()
      .from(seasons)
      .where(eq(seasons.id, seasonId))
      .for('update');
    if (!season || season.status === 'frozen' || season.status === 'wiped') return;
    if (season.status !== 'live') throw new Error(`season ${seasonId} is ${season.status}`);
    if (event !== null && clock.now().getTime() < season.endsAt.getTime()) {
      throw new Error(`season_end for ${seasonId} fired before endsAt`);
    }
    const [seasonShard] = await tx
      .select({ role: shards.role })
      .from(shards)
      .where(eq(shards.id, season.shardId))
      .limit(1);
    if (!seasonShard) throw new Error(`season ${seasonId} has no shard`);

    if (event !== null) {
      // Recovery guard for pre-D85 rows and same-instant worker ordering. Delete
      // this processing event and replace it atomically; EventWorker's later
      // `complete()` update simply finds no old row.
      const [[missionCount], [miningCount], [buildCount], [strategicCount], [researchCount], [pirateCount], [tradeCount], [convoyCount], [clanWarCount], [supportCount], [signalCount]] = await Promise.all([
      tx
        .select({ n: sql<number>`count(*)::int` })
        .from(missions)
        .where(and(eq(missions.seasonId, seasonId), eq(missions.status, 'in_flight'))),
      tx
        .select({ n: sql<number>`count(*)::int` })
        .from(miningRuns)
        .where(and(eq(miningRuns.seasonId, seasonId), ne(miningRuns.status, 'done'))),
      tx
        .select({ n: sql<number>`count(*)::int` })
        .from(buildOrders)
        .innerJoin(planets, eq(planets.id, buildOrders.planetId))
        .where(and(eq(planets.seasonId, seasonId), eq(buildOrders.status, 'BUILDING'))),
      tx
        .select({ n: sql<number>`count(*)::int` })
        .from(strategicAssets)
        .innerJoin(planets, eq(planets.id, strategicAssets.planetId))
        .where(and(
          eq(planets.seasonId, seasonId),
          inArray(strategicAssets.status, ['BUILDING', 'PAUSED']),
        )),
      tx.select({ n: sql<number>`count(*)::int` }).from(researchOrders)
        .innerJoin(players, eq(players.id, researchOrders.playerId))
        .where(and(eq(players.seasonId, seasonId), eq(researchOrders.status, 'BUILDING'))),
      tx.select({ n: sql<number>`count(*)::int` }).from(pirateRaids)
        .where(and(eq(pirateRaids.seasonId, seasonId), ne(pirateRaids.status, 'done'))),
      tx.select({ n: sql<number>`count(*)::int` }).from(tradeRuns)
        .where(and(eq(tradeRuns.seasonId, seasonId), ne(tradeRuns.status, 'done'))),
      tx.select({ n: sql<number>`count(*)::int` }).from(intergalacticConvoyRuns)
        .where(and(
          eq(intergalacticConvoyRuns.seasonId, seasonId),
          ne(intergalacticConvoyRuns.status, 'done'),
        )),
      tx.select({ n: sql<number>`count(*)::int` }).from(clanWarContributions)
        .where(and(
          eq(clanWarContributions.seasonId, seasonId),
          inArray(clanWarContributions.status,
            ['OUTBOUND', 'STAGED', 'RECALL_ORDERED', 'IN_BATTLE', 'RETURNING']),
        )),
      // A clan support wave still out — its stay is clipped to come home before the end.
      tx.select({ n: sql<number>`count(*)::int` }).from(clanSupportWaves)
        .where(and(
          eq(clanSupportWaves.seasonId, seasonId),
          inArray(clanSupportWaves.status, ['OUTBOUND', 'STATIONED', 'RETURNING']),
        )),
      tx.select({ n: sql<number>`count(*)::int` }).from(unknownSignals)
        .where(and(eq(unknownSignals.seasonId, seasonId), inArray(unknownSignals.status, ['outbound', 'returning', 'recalled']))),
      ]);
      if (
        (missionCount?.n ?? 0) > 0
        || (miningCount?.n ?? 0) > 0
        || (buildCount?.n ?? 0) > 0
        || (strategicCount?.n ?? 0) > 0
        || (researchCount?.n ?? 0) > 0
        || (pirateCount?.n ?? 0) > 0
        || (tradeCount?.n ?? 0) > 0
        || (convoyCount?.n ?? 0) > 0
        || (clanWarCount?.n ?? 0) > 0
        || (supportCount?.n ?? 0) > 0
        || (signalCount?.n ?? 0) > 0
      ) {
        await tx.delete(scheduledEvents).where(eq(scheduledEvents.id, event.id));
        await schedule(tx, {
          seasonId,
          kind: 'season_end',
          refId: seasonId,
          resolveAt: new Date(clock.now().getTime() + 1_000),
        });
        return;
      }
    }

    const capturedThrough = event === null
      ? new Date(Math.min(clock.now().getTime(), season.endsAt.getTime()))
      : season.endsAt;
    await closeSeasonRadiationBombs(tx, seasonId, capturedThrough);
    await closeSeasonMonuments(tx, { seasonId, cutoff: capturedThrough, adminUsernames: [...adminUsernames] });
    const ownedWorlds = await tx
      .select({ id: planets.id })
      .from(planets)
      .where(and(eq(planets.seasonId, seasonId), isNotNull(planets.controllerPlayerId)));
    const boundaryClock: Clock = { now: () => capturedThrough };
    for (const world of ownedWorlds) {
      await loadLocked(tx, world.id, boundaryClock, { requireLive: false });
    }

    const allRoster = await tx
      .select({
        playerId: players.id,
        accountId: players.accountId,
        joinedAt: players.joinedAt,
        taken: players.dominionTaken,
        lost: players.dominionLost,
        commanderName: accounts.displayName,
        countryCode: accounts.countryCode,
        planetName: planets.name,
      })
      .from(players)
      .innerJoin(accounts, eq(players.accountId, accounts.id))
      .innerJoin(
        planets,
        and(eq(planets.controllerPlayerId, players.id), eq(planets.kind, 'CAPITAL')),
      )
      .where(eq(players.seasonId, seasonId));
    const adminPlayerIds = await adminPlayerIdsInSeason(tx, seasonId, adminUsernames);
    const roster = allRoster.filter((player) => !adminPlayerIds.has(player.playerId));
    const cycleSeasons = tx.select({ id: seasons.id }).from(seasons).where(eq(seasons.cycleId, season.cycleId));
    const [
      scoreEvents,
      jointWarEvents,
      reports,
      supportShares,
      impacts,
      clanRows,
      clanEvents,
      membershipRows,
      telemetryRows,
      telemetrySegments,
      miningRows,
      convoyRows,
      botRows,
      chronicleRows,
      worldRows,
      monumentShares,
    ] = await Promise.all([
      tx.select({
        attackerPlayerId: dominionEvents.attackerPlayerId,
        defenderPlayerId: dominionEvents.defenderPlayerId,
        dominionSwing: dominionEvents.transfer,
        dominionRuleVersion: dominionEvents.rulesetVersion,
        dominionLootValue: dominionEvents.lootValue,
        dominionAttackerLossValue: dominionEvents.attackerLossValue,
        dominionDefenderLossValue: dominionEvents.defenderLossValue,
        dominionRawExchange: dominionEvents.rawExchange,
        dominionEligible: dominionEvents.eligible,
      }).from(dominionEvents).where(inArray(dominionEvents.seasonId, cycleSeasons)),
      tx.select({ playerId: clanWarDominionEvents.playerId, delta: clanWarDominionEvents.delta })
        .from(clanWarDominionEvents).where(inArray(clanWarDominionEvents.seasonId, cycleSeasons))
        // Klan Savunma Desteği: a supported raid's per-commander journal, never in `dominion_events`.
        .then(async (joint) => [
          ...joint,
          ...await tx.select({ playerId: clanSupportDominionEvents.playerId, delta: clanSupportDominionEvents.delta })
            .from(clanSupportDominionEvents).where(inArray(clanSupportDominionEvents.seasonId, cycleSeasons)),
          ...await tx.select({ playerId: monumentBattleParticipants.playerId, delta: monumentBattleParticipants.dominionDelta })
            .from(monumentBattleParticipants).where(inArray(monumentBattleParticipants.seasonId, cycleSeasons)),
        ]),
      tx.select().from(battleReports).where(inArray(battleReports.seasonId, cycleSeasons)),
      tx.select({
        reportId: clanSupportBattleResults.reportId,
        playerId: clanSupportBattleResults.playerId,
        role: clanSupportBattleResults.role,
        power: clanSupportBattleResults.power,
        losses: clanSupportBattleResults.losses,
      }).from(clanSupportBattleResults).where(inArray(clanSupportBattleResults.seasonId, cycleSeasons)),
      tx.select().from(strategicImpacts).where(inArray(strategicImpacts.seasonId, cycleSeasons)),
      tx.select({
        id: clans.id,
        name: clans.name,
        tag: clans.tag,
        taken: clans.dominionTaken,
        lost: clans.dominionLost,
        createdAt: clans.createdAt,
      }).from(clans).where(and(eq(clans.seasonId, seasonId), isNull(clans.disbandedAt))),
      tx.select({
        clanId: clanScoreEvents.clanId,
        dominionDelta: clanScoreEvents.dominionDelta,
      }).from(clanScoreEvents).where(eq(clanScoreEvents.seasonId, seasonId)),
      tx.select({ playerId: clanMemberships.playerId, clanId: clanMemberships.clanId })
        .from(clanMemberships)
        .where(and(eq(clanMemberships.seasonId, seasonId), isNull(clanMemberships.leftAt))),
      tx.select({
        playerId: planets.statsOwnerPlayerId,
        telemetry: planets.seasonTelemetry,
      }).from(planets).where(and(
        inArray(planets.seasonId, cycleSeasons),
        isNotNull(planets.statsOwnerPlayerId),
      )),
      tx.select({
        playerId: seasonTelemetrySegments.playerId,
        telemetry: seasonTelemetrySegments.telemetry,
      }).from(seasonTelemetrySegments).where(inArray(
        seasonTelemetrySegments.seasonId,
        cycleSeasons,
      )),
      tx.select().from(miningRuns).where(inArray(miningRuns.seasonId, cycleSeasons)),
      tx.select().from(intergalacticConvoyRuns)
        .where(inArray(intergalacticConvoyRuns.seasonId, cycleSeasons)),
      tx.select({ accountId: botProfiles.accountId }).from(botProfiles),
      tx.select({
        seasonId: galaxyEvents.seasonId,
        kind: galaxyEvents.kind,
        refId: galaxyEvents.refId,
        subjectPlanetId: galaxyEvents.subjectPlanetId,
        payload: galaxyEvents.payload,
      }).from(galaxyEvents).where(eq(galaxyEvents.seasonId, seasonId)),
      tx.select({ id: planets.id, name: planets.name })
        .from(planets)
        .where(eq(planets.seasonId, seasonId)),
      tx.select({ participant: monumentBattleParticipants, battle: monumentBattles }).from(monumentBattleParticipants)
        .innerJoin(monumentBattles, eq(monumentBattleParticipants.battleId, monumentBattles.id))
        .where(inArray(monumentBattleParticipants.seasonId, cycleSeasons)),
    ]);
    assertDominionLedgers(roster, scoreEvents, season.rulesetVersion, jointWarEvents);
    assertClanDominionLedgers(
      clanRows.map((clan) => ({ clanId: clan.id, taken: clan.taken, lost: clan.lost })),
      clanEvents,
      season.rulesetVersion,
    );
    const identity = new Map(allRoster.map((row) => [row.playerId, row]));
    const ranked = [...roster].sort((a, b) => {
      const left = dominionScore(a.taken, a.lost);
      const right = dominionScore(b.taken, b.lost);
      return left === right
        ? a.joinedAt.getTime() - b.joinedAt.getTime() || a.playerId.localeCompare(b.playerId)
        : right > left ? 1 : -1;
    });
    const rankedClans = [...clanRows].sort((a, b) => {
      const left = dominionScore(a.taken, a.lost);
      const right = dominionScore(b.taken, b.lost);
      return left === right
        ? a.createdAt.getTime() - b.createdAt.getTime() || a.id.localeCompare(b.id)
        : right > left ? 1 : -1;
    });
    const clanRecapById = new Map(rankedClans.map((clan, index) => [clan.id, {
      name: clan.name,
      tag: clan.tag,
      finalRank: index + 1,
      dominion: dominionScore(clan.taken, clan.lost),
      topThree: index < 3,
    }]));
    const clanIdByPlayer = new Map(membershipRows.map((membership) => [
      membership.playerId,
      membership.clanId,
    ]));
    const botAccountIds = new Set(botRows.map((bot) => bot.accountId));
    const honorRanks = await sealHonor(tx, { seasonId, at: capturedThrough,
      humanPlayerIds: roster.filter(player => !botAccountIds.has(player.accountId)).map(player => player.playerId) });
    const honorByPlayer = new Map(honorRanks?.map(row => [row.actor, row]) ?? []);
    /*
      THE SEASON'S ROWS, INDEXED BY COMMANDER ONCE INSTEAD OF RESCANNED PER HEAD.
      2026-09-15.

      Every figure below is built inside `ranked.map`, so a table read here is
      walked once per commander. That is affordable for battle reports — a season
      has thousands — and it is not for `mining_runs`, which is one row per drill
      launched by anybody all season and is read across the whole CYCLE: at 300
      seats the scan is quadratic in the two largest tables the freeze touches,
      inside the one transaction that holds `seasons FOR UPDATE` and every planet
      lock in the galaxy. The freeze is already the longest transaction the worker
      runs; it must not also be the one that grows with the square of the roster.

      Indexing changes no figure: the filters below are equality on the owner plus
      the same per-row conditions, and a row with no owner belonged to nobody.
    */
    const byPlayer = <T>(rows: readonly T[], owner: (row: T) => string | null): Map<string, T[]> => {
      const grouped = new Map<string, T[]>();
      for (const row of rows) {
        const id = owner(row);
        if (id === null) continue;
        const bucket = grouped.get(id);
        if (bucket) bucket.push(row);
        else grouped.set(id, [row]);
      }
      return grouped;
    };
    // The live counters and the closed hand-over segments are one list per
    // commander; freeze reads them the same way and must not join them per head.
    const telemetryByPlayer = byPlayer(
      [...telemetryRows, ...telemetrySegments],
      (row) => row.playerId,
    );
    const miningByPlayer = byPlayer(miningRows, (run) => run.ownerPlayerId);
    const convoyByPlayer = byPlayer(convoyRows, (run) => run.ownerPlayerId);
    const strikesTakenBy = byPlayer(impacts, (impact) => impact.defenderPlayerId);
    const supportSharesByPlayer = byPlayer(supportShares, (row) => row.playerId);
    const monumentLines = byPlayer(monumentShares, (row) => row.battle.id);
    // A neutral garrison has no personal defence row. Operator PvP still has one.
    const monumentPvp = monumentShares.filter((row) => monumentLines.get(row.battle.id)?.some((entry) => entry.participant.side === 'DEFENCE'));
    const monumentsByPlayer = byPlayer(monumentPvp, (row) => row.participant.playerId);
    const linePowerByReport = new Map<string, number>();
    for (const row of supportShares) {
      linePowerByReport.set(row.reportId, (linePowerByReport.get(row.reportId) ?? 0) + row.power);
    }
    const [cycle] = await tx
      .select({ rewardProgramVersion: seasonCycles.rewardProgramVersion })
      .from(seasonCycles)
      .where(eq(seasonCycles.id, season.cycleId))
      .limit(1);
    const rewardProgram = seasonRankRewardProgram(cycle?.rewardProgramVersion ?? 0);

    const [shard] = await tx.select().from(shards).where(eq(shards.id, season.shardId));
    const shardLabel = shard?.name === ''
      ? shard.code
      : (shard?.name ?? shard?.code ?? 'the galaxy');
    const values = ranked.map((player, index) => {
      /*
        KLAN SAVUNMA DESTEĞİ. A supported report's `defender_*` columns are the whole line;
        each defender — the host and every supporter — counts their OWN losses and the
        share of the raider's losses their power brought (the K6 weight), and a supporter
        counts the battle as a defence of their own.
      */
      const mySupportShares = new Map(
        (supportSharesByPlayer.get(player.playerId) ?? []).map((row) => [row.reportId, row]),
      );
      const mine = reports.filter((report) => report.targetKind === 'PLAYER' && (
        report.attackerPlayerId === player.playerId || report.defenderPlayerId === player.playerId
        || mySupportShares.has(report.id)
      ));
      const myMonuments = monumentsByPlayer.get(player.playerId) ?? [];
      const defenderPart = (report: (typeof reports)[number]) => {
        const share = mySupportShares.get(report.id);
        if (report.defenderCount <= 1 || !share) {
          return { losses: report.defenderLosses, dealt: fleetValue(report.attackerLosses) };
        }
        const line = linePowerByReport.get(report.id) ?? 0;
        const weight = line > 0 ? share.power / line : (share.role === 'HOST' ? 1 : 0);
        return { losses: share.losses, dealt: fleetValue(report.attackerLosses) * weight };
      };
      const rivalCounts = new Map<string, number>();
      let damageDealt = 0;
      let damageTaken = 0;
      let attacks = 0;
      let defences = 0;
      let biggest: { value: number; opponentName: string } | null = null;
      for (const report of mine) {
        const attacking = report.attackerPlayerId === player.playerId;
        const opponentId = attacking ? report.defenderPlayerId : report.attackerPlayerId;
        if (opponentId === null) continue;
        rivalCounts.set(opponentId, (rivalCounts.get(opponentId) ?? 0) + 1);
        if (attacking) {
          attacks++;
          damageDealt += fleetValue(report.defenderLosses);
          damageTaken += fleetValue(report.attackerLosses);
          const value = report.loot.alloy + report.loot.crystal + deuteriumOf(report.loot);
          const opponentName = identity.get(opponentId)?.commanderName ?? 'Unknown commander';
          if (!biggest || value > biggest.value) biggest = { value, opponentName };
        } else {
          defences++;
          const part = defenderPart(report);
          damageDealt += part.dealt;
          damageTaken += fleetValue(part.losses);
        }
      }
      for (const impact of impacts) {
        if (impact.attackerPlayerId === player.playerId) damageDealt += impact.damage;
        if (impact.defenderPlayerId === player.playerId) damageTaken += impact.damage;
      }
      for (const { participant, battle } of myMonuments) {
        const line = monumentLines.get(battle.id) ?? [];
        const ownSide = line.filter((row) => row.participant.side === participant.side);
        const enemies = line.filter((row) => row.participant.side !== participant.side);
        const sidePower = ownSide.reduce((sum, row) => sum + combatValue(row.participant.fleet), 0);
        const sideValue = ownSide.reduce((sum, row) => sum + fleetValue(row.participant.fleet), 0);
        const weight = sidePower > 0 ? combatValue(participant.fleet) / sidePower
          : sideValue > 0 ? fleetValue(participant.fleet) / sideValue : 0;
        damageDealt += enemies.reduce((sum, row) => sum + fleetValue(row.participant.losses), 0) * weight;
        damageTaken += fleetValue(participant.losses);
        if (participant.side === 'ATTACK') attacks++;
        else defences++;
        for (const enemy of enemies) rivalCounts.set(enemy.participant.playerId, (rivalCounts.get(enemy.participant.playerId) ?? 0) + 1);
        if (participant.side === 'ATTACK' && (!biggest || participant.lootDeuterium > biggest.value)) {
          const opponentId = enemies.map((row) => row.participant.playerId).sort()[0];
          biggest = { value: participant.lootDeuterium, opponentName: opponentId === undefined ? 'Unknown commander'
            : identity.get(opponentId)?.commanderName ?? 'Unknown commander' };
        }
      }
      const rivalEntry = [...rivalCounts.entries()]
        .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))[0];
      const rival = rivalEntry
        ? { commanderName: identity.get(rivalEntry[0])?.commanderName ?? 'Unknown commander', battles: rivalEntry[1] }
        : null;
      const dominion = dominionScore(player.taken, player.lost);
      const finalRank = index + 1;
      const honorResult = honorByPlayer.get(player.playerId);
      const primaryRank = honorResult?.rank ?? finalRank;
      const meritsTitle = honorRanks === null || (honorResult?.honor ?? 0) > 0;
      const title = meritsTitle && primaryRank === 1
        ? `Sovereign of ${shardLabel}`
        : meritsTitle && primaryRank <= 3 ? 'Vanguard'
          : (honorRanks === null ? dominion : honorResult?.honor ?? 0) > 0 ? 'Conqueror' : 'Commander';
      const playerClanId = clanIdByPlayer.get(player.playerId);
      const clan = playerClanId ? clanRecapById.get(playerClanId) ?? null : null;
      const stats: SeasonStatsSnapshot = emptySeasonStats();
      if (season.statsVersion !== 1) {
        stats.coverage = { kind: 'partial', reason: 'TELEMETRY_CUTOVER' };
      }
      {
        stats.competition.battles = mine.length + myMonuments.length;
        stats.competition.attacks = attacks;
        stats.competition.defences = defences;
        stats.competition.damageDealt = damageDealt;
        stats.competition.damageTaken = damageTaken;
        for (const report of mine) {
          const attacking = report.attackerPlayerId === player.playerId;
          if (attacking) {
            stats.competition.playerLoot.alloy += report.loot.alloy;
            stats.competition.playerLoot.crystal += report.loot.crystal;
            stats.competition.playerLoot.deuterium += deuteriumOf(report.loot);
          }
          const losses = attacking ? report.attackerLosses : defenderPart(report).losses;
          for (const [hull, count] of fleetEntries(losses)) {
            if (HULLS[hull].ground || count <= 0) continue;
            stats.competition.shipsLostByHull[hull] =
              (stats.competition.shipsLostByHull[hull] ?? 0) + count;
            stats.competition.shipsLost += count;
          }
        }
        for (const impact of strikesTakenBy.get(player.playerId) ?? []) {
          for (const [hull, count] of fleetEntries(impact.destroyedFleet)) {
            if (HULLS[hull].ground || count <= 0) continue;
            stats.competition.shipsLostByHull[hull] =
              (stats.competition.shipsLostByHull[hull] ?? 0) + count;
            stats.competition.shipsLost += count;
          }
        }
        for (const { participant } of myMonuments) {
          stats.competition.playerLoot.deuterium += participant.lootDeuterium;
          for (const [hull, count] of fleetEntries(participant.losses)) {
            if (HULLS[hull].ground || count <= 0) continue;
            stats.competition.shipsLostByHull[hull] = (stats.competition.shipsLostByHull[hull] ?? 0) + count;
            stats.competition.shipsLost += count;
          }
        }
        for (const row of telemetryByPlayer.get(player.playerId) ?? []) {
          stats.economy.produced.alloy += row.telemetry.produced.alloy;
          stats.economy.produced.crystal += row.telemetry.produced.crystal;
          stats.economy.produced.deuterium += row.telemetry.produced.deuterium;
          stats.economy.productiveSeconds += row.telemetry.productiveSeconds;
          for (const [hull, count] of fleetEntries(row.telemetry.shipsBuilt)) {
            if (HULLS[hull].ground || count <= 0) continue;
            stats.competition.shipsBuiltByHull[hull] =
              (stats.competition.shipsBuiltByHull[hull] ?? 0) + count;
            stats.competition.shipsBuilt += count;
          }
        }
        for (const run of miningByPlayer.get(player.playerId) ?? []) {
          if (run.targetKind !== 'asteroid' || run.homeAt === null) continue;
          stats.exploration.asteroidRuns++;
          stats.exploration.asteroidMined.alloy += run.minedAlloy;
          stats.exploration.asteroidMined.crystal += run.minedCrystal;
          stats.exploration.asteroidMined.deuterium += run.minedDeuterium;
        }
        for (const run of convoyByPlayer.get(player.playerId) ?? []) {
          if (run.abandonedAt !== null || run.resourceReward === null) continue;
          stats.exploration.convoyAttempts++;
          if (
            run.resourceReward.alloy + run.resourceReward.crystal
              + run.resourceReward.deuterium > 0
            || fleetCount(run.awardedFleet ?? {}) > 0
          ) stats.exploration.convoySuccesses++;
          if (run.status === 'done') {
            stats.exploration.convoyDelivered.alloy += run.resourceReward.alloy;
            stats.exploration.convoyDelivered.crystal += run.resourceReward.crystal;
            stats.exploration.convoyDelivered.deuterium += run.resourceReward.deuterium;
          }
        }
      }
      return {
        seasonId,
        cycleId: season.cycleId,
        accountId: player.accountId,
        finalRank,
        dominion,
        honorScore: honorByPlayer.get(player.playerId)?.honor ?? null,
        honorRank: honorByPlayer.get(player.playerId)?.rank ?? null,
        damageDealt,
        damageTaken,
        rivalName: rival?.commanderName ?? null,
        biggestRaid: biggest?.value ?? 0,
        title,
        recap: {
          commanderName: player.commanderName,
          countryCode: player.countryCode,
          planetName: player.planetName,
          battles: mine.length + myMonuments.length,
          attacks,
          defences,
          rival,
          biggestRaid: biggest,
          clan,
        },
        statsVersion: stats.version,
        stats,
        averageEligible: !botAccountIds.has(player.accountId),
        createdAt: clock.now(),
      };
    });
    if (values.length > 0) {
      await tx.insert(seasonResults).values(values).onConflictDoNothing();
    }
    const galaxyRecord = buildGalaxyRecord({
      seasonId,
      ranked,
      rankedClans,
      reports,
      events: chronicleRows,
      worlds: worldRows,
    });
    // WAITING is Silent Space: it preserves inactive commanders but is not a
    // season they entered or a ladder that pays into the next competitive world.
    if ((rewardProgram || honorRanks) && seasonShard.role !== 'WAITING') {
      /*
        A PLACE MAY BE EMPTY, BUT IT MAY NEVER MOVE.

        Bots compete on the same public ladder as everybody else. They cannot
        receive persistent power, and zero-Dominion commanders have not earned a
        prize, but removing either BEFORE assigning tiers promoted everybody below
        them: the public #2 received the #1 package while the live reward card
        truthfully called it the #2 place. First bind every tier to its global
        rank, then omit recipients who cannot collect it. A bot winner therefore
        leaves first prize unclaimed; it does not rewrite the race after it ends.
      */
      const honorByAccount = new Map(roster.map(player => [player.accountId, honorByPlayer.get(player.playerId)]));
      const earned = values.flatMap(row => {
        if (botAccountIds.has(row.accountId)) return [];
        const tier = rewardProgram && row.dominion >= rewardProgram.minimumDominion
          ? rewardProgram.tiers.find(candidate => candidate.place === row.finalRank) : undefined;
        const honor = honorByAccount.get(row.accountId);
        const zero = { alloy: 0, crystal: 0, deuterium: 0 };
        const selected = selectSeasonReward(tier?.reward ?? zero, honor?.reward ?? zero);
        if (honorResourceValue(selected.reward) === 0) return [];
        const place = selected.ranking === 'HONOR' ? honor?.rank : tier?.place;
        if (place === undefined) throw new Error('Missing selected season reward rank');
        return [{ row, ...selected, place }];
      });
      if (earned.length > 0) {
        await tx.insert(seasonRewardEntitlements).values(earned.map(({ row, ranking, reward, place }) => {
          return {
            sourceCycleId: season.cycleId,
            sourceSeasonId: seasonId,
            accountId: row.accountId,
            displayRank: ranking === 'HONOR' ? row.honorRank! : row.finalRank,
            rewardPlace: place,
            ranking,
            ...reward,
            programVersion: rewardProgram?.version ?? 1,
            createdAt: clock.now(),
          };
        })).onConflictDoNothing();
      }
    }
    await tx.update(unknownSignals).set({ status: 'expired' }).where(and(eq(unknownSignals.seasonId, seasonId), eq(unknownSignals.status, 'open')));
    await tx.update(unknownSignalState).set({ nextAt: null }).where(eq(unknownSignalState.seasonId, seasonId));
    await tx.update(seasons).set({
      status: 'frozen',
      closedAt: capturedThrough,
      endReason: event === null ? 'FORCED_WIPE' : 'SCHEDULED_END',
      galaxyRecord,
    }).where(eq(seasons.id, seasonId));
    await publishShard(tx, seasonId, 'season');
  });
}

export const onSeasonEnd: Handler = async (ctx, event) => {
  const seasonId = event.refId ?? event.seasonId;
  if (seasonId !== event.seasonId) throw new Error('season_end refId does not match its season');
  await freezeSeason(ctx, seasonId, event);
};

/** Seal a live season through now before an operator removes its world rows. */
export async function forceSeasonEnd(ctx: HandlerContext, seasonId: string): Promise<void> {
  await freezeSeason(ctx, seasonId, null);
}

/** Fifteen minutes after the snapshot, replace every galaxy in one commit. D88. */
export const onSeasonRollover: Handler = async ({ db, clock }, event) => {
  const seasonId = event.refId ?? event.seasonId;
  if (seasonId !== event.seasonId) {
    throw new Error('season_rollover refId does not match its season');
  }

  const result = await wipeAllServers(
    db,
    clock,
    {
      // A predecessor row records what that season admitted. It must never pin
      // the next world to a legacy 50-seat cap or resurrect retired ordinals.
      count: SERVERS.count,
      capacity: SERVERS.capacity,
    },
    { eventSeasonId: seasonId, requireAllFrozen: true },
  );
  if (!result.deferred) return;

  // A late season-end event must finish first. Replace this claimed event rather
  // than mutating it back to pending; `complete()` then safely finds no old row.
  await db.transaction(async (tx) => {
    const [source] = await tx
      .select({ status: seasons.status })
      .from(seasons)
      .where(eq(seasons.id, seasonId))
      .for('update');
    if (!source || source.status === 'wiped') return;
    await tx.delete(scheduledEvents).where(eq(scheduledEvents.id, event.id));
    await schedule(tx, {
      seasonId,
      kind: 'season_rollover',
      refId: seasonId,
      resolveAt: new Date(clock.now().getTime() + 1_000),
    });
  });
};

export const onDeathStarReady: Handler = async ({ db, clock }, event) => {
  if (!event.refId || typeof event.payload?.expectedReadyAt !== 'string') return;
  await db.transaction(async (tx) => {
    await lockSeason(tx, event.seasonId);
    const [asset] = await tx.select({ planetId: strategicAssets.planetId }).from(strategicAssets).where(eq(strategicAssets.id, event.refId!));
    if (!asset) return;
    await lockWorlds(tx, [asset.planetId]);
    const ready = await finishDeathStarBuild(tx, event.refId!, event.payload!.expectedReadyAt as string);
    const planetId = ready[0]?.planetId;
    if (!planetId) return;
    if (ready[0]?.type === 'INTERCEPTOR') {
      await wakeStrategicInterceptions(tx, planetId, new Date(event.payload!.expectedReadyAt as string));
    }
    const [world] = await tx
      .select({ playerId: planets.controllerPlayerId })
      .from(planets)
      .where(eq(planets.id, planetId));
    if (world?.playerId) {
      await observeHonorOwner(tx, world.playerId, clock.now());
      await publish(tx, world.playerId, 'death_star_ready');
    }
  });
};

export const onBuildComplete: Handler = async ({ db, clock }, event) => {
  if (!event.refId || typeof event.payload?.expectedReadyAt !== 'string') return;
  await db.transaction(async (tx) => {
    await lockSeason(tx, event.seasonId);
    const applied = await applyBuildCompletion(
      tx,
      event.refId!,
      event.payload!.expectedReadyAt as string,
      clock,
    );
    if (!applied) {
      // Migration 0047 keeps legacy completion events on their old enum value:
      // PostgreSQL cannot use a newly-added enum value until the migration
      // transaction commits. The migrated research row retains the same id and
      // expected instant, so this one-release bridge completes it safely.
      const research = await applyResearchCompletion(
        tx,
        event.refId!,
        event.payload!.expectedReadyAt as string,
        clock,
      );
      if (research) await publish(tx, research.playerId, 'research_complete');
      return;
    }
    const [owner] = await tx
      .select({ playerId: planets.controllerPlayerId })
      .from(buildOrders)
      .innerJoin(planets, eq(planets.id, buildOrders.planetId))
      .where(eq(buildOrders.id, event.refId!));
    // The absolute timer wakes an open planet screen. This event reconciles the
    // worker race and also reaches an owner who was looking elsewhere at the time.
    if (owner?.playerId) await publish(tx, owner.playerId, 'build_complete');
  });
};

