  const client = useQueryClient();
  const lane = usePlanetInputLane();
  const refresh = async (): Promise<void> => {
    await Promise.all([keys.monuments, keys.galaxy, keys.planet, keys.planets, keys.pending,
      keys.traffic, keys.notifications, keys.reports, keys.clanWar, keys.season].map((queryKey) => refreshQueries(client, { queryKey })));
  };
  return {
    send: useMutation({
      mutationFn: ({ monumentId, input, key }: { monumentId: string; input: MonumentSendInput; key: string }) => api.sendMonument(monumentId, input, key),
      onMutate: ({ input }) => lane.enter(input.originPlanetId),
      onSuccess: refresh,
      onSettled: (_data, _error, _vars, turn) => { lane.leave(turn); },
    }),
    probe: useMutation({
      mutationFn: ({ monumentId, originPlanetId, key }: { monumentId: string; originPlanetId: string; key: string }) => api.probeMonument(monumentId, originPlanetId, key),
      onMutate: ({ originPlanetId }) => lane.enter(originPlanetId),
      onSuccess: refresh,
      onSettled: (_data, _error, _vars, turn) => { lane.leave(turn); },
    }),
    recall: useMutation({ mutationFn: ({ waveId, selections, key }: { waveId: string; selections: readonly MonumentRecallSelection[]; key: string }) => api.recallMonument(waveId, selections, key), onSuccess: refresh }),
  };
}

/** War writes affect a small set of reads; each response is parsed by Api. */
export function useClanWarActions() {
  const api = useApi();
  const client = useQueryClient();
  const { activePlanetId } = useWorld();
  const lane = usePlanetInputLane();
  const applyPlanet = useApplyPlanet();
  const refresh = (): void => {
    void refreshQueries(client, { queryKey: keys.clanWar });
    void refreshQueries(client, { queryKey: keys.pending });
    void refreshQueries(client, { queryKey: keys.traffic });
  };
  return {
    target: useMutation({ mutationFn: (planetId: string) => api.markClanWarTarget(planetId),
      onSuccess: refresh }),
    monumentTarget: useMutation({ mutationFn: (monumentId: string) => api.markClanWarMonumentTarget(monumentId),
      onSuccess: refresh }),
    cancel: useMutation({ mutationFn: () => api.cancelClanWar(), onSuccess: refresh }),
    start: useMutation({ mutationFn: ({ acknowledgeShieldLoss, pace, acknowledgeRadiationLoss }: {
      acknowledgeShieldLoss: boolean; pace: MissionPace; acknowledgeRadiationLoss?: boolean;
    }) => acknowledgeRadiationLoss ? api.startClanWar(acknowledgeShieldLoss, pace, true)
      : api.startClanWar(acknowledgeShieldLoss, pace), onSuccess: refresh }),
    quote: useMutation({ mutationFn: (input: { originPlanetId: string; fleet: Fleet }) =>
      api.quoteClanWar(input) }),
    contribute: useMutation({ mutationFn: (input: { originPlanetId: string; fleet: Fleet;
      acknowledgeShieldLoss: boolean; acknowledgeRadiationLoss?: boolean }) => api.contributeClanWar(input),
      onMutate: ({ originPlanetId }) => lane.enter(originPlanetId),
      onSuccess: async (result) => {
        await applyPlanet(result.planet);
        /*
          Pending and traffic are viewpoints from the contribution's origin.
          Only hand them to the global selected-world caches when that is the
          world the player is looking through. The null id is the supported
          capital alias used by legacy embeds and tests.
        */
        const resultIsActive = activePlanetId === null
          || result.planet.planet.id === activePlanetId;
        if (resultIsActive) {
          client.setQueryData(keys.pending, { pending: result.pending });
          client.setQueryData(keys.traffic, result.traffic);
        }
        client.setQueryData<ClanWar>(keys.clanWar, (current) =>
          current ? { ...current, operation: result.war } : current);
        refresh();
      },
      onSettled: (_data, _error, _vars, turn) => { lane.leave(turn); },
    }),
    recall: useMutation({ mutationFn: (id: string) => api.recallClanWar(id), onSuccess: refresh }),
    donate: useMutation({
      mutationFn: (input: { planetId: string; resources: Resources }) => api.donateClanTreasury(input),
      onMutate: ({ planetId }) => lane.enter(planetId),
      onSuccess: () => Promise.all([keys.clanWar, keys.planets, keys.planet]
        .map((queryKey) => refreshQueries(client, { queryKey }))),
      onSettled: (_data, _error, _vars, turn) => { lane.leave(turn); },
    }),
    upgrade: useMutation({ mutationFn: (level: number) => api.upgradeClanLevel(level),
      onSuccess: () => {
        void refreshQueries(client, { queryKey: keys.clanWar });
        void refreshQueries(client, { queryKey: keys.clanLeaderboard });
      } }),
  };
}

