    onSuccess: ({ message }) => {
      client.setQueryData<InfiniteData<ChatPage, string | null>>(keys.chatMessagesFor(language), (current) => {
        if (!current) {
          return { pages: [{ messages: [message], nextBefore: null }], pageParams: [null] };
