/**
 * Apply every authoritative view a mining/salvage launch moved. D120.
 *
 * The status key is per selected world, while the old capital-only client still
 * reads the unqualified alias. Always seed the explicit key and seed the alias only
 * when it is the surface this tree is using. Each older GET is cancelled before
 * the POST answer is written, or a pre-launch run list can erase the new craft.
 */
function useApplyMiningResult(activePlanetId: string | null) {
  const client = useQueryClient();
  const applyPlanet = useApplyPlanet();
  return async (result: MiningLaunchResult | MiningRecallResult) => {
    const planetId = result.planet.planet.id;
    const statusKey = keys.miningStatusById(planetId);
    const capitalId = client.getQueryData<PlanetsView>(keys.planets)?.capitalPlanetId
      ?? client.getQueryData<PlanetView>(keys.planet)?.planet.id;
    // A recall can originate at another colony even on the legacy capital-only
    // surface. Only the roster is commander-wide; hardware and stock are not.
    const seedAlias = activePlanetId === null && (!capitalId || capitalId === planetId);
    await Promise.all([
      applyPlanet(result.planet, seedAlias),
      // Every per-world status carries the commander's complete run roster. An
      // older read for any selected colony must not erase this launch later.
      client.cancelQueries({ queryKey: keys.miningStatus }),
      client.cancelQueries({ queryKey: keys.pending }),
    ]);
    client.setQueriesData<MiningStatusView>(
      { queryKey: keys.miningStatus },
      (current) => current
        ? { ...current, runs: result.mining.runs, isotopes: result.mining.isotopes }
        : current,
    );
    client.setQueryData(statusKey, result.mining);
    if (seedAlias) client.setQueryData(keys.miningStatus, result.mining);
    client.setQueryData(keys.pending, { pending: result.pending });
  };
}

/**
 * THE PIRATES THIS COMMANDER CAN SEE. D150.
 *
 * Keyed by the world it is measured FROM, because `reachMinutes` is a rendezvous
 * solved from that world's coordinates — reusing another world's answer would put
 * a flight time on the screen that no launch from here could keep.
 *
 * A current reading of pirates identified once by Telescope. Discovery persists
 * after they leave sight, but the roster, rendezvous and deadline keep changing.
 * A dead pirate leaves the list, so no earlier read may be merged forward.
 */
export function usePirates(options: { live?: boolean } = {}) {
  const api = useApi();
  const { activePlanetId } = useWorld();
  return useQuery({
    queryKey: activePlanetId ? keys.piratesFrom(activePlanetId) : keys.pirates,
    queryFn: ({ signal }) => api.pirates(activePlanetId ?? undefined, { signal }),
    /*
      AT THE TRAFFIC PACE WHILE SOMEBODY IS AIMING, NOT THE ORDINARY ONE. D183.

      This payload carries a RENDEZVOUS TABLE — an instantaneous solve against a
      moving target — and at a minute's staleness it can name a different lap of
      the orbit than the launch will. `TRAFFIC_MS` is the pace everything else that
      moves on the disc is read at, and a pirate is one of the things that moves.
      The launch still carries the quote and the server still refuses a drifted one;
      this is what keeps that refusal rare rather than routine.

      That only matters while a pirate's focus or its launch sheet is open, so only
      those observers ask for `live`. Every other one — the disc tally — rides the
      `shard:pirate` events and the one-minute net: solving the table every five
      seconds for every commander was 10% of production requests (resource analysis
      2026-10-13). Observers share the query; each keeps its own interval.
    */
    staleTime: 5_000,
    refetchInterval: options.live === true ? TRAFFIC_MS : NET_MS,
  });
}

