    ) => api.raidPirate(pirateId, fleet, planetMutationOrigin(context) ?? undefined, quotedMinutes, acknowledgeRadiationLoss),
    onMutate: lane.enter,
    onSuccess: async (result) => {
      playSound('launch');
      await Promise.all([
        applyPlanet(result.planet),
        client.cancelQueries({ queryKey: keys.pending }),
