export const seasonSchema = z.object({
  honorSoloCredit: z.boolean().optional(),
  seasonReward: seasonRewardReceipt.nullish(),
  seasonId: z.string(),
  /** Last season's top eight, index N − 1 naming monument N (2026-10-10). Older servers omit it. */
  monumentHonorees: z.array(z.string().nullable()).optional(),
  shard: z.string(),
  /** Added after the first season payload; old servers remain readable. */
  shardName: z.string().optional(),
  /** Public galaxy generation identity. Private asteroid schedules use a server-only key. */
  seed: z.number(),
  status: z.string(),
  startsAt: z.coerce.date(),
  endsAt: z.coerce.date(),
  playerCap: z.number(),
  /**
   * The rule set this season was dealt. Optional so a client one deploy ahead of the
   * server still parses; read through `fleetEscapeApplies` and its siblings, never
   * compared by hand.
   */
  rulesetVersion: z.number().int().positive().optional(),
  players: z.number(),
  /**
   * Commanders whose last authenticated request was inside the online window.
   *
   * Optional so a client one deploy ahead of the server still parses — the same
   * rule every added field follows here.
   */
  online: z.number().optional(),
  /**
   * Distinct commanders seen in this galaxy over `SERVERS.dayWindowMinutes`.
   *
   * Optional for the same rolling-deploy reason as `online`, and read the same
   * way: absent means "this server does not say", never zero.
   */
  onlineToday: z.number().optional(),
  /**
   * WHAT THE TOP TEN WIN NEXT SEASON, read from the cycle's own frozen program.
   *
   * Optional and nullable for two different reasons, and both matter: OPTIONAL
   * because a server one deploy behind does not send it, NULL because a cycle
   * opened before the program was activated genuinely promises nothing. A client
   * that showed a table in either case would be inventing an offer.
   */
  seasonRewards: z
    .object({
      version: z.number().int().positive(),
      minimumDominion: z.number(),
      tiers: z.array(z.object({
        place: z.number().int().positive(),
        alloy: z.number().nonnegative(),
        crystal: z.number().nonnegative(),
        deuterium: z.number().nonnegative(),
      })),
    })
    .nullable()
    .optional(),
  result: seasonResultSchema.nullable().optional(),
  /**
   * THE COMMANDERS THIS ONE IS WATCHING — up to `RIVAL.max`, each in its own slot.
   * D183.
   *
   * It was one planet id and one commander id (D91 · D97), and the ceiling went to
   * five on the owner's instruction. The SLOT is the load-bearing field: the disc
   * draws a mark's colour from it, so it is stored rather than read off a position
   * in this array — a mark that changed colour because an unrelated one was cleared
   * would be a different bookmark every time the list moved.
   *
   * `.default([])` so a client ahead of its server reads an empty disc rather than
   * failing the season payload, which also carries the clock and the population.
   */
  rivals: z.array(z.object({
    planetId: z.string(),
    playerId: z.string(),
    slot: z.number().int().nonnegative(),
  })).default([]),
  /**
   * WHEN THIS COMMANDER'S OWN RAID IMMUNITY ENDS — null when they have none.
   * D183 · 2026-09-14.
   *
   * Read by the launch surface, which has to say what a raid COSTS before it is
   * pressed: firing gives the shield up, once, and a position spent without being
   * offered is one the player did not choose to spend.
   *
   * IT IS THE LATER OF THE TWO SHIELDS since the recovery window shipped, composed
   * server-side by `effectiveAttackProtection`, because both are spent by the same
   * launch and both refuse the same raid. `shieldKind` says WHICH, so the HUD and
   * the confirmation can name what is being given up — the first day never comes
   * back, a recovery window can be earned again, and telling a player the wrong one
   * misprices the decision.
   *
   * `.nullish()` on both so a client ahead of its server simply shows no warning
   * rather than failing the season payload, which also carries the clock.
   */
  shieldUntil: z.coerce.date().nullish().transform((at) => at ?? null),
  shieldKind: z.enum(['NEWCOMER', 'RECOVERY']).nullish().transform((kind) => kind ?? null),
});

/**
 * THE SIX NUMBERS THAT MAKE ONE ORBIT, AND THE SAME SIX A DISCOVERED ROCK CARRIES.
 *
 * Given these, the client runs the shared `interceptOrbit` the server runs, which
 * is what stops the launch screen and the server disagreeing about the minute a
 * convoy meets the merchant.
 */
const galaxyOrbitSchema = z.object({
  radius: z.number().positive(),
  period: z.number().positive(),
  phase: z.number(),
  inclination: z.number(),
  ascendingNode: z.number(),
  speed: z.number().positive(),
});

/**
 * WHOLE NUMBERS, AND THE ARITHMETIC IS WHY. D183.
 *
 * The split's step comes from `leadStride`, which divides the cheap price by
 * `gcd(dear, cheap)` — and a greatest common divisor of two fractions is not a
 * number anybody should reason about. A rate of 1.5 would snap the split onto
 * positions that leave a remainder, quietly reintroducing the scrap the whole
 * mechanism exists to prevent.
 *
 * `TRADE.rate` is authored as whole numbers and an occurrence freezes what it was
 * dealt, so a fraction cannot reach here today. `.int()` is what keeps that true
 * after somebody edits the table: the boundary states the requirement rather than
 * the arithmetic assuming it.
 */
export const tradeRateSchema = z.object({
  alloy: z.number().int().positive(),
  crystal: z.number().int().positive(),
  deuterium: z.number().int().positive(),
});

const activeGalaxyEventSchema = z.discriminatedUnion('kind', [
  z.object({
    id: z.string().uuid(),
    kind: z.literal('ASTEROID_SHOWER'),
    startsAt: z.coerce.date(),
    endsAt: z.coerce.date(),
    asteroidSpawnMultiplier: z.number().gt(1),
  }),
  /**
   * Ticaret Gemisi. D156. Unlike a pirate, whose elements ARE its route and stay
   * server-private (D150), the merchant is an announced public moment and the disc
   * may draw its whole circle — but only while it is actually there.
   */
  z.object({
    id: z.string().uuid(),
    kind: z.literal('TRADE_SHIP'),
    startsAt: z.coerce.date(),
    endsAt: z.coerce.date(),
    rate: tradeRateSchema,
    /** Minutes since season start — the clock `orbit` is evaluated on. */
    appearsAtMinute: z.number(),
    expiresAtMinute: z.number(),
    orbit: galaxyOrbitSchema,
  }),
  z.object({
    id: z.string().uuid(),
    kind: z.literal('INTERGALACTIC_CONVOY'),
    startsAt: z.coerce.date(),
    endsAt: z.coerce.date(),
    appearsAtMinute: z.number(),
    expiresAtMinute: z.number(),
    route: z.object({
      from: vec3,
      to: vec3,
      velocity: vec3,
      speed: z.number().positive(),
    }),
    visual: z.object({ formationVersion: z.literal(1) }),
    rewardPolicy: z.object({
      resourceCapHours: z.number().positive(),
      fullRewardForceRatio: z.number().positive(),
      shipDropFullFirepower: z.number().positive(),
      shipDropChanceAtFullQuality: z.number().min(0).max(1),
      maxAwardedShips: z.number().int().positive(),
    }),
  }),
]);

const knownGalaxyEventKinds: ReadonlySet<string> = new Set(
  activeGalaxyEventSchema.options.map((option) => option.shape.kind.value),
);

/**
 * FORWARD-COMPATIBLE ON PURPOSE, AND THAT IS ALSO ITS ONE HAZARD.
 *
 * An unknown kind is dropped so a server that learns a new public event never
 * blanks the chip on an older client. The cost is that a kind the server publishes
 * correctly and this file has not been taught simply never appears, with no error
 * anywhere — which is exactly what happened while `activeGalaxyEventsSchema` knew
 * only `ASTEROID_SHOWER`: a live trade ship arrived on every response and was
 * silently discarded. `contract.test.ts` now parses this route with a live
 * merchant on it so the drop can never be the reason a kind is missing again.
 */
export const activeGalaxyEventsSchema = z.object({
  next: z.object({
    kind: z.enum(['ASTEROID_SHOWER', 'TRADE_SHIP', 'INTERGALACTIC_CONVOY']),
    startsAt: z.coerce.date(),
  }).nullable().default(null),
  events: z.array(z.unknown()).transform((rows, context) => rows.flatMap((row, index) => {
    const identity = z.object({ kind: z.string() }).passthrough().safeParse(row);
    if (!identity.success || !knownGalaxyEventKinds.has(identity.data.kind)) return [];
    const parsed = activeGalaxyEventSchema.safeParse(row);
    if (parsed.success) return [parsed.data];
    for (const issue of parsed.error.issues) {
      context.addIssue({ ...issue, path: [index, ...issue.path] });
    }
    return [];
  })),
});

