export const planetSchema = z.object({
  workshopRadiation: z.boolean().optional(),
  planet: z.object({
    id: z.string(),
    /** Economy anchor and ordering of server views; optional for rolling deploys. */
    snapshotAt: z.coerce.date().optional(),
    name: z.string(),
    skinId: z.enum(PLANET_SKIN_IDS).nullable().optional(),
    kind: z.enum(['CAPITAL', 'COLONY']).optional(),
    position: vec3,
    alloy: z.number(),
    crystal: z.number(),
    deuterium: z.number(),
    alloyCap: z.number(),
    crystalCap: z.number(),
    deuteriumCap: z.number(),
    alloyPerHour: z.number(),
    /** Hardware output before a temporary colony fault; used to state the outage cost. */
    nominalAlloyPerHour: z.number().optional(),
  /** Zero on a world with no refinery, and absent on a server that predates one. */
  deuteriumPerHour: z.number().optional(),
    crystalPerHour: z.number(),
    nominalCrystalPerHour: z.number().optional(),
    nominalDeuteriumPerHour: z.number().optional(),
    /**
     * The works: uncollected production, and the ceiling it stops at. D16.
     *
     * Both are needed here, not just the amount, because the interface has to say
     * "full in 3h 20m" before it can say "FULL — you are throwing away 160/h", and
     * only the second of those is a reason to open the game right now.
     */
    bufferAlloy: z.number(),
    bufferCrystal: z.number(),
    bufferDeuterium: z.number(),
    bufferAlloyCap: z.number(),
    bufferCrystalCap: z.number(),
    bufferDeuteriumCap: z.number(),
    vaultFloor: z.number(),
    vaultProtected: resources,
    vaultCapacity: resources,
    shield: z.number(),
    shieldMax: z.number(),
    shieldPerHour: z.number(),
    shieldRegenAt: z.coerce.date().nullable().optional(),
    radiationProtectionHpPerMinute: z.number().nonnegative().optional(),
    radiationProtectionLevel: z.number().int().nonnegative().optional(),
    radiationProtectionRestoresAt: z.coerce.date().nullable().optional(),
    disruptedUntil: z.coerce.date().nullable(),
    recoveryUntil: z.coerce.date().nullable().optional(),
    empUntil: z.coerce.date().nullable().optional(),
    protectedUntil: z.coerce.date().nullable().optional(),
    /**
     * NO TRANSFER MAY LEAVE THIS WORLD UNTIL THIS INSTANT. Faz 2A.3.
     *
     * The five minutes after a squadron lands, so a fleet cannot be bounced between two of a
     * commander's own worlds fast enough to never be on the ground. Null once it has passed, and
     * absent from a server that predates it.
     */
    transferReadyAt: z.coerce.date().nullable().optional(),
    /**
