import type { BattleReplayData, BattleSide } from '@astera/rules';
import { z } from 'zod';
import { grade, hullId } from './schemas.js';

const nonnegative = z.number().finite().nonnegative();
const side = z.enum(['ATTACK', 'DEFENCE']);
const shipState = z.object({ id: z.string().min(1), hp: nonnegative, shield: nonnegative, status: z.enum(['ACTIVE', 'DESTROYED', 'RETREATED']) });
const hit = z.object({ targetId: z.string(), pass: nonnegative.int(), baseShare: nonnegative, counter: nonnegative,
  hpBefore: nonnegative, hpAfter: nonnegative, shieldBefore: nonnegative, shieldAfter: nonnegative,
  aegisBefore: nonnegative, aegisAfter: nonnegative, bonusAegisDamage: nonnegative, normalAegisDamage: nonnegative,
  shieldDamage: nonnegative, hullDamage: nonnegative });
const shot = z.object({ sourceId: z.string(), order: nonnegative.int(), baseDamage: nonnegative, unusedBaseDamage: nonnegative, hits: z.array(hit) });
const fleet = z.record(hullId, nonnegative.int());
const recording = z.object({ schemaVersion: z.literal(1), roundLimit: nonnegative.int().positive(), initialAegis: nonnegative,
  ships: z.array(shipState.extend({ side, hull: hullId, stackId: z.string(), playerId: z.string(), maxHp: nonnegative.positive(),
    maxShield: nonnegative, attack: nonnegative, canFire: z.boolean(), cls: z.enum(['SKIRMISHER', 'LANCE', 'BULWARK', 'SUPPORT']).optional(), ground: z.boolean().optional() })),
  rounds: z.array(z.object({ round: nonnegative.int().positive(), attackerRoll: nonnegative, defenderRoll: nonnegative,
    aegisBefore: nonnegative, aegisAfter: nonnegative, aegisStrikes: z.array(z.object({ sourceId: z.string(), baseDamage: nonnegative,
      classMultiplier: nonnegative, bonusMultiplier: nonnegative, damage: nonnegative, aegisBefore: nonnegative, aegisAfter: nonnegative })).optional(), attackerShots: z.array(shot), defenderShots: z.array(shot),
    retreated: z.array(z.string()), exploded: z.array(z.string()).optional(), after: z.array(shipState) })),
  damageScale: z.object({ attacker: nonnegative, defender: nonnegative }).optional(),
  aftermath: z.array(z.object({ kind: z.enum(['PIRATE_OVERRUN', 'CARGO_WITHDRAWAL']), shipIds: z.array(z.string()) })).optional(),
  finalState: z.array(shipState).optional(),
}).superRefine((value, ctx) => {
  const ids = new Set(value.ships.map(ship => ship.id));
  const unknown = (id: string) => !ids.has(id);
  const complete = (states: { id: string }[]) => states.length === ids.size && new Set(states.map(state => state.id)).size === ids.size && !states.some(state => unknown(state.id));
  if (ids.size !== value.ships.length || value.rounds.some(round => !complete(round.after) || round.retreated.some(unknown) || round.exploded?.some(unknown) === true || round.aegisStrikes?.some(strike => unknown(strike.sourceId)) === true
    || [...round.attackerShots, ...round.defenderShots].some(shot => unknown(shot.sourceId) || shot.hits.some(hit => unknown(hit.targetId))))
    || value.aftermath?.some(action => action.shipIds.some(unknown)) === true || value.finalState !== undefined && !complete(value.finalState)) {
    ctx.addIssue({ code: 'custom', message: 'Recording refers to unknown or duplicate units' });
  }
});
export const battleReplayResponseSchema: z.ZodType<{ viewer: BattleSide; ownPlayerIds?: string[]; replay: BattleReplayData }> = z.object({ viewer: side, ownPlayerIds: z.array(z.string()).optional(), replay: z.object({ recording,
  owners: z.array(z.object({ side, playerId: z.string(), stackId: z.string(), wing: nonnegative.int().positive(),
    research: z.object({ SHIP_POWER: nonnegative.int().optional(), SHIP_ARMOR: nonnegative.int().optional(),
      SHIP_SHIELDS: nonnegative.int().optional(), EMPLACEMENT_DOCTRINE: nonnegative.int().optional() }) })),
  result: z.object({ grade, defenceSalvage: fleet }), environment: z.enum(['PLANET', 'MONUMENT']),
  aegisCapacity: nonnegative, defenceOffline: z.boolean(), escape: z.object({ kind: z.enum(['ESCAPED', 'STRANDED']), ships: fleet }).nullable(),
  control: z.enum(['ATTACKER', 'DEFENDER', 'EMPTY']).nullable(),
}) });

sources.apps/web/src/session/shardEvents.ts:
import { keys } from '../api/keys.js';

/**
 * WHAT A GALAXY-WIDE EVENT MEANS TO THIS CLIENT. D53.
 *
 * The stream now carries two families. A PLAYER event is something that happened
 * to this commander and refreshes everything, because almost anything can have
 * moved. A SHARD event is something that happened to SOMEBODY ELSE in the same
 * galaxy — a fleet leaving, a raid resolving, a drill going out, a world growing
 * — and it is the half that used to arrive on a twenty-to-thirty-second poll.
 *
 * The server says what HAPPENED; this file decides what to read because of it.
 * That split is deliberate: which query holds which fact is a client concern, and
 * putting the mapping on the wire would mean a payload shape to keep in step with
 * every refactor of the query keys.
 *
 * NOTHING HERE IS A STATE UPDATE. A shard event carries a kind and nothing else —
 * no id, no owner, no position — so the only thing it can do is send the client
 * to a payload it was already entitled to read. Every fog rule is still enforced
 * in the query it points at, exactly as it was when a timer pointed at the same
 * query thirty seconds later.
 */

/** The prefix the server namespaces shard kinds with. Must match `bus.ts`. */
export const SHARD_PREFIX = 'shard:';
export const GLOBAL_PREFIX = 'global:';

export const isShardEvent = (kind: string): boolean => kind.startsWith(SHARD_PREFIX);
export const isGlobalEvent = (kind: string): boolean => kind.startsWith(GLOBAL_PREFIX);

/** A global event is deliberately rarer and narrower than a game-state event. */
export function readsForGlobalEvent(kind: string): readonly (readonly string[])[] {
  switch (kind.slice(GLOBAL_PREFIX.length)) {
    case 'announcement':
      return [keys.announcements];
    case 'chat-badges':
      return [keys.chatMessages, keys.clanChat, keys.dmMessages];
    default:
      return [];
  }
}

/**
 * Which reads a galaxy-wide event moves.
 *
 * DELIBERATELY NARROW, and `galaxy` is the reason. It is the most expensive read
 * in the game — it carries a telescope reading for every world the caller watches
 * and it provokes a `lastConfirmedAt` write — so it is refetched only for the one
 * kind that can actually change it. `launch`, `arrival` and `mining` cannot: a
 * craft in the air appears in `traffic` and in `mining`, and the galaxy payload
 * publishes a world's silhouette, its orbit and its dome, none of which a flight
 * touches.
 *
 * An unknown kind maps to nothing. A newer server publishing a kind this client
 * has never heard of must be inert here, not a crash and not a blanket refetch —
 * the same reason the client parses a notification kind as a string and never as
 * an enum.
 */
export function readsForShardEvent(kind: string): readonly (readonly string[])[] {
  switch (kind.slice(SHARD_PREFIX.length)) {
    /** Somebody's craft left a world. It is in the air, so it is in `traffic`. */
    case 'launch':
      return [keys.traffic];
    /**
     * A flight ended. `traffic` loses the contact — and `mining` gains whatever a
     * battle left behind, because a debris field is published on that payload.
     */
    case 'arrival':
      return [keys.traffic, keys.miningField];
    case 'transfer':
      return [keys.traffic, keys.pending, keys.planet, keys.planets];
    case 'impact':
      return [keys.traffic, keys.galaxy, keys.planet, keys.pending, keys.miningField];
    case 'control':
      return [
        keys.monuments,
        keys.traffic,
        keys.galaxy,
        keys.planet,
        keys.planets,
        keys.pending,
        keys.leaderboard,
        keys.miningField,
      ];
    /**
     * A world came out of its outage, or somebody's raid immunity moved.
     *
     * `season` is in the list because the commander's OWN shield countdown lives on
     * that payload: a recovery shield granted by a battle has to appear in the HUD
     * and price the launch sheet immediately, not on the next minute's poll.
     */
    case 'recovery':
    case 'protection':
      return [keys.galaxy, keys.planet, keys.season];
    /**
     * A mining or salvage run started, turned for home, or landed. The shard-wide
     * half refreshes only the caller-filtered rock/wreck field and public traffic. The one
     * owner receives a player event (or their launch response) for private runs,
     * research and orbit; making everybody query those rows was the D99 fan-out.
     */
    case 'mining':
      return [keys.miningField, keys.traffic];
    /**
     * A PIRATE RAID LEFT, LANDED, OR CAME HOME. D150.
     *
     * The server has published this since the lane shipped and this table had no
     * case for it, so the kind fell through to the inert default below and the
     * whole feature ran on the sixty-second safety net. Three things arrived late:
     *
     *   · THE WRECK. A pirate battle leaves a real field at the rendezvous, and
     *     the public race to collect it is half of what makes the fight worth
     *     watching (D32). Nobody in the galaxy was told to go and look — not even
     *     the commander who fought it, because a `raid_result` resync reads
     *     `miningField` off a projection that was not invalidated either.
     *   · THE CONTACT. The squadron is in `traffic` for both of its legs.
     *   · THE LANE. Unlike the rock field, this list SHRINKS: a pirate somebody
     *     else wiped has to leave the disc, and `usePirates` is the only read that
     *     says so. `keys.pirates` is a prefix of the per-world key, so this covers
     *     whichever world the reading was measured from.
     */
    case 'pirate':
      return [keys.traffic, keys.miningField, keys.pirates];
    /** A world changed shape or gained hardware — the only public change to a world. */
    case 'world':
      return [keys.galaxy, keys.leaderboard];
    /** A battle changed at least one rounded-chip Dominion score. */
    case 'score':
      return [keys.leaderboard, keys.galaxy];
    /** A season-scoped message changed both the open conversation and closed dot. */
    case 'chat':
      return [keys.chatMessages, keys.chatUnread];
    /** A public moment was committed to the galaxy's 24-hour memory. */
    case 'chronicle':
      return [keys.chronicle];
    /** A public event started or ended: refresh its chip, Signals and Chronicle. */
    case 'galaxy-event':
      return [keys.galaxyEvents, keys.notifications, keys.chronicle, keys.miningField];
    /** The deadline landed: freeze controls, standings and the permanent recap. */
    case 'season':
      return [keys.season, keys.planet, keys.pending, keys.leaderboard, ['honor-target'], keys.unknownSignals];
    /** Public clan identity or score moved; private state has its own player event. */
    case 'clan':
      return [keys.galaxy, keys.leaderboard, ['clan', 'directory'], keys.clanLeaderboard];
    default:
      return [];
  }
}

/**
 * A FINISHED BUILD OR RESEARCH IS ABOUT ONE WORLD. Resource analysis 2026-10-13.
 *
 * These player events arrived unrouted, so each one re-read all of `LIVE_READS`.
 * What they move is the world and its commander: levels, queues, research and the
 * reward progress counted off them. A sensor change publishes `private:sensors` and a
 * public change publishes `shard:world`, so traffic, mining field and the public map
 * have their own events. `galaxy` stays on a build so the owner's own world redraws
 * at once rather than on the heavy lane.
 *
 * `null` means "not one of these" and the caller keeps the full resync.
 */
export function readsForPlayerEvent(kind: string): readonly (readonly string[])[] | null {
  switch (kind) {
    case 'build_complete':
      return [keys.planet, keys.planets, keys.pending, keys.rewards, keys.galaxy];
    case 'research_complete':
      return [keys.planet, keys.planets, keys.pending, keys.rewards, keys.miningStatus];
    case 'death_star_ready':
      return [keys.planet, keys.planets, keys.pending];
    default:
      return null;
  }
}

/** The prefix the server namespaces player-private clan kinds with. Matches `bus.ts`. */
export const PRIVATE_PREFIX = 'private:';

export const isPrivateEvent = (kind: string): boolean => kind.startsWith(PRIVATE_PREFIX);

/**
 * A NARROW PRIVATE EVENT IS ABOUT YOU, AND STILL MUST NOT COST WHAT A RESYNC DOES. D114.
 *
 * `publishPrivate` namespaces five narrow kinds and its docblock calls each one "a
 * narrow invalidation" — but nothing here read the prefix, so every one of them fell
 * through to the blanket player-event resync. One clan chat message therefore sent
 * each of five members to refetch the planet, the galaxy, intel, notifications,
 * pending, reports, traffic, mining, rewards, both chats, the chronicle AND all seven
 * clan reads, five times per ten seconds at the permitted burst. That is the exact
 * fan-out `readsForShardEvent` exists to prevent, arriving through the other door.
 *
 * `null` means "this client does not know that kind" and the caller falls back to the
 * full resync — the safe direction for a newer server, and the opposite of the shard
 * table's inert `[]`, because a private event genuinely did happen to this commander.
 */
export function readsForPrivateEvent(kind: string): readonly (readonly string[])[] | null {
  switch (kind.slice(PRIVATE_PREFIX.length)) {
    case 'community-block':
      return [keys.communityBlocks, keys.chatMessages, keys.chatUnread, keys.clanChat, keys.clanBadge, keys.dmConversations, keys.dmUnread, keys.dmMessages, ['dm', 'contacts']];
    case 'unknown-signal-spawn':
      return [keys.unknownSignals];
    case 'unknown-signal':
      return [keys.unknownSignals, keys.pending, keys.planet, keys.planets, keys.notifications, keys.skins];
    case 'honor':
      return [keys.reports, keys.planet, keys.planets, keys.leaderboard];
    case 'sensors':
      return [keys.traffic, keys.miningField, keys.pirates, keys.galaxy];
    case 'monument':
      return [keys.monuments, keys.pending, keys.planet, keys.planets, keys.notifications, keys.reports, keys.galaxy, keys.traffic, keys.clanWar];
    /** A world this commander watches launched or recovered combat craft. */
    case 'sight':
      return [keys.galaxy, keys.intel];
    /**
     * An entitled commander can now render the eight-second interceptor scene — and the
     * weapon it hunts has already left the participants' own lists (the attacker's craft,
     * the defender's siren), which `pending` carries (owner, 2026-10-16).
     */
    case 'strategic-sight':
      return [keys.traffic, keys.pending];
    /** A mission began or an operator granted a reward while this commander was online. */
    case 'reward':
      return [keys.rewards];
    /**
     * A CRAFT OF THIS COMMANDER'S REACHED A WORLD AND WROTE DOWN WHAT IT FOUND. D151.
     *
     * One read, and it is the expensive one — which is the whole reason this row
     * exists rather than falling through to the resync below. A raid already wakes
     * its owner with `raid_result`, and that wake is unrouted and therefore refetches
     * everything; this arrives on the same commit and is precise about the one
     * payload the record actually moves.
     */
    case 'memory':
      return [keys.galaxy];
    /** A run launched on another tab/device moved this commander's own state. */
    case 'mining':
      return [keys.miningStatus, keys.pending, keys.planet];
    /** A pirate fleet launched, made an early U-turn, or landed. */
    case 'pirate':
      return [keys.pending, keys.planet, keys.planets];
    /** Joined, left, kicked, promoted, disbanded, or the settings changed. */
    case 'clan-membership':
      return [
        keys.clanBadge,
        keys.clanHome,
        keys.clanStrength,
        keys.clanEvents,
        keys.galaxy,
        keys.leaderboard,
        keys.season,
      ];
    /** An application or invitation was raised, withdrawn, rejected or expired. */
    case 'clan-request':
      return [keys.clanBadge, keys.clanHome];
    /** Somebody spoke. The badge carries the unread count the beacon is drawn from. */
    case 'clan-chat':
      return [keys.clanBadge, keys.clanChat];
    case 'dm':
      return [keys.dmConversations, keys.dmMessages, keys.dmUnread];
    /** A share was credited or claimed; the outside view carries the depot too. */
    case 'clan-depot':
      return [keys.clanBadge, keys.clanDepot, keys.clanHome];
    /**
     * A convoy left, landed, turned round or came home. A DELIVERY moves real
     * hardware and real resources on a world, so this one legitimately reaches
     * past the clan surface — leaving it out would park the recipient's gifted
     * ships on a stale planet payload until the sixty-second net came round.
     */
    case 'clan-aid':
      return [keys.clanAid, keys.clanHome, keys.planet, keys.planets, keys.pending, keys.traffic];
    case 'clan-war':
      return [keys.clanWar, keys.pending, keys.planet, keys.planets, keys.traffic, keys.reports];
    case 'clan-treasury':
      return [keys.clanWar, keys.planet, keys.planets, keys.leaderboard, keys.clanLeaderboard];
    /**
     * KLAN SAVUNMA DESTEĞİ: a wave this commander sent, or one at their world, moved —
     * dispatched, landed, turned, fought or came home. Both worlds and the strip move.
     */
    case 'clan-support':
      return [keys.clanSupport, keys.planet, keys.planets, keys.pending, keys.traffic, keys.reports];
    /** A clanmate's world opened or closed to clan support: the door on its Focus rail. */
    case 'clan-posture':
      return [keys.galaxy];
    default:
      return null;
  }
}

/**
 * HOW LONG TO GATHER BEFORE ASKING. D53.
 *
 * The thing a broadcast makes possible is also the thing it makes easy to get
 * wrong: three hundred clients hearing the same event and all refetching in the same
 * instant is fifty queries per launch, and a galaxy where four things happen at
 * once is four times that from every one of them.
 *
 * So the events are collected and the reads are done once. A quarter of a second
 * is under the threshold where a person reads a delay as a delay, and it collapses
 * a battle — which publishes an arrival, and whose debris and traffic both move —
 * into a single pass. It is a coalescing window, not a poll: an event on a quiet
 * galaxy still lands within a quarter second of the instant it names.
 */
export const COALESCE_MS = 250;

/**
 * Gathers shard events and flushes them as one set of reads.
 *
 * Deliberately not a React hook: the whole point is that it holds state ACROSS
 * renders and across the stream reconnecting, and it is far easier to assert
 * against as a plain object than through a test renderer.
 */
/**
 * THE HEAVY LANE. 2026-09-19, the owner's first phone recording.
 *
 * In a full thousand-seat galaxy `/api/galaxy` is ~475 KB and the ladder ~194 KB,
 * and GROWTH — a satellite installed, a Core tier crossed, a score moved, a clan
 * changed — made every client read both at once and again 1.5 s later for
 * consistency. With a roster of bots building all day that was a megabyte and a
 * 140–214 ms stall every few seconds, second for second in the recording.
 *
 * Growth is not urgent, so it waits: one read at most every thirty seconds after
 * the first event, and never sooner than `CONSISTENCY_MS` after the last one it
 * covers — which is what the separate consistency re-read used to buy. Anything
 * that changes the map in a way a player is watching for (a capture, a strike, a
 * dome, a record) keeps the quick lane.
 */
export const HEAVY_COALESCE_MS = 30_000;
/** How long every replica's projection cache needs to observe a commit. */
export const CONSISTENCY_MS = 1_500;
const HEAVY_KINDS: ReadonlySet<string> = new Set(['shard:world', 'shard:score', 'shard:clan']);

export function shardCoalescer(
  flush: (reads: readonly (readonly string[])[]) => void,
  windowMs = COALESCE_MS,
) {
  /** Query keys waiting to be read, de-duplicated by their joined name. */
  let waiting = new Map<string, readonly string[]>();
  let timer: ReturnType<typeof setTimeout> | undefined;
  let heavy = new Map<string, readonly string[]>();
  let heavyTimer: ReturnType<typeof setTimeout> | undefined;
  let heavyFirst = 0;
  let heavyLast = 0;

  const armHeavy = (): void => {
    const due = Math.max(heavyFirst + HEAVY_COALESCE_MS, heavyLast + CONSISTENCY_MS);
    heavyTimer = setTimeout(() => {
      // An event landed inside the consistency window: wait it out, once more.
      if (Date.now() < heavyLast + CONSISTENCY_MS) {
        armHeavy();
        return;
      }
      heavyTimer = undefined;
      const reads = [...heavy.values()];
      heavy = new Map();
      flush(reads);
    }, Math.max(0, due - Date.now()));
  };

  return {
    note(kind: string): void {
      const reads = readsForShardEvent(kind);
      // An unknown kind must not arm a timer that will flush nothing.
      if (reads.length === 0) return;
      if (HEAVY_KINDS.has(kind)) {
        for (const key of reads) heavy.set(key.join('/'), key);
        heavyLast = Date.now();
        if (heavyTimer !== undefined) return;
        heavyFirst = heavyLast;
        armHeavy();
        return;
      }
      for (const key of reads) waiting.set(key.join('/'), key);
      if (timer !== undefined) return;
      timer = setTimeout(() => {
        timer = undefined;
        const due = [...waiting.values()];
        waiting = new Map();
        flush(due);
      }, windowMs);
    },
    /** On unmount. A pending flush must not outlive the component that armed it. */
    cancel(): void {
      if (timer !== undefined) clearTimeout(timer);
      if (heavyTimer !== undefined) clearTimeout(heavyTimer);
      timer = undefined;
      heavyTimer = undefined;
      waiting = new Map();
      heavy = new Map();
    },
  };
}

