import { useEffect, useRef, useState, useSyncExternalStore, type PointerEvent } from 'react';
import { ARENA_TUNING as T } from '@astera/rules/arena';
import { KNOB_TRAVEL, LANDING_THROTTLE, THROTTLE_DETENTS, chordAt, stickHome, type ArenaAction, type ArenaControls, type Circle } from './input.js';
import type { HudSnapshot, HudStore } from './store.js';
import { arenaCopy } from './copy.js';

const ICONS: Record<ArenaAction, React.ReactNode> = {
  fire: <svg viewBox="0 0 32 32"><circle cx="16" cy="16" r="7" /><path d="M16 3v7M16 22v7M3 16h7M22 16h7" /><circle cx="16" cy="16" r="1.4" fill="currentColor" /></svg>,
  turbo: <svg viewBox="0 0 32 32"><path d="M7 8l8 8-8 8M16 8l8 8-8 8" /></svg>,
  smoke: <svg viewBox="0 0 32 32"><path d="M9 23a5 5 0 0 1-1.2-9.8 7 7 0 0 1 13.4-2.7 5 5 0 0 1 4.6 7.7A4.5 4.5 0 0 1 22 23z" /></svg>,
  cloak: <svg viewBox="0 0 32 32"><path d="M4 16s4.5-7 12-7 12 7 12 7-4.5 7-12 7S4 16 4 16z" /><circle cx="16" cy="16" r="3.4" /><path d="M6 26 26 6" /></svg>,
};

/**
 * Two-thumb portrait layout. Left thumb: a floating stick anywhere in the lower left.
 * Right thumb: FIRE at rest, TURBO beside it (used together with steering), SMOKE and
 * CLOAK further away so they are never hit by accident, and a sticky throttle rail on
 * the right edge. A contextual LAND / TAKE OFF key sits centred under the ship.
 */
/** One key, three states. Landing is a tap; taking off needs a short hold so a stray tap never launches you. */
/** Owner 2026-10-21: 70 % shorter than the first 550 ms. */
export const TAKEOFF_HOLD_MS = 165;

export function LandKey({ status, onLand, onCancel, onTakeOff }: { status: HudSnapshot; onLand: () => void; onCancel: () => void; onTakeOff: () => void }) {
  const c = arenaCopy();
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const [holding, setHolding] = useState(false);
  const release = (): void => { if (timer.current) clearTimeout(timer.current); timer.current = null; setHolding(false); };
  useEffect(() => release, []);
  if (status.landed) {
    return <button className={`ac-land is-takeoff ${holding ? 'is-holding' : ''}`} style={{ '--hold': `${String(TAKEOFF_HOLD_MS)}ms` } as React.CSSProperties}
      onPointerDown={event => { event.preventDefault(); setHolding(true); timer.current = setTimeout(() => { release(); onTakeOff(); }, TAKEOFF_HOLD_MS); }}
      onPointerUp={release} onPointerCancel={release} onPointerLeave={release}>
      <i aria-hidden />{c.takeOffHold}
    </button>;
  }
  if (status.landing === 'approach') {
    return <button className="ac-land is-cancel" onPointerDown={event => { event.preventDefault(); onCancel(); }}>
      {c.cancelLanding}<small>{String(Math.round(status.landingDistance))} m</small>
    </button>;
  }
  return <button className="ac-land" onPointerDown={event => { event.preventDefault(); onLand(); }}>{c.land}</button>;
}

const circleOf = (element: HTMLElement): Circle => {
  const r = element.getBoundingClientRect();
  return { x: r.left + r.width / 2, y: r.top + r.height / 2, r: r.width / 2 };
};

export function FlightControls({ controls, store, onLand, onCancel }: { controls: ArenaControls; store: HudStore; onLand: () => void; onCancel: () => void }) {
  const c = arenaCopy();
  const keys = useRef(new Map<ArenaAction, HTMLButtonElement>());
  // FIRE and TURBO share one touch zone so one thumb across both holds both (chordAt).
  const chords = useRef(new Map<number, Set<ArenaAction>>());
  const [held, setHeld] = useState<ReadonlySet<ArenaAction>>(new Set());
  const chord = (event: PointerEvent<HTMLDivElement>, phase: 'move' | 'up' | 'cancel'): void => {
    const fire = keys.current.get('fire'); const turbo = keys.current.get('turbo');
    const id = event.pointerId; const had = chords.current.get(id);
    if (!fire || !turbo || (phase === 'move' && !had)) return;
    const contact = event.pointerType === 'touch' ? Math.max(event.width, event.height) / 2 : 0;
    const next = phase === 'move' && !fire.disabled ? chordAt(event.clientX, event.clientY, contact, circleOf(fire), circleOf(turbo)) : [];
    const mine = had ?? new Set<ArenaAction>();
    // A thumb rolling off a key is not a tap: only a lift may count as a turbo tap-burst.
    for (const action of [...mine]) if (!next.includes(action as 'fire' | 'turbo')) {
      controls.actionUp(action, id, event.timeStamp, phase !== 'up'); mine.delete(action);
    }
    for (const action of next) if (!mine.has(action) && controls.actionDown(action, id, event.timeStamp)) mine.add(action);
    if (phase === 'move') chords.current.set(id, mine); else chords.current.delete(id);
    setHeld(new Set([...chords.current.values()].flatMap(set => [...set])));
  };
  const ring = useRef<HTMLDivElement>(null);
  const knob = useRef<HTMLDivElement>(null);
  const pad = useRef<HTMLDivElement>(null);
  const status = useSyncExternalStore(store.subscribe, store.getSnapshot, store.getSnapshot);
  const throttle = useSyncExternalStore(listener => controls.subscribe(listener), () => controls.throttle, () => controls.throttle);
  useEffect(() => {
    let frame = 0;
    const paint = (): void => {
      frame = requestAnimationFrame(paint);
      const bounds = pad.current?.getBoundingClientRect();
      if (!bounds || !ring.current || !knob.current) return;
      const active = controls.stickPointer !== null;
      ring.current.toggleAttribute('data-active', active);
      if (active) {
        ring.current.style.left = `${String(controls.stickCenter.x - bounds.left)}px`;
        ring.current.style.top = `${String(controls.stickCenter.y - bounds.top)}px`;
      } else { ring.current.style.left = ''; ring.current.style.top = ''; }
      knob.current.style.transform = `translate(${String(controls.stick.x * KNOB_TRAVEL)}px, ${String(controls.stick.y * KNOB_TRAVEL)}px)`;
    };
    frame = requestAnimationFrame(paint);
    return () => { cancelAnimationFrame(frame); };
  }, [controls]);
  const level = (event: PointerEvent<HTMLDivElement>): number => {
    const bounds = event.currentTarget.getBoundingClientRect();
    return Math.max(0, Math.min(1, 1 - (event.clientY - bounds.top - 10) / Math.max(1, bounds.height - 20)));
  };
  const alive = status.phase === 'flying';
  const cooldown = (action: ArenaAction): number => action === 'smoke' ? status.smokeCooldown / T.smokeCooldown
    : action === 'cloak' ? status.cloakCooldown / T.cloakCooldown : action === 'turbo' ? 1 - status.turboCharge / T.turboCharge : 0;
  const seconds = (action: ArenaAction): number => action === 'smoke' ? status.smokeCooldown : action === 'cloak' ? status.cloakCooldown : 0;
  return <div className="ac-root">
    <div ref={pad} className="ac-stick-pad" role="group" aria-label={c.throttle}
      onPointerDown={event => {
        event.preventDefault();
        // The base appears where the thumb lands, but only inside a fixed home area.
        const keys = [...(event.currentTarget.parentElement?.querySelectorAll('.ac-action, .ac-land') ?? [])].map(key => key.getBoundingClientRect());
        const home = stickHome({ x: event.clientX, y: event.clientY }, event.currentTarget.getBoundingClientRect(), keys);
        if (controls.stickDown(event.pointerId, home.x, home.y)) {
          event.currentTarget.setPointerCapture(event.pointerId);
          controls.stickMove(event.pointerId, event.clientX, event.clientY);
        }
      }}
      onPointerMove={event => { controls.stickMove(event.pointerId, event.clientX, event.clientY); }}
      onPointerUp={event => { controls.stickUp(event.pointerId); }} onPointerCancel={event => { controls.stickUp(event.pointerId); }}
      onLostPointerCapture={event => { controls.stickUp(event.pointerId); }}>
      <div ref={ring} className="ac-stick"><i /><i /><i /><i /><div ref={knob} className="ac-knob" /></div>
    </div>
    <div className="ac-throttle" role="slider" aria-label={c.throttle} aria-valuemin={0} aria-valuemax={100} aria-valuenow={Math.round(throttle * 100)} tabIndex={0}
      onPointerDown={event => {
        event.preventDefault();
        if (controls.throttleDown(event.pointerId, level(event), event.timeStamp)) event.currentTarget.setPointerCapture(event.pointerId);
      }}
      onPointerMove={event => { controls.throttleMove(event.pointerId, level(event)); }}
      onPointerUp={event => { controls.throttleUp(event.pointerId); }} onPointerCancel={event => { controls.throttleUp(event.pointerId); }}
      onLostPointerCapture={event => { controls.throttleUp(event.pointerId); }}>
      <span>{c.throttle}</span>
      <div className="ac-rail" style={{ '--level': String(throttle) } as React.CSSProperties}>
        {THROTTLE_DETENTS.map(detent => <em key={detent} style={{ bottom: `${String(detent * 100)}%` }}
          data-land={detent === LANDING_THROTTLE ? '' : undefined}>{detent === LANDING_THROTTLE ? c.landStop : ''}</em>)}
        <i /><b />
      </div>
      <strong>{Math.round(throttle * 100)}</strong>
    </div>
    {alive && (status.landed || status.landing === 'approach' || status.canLand) && <LandKey status={status} onLand={onLand}
      onCancel={onCancel} onTakeOff={() => { controls.takeOff(); }} />}
    <div className="ac-chord" aria-hidden
      onPointerDown={event => {
        event.preventDefault(); event.currentTarget.setPointerCapture(event.pointerId);
        chords.current.set(event.pointerId, new Set()); chord(event, 'move');
      }}
      onPointerMove={event => { chord(event, 'move'); }}
      onPointerUp={event => { chord(event, 'up'); }} onPointerCancel={event => { chord(event, 'cancel'); }}
      onLostPointerCapture={event => { chord(event, 'cancel'); }} />
    {(['fire', 'turbo', 'smoke', 'cloak'] as const).map(action => {
      const wait = seconds(action);
      const charge = cooldown(action);
      const chorded = action === 'fire' || action === 'turbo';
      return <button key={action} ref={element => { if (element) keys.current.set(action, element); else keys.current.delete(action); }}
        className={`ac-action ac-${action} ${action === 'turbo' && status.turboActive ? 'is-active' : ''} ${action === 'fire' && status.locked ? 'is-locked' : ''} ${chorded ? 'is-chorded' : ''} ${held.has(action) ? 'is-pressed' : ''}`}
        aria-label={c[action]} disabled={!alive || wait > 0}
        style={{ '--charge': String(Math.max(0, Math.min(1, charge))) } as React.CSSProperties}
        {...(chorded ? {} : {
          onPointerDown: (event: PointerEvent<HTMLButtonElement>) => {
            event.preventDefault();
            if (controls.actionDown(action, event.pointerId, event.timeStamp)) event.currentTarget.setPointerCapture(event.pointerId);
          },
          onPointerUp: (event: PointerEvent<HTMLButtonElement>) => { controls.actionUp(action, event.pointerId, event.timeStamp); },
          onPointerCancel: (event: PointerEvent<HTMLButtonElement>) => { controls.actionUp(action, event.pointerId, event.timeStamp, true); },
          onLostPointerCapture: (event: PointerEvent<HTMLButtonElement>) => { controls.actionUp(action, event.pointerId, event.timeStamp, true); },
        })}>
        <svg className="ac-ring" viewBox="0 0 100 100" aria-hidden><circle cx="50" cy="50" r="47" /></svg>
        <span className="ac-icon" aria-hidden>{ICONS[action]}</span>
        <small>{wait > 0 ? String(Math.ceil(wait)) : c[action]}</small>
      </button>;
    })}
  </div>;
}

sources.apps/web/src/arena/resolution.ts:
/**
 * RESOLUTION GOVERNOR (owner 2026-10-20: smooth on every friend's phone). The arena
 * renders sharp, up to 2×. A device that cannot hold the frame rate steps its pixel
 * ratio down a quarter at a time until it can; one that keeps up is never touched.
 * Down only: climbing back would oscillate on a phone that sits at the edge.
 */
export interface Resolution { ratio: number; warmup: number; elapsed: number; frames: number }

const FLOOR = 1;
const STEP = 0.25;
const MIN_FPS = 48;
const WINDOW_S = 2;
/** Loading, shader compile and the warp-in hitch are not the device's steady pace. */
const WARMUP_S = 3;
/** A frame this long is a hitch or a backgrounded tab, not a slow GPU. */
const HITCH_S = 0.25;

export const createResolution = (ratio: number): Resolution => ({ ratio, warmup: WARMUP_S, elapsed: 0, frames: 0 });

/** Feeds one frame's dt; returns the new pixel ratio when it should change, else null. */
export function stepResolution(r: Resolution, dt: number): number | null {
  if (dt > HITCH_S) { r.elapsed = 0; r.frames = 0; return null; }
  if (r.warmup > 0) { r.warmup -= dt; return null; }
  r.elapsed += dt; r.frames++;
  if (r.elapsed < WINDOW_S) return null;
  const fps = r.frames / r.elapsed;
  r.elapsed = 0; r.frames = 0;
  if (fps >= MIN_FPS || r.ratio <= FLOOR) return null;
  r.ratio = Math.max(FLOOR, r.ratio - STEP);
  return r.ratio;
}

sources.apps/web/src/arena/Hud.tsx:
import { useSyncExternalStore, type ReactNode, type Ref } from 'react';
import { ARENA_TUNING as T, FARM_POINTS, MAX_REMOTE_PILOTS } from '@astera/rules/arena';
import { FARM_TONE } from './farmColors.js';
import type { HudStore, HudSnapshot } from './store.js';
import { arenaCopy, type ArenaCopy } from './copy.js';

export interface HudBind {
  reticle: Ref<HTMLDivElement>; lead: Ref<HTMLDivElement>; hit: Ref<HTMLDivElement>; kill: Ref<HTMLDivElement>;
  enemies: (index: number) => Ref<HTMLDivElement>; threats: (index: number) => Ref<HTMLDivElement>;
  exit: Ref<HTMLDivElement>; crystal: Ref<HTMLDivElement>; damage: Ref<HTMLDivElement>; rear: Ref<HTMLDivElement>;
  landing: Ref<HTMLDivElement>;
  radar: Ref<HTMLCanvasElement>;
}

const clock = (seconds: number): string => `${String(Math.floor(seconds / 60))}:${String(Math.floor(seconds % 60)).padStart(2, '0')}`;

function Gauge({ icon, label, value, fill, tone, alert }: { icon: ReactNode; label: string; value: string; fill: number; tone: string; alert?: boolean }) {
  return <div className={`ah-gauge ${alert ? 'is-alert' : ''}`} style={{ '--tone': tone, '--fill': String(Math.max(0, Math.min(1, fill))) } as React.CSSProperties}>
    <span className="ah-gauge-icon" aria-hidden>{icon}</span>
    <span className="ah-gauge-label">{label}</span>
    <strong>{value}</strong>
    <i aria-hidden><b /></i>
  </div>;
}

/** The hold: what it would score (the number), how full it is and of what (the bar, by kind). */
function HoldGauge({ s, c }: { s: HudSnapshot; c: ArenaCopy }) {
  const full = s.cargo >= T.cargoCapacity;
  return <div className={`ah-gauge ah-hold ${full ? 'is-full' : ''}`} style={{ '--tone': 'var(--color-v2-ink)' } as React.CSSProperties}>
    <span className="ah-gauge-icon" aria-hidden>{ICON.cargo}</span>
    <span className="ah-gauge-label">{c.cargo} · {String(Math.floor(s.cargo))}/{String(T.cargoCapacity)}</span>
    <strong>{s.points}<small> {c.pointsShort}</small></strong>
    <i aria-hidden>{s.hold.map((units, kind) => units > 0 && <b key={kind}
      style={{ width: `${String(units / T.cargoCapacity * 100)}%`, background: FARM_TONE[kind], boxShadow: `0 0 6px ${FARM_TONE[kind] ?? ''}` }} />)}</i>
  </div>;
}

const ICON = {
  hull: <svg viewBox="0 0 16 16"><path d="M8 1.5 13.5 4v4.2c0 3-2.3 5.2-5.5 6.3C4.8 13.4 2.5 11.2 2.5 8.2V4z" fill="none" stroke="currentColor" strokeWidth="1.4" /></svg>,
  fuel: <svg viewBox="0 0 16 16"><path d="M8 1.8c2.6 3.4 4.2 5.7 4.2 7.7A4.2 4.2 0 0 1 3.8 9.5c0-2 1.6-4.3 4.2-7.7z" fill="none" stroke="currentColor" strokeWidth="1.4" /></svg>,
  cargo: <svg viewBox="0 0 16 16"><path d="m8 1.5 5.6 3.2v6.6L8 14.5l-5.6-3.2V4.7zM2.6 4.8 8 8l5.4-3.2M8 8v6.3" fill="none" stroke="currentColor" strokeWidth="1.3" /></svg>,
};

/** One line that says what the pilot must know right now, and why. */
function context(s: HudSnapshot, c: ArenaCopy): { title: string; hint?: string; tone: 'self' | 'warn' | 'hostile' | 'crystal'; progress?: number } | null {
  if (s.clientPhase !== 'flight' || (s.phase !== 'flying' && s.phase !== 'fuelOut')) return null;
  if (s.linkLost > 0) return { title: c.link, hint: `${String(Math.ceil(s.linkLost))} s`, tone: 'hostile' };
  if (s.phase === 'fuelOut') return { title: c.rescue, hint: `${String(Math.ceil(s.rescue))} s`, tone: 'warn', progress: 1 - s.rescue / T.fuelOutRescueDelay };
  if (s.inExit) {
    if (s.extraction > 0) return { title: c.exitHold, hint: `${s.extraction.toFixed(1)} / ${String(T.exitHold)} s`, tone: 'self', progress: s.extraction / T.exitHold };
    if (s.damageRecent) return { title: c.exitBroken, tone: 'hostile' };
    return { title: c.exitZone, hint: c.exitStop, tone: 'self' };
  }
  if (s.landed) {
    const kind = c.kinds[s.depositKind];
    if (s.mining && kind) return { title: `${kind} · ${c.mining}`, hint: `${String(Math.floor(s.cargo))}/${String(T.cargoCapacity)} · ${c.perUnit} ${String(FARM_POINTS[s.depositKind] ?? 0)} ${c.pointsShort} · ${c.miningHint}`, tone: 'crystal', progress: s.cargo / T.cargoCapacity };
    if (s.depositKind >= 0 && s.cargo >= T.cargoCapacity) return { title: c.full, hint: c.fullHint, tone: 'warn' };
    if (s.depositKind >= 0 && s.dry) return { title: c.dry, hint: c.dryHint, tone: 'warn' };
    return { title: c.landed, hint: c.landedHint, tone: 'self' };
  }
  if (s.landing === 'approach') return { title: `${c.landingNote} · ${String(Math.round(s.landingDistance))} m`, hint: c.landingHint, tone: 'crystal' };
  if (s.cloak > 0) return { title: c.cloaked, hint: `${s.cloak.toFixed(1)} s · ${c.cloakedHint}`, tone: 'self', progress: s.cloak / T.cloakDuration };
  if (s.fuel < 15) return { title: c.lowFuel, hint: `${clock(s.remaining)} · ${c.lowFuelHint}`, tone: 'hostile' };
  if (s.boundary < T.boundaryWarn) return { title: c.boundary, hint: `${String(Math.max(0, Math.round(s.boundary)))} m`, tone: 'warn' };
  // A full hold sends you to an exit, and the spawn shield is a countdown you plan around;
  // "you can land" is last because the LAND key and the touchdown ring already say it.
  if (s.cargo >= T.cargoCapacity) return { title: c.full, hint: c.fullHint, tone: 'warn' };
  if (s.shield > 0) return { title: `${c.shield} · ${String(Math.ceil(s.shield))} s`, hint: c.shieldHint, tone: 'self', progress: s.shield / T.spawnShield };
  if (s.canLand) return { title: c.approach, hint: c.approachHint, tone: 'crystal' };
  return null;
}

export function ArenaHud({ store, bind, onMenu, connection }: { store: HudStore; bind: HudBind; onMenu: () => void; connection: ReactNode }) {
  const s = useSyncExternalStore(store.subscribe, store.getSnapshot, store.getSnapshot);
  const c = arenaCopy();
  const flight = s.clientPhase === 'flight';
  const note = context(s, c);
  const hullShare = s.hull / T.hull;
  return <div className={`ah-root ${flight ? 'is-flight' : ''}`}>
    <div className="ah-top">
      <Gauge icon={ICON.hull} label={c.hull} value={`${String(Math.round(hullShare * 100))}%`} fill={hullShare}
        tone={hullShare < 0.3 ? 'var(--color-v2-hostile)' : 'var(--color-v2-self)'} alert={hullShare < 0.3} />
      <Gauge icon={ICON.fuel} label={c.fuel} value={clock(s.remaining)} fill={s.fuel / T.fuelTank}
        tone={s.fuel < 15 ? 'var(--color-v2-hostile)' : 'var(--color-v2-deut)'} alert={s.fuel < 15} />
      <HoldGauge s={s} c={c} />
      <button className="ah-menu" aria-label={c.settings} onClick={onMenu}>
        <svg viewBox="0 0 20 20" aria-hidden><path d="M4 6h12M4 10h12M4 14h12" stroke="currentColor" strokeWidth="1.5" /></svg>
      </button>
    </div>
    <div className="ah-instruments">
      <div className="ah-radar"><canvas ref={bind.radar} width={132} height={132} aria-hidden /></div>
      <div ref={bind.rear} className="ah-rear" data-hit={s.damageRecent ? '' : undefined}><span>{c.rear}</span><i /><i /><i /><i /></div>
      <div className="ah-speed">
        <strong>{Math.round(s.speed)}</strong><small>{c.speed}</small>
        <em data-state={s.landed ? 'landed' : s.turboActive ? 'turbo' : s.speed === 0 ? 'stopped' : 'flying'}>
          {s.landed ? c.landedChip : s.turboActive ? c.turboChip : s.speed === 0 ? c.stopped : `${String(Math.round(s.throttle * 100))}%`}
        </em>
      </div>
    </div>
    {connection}
    {note && <div className={`ah-note tone-${note.tone}`} role="status">
      <strong>{note.title}</strong>{note.hint && <span>{note.hint}</span>}
      {note.progress !== undefined && <i><b style={{ transform: `scaleX(${String(Math.max(0, Math.min(1, note.progress)))})` }} /></i>}
    </div>}
    <div className="ah-marks" aria-hidden>
      <div ref={bind.reticle} className="ah-reticle"><i /><i /><i /><i /><b /></div>
      <div ref={bind.hit} className="ah-hit"><i /><i /><i /><i /></div>
      <div ref={bind.kill} className="ah-kill"><i /><span>{c.destroyed}</span></div>
      <div ref={bind.lead} className="ah-lead" />
      {Array.from({ length: MAX_REMOTE_PILOTS }, (_, i) => <div key={i} ref={bind.enemies(i)} className="ah-enemy">
        <i /><i /><i /><i /><span><em data-name /> <b data-distance /></span><u><b data-hull /></u>
      </div>)}
      {Array.from({ length: 8 }, (_, i) => <div key={i} ref={bind.threats(i)} className="ah-threat" />)}
      <div ref={bind.exit} className="ah-exit"><i /><span>{c.exit} <b data-distance /><em data-points /></span></div>
      <div ref={bind.landing} className="ah-landing"><i /></div>
      <div ref={bind.crystal} className="ah-crystal"><i /><span><em data-kind>{c.crystal}</em> <b data-distance /></span></div>
      <div ref={bind.damage} className="ah-damage"><svg viewBox="0 0 120 120"><path d="M30 18a52 52 0 0 1 60 0" /></svg></div>
    </div>
    <div className={`ah-vignette ${s.damageRecent ? 'is-hit' : ''} ${hullShare < 0.3 && flight ? 'is-critical' : ''}`} aria-hidden />
  </div>;
}

