/**
 * THE GALAXY IS THE GAME. D20.
 *
 * There is no longer anywhere else to be. The canvas is mounted once and never
 * unmounted, it fills everything between the resource header and the in-flight
 * strip, and every other surface in the game — your own planet, its four decision
 * groups, the intel centre, a neighbour's dossier, an asteroid, a squadron in
 * transit — opens over it.
 *
 * The tab bar is gone. It was the last thing insisting the map was a place you
 * VISIT, and D1 has said since the design phase that the information game "makes
 * the 3D galaxy an interface rather than a target list".
 *
 * FOCUS IS THE PRIMITIVE. The first tap selects and frames an object — following,
 * if it moves — while the second tap on that same object opens its detail. For a
 * world the commander controls, that second tap opens management instead.
 */

/**
 * WHICH SHEET WAS OPEN, AS A NUMBER THE PERFORMANCE RECORDING CAN CARRY. Admin
 * only (2026-09-19): a sample's context is numbers, and the second recording froze
 * for 745 ms with "a sheet" open and no way to say which. 0 is none; the rest are
 * their place in this list plus one, and the list only ever grows at the end.
 */
export const PERF_PANEL_CODES = [
  'planet', 'research', 'intel', 'report', 'leaderboard', 'clan', 'chat', 'chronicle',
  'rewards', 'announcements', 'feedback', 'donate', 'skin-shop', 'skin-inventory', 'admin',
  'recap', 'menu', 'return', 'wiki', 'ship',
] as const;
export const perfPanelCode = (panel: Panel): number =>
  panel === null ? 0 : PERF_PANEL_CODES.indexOf(panel) + 1;

export type Panel = 'planet' | 'research' | 'ship' | 'intel' | 'report' | 'leaderboard' | 'clan' | 'chat' | 'chronicle' | 'rewards' | 'announcements' | 'feedback' | 'donate' | 'skin-shop' | 'skin-inventory' | 'admin' | 'recap' | 'menu' | 'return' | 'wiki' | null;

/**
 * WHICH SHELF INSIDE A PANEL, WHEN THE PANEL ALONE IS NOT AN ANSWER. D121.
 *
 * A panel is a place; the Intel centre holds two lists in it, and "a battle
 * report arrived" pointed at the place and dropped the reader on the other one.
 * Only `intel` has shelves today, so this is deliberately its two tabs and not a
 * general routing scheme nobody has asked for.
 *
 * The `report` panel names one too, and means it as a FALLBACK: a battle
 * notification opens its own report directly (owner instruction), and lands on
 * this shelf only when that exact fight cannot be found.
 */
export type PanelStop = 'probes' | 'battles';

export function GalaxyView({
  panel,
  onPanel,
  panelStop,
  panelFocus,
  focusRequest,
  craftFocusRequest,
  commander,
  country,
  isAdmin = false,
  pastResult,
  onSignOut,
  onCountryChange,
  onReplayAcademy,
  onEnterArena,
  onPlacementLost,
  onFocused,
  planetGroup,
  openWide,
  wideDistance,
  frameTelescope = false,
  openingHome = false,
  coachFocus = null,
  coachTap = null,
  allowFocus,
  goHome,
  worldsRequest,
  homeRequest,
  centerRequest,
  clearRequest,
  onOpenChat,
  showChat = true,
  showGuidance = true,
}: {
  /** Opened from the header, which is the only chrome left outside the canvas. */
  panel: Panel;
  /**
   * The shelf and the fight travel with the panel, because the report door falls
   * back to the Intel centre and has to be able to say where.
   */
  onPanel: (panel: Panel, stop?: PanelStop, reportMissionId?: string) => void;
  /**
   * Which shelf the panel should open on, with a counter so the same one twice
   * still lands — a second battle notification must not be swallowed because the
   * Intel centre is already showing battles and the reader has since moved off it.
   */
  panelStop?: { stop: PanelStop; request: number; reportMissionId?: string } | null;
  /** A notification that names a world, a tab and a row. Koloni arızaları. */
  panelFocus?: PanelFocusRequest | null;
  /** A route from an already-revealed identity back to its world. */
  /** A world to frame, from outside the galaxy; `dossier` opens its dossier as well (M4). */
  focusRequest?: { planetId: string; request: number; dossier?: boolean; select?: boolean } | null;
  /** A route from the permanent in-flight sheet to a craft already on the disc. */
  craftFocusRequest?: { focus: StripFocus; request: number } | null;
  /** Who is signed in. Shown on the one surface that is about you rather than the world. */
  commander: string;
  country?: CountryCode;
  /** Operations access comes from the server's out-of-band username allow-list. */
  isAdmin?: boolean;
  /** The newest permanent record, still readable after its world was wiped. D87. */
  pastResult?: HistoricalSeasonResult | null;
  onSignOut: () => void;
  onCountryChange?: (country: CountryCode) => Promise<void>;
  onReplayAcademy?: () => void;
  /** F1–F7 prototype entry; absent in the public build and in the Academy. */
  onEnterArena?: () => void;
  /** Safety net when the rollover broadcast was missed while this tab slept. */
  onPlacementLost?: () => void;
  /**
   * What the player just selected, reported to whoever is watching. D56.
   *
   * READ-ONLY, AND ONLY THE ONBOARDING LISTENS. The rehearsal's beats advance on
   * what the player DID — tapping their own world, then a neighbour — rather than
   * on a "next" button, and the honest way to know is to be told. Focus itself
   * stays owned here: a beat that could MOVE the camera would be a tutorial
   * playing itself, which is the thing this whole flow exists not to be.
   */
  onFocused?: (focus: Focus | null) => void;
  /** Which decision group the planet panel opens on, when something else decides. */
  planetGroup?: PlanetGroup;
  /** Open on the whole disc with nothing selected, for the rehearsal. D56. */
  openWide?: boolean;
  /** Exact range for a scripted wide re-frame; used by the rehearsal's neighbourhood beat. */
  wideDistance?: number;
  /** Explicit training exercise: frame the owned world's complete sight sphere. */
  /**
   * ACADEMY ONLY: FLY THE CAMERA ONTO A SUBJECT AND DRAW NO RAIL FOR IT.
   *
   * The mission lessons need the commander to LOOK at the pirate, the rock or the
   * world before they are asked to attack it — and then to tap it. A rail opening
   * over the subject is the one thing that cannot happen there: it covers the
   * target the lesson is pointing at, and it offers a commitment the lesson has
   * not reached yet.
   *
   * `interception` already establishes that a focus kind may be camera-only
   * (`FocusPanel`'s union says so in as many words). This is the same idea reached
   * from outside: while it is set, the subject is followed and every information
   * rail stays shut.
   */
  coachFocus?: { focus: Focus; request: number } | null;
  /** Academy: an invisible hit area pinned to whatever `coachFocus` is showing. */
  coachTap?: { label: string; onTap: () => void } | null;
  frameTelescope?: boolean;
  /** Explicit scripted entrance; ordinary navigation keeps its own camera. */
  openingHome?: boolean;
  /** Which worlds may be selected. Absent means all of them, which is the game. */
  allowFocus?: (planetId: string) => boolean;
  /**
   * Bumped from outside to fly the camera to the player's own world. D56.
   *
   * The same path the header's own control takes, deliberately: the selection is
   * cleared first and then the signal is raised, because a subject still being
   * tracked drags the camera straight back and the flight appears to do nothing.
   */
  goHome?: number;
  /**
   * Bumped from outside to open the Worlds sheet: the v2 shell's world mark (B1).
   * The disc's own transfer mark that used to open it is gone with `DiscControls`.
   */
  worldsRequest?: number;
  /**
   * Bumped from outside to fly home the way the disc's Home mark did (D163): clear
   * the focus, focus the active world — so the next tap on it opens management —
   * and raise the home signal. The v2 dock's Galaxy tab, pressed while lit.
   * `goHome` is the Academy's flight (D56), which leaves nothing focused.
   */
  homeRequest?: number;
  /**
   * E11 · K10, the desk keyboard. Space: bring what is selected back into frame, or fly
   * home with nothing selected. Esc with no page open: let go of the selection.
   */
  centerRequest?: number;
  clearRequest?: number;
  /** Open chat as its own page on a given room: the war room's "Clan chat" (E9). */
  onOpenChat?: (channel?: ChatChannel, draft?: string) => void;
  /** Hidden in the pre-account rehearsal, where no commander identity exists. */
  showChat?: boolean;
  /** The scripted lesson owns guidance during training. */
  showGuidance?: boolean;
}) {
  // The admin performance recorder notes which sheet was open that second.
  useEffect(() => { setPerfExtra('panel', perfPanelCode(panel)); }, [panel]);
  const { t, i18n } = useTranslation();
  const returnStatus = useReturnStatus(showChat);
  const applyToReturn = useApplyToReturn();
  const galaxy = useGalaxy();
  const cosmetics = useSkins();
  const [cosmeticTrial, setCosmeticTrial] = useState<CosmeticTrial | null>(null);
  const [shopSelection, setShopSelection] = useState<CosmeticId | undefined>();
  const planet = usePlanet();
  const intel = useIntel();
  const season = useSeason();
  const monumentCatalog = useMonuments(hpRadiationApplies(planet.data?.rulesetVersion ?? 0));
  const personalSignals = useUnknownSignals();
  const signalActions = useUnknownSignalActions();
  const pending = usePending();
  const traffic = useTraffic();
  const mining = useMining();
  const reports = useReports();
  const setRival = useSetRival();
  const mine = useMine();
  const harvest = useHarvest();
  const recallMining = useRecallMining();
  const recallFlight = useRecallFlight();
  const settlement = useSettlement();
  const deathStar = useLaunchDeathStar();
  const { activePlanetId, capitalPlanetId, worlds, selectPlanet } = useWorld();
  // The clan mark on the disc needs to know whether there is a clan layer at all,
  // and whether anything is waiting inside it. Same read the menu row used.
  const clanBadge = useClanBadge();
  const chatUnread = useChatUnread().data?.count ?? 0;
  const dmUnread = useDmUnread().data?.count ?? 0;
  const say = useToast();
  const now = useNow(5_000);
  /**
   * THE SKY ANSWERS THE EVENT. Owner instruction, D149.
   *
   * A shower is announced by a caption in the corner and by rocks arriving over
   * the next hour — neither of which a player notices on the second they open the
   * disc. `Meteors` triples its shooting stars while this is true and drops back
   * the moment it is not, so the whole sky says something is happening.
   *
   * READ OFF THE SAME FIVE-SECOND TICK the rest of this screen already runs on:
   * the payload carries only ACTIVE events, and the end of one is a clock, so this
   * needs no timer of its own and adds no render.
   */
  const galaxyEvents = useGalaxyEvents();
  /*
    NARROWED ON KIND, which it was not. D154 gives the extra shooting stars to an
    ASTEROID SHOWER, and `/api/galaxy/events` has published a second kind since
    D156 — so a trade window was quietly tripling the meteor pool as well. The
    sky is a statement about rocks arriving; a merchant is not one.
  */
  const meteorShower = (galaxyEvents.data?.events ?? [])
    .some((event) => event.kind === 'ASTEROID_SHOWER' && now < event.endsAt.getTime());
  /**
   * THE MERCHANT, AND THE PROP THAT WAS NEVER PASSED. D156.
   *
   * `GalaxyCanvas` has mounted `<TradeShip>` since slice 2a and its `tradeShip`
   * default is `null`, so the ship was never drawn and nothing anywhere errored —
   * the feature simply was not in the galaxy. `activeTradeShip` narrows the union
   * (`filter` does not) and drops a window that has already shut, so the disc, the
   * chip, the rail and the sheet all read one answer.
   */
  const tradeShip = useMemo(
    () => activeTradeShip(galaxyEvents.data?.events, now),
    [galaxyEvents.data, now],
  );
  const intergalacticConvoy = useMemo(
    () => activeIntergalacticConvoy(galaxyEvents.data?.events, now),
    [galaxyEvents.data, now],
  );
  const [requestedPlanetGroup, setRequestedPlanetGroup] = useState<PlanetGroup | null>(null);
  /** The project a Base door asked research for; the map opens on it (E8). */
  const [researchFocus, setResearchFocus] = useState<ResearchProjectId | null>(null);
  /** The row a notification asked for, cleared the moment the sheet has used it. */
  const [requestedItem, setRequestedItem] = useState<string | null>(null);

  /*
    A REQUESTED TAB BELONGS TO THE PANEL IT WAS MADE FOR. D183.

    This read `panel === null`, and a reader rarely closes anything: Intel's
    "install a Telescope" asks for the orbit, the reader crosses to the Signals
    shelf, then taps a world of their own — the panel never passed through `null`,
    so the orbit request was still standing and the sheet opened on a tab nobody
    had asked for that time. `keepsPlanetGroup` is the single statement of it.
  */
  useEffect(() => {
    if (!keepsPlanetGroup(panel)) {
      setRequestedPlanetGroup(null);
      setRequestedItem(null);
    }
  }, [panel]);

  /*
    THE THREE MOVES OF A FAULT NOTIFICATION, IN ORDER. Owner instruction:
    *"ekran -> ilgili koloniye geçmeli -> menü açmalı -> filo tabını acıp tershaneye
    gelmeli."*

    Keyed on `request` rather than on the payload, so the SAME fault announced twice —
    two colonies losing the same thing, or a reader coming back to a row they already
    visited — lands both times. `nextPanelFocus` is what increments it, and it returns
    null for every navigation that carries no focus, which is what clears a stale one.
  */
  useEffect(() => {
    if (!panelFocus) return;
    if (panelFocus.planetId && panelFocus.planetId !== activePlanetId) {
      selectPlanet(panelFocus.planetId);
    }
    if (panelFocus.group) setRequestedPlanetGroup(panelFocus.group as PlanetGroup);
    setRequestedItem(panelFocus.itemId ?? null);
    /*
      KEYED ON THE REQUEST AND ON NOTHING ELSE. Reacting to `activePlanetId` would re-run
      this the moment the selection it just made lands, and re-assert a tab the reader
      may already have moved off — the exact failure D183 records for the group request.
    */
  }, [panelFocus?.request]);

  /**
   * WAKE UP WHEN SOMETHING LANDS. D48.
   *
   * Both lists are polled on a timer, and a timer is the wrong instrument for an
   * instant the payload already names. Every leg is drawn by an interpolation that
   * CLAMPS, so a craft whose payload is thirty seconds stale is not missing — it is
   * parked on its destination: a squadron hanging over a world it has already
   * finished fighting, a drill sitting at a point its rock left half a minute ago.
   */
  useMiningArrivals(mining.statusData?.runs);
  useFleetArrivals(pending.data?.pending);
  /**
   * AND ASK FOR THE NEXT BEARING WINDOW WHEN THE CURRENT ONE RUNS OUT.
   *
   * A stranger's craft is drawn inside a published window; when it ends the client
   * has no more motion to interpolate and coasts on a guess. This asks for the next
   * one, and — unlike a real arrival — it refetches `traffic` and nothing else,
   * because nothing else can have changed. See `useContactWindows`.
   */
  /**
   * ONE ARRAY IDENTITY, BECAUSE THIS SCREEN RERENDERS ON A CLOCK. D53.
   *
   * `?? []` here minted a fresh empty array every render whenever the server had
   * not sent any — which re-ran the crossing solve and handed `GalaxyCanvas` a new
   * prop each tick, the exact rebuild the stable-prop rule exists to stop. A
   * module-level empty is the same array for ever.
   */
  const sensors = galaxy.data?.sensors ?? NO_SENSORS;
  useContactWindows(traffic.data?.contacts, sensors);

  const [focus, setFocus] = useState<Focus | null>(null);
  const focusedSignalId = focus?.kind === 'unknownSignal' ? focus.id : null;
  const signalDetail = useUnknownSignalDetail(focusedSignalId, !personalSignals.data?.signals.some(row => row.id === focusedSignalId));
  const signalData = useMemo(() => signalDetail.data && focusedSignalId && !personalSignals.data?.signals.some(row => row.id === focusedSignalId)
    ? { ...personalSignals.data, signals: [...personalSignals.data?.signals ?? [], signalDetail.data.signal] } : personalSignals.data,
    [personalSignals.data, signalDetail.data, focusedSignalId]);
  useEffect(() => subscribeUnknownSignal(id => { onPanel(null); setFocus({ kind: 'unknownSignal', id }); }), [onPanel]);
  useEffect(() => { signalActions.send.reset(); signalActions.recall.reset(); }, [focusedSignalId]);
  const [clanInitialTab, setClanInitialTab] = useState<'overview' | 'war'>('overview');
  const clanWar = useClanWar(clanBadge.data?.membership?.role === 'LEADER'
    && (focus?.kind === 'planet' || focus?.kind === 'monument'));
  const clanWarActions = useClanWarActions();
  const [transferTargetId, setTransferTargetId] = useState<string | null>(null);
  /** Klan Savunma Desteği: the clanmate world the send sheet is open for. */
  const [supportHost, setSupportHost] = useState<SupportHost | null>(null);
  /** The active source, kept separate from the focused transfer destination. */
  const [transferOriginId, setTransferOriginId] = useState<string | null>(null);
  const [worldsOpen, setWorldsOpen] = useState(false);
  /**
   * WHETHER THE BOUNDARIES ARE DRAWN AT ALL. Owner instruction, third version.
   *
   * IT WAS A SET OF WORLDS AND IT IS NOW ONE FLAG EACH, and the history is worth
   * the paragraph because both earlier versions were reported as bugs.
   *
   *   1. ONE FLAG FOR THE WHOLE GALAXY, when only the ACTIVE world's radar was
   *      ever drawn. Pressing the telescope hid four shells and pressing the radar
   *      hid one — two adjacent switches with two different reaches.
   *   2. A SET KEYED BY WORLD, which fixed that by making each switch act on the
   *      active world alone. It was consistent and it was not what anybody wanted:
   *      a player who takes the glass off does not mean "off here", they mean off.
   *
   * So the switch is global again, and the thing that made version 1 wrong is
   * fixed at the other end instead — the radar now draws for EVERY world that has
   * one, so both switches cover the same ground. One press, every world.
   *
   * BOTH START OFF. They used to start drawn, on the reasoning that nobody should
   * have to discover the boundaries by finding a switch. The owner's call is the
   * other way: the galaxy is the subject, and the instruments are something you
   * ask for. `SensorToggles` keeps its struck-through glyph precisely so an unlit
   * switch reads as "off", not as "missing".
   *
   * Remember each device's choice across reloads. Both start off only when there
   * is no saved preference; unavailable storage falls back to this visit's state.
   */
  const [showTelescopeReach, setShowTelescopeReach] = useSensorReach('telescope');
  const [showRadarReach, setShowRadarReach] = useSensorReach('radar');
  const [eventsGuideOpen, setEventsGuideOpen] = useState(false);
  /**
   * THE RADAR SWITCH ONLY EXISTS IF THERE IS A RADAR. Owner instruction.
   *
   * A telescope switch is always meaningful — the naked-eye neighbourhood is free
   * and every commander has one — but a radar circle is hardware, and a control
   * that draws nothing when pressed teaches that the pair is decorative. `detect`
   * is above zero exactly when a world is running a working, Uplink-gated Radar,
   * so this asks the same question the drawing does.
   */
  const hasRadar = sensors.some((post) => post.detect > 0);

  /**
   * Whether the focus rail is expanded. Reset to closed on every new selection —
   * a panel that stayed open as the player swept from world to world would undo
   * the whole point of it opening closed.
   */
  const [detail, setDetail] = useState(false);
  const [attacking, setAttacking] = useState(false);
  /**
   * Which pirate the commitment sheet is open against. D150.
   *
   * Held by ID rather than by the contact itself because the pirate's roster,
   * deadline and rendezvous keep changing. The list can also shrink when a
   * pirate dies, so the sheet always reads the current server entry.
   */
  const [attackingPirateId, setAttackingPirateId] = useState<string | null>(null);
  /**
   * The caller's own fog-filtered sightings, for the disc tally and the pirate launch
   * sheet. D150. Live (traffic pace) only while that sheet is open.
   */
  const pirateList = usePirates({ live: attackingPirateId !== null });
  /**
   * WHERE THE OPEN SHEET WOULD SEND THE WING IT HAS SELECTED. D155.
   *
   * Lifted out of `LaunchSheet` because the rendezvous is a point in the GALAXY
   * and the sheet is a panel over it — the disc is what has to draw it, and the
   * player is choosing hulls at the moment they need to see where those hulls
   * would go. The sheet reports it and clears it on the way out, so a mark can
   * never outlive the decision it belongs to.
   */
  const [aim, setAim] = useState<{ x: number; y: number; z: number } | null>(null);
  /**
   * Whether the merchant's commitment sheet is open. D156.
   *
   * A boolean rather than an id, because there is exactly one merchant in the
   * galaxy at a time and the sheet is rendered from the LIVE payload — so a window
   * that shuts while the sheet is open takes the sheet with it, which is the honest
   * behaviour for an appointment nobody can extend.
   */
  const [trading, setTrading] = useState(false);
  const [strikingConvoy, setStrikingConvoy] = useState(false);
  const [settlingTargetId, setSettlingTargetId] = useState<string | null>(null);
  const [homeSignal, setHomeSignal] = useState(0);
  const [centerSignal, setCenterSignal] = useState(0);
  const reportedLostPlacement = useRef(false);
  useEffect(() => {
    if (
      reportedLostPlacement.current ||
      !(season.error instanceof ApiError) ||
      season.error.code !== 'NO_PLANET'
    ) return;
    reportedLostPlacement.current = true;
    onPlacementLost?.();
  }, [onPlacementLost, season.error]);

  /**
   * THE ONE ENDING, ONCE. D86.
   *
   * The season event invalidates this existing query through `shard:season`; no
   * second result request and no polling loop is introduced. Local storage only
   * remembers that this person closed this season's ceremony — it never stores an
   * outcome. `shownRecap` also prevents repeated effects before storage settles.
   */
  const openSeasonRecap = useCallback(() => {
    onPanel('recap');
  }, [onPanel]);
  /** Where a battle notification lands when its own report cannot be found. */
  const openBattleList = useCallback(() => {
    onPanel('intel', 'battles');
  }, [onPanel]);
  const recapResult = season.data?.result ?? pastResult;
  useSeasonRecapOpening(
    season.data?.result ? season.data.status : pastResult ? 'frozen' : undefined,
    recapResult,
    openSeasonRecap,
  );

  /**
   * FLY HOME WHEN SOMEBODY OUTSIDE ASKS. D56.
   *
   * Skips the very first value so a mount does not count as a request — the rig
   * already frames the opening, and re-triggering it here would fight that with an
   * ease starting from the frame it just set.
   */
  useRequest(goHome, () => {
    setFocus(null);
    setTransferOriginId(null);
    setHomeSignal((n) => n + 1);
  });
  const [viewOpen, setViewOpen] = useState(false);
  /**
   * The context slot's closed cards (B3), kept here because the slot unmounts under every page,
   * and on this device for an event (owner, 2026-09-24: a closed event card came back on every
   * return to the game) — `lib/slotMemory.ts`.
   */
  const [slotDismissed, setSlotDismissed] = useState<ReadonlySet<string>>(() => readDismissed(serverNow()));
  /** The element the scene lends over the active world; the collect bubble is portalled into it. */

  /**
   * THE DISC COMES UP UNDER A COVER, NOT AFTER ONE. Owner decision.
   *
   * Eleven models have to arrive and decode before the galaxy is smooth, and on a
   * phone that is a second or two of a half-built scene: worlds without their
   * instruments, rocks popping in, a stutter as each hull lands. The canvas is
   * mounted and working the whole time this is up — the cover hides the jank
   * rather than delaying the work, which is the point of it being an overlay and
   * not a gate.
   */
  const assets = usePreload(GALAXY_ASSETS);

  /**
   * AND THE COVER STAYS UNTIL THERE IS A GALAXY UNDER IT. Owner decision.
   *
   * It used to come off on `assets.ready && !galaxy.isPending`, and both halves
   * were early. `assets.ready` means the BYTES arrived — the models still have to
   * be parsed, compiled and uploaded, which is the part a phone shows as worlds
   * popping in one at a time. And `galaxy` is one of four payloads the first frame
   * is drawn from: without `planet` there is no home to centre on, without
   * `season` the rocks cannot be placed on their orbits at all, and without
   * `mining` there is no rock field and no wreckage. The disc was uncovered and
   * then visibly assembled itself.
   *
   * So three things now have to be true: the files are in, every first-paint
   * payload has SETTLED, and the canvas has painted a frame with all of it in
   * (`onReady` — see `FirstSceneFrame`).
   *
   * SETTLED, NOT SUCCEEDED. A failed request must open the door: the surfaces
   * below degrade on their own, and a loading screen that outlives the network is
   * a game nobody can reach.
   */
  const [drawn, setDrawn] = useState(false);
  const dataSettled =
    !galaxy.isPending && !planet.isPending && !season.isPending && !mining.isPending;
  const covered = useOpeningCover(assets.ready && dataSettled && drawn);


  // The opening cover owns one seven-second deadline from mount.

  /**
   * THE SOONEST THIS WORLD COULD BE ALONGSIDE THE MERCHANT, AND IT IS A BEST CASE.
   *
   * Solved with the FASTEST CARRIER standing here, because a convoy with no hold
   * is not a trade — so the honest upper bound on opportunity is the quickest
   * craft that could actually carry something. The sheet then quotes the exact
   * minute for the wing actually picked, off the same solver, exactly as the
   * pirate rail and its sheet already split the question.
   *
   * `null` says the appointment cannot be kept from here, and the rail writes that
   * refusal out rather than letting the line quietly disappear.
   */
  /*
    THE SOLVE IS PRICED IN MINUTES, SO IT DEPENDS ON THE MINUTE. D166.

    `now` really is needed — the merchant is on a moving orbit and the rendezvous
    it is solved against moves with it — but the memo listed the raw tick, which
    advances every five seconds and can therefore never hit. That ran a scan plus a
    bisection over a three-hour horizon twelve times a minute, on the main thread
    beside the 3D scene, to produce a figure printed in whole minutes.
  */
  const tradeMinute = minuteTick(now);
  const tradeReach = useMemo(() => {
    if (!tradeShip || !planet.data || !season.data) return null;
    const home = planet.data;
    const carriers = MOBILE_HULLS.filter(
      (hull) => (home.fleet[hull] ?? 0) > 0 && transferCargoCapacity({ [hull]: 1 }, UNAIDED.tech) > 0,
    );
    const quickest = carriers.reduce<MobileHullId | null>(
      (best, hull) => (best === null || HULLS[hull].speed > HULLS[best].speed ? hull : best),
      null,
    );
    if (quickest === null) return null;
    const route = planTradeRoute(
      home.planet.position,
      { orbit: tradeShip.orbit, expiresAtMinute: tradeShip.expiresAtMinute },
      (tradeMinute * 60_000 - season.data.startsAt.getTime()) / 60_000,
      { [quickest]: 1 },
      home.fleet,
      home.ground,
      flightModifiers(home),
    );
    return route?.oneWayMinutes ?? null;
  }, [tradeShip, planet.data, season.data, tradeMinute]);

  const convoyReach = useMemo(() => {
    if (!intergalacticConvoy || !planet.data || !season.data) return null;
    const home = planet.data;
    const armed = MOBILE_HULLS.filter(
      (hull) => (home.fleet[hull] ?? 0) > 0 && combatValue({ [hull]: 1 }) > 0,
    );
    let best: number | null = null;
    for (const hull of armed) {
      const route = planIntergalacticConvoyRoute(
        home.planet.position,
        intergalacticConvoy,
        (tradeMinute * 60_000 - season.data.startsAt.getTime()) / 60_000,
        { [hull]: 1 },
        home.fleet,
        home.ground,
        flightModifiers(home),
      );
      if (route && (best === null || route.oneWayMinutes < best)) best = route.oneWayMinutes;
    }
    return best;
  }, [intergalacticConvoy, planet.data, season.data, tradeMinute]);

  const planets = useMemo(() => planetsWithClanPresence(galaxy.data), [galaxy.data]);
  const trialWorlds = useMemo(() => planets.filter(world => world.isOwned && world.intel !== 'UNKNOWN'), [planets]);
  const trialBoostUntil = worlds.find(world => world.planet.id === cosmeticTrial?.planetId)?.planet.productionBoostUntil ?? null;
  const trialStatus = planetSkinStatus(trialBoostUntil, new Date(now));
  const displayPlanets = useMemo(() => applyCosmeticTrial(planets, cosmeticTrial, trialStatus), [planets, cosmeticTrial, trialStatus]);
  useEffect(() => {
    if (cosmeticTrial && (panel !== null || !trialWorlds.some(world => world.id === cosmeticTrial.planetId))) setCosmeticTrial(null);
  }, [panel, cosmeticTrial, trialWorlds]);
  useEffect(() => {
    if (!cosmeticTrial) return;
    const escape = (event: KeyboardEvent) => { if (event.key === 'Escape') setCosmeticTrial(null); };
    window.addEventListener('keydown', escape);
    return () => { window.removeEventListener('keydown', escape); };
  }, [cosmeticTrial]);
  /*
    WHAT A BATTLE REPORT IS HANDED, from a notification or from Intel's list (M4): whether
    the other side is a colony (its loyalty line), the mark it wears, and — in a clan only —
    the door that tells the clan: clan chat, opened with the report's line as a draft.
  */
  const reportDoors: ReportDoors = {
    onFocusMonument: (id) => { onPanel(null); setFocus({ kind: 'monument', id }); setDetail(true); setAttacking(false); },
    onFocusPlanet: (planetId: string) => {
      onPanel(null);
      focusPlanet(planetId);
      setDetail(true);
    },
    colonyOf: (planetId: string) => planets.find((world) => world.id === planetId)?.kind === 'COLONY',
    rivalOf: (planetId: string) => season.data?.rivals.find((mark) => mark.planetId === planetId)?.slot ?? null,
    ...(onOpenChat && clanBadge.data?.membership
      ? { onShare: (line: string) => { onOpenChat('clan', line); } }
      : {}),
  };
  /**
   * CAMERA HOME COMES FROM THE DISC IT MOVES OVER.
   *
   * Multi-world selection made `planet.data` and `galaxy.data` two independently
   * refreshing views of the active world. Using the former to aim at a body drawn
   * from the latter let one stale frame send Home to coordinates with no rendered
   * planet. Resolve the active id inside the exact array the canvas renders.
   */
  const activeWorldPosition = useMemo(
    () => planets.find((world) => world.id === activePlanetId)?.position
      ?? planet.data?.planet.position,
    [activePlanetId, planet.data, planets],
  );
  const miningScene = useMemo(
    () => miningSceneData(mining.fieldData, mining.statusData),
    [mining.fieldData, mining.statusData],
  );
  const asteroids = miningScene.asteroids;
  const runs = miningScene.runs;
  const wrecks = miningScene.debris;
  // The monument payload carries the server-time snapshot used for its flight
  // visibility.  Rebuilding this array on the five-second HUD clock made the
  // 3D fleet tree churn even though no flight data had changed; countdown text
  // is derived from each thread's arrival instant where it is displayed.
  const monumentThreads = useMemo(() => monumentPendingThreads(monumentCatalog.data), [monumentCatalog.data]);
  const threads = useMemo(() => [...pending.data?.pending ?? [], ...monumentThreads], [pending.data, monumentThreads]);
  const contacts = useMemo(() => traffic.data?.contacts ?? [], [traffic.data]);
  /* The corner lists pirates the Telescope has identified, including remembered ones.
     Radar-only returns stay anonymous on the disc and outside this named tally. */
  const knownPirates = useMemo(() => knownPirateContacts(contacts), [contacts]);
  const findableTargets = useMemo<GalaxyTarget[]>(() => [
      ...monumentFinderTargets(galaxy.data?.monuments ?? [], t),
      ...asteroids.map((rock, index) => ({
        kind: 'asteroid' as const,
        id: rock.id,
        label: `${t('focus.run.targetRock', { level: rock.level })} #${String(index + 1)}`,
        detail: t('galaxy.targetOre', { amount: compact(rock.oreRemaining) }),
      })),
      ...knownPirates.map((contact) => {
        const pirate = pirateList.data?.pirates.find((candidate) => candidate.id === contact.id);
        const name = pirate ? pirateTargetName(pirate) : null;
        return {
          kind: 'contact' as const,
          id: contact.id,
          label: name?.key === 'pirate.name'
            ? t(name.key, { level: name.level, callsign: name.callsign })
            : t('focus.contact.titlePirate'),
          detail: pirate
            ? t('galaxy.targetMinutes', { count: Math.ceil(pirate.expiresInMinutes) })
            : contact.level === undefined ? '' : t('pirate.eyebrow', { level: contact.level }),
        };
      }),
      ...wrecks.map((field) => ({
        kind: 'debris' as const,
        id: field.id,
        label: field.planetId === null
          ? t('focus.debris.titleUnknown')
          : t('focus.debris.titleOver', { planet: planets.find((world) => world.id === field.planetId)?.name ?? '' }),
        detail: t('galaxy.targetResources', { amount: compact(field.alloy + field.crystal + field.deuterium) }),
      })),
    ], [galaxy.data?.monuments, season.data?.monumentHonorees, asteroids, knownPirates, pirateList.data?.pirates, planets, t, wrecks]);
  const interceptions = useMemo(() => traffic.data?.interceptions ?? [], [traffic.data]);
  const interceptionImpacts = useMemo(
    () => traffic.data?.interceptionImpacts ?? [],
    [traffic.data],
  );
  const controlledPlanetIds = useMemo(
    () => new Set(planets.filter((world) => world.isOwned).map((world) => world.id)),
    [planets],
  );

  /**
   * An interceptor is not a pending mission: it lives for eight seconds in the
   * participant/Telescope traffic projection. Focus a newly appearing one only
   * when its defended target is one of this commander's worlds. That includes a
   * colony without changing the active management world, and excludes the enemy
   * battery that happens to destroy this commander's outgoing Death Star.
   */
  const seenOwnInterceptions = useRef<ReadonlySet<string> | null>(null);
  useEffect(() => {
    if (traffic.data === undefined || galaxy.data === undefined) return;
    const result = reconcileOwnInterceptions(
      seenOwnInterceptions.current,
      interceptions,
      controlledPlanetIds,
      serverNow(),
    );
    seenOwnInterceptions.current = result.seen;
    if (!result.focus) return;
    setFocus(result.focus);
    setTransferOriginId(null);
    setDetail(false);
    setAttacking(false);
  }, [controlledPlanetIds, galaxy.data, interceptions, traffic.data]);

  /**
   * If the short launch scene was missed, centre the defending commander on the
   * collision when its public effect arrives. Attackers and witnesses retain
   * their camera. The distinct collision focus also closes the race where launch
   * focus was recorded but its short traffic row vanished before the rig read it.
   */
  const seenOwnInterceptionImpacts = useRef<ReadonlySet<string> | null>(null);
  useEffect(() => {
    if (traffic.data === undefined) return;
    const result = reconcileOwnInterceptionImpacts(
      seenOwnInterceptionImpacts.current,
      interceptionImpacts,
    );
    seenOwnInterceptionImpacts.current = result.seen;
    if (!result.focus) return;
    setFocus(result.focus);
    setTransferOriginId(null);
    setDetail(false);
    setAttacking(false);
  }, [interceptionImpacts, traffic.data]);

  /** Academy: a camera move the lesson asked for, with no rail behind it. */
  const handledCoachFocus = useRef<number | null>(null);
  useEffect(() => {
    if (!coachFocus || handledCoachFocus.current === coachFocus.request) return;
    handledCoachFocus.current = coachFocus.request;
    setFocus(coachFocus.focus);
    setTransferOriginId(null);
    setDetail(false);
    setAttacking(false);
  }, [coachFocus]);

  const handledCraftFocusRequest = useRef<number | null>(null);
  useEffect(() => {
    if (
      !craftFocusRequest
      || handledCraftFocusRequest.current === craftFocusRequest.request
    ) return;
    const requested = craftFocusRequest.focus;
    /*
      THE CRAFT HAS TO STILL BE THERE. Three kinds now: a mining run, one of your
      own threads, and — since the inbound warning became pressable — a public
      contact on the disc, which is exactly the state a tap on a foreign fleet
      produces. D163.
    */
    const exists = requested.kind === 'monument' ? (galaxy.data?.monuments ?? []).some((row) => row.id === requested.id) : requested.kind === 'run'
      ? runs.some((run) => run.id === requested.id && run.status !== 'done')
      : requested.kind === 'contact'
        ? contacts.some((c) => c.id === requested.id)
        : threads.some((thread, index) => threadKey(thread, index) === requested.key && thread.path);
    if (!exists) return;
    handledCraftFocusRequest.current = craftFocusRequest.request;
    setFocus(requested);
    setTransferOriginId(null);
    setDetail(requested.kind === 'monument');
    setAttacking(false);
  }, [craftFocusRequest, runs, threads, contacts, galaxy.data?.monuments]);

  /**
   * EVERY PROP THE DISC TAKES IS STABLE. D53.
   *
   * This component holds a clock, so it re-renders on a timer whether or not
   * anything about the galaxy has changed. That is meant to be free — React
   * reconciles, nothing below it sees a changed prop, nothing is rebuilt.
   *
   * `contacts` is memoised for the same reason rather than because it churns —
   * React Query's structural sharing keeps it stable while the payload is
   * unchanged, but only while `traffic.data` is DEFINED; the `?? []` fallback
   * before the first fetch was a fresh array each time.
   */
  const onReady = useCallback(() => {
    setDrawn(true);
  }, []);
  const onFocus = useCallback(
    (next: Focus | null) => {
      setCosmeticTrial(null);
      if (next) haptic('tap');
      const ownedId = next?.kind === 'planet' ? controlledWorldId(planets, next.id) : null;
      const decision = focusTapDecision(focus, next, ownedId);
      if (decision.kind === 'manage') {
        selectPlanet(decision.planetId);
        setFocus(null);
        setTransferOriginId(null);
        setDetail(false);
        setAttacking(false);
        onPanel('planet');
        onFocused?.(next);
        return;
      }
      setTransferOriginId(planetFocusSelection(activePlanetId, ownedId).transferOriginId);
      setFocus(decision.focus);
      setDetail(decision.detail);
      setAttacking(false);
      onFocused?.(next);
    },
    [activePlanetId, focus, onFocused, onPanel, planets, selectPlanet],
  );
  const focusPlanet = useCallback(
    (planetId: string, intent: 'focus' | 'select' = 'focus') => {
      const target = planets.find((candidate) => candidate.id === planetId);
      if (!target) return;
      const next: Focus = { kind: 'planet', id: planetId };
      const ownedId = controlledWorldId(planets, planetId);
      const selection = planetFocusSelection(activePlanetId, ownedId, intent);
      setTransferOriginId(selection.transferOriginId);
      if (selection.activePlanetId !== null && selection.activePlanetId !== activePlanetId) {
        selectPlanet(selection.activePlanetId);
      }
      setFocus(next);
      setDetail(false);
      setAttacking(false);
      onFocused?.(next);
    },
    [activePlanetId, onFocused, planets, selectPlanet],
  );
  const handledFocusRequest = useRef<number | null>(null);
  useEffect(() => {
    if (!focusRequest || handledFocusRequest.current === focusRequest.request) return;
    if (!planets.some((candidate) => candidate.id === focusRequest.planetId)) return;
    handledFocusRequest.current = focusRequest.request;
    focusPlanet(focusRequest.planetId, focusRequest.select === true ? 'select' : 'focus');
    if (focusRequest.dossier) setDetail(true);
  }, [focusPlanet, focusRequest, planets]);

  /**
   * REFETCH THE MOMENT ANYTHING LANDS.
   *
   * Every list here draws its craft by interpolating between two timestamps, and
   * that interpolation clamps — so a craft whose list has gone stale does not turn
   * for home or disappear, it sits on its target. See `useArrivals`; the instants
   * are gathered here because this is the one place that holds all four lists.
   *
   * A mining run's next event is its arrival on the way out and its landing on the
   * way back, so both are offered and the hook takes whichever is sooner.
   */
  useArrivals(
    useMemo(
      () => [
        planet.data?.vacationUntil,
        ...threads.map((t) => t.arriveAt),
        /**
         * AND THE INSTANT THE BATTLE IS ACTUALLY SETTLED. D44, D45.
         *
         * A raid reaches its target at `arriveAt` and is decided ten seconds
         * later, and only `arriveAt` was offered here. So the one refetch an
         * attacker got landed while the mission was still in flight and nothing
         * had happened yet: the strip still counted a fleet that was over its
         * target, the report did not exist, and the next refresh was whenever a
         * poll or a focus event came along. The player watched the bombardment
         * play out and the interface never acknowledged it.
         *
         * A return leg lands at `arriveAt` with no window at all, and a probe has
         * none either — only an outbound fleet is going to fight.
         */
        ...threads
          .filter((t) => t.kind === 'fleet' && t.leg === 'outbound')
          .map((t) => new Date(engagementEndsAt(t.arriveAt.getTime()))),
        ...runs.map((r) => (r.status === 'returning' ? r.homeAt : r.arriveAt)),
        /**
         * AND SOMEBODY ELSE'S BATTLE, WHICH IS NOW EVERYBODY'S. D52.
         *
         * A bystander has no pending thread of their own, so nothing here was ever
         * armed for a raid they are only WATCHING — their traffic list arrived on a
         * poll, which was that many seconds of a squadron hanging over a world with
         * its volley finished. Both edges are offered: the landing, so the
         * bombardment starts on the instant, and the settlement, so the wreck of it
         * clears the moment the server says so.
         *
         * These stay in the FULL refresh while a contact's plain window end does
         * not (D72): a battle resolving really does move the planet, the reports
         * and the debris on `mining`, where a bearing window expiring moves only
         * `traffic`.
         */
        ...(traffic.data?.contacts ?? []).flatMap((c) =>
          c.engagement ? [c.engagement.arriveAt, c.engagement.endsAt] : [],
        ),
      ],
      [threads, runs, traffic.data, planet.data?.vacationUntil],
    ),
  );

  const selected = focus?.kind === 'planet' ? planets.find((p) => p.id === focus.id) : undefined;
  const selectedClanId = selected?.clan?.id;
  const clanTarget = clanTargetDecision({
    leader: clanBadge.data?.membership?.role === 'LEADER',
    available: clanWar.data?.available === true,
    realForeignPlayer: selected?.controller?.kind === 'PLAYER'
      && selected.intel !== 'UNKNOWN' && selected.isOwned !== true,
    sameClan: selectedClanId !== undefined
      && selectedClanId === clanBadge.data?.membership?.clanId,
    operationOpen: clanWar.data?.operation != null
      && clanWar.data.operation.status !== 'COMPLETED',
    seasonEndsAt: season.data?.endsAt ?? null,
    now,
  });
  const transferOrigin = transferOriginId === null
    ? undefined
    : worlds.find((world) => world.planet.id === transferOriginId);
  const focusedPlanet = selected?.isOwned && transferOrigin ? transferOrigin : planet.data;
  const showPlanetFocus = selected
    ? planetFocusRailVisible(selected.isOwned === true, transferOriginId)
    : false;
  /** Something on the disc has the screen (B3): the context slot yields, the event chips step aside. */
  const slotSelected = showPlanetFocus || (focus !== null && !(focus.kind === 'planet' && focus.id === activePlanetId));
  const settlementInFlight = selected !== undefined && threads.some((thread) =>
    thread.kind === 'settlement'
    && thread.leg === 'outbound'
    && thread.targetPlanetId === selected.id);

  const close = (): void => {
    setFocus(null);
    setTransferOriginId(null);
    setDetail(false);
    setAttacking(false);
    setTrading(false);
    setStrikingConvoy(false);
    setSettlingTargetId(null);
  };

  // The shell's requests, answered once each (`useRequest`): see `homeRequest`.
  /** K6: the Base's two pages, one switch apart. */
  const openBase = (view: BaseView): void => {
    setResearchFocus(null);
    onPanel(view === 'world' ? 'planet' : view === 'ship' ? 'ship' : 'research');
  };
  const arenaAvailable = onEnterArena !== undefined;

  const tryCosmetic = (cosmeticId: CosmeticId): void => {
    const item = cosmeticById(cosmeticId);
    if (item?.category !== 'PLANET' && item?.category !== 'RING') return;
    const target = trialWorlds.find(world => world.id === activePlanetId) ?? trialWorlds[0];
    if (!target) return;
    close();
    onPanel(null);
    focusPlanet(target.id);
    setCenterSignal(n => n + 1);
    setShopSelection(cosmeticId);
    setCosmeticTrial({ planetId: target.id, cosmeticId, enabled: true });
  };

  /** Home, the disc's old mark (D163): clear the focus, focus the active world, raise the home signal. */
  const flyHome = (): void => {
    if (activePlanetId === null) return;
    close();
    focusPlanet(activePlanetId);
    setHomeSignal((n) => n + 1);
  };
  useRequest(homeRequest, flyHome);
  useRequest(worldsRequest, () => { setWorldsOpen(true); });
  useRequest(centerRequest, () => {
    if (focus === null) flyHome();
    else setCenterSignal((n) => n + 1);
  });
  useRequest(clearRequest, () => { if (focus !== null) close(); });

  /**
   * CHAT'S BUTTON, LOW ON THE RIGHT (owner, 2026-09-24): back where it was, above the dock,
   * where a thumb reaches it — people chat live, and it keeps them coming back. It rides the
   * context slot's corner so it stands above a card and never under one.
   */
  const chatButton = showGuidance && showChat
    ? <ChatChip unread={chatUnread + dmUnread + (clanBadge.data?.clanChatUnread ?? 0)} onOpen={() => { onPanel('chat'); }} />
    : null;
  /** Daily activity and the galaxy's objects (top right). */
  const galaxyReadout = {
    ...(season.data?.onlineToday === undefined ? {} : { onlineToday: season.data.onlineToday }),
    counts: {
      worlds: planets.length,
      fleetsAway: windowsOpen(planets),
      rocks: asteroids.length,
      pirates: knownPirates.length,
      wrecks: wrecks.length,
      monuments: galaxy.data?.monuments?.length ?? 0,
    },
  };
  /** The context slot draws at the foot while the season is live and no page is open. */
  const slotShown = showGuidance && Boolean(planet.data) && panel === null && !cosmeticTrial && season.data?.status === 'live';

  const toggle = (): void => {
    setDetail((open) => !open);
  };

  /**
   * THE WAY BACK TO THE MENU, for the surfaces the menu is the only door onto.
   *
   * Owner report: *"yanlış bir buton'a tıklayınca geri dönme yok direk
   * kapatılıyor"*. A menu tile REPLACES the menu, so closing what it opened landed
   * the reader on the disc — the price of one mis-tap was the header control plus
   * finding your place in the list again.
   *
   * `returnsToMenu` decides, so the set is a rule with a test rather than six
   * hand-written props that a seventh sheet can quietly disagree with. Spread
   * rather than passed, because a sheet with nowhere to go back to must not draw
   * the arrow at all.
   */
  const menuBack = returnsToMenu(panel) ? { onBack: () => { onPanel('menu'); } } : {};

  return (
    <SeasonLockProvider locked={season.data?.status === 'frozen'} vacation={Boolean(planet.data?.vacationUntil && planet.data.vacationUntil.getTime() > now)}>
    <div className="absolute inset-0 overflow-hidden">
      <GalaxyCanvas
        cosmeticAppearance={{ engineId: cosmetics.data?.equipment?.ENGINE,
          probeId: cosmetics.data?.equipment?.PROBE, flagId: cosmetics.data?.clanFlagId ?? undefined,
          shipSkins: cosmetics.data?.equipment?.SHIP }}
        planets={displayPlanets}
        unknownSignals={signalData?.signals}
        unknownSignalRadar={focusedSignalId ? personalSignals.data?.radar ?? undefined : undefined}
        inspectionPlanetId={cosmeticTrial?.planetId}
        pending={threads}
        contacts={contacts}
        interceptions={interceptions}
        interceptionImpacts={interceptionImpacts}
        asteroids={asteroids}
        runs={runs}

        wrecks={wrecks}
        meteorShower={meteorShower}
        tradeShip={tradeShip}
        intergalacticConvoy={intergalacticConvoy}
        sensors={sensors}
        {...(galaxy.data?.radiation ? { radiation: galaxy.data.radiation } : {})}
        {...(galaxy.data?.hpRadiation ? { hpRadiation: galaxy.data.hpRadiation } : {})}
        {...(galaxy.data?.monuments ? { monuments: galaxy.data.monuments } : {})}
        showTelescopeReach={showTelescopeReach}
        showRadarReach={showRadarReach}
        {...(activeWorldPosition ? { homePosition: activeWorldPosition } : { homePosition: undefined })}
        activePlanetId={activePlanetId}
        aegisLevel={planet.data?.instruments.AEGIS ?? 0}
        {...(season.data ? { seasonStart: season.data.startsAt } : { seasonStart: undefined })}
        rivals={season.data?.rivals ?? []}
        focus={focus}
        onReady={onReady}
        openingDataReady={dataSettled}
        openingCovered={covered}
        onFocus={onFocus}
        homeSignal={homeSignal}
        centerSignal={centerSignal}
        openingHome={openingHome}
        aim={aim}
        coachTap={coachTap}
        openWide={openWide ?? false}
        {...(wideDistance !== undefined ? { wideDistance } : {})}
        {...(frameTelescope ? { sightRadius: Math.max(0, ...sensors.map((post) => post.identify)) / VIEW.scale } : {})}
        {...(allowFocus ? { allowFocus } : {})}
      />

      {/*
        ── ONE THING PER CORNER (K1). ──────────────────────────────────────────

        The disc's caption, the sensor switches, the four marks (`DiscControls`) and
        the chat and chronicle launchers all left this layer with the v2 shell: the
        dock carries Base, Fleet, Intel and Clan (and Galaxy pressed again flies
        home), the bell carries chat and the chronicle, the world mark opens the
        Worlds sheet, and the caption and switches sit in the View sheet behind the
        one chip at top right, which the Academy hides with the sensor switches
        until its Telescope exercise (`data-sensor-toggles`).
      */}
      <div data-galaxy-top-corners="" className="pointer-events-none absolute inset-x-0 top-0 flex items-start justify-between p-2 pt-1">
        <div className="pointer-events-none flex min-w-0 flex-col items-start gap-1">
          <UnknownSignalHud data={signalData} planet={planet.data} worlds={worlds}
            focusedId={focus?.kind === 'unknownSignal' ? focus.id : null}
            busy={signalActions.send.isPending || signalActions.recall.isPending}
            error={signalActions.send.error ? describe(signalActions.send.error) : signalActions.recall.error ? describe(signalActions.recall.error) : null}
            onFocus={id => { onPanel(null); onFocus({ kind: 'unknownSignal', id }); }} onClose={close} onOrigin={selectPlanet}
            onSend={(id, hull) => {
              if (!planet.data) return;
              signalActions.send.mutate({ id, originPlanetId: planet.data.planet.id, fleet: { [hull]: 1, COURIER: 1 }, key: createIdempotencyKey() },
                { onSuccess: () => { say(t('unknownSignal.sent')); }, onError: error => { say(describe(error), 'error'); } });
            }}
            onBuild={hull => { close(); onPanel('planet'); setRequestedPlanetGroup('reach'); setRequestedItem(hull === 'COURIER' && (planet.data?.buildings.SHIPYARD ?? 0) < 1 ? 'SHIPYARD' : hull); }}
            onSkins={() => { close(); onPanel('skin-inventory'); }} onDetected={() => { say(t('unknownSignal.detected')); }} />
          {/*
            THE EVENTS RUNNING NOW, with their time left (owner, 2026-09-24): the context card
            says it once and is closed; this stays. Not while something is selected — the
            selection keeps its screen (B3), and the attack pill takes this corner then.
          */}
          {showGuidance && season.data?.status === 'live' && !slotSelected && (
            <EventChips
              events={activeEvents(galaxyEvents.data?.events ?? [], now)}
              now={now}
              onOpen={(event) => {
                if (event.kind === 'TRADE_SHIP') setFocus({ kind: 'tradeShip', id: event.id });
                else if (event.kind === 'INTERGALACTIC_CONVOY') setFocus({ kind: 'intergalacticConvoy', id: event.id });
                else { setEventsGuideOpen(true); return; }
                setDetail(true);
              }}
            />
          )}
          <FpsReadout />
        </div>

        {/*
          THE PICK-VOLUME COLOUR KEY. Off unless `?hitboxes=1` asked for it, and it
          renders nothing at all in that state — see `galaxy/hitboxDebug`.
        */}
        <HitboxLegend />

        {/*
          `data-sensor-toggles`, not `data-disc-controls`: the chip carries the sensor
          switches now, and the Academy reveals it with them for its Telescope exercise.
        */}
        <div className="pointer-events-none flex flex-col items-end gap-1.5">
          {/* What is out there, at a glance (owner, 2026-09-24): back at the top right. */}
          {showGuidance && <GalaxyReadout {...galaxyReadout} targets={findableTargets} onFocusTarget={onFocus} />}
          {/* Home, back in plain sight and first in the stack (owner, 2026-09-24): never under a card or a rail. */}
          {showGuidance && <HomeChip onHome={flyHome} />}
          <div data-sensor-toggles className="pointer-events-none">
            <ViewChip layersOn={showTelescopeReach || (hasRadar && showRadarReach)} onOpen={() => { setViewOpen(true); }} />
          </div>
        </div>
      </div>

      {viewOpen && (
        <ViewSheet
          shard={season.data?.shard ?? ''}
          telescope={showTelescopeReach}
          onToggleTelescope={() => { setShowTelescopeReach((on) => !on); }}
          {...(hasRadar
            ? { radar: showRadarReach, onToggleRadar: () => { setShowRadarReach((on) => !on); } }
            : {})}
          onOpenEvents={() => {
            setViewOpen(false);
            setEventsGuideOpen(true);
          }}
          onClose={() => { setViewOpen(false); }}
        />
      )}

      {/*
        The colour legend that used to sit down here is gone (owner decision). It
        explained the stance colours to a player who had no reason to be reading a
        key — and now that tapping a world says what it is in words, the panel is
        both the explanation and the answer.
      */}

      {/* ── focus ───────────────────────────────────────────── */}

      {!coachFocus && focus?.kind === 'monument' && !detail && galaxy.data?.monuments?.find((row) => row.id === focus.id) && (
        <MonumentFocus monument={galaxy.data.monuments.find((row) => row.id === focus.id)!}
          onInspect={() => { setDetail(true); }} onClose={close} />
      )}
      {!coachFocus && focus?.kind === 'monument' && detail && planet.data && galaxy.data && (
        <MonumentSheet key={`${focus.id}:${planet.data.planet.id}`} monumentId={focus.id} origin={planet.data} playerId={galaxy.data.you.playerId}
          clanId={clanBadge.data?.membership?.clanId ?? null} onClose={() => { setDetail(false); }}
          {...(clanBadge.data?.membership?.role === 'LEADER' && clanWar.data?.available === true && planet.data.silentSpace !== true
            && (clanWar.data.operation === null || clanWar.data.operation.status === 'COMPLETED') ? { onClanTarget: (monumentId: string) => {
              clanWarActions.monumentTarget.mutate(monumentId, { onSuccess: () => { setFocus(null); setDetail(false); setClanInitialTab('war'); onPanel('clan'); },
                onError: (error: Error) => { say(describe(error), 'error'); } });
            } } : {})} />
      )}
      {!cosmeticTrial && !coachFocus && focus?.kind === 'planet' && selected && focusedPlanet && showPlanetFocus && !attacking && (
        <PlanetFocus
          target={selected}
          planet={focusedPlanet}
          intel={intel.data}
          reports={reports.data?.reports ?? []}
          rival={reports.data?.rivals.find((rival) =>
            selected.controller?.kind === 'PLAYER'
              ? rival.playerId === selected.controller.playerId
              : rival.planetId === selected.id)}
          /*
            WHICH MARK THIS WORLD WEARS, IF ANY. D183.

            The rail reads the slot rather than a boolean so it can draw the mark's
            own colour beside the control — five identical reticles would be five
            marks and no information.
          */
          rivalSlot={rivalSlotFor(season.data?.rivals ?? [], selected)}
          now={now}
          showClanTargetAction={clanTarget.visible}
          clanTargetReason={clanTarget.reason ? t(`clanWar.${clanTarget.reason}`) : null}
          clanTargetPending={clanWarActions.target.isPending}
          onMarkClanTarget={() => {
            clanWarActions.target.mutate(selected.id, {
              onSuccess: () => {
                setClanInitialTab('war');
                close();
                onPanel('clan');
              },
              onError: (error) => { say(describe(error), 'error'); },
            });
          }}
          settlementInFlight={settlementInFlight}
          onSendSupport={() => {
            setSupportHost({ planetId: selected.id, planetName: selected.name, ownerName: selected.owner });
          }}
          onClose={close}
          onLaunched={() => {
            close();
          }}
          onAttack={() => {
            setAttacking(true);
          }}
          {...(transferOrigin ? {
            onTransfer: () => {
              setTransferTargetId(selected.id);
            },
          } : {})}
          /*
            A DISPATCH TOAST NAMES ITS DESTINATION, AND AN UNSURVEYED WORLD HAS NO
            NAME TO GIVE IT. D127. Both of these controls can now be reached on a
            world the caller cannot see — the settlement because a live claim
            window survives the fog (D112), the strike because there is no
            development gate left to stop it — so both had to stop assuming the
            payload carried a name.
          */
          onSettle={() => {
            setSettlingTargetId(selected.id);
          }}
          /*
            THE HALF OF D168 THE DISC CAN PROVE. `lib/band.ts` carries the whole
            argument; what matters here is that this screen is already holding
            every world the caller can see, so the answer costs one pass and no
            request. It only ever refuses "further developed than you" — the
            other direction is unprovable through fog and stays with the server.
          */
          outOfBand={outOfBandAbove(planets, selected)}
          ownPeakCore={ownPeakCore(planets)}
          onDeathStar={() => {
            deathStar.mutate(selected.id, {
              onSuccess: () => {
                say(t('galaxy.deathStarAway', {
                  world: selected.intel === 'UNKNOWN'
                    ? t('focus.planet.unsurveyedTitle')
                    : selected.name,
                }));
                close();
              },
              onError: (error) => { say(describe(error), 'error'); },
            });
          }}
          onInstallTelescope={() => {
            onPanel('planet');
          }}
          open={detail}
          onToggle={toggle}
        />
      )}

      {!coachFocus && focus?.kind === 'debris' && (
        <DebrisFocusHost
          field={wrecks.find((d) => d.id === focus.id)}
          planets={planets}
          runs={runs}
          mining={miningScene.mining}
          homePosition={activeWorldPosition}
          busy={harvest.isPending}
          open={detail}
          onToggle={toggle}
          onClose={close}
          onSend={(fieldId, craft) => {
            harvest.mutate(
              { fieldId, craft },
              {
                onSuccess: (r) => {
                  say(
                    t('galaxy.harvestAway', {
                      count: r.craft,
                      minutes: Math.round(r.flightMinutes),
                    }),
                  );
                  close();
                },
                onError: (err) => {
                  say(describe(err), 'error');
                },
              },
            );
          }}
        />
      )}

      {!coachFocus && focus?.kind === 'asteroid' && season.data && (
        <AsteroidFocusHost
          rock={asteroids.find((a) => a.id === focus.id)}
          runs={runs}
          mining={miningScene.mining}
          seasonStart={season.data.startsAt}
          homePosition={activeWorldPosition}
          now={now}
          busy={mine.isPending}
          open={detail}
          onToggle={toggle}
          onClose={close}
          onSend={(id, craft) => {
            mine.mutate(
              { asteroidId: id, craft },
              {
                onSuccess: (r) => {
                  say(
                    t('galaxy.miningAway', {
                      count: r.craft,
                      minutes: Math.round(r.flightMinutes),
                    }),
                  );
                  close();
                },
                onError: (err) => {
                  say(describe(err), 'error');
                },
              },
            );
          }}
        />
      )}

      {/*
        THE MERCHANT'S RAIL. D156.

        Rendered from the live event rather than from a captured object, exactly as
        the pirate rail is: an appointment that has ended takes its own surface with
        it instead of offering a launch the server would refuse.
      */}
      {!coachFocus && focus?.kind === 'tradeShip' && tradeShip?.id === focus.id && (
        <TradeFocus
          merchant={tradeShip}
          fleetAtHome={planet.data?.fleet ?? {}}
          fleetAway={planet.data?.fleetAway ?? {}}
          minutesLeft={Math.max(0, (tradeShip.endsAt.getTime() - now) / 60_000)}
          reachMinutes={tradeReach}
          launchBlock={launchFault(planet.data?.faults, 'fleet', planet.data?.silentSpace === true)}
          onClose={close}
          onTrade={() => { setTrading(true); }}
          open={detail}
          onToggle={toggle}
        />
      )}

      {!coachFocus
        && focus?.kind === 'intergalacticConvoy'
        && intergalacticConvoy?.id === focus.id
        && (
          <IntergalacticConvoyFocus
            convoy={intergalacticConvoy}
            minutesLeft={Math.max(
              0,
              (intergalacticConvoy.endsAt.getTime() - now) / 60_000,
            )}
            reachMinutes={convoyReach}
            hasCombatCraft={combatValue(planet.data?.fleet ?? {}) > 0}
            launchLocked={planet.data?.convoyLaunchLocked === true}
            occurrenceSpent={planet.data?.convoyOccurrenceSpent === true}
            launchBlock={launchFault(planet.data?.faults, 'fleet', planet.data?.silentSpace === true)}
            onClose={close}
            onRaid={() => { setStrikingConvoy(true); }}
            open={detail}
            onToggle={toggle}
          />
        )}

      {!coachFocus && focus?.kind === 'run' &&
        (() => {
          const run = runs.find((r) => r.id === focus.id);
          if (!run) return null;
          const target = run.status === 'returning' ? run.homeAt : run.arriveAt;
          /**
           * A HARVEST HAS NO ROCK. D32.
           *
           * `asteroidId` is null on a salvage run, so the rock lookup below can
           * only ever miss — and a miss is what `RunFocus` renders as "Rock has
           * passed". The field is the target, and it is in the same payload.
           */
          const field =
            run.debrisFieldId === null
              ? undefined
              : wrecks.find((d) => d.id === run.debrisFieldId);
          return (
            <RunFocus
              run={run}
              recalling={recallMining.isPending}
              onRecall={() => {
                recallMining.mutate({ runId: run.id, ...(run.planetId ? { originPlanetId: run.planetId } : {}) }, {
                  onSuccess: () => { say(t('pendingStrip.recallStarted')); },
                  onError: (error) => { say(describe(error), 'error'); },
                });
              }}
              rock={asteroids.find((a) => a.id === run.asteroidId)}
              wreck={
                run.targetKind === 'debris'
                  ? field && {
                      planetName: planets.find((p) => p.id === field.planetId)?.name,
                      minutesLeft: field.minutesLeft,
                    }
                  : undefined
              }
              minutesRemaining={target ? minutesLeft(target, now) : 0}
              onClose={close}
              open={detail}
              onToggle={toggle}
            />
          );
        })()}

      {!coachFocus && focus?.kind === 'thread' &&
        (() => {
          const index = threads.findIndex((t, i) => threadKey(t, i) === focus.key);
          const thread = threads[index];
          // The thread landed between the tap and the render. Dropping the
          // selection is honest — there is nothing there any more.
          if (!thread) return null;
          return (
            <ThreadFocus
              onFocusMonument={(id) => { setFocus({ kind: 'monument', id }); setDetail(true); setAttacking(false); }}
              thread={thread}
              recalling={recallFlight.isPending}
              onRecall={() => {
                const input = flightRecallInput(thread);
                if (!input) return;
                recallFlight.mutate(input, {
                  onSuccess: () => { say(t('pendingStrip.recallFleetStarted')); },
                  onError: (error) => { say(describe(error), 'error'); },
                });
              }}
              /**
               * OFF THE CLOCK, NOT OFF THE PAYLOAD.
               *
               * `minutesRemaining` is computed on the server at request time and
               * rounded to a whole minute, and `pending` refetches once a minute —
               * so this rail sat on a figure that was up to a minute stale and only
               * ever moved in whole minutes, while the pending strip DIRECTLY BELOW
               * IT counted the same craft down in seconds off `arriveAt`. Two clocks
               * for one fleet, stacked, disagreeing, one of them not moving.
               *
               * `arriveAt` is the instant itself and needs no anchor — the same
               * reasoning as `arrivalOf` in the strip, which is the surface this
               * now agrees with.
               */
              minutesRemaining={minutesLeft(thread.arriveAt, now)}
              onClose={close}
              open={detail}
              onToggle={toggle}
            />
          );
        })()}

      {/* Somebody else's craft. D24: selectable, and readable up to a point. */}
      {!coachFocus && focus?.kind === 'contact' &&
        (() => {
          const contact = (traffic.data?.contacts ?? []).find((c) => c.id === focus.id);
          // A public effect outside sensor reach is not a contact the commander
          // can inspect; a stale focus may survive the boundary-crossing refetch.
          if (!contact || contact.effectOnly === true) return null;
          /*
            A PIRATE IS A TARGET, NOT A CURIOSITY. D150.

            `ContactFocus` is deliberately read-only — there is nothing a commander
            may DO to somebody else's craft. A pirate is the one contact on the disc
            that can be flown at, so it gets its own rail with the level, the
            handicap, the deadline and the button. Matched on the payload's own kind
            rather than on a separate id list, so a contact that is only a Radar
            question mark still reads as one.
          */
          if (contact.kind === 'pirate') {
            return (
              <PirateFocusHost
                id={contact.id}
                onClose={close}
                onAttack={() => { setAttackingPirateId(contact.id); }}
                open={detail}
                onToggle={toggle}
              />
            );
          }
          return (
            <ContactFocus contact={contact} onClose={close} open={detail} onToggle={toggle} />
          );
        })()}

      {season.data?.status === 'frozen' && panel === null && (
        <div className="pointer-events-none absolute inset-x-0 bottom-[calc(var(--v2-dock-h,96px)+0.5rem)] z-30 mx-auto flex w-full max-w-sm flex-col gap-2 px-2">
          {chatButton && <div className="flex justify-end">{chatButton}</div>}
          <NextSeason endsAt={season.data.endsAt} />
        </div>
      )}

      {/* Chat still in reach on a galaxy with no slot and no next-season card. */}
      {chatButton && panel === null && !slotShown && season.data?.status !== 'frozen' && (
        <div className="pointer-events-none absolute bottom-[calc(var(--v2-dock-h,96px)+0.5rem)] right-2 z-20">{chatButton}</div>
      )}

      {/* ── full surfaces, over the live galaxy ─────────────── */}

      {/*
        ── THE CONTEXT SLOT (B3): one card at the foot of the galaxy. ─────────────

        An attack coming for you, else the galaxy's events, else one suggestion — and
        while the player has something selected its own panel keeps the screen and an
        attack waits as a pill. It replaced the event chip that sat top-left and the
        `SituationGuide` card, whose rules it keeps (`slotSuggestion`): only a
        commander who came through the Academy is coached, and the shield is read
        against this host's clock (H1) — `shieldUntil: season.data.shieldUntil`.
      */}
      {slotShown && planet.data && season.data && (
        <ContextSlot
          {...(chatButton ? { corner: chatButton } : {})}
          now={now}
          selected={slotSelected}
          threats={threads.filter((thread) => thread.kind === 'incoming')}
          contacts={contacts}
          events={activeEvents(galaxyEvents.data?.events ?? [], now)}
          suggestion={slotSuggestion({ planet: planet.data, galaxy: galaxy.data, intel: intel.data,
            pending: threads, held: planet.data.planet,
            shieldUntil: season.data.shieldUntil }, now, slotDismissed)}
          onPrepare={(thread) => {
            if (thread.targetPlanetId) selectPlanet(thread.targetPlanetId);
            setRequestedPlanetGroup('defend');
            onPanel('planet');
          }}
          onLook={(contactId) => {
            setFocus({ kind: 'contact', id: contactId });
            setDetail(true);
          }}
          onShowEvent={(event) => {
            if (event.kind === 'TRADE_SHIP') setFocus({ kind: 'tradeShip', id: event.id });
            else if (event.kind === 'INTERGALACTIC_CONVOY') setFocus({ kind: 'intergalacticConvoy', id: event.id });
            setDetail(true);
          }}
          onAct={({ action }) => {
            if (action.screen === 'planet') {
              if (action.planetId) selectPlanet(action.planetId);
              setRequestedPlanetGroup(action.group ?? 'grow');
              onPanel('planet');
            } else if (action.screen === 'intel') {
              onPanel('intel');
            } else {
              onPanel(null);
              if (action.planetId) focusPlanet(action.planetId);
              else setFocus(null);
            }
          }}
          onClearSelection={close}
          dismissed={slotDismissed}
          onDismiss={(keys) => {
            rememberDismissed(keys, serverNow());
            setSlotDismissed((current) => new Set([...current, ...keys]));
          }}
        />
      )}

      {/*
        THE BASE AND ITS RESEARCH, AS THE MOCKS DRAW THEM (M5): no page header — the switch
        and the world's hero head the page, the close floats beside the switch, and the page
        stands under the top bar so the purse stays in sight while it is spent.
      */}
      {panel === 'planet' && planet.data && (
        <V2Sheet
          bleed
          detents={['full']}
          quietTitle
          eyebrow={commander}
          title={planet.data.planet.name}
          onClose={() => {
            onPanel(null);
          }}
        >
          <BaseSwitch value="world" onChange={openBase} arenaAvailable={arenaAvailable} />
          <PlanetScreen
            onOpenResearch={(project) => {
              setResearchFocus(project);
              onPanel('research');
            }}
            {...(requestedPlanetGroup ?? planetGroup
              ? { focusGroup: requestedPlanetGroup ?? planetGroup }
              : {})}
            {...(requestedItem ? { focusItem: requestedItem } : {})}
          />
        </V2Sheet>
      )}

      {eventsGuideOpen ? (
        <GalaxyEventsGuide onClose={() => { setEventsGuideOpen(false); }} />
      ) : null}

      {/*
        RESEARCH. Its own panel because the levels are the COMMANDER's since T7, and
        `PlanetScreen` is about one world. `onNeed` is what carries a refusal back
