const windowsOpen = (planets: readonly { isSelf: boolean; fleet?: { status: string } }[]): number =>
  planets.filter((p) => !p.isSelf && p.fleet?.status === 'AWAY').length;

/**
 * The asteroid panel needs three things the panel itself should not compute:
 * how long the rock has left, whether your craft could catch it, and how many are
 * free to send. Gathered here so the panel stays a view.
 */
/**
 * THE PIRATE RAIL, FED FROM THE ONE PLACE THAT KNOWS THE PRICE. D150.
 *
 * The disc's contact carries where it is and what it flies; `/api/pirates` carries
 * the level, the deadline and the rendezvous table. Both are keyed by the same
 * opaque handle, so this joins them rather than duplicating either — and the
 * rendezvous in particular may only ever come from the server, because a second
 * numerical solver would quote a minute no launch would keep.
 */
function PirateFocusHost({
  id,
  onClose,
  onAttack,
  open,
  onToggle,
}: {
  id: string;
  onClose: () => void;
  /** Opens `LaunchSheet` against this pirate — the one commitment surface. D150. */
  onAttack: () => void;
  open: boolean;
  onToggle: () => void;
}) {
  // The focus quotes reach and opens the launch sheet: read at the traffic pace.
  const pirates = usePirates({ live: true });
  const planet = usePlanet();
  const pending = usePending();

  const pirate = pirates.data?.pirates.find((candidate) => candidate.id === id);
  if (!pirate) return null;

  // One raid per world per pirate — the server refuses a second, and offering a
  // control that cannot work teaches a rule that is not true.
  const raiding = (pending.data?.pending ?? []).some(
    (thread) => thread.kind === 'pirate' && thread.pirate?.callsign === pirate.callsign,
  );

  return (
    <PirateFocus
      pirate={pirate}
      fleetAtHome={planet.data?.fleet ?? {}}
      launchBlock={launchFault(planet.data?.faults, 'fleet', planet.data?.silentSpace === true)}
      raiding={raiding}
      open={open}
      onToggle={onToggle}
      onClose={onClose}
      onAttack={onAttack}
    />
  );
}

/**
 * WHICH MARK A FOCUSED WORLD WEARS, OR NULL. D183.
 *
 * The rail is handed a `GalaxyPlanet` rather than a scene node, so this asks the
 * same question `rivalSlotOf` asks of the disc and asks it the same way: the
 * COMMANDER first (a mark follows them across every world they hold, D97), the
 * world only where there is no commander to read.
 */
function rivalSlotFor(
  rivals: readonly RivalMark[],
  world: GalaxyPlanet,
): number | null {
  const holder = world.controller?.kind === 'PLAYER' ? world.controller.playerId : null;
  const mark = rivals.find((candidate) => (
    holder !== null ? candidate.playerId === holder : candidate.planetId === world.id
  ));
  return mark ? mark.slot : null;
}

function AsteroidFocusHost({
  rock,
  runs,
  mining,
  seasonStart,
  homePosition,
  now,
  busy,
  open,
  onToggle,
  onClose,
  onSend,
}: {
  rock: AsteroidView | undefined;
  runs: readonly MiningRun[];
  mining: MiningView | undefined;
  seasonStart: Date;
  homePosition: { x: number; y: number; z: number } | undefined;
  now: number;
  busy: boolean;
  open: boolean;
  onToggle: () => void;
  onClose: () => void;
  onSend: (id: string, craft: number) => void;
}) {
  const planet = usePlanet();
  if (!rock) return null;

  const isotopeProject = planet.data?.research.find(
    (project) => project.id === 'ISOTOPE_SPECTROMETRY',
  );
  // Research is commander-wide. Prefer its explicit project state, while a
  // research-gated composition reading is also positive proof during a rolling
  // deploy or split-query refresh. Either proof is monotonic; absence of target
  // detail must not revoke a project the commander already completed.
  const isotopeAccess = (isotopeProject?.level ?? (isotopeProject?.completed ? 1 : 0)) > 0
    || rock.deuteriumShare !== null;

  const minutesLeft = minutesLeftFor(rock, seasonStart, now);
  const speed = mining?.craftSpeed ?? 0;

  /**
   * The real interception, solved with the same function the server uses.
   *
   * It used to be a straight-line guess to where the rock is NOW, which was close
   * enough on a slow one-way path and is badly wrong on a fast orbit — a rock can
   * be on the far side of its circle by the time a craft arrives. Running the
   * actual solver means the flight time shown is the flight time you get, and the
   * button is never offered for a trip the server would refuse.
   */
  /**
   * How much the works can still absorb. D31 — mined ore lands in the buffer, so
   * this is the ceiling that decides how much of a haul survives the trip home.
   */
  const p = planet.data?.planet;
  const worksRoom = p
    ? Math.max(0, p.bufferAlloyCap - p.bufferAlloy)
      + Math.max(0, p.bufferCrystalCap - p.bufferCrystal)
      + Math.max(0, p.bufferDeuteriumCap - p.bufferDeuterium)
    : 0;

  const minutesNow = (now - seasonStart.getTime()) / 60_000;
  const hit =
    homePosition && speed > 0
      ? interceptAsteroid(
          homePosition,
          speed,
          {
            ...rock,
            index: asteroidVisualSeed(rock.id),
            deuteriumShare: rock.deuteriumShare ?? 0,
          },
          minutesNow,
        )
      : null;
  const reach = hit ? hit.flightMinutes : null;

  return (
    <AsteroidFocus
      rock={rock}
      isotopeAccess={isotopeAccess}
      craftAvailable={planet.data?.fleet.PROSPECTOR ?? 0}
      craftHold={mining?.craftHold ?? 0}
      derrick={mining?.derrick ?? false}
      derrickHold={mining?.derrickHold ?? 0}
      minutesLeft={minutesLeft}
      reachMinutes={reach}
      worksRoom={worksRoom}
      run={runForPlanetTarget(runs, p?.id, { kind: 'asteroid', id: rock.id })}
      /** D183: the selected world's rest, published on the private mining view. */
      craftReadyAt={mining?.craftReadyAt ?? null}
      craftCooldowns={mining?.craftCooldowns}
      launchBlock={launchFault(planet.data?.faults, 'prospector', planet.data?.silentSpace === true) ?? undefined}
      onClose={onClose}
      busy={busy}
      open={open}
      onToggle={onToggle}
      onSend={(craft) => {
        onSend(rock.id, craft);
      }}
    />
  );
}

/**
 * A wreck field, and what it would take to go and get it. D32.
 *
 * A field does not move, so this is a plain flight to a fixed point — no
 * interception solve, unlike a rock. Everything else is the asteroid host's shape,
 * because to the player it is the same kind of decision.
 */
function DebrisFocusHost({
  field,
  planets,
  runs,
  mining,
  homePosition,
  busy,
  open,
  onToggle,
  onClose,
  onSend,
}: {
  field: {
    id: string;
    /** Null for a pirate battle: the fight had no world under it. D150. */
    planetId: string | null;
    at: { x: number; y: number; z: number };
    alloy: number;
    crystal: number;
    deuterium: number;
    minutesLeft: number;
  } | undefined;
  planets: readonly { id: string; name: string; position: { x: number; y: number; z: number } }[];
  runs: readonly MiningRun[];
  mining: MiningView | undefined;
  homePosition: { x: number; y: number; z: number } | undefined;
  busy: boolean;
  open: boolean;
  onToggle: () => void;
  onClose: () => void;
  onSend: (fieldId: string, craft: number) => void;
}) {
  const planetQuery = usePlanet();
  if (!field) return null;

  /*
    THE FLIGHT IS PRICED AGAINST THE FIELD, NOT AGAINST ITS WORLD. D150.

    This resolved the position by looking the planet up in the drawn list, so a
    wreck whose world was outside the caller's payload quoted no reach at all —
    and a pirate battle, which has no world, could never have quoted one. The
    field carries its own coordinates now, which is also the pair the server
    solves the harvest against.
  */
  const named = field.planetId === null
    ? undefined
    : planets.find((p) => p.id === field.planetId);
  const speed = mining?.craftSpeed ?? 0;
  const reach =
    homePosition && speed > 0
      ? travelMinutes(distance(homePosition, field.at), speed)
      : null;

  const p = planetQuery.data?.planet;
  const worksRoom = p
    ? Math.max(0, p.bufferAlloyCap - p.bufferAlloy)
      + Math.max(0, p.bufferCrystalCap - p.bufferCrystal)
      + Math.max(0, p.bufferDeuteriumCap - p.bufferDeuterium)
    : 0;

  return (
    <DebrisFocus
      field={field}
      planetName={named?.name}
      craftAvailable={planetQuery.data?.fleet.PROSPECTOR ?? 0}
      craftHold={mining?.craftHold ?? 0}
      reachMinutes={reach}
      worksRoom={worksRoom}
      run={runForPlanetTarget(runs, p?.id, { kind: 'debris', id: field.id })}
      /** The lane the rule exists for: a field over your own world. D183. */
      craftReadyAt={mining?.craftReadyAt ?? null}
      craftCooldowns={mining?.craftCooldowns}
      launchBlock={launchFault(planetQuery.data?.faults, 'prospector', planetQuery.data?.silentSpace === true) ?? undefined}
      busy={busy}
      open={open}
      onToggle={onToggle}
      onClose={onClose}
      onSend={(craft) => {
        onSend(field.id, craft);
      }}
    />
  );
}

