import { SCENE_LIGHT } from './planetSurface.js';
import { SpaceLighting } from './SpaceLighting.js';
import { FirstSceneFrame, SceneRenderGate, SceneWarmup } from './SceneWarmup.js';
import { createOpeningPreparation, type OpeningPreparation } from './openingPreparation.js';
import { OpeningWork, useOpeningViews } from './OpeningViews.js';

/** The rig's per-frame scratch for a tracked subject's drift (never allocated in the loop). */
const TRACK_DRIFT = new THREE.Vector3();
import { DysonShells } from './DysonShells.jsx';
import { Satellites, Shields } from './Satellites.jsx';
import { MiningFlights } from './MiningFlights.jsx';
import { OwnershipFilaments } from './OwnershipFilaments.jsx';
import { RadiationHaze } from './RadiationHaze.js';
import { monumentFocusDistance } from './MonumentModel.js';
import { SensorRings, type ReachRing } from './SensorRings.jsx';
import {
  DISC_RADIUS,
  activeWorldPosition,
  asteroidWorldPosition,
  contactPosition,
  rivalSlotOf,
  claimLabelOf,
  legStandoff,
  planetNodes,
  rendezvousMarks,
  runHomePosition,
  runPosition,
  threadPosition,
  toWorld,
  tradeShipWorldPosition,
  intergalacticConvoyWorldPosition,
  type PlanetNode,
  type Vec3Tuple,
} from './scene.js';
import { installTapGuard, wasMiss, wasTap } from './tap.js';
import { serverNow } from '../lib/clock.js';
import { staleness } from '../lib/time.js';
import { commanderLabel } from '../lib/identity.js';
import { recordAgeMinutes } from '../lib/dossier.js';
import { RankBadge } from './RankBadge.jsx';
import { layoutPlanetLabels, planetLabelRank, planetLabelWidth, type PlanetLabelSize } from './planetLabels.js';
import { Flag } from '../v2/identity/Flag.js';
import type { TFunction } from 'i18next';
import { useTranslation } from 'react-i18next';
import { FaultMark } from '../ui/marks.js';
import { FLIGHT_FPS, HoldRate } from './frames.js';
import { galaxyFrames, useFpsMeterEnabled } from '../lib/fpsMeter.js';
import { perfGalaxyFrame, perfPreparationCode, setPerfExtra, setPerfGalaxyContext, usePerfSession } from '../lib/perfSession.js';
import { anythingInFlight } from './flightRate.js';

/**
 * THE GAME SURFACE.
 *
 * Not a screen the player visits — the thing every other screen is drawn on top
 * of. `decisions.md` D1 puts it plainly: the information game "makes the 3D galaxy
 * an interface rather than a target list".
 *
 * PERFORMANCE SHAPE, which is what keeps this from being a slideshow on a phone:
 *
 *   · The galaxy is instanced — one draw call per distinct planet render rather
 *     than four meshes per planet.
 *   · Rendering is ON DEMAND. A loop running sixty times a second is the biggest
 *     battery drain a page can have, and this scene is usually still. The camera
 *     invalidates itself while it moves; a slow ticker invalidates for the
 *     asteroids and the dust. When nothing is happening, nothing renders.
 *   · Display resolution stays fixed while the player moves the camera. Thin
 *     trails and small hulls cannot visibly blur during the most tactile gesture.
 *     Performance is bought by batching and effect density, not temporary blur.
 */

/**
 * The whole sphere, minus the two poles.
 *
 * You may fly under the galaxy and look up at it. The earlier clamp stopped at
 * 0.46π — just above the disc's own plane — which meant half of every orbit was a
 * wall: you could tilt to look down and then the camera simply refused. Space has
 * no floor and a galaxy has an underside.
 *
 * The poles themselves stay excluded by a hair. Exactly overhead, azimuth becomes
 * undefined and the view snaps a quarter turn for no reason the player can see.
 */
const MIN_POLAR = Math.PI * 0.04;
const MAX_POLAR = Math.PI * 0.96;

/** How far past the rim you may drift before the camera is quietly walked back. */

/** Seconds spent easing onto a new subject. Long enough to follow, short enough not to wait. */
const EASE = 0.5;

/**
 * How close the camera comes whenever it flies home. D56.
 *
 * MUCH CLOSER THAN THE ORDINARY FRAMING, on the owner's instruction, and the
 * reason is what the flight is FOR. A returning commander may open wider because
 * they want their neighbourhood. Pressing Home is different: it explicitly asks
 * to see the active world. Moving only the pivot while preserving a disc-wide
 * camera range technically centred the coordinate and visibly showed empty space.
 *
 * Well clear of `minDistance`, so the rig lands rather than being caught by a
 * clamp — and the player can pull straight back out, because the approach is
 * one-way (see `rangeTo`) and never pushes anybody off a view they went and got.
 */
const HOME_DISTANCE = 7;

/**
 * World units from the camera to a focused craft or rock.
 *
 * Close enough that a 0.3-unit hull fills a readable part of the frame, far enough
 * that a squadron's whole formation and the world it is heading for both stay in
 * shot. Planets are exempt: they are already the size the map is drawn at.
 */
const CRAFT_DISTANCE = 7;

/** Distance and angle of the opening whole-disc composition. */
const WIDE_TILT = Math.hypot(1.15, 1.75);
const WHOLE_DISC_DISTANCE = DISC_RADIUS * WIDE_TILT;

export interface GalaxyCanvasProps {
  unknownSignals?: readonly UnknownSignalView[];
  unknownSignalRadar?: { capitalPlanetId: string; at: { x: number; y: number; z: number }; range: number };
  cosmeticAppearance?: Contact['appearance'];
  planets: readonly GalaxyPlanet[];
  /** Your own missions. Inbound attacks carry no path and are not drawn as one. */
  pending: readonly PendingThread[];
  /** Everyone else's sensed craft plus effect-only public engagements. */
  contacts: readonly Contact[];
  /** Anti-strategic launches the caller participates in or identifies by Telescope. */
  interceptions?: readonly StrategicInterception[];
  /** Public collision fire; carries no craft or route. */
  interceptionImpacts?: readonly StrategicInterceptionImpact[];
  /** Rocks crossing the disc right now, and your craft working them. D19. */
  asteroids: readonly AsteroidView[];
  runs: readonly MiningRun[];
  /**
   * The merchant, if one is currently in the sky. D156.
   *
   * Public by owner decision — an announced moment, not a fogged craft — so this
   * is the one already-narrowed occurrence rather than the raw event array: there
   * is never more than one live at a time (`TRADE_SHIP`'s cooldown equals its own
   * window), and narrowing which entry of a discriminated union is the merchant
   * is exactly the kind of decision that belongs with whoever reads the wire
   * payload, not with the renderer.
   */
  tradeShip?: TradeShipEvent | null;
  /** Public formation crossing the galaxy on its announced diameter. */
  intergalacticConvoy?: IntergalacticConvoyEvent | null;
  /** Wreck fields left by battles, visible to the whole galaxy. D32. */
  wrecks: readonly WreckView[];
  /**
   * Whether an Asteroid Shower is running right now. D149, owner instruction.
   *
   * The only thing it moves is the sky: three times the shooting stars for as long
   * as the event lasts. Decoration, not a reading — see `METEOR_SHOWER_MULTIPLIER`.
   */
  meteorShower?: boolean;
  /**
   * The caller's own sensor boundaries, one per controlled world. D125/D126.
   *
   * Drawn so the ladder is a thing in the galaxy rather than a fact in a payload
   * (D124). Absent draws nothing, which is right for a client ahead of its server.
   */
  sensors?: readonly ReachRing[];
  /** Radiation clouds (K3, F10). Public, like the worlds; absent draws nothing. */
  radiation?: readonly RadiationSourceView[];
  hpRadiation?: readonly HpRadiationSourceView[];
  monuments?: readonly PublicMonument[];
  /**
   * Whether each instrument's boundaries are drawn AT ALL. Owner instruction.
   *
   * One flag each, covering every controlled world — see `GalaxyView` for why the
   * per-world set that preceded them was wrong. Both default to off: the galaxy is
   * the subject and the instruments are something the player asks for.
   */
  showTelescopeReach?: boolean;
  showRadarReach?: boolean;
  /** Where your own craft launch from, for drawing mining legs. */
  homePosition: { x: number; y: number; z: number } | undefined;
  /** The controlled world Camera Home resolves inside the rendered galaxy list. */
  activePlanetId?: string | null;
  /** Your Aegis level. Only ever your own — D15 keeps everyone else's private. */
  aegisLevel: number;
  seasonStart: Date | undefined;
  /** The one commander whose history is pinned for this season. */
  /** Up to `RIVAL.max` marks, each carrying the slot its colour comes from. D183. */
  rivals?: readonly RivalMark[];
  focus: Focus | null;
  onFocus: (focus: Focus | null) => void;
  /** Bumped by the HOME button to re-centre on the player's own world. */
  homeSignal: number;
  /** Bumped to bring the selection back into frame after the player panned away (E11: Space). */
  centerSignal?: number;
  /** A local cosmetic trial explicitly asks for a close view of this owned world. */
  inspectionPlanetId?: string;
  /** Local asset review may start closer to small debris and rocks. */
  reviewFocusDistance?: number;
  /**
   * Open on the whole disc, with nothing selected. D56.
   *
   * For the onboarding rehearsal only. See `Rig` for why the ordinary first frame
   * snaps to the player's own world and why that is the wrong opening for somebody
   * who has never seen this galaxy.
   */
  openWide?: boolean;
  /** Exact camera range for an animated wide re-frame. Defaults to the whole disc. */
  wideDistance?: number;
  /** Explicit Academy toggle only; ordinary sensor toggles never move the camera. */
  /**
   * ACADEMY ONLY: A THING TO TAP, DRAWN WHERE THE SUBJECT ACTUALLY IS.
   *
   * The lesson needs the commander to tap the pirate, the rock or the world it has
   * just flown the camera to. The first attempt put a button at the CENTRE of the
   * screen on the argument that focusing centres the subject — true right up until
   * it is not. Turn the disc by hand during the previous beat, or open a beat whose
   * subject has not reached its payload yet so the rig never moved, and the centre
   * of the screen is empty space with a hand pointing at it. That is exactly what
   * was reported.
   *
   * So it is not placed by assumption. It rides the same `subject` the camera
   * follows and is projected every frame, which puts it ON the target whether the
   * camera got there or not.
   */
  coachTap?: { label: string; onTap: () => void } | null;
  sightRadius?: number;
  /** The Academy entrance flies toward home once, over two seconds. */
  openingHome?: boolean;
  /**
   * Which worlds may be selected at all. D56.
   *
   * Absent means every world, which is the game. The rehearsal narrows it beat by
   * beat — first to the visitor's own world, then to everybody else's, then to the
   * ones inside the tier band — so that a step cannot be completed by tapping the
   * wrong thing and leaving the instruction on screen contradicting the world.
   *
   * FILTERED AT THE TAP ROUTER RATHER THAN BY MASKING THE SCREEN. A world is a
   * moving point inside a canvas the player can orbit; a hole cut in an overlay
   * drifts off it the moment the camera does. This cannot drift — it is the same
   * decision the router already makes, with one more question asked of it.
   */
  allowFocus?: (planetId: string) => boolean;
  /**
   * WHERE AN OPEN LAUNCH SHEET WOULD SEND THE WING IT HAS SELECTED. D155.
   *
   * In game coordinates, from `planPirateRoute` — the server's own solve for the
   * slowest ship picked. Absent draws nothing, which is the state for every launch
   * at a world: a world is its own address and is already on screen with a label
   * under it. See `AimMark`.
   */
  aim?: { x: number; y: number; z: number } | null;
  /**
   * Called once, after the first frame that has every model in it is on screen.
   *
   * The cover over this canvas cannot be lifted on "the request came back": the
   * models still have to decode, compile and upload after that. See `FirstSceneFrame`.
   */
  onReady?: () => void;
  /** Do not certify an empty scene while its opening API payloads are pending. */
  openingDataReady?: boolean;
  /** Only prepare camera views while the parent cover actually hides the scene. */
  openingCovered?: boolean;
}

export function GalaxyCanvas({
  cosmeticAppearance,
  planets,
  pending,
  contacts,
  interceptions,
  interceptionImpacts,
  asteroids,
  runs,
  wrecks,
  tradeShip = null,
  intergalacticConvoy = null,
  meteorShower = false,
  sensors,
  radiation,
  hpRadiation = EMPTY_HP_RADIATION,
  monuments = EMPTY_MONUMENTS,
  unknownSignals = EMPTY_UNKNOWN_SIGNALS,
  unknownSignalRadar,
  showTelescopeReach = false,
  showRadarReach = false,
  homePosition,
  activePlanetId = null,
  aegisLevel,
  seasonStart,
  rivals = EMPTY_RIVALS,
  focus,
  onFocus,
  homeSignal,
  centerSignal = 0,
  inspectionPlanetId,
  reviewFocusDistance,
  aim = null,
  openWide = false,
  wideDistance = WHOLE_DISC_DISTANCE,
  coachTap = null,
  sightRadius,
  openingHome = false,
  allowFocus,
  onReady,
  openingDataReady = true,
  openingCovered = false,
}: GalaxyCanvasProps) {
  const sceneReady = useRef(false);
  const openingSettled = useRef(!openingCovered);
  const openingWork = useMemo(() => createOpeningPreparation(openingCovered), []);
  const openingMark = useRef<HTMLSpanElement>(null);
  const nodes = useMemo(() => planetNodes(planets), [planets]);
  const navigationRadius = useMemo(() => monumentNavigationRadius(monuments, hpRadiation), [monuments, hpRadiation]);
  const home = useMemo<[number, number, number]>(
    () => activeWorldPosition(planets, activePlanetId, homePosition),
    [activePlanetId, homePosition, planets],
  );

  const rendezvous = useMemo(() => rendezvousMarks(runs, pending), [runs, pending]);
  // Weapons a battery shot down; their surface blast never plays (owner, 2026-10-16).
  const interceptedWeapons = useMemo(() => new Set([...interceptions ?? [], ...interceptionImpacts ?? []]
    .flatMap((event) => event.weaponId ? [event.weaponId] : [])), [interceptions, interceptionImpacts]);
  /**
   * Held to the coordinates rather than the object: `aim` is rebuilt on every
   * keystroke in the picker, and a fresh tuple would remount `AimMark` — and its
   * line buffer with it — on each one.
   */
  const aimAt = useMemo<Vec3Tuple | null>(
    () => (aim ? toWorld(aim) : null),
    [aim?.x, aim?.y, aim?.z],
  );

  const selfId = useMemo(() => planets.find((p) => p.isSelf)?.id, [planets]);
  const selectedId = focus?.kind === 'planet' ? focus.id : null;

  /**
   * The camera's subject.
   *
   * A PLANET is a fixed point and the rig can ease onto it once. EVERYTHING ELSE
   * MOVES — a rock crossing the disc, a squadron on its way to a raid, a
   * Prospector coming home — so focusing one has to keep following, or the thing
   * you tapped drifts out of frame mid-sentence. That is what `subject` is: a live
   * position, read fresh each frame, rather than a destination.
   *
   * SQUADRONS AND MINING RUNS WERE MISSING FROM THIS LIST, and the symptom was
   * exact: tapping a rock flew the camera to it and tracked it, tapping your own
   * fleet selected it, opened its panel, and left the camera wherever it was — so
   * the two gestures behaved differently for no reason a player could see. They
   * are the same gesture and they now do the same thing.
   *
   * Every branch reads the SAME interpolation the renderer uses, so the camera and
   * the craft agree to the frame. Deriving a second position here — even a very
   * close one — would show as the subject creeping out of centre over a long leg.
   */
  const subject = useMemo<(() => [number, number, number] | null) | null>(() => {
    if (!focus) return null;

    if (focus.kind === 'unknownSignal') {
      const signal = unknownSignals.find(row => row.id === focus.id);
      return signal ? () => toWorld(signal.at) : null;
    }

    if (focus.kind === 'planet') {
      const node = nodes.find((n) => n.id === focus.id);
      return node ? () => node.position : null;
    }

    if (focus.kind === 'monument') {
      const monument = monuments.find((row) => row.id === focus.id);
      return monument ? () => toWorld(monument.motion?motionPositionAt(monument.motion,serverNow()):monument.position) : null;
    }

    if (focus.kind === 'asteroid' && seasonStart) {
      const rock = asteroids.find((a) => a.id === focus.id);
      if (!rock) return null;
      return () => asteroidWorldPosition(rock, seasonStart, serverNow());
    }

    /**
     * A WRECK IS WHERE THE WRECK IS. See `wreckPosition`.
     *
     * This used to resolve the field through the world the battle happened over,
     * which is null for a pirate fight in open space — so the camera silently did
     * nothing when a player tapped the one field nobody owns. A field states its
     * own coordinates and they do not move, so the subject is a fixed point like a
     * planet's rather than a live read.
     */
    if (focus.kind === 'debris') {
      const wreck = wrecks.find((w) => w.id === focus.id);
      if (!wreck) return null;
      const at = wreckPosition(wreck);
      return () => at;
    }

    if (focus.kind === 'thread') {
      const thread = pending.find((t, i) => threadKey(t, i) === focus.key);
      const path = thread?.path;
      if (!thread || !path) return null;
      /**
       * THE SAME STANDOFF THE RENDERER USES. D44.
       *
       * A leg now stops in orbit rather than at a world's centre, and the camera
       * has to read the identical number — a rig that tracked the old endpoint
       * would let a focused squadron drift a planet-radius off centre over the
       * last minute of its approach, and then sit looking past it for the whole
       * engagement.
       */
      const standoff = legStandoff(thread, nodes);
      return () => threadPosition(path, serverNow(), standoff);
    }

    if (focus.kind === 'run' && homePosition) {
      const run = runs.find((r) => r.id === focus.id);
      if (!run) return null;
      const origin = runHomePosition(run, nodes, homePosition);
      return () => runPosition(run, origin, serverNow(), nodes);
    }

    /**
     * THE MERCHANT IS FOLLOWED, because it moves and it is the only reason anyone
     * tapped it. Read from the SAME `tradeShipWorldPosition` the renderer uses, so
     * the camera and the ship agree to the frame — deriving a second position here
     * would show as the subject creeping out of centre over a three-hour window.
     */
    if (focus.kind === 'tradeShip' && seasonStart && tradeShip?.id === focus.id) {
      const orbit = tradeShip.orbit;
      return () => tradeShipWorldPosition(orbit, seasonStart, serverNow());
    }

    if (focus.kind === 'intergalacticConvoy'
      && seasonStart
      && intergalacticConvoy?.id === focus.id) {
      const convoy = intergalacticConvoy;
      return () => intergalacticConvoyWorldPosition(convoy, seasonStart, serverNow());
    }

    if (focus.kind === 'interception') {
      const event = interceptions?.find((candidate) => candidate.id === focus.id);
      if (!event) return null;
      return () => strategicInterceptionMissilePosition(
        event,
        nodes,
        serverNow(),
      );
    }

    if (focus.kind === 'interceptionImpact') {
      const impact = interceptionImpacts?.find((candidate) => candidate.id === focus.id);
      if (!impact) return null;
      const collision = toWorld(impact.collision);
      return () => collision;
    }

    /**
     * Somebody else's craft is followed from its BEARING WINDOW rather than from a
     * route, because a window is all the server sends (D24). The camera therefore
     * tracks it exactly as far ahead as the payload knows, and re-anchors on the
     * next poll — which is the same thing the renderer does, from the same numbers.
     */
    if (focus.kind === 'contact') {
      const contact = contacts.find((c) => c.id === focus.id);
      // An effect-only engagement is deliberately not a craft: it has no hit box,
      // no focus target and no authoritative orbit point for the camera to follow.
      if (!contact || contact.effectOnly === true) return null;
      // The window is already on the server's shared visual leg; nodes remain for
      // the landed engagement hold, which still reads the target's drawn radius.
      return () => contactPosition(contact, serverNow(), nodes);
    }

    return null;
  }, [
    focus,
    nodes,
    monuments,
    unknownSignals,
    asteroids,
    seasonStart,
    pending,
    runs,
    homePosition,
    contacts,
    interceptions,
    interceptionImpacts,
    tradeShip,
    intergalacticConvoy,
  ]);

  /**
   * How close the camera is pulled in when it takes a new subject.
   *
   * A world is drawn between 0.44 and 1.4 units across and a craft is a fraction
   * of that, so the distance at which a planet is comfortably framed is one at
   * which a squadron is three pixels. Focusing something small therefore has to
   * DOLLY as well as pivot — the owner's note was that tapping a fleet did not
   * zoom, and a camera that only re-centres on something invisible has technically
   * obeyed and practically done nothing.
   *
   * Only ever pulls IN, and only when the camera is further out than this. A
   * player who has deliberately gone close keeps their framing.
   */
  const approach = focus === null || focus.kind === 'planet'
    ? null
    : focus.kind === 'monument' ? monumentFocusDistance(monuments.find(row => row.id === focus.id)?.difficulty ?? 'LEGACY') : focus.kind === 'intergalacticConvoy'
      ? CONVOY_FOCUS_DISTANCE
      : CRAFT_DISTANCE;

  /**
   * WHAT IS FOCUSED, AS A STABLE STRING — and it is the fix for a camera that
   * re-framed itself while the player sat still. Owner-reported bug.
   *
   * `subject` above is a memo over `nodes`, `asteroids`, `pending`, `runs`,
   * `contacts` and `wrecks`. Every one of those is a fresh array on every refetch,
   * and in a live galaxy they refetch on every shard broadcast as well as on the
   * sixty-second net — so the memo produced a NEW FUNCTION several times a minute
   * without the player touching anything. The rig's "ease onto a new subject"
   * effect was keyed on that function, so it fired each time: the pivot re-eased
   * and, worse, `rangeTo` dollied the camera back in to `CRAFT_DISTANCE`, undoing
   * whatever framing the player had chosen. The docblock on that effect claimed it
   * "fires on a change of subject and not on every render", which was the
   * intention and was never true.
   *
   * This is what a change of subject actually is: the player picked something
   * else. It moves when they act and at no other time.
   */
  const focusKey = useMemo(() => focusIdentity(focus), [focus]);

  useEffect(() => installTapGuard(), []);

  /**
   * WHAT THIS DEVICE SPENDS PER PIXEL. See `lib/quality.ts` for the whole argument.
   *
   * Read here rather than threaded through `GalaxyView` because it is a property
   * of the phone, not of the galaxy: nothing above this component has an opinion
   * about it, and every screen that mounts a disc — the game, the Academy, the
   * write-free rehearsal — gets the player's own setting without being told.
   */
  const quality = useRenderQuality();
  const preset = QUALITY_PRESETS[quality];

  /**
   * SURVIVING THE PHONE TAKING THE GPU BACK. See `gpuContext.ts` for the crash
   * this answers — a backgrounded Chrome drops the WebGL context, and the first
   * render afterwards dereferenced null inside `EffectComposer` and took the
   * whole app down. `live` gates the composer; `epoch` rebuilds it on the far
   * side, because a restored context is a new one.
   */
  const gpu = useGpuContext();
  const [preparedEpoch, setPreparedEpoch] = useState(-1);
  const prepared = preparedEpoch === gpu.epoch;
  const onCompiled = useCallback(() => { setPreparedEpoch(gpu.epoch); }, [gpu.epoch]);
  const signalGuide = useRef<HTMLButtonElement>(null);

  return (
    <>
    <Canvas
      frameloop="demand"
      camera={{ position: initialHomeCameraPosition(...home), fov: GALAXY_FOV, near: 0.1, far: Math.max(600, navigationRadius * 5) }}
      /**
       * A CLAMP, SO THE PRESET CAN ONLY EVER LOWER THE RATIO.
       *
       * `[1, cap]` keeps fiber's own behaviour — take the device's ratio and clamp
       * it — rather than forcing a number. A fixed 1.5 on a desktop at 1 would
       * render half again as many pixels as the screen has and then throw them
       * away, which would make the cheap preset the expensive one.
       */
      dpr={[1, preset.dprCap]}
      /**
       * NO `antialias` HERE, BECAUSE THE COMPOSER BELOW ALREADY DOES IT.
       *
       * The scene is never drawn to this context's own framebuffer: `EffectComposer`
       * renders it into a multisampled target of its own (`multisampling={2}`) and
       * then puts ONE full-screen quad on the canvas. Asking the context for
       * antialiasing as well allocated a second multisampled default framebuffer and
       * resolved it on every present, to smooth the edges of a rectangle that has
       * none — at device pixel ratio 2 on a phone, a full-screen buffer of tile
       * memory and a resolve per frame, bought and never looked at.
       *
       * SAID OUT LOUD, because fiber's own default is `antialias: true` and the `gl`
       * prop is merged ON TOP of it. Deleting the key turns nothing off.
       *
       * Nothing about the image changes. `render-cost.test.ts` holds the pair apart.
       */
      gl={{ antialias: false, powerPreference: 'high-performance' }}
      onCreated={({ gl }) => {
        /**
         * THE COLOUR CONTRACT, stated rather than inherited from library defaults.
         *
         * Three works in linear-sRGB; the display is sRGB. R3F currently chooses
         * this default too, but a premium renderer cannot let a dependency upgrade
         * silently change what every texture and plume means. The post-process
         * target below is half-float so highlights survive long enough for bloom
         * to read them.
         *
         * THIS SCENE HAS NO TONE MAPPING, ON PURPOSE, AND THAT IS WORTH SAYING
         * BECAUSE IT LOOKS LIKE AN OVERSIGHT.
         *
         * There used to be a `gl.toneMapping = ACESFilmicToneMapping` here and it
         * never did anything: while an `EffectComposer` is mounted,
         * `@react-three/postprocessing` forces the renderer to `NoToneMapping` and
         * hands the job to the composer, so the assignment was overwritten on the
         * next frame. The shipped image has never had a mapping of any kind.
         *
         * ADDING ONE WAS TRIED AND REVERTED. A `<ToneMapping>` effect in the
         * composer is where it would belong and it works immediately — and the
         * owner's report on seeing it was that the disc went dark: the background
         * galaxy and the dust cloud at its centre disappeared. That is correct
         * behaviour and the wrong change. Every colour in this directory — the
         * nebula's three depth bands, the dust, the star magnitudes, every plume
         * and drive core — was authored by eye against a linear passthrough, so a
         * filmic curve does not "fix" them, it RE-GRADES all of them at once, and
         * its toe takes the faint end first. Nothing in the scene is faded on
         * purpose; the whole galaxy is the faint end.
         *
         * So a mapping goes in only WITH a re-grade of those values, never on its
         * own. The line is gone rather than left dead, so nobody reads it as a
         * setting that is already in force.
         */
        gl.outputColorSpace = THREE.SRGBColorSpace;
        gl.toneMappingExposure = 1;
        /*
          A LOST CONTEXT IS ROUTINE ON A PHONE AND USED TO BE A CRASH. Nothing in
          this app listened for it; `gpuContext.ts` carries the whole account.
        */
        gpu.watch(gl.domElement);
      }}
      onPointerMissed={() => {
        /**
         * Clear the selection ONLY when the gesture genuinely hit nothing.
         *
         * `wasMiss()` is the scene's own answer, set by the pick handlers, rather
         * than R3F's inference — which counted a tap on an object as a miss and
         * cleared the very selection that tap had just made, at random, depending
         * on which state update React flushed last.
         */
        // A rehearsal that is holding a world for a beat must not have it cleared
        // by a tap on empty space: the instruction would still be on screen with
        // nothing selected behind it.
        if (wasTap() && wasMiss() && !allowFocus) onFocus(null);
      }}
      style={{ position: 'absolute', inset: 0, touchAction: 'none' }}
    >
      <color attach="background" args={['#04060c']} />
      {/*
        Atmospheric perspective. Distant worlds fade into the nebula instead of
        staying crisp, which is most of what makes a scene read as deep rather than
        as objects on a black sheet. The owner-set 250–500 range keeps worlds
        visible longer as the camera zooms out (owner, 2026-10-05).
      */}
      <fog attach="fog" args={['#070c18', 250, 500]} />

      {/* One key light, from the same upper-left the planet renders assume, so the
          asteroids are shaded consistently with everything else. RAISED WITH THE 3D
          WORLDS (F9, owner: "ışığı biraz arttır"): lit surfaces now carry the disc, and
          at 0.35 the side away from the key read as a hole. */}
      <ambientLight intensity={SCENE_LIGHT.ambient} />
      <directionalLight position={[-8, 12, 9]} intensity={SCENE_LIGHT.key} />
      <directionalLight position={[10, -3, -12]} intensity={0.48} color="#91b5de" />
      <SpaceLighting />

      <Sky />
      <Core />
      <BrightStars />
      <Dust />
      <Meteors shower={meteorShower} />
      <Disc />

      <OpeningWork.Provider value={openingWork}>
      <GalaxyVisualPhase>
      <Suspense fallback={null}>
        {/* Wreckage is independent of the rock field — a battle can leave one on a
            day when nothing is crossing the disc. D32. */}
        <Wrecks
          wrecks={wrecks}
          nodes={nodes}
          focusedId={focus?.kind === 'debris' ? focus.id : null}
          onSelect={(id) => {
            onFocus({ kind: 'debris', id });
          }}
        />

        {seasonStart && asteroids.length > 0 && (
          <Asteroids
            asteroids={asteroids}
            seasonStart={seasonStart}
            focusedId={focus?.kind === 'asteroid' ? focus.id : null}
            onSelect={(id) => {
              onFocus({ kind: 'asteroid', id });
            }}
          />
        )}

        {/*
          THE MERCHANT. D156. Public by owner decision, so it is drawn for every
          player with no sensor check at all — unlike everything else in this
          block it carries no fog whatsoever. It is tappable since slice 3a, and a
          tap is the explicit instruction D69 requires before the camera moves.
        */}
        <TradeShip
          event={tradeShip}
          seasonStart={seasonStart}
          focused={focus?.kind === 'tradeShip' && focus.id === tradeShip?.id}
          onSelect={(id) => {
            onFocus({ kind: 'tradeShip', id });
          }}
        />

        <IntergalacticConvoy
          event={intergalacticConvoy}
          seasonStart={seasonStart}
          focused={focus?.kind === 'intergalacticConvoy'
            && focus.id === intergalacticConvoy?.id}
          onSelect={(id) => {
            onFocus({ kind: 'intergalacticConvoy', id });
          }}
        />

        {/*
          THE BOUNDARIES, DRAWN. D125/D126. Before the worlds, so the rings sit
          behind the things they are about rather than over them.
        */}
        {/* Radiation (K3): a haze where the dose is, behind the worlds it may wrap. */}
        <RadiationHaze {...(radiation ? { clouds: radiation } : {})} hpClouds={hpRadiation} />
        <RadiationBombEffects sources={hpRadiation} nodes={nodes} monuments={monuments} />
        {/* A Death Star's EMP hour, as a dull ember that survives the zoom (owner, 2026-10-16). */}
        <PlanetEmbers nodes={nodes} />
        {/* The commander's own broken colonies, at every zoom (owner, 2026-10-16). */}
        <FaultMarks nodes={nodes} />
        {unknownSignals.length > 0 && <UnknownSignals signals={unknownSignals} focusedId={focus?.kind === 'unknownSignal' ? focus.id : null}
          onSelect={id => { onFocus({ kind: 'unknownSignal', id }); }} />}
        <UnknownSignalGuideTracker signals={unknownSignals} element={signalGuide} />
        {unknownSignalRadar && <SensorRings posts={[{ planetId: unknownSignalRadar.capitalPlanetId, at: unknownSignalRadar.at,
          identify: 0, detect: unknownSignalRadar.range, telescope: false }]} showTelescope={false} showRadar />}
        <Monuments monuments={monuments} planets={nodes} hpRadiation={hpRadiation} focusedId={focus?.kind === 'monument' ? focus.id : null}
          onSelect={(id) => { onFocus({ kind: 'monument', id }); }} />
        {sensors && sensors.length > 0 && (
          <SensorRings
            posts={sensors}
            showTelescope={showTelescopeReach}
            showRadar={showRadarReach}
          />
        )}
        <OwnershipFilaments nodes={nodes} selectedId={selectedId} />
        <PlanetField
          nodes={nodes}
          selectedId={selectedId}
          rivals={rivals}
          onSelect={(id) => {
            // D56. Absent means every world, which is the game; the rehearsal
            // narrows it per beat so a step cannot be finished on the wrong world.
            if (allowFocus && !allowFocus(id)) return;
            onFocus({ kind: 'planet', id });
          }}
        />
        {/*
          After the worlds, because the structure has to interleave with the
          billboard it wraps by depth rather than by draw order, and before the
          orbiting hardware, which is drawn small and must not be buried under it.
        */}
        <DysonShells nodes={nodes} />
        <Satellites nodes={nodes} />
        <Shields nodes={nodes} ownLevel={aegisLevel} ownId={selfId} />
        <OwnFleets
          appearance={cosmeticAppearance}
          pending={pending}
          nodes={nodes}
          focusedKey={focus?.kind === 'thread' ? focus.key : null}
          onSelect={(key) => {
            onFocus({ kind: 'thread', key });
          }}
        />
        {homePosition && (
          <MiningFlights
            runs={runs}
            home={homePosition}
            nodes={nodes}
            focusedId={focus?.kind === 'run' ? focus.id : null}
            onSelect={(id) => {
              onFocus({ kind: 'run', id });
            }}
          />
        )}
        {/*
          EVERY POINT IN OPEN SPACE ONE OF YOUR CRAFT IS AIMED AT, both lanes. D40.

          `rendezvousMarks` is the one list: a mining run's interception and a
          raid's rendezvous with a pirate are the same thing to look at, and the
          pirate lane went without one until D155 — so a raid flew off at an angle
          to the contact that had just been tapped with nothing explaining it.
        */}
        <RendezvousMarks points={rendezvous} />
        {/*
          And where an OPEN sheet would send the wing it has selected — the only
          moment the player can still act on it. D124.
        */}
        {aimAt && <AimMark from={home} to={aimAt} />}
        <Traffic
          contacts={contacts}
          nodes={nodes}
          focusedId={focus?.kind === 'contact' ? focus.id : null}
          onSelect={(id) => {
            onFocus({ kind: 'contact', id });
          }}
        />
        <DeathStarImpacts pending={pending} contacts={contacts} nodes={nodes} intercepted={interceptedWeapons} />
        <StrategicInterceptions
          events={interceptions ?? []}
          impacts={interceptionImpacts ?? []}
          nodes={nodes}
        />
        <Labels
          nodes={nodes}
          hpRadiation={hpRadiation}
          selectedId={selectedId}
          rivals={rivals}
        />
        {gpu.live && <SceneWarmup key={gpu.epoch} dataReady={openingDataReady} onCompiled={onCompiled} />}
        <FirstSceneFrame settled={openingSettled} ready={prepared && openingDataReady && gpu.live} onDrawn={() => {
          sceneReady.current = true;
          if (openingCovered && openingMark.current && openingSettled.current) {
            openingMark.current.dataset.academyHomeReady = 'true';
          }
          onReady?.();
        }} />
      </Suspense>
      </GalaxyVisualPhase>
      </OpeningWork.Provider>

      {/*
        Bloom is the difference between "lights" and "light". It is the one
        post-process worth its cost here: everything bright in this scene is
        additive already, so a small mipmap kernel does all the work.
      */}
      {/*
        REBUILT WHEN THE RESOLUTION CEILING MOVES, and it has to be.

        `EffectComposer` sizes its buffers from `setSize(size.width, size.height)`
        in an effect keyed on `size` — the CSS box — and `postprocessing` then
        multiplies by whatever `renderer.getPixelRatio()` says AT THAT MOMENT.
        Changing the preset moves the pixel ratio without moving the CSS box, so
        nothing in that dependency list fires: the scene would keep rendering into
        buffers built for the old ratio, which is a scaled, cropped picture rather
        than a slow one.

        The key is the whole fix. A preset change is a deliberate, rare tap, and
        fiber applies the new ratio in the canvas's LAYOUT effect — before this
        subtree's passive effects, which is where the composer is constructed — so
        the replacement reads the ratio that is already in force.
      */}
      {/*
        NOT MOUNTED AGAINST A DEAD CONTEXT, and the gate rather than a prop is
        the point: the crash is inside `EffectComposer.setRenderer`, which runs
        when the element is constructed. A composer that merely knew the context
        was gone would already have dereferenced the null.

        The epoch joins the key for the same reason the resolution ceiling is
        there — a restored context is a NEW one, and every render target the old
        composer allocated belonged to the one that died.
      */}
      <RedrawOnRestore epoch={gpu.epoch} />
      <WideScreenFov />
      <SceneRenderGate />
      <GalaxyPostprocessing
        live={gpu.live}
        epoch={gpu.epoch}
        dprCap={preset.dprCap}
        multisampling={preset.multisampling}
        prepared={prepared}
      />

      {/*
        THE LESSON'S TAP TARGET, ON THE SUBJECT RATHER THAN ON THE MIDDLE.
        See `coachTap`. Mounted here because this is where `subject` is — the same
        live read the camera follows, so the button and the camera cannot disagree.
      */}
      {coachTap && subject && (
        <CoachTap subject={subject} label={coachTap.label} onTap={coachTap.onTap} />
      )}

      <DevBridge />
      {openingHome && <Html position={home} center zIndexRange={[10, 0]} style={{ pointerEvents: 'none' }}>
        <span ref={openingMark} data-academy-home data-academy-home-ready="false" className="pointer-events-none block size-px" />
      </Html>}
      <Rig
        navigationRadius={navigationRadius}
        home={home}
        homeSignal={homeSignal}
        centerSignal={centerSignal}
        subject={subject}
        focusKey={focusKey}
        approach={reviewFocusDistance !== undefined && Number.isFinite(reviewFocusDistance)
          ? Math.max(1.2, reviewFocusDistance) : approach}
        inspectionRadius={focus?.kind === 'planet' && focus.id === inspectionPlanetId ? nodes.find(node => node.id === inspectionPlanetId)?.radius : undefined}
        exactApproach={coachTap !== null || focus?.kind === 'intergalacticConvoy' || focus?.kind === 'monument'}
        openWide={openWide}
        wideDistance={wideDistance}
        {...(sightRadius !== undefined ? { sightRadius } : {})}
        openingHome={openingHome}
        sceneReady={sceneReady}
        openingSettled={openingSettled}
        openingCovered={openingCovered}
        openingPrepared={prepared && openingDataReady && gpu.live}
        openingWork={openingWork}
        openingMark={openingMark}
      />
      {/* E11: a page docked on the right does not hide the camera's subject. */}
      <ViewOffset />
      <AmbientTicker />
      <FpsProbe />
      <PerfProbe
        focused={focus !== null}
        context={{
          planets: nodes.length,
          shielded: nodes.filter((node) => node.shielded && node.intel !== 'UNKNOWN').length,
          contacts: contacts.length,
          pirates: contacts.filter((contact) => contact.kind === 'pirate').length,
          ownFlights: pending.filter((thread) => thread.path !== undefined).length,
          drills: runs.filter((run) => run.status !== 'done').length,
          rocks: asteroids.length,
          wrecks: wrecks.length,
        }}
      />
      {/* Drills, probes and fleets cross the disc at thirty (owner, 2026-09-19). */}
      <HoldRate fps={FLIGHT_FPS} active={anythingInFlight({ pending, runs, contacts })} />
    </Canvas>
    <UnknownSignalGuide signals={unknownSignals} element={signalGuide} onSelect={id => { onFocus({ kind: 'unknownSignal', id }); }} />
    </>
  );
}

/**
 * Names, only where they earn the pixels — AND ONLY WHERE THEY FIT.
 *
 * Semantic zoom was the whole idea and only half of it was implemented. The
 * filter picked which worlds DESERVE a name — yours, an open window, the current
 * selection, your marked rival, a world in recovery, a claim on the clock — and
 * then drew every one of them, at every distance, with no idea where the others
 * had landed. Three recovering worlds falling into the same corner of the disc
 * wrote three names into the same forty pixels, and the map's most important
 * labels became a smear that also ran off the left edge of a phone.
 *
 * A LABEL IS PLACED IN SCREEN SPACE, NOT WORLD SPACE, so this is settled where the
 * collision actually happens:
 *
 *   · PRIORITY, highest first — the selection, then your own worlds, then the
 *     rival, then a world that is on a clock (recovery or an open claim), then an
 *     open window. When two labels cannot both be drawn, the one the player is
 *     less likely to be looking for is the one that goes.
 *   · A GREEDY KEEP. Walk that order, project each anchor to CSS pixels, and drop
 *     any whose box would overlap one already placed. Nothing is ever half drawn.
 *   · OFF-SCREEN AND FAR-AWAY GO FIRST, because a name you cannot read is a name
 *     that is only costing the frame.
 *
 * It runs in `useFrame` against DOM refs rather than through React state: the
 * camera moves every frame, and re-rendering the label set at frame rate would put
 * a list rebuild on the disc's own budget. Nothing above this re-renders at all.
 */
/** A stable empty set: a fresh array each render would move a prop identity. */
const EMPTY_RIVALS: readonly RivalMark[] = [];
const EMPTY_MONUMENTS: readonly PublicMonument[] = [];
const EMPTY_UNKNOWN_SIGNALS: readonly UnknownSignalView[] = [];
const EMPTY_HP_RADIATION: readonly HpRadiationSourceView[] = [];

/** The claim word on a label: open, the caller's own first hour, or somebody else's. */
function claimTag(claim: ReturnType<typeof claimLabelOf>, t: TFunction) {
  if (claim === null) return null;
  if (claim === 'PRIORITY') return <span className="text-dim">· {t('galaxy.claimPriority')}</span>;
  return <span className="text-opportunity">· {t(claim === 'MINE' ? 'galaxy.claimMine' : 'galaxy.claimOpen')}</span>;
}

export function Labels({
  nodes,
  hpRadiation,
  selectedId,
  rivals,
}: {
  nodes: readonly PlanetNode[];
  hpRadiation: readonly HpRadiationSourceView[];
  selectedId: string | null;
  rivals: readonly RivalMark[];
}) {
  const { t } = useTranslation();
  const radiationByWorld = useMemo(() => {
    const sources = new Map<string, HpRadiationSourceView[]>();
    for (const source of hpRadiation) {
      if (source.target?.kind !== 'PLANET') continue;
      const bucket = sources.get(source.target.id) ?? [];
      bucket.push(source); sources.set(source.target.id, bucket);
    }
    return sources;
  }, [hpRadiation]);
  // The radiation bar is the only part of a name that changes by the second.
  const radiationNow = useNow(radiationByWorld.size > 0 ? 1000 : 60_000);
  // Nearby earned identities need no tap. Unknown worlds remain unnamed, and
  // remembered identities keep their record age. Only the visible, non-colliding
  // pool mounts Html; the eye remains in PlanetField's spatial marker stack.
  const [visibleIds, setVisibleIds] = useState<readonly string[]>([]);
  const invalidate = useThree((state) => state.invalidate);
  const membership = useRef('');
  const labelIdentity = `${selectedId ?? ''}|${visibleIds.join('|')}`;

  // A newly committed label needs one projection frame in the demand renderer.
  useCommittedDemandFrame(labelIdentity);

  const byId = new Map(nodes.map((node) => [node.id, node]));
  const ordered = visibleIds.flatMap((id) => { const node = byId.get(id); return node ? [node] : []; });
  const boxes = useRef(new Map<string, HTMLElement | null>());
  const sizes = useRef(new Map<string, PlanetLabelSize>());
  const observer = useRef<ResizeObserver | null>(null);
  const clock = useRef(0.1);

  const measure = useCallback((id: string, element: HTMLElement) => {
    const intel = element.dataset.worldLabelIntel;
    if (intel !== 'UNKNOWN' && intel !== 'RESOLVED' && intel !== 'REMEMBERED') return;
    const width = element.offsetWidth;
    const height = element.offsetHeight;
    if (width === 0 || height === 0) return;
    const detail = element.dataset.worldLabelDetail === 'true';
    const previous = sizes.current.get(id);
    if (previous?.width === width && previous.height === height && previous.detail === detail && previous.intel === intel) return;
    sizes.current.set(id, { width, height, detail, intel });
    clock.current = 0.1;
    invalidate();
  }, [invalidate]);

  /*
    ONE REF PER NAME, kept for as long as it is mounted. An inline ref is a new function on every
    render, and React detaches and re-attaches it: with the radiation clock that was every second,
    a forced layout and a requested galaxy frame per label (2026-10-20, profiled on a phone).
    Size changes after mounting arrive through the ResizeObserver below.
  */
  const refs = useRef(new Map<string, (element: HTMLSpanElement | null) => void>());
  const labelRef = (id: string) => {
    let attach = refs.current.get(id);
    if (!attach) {
      attach = (element) => {
        if (element) {
          boxes.current.set(id, element);
          clock.current = 0.1;
          // Html's child root can commit after our post-commit frame. Its
          // own ref is the reliable point to request the first projection.
          measure(id, element);
          observer.current?.observe(element);
          invalidate();
          return;
        }
        const previous = boxes.current.get(id);
        if (previous) observer.current?.unobserve(previous);
        boxes.current.delete(id);
        refs.current.delete(id);
      };
      refs.current.set(id, attach);
    }
    return attach;
  };

  useEffect(() => {
    // Font, language and status changes can resize a name without a camera move.
    // Observe the small mounted pool; projection only reads the cached numbers.
    const resized = new ResizeObserver((entries) => {
      for (const { target } of entries) {
        if (!(target instanceof HTMLElement)) continue;
        const id = target.dataset.worldLabel;
        if (id) measure(id, target);
      }
    });
    observer.current = resized;
    for (const element of boxes.current.values()) if (element) resized.observe(element);
    return () => { resized.disconnect(); observer.current = null; };
  }, [measure]);

  useFrame(({ camera, size }, delta) => {
    // Ten times a second. The camera eases rather than jumps, so a label that
    // settles a frame late is invisible; a projection per world per frame is not.
    clock.current += delta;
    if (clock.current < 0.1) return;
    clock.current = 0;

    const placements = layoutPlanetLabels({ nodes, camera, width: size.width, height: size.height, selectedId, rivals, now: serverNow(), sizes: sizes.current });
    // Camera distance may reorder priorities without changing membership. Keep
    // mounted labels stable so panning does not cause needless React updates.
    const nextIds = placements.map((placement) => placement.id).sort();
    const nextMembership = nextIds.join('|');
    if (membership.current !== nextMembership) {
      membership.current = nextMembership;
      setVisibleIds(nextIds);
    }
    const byPlacement = new Map(placements.map((placement) => [placement.id, placement]));
    for (const [id, element] of boxes.current) {
      if (!element) continue;
      const placement = byPlacement.get(id);
      if (placement) {
        const shiftX = placement.left + placement.width / 2 - placement.x;
        const shiftY = placement.top + placement.height - placement.y;
        // The class already translates half the height in Tailwind's separate
        // CSS `translate` property; adding -50% here would apply it twice.
        const transform = `translate(${String(shiftX)}px, ${String(shiftY)}px)`;
        if (element.style.transform !== transform) element.style.transform = transform;
        const maxWidth = `${String(Math.min(placement.detail ? 180 : 150, size.width - 16))}px`;
        if (element.style.maxWidth !== maxWidth) element.style.maxWidth = maxWidth;
      }
      // `visibility` rather than `display`: drei keeps measuring the wrapper, and
      // a box that collapses to zero would flip the answer on the next frame.
      const next = placement ? 'visible' : 'hidden';
      if (element.style.visibility !== next) element.style.visibility = next;
    }
  });

  return (
    <>
      {ordered.map((node) => {
      /**
       * HOW OLD THIS WORLD'S RECORD IS, OR NULL IF IT IS A LIVE READING. D151.
       * The shared definition, so the label and the dossier cannot drift apart.
       */
      const age = recordAgeMinutes(node, serverNow());
      const detail = planetLabelRank(node, selectedId, rivals, serverNow()) < 7;
      const radiation = radiationAtTarget({ kind: 'PLANET', id: node.id }, radiationByWorld.get(node.id) ?? [], radiationNow);
      return (
        <Html
          key={node.id}
          position={[node.position[0], node.position[1] + node.radius * 1.85, node.position[2]]}
          center
          zIndexRange={[10, 0]}
          style={{ pointerEvents: 'none' }}
        >
          {/*
            THE WHOLE BLOCK SITS ABOVE THE ANCHOR. drei centres an `Html` on its
            point, so half of a three-line label hung BELOW it — across the world's
            own selection marker and over the top of the sphere. Translating by
            half its own height puts its baseline on the standoff instead, which
            is what the standoff was measured for.
          */}
          <span
            ref={labelRef(node.id)}
            data-world-label={node.id}
            data-world-label-detail={detail || undefined}
            data-world-label-intel={node.intel}
            className="galaxy-world-label flex -translate-y-1/2 flex-col items-center gap-0.5 whitespace-nowrap text-center"
            style={{ width: 'max-content', maxWidth: planetLabelWidth(node, detail), visibility: 'hidden', textShadow: '0 1px 4px #05070d, 0 0 12px #05070d' }}
          >
            {radiation && <RadiationIndicator state={radiation} variant="bar" now={radiationNow} />}
            {/*
              THE EYE IS NOT HERE. D126. It sits in the marker stack instead, one
              step above the pin and on the pin's own scale law — the owner's
              instruction, and the only arrangement in which the two stay in step
              at every zoom. See `EyeMarks` in `PlanetField`.
            */}
            {/*
              A SELECTED UNKNOWN WORLD SAYS ONE TRUE THING. D127.

              Tapping a world selects it, and selection is the one route into this
              container that does not test `intel` — so an unsurveyed world came
              through here and was printed from the schema's DEFAULTS: an empty
              name, an empty commander, and the kind row falling through its two
              branches to read NEUTRAL. The map was answering a question the player
              had just been told it could not answer, and answering it wrong.

              The fog hides and never lies, so the label states the state. It stays
              rather than disappearing because the player asked for it by tapping,
              and a tap that produces nothing reads as a broken control.
            */}
            {node.intel === 'UNKNOWN' ? (
              <span className="legend text-micro text-faint">{t('galaxy.unsurveyed')}</span>
            ) : (
            <>
            {detail && <span className="legend text-micro flex max-w-full items-center gap-2 overflow-hidden">
              <span className={node.kind === 'CAPITAL' ? 'text-crystal' : node.kind === 'COLONY' ? 'text-opportunity' : 'text-dim'}>
                {t(node.kind === 'CAPITAL'
                  ? 'galaxy.kindCapital'
                  : node.kind === 'COLONY'
                    ? 'galaxy.kindColony'
                    : 'galaxy.kindNeutral', { tier: node.neutralTier ?? 1 })}
              </span>
              {node.isOwned && <span className="text-crystal">· {t('galaxy.owned')}</span>}
              {node.isClanmate && <span className="text-opportunity">· {t('galaxy.clanmate')}</span>}
              {rivalSlotOf(node, rivals) !== null && (
                /*
                  THE LABEL WEARS THE MARK'S OWN COLOUR TOO. D183 — the reticle on
                  the body and the word on the label have to agree, or the colour
                  stops being the thing that tells five marks apart.
                */
                <span style={{ color: rivalColour(rivalSlotOf(node, rivals) ?? 0) }}>
                  · {t('galaxy.rival')}
                </span>
              )}
              {node.state.kind === 'RECOVERY' && <span className="text-threat-ink">· {t('galaxy.recovery')}</span>}
              {node.state.kind === 'EMP' && <span className="text-crystal">· {t('galaxy.emp')}</span>}
              {/*
                WHOSE HOUR IT IS (owner, 2026-10-07): a claim in its first hour is the raider's
                alone, and "claim open" over it would send everyone else at a refusal.
              */}
              {claimTag(claimLabelOf(node, serverNow()), t)}
            </span>}
            <GalaxyCommanderName node={node} />
            <GalaxyPlanetName node={node} compact={!detail} />
            {/*
              A RECORD SAYS WHEN IT WAS TAKEN, AND WHAT IT IS. D127 · D151.

              Everything above this line on a remembered world is what a craft of
              yours saw when it was last there, and it may have been wrong for
              hours. Printing it without its age would be the map asserting
              something it cannot know — the fog hides, it never lies.

              IT USED TO PRINT A BARE DURATION. "3h 10m ago" under a confident kind
              row and a commander's name reads as decoration; what is three hours
              old is not stated, so the eye takes the rows above it as current and
              the line as trim. It names the record now — and the record is no
              longer only a probe's (D151), which is the other reason the old
              wording could not stay.

              THE ARITHMETIC IS `recordAgeMinutes` AND NOT A SECOND COPY OF IT. The
              dossier stamps the same age on its fact rows; the two ran their own
              subtraction, and a map and a panel that disagree about how old one
              world is are worse than either of them being wrong alone.
            */}
            {age !== null && (
              <span data-world-record-age className="font-v2-mono text-micro max-w-full truncate text-v2-ink-3">
                {t('galaxy.recordAge', { age: staleness(age) })}
              </span>
            )}
            </>
            )}
          </span>
        </Html>
      );
      })}
    </>
  );
}

/** The owner's private fault state, attached to the name it qualifies. */
export function GalaxyPlanetName({ node, compact = false }: { node: PlanetNode; compact?: boolean }) {
  const { t } = useTranslation();
  return (
    <span className={`${compact ? 'font-v2-ui' : 'legend'} text-micro font-normal text-v2-ink-2 flex max-w-full items-center gap-1.5`}>
      <span className="truncate">{node.name}</span>
      {node.isOwned && node.faulty ? (
        <span
          data-colony-fault-icon
          title={t('faults.mark')}
          className="text-threat-ink"
        >
          <FaultMark className="size-3.5" />
          <span className="sr-only">{t('faults.mark')}</span>
        </span>
      ) : null}
    </span>
  );
}

/** The flag is the same earned/frozen identity as the commander printed beside it. */
export function GalaxyCommanderName({ node }: { node: PlanetNode }) {
  const { i18n } = useTranslation();
  if (node.intel === 'UNKNOWN' || node.kind === 'NEUTRAL' || !node.owner) return null;
  const rank = node.honorRanking ? node.honorRank : node.dominionRank;
  return <span className="name text-caption text-bone flex max-w-full items-center gap-1.5">
    {rank ? <RankBadge rank={rank} honor={node.honorRanking} /> : null}
    <span className="min-w-0 truncate">{commanderLabel(node.owner, node.clan?.tag)}</span>
    {node.country && <Flag code={node.country} language={i18n.language} size="small" className="shrink-0" />}
  </span>;
}

/**
 * Camera behaviour.
 *
 * Free to roam the whole galaxy — an earlier version tethered the camera near the
 * player's own planet, which left half the galaxy unreachable and unclickable.
 * Three things make free roaming comfortable rather than merely possible:
 *
 * ORBIT AROUND WHAT YOU TAPPED. The single biggest comfort factor in an orbit
 * camera is whether the pivot is the thing you are looking at. Rotating a distant
 * pivot swings your subject across the screen and out of frame, and the player
 * fights the camera the whole way. Selecting a world eases the pivot onto it.
 *
 * ZOOM WHERE YOU POINT. Pinching or scrolling moves toward the cursor rather than
 * the centre of the screen, so reaching a world in the corner is one gesture
 * instead of zoom-then-pan-then-zoom.
 *
 * A LEASH RATHER THAN A WALL. Panning is unrestricted in the moment; drift far
 * enough outside the playable sphere and the pivot is eased back over the next
 * second. You cannot get lost in empty space, and you are never stopped dead
 * mid-gesture.
 */
function Rig({
  navigationRadius,
  home,
  homeSignal,
  centerSignal,
  subject,
  focusKey,
  approach: focusApproach,
  inspectionRadius,
  exactApproach = false,
  openWide = false,
  wideDistance,
  sightRadius,
  openingHome,
  sceneReady,
  openingSettled,
  openingCovered,
  openingPrepared,
  openingWork,
  openingMark,
}: {
  navigationRadius: number;
  home: [number, number, number];
  homeSignal: number;
  /** Re-take the current subject, as a fresh selection would (E11: Space). 0 is never a request. */
  centerSignal: number;
  /**
   * Where the camera should be looking, read fresh each frame.
   *
   * A function rather than a point because the subject may be MOVING: an asteroid
   * crosses the disc while the player reads its panel, and a rig that eased onto
   * where it used to be would let the thing they tapped slide out of frame.
   */
  subject: (() => [number, number, number] | null) | null;
  /**
   * WHAT IS FOCUSED, AND THE ONLY THING THAT MAY RE-FRAME THE CAMERA.
   *
   * `subject` changes identity whenever any of the six lists behind it refetches,
   * which in a live galaxy is several times a minute. Keying the ease on it made
   * the rig re-frame itself while the player sat watching. This changes when the
   * player picks something else, and at no other time.
   */
  focusKey: string | null;
  /** Pull the camera in to at most this distance while easing. Null leaves it. */
  approach: number | null;
  inspectionRadius?: number;
  /**
   * TAKE THE RANGE EXACTLY, RATHER THAN ONLY PULLING IN. Academy instruction.
   *
   * An ordinary focus is one-way on purpose: it may close on a small craft but
   * must never shove a player back out of a view they chose. A LESSON is the other
   * case — the owner asked for the target to be framed the same way every time,
   * however the commander left the camera — so the coach focus is a scripted
   * composition like the opening wide shot, and takes its distance exactly.
   */
  exactApproach?: boolean;
  /**
   * OPEN ON THE WHOLE DISC RATHER THAN ON YOUR OWN DOORSTEP. D56.
   *
   * The first frame normally snaps to the player's world, which is right for a
   * commander coming back to a season and wrong for somebody who has never seen
   * this galaxy: it answers "where am I" before they have asked it, and it makes
   * "show me my world" a control with nothing left to do. Opening wide is what
   * gives that first instruction something to be.
   */
  openWide?: boolean;
  /** The range an animated wide re-frame must reach, even when that means pulling back. */
  wideDistance: number;
  sightRadius?: number;
  openingHome: boolean;
  sceneReady: RefObject<boolean>;
  openingSettled: RefObject<boolean>;
  openingCovered: boolean;
  openingPrepared: boolean;
  openingWork: OpeningPreparation;
  openingMark: RefObject<HTMLSpanElement | null>;
}) {
  const ref = useRef<ComponentRef<typeof OrbitControls>>(null);
  const preparing = useOpeningViews({ controls: ref, covered: openingCovered, ready: openingPrepared,
    settled: openingSettled, wideDistance: Math.min(wideDistance, navigationRadius / 1.15 * 3),
    homeDistance: openingHome && !openWide && !sightRadius ? HOME_DISTANCE : null, work: openingWork });
  const invalidate = useThree((state) => state.invalidate);
  const size = useThree((state) => state.size);
  const approach = inspectionRadius === undefined ? focusApproach : planetInspectionDistance(inspectionRadius, size.width, size.height);
  /** Where the pivot is heading, how much ease is left, and how to frame it. */
  const ease = useRef<{
    to: THREE.Vector3;
    left: number;
    duration: number;
    rangeTo: number | null;
    exactRange: boolean;
    waitForScene: boolean;
  } | null>(null);

  /**
   * The live getter, mirrored so the frame loop reads the current one WITHOUT the
   * effects below depending on its identity.
   *
   * Assigned during render on purpose. A `useEffect` would land after this
   * component's own effects — and after the ease effect that has to read it on the
   * frame the focus changes — so the first frame of every new subject would track
   * the previous one's position.
   */
  const live = useRef(subject);
  live.current = subject;

  /**
   * THE SUBJECT IS GONE AND THE CAMERA STAYS WHERE IT IS. Owner-reported bug.
   *
   * A followed craft stops existing the moment it lands, turns for home, or gets
   * back — `pending`, `runs` and `contacts` simply stop carrying it. The rig read
   * that as "nothing is focused", which handed the frame straight to the LEASH
   * below: a camera that had followed a squadron out toward the rim was yanked
   * back toward the middle of the disc, at a new angle, for no reason the player
   * could connect to anything they did.
   *
   * What they asked for is what a camera should do anyway: *"focus nerede nasıl
   * kaldıysa öylece kalsın, free looking mode'una geçsin."* So losing a subject
   * releases the rig — no ease, no leash, no re-frame — and it simply stops
   * driving. The leash is a comfort rule about a player PANNING into the void, and
   * it resumes the moment they touch the controls again.
   */
  const mode = useRef<'follow' | 'released' | 'manual'>('manual');
  /** Whether this exact selection has existed in the scene at least once. */
  const acquired = useRef(false);
  /** Distinguishes initial `null` from a selection disappearing or being cleared. */
  const previousFocusKey = useRef<string | null>(null);
  const [homeX, homeY, homeZ] = home;

  const goTo = (
    x: number,
    y: number,
    z: number,
    rangeTo: number | null = null,
    exactRange = false,
    duration = EASE,
    waitForScene = false,
  ): void => {
    ease.current = {
      to: new THREE.Vector3(x, y, z),
      left: duration,
      duration,
      rangeTo,
      exactRange,
      waitForScene,
    };
    invalidate();
  };

  /**
   * TAKE A NEW SUBJECT. Keyed on `focusKey`, never on `subject` — see the prop.
   *
   * A fresh selection also clears the release latch: the player has just told the
   * rig what to look at, so it is driving again and the leash is back on duty.
   */
  useEffect(() => {
    const previous = previousFocusKey.current;
    previousFocusKey.current = focusKey;
    if (focusKey === null) {
      if (previous !== null) {
        // Losing/clearing a selection is not permission to finish an old zoom.
        ease.current = null;
        mode.current = 'released';
        acquired.current = false;
      }
      return;
    }

    mode.current = 'follow';
    acquired.current = false;
    ease.current = null;
    const at = live.current?.();
    if (at) {
      acquired.current = true;
      goTo(at[0], at[1], at[2], approach, exactApproach);
    }
    // `live` is read through a ref by design: this must not re-run when the data
    // behind the subject refetches, only when the player picks something else.
  }, [focusKey, approach, exactApproach]);

  /**
   * BRING THE SELECTION BACK. A player who panned off what they selected released the
   * leash; asking for it again (Space on a desk) takes the subject as a fresh selection
   * would. Keyed on the signal alone, so a refetch never re-frames.
   */
  useEffect(() => {
    if (centerSignal === 0) return;
    const at = live.current?.();
    if (!at) return;
    mode.current = 'follow';
    acquired.current = true;
    ease.current = null;
    goTo(at[0], at[1], at[2], approach, exactApproach);
  }, [centerSignal]);

  /**
   * HOME re-frames rather than teleports: an instant cut loses every sense of
   * where you were, and re-orienting afterwards costs more than the half second.
   *
   * This effect deliberately follows the focus effect. Home clears selection and
   * bumps the signal in one render; the explicit home instruction must therefore
   * win over the selection's passive disappearance.
   */
  useEffect(() => {
    const controls = ref.current;
    if (!controls) return;
    mode.current = 'manual';
    acquired.current = false;
    if (openWide) {
      if (homeSignal === 0) {
        controls.target.set(0, 0, 0);
        controls.object.position.set(
          0,
          wideDistance * (1.15 / WIDE_TILT),
          wideDistance * (1.75 / WIDE_TILT),
        );
        controls.update();
        // The scene renders on demand. `<Html distanceFactor>` measured the
        // default camera on its first frame and otherwise kept that stale scale
        // until the first gesture. Draw once more after the initial camera snap
        // so world labels and WebGL start on the same projection.
        invalidate();
      } else {
        // Returning to a wide tutorial beat must also be allowed to pull the
        // camera OUT. Ordinary focus ranges are one-way so a deliberate close
        // view is preserved; this is a scripted change of framing, not a focus.
        goTo(0, 0, 0, wideDistance, true);
      }
      return;
    }
    if (homeSignal === 0) {
      controls.target.set(homeX, homeY, homeZ);
      controls.object.position.set(...initialHomeCameraPosition(homeX, homeY, homeZ));
      controls.update();
      if (openingHome && openingSettled.current) goTo(homeX, homeY, homeZ, HOME_DISTANCE, true, 2, true);
      invalidate();
      return;
    }
    goTo(homeX, homeY, homeZ, HOME_DISTANCE);
    // Primitive coordinates are deliberate. `home` is rebuilt from every live
    // galaxy refetch; depending on the tuple identity made broadcasts press Home.
  }, [homeX, homeY, homeZ, homeSignal, openWide, wideDistance]);

  useEffect(() => {
    if (!sightRadius) return;
    const camera = ref.current?.object;
    if (!(camera instanceof THREE.PerspectiveCamera)) return;
    mode.current = 'manual';
    acquired.current = false;
    goTo(homeX, homeY, homeZ, sightCameraDistance(sightRadius, camera.fov, camera.aspect), true);
  }, [sightRadius]);

  useFrame((_, delta) => {
    const controls = ref.current;
    if (!controls || preparing.current) return;

    /**
     * KEEP UP WITH A MOVING SUBJECT.
     *
     * Once the initial ease has landed, a focused asteroid is tracked directly:
     * the pivot and the camera both take the subject's per-frame delta, so the
     * rock stays put on screen and the player keeps whatever angle they chose.
     * Applied as a delta rather than a lerp-to-point so it does not fight a player
     * who is orbiting at the same time.
     */
    const follow = live.current;
    const at = follow?.() ?? null;

    /** Every decision the rig makes on its own, in one pure call. See `follow.ts`. */
    const act = rigAction({
      easing: ease.current !== null,
      focused: focusKey !== null,
      positioned: at !== null,
      acquired: acquired.current,
      mode: mode.current,
    });
    if (act.cancelEase) ease.current = null;
    if (act.release) {
      mode.current = 'released';
      return;
    }
    if (act.acquire && at) {
      acquired.current = true;
      goTo(at[0], at[1], at[2], approach, exactApproach);
    }

    if (act.track && at) {
      // One scratch vector, not two new ones a frame: a tracked pan made garbage mid-flight.
      const drift = TRACK_DRIFT.set(at[0], at[1], at[2]).sub(controls.target);
      if (drift.lengthSq() > 1e-10) {
        controls.target.add(drift);
        controls.object.position.add(drift);
        controls.update();
        invalidate();
      }
    }

    /**
     * The leash. Checked continuously rather than on release, because a player who
     * has flung the camera into the void wants it back before they let go — and
     * because the correction is a lerp, it reads as the galaxy pulling rather than
     * as an edge they hit.
     */
    /**
     * The leash. Off while the rig is released, and off on the frame a subject
     * ends — see `rigAction`, which is where that rule lives and is tested.
     */
    if (act.leash) {
      const t = controls.target;
      const correction = sphericalLeashCorrection(t.x, t.y, t.z, navigationRadius);
      if (correction) goTo(correction[0], correction[1], correction[2]);
    }

    const move = ease.current;
    if (!move) return;

    // The Rig lives outside Suspense: starting on mount spends the opening on
    // model decoding / shader compilation. Wait for the compiled scene's paint,
    // then discard that loading frame's delta so the glide gets its full 2s.
    if (move.waitForScene) {
      if (sceneReady.current) move.waitForScene = false;
      invalidate();
      return;
    }

    // Frame-rate independent easing: the same curve at 30fps and at 120.
    const progress = cameraEaseStep(move.left, move.duration, delta);
    const step = progress.fraction;
    const previous = controls.target.clone();
    controls.target.lerp(move.to, Math.min(1, step));
    // The camera follows its pivot, so the framing is preserved and only the
    // subject changes. Moving the pivot alone would swing the view instead.
    controls.object.position.add(controls.target.clone().sub(previous));

    /**
     * And adjust the distance, on the same curve.
     *
     * Applied along the camera's own view vector, so the angle the player chose is
     * untouched and only the range changes. Focus is one-way: if they are already
     * closer than the approach distance, nothing happens. A scripted overview is
     * exact and may pull back, because the wider composition is the instruction.
     */
    if (move.rangeTo !== null) {
      const out = controls.object.position.clone().sub(controls.target);
      const range = out.length();
      if (move.exactRange || range > move.rangeTo) {
        const wanted = easedCameraRange(
          range,
          move.rangeTo,
          Math.min(1, step),
          move.exactRange,
        );
        controls.object.position.copy(
          controls.target.clone().add(out.setLength(wanted)),
        );
      }
    }

    controls.update();
    invalidate();

    move.left = progress.remaining;
    if (progress.done) {
      const out = controls.object.position.clone().sub(controls.target);
      controls.target.copy(move.to);
      if (move.rangeTo !== null && out.lengthSq() > 1e-10) {
        const finishedRange = finishedCameraRange(
          out.length(),
          move.rangeTo,
          move.exactRange,
        );
        controls.object.position.copy(controls.target.clone().add(out.setLength(finishedRange)));
      }
      controls.update();
      ease.current = null;
      if (openingMark.current) openingMark.current.dataset.academyHomeReady = 'true';
    }
  });

  return (
    <OrbitControls
      ref={ref}
      makeDefault
      enableDamping
      dampingFactor={0.08}
      rotateSpeed={0.5}
      zoomSpeed={0.9}
      panSpeed={0.9}
      zoomToCursor
      minPolarAngle={MIN_POLAR}
      maxPolarAngle={MAX_POLAR}
      minDistance={1.2}
      // Far enough to see the whole disc at once, and no further — past this the
      // galaxy is a smudge and the player has lost their bearings.
      maxDistance={navigationRadius / 1.15 * 3}
      screenSpacePanning
      mouseButtons={{
        LEFT: THREE.MOUSE.ROTATE,
        MIDDLE: THREE.MOUSE.DOLLY,
        RIGHT: THREE.MOUSE.PAN,
      }}
      touches={{ ONE: THREE.TOUCH.ROTATE, TWO: THREE.TOUCH.DOLLY_PAN }}
      /**
       * Touching the controls ends free-look and puts the leash back on duty.
       *
       * Without this a camera released by a vanished fleet would stay unleashed for
       * the rest of the session, and a player could then pan into empty space with
       * nothing to walk them back. The release is about not being moved WITHOUT
       * asking; the moment they ask, the ordinary rules apply again.
       */
      onStart={() => {
        // A gesture changes the framing, not the selection. Keep translating the
        // camera with a moving focused subject after the player orbits or zooms;
        // only a missing/unfocused subject becomes genuine free-look.
        const at = live.current?.() ?? null;
        const next = rigGestureState(focusKey !== null, at !== null);
        mode.current = next.mode;
        acquired.current = next.acquired;
        ease.current = null;
        // A deliberate gesture ends the scripted zoom too; don't strand its cue.
        if (openingMark.current) openingMark.current.dataset.academyHomeReady = 'true';
      }}
    />
  );
}

/**
 * A handle on the scene, in development only.
 *
 * R3F stopped exposing its store on the canvas element, and a 3D scene cannot be
 * debugged from the outside — "the planets are missing" has a dozen possible
 * causes and only the live scene graph distinguishes them. Stripped from
 * production builds by the `DEV` guard.
 */
interface DebugWindow {
  __galaxy?: unknown;
  __galaxyMetrics?: {
    snapshot: () => GalaxyMetricSnapshot;
    reset: () => void;
  };
}

interface GalaxyMetricSnapshot {
  continuous: boolean;
  frameIntervalMs: { samples: number; p50: number; p95: number; p99: number; max: number };
  longTaskMs: { samples: number; p50: number; p95: number; p99: number; max: number };
  heap: { usedBytes: number; totalBytes: number; limitBytes: number } | null;
  renderer: {
    calls: number;
    triangles: number;
    points: number;
    lines: number;
    geometries: number;
    textures: number;
    programs: number;
  };
  scene: { objects: number; meshes: number; instancedMeshes: number; instances: number };
}

const metricSummary = (input: readonly number[]) => {
  if (input.length === 0) return { samples: 0, p50: 0, p95: 0, p99: 0, max: 0 };
  const sorted = [...input].sort((a, b) => a - b);
  const at = (percentile: number): number =>
    sorted[Math.min(sorted.length - 1, Math.ceil(sorted.length * percentile / 100) - 1)] ?? 0;
  return { samples: sorted.length, p50: at(50), p95: at(95), p99: at(99), max: at(100) };
};

function DevBridge() {
  // The store object is stable. Subscribing to the entire RootState here made
  // this component re-render whenever R3F replaced that state, repeatedly
  // recreating a buffered PerformanceObserver and counting old long tasks again.
  const store = useStore();
  const frameTimes = useRef(new Float64Array(2048));
  const longTasks = useRef(new Float64Array(512));
  const frameCount = useRef(0);
  const frameCursor = useRef(0);
  const longTaskCount = useRef(0);
  const longTaskCursor = useRef(0);
  const lastFrameAt = useRef<number | null>(null);
  const enabled = import.meta.env.DEV || import.meta.env.VITE_VISUAL_TEST === '1';
  const continuous = import.meta.env.VITE_VISUAL_TEST === '1';

  useFrame(({ invalidate }) => {
    if (!enabled) return;
    const now = performance.now();
    if (lastFrameAt.current !== null) {
      frameTimes.current[frameCursor.current] = now - lastFrameAt.current;
      frameCursor.current = (frameCursor.current + 1) % frameTimes.current.length;
      frameCount.current = Math.min(frameCount.current + 1, frameTimes.current.length);
    }
    lastFrameAt.current = now;
    // `frameloop="demand"` intentionally idles in the real game. A visual test
    // requests a continuous sample so frame intervals measure rendering capacity
    // rather than the ambient ticker's chosen sleep.
    if (continuous) invalidate();
  });

  useEffect(() => {
    if (!enabled) return;
    let observer: PerformanceObserver | null = null;
    try {
      observer = new PerformanceObserver((list) => {
        for (const entry of list.getEntries()) {
          longTasks.current[longTaskCursor.current] = entry.duration;
          longTaskCursor.current = (longTaskCursor.current + 1) % longTasks.current.length;
          longTaskCount.current = Math.min(longTaskCount.current + 1, longTasks.current.length);
        }
      });
      observer.observe({ type: 'longtask', buffered: true });
    } catch {
      // Firefox and older WebViews do not expose the Long Tasks API. The rest of
      // the bridge remains useful and reports an empty window.
    }
    if (continuous) store.getState().invalidate();
    const debug = window as unknown as DebugWindow;
    // Existing visual harnesses inspect the live RootState directly. A proxy
    // keeps that API while reading the latest Zustand snapshot on every access.
    const exposedState = new Proxy(store.getState(), {
      get: (_target, property): unknown => {
        const value: unknown = Reflect.get(store.getState(), property);
        return value;
      },
    });
    debug.__galaxy = exposedState;
    const bridge = {
      snapshot: (): GalaxyMetricSnapshot => {
        const state = store.getState();
        let objects = 0;
        let meshes = 0;
        let instancedMeshes = 0;
        let instances = 0;
        state.scene.traverse((object) => {
          objects += 1;
          if (object instanceof THREE.Mesh) meshes += 1;
          if (object instanceof THREE.InstancedMesh) {
            instancedMeshes += 1;
            instances += object.count;
          }
        });
        const info = state.gl.info;
        const memory = (performance as Performance & {
          memory?: { usedJSHeapSize: number; totalJSHeapSize: number; jsHeapSizeLimit: number };
        }).memory;
        return {
          continuous,
          frameIntervalMs: metricSummary(Array.from(frameTimes.current.slice(0, frameCount.current))),
          longTaskMs: metricSummary(Array.from(longTasks.current.slice(0, longTaskCount.current))),
          heap: memory
            ? {
                usedBytes: memory.usedJSHeapSize,
                totalBytes: memory.totalJSHeapSize,
                limitBytes: memory.jsHeapSizeLimit,
              }
            : null,
          renderer: {
            calls: info.render.calls,
            triangles: info.render.triangles,
            points: info.render.points,
            lines: info.render.lines,
            geometries: info.memory.geometries,
            textures: info.memory.textures,
            programs: info.programs?.length ?? 0,
          },
          scene: { objects, meshes, instancedMeshes, instances },
        };
      },
      reset: (): void => {
        frameCount.current = 0;
        frameCursor.current = 0;
        longTaskCount.current = 0;
        longTaskCursor.current = 0;
        lastFrameAt.current = null;
      },
    };
    debug.__galaxyMetrics = bridge;
    return () => {
      observer?.disconnect();
      if (debug.__galaxy === exposedState) delete debug.__galaxy;
      if (debug.__galaxyMetrics === bridge) delete debug.__galaxyMetrics;
    };
  }, [continuous, enabled, store]);
  return null;
}

/**
 * Requests frames for the things that move on their own.
 *
 * With `frameloop="demand"` nothing renders unless something asks. The camera asks
 * while it is moving; this asks slowly and constantly, so the asteroids and the
 * dust keep drifting without paying for sixty frames a second of a still scene.
 *
 * The asking itself lives in `frames.tsx` — it used to be a `setInterval`, which
 * beat against the display's refresh and was throttled by the browser whenever it
 * decided the page was not being looked at. See that file for the measurements.
 */
/**
 * A DOM BUTTON PINNED TO A POINT IN THE GALAXY. Academy only.
 *
 * `Html` projects it every frame, so it tracks the subject through a camera move,
 * a hand-turned disc and the subject's own orbit alike. The group's position is
 * written in `useFrame` from the same `subject` closure the rig reads — a prop
 * would freeze it at whatever the point was when React last rendered, which for a
 * pirate on an orbit is wrong within a second.
 *
 * Invisible on purpose: the thing being pointed at is the pirate, the rock or the
 * world already drawn there. This is only the part a thumb can hit, and the hand
 * that points at it is `TutorialHand` finding it by `data-academy-tap-target`.
 */
function CoachTap({ subject, label, onTap }: {
  subject: () => [number, number, number] | null;
  label: string;
  onTap: () => void;
}) {
  const group = useRef<THREE.Group>(null);
  useFrame(() => {
    const at = subject();
    if (at) group.current?.position.set(at[0], at[1], at[2]);
  });
  const start = subject() ?? [0, 0, 0];
  return (
    <group ref={group} position={start}>
      <Html center zIndexRange={[40, 40]}>
        <button
          type="button"
          data-academy-tap-target
          aria-label={label}
          onClick={onTap}
          className="size-24 rounded-full"
        />
      </Html>
    </group>
  );
}

/**
 * Marks every frame the galaxy draws, for the readout in the corner. Only while
 * the readout is on; otherwise it does nothing at all.
 */
function FpsProbe() {
  const on = useFpsMeterEnabled();
  useFrame(() => {
    if (on) galaxyFrames.frame(performance.now());
  });
  return null;
}

/**
 * THE GALAXY'S SIDE OF A PERFORMANCE RECORDING (admin only, 2026-09-19).
 *
 * While a recording runs, every draw is timed and counted. Two things make that
 * honest:
 *
 *   · THE COUNT IS PER FRAME. The composer renders the scene and then its bloom and
 *     vignette passes, and `renderer.info` resets on every one of those calls — so
 *     read as-is it reports the last full-screen quad, not the galaxy. `autoReset`
 *     is off for the recording and the probe resets it once a frame instead.
 *   · THE TIME IS CPU SUBMISSION, summed over every `render` call the composer
 *     makes. A GPU timer query is what would measure the GPU, and phones rarely
 *     expose one; the stall figures (`displayFrame`) catch what the GPU costs.
 *
 * `useFrame` runs before its frame draws, so each call reports the frame before.
 */
function PerfProbe({ context, focused }: { context: Record<string, number>; focused: boolean }) {
  const recording = usePerfSession().status === 'recording';
  const gl = useThree((state) => state.gl);
  const renderMs = useRef(0);
  const key = JSON.stringify(context);

  useEffect(() => {
    setPerfGalaxyContext(JSON.parse(key) as Record<string, number>);
  }, [key]);
  useEffect(() => () => { setPerfGalaxyContext(null); }, []);
  useEffect(() => { setPerfExtra('focus', focused ? 1 : 0); }, [focused]);

  useEffect(() => {
    if (!recording) return undefined;
    // The button appears after loading; retain why loading ended in this recording.
    setPerfExtra('opening', perfPreparationCode(gl.domElement.dataset.galaxyPreparation));
    const info = gl.info;
    const autoReset = info.autoReset;
    info.autoReset = false;
    info.reset();
    const original = gl.render.bind(gl);
    gl.render = (scene, camera) => {
      const started = performance.now();
      original(scene, camera);
      renderMs.current += performance.now() - started;
    };
    return () => {
      gl.render = original;
      info.autoReset = autoReset;
    };
  }, [gl, recording]);

  useFrame((state) => {
    if (!recording) return;
    // How far the camera stands from what it orbits: zoomed in on a world, or
    // out over the whole disc. Rounded, so it is a reading rather than noise.
    const target = (state.controls as { target?: THREE.Vector3 } | null)?.target;
    setPerfExtra('camera', Math.round(target ? state.camera.position.distanceTo(target) : state.camera.position.length()));
    if (renderMs.current === 0) return;
    const info = gl.info;
    perfGalaxyFrame(renderMs.current, {
      calls: info.render.calls,
      triangles: info.render.triangles,
      geometries: info.memory.geometries,
      textures: info.memory.textures,
      programs: info.programs?.length ?? 0,
    });
    renderMs.current = 0;
    info.reset();
  });
  return null;
}

function AmbientTicker() {
  useAmbientFrames();
  return null;
}

/**
 * THE FRAME THAT PROVES THE GALAXY IS ACTUALLY UP. Owner decision.
 *
 * A preloader that fetches urls can only tell you the BYTES have arrived. Eleven
 * GLTFs then have to be parsed, their materials compiled and their buffers pushed
 * to the GPU, and on a phone that is the visible part of the wait — the part where
 * worlds appear without their instruments and each hull lands with a stutter. The
 * old cover came off on `assets.ready`, which is the moment before all of that
 * rather than after it.
 *
 * SceneWarmup sits INSIDE the same Suspense boundary as the models and prepares
 * their programs with compileAsync. The composer waits for that preparation;
 * FirstSceneFrame then reports from the animation frame AFTER its first draw,
 * including the texture/buffer uploads. Download completion alone is never ready.
 *
 * Fires once and never again. A cover that can come back is a flash.
 */
/**
 * ONE FRAME AFTER THE GPU COMES BACK.
 *
 * `frameloop` is `demand`, so this scene draws only when something asks it to.
 * A phone that dropped the WebGL context and got a new one has nothing asking:
 * `gpuContext.ts` stops the crash, and without this the reward for surviving it
 * is a still picture of whatever the last frame before the loss happened to be.
 *
 * The epoch is the trigger rather than the flag, because it moves exactly once
 * per restore. Mounted outside the composer's own gate so it is here to fire
 * when the composer comes back.
 */
function RedrawOnRestore({ epoch }: { epoch: number }) {
  const invalidate = useThree((state) => state.invalidate);
  useEffect(() => {
    invalidate();
  }, [epoch, invalidate]);
  return null;
}

/** The vertical field of view on a portrait screen. Narrowed on wide ones below. */
const GALAXY_FOV = 45;

/**
 * THE FIELD FOLLOWS THE SHAPE OF THE SCREEN. See `fovForAspect`: a wide screen or
 * a phone turned sideways gets a narrower vertical field, so the view across it
 * never widens to where the edges visibly stretch. Portrait is untouched.
 */
function WideScreenFov() {
  const camera = useThree((state) => state.camera);
  const width = useThree((state) => state.size.width);
  const height = useThree((state) => state.size.height);
  const invalidate = useThree((state) => state.invalidate);
  useEffect(() => {
    if (!(camera instanceof THREE.PerspectiveCamera)) return;
    const fov = fovForAspect(GALAXY_FOV, width / Math.max(1, height));
    if (camera.fov === fov) return;
    camera.fov = fov;
    camera.updateProjectionMatrix();
    invalidate();
  }, [camera, width, height, invalidate]);
  return null;
}

