import { towingFormation } from './towing.js';
import { TowedShips } from './TowedShips.js';
import { isAppActive, watchAppActivity } from '../platform/activity.js';
import { useGalaxyCulling, useVisualFrame } from './visualFrame.js';
import { createLocalVisibility, localSphereVisible, hullPartRadius } from './formationVisibility.js';
import { createHullBatches, shownInScene, type HullBatch, type HullBatches } from './hullBatches.js';
import { cosmeticById } from '@astera/rules';
import type { ShipCosmeticEquipment } from '@astera/rules';
import { shipHullModels } from './shipCosmetics.js';
import {
  isReferenceShip,
  markReferenceShipFailed,
  referenceHullId,
  referenceShipScene,
  useReferenceShipFailures,
} from './referenceArt.js';
import { SkinAssetBoundary } from './SkinAssetBoundary.js';
import { FleetCosmeticFlag, FormationCosmeticEngines } from './CosmeticEffects.jsx';
import { ProbeSkinBeam } from './ProbeSkinBeam.js';
import {
  Suspense,
  createContext,
  useContext,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
  type RefObject,
} from 'react';
import { useFrame, useThree, type ThreeEvent } from '@react-three/fiber';
import { Billboard, useGLTF, useTexture } from '@react-three/drei';
import { useGltfPair } from './useGltfPair.js';
import * as THREE from 'three';
import {
  INTERGALACTIC_CONVOY,
  engagementEndsAt,
  isEngaging,
  seededFrom,
  type HullId,
} from '@astera/rules';
import type { Contact, PendingThread } from '../api/schemas.js';
import {
  HULL_MODEL,
  HULL_LOD_MODEL,
  MODEL,
  MODEL_FACING,
  MODEL_POSE,
  hullPoseLift,
} from '../ui/assets.js';
import { Bombardment, bombardmentIntensity } from './Bombardment.jsx';
import { returnVolleyFrame } from './volley.js';
import { TRAIL_MAP } from './vfx.js';
import { EngineJets, type EngineUnit } from './EngineJets.js';
import { nativeEngineAnchors } from './engineAnchors.js';
import { formationEngineUnits } from './engineUnits.js';
import { StrategicExhaust, RadiationBombExhaust } from './StrategicExhaust.jsx';
import { RADIATION_BOMB_VISUAL } from '@astera/rules';
import { configureOpaqueTransparentBody, posedCraft } from './model.js';
import {
  concealedVolley,
  contactHeadingAim,
  contactPosition,
  CRAFT_SCALE,
  STRATEGIC_CONTACT_SCALE,
  STRATEGIC_HULL_SCALE_MULT,
  engagementPosition,
  engagementTargetPosition,
  isHeading,
  legEnd,
  legStandoff,
  bombardmentTarget,
  targetNodeOf,
  threadPosition,
  toWorld,
  type PlanetNode,
  type Vec3Tuple,
} from './scene.js';
import { trackingMarkStyle, trackingTicksGeometry, type TrackingKind } from './trackingMark.js';
import {
  PER_MODEL,
  formationHitBox,
  markersFor,
  type Marker,
} from './Squadrons.js';
import { STAR, rankLayout, rankRow, type RankGlyph } from './rank.js';
import { markHit, wasTap } from './tap.js';
import { CONTACT_HITBOX_KIND, HitboxMaterial } from './hitboxDebug.jsx';
import { serverNow } from '../lib/clock.js';
import {
  DEATH_STAR_LIGHT,
  HULL_LIGHT,
  TRACKING_MARK,
  UNKNOWN_CONTACT_MARK,
  formationAimDirection,
  formationAimDistance,
  formationLayout,
  hullVisualScale,
} from './flightVisual.js';
import { threadKey } from './threadKey.js';
import { useModelWarmup } from './SceneWarmup.js';
import {
  bucketFormationHulls,
  createFormationHullMatrixScratch,
  formationHullMatrix,
  shipLod,
  type FormationHullMember,
  type ShipLod,
} from './formationHullInstances.js';

export { threadKey } from './threadKey.js';

/**
 * Things moving between the worlds.
 *
 * Your own craft are real geometry — the models are a thousand triangles each and
 * they are the only objects in the scene a player watches long enough to notice a
 * billboard turning. Everything else stays flat, because everything else is either
 * a world seen from far away or a contact you are not entitled to resolve.
 *
 * WHAT IS DRAWN HERE IS EXACTLY WHAT THE PLAYER IS ENTITLED TO SEE:
 *
 *   · Your own fleets and probes, in full, along their real path.
 *   · Other people's traffic as unattributable contacts — mid-flight only, offset,
 *     no endpoints. The server decides that; this only renders it.
 *   · An inbound attack has NO path in the payload and so cannot be drawn as one.
 *     It appears as a threat on your own world, which is all radar sold you.
 */

export function OwnFleets({
  appearance,
  pending,
  nodes,
  focusedKey,
  onSelect,
}: {
  appearance?: Contact['appearance'];
  pending: readonly PendingThread[];
  /**
   * The worlds, so a leg can find the one it ends at.
   *
   * A thread carries coordinates and no id, and what a leg needs from its target
   * is how BIG it is — where to stop short of it (D44), and how far to scatter a
   * bombardment across its face. Both are the drawn radius, which only the disc
   * knows.
   */
  nodes: readonly PlanetNode[];
  focusedKey: string | null;
  onSelect: (key: string) => void;
}) {
  const flying = pending.filter((thread) => thread.path !== undefined);
  if (flying.length === 0) return null;

  return (
    <HullBatchLayer>
      {flying.map((thread, i) => {
        const key = threadKey(thread, i);
        return (
          <Flight
            key={key}
            id={key}
            thread={thread}
            appearance={thread.kind === 'incoming' ? undefined : appearance}
            nodes={nodes}
            focused={key === focusedKey}
            onSelect={() => {
              onSelect(key);
            }}
          />
        );
      })}
    </HullBatchLayer>
  );
}

/**
 * A probe reads differently from a fleet, on purpose.
 *
 * They are different bets — one costs a little of both resources and some minutes,
 * the other costs ships you cannot get back — and a player glancing at the disc
 * should never have to work out which of the two is in the air.
 *
 * TWO SIGNALS, AND THEY ANSWER DIFFERENT QUESTIONS. Owner decision.
 *
 *   NEON is on the CRAFT, and everyone who can see the craft sees it. Green means
 *   scout, blue means warship. A hull at this distance is a few dark pixels
 *   against a nebula; the rim is what makes it an object rather than a smudge, and
 *   the colour is what makes it a KIND of object without a label.
 *
 *   THE ROUTE is on the OWNER'S SCREEN ONLY, and it is orange. Where a craft is
 *   going is intent — the single most valuable thing another commander could read
 *   off this map — so it is drawn from your own pending payload and the server
 *   never sends anyone else's. Nothing here filters it: an inbound attack arrives
 *   with no `path` key at all, so there is no field for a modified client to
 *   render. See `pendingThreads` on the server.
 *
 * Orange for both legs and both kinds, because the line answers one question and
 * one question deserves one colour. The craft at its head already says which of
 * them it is.
 */
export const ROUTE_COLOUR = '#ff8b3d';

/**
 * How loud a route is. One number, and every line in the galaxy reads it.
 *
 * Taken down on the owner's eye: at 0.34 the threads were the brightest thing on
 * the disc and the worlds had to compete with them. A route is context — it says
 * where a craft you have already found is going — so it belongs under the objects
 * rather than over them. Thin and faint, and brighter only for the one you have
 * selected.
 */
export const ROUTE_OPACITY = 0.16;
export const ROUTE_OPACITY_FOCUSED = 0.42;

const ROUTE = {
  fleet: {
    url: HULL_MODEL.DART,
    scale: 0.225 * CRAFT_SCALE,
    flame: '#8fd8ff',
    /** Blue: this is a warship. */
    neon: '#3fa9ff',
  },
  probe: {
    url: MODEL.probe,
    scale: 0.18 * CRAFT_SCALE,
    flame: '#9dffc4',
    /** Green: this is the scout. */
    neon: '#3ff08a',
  },
} as const;

/**
 * Drive and silhouette colours belong to the hull, not to the mission carrying it.
 * In particular the Runner is the fast amber courier and the Breacher is the red
 * shield-breaker; painting an entire mixed fleet blue erased both identities.
 */

/**
 * The models are loaded with Draco off and meshopt on.
 *
 * Draco off matters: drei's default would build a DRACOLoader that pulls its
 * decoder from a CDN, and nothing here is Draco-compressed anyway. Meshopt is
 * bundled, so the whole thing works offline and behind a strict content policy.
 */
useGLTF.preload(MODEL.probe, false);
useGLTF.preload(HULL_MODEL.DART, false);
useGLTF.preload(MODEL.deathStar, false);

/**
 * A hull, pointed the way it is going.
 *
 * Both models come out of the generator a metre long down +Z with the origin at
 * their centre, so the parent group's own +Z is all that has to be aimed. Get
 * this wrong and a ship crabs sideways down its own route, which is the single
 * most obvious way for a scene like this to look unfinished.
 */
export function Hull(props: HullProps) {
  /*
    ITS OWN BOUNDARY, WHEREVER IT IS MOUNTED (six files mount it). A hull whose model is
    still loading costs itself; it never climbs to the scene's one boundary, which would
    hide every world, pin and fleet at once while leaving them tappable.
  */
  return (
    <Suspense fallback={null}>
      <LoadedHull {...props} />
    </Suspense>
  );
}

interface HullProps {
  url: string;
  scale: number;
  glow: string;
  focused: boolean;
  /** Landmark callers can opt out of the galaxy's distance fog. */
  fog?: boolean;
  /** Moving craft draw last in the transparent queue; landmarks keep their place in it. */
  foreground?: boolean;
}

function craftPose(url: string) {
  const hull = referenceHullId(url);
  return hull ? { rotation: [0, 0, 0] as const, height: hullPoseLift(hull) } : MODEL_POSE[url];
}

function LoadedHull({ url, scale, glow, focused, fog = true, foreground = true }: HullProps) {
  const { scene } = useGLTF(url, false);

  const model = useMemo(() => {
    // Centred, turned so the NOSE runs down +Z, and normalised into a unit box —
    // so `lookAt` points the nose and `scale` is a real world size. The facing is
    // declared per model; a bounding box cannot tell a fuselage from a wingspan.
    const clone = posedCraft(referenceShipScene(scene, url), isReferenceShip(url) ? '-z' : MODEL_FACING[url] ?? '+z', craftPose(url));
    clone.traverse((node) => {
      if (!isMesh(node)) return;
      node.renderOrder = foreground ? SHIP_ORDER : 0;
      /**
       * Marked transparent so the hull joins the LAST render queue, after every
       * world has written its depth. It is fully opaque and looks identical
       * either way; what changes is when it draws.
       *
       * WORLDS ARE OPAQUE (owner, 2026-10-08). Hulls used to clear the depth
       * buffer here so a craft stayed visible behind a planet; it then drew
       * straight through the planet. A craft behind a world is hidden by it.
       */
      const materials = materialsOf(node).map((sourceMaterial) => {
        // The GLTF cache owns the source material. Fog and finish belong to this hull.
        const material = sourceMaterial.clone();
        configureOpaqueTransparentBody(material);
        material.depthTest = true;
        if ('fog' in material) material.fog = fog;
        if (material instanceof THREE.MeshStandardMaterial) {
          material.roughness = Math.max(0.38, Math.min(0.86, material.roughness));
        }
        return material;
      });
      node.material = Array.isArray(node.material) ? materials : materials[0]!;
    });
    return clone;
  }, [scene, url, fog, foreground]);

  /*
    Owner, 2026-10-12: halve the previous 0.008 rim width and reduce opacity by 25%.
    The same values are used by the instanced hulls below.
  */
  const { outline, outlineMaterials } = useMemo(() => {
    const clone = model.clone(true);
    const owned: THREE.ShaderMaterial[] = [];
    clone.traverse((node) => {
      if (!isMesh(node)) return;
      const material = new THREE.ShaderMaterial({
        uniforms: {
          uColour: { value: new THREE.Color(glow) },
          uOpacity: { value: focused ? 0.4875 : 0.315 },
        },
        transparent: true,
        depthWrite: false,
        side: THREE.BackSide,
        blending: THREE.AdditiveBlending,
        vertexShader: `
          void main() {
            vec3 expanded = position + normal * 0.004;
            gl_Position = projectionMatrix * modelViewMatrix * vec4(expanded, 1.0);
          }
        `,
        fragmentShader: `
          uniform vec3 uColour;
          uniform float uOpacity;
          void main() {
            gl_FragColor = vec4(uColour, uOpacity);
          }
        `,
      });
      material.toneMapped = false;
      material.fog = false;
      node.material = material;
      node.renderOrder = foreground ? SHIP_ORDER - 1 : -1;
      owned.push(material);
    });
    return { outline: clone, outlineMaterials: owned };
  }, [model, url, glow, focused, foreground]);

  useEffect(
    () => () => {
      outlineMaterials.forEach((material) => { material.dispose(); });
    },
    [outlineMaterials],
  );
  useEffect(() => () => {
    model.traverse((node) => { if (isMesh(node)) materialsOf(node).forEach((material) => { material.dispose(); }); });
  }, [model]);
  // A monument first seen on a zoom out compiled and uploaded its maps in that frame.
  useModelWarmup(model);
  useModelWarmup(outline);

  return (
    <group scale={scale} name="craft-hull">
      <primitive object={outline} name="craft-silhouette-rim" />
      <primitive object={model} />
      <ProbeSkinBeam url={url} />
    </group>
  );
}

interface FormationHullPart {
  geometry: THREE.BufferGeometry;
  material: THREE.Material | THREE.Material[];
  matrix: THREE.Matrix4;
}

function formationHullParts(scene: THREE.Object3D, url: string): FormationHullPart[] {
  const model = posedCraft(referenceShipScene(scene, url), isReferenceShip(url) ? '-z' : MODEL_FACING[url] ?? '+z', craftPose(url));
  model.updateWorldMatrix(true, true);
  const parts: FormationHullPart[] = [];
  model.traverse((node) => {
    if (!isMesh(node)) return;
    parts.push({
      geometry: node.geometry,
      material: node.material,
      matrix: node.matrixWorld.clone(),
    });
  });
  return parts;
}

/** All tiers share the full material; geometry-only derivatives carry no paint of their own. */
export function formationLodParts(scene: THREE.Object3D, url: string, full: readonly FormationHullPart[]): FormationHullPart[] {
  return formationHullParts(scene, url).map((part, index) => ({ ...part, material: full[index]?.material ?? part.material }));
}

/** Each hull type writes its members into the fleet layer's shared body and outline batches. */
export function FormationHulls({
  markers,
  slots,
  scale,
  aimDistance,
  focused,
  shipSkins,
  longitudinalOffset,
  longitudinalOffsetBound = 0,
}: {
  markers: readonly Marker[];
  slots: readonly Vec3Tuple[];
  scale: number;
  aimDistance: RefObject<number>;
  focused: boolean;
  shipSkins?: ShipCosmeticEquipment;
  /** A ship's own drift along the formation (the convoy's), by its marker index and the clock. */
  longitudinalOffset?: (index: number, elapsedSeconds: number) => number;
  /** The most that drift can move a ship, so culling never drops one at the edge. */
  longitudinalOffsetBound?: number;
}) {
  const buckets = useMemo(() => bucketFormationHulls(markers, slots), [markers, slots]);
  return (
    <>
      {buckets.map((bucket) => (
        <FormationHullBucket
          key={bucket.hull}
          hull={bucket.hull}
          members={bucket.members}
          scale={scale}
          aimDistance={aimDistance}
          focused={focused}
          shipSkins={shipSkins}
          longitudinalOffset={longitudinalOffset}
          longitudinalOffsetBound={longitudinalOffsetBound}
        />
      ))}
    </>
  );
}

interface FormationHullBucketProps {
  hull: Marker['hull'];
  members: readonly FormationHullMember[];
  scale: number;
  aimDistance: RefObject<number>;
  focused: boolean;
  shipSkins?: ShipCosmeticEquipment;
  longitudinalOffset?: (index: number, elapsedSeconds: number) => number;
  longitudinalOffsetBound: number;
}

function FormationHullBucket(props: FormationHullBucketProps) {
  const { hull, shipSkins } = props;
  const { model: url, lodModel: lowUrl } = shipHullModels(hull, shipSkins);
  return (
    <SkinAssetBoundary key={`${url}:${lowUrl}`} onError={() => { markReferenceShipFailed(url); }} fallback={
      <Suspense fallback={null}>
        <LoadedFormationHullBucket {...props} url={HULL_MODEL[hull]} lowUrl={HULL_LOD_MODEL[hull]} />
      </Suspense>
    }>
      <Suspense fallback={null}>
        <LoadedFormationHullBucket {...props} url={url} lowUrl={lowUrl} />
      </Suspense>
    </SkinAssetBoundary>
  );
}

function LoadedFormationHullBucket({ hull, members, scale, aimDistance, focused, url, lowUrl, longitudinalOffset, longitudinalOffsetBound }:
  FormationHullBucketProps & { url: string; lowUrl: string }) {
  const [full, low] = useGltfPair(url, lowUrl);
  const scene = full.scene;
  const lowScene = low.scene;
  const fullParts = useMemo(() => formationHullParts(scene, url), [scene, url]);
  // LOD geometry has the same authored axes and pose as its source model.
  const lowParts = useMemo(() => {
    if (lowScene === scene) return fullParts;
    return formationLodParts(lowScene, url, fullParts);
  }, [lowScene, scene, url, fullParts]);
  const anchor = useRef<THREE.Group>(null);
  return (
    <group ref={anchor} name={`formation-hulls-${hull.toLowerCase()}`}>
      {fullParts.map((part, index) => (
        <FormationHullPartMesh
          key={`full:${part.geometry.uuid}:${String(index)}`}
          anchor={anchor}
          part={part}
          lod="full"
          members={members}
          scale={scale}
          aimDistance={aimDistance}
          glow={HULL_LIGHT[hull].glow}
          focused={focused}
          longitudinalOffset={longitudinalOffset}
          longitudinalOffsetBound={longitudinalOffsetBound}
        />
      ))}
      {lowParts.map((part, index) => (
        <FormationHullPartMesh
          key={`low:${part.geometry.uuid}:${String(index)}`}
          anchor={anchor}
          part={part}
          lod="low"
          members={members}
          scale={scale}
          aimDistance={aimDistance}
          glow={HULL_LIGHT[hull].glow}
          focused={focused}
          longitudinalOffset={longitudinalOffset}
          longitudinalOffsetBound={longitudinalOffsetBound}
        />
      ))}
    </group>
  );
}

/**
 * WHERE EVERY FORMATION'S HULLS ARE DRAWN (owner, 2026-10-20: "fps'te çok fazla dalgalanma
 * olmamalı"). One layer per fleet root; see `hullBatches.ts` for why a frame is a number.
 */
export const HullBatchContext = createContext<HullBatches | null>(null);

export function HullBatchLayer({ children }: { children: ReactNode }) {
  const batches = useMemo(createHullBatches, []);
  // The batches hold world matrices, so they hang off the scene itself, never a moving group.
  const scene = useThree((state) => state.scene);
  useEffect(() => {
    scene.add(batches.root);
    return () => { scene.remove(batches.root); };
  }, [scene, batches]);
  useVisualFrame(({ clock }) => { batches.settle(clock.elapsedTime); });
  return <HullBatchContext.Provider value={batches}>{children}</HullBatchContext.Provider>;
}

function useHullBatches(): HullBatches {
  const batches = useContext(HullBatchContext);
  if (!batches) throw new Error('Formation hulls are drawn inside a HullBatchLayer');
  return batches;
}

function hullBodyMaterial(source: THREE.Material | THREE.Material[]): THREE.Material | THREE.Material[] {
  const clones = (Array.isArray(source) ? source : [source]).map((material) => {
    const clone = material.clone();
    configureOpaqueTransparentBody(clone);
    if (clone instanceof THREE.MeshStandardMaterial) clone.roughness = Math.max(0.38, Math.min(0.86, clone.roughness));
    return clone;
  });
  return Array.isArray(source) ? clones : clones[0]!;
}

function hullOutlineMaterial(glow: string, focused: boolean): THREE.ShaderMaterial {
  return new THREE.ShaderMaterial({
    uniforms: {
      uColour: { value: new THREE.Color(glow) },
      uOpacity: { value: focused ? 0.4875 : 0.315 },
    },
    transparent: true,
    depthWrite: false,
    side: THREE.BackSide,
    blending: THREE.AdditiveBlending,
    vertexShader: `
      void main() {
        vec4 expanded = vec4(position + normal * 0.004, 1.0);
        #ifdef USE_INSTANCING
          expanded = instanceMatrix * expanded;
        #endif
        gl_Position = projectionMatrix * modelViewMatrix * expanded;
      }
    `,
    fragmentShader: `
      uniform vec3 uColour;
      uniform float uOpacity;
      void main() { gl_FragColor = vec4(uColour, uOpacity); }
    `,
    toneMapped: false,
  });
}

const materialIds = (material: THREE.Material | THREE.Material[]): string =>
  (Array.isArray(material) ? material : [material]).map((row) => row.uuid).join(',');

function FormationHullPartMesh({
  anchor,
  part,
  lod,
  members,
  scale,
  aimDistance,
  glow,
  focused,
  longitudinalOffset,
  longitudinalOffsetBound,
}: {
  /** The bucket's group: the formation space every member's matrix is written from. */
  anchor: RefObject<THREE.Group | null>;
  part: FormationHullPart;
  lod: ShipLod;
  members: readonly FormationHullMember[];
  scale: number;
  aimDistance: RefObject<number>;
  glow: string;
  focused: boolean;
  longitudinalOffset?: (index: number, elapsedSeconds: number) => number;
  longitudinalOffsetBound: number;
}) {
  const batches = useHullBatches();
  const body = useRef<HullBatch | null>(null);
  const outline = useRef<HullBatch | null>(null);

  useEffect(() => {
    const batch = batches.acquire(`body:${lod}:${part.geometry.uuid}:${materialIds(part.material)}`, () => ({
      geometry: part.geometry, material: hullBodyMaterial(part.material), renderOrder: SHIP_ORDER, name: `formation-hull-bodies-${lod}`,
    }));
    body.current = batch;
    return () => {
      body.current = null;
      batches.release(batch);
    };
  }, [batches, lod, part.geometry, part.material]);
  useEffect(() => {
    const batch = batches.acquire(`outline:${lod}:${part.geometry.uuid}:${glow}:${String(focused)}`, () => ({
      geometry: part.geometry, material: hullOutlineMaterial(glow, focused), renderOrder: SHIP_ORDER - 1, name: `formation-hull-outlines-${lod}`,
    }));
    outline.current = batch;
    return () => {
      outline.current = null;
      batches.release(batch);
    };
  }, [batches, lod, part.geometry, glow, focused]);

  const rootMatrix = useMemo(() => new THREE.Matrix4(), []);
  const instanceMatrix = useMemo(() => new THREE.Matrix4(), []);
  const worldPoint = useMemo(() => new THREE.Vector3(), []);
  const scratch = useMemo(createFormationHullMatrixScratch, []);
  const drifted = useMemo<Vec3Tuple>(() => [0, 0, 0], []);

  const culling = useGalaxyCulling();
  const visibility = useMemo(createLocalVisibility, []);
  const radius = useMemo(() => {
    const partRadius = hullPartRadius(part.geometry, part.matrix);
    return members.reduce((bound, member) => Math.max(bound,
      Math.hypot(...member.offset) + Math.abs(hullVisualScale(member.marker.hull, scale)) * partRadius), 0) + longitudinalOffsetBound;
  }, [members, part, scale, longitudinalOffsetBound]);
  useVisualFrame(({ camera, clock }) => {
    const space = anchor.current;
    const bodies = body.current;
    const rims = outline.current;
    if (!space || !bodies || !rims || !shownInScene(space)) return;
    if (!culling) space.updateWorldMatrix(true, false);
    else if (!localSphereVisible(visibility, camera, space, radius)) return;
    const parentScale = space.matrixWorld.getMaxScaleOnAxis();
    members.forEach((member) => {
      drifted[0] = member.offset[0];
      drifted[1] = member.offset[1];
      drifted[2] = member.offset[2] + (longitudinalOffset?.(member.index, clock.elapsedTime) ?? 0);
      worldPoint.set(...drifted).applyMatrix4(space.matrixWorld);
      const radius = hullVisualScale(member.marker.hull, scale) * parentScale * 0.5;
      if (shipLod(radius, camera.position.distanceTo(worldPoint)) !== lod) return;
      formationHullMatrix(
        member.marker,
        drifted,
        scale,
        aimDistance.current,
        rootMatrix,
        scratch,
      );
      instanceMatrix.multiplyMatrices(space.matrixWorld, rootMatrix).multiply(part.matrix);
      batches.write(bodies, clock.elapsedTime, instanceMatrix);
      batches.write(rims, clock.elapsedTime, instanceMatrix);
    });
  });

  return null;
}

/**
 * The exhaust.
 *
 * A stack of soft billboards down the thrust axis rather than one flat sprite or
 * one cone. Both of those were tried and both are wrong for a top-down galaxy: a
 * single quad vanishes the moment you look at the ship from above, and a cone
 * renders as a hard-edged wedge that reads as a searchlight rather than as fire.
 *
 * Overlapping billboards have neither problem. They face the camera from every
 * angle, so there is no viewing direction where the engine appears to be off, and
 * because they overlap under additive blending they accumulate into something with
 * a bright core and a soft edge — volume, not a shape. Short on purpose: a long
 * plume reads as a comet, and this is a craft.
 */
/** Last in the transparent queue, still depth-tested against the worlds. */
const SHIP_ORDER = 999;

/**
 * `instanceof Mesh` narrows to `Mesh<any, any, any>` in three's own types, which
 * loses every material type downstream. The runtime flag is the narrowing three
 * itself uses internally, and it comes back typed.
 */
function isMesh(node: THREE.Object3D): node is THREE.Mesh {
  return (node as { isMesh?: boolean }).isMesh === true;
}

/**
 * `Mesh.material` is one or many, and the narrowing above now says so.
 *
 * `isMesh` used to narrow to `Mesh<BufferGeometry, Material>` — a SINGLE material,
 * which three's own default type does not claim. That made every array case a
 * runtime-only hazard the compiler could not see, and the first draft of
 * `dimMeshMaterials` was written against the lie and would have thrown on a
 * multi-primitive hull, inside a render memo, taking the scene down with it.
 */
function materialsOf(mesh: THREE.Mesh): THREE.Material[] {
  return Array.isArray(mesh.material) ? mesh.material : [mesh.material];
}



/** Native jet attachments share the same posed model space in flights and inspection. */
export function Exhaust({ url, colour, scale }: {
  url: string;
  colour: string;
  scale: number;
}) {
  const aim = useRef(1000);
  const units = useMemo<EngineUnit[]>(() => [{
    at: [0, 0, 0], nozzles: nativeEngineAnchors(url) ?? [[0, 0, -0.42]],
    size: scale, colour, intensity: 0.8,
    widthFactor: 1, lengthFactor: 1,
  }], [url, colour, scale]);
  if (units[0]?.nozzles.length === 0) return null;
  return <SkinAssetBoundary fallback={null}><Suspense fallback={null}>
    <EngineJets units={units} aimDistance={aim} name="craft-engine-jets" />
  </Suspense></SkinAssetBoundary>;
}

/**
 * ONE LINE BUFFER PER CRAFT, FOR AS LONG AS THAT CRAFT EXISTS.
 *
 * Every route on this disc was a `BufferGeometry` built inside a `useMemo` keyed on
 * the leg's endpoints — and those endpoints were derived from a payload that came
 * back as a brand new object on every single refetch (see `api/structural.ts`). So
 * a new buffer was allocated for every craft in the galaxy every time `pending` or
 * `traffic` was read, several times a minute.
 *
 * AND THE OLD ONE WAS NEVER FREED. Replacing the `geometry` prop on a mounted
 * object hands three.js a new buffer and simply drops the old one on the floor;
 * nothing disposes it, because nothing unmounted. That is a GPU allocation per
 * craft per refetch, for as long as the tab is open, and it is invisible until the
 * scene starts to stutter on a phone an hour into a session.
 *
 * Both ends are written every frame anyway — the near end has to follow the craft —
 * so the buffer never needed rebuilding at all. It is allocated once, mutated in
 * place, and disposed when the craft it belongs to leaves the disc.
 *
 * `enabled` is for the one caller that may have no line: a contact only publishes a
 * route when it is a mining or salvage run (D24). Passed as a flag rather than
 * decided by the caller so the hook is still called unconditionally, which is what
 * the rules of hooks require.
 */
export function useLine(): THREE.BufferGeometry;
export function useLine(enabled: boolean): THREE.BufferGeometry | null;
export function useLine(enabled = true): THREE.BufferGeometry | null {
  const geometry = useMemo(() => {
    if (!enabled) return null;
    const g = new THREE.BufferGeometry();
    // Two points, filled on the first frame. Never resized after this.
    g.setAttribute('position', new THREE.Float32BufferAttribute(new Float32Array(6), 3));
    return g;
  }, [enabled]);

  useEffect(
    () => () => {
      geometry?.dispose();
    },
    [geometry],
  );

  return geometry;
}

function Flight({
  appearance,
  id,
  thread,
  nodes,
  focused,
  onSelect,
}: {
  appearance?: Contact['appearance'];
  /** The same key focus uses. Stable across refetches, so a volley does not re-roll. */
  id: string;
  thread: PendingThread;
  nodes: readonly PlanetNode[];
  focused: boolean;
  onSelect: () => void;
}) {
  const path = thread.path;
  const convoyEngagementPath = thread.kind === 'intergalactic_convoy'
    ? thread.engagementPath
    : undefined;
  const isProbe = thread.kind === 'probe';
  const isDeathStar = thread.kind === 'death_star';
  const isBomb = thread.kind === 'radiation_bomb';
  const bombVisual = RADIATION_BOMB_VISUAL[thread.radiationBombLevel ?? 1];
  const style = isBomb ? { ...ROUTE.probe, url: `/assets/models/missiles/radiation-bomb-l${String(thread.radiationBombLevel ?? 1)}.glb`,
    scale: bombVisual.length, neon: bombVisual.glow, flame: bombVisual.flame } : isProbe ? ROUTE.probe : ROUTE.fleet;
  const group = useRef<THREE.Group>(null);
  const formationAim = useRef(100);

  const to = useMemo(() => (path ? toWorld(path.to) : ([0, 0, 0] as Vec3Tuple)), [path]);

  /**
   * A CRAFT ARRIVES IN ORBIT, NOT AT THE MIDDLE OF A WORLD — AND LEAVES FROM THERE
   * AGAIN. D44.
   *
   * The leg's endpoint is the target planet's own coordinates, which are its
   * centre — so an arriving squadron used to be drawn inside the thing it had come
   * to attack. That was invisible while an arrival lasted zero seconds; the
   * engagement window makes it a moment somebody watches, and it is also the
   * distance the missiles have to cross.
   *
   * The RETURN leg reads the same figure at its own near end, so a fleet sets off
   * home from the point it was holding rather than from the middle of the world.
   * See `legStandoff` for what the seam looked like before it did.
   */
  const standoff = useMemo(() => legStandoff(thread, nodes), [thread, nodes]);
  /**
   * Only the FAR end is needed here now.
   *
   * The near end used to be baked into the route's geometry at construction; it is
   * written from the craft's own position every frame instead, so `legStart` is left
   * to `threadPosition`, which is the one place a leg's beginning still decides
   * anything. Keeping a second copy of it here was what forced the geometry to be
   * rebuilt whenever the standoff memo produced a new object.
   */
  const stop = useMemo(
    () => (path ? legEnd(path, standoff.end) : ([0, 0, 0] as Vec3Tuple)),
    [path, standoff],
  );
  const convoyTargetStart = useMemo(
    () => path && convoyEngagementPath ? toWorld(path.to) : null,
    [path, convoyEngagementPath],
  );
  const convoyTargetEnd = useMemo(() => {
    if (!convoyEngagementPath || !convoyTargetStart) return null;
    const attackerStart = toWorld(convoyEngagementPath.from);
    const attackerEnd = toWorld(convoyEngagementPath.to);
    return [
      convoyTargetStart[0] + attackerEnd[0] - attackerStart[0],
      convoyTargetStart[1] + attackerEnd[1] - attackerStart[1],
      convoyTargetStart[2] + attackerEnd[2] - attackerStart[2],
    ] as Vec3Tuple;
  }, [convoyEngagementPath, convoyTargetStart]);
  const convoyReach = useMemo(() => {
    if (!convoyEngagementPath || !convoyTargetStart) return 0;
    const attackerStart = toWorld(convoyEngagementPath.from);
    return Math.hypot(
      convoyTargetStart[0] - attackerStart[0],
      convoyTargetStart[1] - attackerStart[1],
      convoyTargetStart[2] - attackerStart[2],
    );
  }, [convoyEngagementPath, convoyTargetStart]);

  /**
   * What this leg bombards, and how big it is — see `bombardmentTarget`.
   *
   * The rule lives in `scene.ts` beside `legStandoff` rather than here: a pirate
   * raid used to be given `{ radius: 0 }` from this memo, and because the radius
   * is what scatters a volley's aim, both `volleyFor` and `Bombardment` refuse it
   * — so the attacker's own engagement drew nothing and no test could see that.
   */
  const target = useMemo(() => bombardmentTarget(thread, nodes), [thread, nodes]);

  /**
   * The formation. D20 / D40: one model per `PER_MODEL` ships, pips for the rest.
   * Every marker the fleet needs, with nothing cut — D115.
   *
   * A probe is always exactly one craft and gets no pips — empty slots above
   * a scout would be stating a capacity it does not have.
   */
  const towing = useMemo(() => towingFormation(thread.fleet ?? {}, thread.leg === 'return' ? thread.towing : undefined, style.scale),
    [thread.fleet, thread.towing, thread.leg, style.scale]);
  const markers = isProbe || isDeathStar || isBomb ? null : towing.markers;

  /** Sized by the largest drawn hull, so capital craft cannot overlap a Dart grid. */
  const formation = useMemo(() => markers ? towing : formationLayout(null, style.scale), [markers, towing, style.scale]);
  const slots = formation.slots;
  const formationScale = formation.scale;
  const hitBox = useMemo(() => formationHitBox([...slots, ...towing.tows.map(tow => tow.position)],
    Math.max(formationScale, ...towing.tows.map(tow => hullVisualScale(tow.hull, style.scale)))),
    [slots, formationScale, towing.tows, style.scale]);

  const engaging = useEngagement(
    path ? path.arriveAt.getTime() : null,
    thread.kind === 'intergalactic_convoy' ? thread.engagementEndsAt?.getTime() : undefined,
  );
  /**
   * A Death Star is spent at the instant it lands: it is the explosion. Kept here
   * rather than left to the payload because the mission is only resolved on the
   * worker's next tick, and until then this craft is still in `pending` — which
   * drew the weapon hovering over the world it had just detonated on.
   */
  const spent = useStrikeConsumed((isDeathStar || isBomb) && path ? path.arriveAt.getTime() : null);
  // A cloud finished this wing (D15): it leaves the disc where it died, not at a landing.
  const perished = useStrikeConsumed(thread.fadeAt ? thread.fadeAt.getTime() : null);

  /**
   * THE ROUTE IS ONLY EVER WHAT IS LEFT TO FLY.
   *
   * It starts at the craft's nose and ends at the target — no line behind it, so a
   * fleet does not drag a record of where it came from across the disc. Read as
   * intent rather than as a trail: a thread the ship is pulling itself along, thin
   * enough that a glance at the galaxy sees worlds first and traffic second.
   */
  const line = useLine();

  useFrame(() => {
    if (!path || !group.current) return;
    const now = serverNow();
    const convoyPhase = convoyEngagementPath !== undefined
      && convoyTargetStart !== null
      && convoyTargetEnd !== null
      && now >= convoyEngagementPath.departAt.getTime()
      && now < convoyEngagementPath.arriveAt.getTime();
    // The same helper the camera reads, so a focused squadron stays centred.
    const at = convoyPhase
      ? threadPosition(convoyEngagementPath, now, { start: 0, end: 0 })
      : threadPosition(path, now, standoff);
    const targetAt = convoyPhase
      ? (() => {
          const span = convoyEngagementPath.arriveAt.getTime()
            - convoyEngagementPath.departAt.getTime();
          const progress = span <= 0
            ? 1
            : Math.max(0, Math.min(1, (now - convoyEngagementPath.departAt.getTime()) / span));
          return [
            convoyTargetStart[0] + (convoyTargetEnd[0] - convoyTargetStart[0]) * progress,
            convoyTargetStart[1] + (convoyTargetEnd[1] - convoyTargetStart[1]) * progress,
            convoyTargetStart[2] + (convoyTargetEnd[2] - convoyTargetStart[2]) * progress,
          ] as Vec3Tuple;
        })()
      : to;
    group.current.position.set(at[0], at[1], at[2]);
    // Floored against the squadron's own size for the reason written over
    // `formationAimDistance`: on the last seconds of an approach the destination
    // comes inside the formation, and aiming each slot at it splays the wing.
    formationAim.current = formationAimDistance(
      Math.hypot(targetAt[0] - at[0], targetAt[1] - at[1], targetAt[2] - at[2]),
      formationScale,
    );
    /**
     * Nose on the destination.
     *
     * Both models are built a metre long down +Z, which is the axis `lookAt`
     * aims, so pointing the group at the far end of the leg points the ship. Done
     * this way rather than with a rotation between two vectors: that gives the
     * shortest rotation, which is correct about the nose and arbitrary about
     * everything else, and a craft rolled onto its side on the way home was the
     * result. `lookAt` keeps the hull level because it resolves the roll against
     * world up.
     */
    group.current.lookAt(targetAt[0], targetAt[1], targetAt[2]);

    /**
     * BOTH ENDS, EVERY FRAME — which is also why the geometry itself never changes.
     *
     * The near end has always followed the craft. The far end used to be baked in
     * at construction, so the geometry had to be REBUILT whenever the leg's endpoint
     * memo produced a new tuple — which was every refetch, because the payload
     * behind it was a fresh object every time. Writing six floats is cheaper than
     * allocating a buffer, and it means the one buffer lives exactly as long as the
     * flight does. See `useLine`.
     */
    const points = line.getAttribute('position') as THREE.BufferAttribute;
    const nose = style.scale * 0.6;
    const lineEnd = convoyPhase ? targetAt : stop;
    const dx = lineEnd[0] - at[0];
    const dy = lineEnd[1] - at[1];
    const dz = lineEnd[2] - at[2];
    const left = Math.hypot(dx, dy, dz);
    const k = left > nose ? nose / left : 0;
    points.setXYZ(0, at[0] + dx * k, at[1] + dy * k, at[2] + dz * k);
    points.setXYZ(1, lineEnd[0], lineEnd[1], lineEnd[2]);
    points.needsUpdate = true;
  });

  if (!path || spent || perished) return null;

  return (
    <>
      {/*
        THE ROUTE. Yours alone — see `ROUTE_COLOUR`.

        Frustum culling off: the geometry moves every frame and its bounds do not.
        Faint on purpose — see `ROUTE_OPACITY`. It was a hairline at 0.09, which
        hid the one thing it exists to show, then too loud at 0.34, which made the
        threads the brightest objects on the disc. This is the settled middle.
      */}
      <lineSegments geometry={line} frustumCulled={false}>
        <lineBasicMaterial
          color={ROUTE_COLOUR}
          transparent
          opacity={focused ? ROUTE_OPACITY_FOCUSED : ROUTE_OPACITY}
          depthWrite={false}
          blending={THREE.AdditiveBlending}
        />
      </lineSegments>

      <group ref={group} name="flight" userData={{ craftId: id }}>
        {!isProbe && !isDeathStar && !isBomb && appearance?.flagId &&
          <Suspense fallback={null}><FleetCosmeticFlag id={appearance.flagId} scale={formationScale} /></Suspense>}
        {/*
          One generous invisible target for the whole squadron. Picking an
          individual model would be fiddly on a phone and would say the models are
          separately meaningful, which they are not — the squadron is the object.
        */}
        <mesh
          position={hitBox.centre}
          onPointerUp={(event) => {
            if (!wasTap()) return;
            markHit();
            event.stopPropagation();
            onSelect();
          }}
        >
          <boxGeometry args={hitBox.size} />
          <HitboxMaterial kind={isDeathStar ? 'deathStar' : isProbe ? 'probe' : 'fleet'} />
        </mesh>

        <TrackingMark
          kind={isBomb ? 'radiation_bomb' : isDeathStar ? 'death_star' : isProbe ? 'probe' : 'fleet'}
          scale={isDeathStar ? style.scale * STRATEGIC_HULL_SCALE_MULT : style.scale}
          colour={isDeathStar ? DEATH_STAR_LIGHT.glow : style.neon}
          focused={focused}
        />

        <Suspense fallback={null}>
          {markers ? (
            <>
              {appearance?.engineId && <FormationCosmeticEngines id={appearance.engineId} markers={markers} slots={slots} scale={style.scale} aimDistance={formationAim} shipSkins={appearance.shipSkins} />}
              <FormationLightField
                customEngine={Boolean(appearance?.engineId)}
                shipSkins={appearance?.shipSkins}
                markers={markers}
                slots={slots}
                scale={style.scale}
                aimDistance={formationAim}
                focused={focused}
                showPips
              />
              <FormationWakes
                markers={markers}
                slots={slots}
                scale={style.scale}
                aimDistance={formationAim}
              />
              <FormationHulls
                markers={markers}
                slots={slots}
                scale={style.scale}
                aimDistance={formationAim}
                focused={focused}
                shipSkins={appearance?.shipSkins}
              />
              {towing.tugIndex !== null && towing.tows.length > 0 && <TowedShips HullsComponent={FormationHulls} shipSkins={appearance?.shipSkins}
                tows={towing.tows} tug={markers[towing.tugIndex]!} tugSlot={slots[towing.tugIndex]!}
                scale={style.scale} aimDistance={formationAim} focused={focused} />}
            </>
          ) : (
            <>
              <Wake
                scale={isDeathStar ? style.scale * STRATEGIC_HULL_SCALE_MULT : style.scale}
                colour={isDeathStar ? DEATH_STAR_LIGHT.glow : style.neon}
                lengthScale={isDeathStar ? 0.5 : 1}
              />
              <Hull
                url={isDeathStar ? MODEL.deathStar : isProbe && appearance?.probeId ? cosmeticById(appearance.probeId)?.model ?? style.url : style.url}
                scale={isDeathStar ? style.scale * STRATEGIC_HULL_SCALE_MULT : style.scale}
                glow={isDeathStar ? DEATH_STAR_LIGHT.glow : style.neon}
                focused={focused}
              />
              {isDeathStar ? (
                <StrategicExhaust scale={style.scale * STRATEGIC_HULL_SCALE_MULT} />
              ) : isBomb ? (
                <RadiationBombExhaust level={thread.radiationBombLevel ?? 1} />
              ) : (
                <Exhaust
                  url={appearance?.probeId ? cosmeticById(appearance.probeId)?.model ?? MODEL.probe : MODEL.probe}
                  colour={style.flame}
                  scale={style.scale}
                />
              )}
            </>
          )}
        </Suspense>

        {/*
          THE ENGAGEMENT. D44.

          Ten seconds from the moment the fleet is over the world, drawn inside the
          squadron's own group so a missile's line is simply "from this craft,
          straight ahead, to that world". Mounted only while the window is open, so
          nothing is allocated for the forty minutes of flight that precede it.

          A WORLD STATES ITS OWN SIZE; A PIRATE HAS NONE, so the volley scatters
          across this squadron's own footprint instead — which is the identical
          rule the public path a few hundred lines down already used. It did not
          used to be: this side took a stated three world units, more than twice the
          largest planet in the game, so the owner's rounds sprayed over a disc
          nothing was standing in while every bystander watched a tight volley on
          the same battle. `bombardmentTarget` answers `null` for "no world here".
        */}
        {target && engaging && (() => {
          const reach = Math.hypot(to[0] - stop[0], to[1] - stop[1], to[2] - stop[2]);
          const back = returnVolleyFrame(reach);
          return (
            <>
              <Bombardment
                volleyKey={id}
                slots={slots}
                distance={reach}
                radius={target.radius ?? formationScale}
                shipScale={style.scale}
                arriveAt={path.arriveAt.getTime()}
                strikesWorld={target.radius !== null}
              />
              {/*
                AND THE PIRATE SHOOTS BACK. Owner report: *"Korsan filo ile
                savaşırken bize neden korsan ateş etmiyor."*

                The rules were two-sided all along — the Academy's own fight kills
                one of the two Darts it sends — but the disc only ever drew this
                squadron firing. Ten seconds of target practice, and the Dart that
                never came home had been shot by nobody.

                ONLY AT A PIRATE, and that limit is the honest part. A pirate
                always has a crew: its roster is generated and `pirates.test.ts`
                holds the line that it can fight back, so rounds coming out of one
                are always true. A WORLD is not — drawing fire out of an
                undefended planet would be the renderer inventing a garrison,
                which is exactly what the fog rules forbid.
              */}
              {thread.kind === 'pirate' && (
                <group position={back.position} rotation={back.rotation}>
                  <Bombardment
                    volleyKey={`${id}:return`}
                    slots={[[0, 0, 0]]}
                    distance={reach}
                    radius={formationScale}
                    shipScale={style.scale}
                    arriveAt={path.arriveAt.getTime()}
                  />
                </group>
              )}
            </>
          );
        })()}
        {thread.kind === 'intergalactic_convoy' && engaging && convoyReach > 0 ? (
          <Bombardment
            volleyKey={`convoy:${id}`}
            slots={slots}
            distance={convoyReach}
            radius={Math.max(0.5, formationScale)}
            shipScale={style.scale}
            arriveAt={path.arriveAt.getTime()}
            engagementSeconds={INTERGALACTIC_CONVOY.engagementSeconds}
          />
        ) : null}
      </group>
    </>
  );
}

/**
 * Native thruster particles for the entire formation share one instanced draw.
 * URL-specific attachment points follow the aimed hull; equipped cosmetics keep
 * their separate engines. Existing pip and rank fields retain their count semantics.
 */
export function FormationLightField({
  markers,
  slots,
  scale,
  aimDistance,
  focused,
  showPips,
  name = 'formation-lights',
  intensity = 1,
  customEngine = false,
  shipSkins,
  longitudinalOffset,
  longitudinalOffsetBound,
}: {
  markers: readonly Marker[];
  slots: readonly Vec3Tuple[];
  scale: number;
  aimDistance: RefObject<number>;
  focused: boolean;
  showPips: boolean;
  name?: string;
  intensity?: number;
  customEngine?: boolean;
  shipSkins?: ShipCosmeticEquipment;
  longitudinalOffset?: (markerIndex: number, elapsedSeconds: number) => number;
  longitudinalOffsetBound?: number;
}) {
  const failureVersion = useReferenceShipFailures();
  const units = useMemo(() => formationEngineUnits(markers, slots, scale, shipSkins, intensity),
    [markers, slots, scale, shipSkins, failureVersion, intensity]);

  return (
    <>
      {!customEngine && <SkinAssetBoundary fallback={null}><Suspense fallback={null}>
        <EngineJets units={units} aimDistance={aimDistance} name={name} longitudinalOffset={longitudinalOffset} longitudinalOffsetBound={longitudinalOffsetBound} />
      </Suspense></SkinAssetBoundary>}
      {showPips && (
        <>
          <FormationPips markers={markers} slots={slots} scale={scale} focused={focused} />
          <FormationRanks markers={markers} slots={slots} scale={scale} />
        </>
      )}
    </>
  );
}

/**
 * A SQUADRON MARK IS DEPTH-TESTED AS IF A HULL AND A HALF NEARER THE CAMERA.
 *
 * Pips sit above a hull and rank badges under it, and both are depth-tested so a
 * world in front hides them (owner, 2026-10-08). At their own depth a steep camera
 * put the hull in front of its badge and erased it. The lead is the hull's own size:
 * the squadron cannot cover its marks, a planet in front still does, and the lead
 * never reaches past half the distance to the camera.
 */
const MARK_LEAD = 1.5;
const MARK_LEAD_DEPTH = `
  vec4 lead = projectionMatrix * vec4(mv.xy, min(mv.z + aLead, mv.z * 0.5), 1.0);
  gl_Position.z = lead.z / lead.w * gl_Position.w;
`;

function FormationPips({
  markers,
  slots,
  scale,
  focused,
}: {
  markers: readonly Marker[];
  slots: readonly Vec3Tuple[];
  scale: number;
  focused: boolean;
}) {
  const geometry = useMemo(() => {
    const count = markers.length * PER_MODEL;
    const positions = new Float32Array(count * 3);
    const colours = new Float32Array(count * 3);
    const sizes = new Float32Array(count);
    const leads = new Float32Array(count);
    const lit = new THREE.Color(focused ? '#7fd4ff' : '#4aa8e8');
    const empty = new THREE.Color('#33404f');
    /** Wrapped at five so a larger `PER_MODEL` cannot grow an unreadable strip. */
    const perRow = Math.min(PER_MODEL, 5);
    const rows = Math.ceil(PER_MODEL / perRow);
    let cursor = 0;

    markers.forEach((marker, markerIndex) => {
      const slot = slots[markerIndex] ?? [0, 0, 0];
      const authoredScale = hullVisualScale(marker.hull, scale);
      const pipSize = authoredScale * 0.085;
      const gap = pipSize * 1.6;
      const width = gap * (perRow - 1);
      for (let i = 0; i < PER_MODEL; i += 1) {
        positions.set(
          [
            slot[0] + (i % perRow) * gap - width / 2,
            // Top row first, so a partly-filled marker fills left-to-right and
            // downward — the direction a tally is read.
            slot[1] + authoredScale * 0.6 +
              ((rows - 1) / 2 - Math.floor(i / perRow)) * gap,
            slot[2],
          ],
          cursor * 3,
        );
        const colour = i < marker.filled ? lit : empty;
        colours.set([colour.r, colour.g, colour.b], cursor * 3);
        sizes[cursor] = pipSize;
        leads[cursor] = authoredScale * MARK_LEAD;
        cursor += 1;
      }
    });

    const buffer = new THREE.BufferGeometry();
    buffer.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    buffer.setAttribute('color', new THREE.BufferAttribute(colours, 3));
    buffer.setAttribute('aSize', new THREE.BufferAttribute(sizes, 1));
    buffer.setAttribute('aLead', new THREE.BufferAttribute(leads, 1));
    return buffer;
  }, [markers, slots, scale, focused]);

  const material = useMemo(
    () =>
      new THREE.ShaderMaterial({
        uniforms: {
          uProjectionScale: { value: 700 },
          uPixelRatio: { value: 1 },
        },
        vertexColors: true,
        transparent: true,
        depthWrite: false,
        vertexShader: `
          attribute float aSize;
          attribute float aLead;
          varying vec3 vColour;
          uniform float uProjectionScale;
          uniform float uPixelRatio;
          void main() {
            vColour = color;
            vec4 mv = modelViewMatrix * vec4(position, 1.0);
            float projected = aSize * uProjectionScale / max(0.01, -mv.z);
            gl_PointSize = clamp(projected, 1.0, 7.0 * uPixelRatio);
            gl_Position = projectionMatrix * mv;
            ${MARK_LEAD_DEPTH}
          }
        `,
        fragmentShader: `
          varying vec3 vColour;
          void main() {
            float edge = max(abs(gl_PointCoord.x - 0.5), abs(gl_PointCoord.y - 0.5)) * 2.0;
            float alpha = 1.0 - smoothstep(0.72, 1.0, edge);
            gl_FragColor = vec4(vColour, alpha);
          }
        `,
      }),
    [],
  );

  useFrame(({ camera, size: viewport, gl }) => {
    const perspective = camera as THREE.PerspectiveCamera;
    const fov = THREE.MathUtils.degToRad(perspective.fov || 45);
    material.uniforms.uProjectionScale!.value =
      (viewport.height * gl.getPixelRatio()) / (2 * Math.tan(fov / 2));
    material.uniforms.uPixelRatio!.value = gl.getPixelRatio();
  });

  useEffect(() => () => { geometry.dispose(); }, [geometry]);
  useEffect(() => () => { material.dispose(); }, [material]);

  return (
    <points
      geometry={geometry}
      material={material}
      frustumCulled={false}
      renderOrder={SHIP_ORDER + 2}
      name="formation-pips"
    />
  );
}

/* ── rank badges ────────────────────────────────────────────── */

/**
 * THE BADGE UNDER EVERY WARSHIP ON THE DISC. Owner instruction.
 *
 * The pips above a marker say how many ships it stands for. Nothing said what
 * they WERE — and the two facts that decide whether an approaching wing is a
 * problem are its tier and its role. D124: a rule the player cannot see is not a
 * usable rule, and D142: a quantity a player must judge is drawn, not written.
 *
 * `rank.ts` decides the row; this file only draws it. The stars are the tier and
 * the glyph on their left is the family — sword, shield or crate — so "four stars
 * and a sword" is read as fast as a shape and needs no legend.
 *
 * ONE TEXTURE AND ONE DRAW CALL FOR THE WHOLE GALAXY, the same construction the
 * pips already use: an atlas of four glyphs built once on a canvas, and one point
 * buffer per formation whose vertex shader expands each mark into a camera-facing
 * quad. A twenty-model formation is up to a hundred marks and still one call.
 *
 * IT FOLLOWS EXACT SIGHT, NEVER A SILHOUETTE. Mounted from the same `showPips`
 * flag, because a Radar contact's markers are a synthetic count of Darts — a tier
 * printed over an estimate would be the interface inventing a reading nobody
 * bought (D123). The probe and the drill wear no badge at all, which falls out of
 * `rankRow` rather than out of a second exclusion list.
 */

/** The atlas cells, in the order the shader indexes them. */
const RANK_CELLS: readonly RankGlyph[] = ['sword', 'shield', 'crate', STAR];

/** Gold for a rank; the role glyph stays bone so the stars are what counts. */
const RANK_COLOUR = { star: '#ffc93c', glyph: '#dbe7f2' } as const;

/**
 * One mark's size and where the row hangs, both as multiples of the drawn craft.
 *
 * Bigger than a pip (0.085) because a star has internal structure to read where a
 * pip is a square, and low enough under the hull that it never touches it —
 * measured from the craft's own lift so a posed hull keeps the same gap.
 */
const RANK_MARK = { size: 0.115, drop: 0.62 } as const;

let rankTexture: THREE.Texture | null = null;

/**
 * Four white glyphs in a row, drawn once.
 *
 * White so the shader can tint each mark; solid rather than stroked so every one
 * of them survives being drawn eight pixels across on a phone, which is the size
 * it is actually read at.
 */
function rankAtlas(): THREE.Texture {
  if (rankTexture) return rankTexture;
  const cell = 128;
  const canvas = document.createElement('canvas');
  canvas.width = cell * RANK_CELLS.length;
  canvas.height = cell;
  const ctx = canvas.getContext('2d');
  if (ctx) {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#ffffff';
    ctx.strokeStyle = '#ffffff';
    ctx.lineJoin = 'round';
    ctx.lineCap = 'round';
    RANK_CELLS.forEach((glyph, index) => {
      ctx.save();
      ctx.translate(index * cell, 0);
      const u = cell / 100;
      switch (glyph) {
        case 'sword':
          // Blade, crossguard, grip: a weapon pointing up.
          ctx.beginPath();
          ctx.moveTo(50 * u, 6 * u);
          ctx.lineTo(59 * u, 24 * u);
          ctx.lineTo(59 * u, 62 * u);
          ctx.lineTo(41 * u, 62 * u);
          ctx.lineTo(41 * u, 24 * u);
          ctx.closePath();
          ctx.fill();
          ctx.fillRect(22 * u, 62 * u, 56 * u, 11 * u);
          ctx.fillRect(43 * u, 73 * u, 14 * u, 17 * u);
          ctx.fillRect(34 * u, 88 * u, 32 * u, 9 * u);
          break;
        case 'shield':
          ctx.beginPath();
          ctx.moveTo(50 * u, 6 * u);
          ctx.lineTo(88 * u, 22 * u);
          ctx.lineTo(88 * u, 52 * u);
          ctx.quadraticCurveTo(88 * u, 82 * u, 50 * u, 96 * u);
          ctx.quadraticCurveTo(12 * u, 82 * u, 12 * u, 52 * u);
          ctx.lineTo(12 * u, 22 * u);
          ctx.closePath();
          ctx.fill();
          break;
        case 'crate':
          // A parcel: a box with its strapping, which reads as cargo at any size.
          ctx.fillRect(12 * u, 20 * u, 76 * u, 62 * u);
          ctx.globalCompositeOperation = 'destination-out';
          ctx.fillRect(44 * u, 20 * u, 12 * u, 62 * u);
          ctx.fillRect(12 * u, 45 * u, 76 * u, 12 * u);
          ctx.globalCompositeOperation = 'source-over';
          break;
        default: {
          // Five points, outer to inner, starting at the top.
          const outer = 46 * u;
          const inner = 19 * u;
          ctx.beginPath();
          for (let i = 0; i < 10; i += 1) {
            const radius = i % 2 === 0 ? outer : inner;
            const angle = -Math.PI / 2 + (i * Math.PI) / 5;
            const x = 50 * u + Math.cos(angle) * radius;
            const y = 52 * u + Math.sin(angle) * radius;
            if (i === 0) ctx.moveTo(x, y);
            else ctx.lineTo(x, y);
          }
          ctx.closePath();
          ctx.fill();
          break;
        }
      }
      ctx.restore();
    });
  }
  rankTexture = new THREE.CanvasTexture(canvas);
  rankTexture.colorSpace = THREE.SRGBColorSpace;
  rankTexture.needsUpdate = true;
  return rankTexture;
}

function FormationRanks({
  markers,
  slots,
  scale,
}: {
  markers: readonly Marker[];
  slots: readonly Vec3Tuple[];
  scale: number;
}) {
  const texture = useMemo(() => rankAtlas(), []);

  const geometry = useMemo(() => {
    const rows = markers.map((marker) => rankRow(marker.hull));
    const count = rows.reduce((total, row) => total + row.length, 0);
    const positions = new Float32Array(count * 3);
    const colours = new Float32Array(count * 3);
    const sizes = new Float32Array(count);
    const cells = new Float32Array(count);
    const leads = new Float32Array(count);
    const star = new THREE.Color(RANK_COLOUR.star);
    const glyph = new THREE.Color(RANK_COLOUR.glyph);
    let cursor = 0;

    markers.forEach((marker, markerIndex) => {
      const row = rows[markerIndex] ?? [];
      if (row.length === 0) return;
      const slot = slots[markerIndex] ?? [0, 0, 0];
      const authoredScale = hullVisualScale(marker.hull, scale);
      const size = authoredScale * RANK_MARK.size;
      // Under the hull as it is actually drawn, so a posed craft keeps the gap.
      const y = slot[1] + hullPoseLift(marker.hull) * authoredScale
        - authoredScale * RANK_MARK.drop;
      for (const mark of rankLayout(row, size)) {
        positions.set([slot[0] + mark.x, y, slot[2]], cursor * 3);
        const tint = mark.glyph === STAR ? star : glyph;
        colours.set([tint.r, tint.g, tint.b], cursor * 3);
        sizes[cursor] = size;
        cells[cursor] = RANK_CELLS.indexOf(mark.glyph);
        leads[cursor] = authoredScale * MARK_LEAD;
        cursor += 1;
      }
    });

    const buffer = new THREE.BufferGeometry();
    buffer.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    buffer.setAttribute('color', new THREE.BufferAttribute(colours, 3));
    buffer.setAttribute('aSize', new THREE.BufferAttribute(sizes, 1));
    buffer.setAttribute('aCell', new THREE.BufferAttribute(cells, 1));
    buffer.setAttribute('aLead', new THREE.BufferAttribute(leads, 1));
    return buffer;
  }, [markers, slots, scale]);

  const material = useMemo(
    () =>
      new THREE.ShaderMaterial({
        uniforms: {
          uProjectionScale: { value: 700 },
          uPixelRatio: { value: 1 },
          uMap: { value: texture },
          uCells: { value: RANK_CELLS.length },
        },
        vertexColors: true,
        transparent: true,
        depthWrite: false,
        toneMapped: false,
        vertexShader: `
          attribute float aSize;
          attribute float aCell;
          attribute float aLead;
          varying vec3 vColour;
          varying float vCell;
          uniform float uProjectionScale;
          uniform float uPixelRatio;
          void main() {
            vColour = color;
            vCell = aCell;
            vec4 mv = modelViewMatrix * vec4(position, 1.0);
            float projected = aSize * uProjectionScale / max(0.01, -mv.z);
            gl_PointSize = clamp(projected, 1.0, 11.0 * uPixelRatio);
            gl_Position = projectionMatrix * mv;
            ${MARK_LEAD_DEPTH}
          }
        `,
        fragmentShader: `
          uniform sampler2D uMap;
          uniform float uCells;
          varying vec3 vColour;
          varying float vCell;
          void main() {
            // The atlas is one row of cells; the point's own coordinate picks the
            // pixel inside the cell this mark was assigned. Y is flipped because
            // gl_PointCoord counts down from the top and a texture counts up.
            vec2 uv = vec2((vCell + gl_PointCoord.x) / uCells, 1.0 - gl_PointCoord.y);
            float mask = texture2D(uMap, uv).a;
            if (mask < 0.04) discard;
            gl_FragColor = vec4(vColour, mask);
          }
        `,
      }),
    [texture],
  );

  useFrame(({ camera, size: viewport, gl }) => {
    const perspective = camera as THREE.PerspectiveCamera;
    const fov = THREE.MathUtils.degToRad(perspective.fov || 45);
    material.uniforms.uProjectionScale!.value =
      (viewport.height * gl.getPixelRatio()) / (2 * Math.tan(fov / 2));
    material.uniforms.uPixelRatio!.value = gl.getPixelRatio();
  });

  useEffect(() => () => { geometry.dispose(); }, [geometry]);
  useEffect(() => () => { material.dispose(); }, [material]);

  if (geometry.getAttribute('position').count === 0) return null;

  return (
    <points
      geometry={geometry}
      material={material}
      frustumCulled={false}
      renderOrder={SHIP_ORDER + 3}
      name="formation-ranks"
    />
  );
}

/**
 * THE STREAK A CRAFT DRAWS BEHIND IT.
 *
 * The same object as `Tails` in `Asteroids.tsx`, and deliberately so — the owner
 * asked for the rock's streak, thinner and shorter. Read that file for why it is a
 * tapering ribbon rather than a line or a row of billboards: a one-pixel line has
 * no edge to soften and can only ever be a vector diagram, and soft billboards bead
 * up into a string of blobs.
 *
 * WHAT IS SIMPLER HERE THAN ON A ROCK. A rock's ribbon follows a curved orbit, so
 * every segment has to be re-solved against the path and given its own facing. A
 * craft flies straight, so the whole strip lies along its own local −Z and the
 * "across" direction is ONE cross product per craft per frame. That is what makes
 * it affordable on a dozen models at once where the rocks pay for a whole field.
 *
 * ONE PER DRAWN MODEL, not one per squadron. Six Wasps are two models and get two
 * streaks, which is the owner's rule: what is drawn is what trails.
 */

/** Quads down the strip. Fewer than a rock's eleven — it is half the length. */
const WAKE_SEGMENTS = 9;

/**
 * Half-width at the craft, as a multiple of its drawn size.
 *
 * The rock's is 0.31 of its radius; the owner asked for 75% thinner, so a quarter
 * of that. At map distance this is a hairline and at close focus it is a wisp,
 * which is the intent — a craft should read as the object and the streak as
 * something it has shed.
 */
const WAKE_WIDTH = 0.11;

/**
 * How far back it reaches, as a multiple of the craft's own size.
 *
 * A rock's streak spans a twenty-fourth of its orbit. A drive wake is much more
 * compact: enough to establish heading at map distance, short enough that a close
 * formation does not tow laser lines out of the frame.
 */
const WAKE_LENGTH = 6.4;

/**
 * Brightness at the craft. Additive on a near-black sky, so this is a whisper.
 *
 * CUT FROM 0.42 AFTER LOOKING AT IT. The scene runs a bloom pass with a luminance
 * threshold of 0.62, and an additive strip at 0.42 crosses it — so the mipmap blur
 * spread a hairline ribbon into a fat glowing beam wider than the ship towing it.
 * The number that matters is not the ribbon's width, it is whether the ribbon
 * blooms; under the threshold it reads as the thin streak it actually is.
 */
const WAKE_PEAK = 0.11;

/** Soft-edged energy shed behind a drive, shared by solo and formation ribbons. */
function makeWakeMaterial(map: THREE.Texture): THREE.ShaderMaterial {
  return new THREE.ShaderMaterial({
    uniforms: {
      uTime: { value: 0 },
      uMap: { value: map },
      uMotion: { value: 1 },
    },
    vertexColors: true,
    transparent: true,
    depthWrite: false,
    side: THREE.DoubleSide,
    forceSinglePass: true,
    blending: THREE.AdditiveBlending,
    vertexShader: `
      varying vec2 vUv;
      varying vec3 vColour;
      void main() {
        vUv = uv;
        vColour = color;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: `
      uniform sampler2D uMap;
      uniform float uTime;
      uniform float uMotion;
      varying vec2 vUv;
      varying vec3 vColour;
      void main() {
        float across = abs(vUv.x * 2.0 - 1.0);
        float softEdge = 1.0 - smoothstep(0.18, 1.0, across);
        float tail = pow(max(0.0, 1.0 - vUv.y), 2.35);
        float breakup = 0.94 + uMotion * 0.06 * sin(uTime * 7.3 - vUv.y * 24.0);
        float fibers = texture2D(uMap, vec2(vUv.x, fract(vUv.y * 0.8 - uTime * 0.18))).r;
        float alpha = softEdge * tail * breakup * (0.18 + fibers * 0.25);
        gl_FragColor = vec4(vColour * (0.55 + tail * 0.85), alpha);
      }
    `,
  });
}

export function Wake({
  scale,
  colour,
  lengthScale = 1,
}: {
  scale: number;
  colour: string;
  lengthScale?: number;
}) {
  const mesh = useRef<THREE.Mesh>(null);
  const wakeMap = useTexture(TRAIL_MAP);
  const material = useMemo(() => makeWakeMaterial(wakeMap), [wakeMap]);

  /** Colours and indices never change; only the vertices move. Built once. */
  const geometry = useMemo(() => {
    const g = new THREE.BufferGeometry();
    const verts = WAKE_SEGMENTS * 2;
    g.setAttribute('position', new THREE.BufferAttribute(new Float32Array(verts * 3), 3));

    const tint = new THREE.Color(colour);
    const colours = new Float32Array(verts * 3);
    const uvs = new Float32Array(verts * 2);
    const index: number[] = [];
    for (let k = 0; k < WAKE_SEGMENTS; k += 1) {
      // Squared falloff, as on the rocks: a linear fade leaves a hard end,
      // because the last quad is still a quarter lit when it stops existing.
      const back = k / (WAKE_SEGMENTS - 1);
      const v = k * 2;
      colours.set([tint.r * WAKE_PEAK, tint.g * WAKE_PEAK, tint.b * WAKE_PEAK], v * 3);
      colours.set([tint.r * WAKE_PEAK, tint.g * WAKE_PEAK, tint.b * WAKE_PEAK], (v + 1) * 3);
      uvs.set([0, back, 1, back], v * 2);
      if (k < WAKE_SEGMENTS - 1) index.push(v, v + 1, v + 2, v + 1, v + 3, v + 2);
    }
    g.setAttribute('color', new THREE.BufferAttribute(colours, 3));
    g.setAttribute('uv', new THREE.BufferAttribute(uvs, 2));
    g.setIndex(index);
    return g;
  }, [colour]);

  // Freed with the craft. One strip is small; a season's worth of squadrons that
  // each left one behind is not. See `useLine` for the same reasoning at length.
  useEffect(() => () => { geometry.dispose(); }, [geometry]);
  useEffect(() => () => { material.dispose(); }, [material]);

  const eye = useMemo(() => new THREE.Vector3(), []);
  const side = useMemo(() => new THREE.Vector3(), []);

  useFrame(({ camera, clock }) => {
    const node = mesh.current;
    if (!node) return;

    /**
     * Which way is "across" the ribbon, solved in the craft's OWN space.
     *
     * The craft is already turned so its nose runs down local +Z, so the tangent
     * is a constant and only the camera has to be brought into local space. Doing
     * it per frame rather than once is what keeps the strip from vanishing to a
     * line when the player flies into its plane — and this disc can be viewed from
     * underneath.
     */
    node.updateWorldMatrix(true, false);
    eye.copy(camera.position);
    node.worldToLocal(eye);
    side.set(0, 0, 1).cross(eye);
    if (side.lengthSq() < 1e-12) side.set(1, 0, 0);
    else side.normalize();

    const position = node.geometry.getAttribute('position') as THREE.BufferAttribute;
    for (let k = 0; k < WAKE_SEGMENTS; k += 1) {
      const back = k / (WAKE_SEGMENTS - 1);
      // Tapers to a point. The hull covers the widest end, so the streak reads as
      // shed from the craft rather than bolted to it.
      const envelope = (0.42 + Math.sin(Math.PI * back) * 0.72) * (1 - back);
      const w = scale * WAKE_WIDTH * envelope;
      const flutter = Math.sin(clock.elapsedTime * 2.7 + back * 14) * w * back * 0.22;
      const z = -scale * WAKE_LENGTH * lengthScale * back;
      const v = k * 2;
      position.setXYZ(v, side.x * (w + flutter), side.y * (w + flutter), z + side.z * w);
      position.setXYZ(v + 1, side.x * (-w + flutter), side.y * (-w + flutter), z - side.z * w);
    }
    position.needsUpdate = true;
    material.uniforms.uTime!.value = clock.elapsedTime;
    material.uniforms.uMotion!.value = 1;
  });

  return (
    <mesh
      ref={mesh}
      geometry={geometry}
      material={material}
      frustumCulled={false}
      renderOrder={SHIP_ORDER - 2}
    />
  );
}

/** Parallel formation wakes share one camera-facing strip buffer and one draw. */
export function FormationWakes({
  markers,
  slots,
  scale,
  aimDistance,
  name,
  longitudinalOffset,
}: {
  markers: readonly Marker[];
  slots: readonly Vec3Tuple[];
  scale: number;
  aimDistance: RefObject<number>;
  name?: string;
  longitudinalOffset?: (markerIndex: number, elapsedSeconds: number) => number;
}) {
  const mesh = useRef<THREE.Mesh>(null);
  const wakeMap = useTexture(TRAIL_MAP);
  const material = useMemo(() => makeWakeMaterial(wakeMap), [wakeMap]);
  const geometry = useMemo(() => {
    const verticesPerWake = WAKE_SEGMENTS * 2;
    const positions = new Float32Array(markers.length * verticesPerWake * 3);
    const colours = new Float32Array(markers.length * verticesPerWake * 3);
    const uvs = new Float32Array(markers.length * verticesPerWake * 2);
    const index: number[] = [];
    markers.forEach((marker, markerIndex) => {
      const tint = new THREE.Color(HULL_LIGHT[marker.hull].glow);
      const vertexBase = markerIndex * verticesPerWake;
      for (let k = 0; k < WAKE_SEGMENTS; k += 1) {
        const back = k / (WAKE_SEGMENTS - 1);
        const vertex = vertexBase + k * 2;
        colours.set([tint.r * WAKE_PEAK, tint.g * WAKE_PEAK, tint.b * WAKE_PEAK], vertex * 3);
        colours.set([tint.r * WAKE_PEAK, tint.g * WAKE_PEAK, tint.b * WAKE_PEAK], (vertex + 1) * 3);
        uvs.set([0, back, 1, back], vertex * 2);
        if (k < WAKE_SEGMENTS - 1) {
          index.push(vertex, vertex + 1, vertex + 2, vertex + 1, vertex + 3, vertex + 2);
        }
      }
    });

    const buffer = new THREE.BufferGeometry();
    buffer.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    buffer.setAttribute('color', new THREE.BufferAttribute(colours, 3));
    buffer.setAttribute('uv', new THREE.BufferAttribute(uvs, 2));
    buffer.setIndex(index);
    return buffer;
  }, [markers]);
  const eye = useMemo(() => new THREE.Vector3(), []);
  const side = useMemo(() => new THREE.Vector3(), []);
  const direction = useMemo(() => new THREE.Vector3(), []);
  const eyeFromCraft = useMemo(() => new THREE.Vector3(), []);
  const aimed = useMemo<Vec3Tuple>(() => [0, 0, 1], []);
  const animatedSlot = useMemo<Vec3Tuple>(() => [0, 0, 0], []);

  const culling = useGalaxyCulling();
  const visibility = useMemo(createLocalVisibility, []);
  const radius = useMemo(() => {
    // Arbitrary caller animation has no declared bound: keep drawing it.
    if (longitudinalOffset) return Infinity;
    // Envelope <= 1.14; flutter extends either edge by at most another 22%.
    return markers.reduce((bound, marker, index) => Math.max(bound,
      Math.hypot(...(slots[index] ?? [0, 0, 0])) + Math.abs(hullVisualScale(marker.hull, scale))
        * (Math.abs(hullPoseLift(marker.hull)) + WAKE_LENGTH + WAKE_WIDTH * 1.14 * 1.22)), 0);
  }, [markers, slots, scale, longitudinalOffset]);
  useVisualFrame(({ camera, clock }) => {
    const node = mesh.current;
    if (!node) return;
    node.visible = !culling || localSphereVisible(visibility, camera, node, radius);
    if (!node.visible) return;
    if (!culling) node.updateWorldMatrix(true, false);
    eye.copy(camera.position);
    node.worldToLocal(eye);
    side.set(0, 0, 1).cross(eye);
    if (side.lengthSq() < 1e-12) side.set(1, 0, 0);
    else side.normalize();

    const positions = node.geometry.getAttribute('position') as THREE.BufferAttribute;
    markers.forEach((marker, markerIndex) => {
      const slot = slots[markerIndex] ?? [0, 0, 0];
      animatedSlot[0] = slot[0];
      animatedSlot[1] = slot[1];
      animatedSlot[2] = slot[2] + (longitudinalOffset?.(markerIndex, clock.elapsedTime) ?? 0);
      const authoredScale = hullVisualScale(marker.hull, scale);
      // The streak is shed by the hull, so it starts at the hull's own height.
      const lift = hullPoseLift(marker.hull) * authoredScale;
      formationAimDirection(animatedSlot, aimDistance.current, aimed);
      direction.set(...aimed);
      eyeFromCraft.set(
        eye.x - animatedSlot[0],
        eye.y - animatedSlot[1] - lift,
        eye.z - animatedSlot[2],
      );
      side.copy(direction).cross(eyeFromCraft);
      if (side.lengthSq() < 1e-12) side.set(1, 0, 0);
      else side.normalize();
      const vertexBase = markerIndex * WAKE_SEGMENTS * 2;
      for (let k = 0; k < WAKE_SEGMENTS; k += 1) {
        const back = k / (WAKE_SEGMENTS - 1);
        const envelope = (0.42 + Math.sin(Math.PI * back) * 0.72) * (1 - back);
        const width = authoredScale * WAKE_WIDTH * envelope;
        const flutter = Math.sin(clock.elapsedTime * 2.7 + back * 14 + markerIndex * 1.7) *
          width *
          back *
          0.22;
        const distance = authoredScale * WAKE_LENGTH * back;
        const centreX = animatedSlot[0] - direction.x * distance;
        const centreY = animatedSlot[1] + lift - direction.y * distance;
        const centreZ = animatedSlot[2] - direction.z * distance;
        const vertex = vertexBase + k * 2;
        positions.setXYZ(
          vertex,
          centreX + side.x * (width + flutter),
          centreY + side.y * (width + flutter),
          centreZ + side.z * (width + flutter),
        );
        positions.setXYZ(
          vertex + 1,
          centreX + side.x * (-width + flutter),
          centreY + side.y * (-width + flutter),
          centreZ + side.z * (-width + flutter),
        );
      }
    });
    positions.needsUpdate = true;
    material.uniforms.uTime!.value = clock.elapsedTime;
    material.uniforms.uMotion!.value = 1;
  });

  useEffect(() => () => { geometry.dispose(); }, [geometry]);
  useEffect(() => () => { material.dispose(); }, [material]);

  return (
    <mesh
      ref={mesh}
      name={name}
      geometry={geometry}
      material={material}
      frustumCulled={false}
      renderOrder={SHIP_ORDER - 2}
    />
  );
}

/**
 * OTHER PEOPLE'S CRAFT. D24.
 *
 * These used to be motes: featureless points, offset past attribution, drawn only
 * through the middle of a flight. That protected the fog completely and left a
 * galaxy of two hundred real people looking deserted.
 *
 * They are real craft now, at real positions, for the whole flight, wearing the
 * same neon everyone's own craft wear — green for a scout, blue for a warship,
 * amber for a Prospector — and trailing the same streak. What they do NOT wear is
 * a route: the server sends a bearing window rather than endpoints, so there is
 * nothing here to draw a line from even if this file wanted to. The one exception
 * is a mining run to a rock this commander has discovered; its leg and clock make
 * that earned race readable.
 *
 * Radar contacts are silhouettes, not rosters. Once Telescope sight identifies a
 * fleet, it uses the real hull assets and the same exact-count pips as an owned
 * squadron.
 * A public engagement outside every sensor circle is not a contact at all:
 * `Traffic` routes it to `ConcealedEngagement`, which mounts only the volley.
 */
/** What a hostile leg aimed at one of your worlds is painted in. D126. */
const THREAT_NEON = '#ff5b6e';
const THREAT_FLAME = '#ffb0ba';

const CONTACT_STYLE: Record<Contact['kind'], { neon: string; scale: number; flame: string }> = {
  /**
   * A CONTACT YOU CANNOT IDENTIFY. D125.
   *
   * Deliberately colourless. Every other neon on this list is an ANSWER — blue is
   * a warship, green a scout, amber a drill — so an unidentified contact may not
   * borrow any of them, or the disc would be naming the thing it is meant to be
   * withholding. Cold steel says "a return, and nothing more", which is exactly
   * what a sensor at the edge of its range gives you.
   */
  unknown: { neon: '#c7ecff', scale: 0.19 * CRAFT_SCALE, flame: '#c7ecff' },
  fleet: { neon: '#3fa9ff', scale: 0.195 * CRAFT_SCALE, flame: '#8fd8ff' },
  probe: { neon: '#3ff08a', scale: 0.15 * CRAFT_SCALE, flame: '#9dffc4' },
  mining: { neon: '#ffb057', scale: 0.18 * CRAFT_SCALE, flame: '#ffd9a8' },
  // A harvest is the same craft on a different errand, so it keeps the miner's
  // amber and goes a shade paler — recognisably the same kind of thing, visibly
  // not headed for a rock. D32.
  harvest: { neon: '#ffcf8f', scale: 0.18 * CRAFT_SCALE, flame: '#ffe9cc' },
  death_star: { neon: '#ff4d67', scale: STRATEGIC_CONTACT_SCALE, flame: '#ff9cac' },
  radiation_bomb: { neon: '#c4d888', scale: STRATEGIC_CONTACT_SCALE, flame: '#c0dd8e' },
  /**
   * A PIRATE. D150.
   *
   * Violet, and it had to be a hue nothing else on this list owns: `visual-design`
   * says the hue carries the CATEGORY, and a pirate is a category — not a player's
   * warship (blue), not a scout (green), not a drill (amber), and emphatically not
   * the strategic weapon (red). Somebody looking at the disc has to be able to tell
   * "a target I can take" from "a commander who can take me" without reading a
   * word, because that difference is the whole reason this class exists.
   */
  pirate: { neon: '#c46bff', scale: 0.205 * CRAFT_SCALE, flame: '#e7c2ff' },
};

/**
 * HOW MANY UNMARKED HULLS A RADAR SILHOUETTE IS DRAWN WITH. D123.
 *
 * A Radar contact has no actual roster, so its mass bucket must not be rendered as
 * if it did. Telescope contacts bypass this table and draw their actual manifest.
 *
 * So the formation now says SIZE and nothing else. Three counts rather than a
 * continuous ramp, matching the three the server buckets into — the eye separates
 * "a few", "a lot" and "an awful lot", and nothing finer than that would survive
 * being looked at on a phone anyway.
 *
 * PIPS ARE OFF FOR RADAR SILHOUETTES, which matters more than it looks: a pip is a count of
 * real ships, and printing one over a marker that stands for an estimate would be
 * the interface inventing a precision the payload does not have. The panel names
 * the reading as an estimate for the same reason. The fog HIDES; it never lies.
 *
 * It is also the answer to the performance case D115 left open — twenty
 * simultaneous hundred-ship raids were roughly four hundred markers, and are now
 * at most three hundred and twenty in the worst case and typically far fewer.
 */
const SILHOUETTE: Record<'LIGHT' | 'MEDIUM' | 'HEAVY', number> = {
  LIGHT: 3,
  MEDIUM: 8,
  HEAVY: 16,
};

/** A probe is one craft; a run draws its public count; sight draws an exact fleet. */
const contactMarkers = (contact: Contact): Marker[] | null => {
  // An unidentified contact has no hull to draw, which is the whole point of it.
  if (contact.kind === 'unknown') return null;
  if (contact.kind === 'probe' || contact.kind === 'death_star' || contact.kind === 'radiation_bomb') return null;
  // A harvest is Prospectors too, and its count is in `craft` like a mining run's.
  // Telescope has identified these Prospectors, so these are real counts rather
  // than the mass estimate a Radar contact may carry.
  if (contact.kind === 'mining' || contact.kind === 'harvest') {
    return markersFor({ PROSPECTOR: contact.craft ?? 1 });
  }
  // Telescope sight carries the real manifest, so use the same hull assets and
  // marker arithmetic as the owner's own squadron — a pirate included, because an
  // identified pirate IS its hulls and drawing it as an anonymous blob would throw
  // away the one reading the Telescope was bought for. The fallback is only for a
  // client briefly talking to an older server during a rolling deploy.
  if (contact.fleet) return markersFor(contact.fleet);
  return markersFor({ DART: SILHOUETTE[contact.mass ?? 'LIGHT'] * PER_MODEL });
};

/**
 * A BLIND PUBLIC VOLLEY HAS A DRAWN SOURCE, NOT AN INTEL SOURCE. D52/D123.
 *
 * Rockets need somewhere to come from, but using the real orbit hold would hand
 * an out-of-range observer the squadron's final approach direction. This stable
 * unit vector is derived only from the opaque mission id. It is intentionally
 * unrelated to the real leg and therefore cannot be reverse-engineered into one.
 */
export function concealedEngagementDirection(id: string): Vec3Tuple {
  const random = seededFrom('concealed-engagement', id);
  const y = random() * 1.2 - 0.6;
  const angle = random() * Math.PI * 2;
  const horizontal = Math.sqrt(Math.max(0, 1 - y * y));
  return [Math.cos(angle) * horizontal, y, Math.sin(angle) * horizontal];
}

/** Fixed visual battery: it never scales with the hidden fleet's real mass. */
const CONCEALED_VOLLEY_SLOTS: Vec3Tuple[] = [
  [0, 0, 0],
  [-0.13, 0.035, -0.08],
  [0.13, -0.035, -0.08],
];

/**
 * The public half of a raid when no sensor can see the craft itself.
 *
 * No tracking mark, hull, wake, hit box or selectable contact is mounted here.
 * Only the deterministic rounds and their surface impacts exist. The synthetic
 * source keeps the cinematic readable without laundering a hidden bearing through
 * the renderer.
 *
 * AND IT NO LONGER NEEDS A WORLD TO FIRE AT. Both figures it places the volley
 * with used to come off the target's planet node, so a pirate battle — which
 * happens at a rendezvous in open space and never has one — mounted nothing at
 * all, and the one public moment of that fight was invisible to everybody who
 * could not see the craft. `concealedVolley` states both, with or without a world.
 */
function ConcealedEngagement({
  contact,
  nodes,
}: {
  contact: Contact;
  nodes: readonly PlanetNode[];
}) {
  const fight = contact.engagement;
  const engaging = useEngagement(
    fight ? fight.arriveAt.getTime() : null,
    fight?.endsAt.getTime(),
  );
  const shot = useMemo(
    () => (fight
      ? concealedVolley(fight.target, nodes, CONTACT_STYLE.fleet.scale)
      : null),
    [fight, nodes],
  );
  const world = useMemo(
    () => (fight ? targetNodeOf(nodes, fight.target) : undefined),
    [fight, nodes],
  );
  const centre = useMemo(
    () => (fight ? engagementTargetPosition(fight, serverNow()) : null),
    [fight],
  );
  const direction = useMemo(() => concealedEngagementDirection(contact.id), [contact.id]);
  const source = useMemo<Vec3Tuple | null>(() => {
    if (!shot || !centre) return null;
    return [
      centre[0] + direction[0] * shot.standoff,
      centre[1] + direction[1] * shot.standoff,
      centre[2] + direction[2] * shot.standoff,
    ];
  }, [centre, direction, shot]);
  const orientation = useMemo(() => {
    if (!source || !centre) return null;
    const frame = new THREE.Object3D();
    frame.position.set(source[0], source[1], source[2]);
    frame.lookAt(centre[0], centre[1], centre[2]);
    return frame.quaternion.clone();
  }, [centre, source]);
  const group = useRef<THREE.Group>(null);
  useFrame(() => {
    const node = group.current;
    if (!node || !fight || !shot) return;
    const target = engagementTargetPosition(fight, serverNow());
    node.position.set(
      target[0] + direction[0] * shot.standoff,
      target[1] + direction[1] * shot.standoff,
      target[2] + direction[2] * shot.standoff,
    );
    node.lookAt(...target);
  });

  if (!fight || !shot || !centre || !source || !orientation || !engaging) return null;

  return (
    <group
      ref={group}
      name="concealed-engagement"
      position={source}
      quaternion={orientation}
      userData={{ engagementId: contact.id }}
    >
      <Bombardment
        volleyKey={contact.id}
        slots={CONCEALED_VOLLEY_SLOTS}
        distance={Math.hypot(
          centre[0] - source[0],
          centre[1] - source[1],
          centre[2] - source[2],
        )}
        radius={shot.radius}
        shipScale={CONTACT_STYLE.fleet.scale}
        arriveAt={fight.arriveAt.getTime()}
        intensity={bombardmentIntensity(true)}
        engagementSeconds={(fight.endsAt.getTime() - fight.arriveAt.getTime()) / 1000}
        strikesWorld={world !== undefined}
      />
    </group>
  );
}

/** The renderer's hard boundary between a sensed craft and a public effect. */
export const contactPresentation = (contact: Contact): 'effect' | 'craft' =>
  contact.effectOnly === true ? 'effect' : 'craft';

export function Traffic({
  contacts,
  nodes,
  focusedId,
  onSelect,
}: {
  contacts: readonly Contact[];
  /** The worlds are needed when a landed engagement holds in target orbit. */
  nodes: readonly PlanetNode[];
  focusedId: string | null;
  onSelect: (id: string) => void;
}) {
  if (contacts.length === 0) return null;

  return (
    <HullBatchLayer>
      {contacts.map((contact) => (
        contactPresentation(contact) === 'effect' ? (
          <ConcealedEngagement key={contact.id} contact={contact} nodes={nodes} />
        ) : (
          <Foreign
            key={contact.id}
            contact={contact}
            nodes={nodes}
            focused={contact.id === focusedId}
            onSelect={() => {
              onSelect(contact.id);
            }}
          />
        )
      ))}
    </HullBatchLayer>
  );
}

/**
 * HOW FAST A CRAFT SETTLES ONTO A NEW HEADING, as a time constant in seconds.
 *
 * A published bearing window is a straight chord, and a craft on a curve gets a
 * NEW chord every refetch — so its exact heading steps a few degrees each time one
 * lands. Aimed straight at it the ship snapped between headings five seconds
 * apart, which reads as a stutter rather than as a turn.
 *
 * Eased, the same steps become the continuous arc the craft is actually flying.
 * This is presentation only: it turns the ship, never moves it. Position stays
 * exactly where the authoritative clock puts it (D51), so nothing about arrival,
 * interception or the fog is touched by how quickly a nose comes round.
 *
 * Short enough that a genuine course change is followed within a frame or two of
 * being visible, long enough that one window boundary is not a snap.
 */
const HEADING_EASE_SECONDS = 0.35;

/** How long a craft takes to slide back onto its orbit after a fight. D150. */
const RELEASE_EASE_MS = 900;

/** Scratch used to derive a target orientation without allocating each frame. */
const AIM_SCRATCH = new THREE.Object3D();

/**
 * Turn `node` toward `aim`, easing rather than snapping.
 *
 * Frame-rate independent: the exponential makes the fraction covered depend on
 * elapsed time rather than on how many frames happened to be drawn. `settled`
 * carries the one-frame exception — a craft that has just appeared points the
 * right way immediately instead of swinging round from wherever it was created.
 *
 * AND IT REFUSES AN AIM POINT IT IS ALREADY STANDING ON. `isHeading` states why:
 * three.js resolves a zero-length `lookAt` as world +Z rather than as an error, so
 * this used to answer "look at yourself" by turning the craft — and everything
 * mounted inside it, the bombardment included — to a compass bearing. The refusal
 * lives HERE, in the one function that turns anything, rather than in each caller's
 * own guard: a caller that forgets is a formation silently facing the wrong way,
 * and that is precisely the bug this is written for.
 */
function easeHeading(
  node: THREE.Object3D,
  aim: Vec3Tuple,
  delta: number,
  settled: { current: boolean },
): void {
  const at: Vec3Tuple = [node.position.x, node.position.y, node.position.z];
  // Keep the heading it has. A craft that has stopped was going somewhere.
  if (!isHeading(at, aim)) return;
  AIM_SCRATCH.position.copy(node.position);
  AIM_SCRATCH.up.copy(node.up);
  AIM_SCRATCH.lookAt(aim[0], aim[1], aim[2]);
  if (!settled.current) {
    node.quaternion.copy(AIM_SCRATCH.quaternion);
    settled.current = true;
    return;
  }
  node.quaternion.slerp(AIM_SCRATCH.quaternion, 1 - Math.exp(-delta / HEADING_EASE_SECONDS));
}

/**
 * The question mark every unidentified contact wears. D125.
 *
 * ONE TEXTURE FOR THE WHOLE GALAXY, built once and shared by every sprite. A DOM
 * overlay per contact would have been fewer lines and would put a hundred elements
 * on the page in a busy season; a canvas glyph is the same picture for the cost of
 * one upload.
 */
let questionTexture: THREE.Texture | null = null;
function questionMark(): THREE.Texture {
  if (questionTexture) return questionTexture;
  const size = 256;
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d');
  if (ctx) {
    ctx.clearRect(0, 0, size, size);
    ctx.fillStyle = '#ffffff';
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = size * 0.025;
    ctx.shadowColor = '#ffffff';
    ctx.shadowBlur = size * 0.09;
    ctx.font = `800 ${String(size * 0.7)}px system-ui, sans-serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.strokeText('?', size / 2, size * 0.54);
    ctx.fillText('?', size / 2, size * 0.54);
  }
  questionTexture = new THREE.CanvasTexture(canvas);
  questionTexture.colorSpace = THREE.SRGBColorSpace;
  questionTexture.needsUpdate = true;
  return questionTexture;
}

/**
 * The question mark every unidentified contact wears. D125.
 *
 * ONE TEXTURE FOR THE WHOLE GALAXY, built once and shared. A DOM overlay per
 * contact would have been fewer lines and would put a hundred elements on the page
 * in a busy season; a canvas glyph is the same picture for one upload.
 *
 * A BILLBOARDED PLANE, NOT A SPRITE, AND THE FIRST DRAFT LEARNED WHY. `<sprite>`
 * was the obvious primitive and it rendered as large black screen-aligned
 * rectangles that flickered in and out — which is also why `docs/visual-design.md`
 * says camera-facing markers are not used here and why `TrackingMark`, the one
 * component doing exactly this job, is built from `Billboard` and meshes. Using
 * the primitive the scene already trusts is both the fix and the house style.
 */
function UnknownMark({
  scale,
  colour,
  focused,
}: {
  scale: number;
  colour: string;
  focused: boolean;
}) {
  const texture = useMemo(() => questionMark(), []);
  const size = scale * UNKNOWN_CONTACT_MARK.glyphScale;

  return (
    <Billboard follow lockX={false} lockY={false} lockZ={false}>
      <mesh renderOrder={SHIP_ORDER + 4}>
        <planeGeometry args={[size, size]} />
        <meshBasicMaterial
          map={texture}
          color={colour}
          transparent
          opacity={focused
            ? UNKNOWN_CONTACT_MARK.focusedGlyphOpacity
            : UNKNOWN_CONTACT_MARK.glyphOpacity}
          depthWrite={false}
          toneMapped={false}
          blending={THREE.AdditiveBlending}
        />
      </mesh>
    </Billboard>
  );
}

/**
 * THE SKULL A PIRATE WEARS. D150.
 *
 * A pirate flies the same Fleet V2 hulls a commander does — that is the whole
 * reason capturing one is worth anything — so the silhouette alone cannot say
 * what it is. Drive colour carries hull identity (`visual-design.md`), and the
 * neon already separates the contact kinds, but neither answers the question a
 * player actually has at a glance: is that somebody, or is that a target.
 *
 * IT IS DRAWN, NOT WRITTEN. D142/D124 — the thing a player must judge is a
 * picture, and a mark above the formation is legible at mobile map scale where a
 * label is not. Same construction as the unidentified contact's question mark:
 * one canvas texture for the whole galaxy, on a billboarded plane rather than a
 * `<sprite>`, because that is the primitive this scene trusts.
 *
 * ONLY ON AN IDENTIFIED PIRATE. A Radar return keeps its question mark: the skull
 * is an answer, and the radar has not bought one.
 */
let skullTexture: THREE.Texture | null = null;
function skullMark(): THREE.Texture {
  if (skullTexture) return skullTexture;
  const size = 256;
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d');
  if (ctx) {
    const u = size / 100;
    ctx.clearRect(0, 0, size, size);
    ctx.fillStyle = '#ffffff';
    ctx.strokeStyle = '#ffffff';
    ctx.shadowColor = '#ffffff';
    ctx.shadowBlur = size * 0.06;

    // Cranium and jaw, drawn as solids so the glyph survives being scaled down.
    ctx.beginPath();
    ctx.ellipse(50 * u, 42 * u, 27 * u, 25 * u, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.moveTo(34 * u, 60 * u);
    ctx.lineTo(66 * u, 60 * u);
    ctx.lineTo(60 * u, 76 * u);
    ctx.quadraticCurveTo(50 * u, 82 * u, 40 * u, 76 * u);
    ctx.closePath();
    ctx.fill();

    // Eyes and nose are punched out, so the skull reads at any size.
    ctx.globalCompositeOperation = 'destination-out';
    ctx.shadowBlur = 0;
    ctx.beginPath();
    ctx.ellipse(40 * u, 40 * u, 8.5 * u, 10 * u, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.ellipse(60 * u, 40 * u, 8.5 * u, 10 * u, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.moveTo(50 * u, 48 * u);
    ctx.lineTo(55 * u, 58 * u);
    ctx.lineTo(45 * u, 58 * u);
    ctx.closePath();
    ctx.fill();
    // Teeth.
    for (const x of [42, 50, 58]) ctx.fillRect((x - 2.4) * u, 62 * u, 4.8 * u, 9 * u);
    ctx.globalCompositeOperation = 'source-over';
  }
  skullTexture = new THREE.CanvasTexture(canvas);
  skullTexture.colorSpace = THREE.SRGBColorSpace;
  skullTexture.needsUpdate = true;
  return skullTexture;
}

/**
 * Sits above the formation so it never covers the hulls it is labelling.
 *
 * RED, AND NOT THE CONTACT'S OWN NEON. Hue carries category
 * (`docs/visual-design.md`), and the one thing this mark exists to say is "that is
 * a target, not a commander". Taking the kind's neon would have made the skull
 * change colour with the contact and say nothing the outline did not already.
 *
 * SMALL. It is a label on a formation, not a second object in the scene: at full
 * size it competed with the hulls underneath it, which is the opposite of the job.
 */
const PIRATE_MARK = {
  glyphScale: 0.75,
  lift: 1.5,
  opacity: 0.9,
  focusedOpacity: 1,
  colour: THREAT_NEON,
} as const;

function PirateMark({ scale, focused }: {
  scale: number;
  focused: boolean;
}) {
  const texture = useMemo(() => skullMark(), []);
  const size = scale * PIRATE_MARK.glyphScale;

  return (
    <Billboard follow lockX={false} lockY={false} lockZ={false} position={[0, scale * PIRATE_MARK.lift, 0]}>
      <mesh renderOrder={SHIP_ORDER + 4}>
        <planeGeometry args={[size, size]} />
        <meshBasicMaterial
          map={texture}
          color={PIRATE_MARK.colour}
          transparent
          opacity={focused ? PIRATE_MARK.focusedOpacity : PIRATE_MARK.opacity}
          depthWrite={false}
          toneMapped={false}
          blending={THREE.AdditiveBlending}
        />
      </mesh>
    </Billboard>
  );
}

/** A slim pick volume follows each pirate hull along the formation's heading. */
export function formationMarkerHitSize(hull: HullId, baseScale: number): Vec3Tuple {
  const size = hullVisualScale(hull, baseScale);
  return [size * 0.82, size * 0.68, size * 1.3];
}

/**
 * A pirate formation contains large empty wedges between its visible hulls.
 * One narrow box per craft follows those slots without covering the gaps.
 */
function PirateFormationHitTarget({
  markers,
  slots,
  scale,
  onPointerUp,
}: {
  markers: readonly Marker[];
  slots: readonly Vec3Tuple[];
  scale: number;
  onPointerUp: (event: ThreeEvent<PointerEvent>) => void;
}) {
  const mesh = useRef<THREE.InstancedMesh>(null);
  const transform = useMemo(() => new THREE.Object3D(), []);

  useLayoutEffect(() => {
    const node = mesh.current;
    if (!node) return;
    markers.forEach((marker, index) => {
      transform.position.set(...(slots[index] ?? [0, 0, 0]));
      transform.scale.set(...formationMarkerHitSize(marker.hull, scale));
      transform.updateMatrix();
      node.setMatrixAt(index, transform.matrix);
    });
    node.instanceMatrix.needsUpdate = true;
    node.computeBoundingSphere();
  }, [markers, scale, slots, transform]);

  return (
    <instancedMesh
      ref={mesh}
      name="pirate-formation-hit-targets"
      args={[undefined, undefined, markers.length]}
      frustumCulled={false}
      onPointerUp={onPointerUp}
      renderOrder={-1}
    >
      <boxGeometry args={[1, 1, 1]} />
      <HitboxMaterial kind="pirate" />
    </instancedMesh>
  );
}

/**
 * The existing batched flame field, made explicit and brighter for pirates: one
 * point-bank draw, not 13 sprites per ship.
 */
function PirateEngineFlames({
  markers,
  slots,
  scale,
  aimDistance,
  focused,
  showPips,
}: {
  markers: readonly Marker[];
  slots: readonly Vec3Tuple[];
  scale: number;
  aimDistance: RefObject<number>;
  focused: boolean;
  showPips: boolean;
}) {
  return (
    <FormationLightField
      name="pirate-engine-flames"
      markers={markers}
      slots={slots}
      scale={scale}
      aimDistance={aimDistance}
      focused={focused}
      showPips={showPips}
      intensity={1.45}
    />
  );
}

function Foreign({
  contact,
  nodes,
  focused,
  onSelect,
}: {
  contact: Contact;
  nodes: readonly PlanetNode[];
  focused: boolean;
  onSelect: () => void;
}) {
  const group = useRef<THREE.Group>(null);
  const formationAim = useRef(100);
  /** False until the craft has been pointed once, so it never eases in from identity. */
  const headingSettled = useRef(false);
  /**
   * WHERE THE FIGHT LEFT IT, SO IT SLIDES BACK ONTO ITS ORBIT RATHER THAN SNAPPING.
   *
   * A pirate holds at the rendezvous for the ten seconds of a battle while its
   * orbit does not stop — the fight costs it no time, which is what keeps every
   * OTHER raid's rendezvous exactly valid and needs no stored delay and no
   * re-solving. The price is that the moment the fight ends the craft is about a
   * ship-length behind where it belongs, and it used to cover that in one frame.
   *
   * Eased, the same correction reads as the pirate accelerating back onto its
   * track. It is presentation only and it is brief: the authoritative position is
   * unchanged, nothing about arrival, interception or the fog reads this.
   */
  const releasedFrom = useRef<Vec3Tuple | null>(null);
  const releasedAt = useRef(0);
  /**
   * A CONTACT AIMED AT YOU WEARS THE THREAT COLOUR. D126.
   *
   * The radar's long tier has no text and needs none: a mote you cannot identify,
   * turning hostile red as it crosses into the reach of a world you own, says
   * "that one is for you" in the only language this game trusts (D124). What it
   * still does not say is WHEN — that costs the tight ladder, and the picture is
   * careful not to imply otherwise by adding a clock anywhere near it.
   */
  const style = useMemo(() => {
    const bomb = RADIATION_BOMB_VISUAL[contact.radiationBombLevel ?? 1];
    const base = contact.kind === 'radiation_bomb'
      ? { scale: bomb.length, neon: bomb.glow, flame: bomb.flame }
      : CONTACT_STYLE[contact.kind];
    return contact.inbound === true
      ? { ...base, neon: THREAT_NEON, flame: THREAT_FLAME }
      : base;
  }, [contact.kind, contact.inbound, contact.radiationBombLevel]);
  // Polling advances the flight window, while structural sharing retains the fleet.
  // Only formation inputs should rebuild slots, hull buckets and GPU buffers.
  const towing = useMemo(() => towingFormation(contact.fleet ?? {}, contact.kind === 'fleet' ? contact.towing : undefined, style.scale),
    [contact.fleet, contact.towing, contact.kind, style.scale]);
  const markers = useMemo(
    () => contact.kind === 'fleet' && contact.fleet ? towing.markers : contactMarkers(contact),
    [contact.kind, contact.fleet, contact.craft, contact.mass, towing.markers],
  );
  /*
    EXACT-COUNT PIPS BELONG TO ACTUAL SIGHT. D123.
    A pirate inside Telescope reach carries a real manifest exactly as a player's
    fleet does, so it earns the same pips; a Radar silhouette earns none, because a
    pip over an estimate is a count that was never taken.
  */
  const exactFleet =
    (contact.kind === 'fleet' || contact.kind === 'pirate') && contact.fleet !== undefined;



  /**
   * THE BATTLE, DRAWN FOR EVERYBODY. D52.
   *
   * D44 gave the ten-second engagement to the attacker alone, because it needed a
   * target to fire at and a contact carried none. The payload names it now, for
   * exactly those ten seconds, so this mounts the SAME `Bombardment` off the SAME
   * mission id — which is what makes every player in the galaxy watch the identical
   * volley rather than each seeing their own version of it.
   */
  const fight = contact.engagement;
  const engaging = useEngagement(
    fight ? fight.arriveAt.getTime() : null,
    fight?.endsAt.getTime(),
  );
  /**
   * And the same rule from the other side of the payload. The finished mission is
   * republished for the length of the explosion so a client that was elsewhere can
   * still play it (`Contact.impact`) — the effect is what that contact is FOR, and
   * drawing a craft for it as well left a spent weapon parked over the world on
   * every screen in the galaxy.
   */
  const spent = useStrikeConsumed(contact.impact ? contact.impact.at.getTime() : null);
  const world = useMemo(
    () => (fight ? targetNodeOf(nodes, fight.target) : undefined),
    [fight, nodes],
  );
  /**
   * WHERE THIS CRAFT IS STANDING WHILE IT FIRES.
   *
   * A raid on a world derives it: the leg ends at the planet's centre, so the
   * squadron has to be pushed back out to orbit before it can be drawn shooting.
   *
   * A PIRATE FIGHT IS ALREADY PLACED. Both sides hold at points the server
   * computed — the attacker one `ENGAGEMENT_STANDOFF` short of the rendezvous on
   * its own approach, the pirate on the rendezvous itself — and it publishes them
   * as a window with no length. A degenerate window is the payload saying "I am
   * holding here", so recomputing anything from it would move the craft off the
   * spot both clients agreed on.
   *
   * THIS RULE USED TO LIVE HERE AND NOWHERE ELSE, which is why it did not work:
   * this memo only sets how far the volley flies, while `contactPosition` — the
   * helper that actually places the craft, and the one the camera reads — went
   * straight through the world-solve and put the pirate on top of its attacker.
   * `engagementPosition` is now the single answer and both of them call it.
   */
  /*
    BOTH ENDS OF THE VOLLEY ARE READ AT THE SAME INSTANT. D201.

    A convoy strike translates the craft and its target by the identical vector for
    five seconds, so the SEPARATION between them is constant — but only if the two
    are sampled together. Reading the craft at `startAt` against a target sampled
    at `serverNow()` made the rounds stretch across the pass. The window's own
    opening instant is the instant both are read at; for a stationary fight neither
    figure depends on it, so a world raid and a pirate rendezvous are unchanged.
  */
  const volleyAt = contact.startAt.getTime();
  const hold = useMemo(
    () => (fight ? engagementPosition(contact, fight.target, nodes, volleyAt) : null),
    [fight, contact, nodes, volleyAt],
  );
  const volleyAnchor = useMemo(
    () => (fight ? engagementTargetPosition(fight, volleyAt) : null),
    [fight, volleyAt],
  );
  const centre = useMemo(
    () => (fight ? engagementTargetPosition(fight, serverNow()) : null),
    [fight],
  );
  const formation = useMemo(() => contact.kind === 'fleet' && contact.fleet ? towing : formationLayout(markers, style.scale),
    [contact.kind, contact.fleet, towing, markers, style.scale]);
  const slots = formation.slots;
  const formationScale = formation.scale;
  const hitBox = useMemo(() => formationHitBox([...slots, ...towing.tows.map(tow => tow.position)],
    Math.max(formationScale, ...towing.tows.map(tow => hullVisualScale(tow.hull, style.scale)))),
    [slots, formationScale, towing.tows, style.scale]);


  useFrame((_, delta) => {
    const node = group.current;
    if (!node) return;
    /**
     * The same helper the camera reads, so a focused contact stays centred. The
     * published window is already on the shared visual leg; the only node-based
     * adjustment left is the explicit hold during a landed engagement.
     */
    const at = contactPosition(contact, serverNow(), nodes);
    /*
      COMING OUT OF A FIGHT, SLIDE BACK ONTO THE ORBIT. See `releasedFrom`.

      While the engagement is live the held point IS the position, so this only
      records it. On the first frame after it ends the craft is a ship-length off
      its track, and this covers that gap over `RELEASE_EASE_MS` instead of in one
      frame. Any craft that never held simply never enters the branch.
    */
    const wall = performance.now();
    if (centre) {
      releasedFrom.current = [at[0], at[1], at[2]];
      releasedAt.current = wall;
    } else if (releasedFrom.current !== null) {
      const t = (wall - releasedAt.current) / RELEASE_EASE_MS;
      if (t >= 1) {
        releasedFrom.current = null;
      } else {
        const held = releasedFrom.current;
        const k = t * t * (3 - 2 * t);
        at[0] = held[0] + (at[0] - held[0]) * k;
        at[1] = held[1] + (at[1] - held[1]) * k;
        at[2] = held[2] + (at[2] - held[2]) * k;
      }
    }
    node.position.set(at[0], at[1], at[2]);
    // Aimed down its own window, which is its heading and nothing further — or, once
    // it is over a world, at the world it is putting rounds into.
    const aim = contactHeadingAim(contact, at, serverNow());
    /*
      THE SLOTS AIM AT A DIRECTION, NOT AT THE SAMPLE THAT EXPRESSED IT.

      A bearing window ends wherever the craft will be a few seconds later, and a
      pirate's is ten seconds long — closer to the formation than the formation is
      wide. Aimed literally at it, each slot turned inward and the outer ships
      splayed further the more of the chord they ate, then snapped straight when
      the next window landed. `formationAimDistance` floors it against the
      squadron's own size; an engagement's target is a real place well outside it.
    */
    formationAim.current = formationAimDistance(
      Math.hypot(aim[0] - at[0], aim[1] - at[1], aim[2] - at[2]),
      formationScale,
    );
    /*
      NO GUARD HERE ANY MORE, AND THAT IS THE FIX RATHER THAN A TIDY-UP.

      This measured the aim against the window's START, which is not where the
      craft is — so it happily authorised a `lookAt` on a craft standing exactly on
      its own aim point, which is what an engaged pirate was. `easeHeading` asks the
      only question that matters, against the only position that matters, and it
      asks it for every caller.
    */
    easeHeading(node, aim, delta, headingSettled);

  });

  if (spent) return null;

  const pickContact = (event: ThreeEvent<PointerEvent>): void => {
    if (!wasTap()) return;
    markHit();
    event.stopPropagation();
    onSelect();
  };

  return (
    <>
      <group ref={group} name="contact" userData={{ craftId: contact.id }}>
        {/*
          Tappable, exactly like your own squadrons and the rocks. D24: somebody
          else's craft is an object in the world, and an object you can see but
          cannot select reads as scenery — which is the opposite of the liveliness
          this is for.
        */}
        {contact.kind === 'pirate' && markers ? (
          <PirateFormationHitTarget
            markers={markers}
            slots={slots}
            scale={style.scale}
            onPointerUp={pickContact}
          />
        ) : (
          <mesh position={hitBox.centre} onPointerUp={pickContact}>
            <boxGeometry args={hitBox.size} />
            <HitboxMaterial kind={CONTACT_HITBOX_KIND[contact.kind]} />
          </mesh>
        )}

        <TrackingMark
          kind={contact.kind}
          scale={contact.kind === 'death_star' ? style.scale * STRATEGIC_HULL_SCALE_MULT : style.scale}
          colour={contact.kind === 'death_star' ? DEATH_STAR_LIGHT.glow : style.neon}
          focused={focused}
        />

        {/*
          CONTACT FIRST, MODEL SECOND.

          One Suspense boundary used to wrap the entire traffic layer. On a cold
          device the first Wasp, Probe or Prospector decode therefore hid every
          contact — including this already-cheap tracking mark — after the server
          payload had arrived. Keep the live marker mounted and let only the heavy
          hull geometry wait for its asset.
        */}
        {contact.kind === 'fleet' && contact.appearance?.flagId &&
          <Suspense fallback={null}><FleetCosmeticFlag id={contact.appearance.flagId} scale={formationScale} /></Suspense>}
        <Suspense fallback={null}>
          {markers ? (
            <>
              {/*
                EVERY CRAFT ON THE DISC IS DRAWN THE SAME WAY. Owner instruction,
                D166 — reversing the faded treatment D160 gave a remembered pirate.

                The payload still says `remembered`, and the RAIL still states it in
                words, because "no circle covers this right now" is a real fact and a
                commander is entitled to it. What it no longer does is change the
                picture: a target that has left your circles keeps its full light
                field, its wake and its hull, because its position and crew are
                current either way (the rock lane's rule), and a dimmed ship reads as
                a rendering fault rather than as a sentence about sight.
              */}
              {contact.kind === 'fleet' && contact.appearance?.engineId && <FormationCosmeticEngines id={contact.appearance.engineId} markers={markers} slots={slots} scale={style.scale} aimDistance={formationAim} shipSkins={contact.appearance.shipSkins} />}
              {contact.kind === 'pirate' ? (
                <PirateEngineFlames
                  markers={markers}
                  slots={slots}
                  scale={style.scale}
                  aimDistance={formationAim}
                  focused={focused}
                  showPips={exactFleet}
                />
              ) : (
                <FormationLightField
                  customEngine={Boolean(contact.appearance?.engineId)}
                  shipSkins={contact.kind === 'fleet' ? contact.appearance?.shipSkins : undefined}
                  markers={markers}
                  slots={slots}
                  scale={style.scale}
                  aimDistance={formationAim}
                  focused={focused}
                  // Telescope sight is exact, so its tally uses the same pips as an
                  // owned squadron. Radar silhouettes and mining craft do not.
                  showPips={exactFleet}
                />
              )}
              <FormationWakes
                markers={markers}
                slots={slots}
                scale={style.scale}
                aimDistance={formationAim}
              />
              <FormationHulls
                markers={markers}
                slots={slots}
                scale={style.scale}
                aimDistance={formationAim}
                focused={focused}
                shipSkins={contact.kind === 'fleet' ? contact.appearance?.shipSkins : undefined}
              />
              {contact.kind === 'fleet' && towing.tugIndex !== null && towing.tows.length > 0 && <TowedShips HullsComponent={FormationHulls} shipSkins={contact.appearance?.shipSkins}
                tows={towing.tows} tug={markers[towing.tugIndex]!} tugSlot={slots[towing.tugIndex]!}
                scale={style.scale} aimDistance={formationAim} focused={focused} />}
              {contact.kind === 'pirate' && (
                <PirateMark scale={style.scale} focused={focused} />
              )}
            </>
          ) : contact.kind === 'unknown' ? (
            /**
             * NO HULL, BECAUSE THERE IS NO HULL TO SHOW. D125.
             *
             * Every other contact draws a model, and a model is an ANSWER — draw
             * a probe here and the disc has just told the player it is a probe.
             * What is left is a mark and a question, which is the honest content
             * of a sensor return at the edge of its range: something is there, and
             * your instrument cannot say what.
             */
            <UnknownMark scale={style.scale} colour={style.neon} focused={focused} />
          ) : (
            <>
              <Wake
                scale={contact.kind === 'death_star' ? style.scale * STRATEGIC_HULL_SCALE_MULT : style.scale}
                colour={contact.kind === 'death_star' ? DEATH_STAR_LIGHT.glow : style.neon}
                lengthScale={contact.kind === 'death_star' ? 0.5 : 1}
              />
              <Hull
                url={contact.kind === 'radiation_bomb' ? `/assets/models/missiles/radiation-bomb-l${String(contact.radiationBombLevel ?? 1)}.glb`
                  : contact.kind === 'death_star' ? MODEL.deathStar : contact.kind === 'probe' && contact.appearance?.probeId ? cosmeticById(contact.appearance.probeId)?.model ?? MODEL.probe : MODEL.probe}
                scale={contact.kind === 'death_star' ? style.scale * STRATEGIC_HULL_SCALE_MULT : style.scale}
                glow={contact.kind === 'death_star' ? DEATH_STAR_LIGHT.glow : style.neon}
                focused={focused}
              />
              {contact.kind === 'death_star' ? (
                <StrategicExhaust scale={style.scale * STRATEGIC_HULL_SCALE_MULT} />
              ) : contact.kind === 'radiation_bomb' ? (
                <RadiationBombExhaust level={contact.radiationBombLevel ?? 1} />
              ) : (
                <Exhaust
                  url={contact.appearance?.probeId ? cosmeticById(contact.appearance.probeId)?.model ?? MODEL.probe : MODEL.probe}
                  colour={style.flame}
                  scale={style.scale}
                />
              )}
            </>
          )}
        </Suspense>

        {/*
          The volley, seeded from the mission id — the same key the attacker's own
          client uses, so the two of them watch the identical bombardment.
        */}
        {fight && hold && volleyAnchor && centre && engaging && (
          <Bombardment
            volleyKey={contact.id}
            slots={slots}
            distance={Math.hypot(
              volleyAnchor[0] - hold[0],
              volleyAnchor[1] - hold[1],
              volleyAnchor[2] - hold[2],
            )}
            /*
              THE SIZE OF WHAT IS BEING SHOT AT. D150.

              A world gives its drawn radius. A pirate fight has no world — the
              target is the other formation — so it gives the formation's own
              footprint instead. This guard used to require a planet node, which is
              why a pirate battle drew no rounds at all: both sides were firing and
              nothing was rendered.
            */
            radius={world ? world.radius : formationScale}
            shipScale={style.scale}
            arriveAt={fight.arriveAt.getTime()}
            engagementSeconds={(fight.endsAt.getTime() - fight.arriveAt.getTime()) / 1000}
            strikesWorld={world !== undefined}
          />
        )}
      </group>
    </>
  );
}

function TrackingMark({
  kind,
  scale,
  colour,
  focused,
}: {
  kind: TrackingKind;
  scale: number;
  colour: string;
  focused: boolean;
}) {
  const unknown = kind === 'unknown';
  // The Death Star and the radiation bomb share one reticle; only its colour differs.
  const strategic = kind === 'death_star' || kind === 'radiation_bomb';
  const look = trackingMarkStyle(kind, colour);
  const radius = scale * (
    strategic
      ? 0.225
      : unknown
        ? UNKNOWN_CONTACT_MARK.radius
        : TRACKING_MARK.standardRadius
  );
  const opacity = unknown
    ? focused
      ? UNKNOWN_CONTACT_MARK.focusedOpacity
      : UNKNOWN_CONTACT_MARK.opacity
    : focused
      ? 0.92
      : 0.46;
  const segments = kind === 'probe' ? 4 : kind === 'mining' || kind === 'harvest' ? 6 : 32;
  const ringOuter = strategic
    ? 1.0175
    : unknown
      ? UNKNOWN_CONTACT_MARK.ringOuter
      : TRACKING_MARK.ringOuter;
  const ticks = useMemo(() => look.ticks ? trackingTicksGeometry(
    radius,
    scale * (strategic ? 0.02 : TRACKING_MARK.fleetTickWidth),
    scale * (strategic ? 0.225 : TRACKING_MARK.fleetTickLength),
  ) : null, [look.ticks, radius, scale, strategic]);
  // Passed by reference, so the reticle owns and frees it.
  useEffect(() => () => { ticks?.dispose(); }, [ticks]);
  return (
    <Billboard follow lockX={false} lockY={false} lockZ={false}>
      <group name={`tracking-mark-${kind}`} rotation={[0, 0, kind === 'probe' ? Math.PI / 4 : 0]}>
        {/*
          AN UNIDENTIFIED RETURN GETS A BROKEN RETICLE. D125.
          Three segments rather than a closed circle: the reticle itself says the
          lock did not complete, which is the same fact the question mark inside it
          states in words. Nothing here names a kind, because naming it is exactly
          what the Telescope is sold for.
        */}
        {kind === 'unknown' && (
          <mesh renderOrder={SHIP_ORDER + 3}>
            <ringGeometry args={[radius, radius * ringOuter, 3]} />
            <meshBasicMaterial
              color={colour}
              transparent
              opacity={opacity}
              depthWrite={false}
              toneMapped={false}
              blending={THREE.AdditiveBlending}
            />
          </mesh>
        )}
        {look.ring && (
          <mesh renderOrder={SHIP_ORDER + 3}>
            <ringGeometry args={[radius, radius * ringOuter, segments]} />
            <meshBasicMaterial color={look.colour} transparent opacity={opacity} depthWrite={false} />
          </mesh>
        )}
        {ticks && (
          <mesh geometry={ticks} renderOrder={SHIP_ORDER + 3}>
            <meshBasicMaterial color={look.colour} transparent opacity={opacity} depthWrite={false} />
          </mesh>
        )}
        {strategic && (
          <mesh renderOrder={SHIP_ORDER + 3}>
            <ringGeometry args={[radius * 1.11, radius * 1.135, 32]} />
            <meshBasicMaterial color={look.colour} transparent opacity={opacity * 0.7} depthWrite={false} />
          </mesh>
        )}
      </group>
    </Billboard>
  );
}

/**
 * IS THIS FLEET OVER ITS TARGET RIGHT NOW, WITH NOTHING YET DECIDED? D44.
 *
 * State rather than a per-frame read, because it decides whether the bombardment
 * EXISTS. A frame-level check would have to keep three dozen missile groups
 * mounted for the whole forty-minute flight so that one of them could become
 * visible at the end of it; two timers cost nothing and mount the volley for
 * exactly the ten seconds it is wanted.
 *
 * Both edges are armed, and the window is re-read on every change of `arriveAt`
 * AND every time the page becomes visible again — because a backgrounded tab has
 * its timers throttled and its frames stopped, so the state it holds when it wakes
 * is the state it had when it went away rather than the state of the world.
 *
 * Exported for its own test. It decides whether a `Bombardment` EXISTS, which is
 * the one thing on this disc that cannot be checked by looking at a still frame.
 */
/**
 * A DEATH STAR DOES NOT SURVIVE ITS OWN STRIKE. Owner instruction. D106.
 *
 * *"Hedefe vardı → kendisi yok oldu → patlama animasyonu göründü."* The craft IS
 * the explosion: there is nothing left to hover, and a missile parked over a world
 * it has just detonated on is the single most confusing thing the disc can draw —
 * the player has watched the blast and is still looking at the weapon.
 *
 * It lingered for two different reasons, one on each side of the payload. The
 * attacker's own thread lives until the worker resolves the mission, which is up to
 * a poll later; and the finished mission is REPUBLISHED to the whole galaxy for the
 * length of the effect (see `Contact.impact`), so every other screen had a craft to
 * draw for those eight seconds. Both are correct payloads. What was missing was the
 * rule about what they MEAN, so it is stated once, here, and both renderers ask it.
 *
 * The instant is the authority and the timer only says when to look, exactly as in
 * `useEngagement` — including the wake on visibility, because a tab that was in the
 * background for the whole strike comes back holding the answer it had when it
 * left.
 */
export function useStrikeConsumed(at: number | null): boolean {
  const [consumed, setConsumed] = useState(() => at !== null && serverNow() >= at);

  useEffect(() => {
    if (at === null) {
      setConsumed(false);
      return;
    }

    let timer: ReturnType<typeof setTimeout> | undefined;
    const settle = (): void => {
      if (timer !== undefined) clearTimeout(timer);
      const now = serverNow();
      setConsumed(now >= at);
      const delay = at - now;
      if (delay > 0 && delay <= 2_147_483_647) {
        timer = setTimeout(() => {
          setConsumed(true);
        }, delay);
      }
    };

    settle();
    const wake = (): void => {
      if (isAppActive()) settle();
    };
    const stopActivity = watchAppActivity(wake);
    window.addEventListener('pageshow', wake);

    return () => {
      stopActivity();
      window.removeEventListener('pageshow', wake);
      if (timer !== undefined) clearTimeout(timer);
    };
  }, [at]);

  return consumed;
}

export function useEngagement(arriveAt: number | null, explicitEndsAt?: number): boolean {
  const [engaging, setEngaging] = useState(
    () => arriveAt !== null && (explicitEndsAt === undefined
      ? isEngaging(arriveAt, serverNow())
      : serverNow() >= arriveAt && serverNow() < explicitEndsAt),
  );

  useEffect(() => {
    if (arriveAt === null) {
      setEngaging(false);
      return;
    }

    const timers: ReturnType<typeof setTimeout>[] = [];
    const arm = (at: number, to: boolean): void => {
      const delay = at - serverNow();
      // `setTimeout` overflows past 2^31 ms and fires IMMEDIATELY, which would
      // start a bombardment the moment a very distant raid launched. A flight that
      // far out simply arms on a later poll instead.
      if (delay > 0 && delay <= 2_147_483_647) {
        timers.push(
          setTimeout(() => {
            setEngaging(to);
          }, delay),
        );
      }
    };

    /**
     * THE CLOCK IS THE AUTHORITY; THE TIMERS ONLY SAY WHEN TO LOOK AT IT.
     *
     * A backgrounded tab has its timers throttled to about one a minute and its
     * animation frames stopped altogether, so a phone that was in a pocket across
     * a ten-second engagement comes back holding whatever `engaging` was when it
     * went away — which for a raid that has since resolved is `true`, and draws a
     * squadron bombarding a world whose battle report the player has already read.
     *
     * So the answer is recomputed from `serverNow()` whenever the page becomes
     * visible again, and the timers are re-armed from the same instant. Nothing
     * here decides anything: `isEngaging` is the rule, the server owns the clock,
     * and this only asks the question again at the moments it can have changed.
     */
    const settle = (): void => {
      for (const timer of timers) clearTimeout(timer);
      timers.length = 0;
      setEngaging(explicitEndsAt === undefined
        ? isEngaging(arriveAt, serverNow())
        : serverNow() >= arriveAt && serverNow() < explicitEndsAt);
      arm(arriveAt, true);
      arm(explicitEndsAt ?? engagementEndsAt(arriveAt), false);
    };

    settle();
    const wake = (): void => {
      if (isAppActive()) settle();
    };
    const stopActivity = watchAppActivity(wake);

    return () => {
      stopActivity();
      for (const timer of timers) clearTimeout(timer);
    };
  }, [arriveAt, explicitEndsAt]);

  return engaging;
}

