import { useEffect, useRef, useState, type CSSProperties, type ReactNode } from 'react';
import type { DockTab } from '../../lib/dock.js';
import { DESK_QUERY, useMedia } from '../../lib/media.js';
import { shortcutOf } from '../../lib/shortcuts.js';
import { bellTabFor, dockAction, tabOfPanel } from '../../lib/shellRoute.js';
import type { Panel, PanelStop } from '../../screens/GalaxyView.jsx';
import type { StripFocus } from '../../shell/PendingStrip.js';
import { useOpenSignals } from '../../shell/Signals.js';
import type { BellTab } from '../hud/BellSheet.js';
import type { AwayDoor } from '../../lib/awayStory.js';
import type { ChatChannel } from '../../screens/ChatScreen.js';
import { AwayHost } from './AwayHost.js';
import { BellHost } from './BellHost.js';
import { ChatHost } from './ChatHost.js';
import { FleetHost } from './FleetHost.js';
import { REPAIR_STATION_ITEM } from '../../lib/repairStation.js';
import { HudDock } from './HudDock.js';
import { HudTop } from './HudTop.js';
import { OutlineHost } from './OutlineHost.js';
import { RecallHost } from '../../brand/RecallHost.js';

/** Open a page: the panel, its shelf, the report, the row — as the app's router takes it. */
export type ShellRoute = (
  panel: Panel,
  stop?: PanelStop,
  reportMissionId?: string,
  focus?: { planetId?: string; group?: string; itemId?: string },
) => void;

export interface GameShellProps {
  isAdmin?: boolean;
  accountId?: string;
  commander: string;
  /** The page open over the galaxy, owned by the app. */
  panel: Panel;
  onPanel: ShellRoute;
  /** Frame a world on the galaxy; `dossier` opens its dossier too (a sighting's "Open the dossier", M4). */
  onFocusPlanet: (planetId: string, options?: { dossier?: boolean; select?: boolean }) => void;
  /** Frame one of the player's craft (or a contact) from the Fleet page. */
  onFocusCraft: (focus: StripFocus) => void;
  /**
   * The galaxy, handed the shell's counted requests and its router: fly home, open the
   * worlds, bring the selection into view (Space), let go of it (Esc).
   */
  galaxy: (shell: {
    homeRequest: number;
    worldsRequest: number;
    centerRequest: number;
    clearRequest: number;
    onPanel: ShellRoute;
    /**
     * Open chat as its own page, on a given room (the war room's "Clan chat", E9) — with a
     * clan line to start from where one is handed over (a report told to the clan, M4).
     */
    onOpenChat: (channel?: ChatChannel, draft?: string) => void;
  }) => ReactNode;
}

/**
 * THE v2 SHELL. Spec B1–B4, K1 and the "every surface's new place" table
 * (docs/ui-v2/gozlemevi.md).
 *
 * The top bar and the Now line above the galaxy, the dock under it, and the three
 * sheets the shell owns itself: the bell (signals, chronicle), chat and the Fleet
 * page. The galaxy never unmounts; every page opens over it and sits above
 * the dock (`.v2-shell` publishes `--v2-dock-h`, which both sheet kits read), so
 * a tab is always one press from any page.
 *
 * The chronicle is a bell tab (K1): a route to it opens the bell instead of a page.
 * Chat is its own page (owner, 2026-09-24), opened from its button on the galaxy.
 * Opening the bell on Signals marks the feed read, as the old beacon did; opening it
 * on the chronicle, or opening chat, does not — nobody has seen the signals yet.
 *
 * ON A DESK (E11 · K10, ≥1100 px) the phone is not scaled up: the tabs move into the
 * top bar, the outline (worlds, flights, queues) opens as a column beside the galaxy,
 * and pages dock to the right (both sheet kits). The keyboard works at every width:
 * 1–5 the tabs, Space the selection, Esc lets go (`shortcutOf`).
 */
export function GameShell({ accountId, commander, panel, onPanel, onFocusPlanet, onFocusCraft, galaxy, isAdmin = false }: GameShellProps) {
  const [bell, setBell] = useState<{ tab: BellTab; justRead: ReadonlySet<string> } | null>(null);
  const [fleetOpen, setFleetOpen] = useState(false);
  const [chatOpen, setChatOpen] = useState(false);
  const [chatChannel, setChatChannel] = useState<ChatChannel | undefined>(undefined);
  const [chatDraft, setChatDraft] = useState<string | undefined>(undefined);
  /** The Now line's timers sheet: closed by every move below, never left under a page. */
  const [nowOpen, setNowOpen] = useState(false);
  const [homeRequest, setHomeRequest] = useState(0);
  const [worldsRequest, setWorldsRequest] = useState(0);
  const [centerRequest, setCenterRequest] = useState(0);
  const [clearRequest, setClearRequest] = useState(0);
  const openSignals = useOpenSignals();
  const desk = useMedia(DESK_QUERY);
  const top = useRef<HTMLDivElement>(null);
  const [topHeight, setTopHeight] = useState<number | null>(null);

  /**
   * The top bar and the Now line are as tall as what they hold; every page starts under
   * both (`--v2-top-h`, read by both sheet kits — owner, 2026-10-20: a page that ran to the
   * screen top hid its close on some phones). Sheets portaled to the body read it from the
   * document, so it is published there too while the shell is on screen.
   */
  useEffect(() => {
    const node = top.current;
    if (!node || typeof ResizeObserver === 'undefined') return undefined;
    const root = document.documentElement.style;
    const observer = new ResizeObserver(() => {
      setTopHeight(node.offsetHeight);
      root.setProperty('--v2-top-h', `${String(node.offsetHeight)}px`);
    });
    observer.observe(node);
    return () => {
      observer.disconnect();
      root.removeProperty('--v2-top-h');
    };
  }, []);

  /** Leave whatever page is open, so the next thing opens alone. */
  const clearPages = (): void => {
    setNowOpen(false);
    setBell(null);
    setFleetOpen(false);
    setChatOpen(false);
    if (panel !== null) onPanel(null);
  };

  const openBell = (tab: BellTab): void => {
    setNowOpen(false);
    setFleetOpen(false);
    setChatOpen(false);
    if (panel !== null) onPanel(null);
    setBell({ tab, justRead: tab === 'signals' ? openSignals() : new Set() });
  };

  /** Chat, its own page: on the room asked for, or — with none — on what is unread. */
  const openChat = (channel?: ChatChannel, draft?: string): void => {
    clearPages();
    setChatChannel(channel);
    setChatDraft(draft);
    setChatOpen(true);
  };

  const route: ShellRoute = (next, stop, reportMissionId, focus) => {
    const tab = bellTabFor(next);
    if (tab) {
      openBell(tab);
      return;
    }
    if (next === 'chat') {
      openChat();
      return;
    }
    setNowOpen(false);
    setBell(null);
    setFleetOpen(false);
    setChatOpen(false);
    onPanel(next, stop, reportMissionId, focus);
  };

  const active: DockTab | null = bell || chatOpen ? null : tabOfPanel(panel, fleetOpen);

  /** Where each line of the return story (E10) takes the player; a world's door carries its id. */
  const openAway = (door: AwayDoor, planetId?: string): void => {
    switch (door) {
      case 'report':
        route('intel', 'battles');
        return;
      case 'intel':
        route('intel');
        return;
      case 'base':
        route('planet', undefined, undefined, { group: 'grow' });
        return;
      case 'orbit':
        route('planet', undefined, undefined, { group: 'orbit' });
        return;
      case 'signals':
        openBell('signals');
        return;
      case 'dossier':
        if (planetId === undefined) return;
        clearPages();
        onFocusPlanet(planetId, { dossier: true });
        return;
      case 'repair':
        // The faults lead that world's Base (E5), so its Base is the repair.
        route('planet', undefined, undefined, planetId === undefined ? undefined : { planetId });
        return;
    }
  };

  const onSelectTab = (tab: DockTab): void => {
    setNowOpen(false);
    const action = dockAction(tab, active);
    switch (action.kind) {
      case 'stay':
        return;
      case 'home':
        setHomeRequest((n) => n + 1);
        return;
      case 'galaxy':
        clearPages();
        return;
      case 'fleet':
        clearPages();
        setFleetOpen(true);
        return;
      case 'panel':
        route(action.panel);
        return;
    }
  };

  // The keys read the latest routing without re-subscribing on every render.
  const selectTab = useRef(onSelectTab);
  selectTab.current = onSelectTab;
  useEffect(() => {
    const onKey = (event: KeyboardEvent): void => {
      const shortcut = shortcutOf(event, document.querySelector('[data-sheet-panel]') !== null);
      if (shortcut === null) return;
      if (shortcut.kind === 'tab') selectTab.current(shortcut.tab);
      else if (shortcut.kind === 'center') setCenterRequest((n) => n + 1);
      else setClearRequest((n) => n + 1);
      // Space would scroll the page under the galaxy; a number has nothing to type into.
      if (shortcut.kind !== 'clear') event.preventDefault();
    };
    window.addEventListener('keydown', onKey);
    return () => { window.removeEventListener('keydown', onKey); };
  }, []);

  const dock = (
    <HudDock active={active} onSelect={onSelectTab} over={active !== 'galaxy' || nowOpen} bar={desk} />
  );

  return (
    <div
      className="v2-shell relative z-10 flex h-dvh flex-col overflow-hidden bg-v2-void"
      {...(topHeight === null ? {} : { style: { '--v2-top-h': `${String(topHeight)}px` } as CSSProperties })}
    >
      <div ref={top} className="shrink-0">
      <HudTop
        commander={commander}
        onCommander={() => { route('menu'); }}
        onShop={() => { route('skin-shop'); }}
        onRewards={() => { route('rewards'); }}
        onWorlds={() => {
          clearPages();
          setWorldsRequest((n) => n + 1);
        }}
        onEconomy={() => { route('planet', undefined, undefined, { group: 'grow' }); }}
        onBell={() => { openBell('signals'); }}
        nowOpen={nowOpen}
        onNow={setNowOpen}
        onFocusCraft={onFocusCraft}
        {...(desk ? { tabs: dock } : {})}
      />
      </div>

      {/*
        THE GALAXY RUNS UNDER THE DOCK (owner, 2026-09-24): the dock is see-through and floats over
        the bottom of the scene, so everything the galaxy anchors to its foot sits `--v2-dock-h` up.
      */}
      <div className="relative flex min-h-0 flex-1">
        {desk && (
          <OutlineHost
            onFocusPlanet={(planetId) => {
              clearPages();
              // A world row selects that world, not only frames it (owner report, 2026-10-06).
              onFocusPlanet(planetId, { select: true });
            }}
            onFocusCraft={(focus) => {
              clearPages();
              onFocusCraft(focus);
            }}
            onRoute={route}
          />
        )}
        <main className="relative min-w-0 flex-1">
          {galaxy({ homeRequest, worldsRequest, centerRequest, clearRequest, onPanel: route, onOpenChat: openChat })}
          {!desk && <div className="absolute inset-x-0 bottom-0 z-50">{dock}</div>}
        </main>
      </div>

      {/* E10: asked for after the galaxy is up, never before it (K5). */}
      <AwayHost onDoor={openAway} onAll={() => { openBell('signals'); }} />
      {accountId && <RecallHost key={accountId} accountId={accountId} paused={panel !== null || bell !== null || fleetOpen || chatOpen || nowOpen} />}

      {fleetOpen && (
        <FleetHost
          onFocus={(focus) => { onFocusCraft(focus); }}
          // A world row selects that world, not only frames it — as the outline's rows do.
          onFocusWorld={(planetId) => { onFocusPlanet(planetId, { select: true }); }}
          onClose={() => { setFleetOpen(false); }}
          // The world, its Base on the Fleet tab, and the station open on it: one press.
          onOpenRepairStation={(planetId) => {
            route('planet', undefined, undefined, { planetId, group: 'reach', itemId: REPAIR_STATION_ITEM });
          }}
        />
      )}

      {chatOpen && (
        <ChatHost
          accountId={accountId}
          isAdmin={isAdmin}
          onClose={() => { setChatOpen(false); }}
          onFocusPlanet={onFocusPlanet}
          {...(chatChannel ? { channel: chatChannel } : {})}
          {...(chatDraft ? { draft: chatDraft } : {})}
        />
      )}

      {bell && (
        <BellHost
          onFocusMonument={(id) => { onFocusCraft({ kind: 'monument', id }); }}
          tab={bell.tab}
          justRead={bell.justRead}
          onTab={(tab) => {
            // Switching to Signals is its first sight of the feed if the bell opened elsewhere.
            const justRead = tab === 'signals' && bell.tab !== 'signals' && bell.justRead.size === 0
              ? openSignals()
              : bell.justRead;
            setBell({ tab, justRead });
          }}
          onClose={() => { setBell(null); }}
          onGo={route}
          onFocusPlanet={onFocusPlanet}
          onOpenPlanet={() => { route('planet'); }}
        />
      )}
    </div>
  );
}

sources.docker-compose.prod.yml:
# Astera Online — production topology certified by D99.
#
# Three API event loops share PostgreSQL and an ephemeral Valkey rate-limit store;
# exactly one worker resolves scheduled moments. Every published port is loopback
# only. Nginx is the sole public entry point.

name: astera

x-api: &api
  build:
    context: .
    dockerfile: Dockerfile
    target: server
    args:
      ASTERA_GIT_COMMIT: ${ASTERA_GIT_COMMIT:-unknown}
  image: astera-server
  restart: unless-stopped
  volumes:
    - astera_chat_media:/data/chat-media
  # A runaway API must be killed before it can force PostgreSQL out of memory.
  # Three 1 GiB ceilings leave ample room on the 11.7 GiB D99 host.
  mem_limit: ${API_MEMORY_LIMIT:-1g}
  mem_reservation: ${API_MEMORY_RESERVATION:-256m}
  environment: &api-environment
    NODE_ENV: production
    ROLE: api
    PORT: 3200
    DATABASE_URL: postgres://${POSTGRES_USER:-astera}:${POSTGRES_PASSWORD}@postgres:5432/${POSTGRES_DB:-astera}
    DB_POOL_MAX: ${API_DB_POOL_MAX:-8}
    PLACEMENT_POOL_MAX: ${PLACEMENT_POOL_MAX:-2}
    JWT_SECRET: ${JWT_SECRET:?set JWT_SECRET in .env}
    # Enable only after migration 0185 and all API/worker replicas are compatible.
    NATIVE_AUTH_ENABLED: ${NATIVE_AUTH_ENABLED:-false}
    NATIVE_APP_ORIGINS: ${NATIVE_APP_ORIGINS:-}
    ACCOUNT_EMAIL_ENABLED: ${ACCOUNT_EMAIL_ENABLED:-false}
    PASSWORD_RECOVERY_ENABLED: ${PASSWORD_RECOVERY_ENABLED:-false}
    MAIL_DELIVERY_ENABLED: ${MAIL_DELIVERY_ENABLED:-false}
    RESEND_API_KEY: ${RESEND_API_KEY:-}
    RESEND_WEBHOOK_SECRET: ${RESEND_WEBHOOK_SECRET:-}
    MAIL_FROM: ${MAIL_FROM:-Astera Online <security@account.asteraonline.space>}
    MAIL_REPLY_TO: ${MAIL_REPLY_TO:-support@asteraonline.space}
    AUTH_CODE_HMAC_SECRET: ${AUTH_CODE_HMAC_SECRET:-}
    MAIL_OUTBOX_ENCRYPTION_KEY: ${MAIL_OUTBOX_ENCRYPTION_KEY:-}
    FIRST_GAME_SHIELD_ENABLED: ${FIRST_GAME_SHIELD_ENABLED:-true}
    PADDLE_CHECKOUT_ENABLED: ${PADDLE_CHECKOUT_ENABLED:-false}
    PADDLE_ENV: ${PADDLE_ENV:-production}
    PADDLE_LIVE_API_KEY: ${PADDLE_LIVE_API_KEY:-}
    PADDLE_CLIENT_SIDE_TOKEN: ${PADDLE_CLIENT_SIDE_TOKEN:-}
    PADDLE_WEBHOOK_SECRET: ${PADDLE_WEBHOOK_SECRET:-}
    PADDLE_PRICE_LAVA: ${PADDLE_PRICE_LAVA:-pri_01m3fwr44wjzkbenrjctb9k6dd}
    PADDLE_PRICE_ICE: ${PADDLE_PRICE_ICE:-pri_01m3fws4ewv6kp2yr4tztk8427}
    PADDLE_PRICE_TOXIC: ${PADDLE_PRICE_TOXIC:-pri_01m3fwtx8bvz0dbqdv3p18379m}
    PADDLE_PRICE_DESERT: ${PADDLE_PRICE_DESERT:-pri_01m3fwvmk6eysq56ed05z1828m}
    PADDLE_PRICE_TURKEY: ${PADDLE_PRICE_TURKEY:-pri_01m3fx4wqpeqpzav659tz16e7t}
    PADDLE_PRICE_GERMANY: ${PADDLE_PRICE_GERMANY:-pri_01m3fx5v21rxrjaddw764dexe4}
    PADDLE_PRICE_FRANCE: ${PADDLE_PRICE_FRANCE:-pri_01m3fx6rg3nsn9nd3j179287hg}
    PADDLE_PRICE_SPAIN: ${PADDLE_PRICE_SPAIN:-pri_01m3fx85a9gb6gpkbbrjjry73p}
    PADDLE_PRICE_BUNDLE: ${PADDLE_PRICE_BUNDLE:-pri_01m3fx3943k024e12yb67a49r1}
    POLAR_CHECKOUT_ENABLED: ${POLAR_CHECKOUT_ENABLED:-false}
    POLAR_ENV: ${POLAR_ENV:-production}
    POLAR_ACCESS_TOKEN: ${POLAR_ACCESS_TOKEN:-}
    POLAR_WEBHOOK_SECRET: ${POLAR_WEBHOOK_SECRET:-}
    POLAR_COSMETIC_PRODUCTS: ${POLAR_COSMETIC_PRODUCTS:-}
    POLAR_RETURN_URL: ${POLAR_RETURN_URL:-https://asteraonline.space/}
    POLAR_PRODUCT_LAVA: ${POLAR_PRODUCT_LAVA:-}
    POLAR_PRODUCT_ICE: ${POLAR_PRODUCT_ICE:-}
    POLAR_PRODUCT_TOXIC: ${POLAR_PRODUCT_TOXIC:-}
    POLAR_PRODUCT_DESERT: ${POLAR_PRODUCT_DESERT:-}
    POLAR_PRODUCT_TURKEY: ${POLAR_PRODUCT_TURKEY:-}
    POLAR_PRODUCT_GERMANY: ${POLAR_PRODUCT_GERMANY:-}
    POLAR_PRODUCT_FRANCE: ${POLAR_PRODUCT_FRANCE:-}
    POLAR_PRODUCT_SPAIN: ${POLAR_PRODUCT_SPAIN:-}
    POLAR_PRODUCT_JAPAN: ${POLAR_PRODUCT_JAPAN:-82b25098-29bb-4b98-a8f4-11cb78ee2e7b}
    POLAR_PRODUCT_BUNDLE: ${POLAR_PRODUCT_BUNDLE:-}
    SHOPIER_CHECKOUT_ENABLED: ${SHOPIER_CHECKOUT_ENABLED:-false}
    SHOPIER_ACCESS_TOKEN: ${SHOPIER_ACCESS_TOKEN:-}
    shopier_prod_access_token: ${shopier_prod_access_token:-}
    SHOPIER_WEBHOOK_TOKEN: ${SHOPIER_WEBHOOK_TOKEN:-}
    SHOPIER_PRODUCTS: ${SHOPIER_PRODUCTS:-}
    CHAT_MEDIA_DIR: /data/chat-media
    ADMIN_USERNAMES: ${ADMIN_USERNAMES:-}
    BOTS_PER_GALAXY: ${BOTS_PER_GALAXY:-100}
    TRUST_PROXY: 'true'
    LOG_LEVEL: ${LOG_LEVEL:-info}
    RATE_LIMIT_MAX: ${RATE_LIMIT_MAX:-300}
    RATE_LIMIT_AUTH_MAX: ${RATE_LIMIT_AUTH_MAX:-40}
    RATE_LIMIT_SIGNUP_MAX: ${RATE_LIMIT_SIGNUP_MAX:-18}
    RATE_LIMIT_REDIS_URL: redis://valkey:6379/0
    PROJECTION_CACHE_ENABLED: ${PROJECTION_CACHE_ENABLED:-true}
    PROJECTION_CACHE_MAX_SEASONS: ${PROJECTION_CACHE_MAX_SEASONS:-16}
    PROJECTION_CACHE_MAX_ACCOUNTS: ${PROJECTION_CACHE_MAX_ACCOUNTS:-1024}
    COMMANDER_CACHE_TTL_MS: ${COMMANDER_CACHE_TTL_MS:-30000}
    PUBLIC_CACHE_TTL_MS: ${PUBLIC_CACHE_TTL_MS:-30000}
    TRAFFIC_CACHE_TTL_MS: ${TRAFFIC_CACHE_TTL_MS:-5000}
    # Set false for the first compatibility roll, true after all four processes
    # understand the additional pirate handles. Existing targets stay visible.
    PIRATE_SPAWN_INCREASE_ENABLED: ${PIRATE_SPAWN_INCREASE_ENABLED:-true}
    # The same two-phase rule for the 2026-09-14 doubling, which appends a THIRD
    # lane after the one above. Nests with it: while the older flag is false this
    # one changes nothing, because a process that cannot read the +50% lane
    # certainly cannot read the lane after it.
    PIRATE_SPAWN_SURGE_ENABLED: ${PIRATE_SPAWN_SURGE_ENABLED:-true}
    # Keep false until every API and worker can parse the stored v2 pirate inputs.
    PIRATE_BALANCE_V2_ENABLED: ${PIRATE_BALANCE_V2_ENABLED:-true}
    # The recovery shield (2026-09-14). False means the columns are written by the
    # migration and read by nobody: no window is granted and no stored instant
    # refuses a launch, so a fleet mid-roll cannot have one instance enforcing a
    # shield another instance does not know exists. The first-day shield is a
    # separate column and is untouched either way.
    RECOVERY_SHIELD_ENABLED: ${RECOVERY_SHIELD_ENABLED:-true}
    MINING_CACHE_TTL_MS: ${MINING_CACHE_TTL_MS:-5000}
    SSE_MAX_BUFFER_BYTES: ${SSE_MAX_BUFFER_BYTES:-65536}
  depends_on:
    postgres:
      condition: service_healthy
    valkey:
      condition: service_healthy
  stop_grace_period: 30s
  ulimits:
    nofile:
      soft: 65535
      hard: 65535
  healthcheck: &api-healthcheck
    test: ['CMD-SHELL', 'wget -q -O- http://127.0.0.1:3200/health || exit 1']
    interval: 30s
    timeout: 10s
    retries: 3
    start_period: 20s
  logging: &app-logging
    driver: json-file
    options: { max-size: '10m', max-file: '5' }

services:
  postgres:
    image: postgres:16-alpine
    container_name: astera-postgres-prod
    restart: unless-stopped
    mem_limit: ${POSTGRES_MEMORY_LIMIT:-4g}
    mem_reservation: ${POSTGRES_MEMORY_RESERVATION:-1g}
    environment:
      POSTGRES_USER: ${POSTGRES_USER:-astera}
      POSTGRES_PASSWORD: ${POSTGRES_PASSWORD:?set POSTGRES_PASSWORD in .env}
      POSTGRES_DB: ${POSTGRES_DB:-astera}
    volumes:
      - astera_pgdata:/var/lib/postgresql/data
    ports:
      - '127.0.0.1:${POSTGRES_PORT:-5545}:5432'
    healthcheck:
      test: ['CMD-SHELL', 'pg_isready -U ${POSTGRES_USER:-astera} -d ${POSTGRES_DB:-astera}']
      interval: 10s
      timeout: 5s
      retries: 5
    logging:
      driver: json-file
      options: { max-size: '10m', max-file: '3' }

  # Rate-limit counters are disposable. No host port and no persistence: losing
  # this container loses counters, never a player or an outcome.
  valkey:
    image: valkey/valkey:9.1.1-alpine
    container_name: astera-valkey-prod
    restart: unless-stopped
    mem_limit: ${VALKEY_MEMORY_LIMIT:-128m}
    mem_reservation: ${VALKEY_MEMORY_RESERVATION:-64m}
    command:
      - valkey-server
      - --save
      - ''
      - --appendonly
      - 'no'
      - --protected-mode
      - 'no'
      - --maxmemory
      - 64mb
      - --maxmemory-policy
      - allkeys-lru
    healthcheck:
      test: ['CMD', 'valkey-cli', 'ping']
      interval: 5s
      timeout: 3s
      retries: 10
    logging:
      driver: json-file
      options: { max-size: '5m', max-file: '2' }

  api1:
    <<: *api
    container_name: astera-api1-prod
    ports:
      - '127.0.0.1:${API_PORT_1:-3200}:3200'

  api2:
    <<: *api
    container_name: astera-api2-prod
    ports:
      - '127.0.0.1:${API_PORT_2:-3201}:3200'

  api3:
    <<: *api
    container_name: astera-api3-prod
    ports:
      - '127.0.0.1:${API_PORT_3:-3202}:3200'

  worker:
    image: astera-server
    container_name: astera-worker-prod
    restart: unless-stopped
    mem_limit: ${WORKER_MEMORY_LIMIT:-768m}
    mem_reservation: ${WORKER_MEMORY_RESERVATION:-256m}
    environment:
      <<: *api-environment
      ROLE: worker
      PORT: 3210
      DB_POOL_MAX: ${WORKER_DB_POOL_MAX:-12}
      WORKER_POLL_MS: ${WORKER_POLL_MS:-1000}
      WORKER_BATCH: ${WORKER_BATCH:-100}
      # The commanders the server plays. D159. Off unless the .env says otherwise,
      # and only ever here: an API replica never consults it. Names come from
      # the owner list synced during deploy or `pnpm bots add`; none are generated.
      BOTS_ENABLED: ${BOTS_ENABLED:-false}
      SILENT_SPACE_ENABLED: ${SILENT_SPACE_ENABLED:-false}
      SILENT_SPACE_BATCH: ${SILENT_SPACE_BATCH:-5}
      SILENT_SPACE_MAX_SHARDS: ${SILENT_SPACE_MAX_SHARDS:-16}
      SILENT_SPACE_EXEMPT_ACCOUNT_IDS: ${SILENT_SPACE_EXEMPT_ACCOUNT_IDS:-}
      # The worker registers no public routes, so it needs no shared limiter.
      RATE_LIMIT_REDIS_URL: ''
    ports:
      - '127.0.0.1:${WORKER_PORT:-3210}:3210'
    depends_on:
      postgres:
        condition: service_healthy
    stop_grace_period: 30s
    ulimits:
      nofile:
        soft: 65535
        hard: 65535
    healthcheck:
      test: ['CMD-SHELL', 'wget -q -O- http://127.0.0.1:3210/health || exit 1']
      interval: 15s
      timeout: 10s
      retries: 3
      start_period: 20s
    logging: *app-logging

  # Komutan Gemisi live playtest (docs/komutan-gemisi/13). One shared real-time room
  # on its own process: a 30 Hz loop must never share an event loop with the API.
  # Closed unless ARENA_ENABLED=true; only ARENA_PILOTS usernames may fly (`*` = all).
  # Reads accounts to identify a pilot and writes nothing.
  arena:
    image: astera-server
    container_name: astera-arena-prod
    restart: unless-stopped
    mem_limit: ${ARENA_MEMORY_LIMIT:-384m}
    mem_reservation: ${ARENA_MEMORY_RESERVATION:-128m}
    environment:
      <<: *api-environment
      ROLE: arena
      PORT: 3220
      DB_POOL_MAX: 2
      PLACEMENT_POOL_MAX: 1
      ARENA_ENABLED: ${ARENA_ENABLED:-false}
      ARENA_PILOTS: ${ARENA_PILOTS:-}
      ARENA_ALLOWED_ORIGINS: ${ARENA_ALLOWED_ORIGINS:-https://asteraonline.space}
      # Private playtest only: the reference pack is copied to the host by hand, never
      # built into an image; seated pilots read it through a signed cookie.
      ARENA_REF_DIR: /refs
      RATE_LIMIT_REDIS_URL: ''
    volumes:
      - ${ARENA_REF_HOST_DIR:-/opt/astera/arena-refs}:/refs:ro
    ports:
      - '127.0.0.1:${ARENA_PORT:-3220}:3220'
    depends_on:
      postgres:
        condition: service_healthy
    stop_grace_period: 5s
    healthcheck:
      test: ['CMD-SHELL', 'wget -q -O- http://127.0.0.1:3220/health || exit 1']
      interval: 30s
      timeout: 10s
      retries: 3
      start_period: 20s
    logging: *app-logging

volumes:
  astera_chat_media:
  astera_pgdata:

sources.deploy/nginx/astera.conf:
# Astera Online — nginx vhost.
#
# ONE ORIGIN, AND THAT IS A DESIGN DECISION RATHER THAN A SHORTCUT.
#
#   asteraonline.space         → the client (static) AND the API under /api
#   www / api / socket .*      → 301 to the apex
#
# The client is built to talk to its own origin: `fetch` sends
# `credentials: 'same-origin'`, the refresh cookie is `SameSite=Lax`, and the
# server registers no CORS at all. Two things break quietly if the API is moved
# to `api.` without also changing the client:
#
#   · The refresh cookie stops being sent, so every session ends at the first
#     token expiry — fifteen minutes in.
#   · `x-server-time` becomes unreadable, because a cross-origin response only
#     exposes a header named in `Access-Control-Expose-Headers`. The whole disc
#     is drawn by comparing server timestamps against "now", so the client would
#     silently fall back to the DEVICE clock and every fleet, every countdown and
#     every ten-second bombardment would be drawn at the wrong moment — a
#     different wrong moment on each phone (D52).
#
# `socket.` is not needed at all: the only realtime surface is server-sent
# events on /api/stream, which is ordinary HTTP on this same origin.
#
# Install:
#   sudo cp deploy/nginx/astera.conf /etc/nginx/sites-available/astera
#   sudo ln -s /etc/nginx/sites-available/astera /etc/nginx/sites-enabled/
#   sudo nginx -t && sudo systemctl reload nginx
#
# The certificate must exist BEFORE the 443 blocks are enabled or `nginx -t`
# fails on a missing file. The first-install procedure in `docs/deployment.md`
# issues it with `certonly --webroot`; deploy.sh assumes that certificate and its
# renewal hook already exist.

map $status $astera_robots {
    default "";
    404 "noindex";
}

# The dedicated receiver expires UTC daily files within 30 days.
# Keep search/reset query strings, headers and bodies out of ordinary access logs.
log_format astera_access '$remote_addr [$time_local] "$request_method $uri $server_protocol" $status $body_bytes_sent $request_time';

upstream astera_api {
    least_conn;
    server 127.0.0.1:3200 max_fails=2 fail_timeout=5s;
    server 127.0.0.1:3201 max_fails=2 fail_timeout=5s;
    server 127.0.0.1:3202 max_fails=2 fail_timeout=5s;
    keepalive 64;
}

# ── http → https, and the ACME challenge ─────────────────────────────────────
server {
    listen 80;
    listen [::]:80;
    server_name asteraonline.space www.asteraonline.space
                api.asteraonline.space socket.asteraonline.space;
    access_log syslog:server=unix:/run/astera-runtime/log.sock,tag=astera_web,severity=info astera_access;
    error_log syslog:server=unix:/run/astera-runtime/log.sock,tag=astera_web_error error;

    location /.well-known/acme-challenge/ { root /var/www/html; }
    location / { return 301 https://asteraonline.space$request_uri; }
}

# ── every other name → the apex ──────────────────────────────────────────────
# Kept rather than deleted: the DNS records exist, and a name that resolves but
# answers nothing is worse than one that takes you where the game is.
server {
    listen 443 ssl http2;
    listen [::]:443 ssl http2;
    server_name www.asteraonline.space api.asteraonline.space socket.asteraonline.space;
    access_log syslog:server=unix:/run/astera-runtime/log.sock,tag=astera_web,severity=info astera_access;
    error_log syslog:server=unix:/run/astera-runtime/log.sock,tag=astera_web_error error;

    ssl_certificate     /etc/letsencrypt/live/asteraonline.space/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/asteraonline.space/privkey.pem;

    return 301 https://asteraonline.space$request_uri;
}

# ── the game ─────────────────────────────────────────────────────────────────
server {
    listen 443 ssl http2;
    listen [::]:443 ssl http2;
    server_name asteraonline.space;
    access_log syslog:server=unix:/run/astera-runtime/log.sock,tag=astera_web,severity=info astera_access;
    error_log syslog:server=unix:/run/astera-runtime/log.sock,tag=astera_web_error error;

    # Cloudflare proxy edges, https://www.cloudflare.com/ips/ (2026-10-12).
    # Scope trust to this vhost. Direct-origin callers cannot supply their own
    # address; API/SSE forwarded headers below use the corrected remote_addr.
    set_real_ip_from 173.245.48.0/20;
    set_real_ip_from 103.21.244.0/22;
    set_real_ip_from 103.22.200.0/22;
    set_real_ip_from 103.31.4.0/22;
    set_real_ip_from 141.101.64.0/18;
    set_real_ip_from 108.162.192.0/18;
    set_real_ip_from 190.93.240.0/20;
    set_real_ip_from 188.114.96.0/20;
    set_real_ip_from 197.234.240.0/22;
    set_real_ip_from 198.41.128.0/17;
    set_real_ip_from 162.158.0.0/15;
    set_real_ip_from 104.16.0.0/13;
    set_real_ip_from 104.24.0.0/14;
    set_real_ip_from 172.64.0.0/13;
    set_real_ip_from 131.0.72.0/22;
    set_real_ip_from 2400:cb00::/32;
    set_real_ip_from 2606:4700::/32;
    set_real_ip_from 2803:f800::/32;
    set_real_ip_from 2405:b500::/32;
    set_real_ip_from 2405:8100::/32;
    set_real_ip_from 2a06:98c0::/29;
    set_real_ip_from 2c0f:f248::/32;
    real_ip_header CF-Connecting-IP;
    real_ip_recursive off;

    ssl_certificate     /etc/letsencrypt/live/asteraonline.space/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/asteraonline.space/privkey.pem;

    root /var/www/astera;
    index index.html;

    # The bundle is 1.8 MB of three.js and application code, and this game is
    # played on a phone. nginx.conf turns gzip on but leaves the type list
    # commented out, which means only text/html is compressed by default — so the
    # list has to be stated here or the one file that matters goes out raw.
    # PRE-COMPRESSED, NOT COMPRESSED PER REQUEST. nginx's default gzip level is 1;
    # the bundle came out 637 KB at it and 540 KB at maximum. deploy.sh writes a
    # `.gz` beside every compressible file at level 9, and `gzip_static` serves it
    # with no CPU at all — the best size and the least work, which for a game
    # played on a phone in a gap is the whole argument.
    gzip_static on;
    # Still on, for anything without a pre-built `.gz` — the API's JSON, mostly.
    gzip on;
    gzip_vary on;
    gzip_min_length 1024;
    gzip_types text/css application/javascript application/json image/svg+xml
               application/manifest+json font/woff2;

    # Ordinary gameplay keeps a small body ceiling; only admin media accepts large uploads.
    client_max_body_size 256k;

    add_header X-Content-Type-Options nosniff always;
    add_header X-Robots-Tag $astera_robots always;
    add_header Referrer-Policy strict-origin-when-cross-origin always;
    # TWO POLICIES ON ONE ORIGIN, AND THIS IS THE STRICT ONE.
    #
    # This header governs everything that is NOT the game document: the
    # hand-written publisher pages under `public/` — about, the guide, and the
    # six legal documents — the manifest, the icons, and the API's JSON. None of
    # them loads a third party. Not one of them carries an ad tag, an analytics
    # tag or a frame, so none of them is granted an origin that could serve one,
    # and a policy page that provably fetches nothing external is a better answer
    # to a site review than one that merely does not use what it is allowed.
    #
    # `'unsafe-inline'` is NOT granted on script-src and must not be: a publisher
    # page with an inline block is a page whose script silently does not run
    # (that is why `guide-back.js` is a file). `style-src` keeps it because the
    # quick-start guide carries its own inline stylesheet.
    #
    # THE GAME DOCUMENT HAS ITS OWN, NARROWER-ON-SCRIPT POLICY further down, in
    # `location = /index.html`: ads, three.js and the announcement renderer all
    # live there and nowhere else.
    add_header Content-Security-Policy "default-src 'self'; base-uri 'self'; object-src 'none'; form-action 'self'; frame-ancestors 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; font-src 'self' data:; media-src 'self'; connect-src 'self'; frame-src 'none'; worker-src 'self'; manifest-src 'self'" always;
    # Six months. Raise once the deployment has proved itself; a long max-age is
    # not something a mistake can be walked back from quickly.
    add_header Strict-Transport-Security "max-age=15768000" always;

    # The Wiki is build-time HTML. A category may have both a .html file and a
    # directory of articles: check the page before the directory, without an SPA
    # fallback. Existing aliases alone redirect; unknown addresses stay 404.
    location = /wiki {
        default_type text/html;
        try_files /wiki/index.html =404;
    }
    location = /wiki.html { return 308 /wiki$is_args$args; }
    location = /wiki/404.html { internal; }
    location ~ ^(?<wiki_index>/wiki(?:/[a-z0-9-]+)*)/index\.html$ {
        if (-f $document_root$uri) { return 308 $wiki_index$is_args$args; }
        return 404;
    }
    location ~ ^(?<wiki_slash>/wiki(?:/[a-z0-9-]+)*)/$ {
        if (-f $document_root$wiki_slash.html) { return 308 $wiki_slash$is_args$args; }
        if (-f $document_root$wiki_slash/index.html) { return 308 $wiki_slash$is_args$args; }
        return 404;
    }
    location ~ ^(?<wiki_html>/wiki(?:/[a-z0-9-]+)+)\.html$ {
        if (-f $document_root$uri) { return 308 $wiki_html$is_args$args; }
        return 404;
    }
    location /wiki/ {
        default_type text/html;
        error_page 404 /wiki/404.html;
        try_files $uri.html $uri/index.html $uri =404;
    }

    # ── Komutan Gemisi arena (live playtest) ─────────────────────────────────
    # One WebSocket room (`/arena/ws`) and the access probe, on their own process
    # (compose `arena`, loopback 3220). The room checks Origin and the session
    # token itself; ARENA_ENABLED=false answers every upgrade with 403. Its
    # health stays on loopback like the worker's.
    location = /arena/health { return 404; }
    # Private playtest reference pack: the arena answers only a seated pilot's
    # signed cookie, and 404s everything else. Cached privately by the browser.
    location /__ref/ {
        proxy_pass http://127.0.0.1:3220;
        proxy_http_version 1.1;
        proxy_set_header Host              $host;
        proxy_set_header X-Forwarded-Proto $scheme;
        add_header X-Robots-Tag "noindex, nofollow" always;
    }
    location /arena/ {
        proxy_pass http://127.0.0.1:3220;
        proxy_http_version 1.1;
        proxy_set_header Host              $host;
        proxy_set_header X-Real-IP         $remote_addr;
        proxy_set_header X-Forwarded-For   $remote_addr;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Upgrade           $http_upgrade;
        proxy_set_header Connection        "upgrade";
        proxy_buffering off;
        # Pings run every second; a minute of silence is a dead link.
        proxy_read_timeout 60s;
        proxy_send_timeout 60s;
    }

    # ── the live channel ─────────────────────────────────────────────────────
    # BEFORE the general /api/ block, and exact, so it wins.
    #
    # Server-sent events. The server already sends `X-Accel-Buffering: no`, which
    # nginx honours, but buffering is turned off here as well: the header is one
    # line in one route and this is the setting that makes a galaxy feel live. A
    # buffered stream arrives in a lump when the connection closes, which is the
    # same thing as no stream at all.
    location = /api/stream {
        proxy_pass http://astera_api;
        proxy_http_version 1.1;
        proxy_set_header Host              $host;
        proxy_set_header X-Real-IP         $remote_addr;
        # Replace, do not append: the public client must not be able to choose the
        # address Fastify trusts for rate limiting.
        proxy_set_header X-Forwarded-For   $remote_addr;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Connection        '';

        proxy_buffering off;
        proxy_cache off;
        # The stream heartbeats every 25s, so the 60s default would not actually
        # cut it — but a player leaves the tab open for hours and each reconnect
        # is a re-subscribe. An hour makes the reconnect rare.
        proxy_read_timeout 1h;
        proxy_send_timeout 1h;
    }

    # ── the API ──────────────────────────────────────────────────────────────
    location = /api/admin/chat/media {
        client_max_body_size 50m;
        proxy_pass http://astera_api;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $remote_addr;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Connection '';
        proxy_request_buffering off;
        proxy_read_timeout 120s;
        proxy_cache off;
    }

    location /api/ {
        proxy_pass http://astera_api;
        proxy_http_version 1.1;
        proxy_set_header Host              $host;
        proxy_set_header X-Real-IP         $remote_addr;
        proxy_set_header X-Forwarded-For   $remote_addr;
        proxy_set_header X-Forwarded-Proto $scheme;
        # Required for the upstream keepalive pool above. Without clearing the
        # hop-by-hop header nginx opens a fresh API connection for every live
        # event refetch, which turns one shard broadcast into a TCP handshake
        # wave before Fastify sees any work.
        proxy_set_header Connection        '';

        # A mutation answers with the whole planet view and is never cacheable.
        proxy_cache off;
    }

    # ── operations ───────────────────────────────────────────────────────────
    # `/health` reports the queue lag, the failed-event count, the stranded-flight
    # count and whether the live channel's LISTEN socket is open. All of that is
    # internal state and none of it is a player's business, so it is readable from
    # the box and nowhere else. Check it with:
    #   curl -s localhost:3200/health | jq
    location = /health {
        allow 127.0.0.1;
        allow ::1;
        deny all;
        proxy_pass http://astera_api/health;
        proxy_set_header Host $host;
    }

    location = /metrics {
        allow 127.0.0.1;
        allow ::1;
        deny all;
        proxy_pass http://astera_api/metrics;
        proxy_set_header Host $host;
    }

    # ── the client ───────────────────────────────────────────────────────────
    # Hashed filenames, so a year is safe and a deploy is invisible to a cache.
    location /assets/ {
        # `expires 1y` is deliberately NOT used alongside this: it emits a
        # Cache-Control of its own and the response went out carrying two of them.
        # Only successful hashed assets are immutable. A missing lazy chunk must
        # not leave a browser holding its 404 for a year after the file returns.
        add_header Cache-Control "public, max-age=31536000, immutable";
        try_files $uri =404;
    }

    # The entry point must never be cached, or a phone keeps loading the previous
    # deploy's module graph and asking for chunks that are no longer there.
    #
    # THE SECURITY HEADERS ARE REPEATED HERE, and they have to be. `add_header` is
    # not additive across levels: a location that declares one stops inheriting
    # every add_header above it. `location /` falls through to this block by
    # internal redirect, so the server-level three were silently dropped from the
    # only response that is actually HTML — the one they exist for.
    #
    # THIS IS ALSO THE ONE DOCUMENT THAT CARRIES ADS, and its script policy is
    # therefore different from every other response on the origin. Google does
    # not support allow-listing AdSense by domain: the tag in `<head>` fetches
    # further loaders from shards Google rotates, so a list is a policy that
    # breaks on a Tuesday and blanks the ads with a console line nobody is
    # watching. Their documented model is a per-request NONCE plus
    # `'strict-dynamic'` — trust what a trusted script loads, rather than where it
    # came from — and it is strictly stronger here than the list it replaces: an
    # injected `<script src>` without the nonce is refused whatever its origin,
    # which is exactly the wall player-authored announcements need behind the
    # sanitizer.
    #
    #   · `$request_id` is 32 hex characters, fresh per request. That is the nonce.
    #   · `sub_filter` writes it over the `__CSP_NONCE__` literal Vite stamps on
    #     every script tag it emits (`apps/web/vite.config.ts`, `html.cspNonce`).
    #   · `https:` and `'unsafe-inline'` are the CSP2 fallbacks Google's own
    #     example carries. A browser that understands `'strict-dynamic'` and the
    #     nonce ignores both; one that does not would otherwise run nothing.
    #   · `gzip_static off` IS LOAD-BEARING. `sub_filter` cannot rewrite a body
    #     that was pre-compressed on disk, and a page served with the placeholder
    #     intact has NO valid nonce — every script on it is refused and the game
    #     is a blank screen. `deploy.sh` already excludes index.html from
    #     pre-compression and `publish-web.sh` deletes any stale `index.html.gz`;
    #     this is the third lock on the same door, and it costs one small file
    #     being compressed per request instead of ahead of time.
    #
    # WHAT THE REST OF THIS POLICY IS FOR, since it all lives on this one
    # document: GLTF textures are exposed as browser-created blob URLs and the
    # Draco decoder compiles WebAssembly, so `blob:` and `'wasm-unsafe-eval'` are
    # the scene's two requirements — the latter grants Wasm compilation only, not
    # the JavaScript string evaluation that `'unsafe-eval'` would. Stored
    # announcements are allow-list sanitized on write and again at the browser
    # sink, and this header is the independent last wall behind that: YouTube is
    # the only framed provider the editor admits, and `frame-src` says so.
    #
    # Paddle payment links need a public page that loads Paddle.js so its _ptxn
    # query parameter can open the prepared transaction, even for a guest.
    # Keep this permission scoped to that one page; legal pages stay self-only.
    location = /checkout.html {
        try_files $uri =404;
        add_header Cache-Control "no-cache, must-revalidate" always;
        add_header X-Content-Type-Options nosniff always;
        add_header Referrer-Policy strict-origin-when-cross-origin always;
        add_header Content-Security-Policy "default-src 'self'; base-uri 'self'; object-src 'none'; form-action 'self'; frame-ancestors 'self'; script-src 'self' https://cdn.paddle.com https://*.paddle.com; style-src 'self' 'unsafe-inline'; img-src 'self' data: https://*.paddle.com; font-src 'self' data:; media-src 'self'; connect-src 'self' https://*.paddle.com; frame-src https://*.paddle.com; worker-src 'self'; manifest-src 'self'" always;
        add_header Strict-Transport-Security "max-age=15768000" always;
    }

    # Locale entry documents run the same client and require the same per-request nonce.
    location ~ ^/(?:tr|en|fr|de|es|ja)/index\.html$ {
        try_files $uri =404;
        gzip_static off;
        sub_filter_once off;
        sub_filter_types text/html;
        sub_filter '__CSP_NONCE__' $request_id;

        add_header Cache-Control "no-cache, must-revalidate" always;
        add_header X-Content-Type-Options nosniff always;
        add_header Referrer-Policy strict-origin-when-cross-origin always;
        add_header Content-Security-Policy "default-src 'self'; base-uri 'self'; object-src 'none'; form-action 'self'; frame-ancestors 'self'; script-src 'nonce-$request_id' 'strict-dynamic' 'wasm-unsafe-eval' https: 'unsafe-inline'; style-src 'self' 'unsafe-inline'; img-src 'self' data: blob: https:; font-src 'self' data:; media-src 'self'; connect-src 'self' blob: https://*.paddle.com https://*.google-analytics.com https://*.analytics.google.com https://*.googlesyndication.com https://*.googleadservices.com https://*.doubleclick.net https://*.adtrafficquality.google https://www.google.com; frame-src https://*.paddle.com https://www.youtube.com https://youtube.com https://www.youtube-nocookie.com https://youtube-nocookie.com https://*.googlesyndication.com https://*.doubleclick.net https://*.adtrafficquality.google https://www.google.com; worker-src 'self' blob:; manifest-src 'self'" always;
        add_header Strict-Transport-Security "max-age=15768000" always;
    }

    location = /index.html {
        gzip_static off;
        sub_filter_once off;
        sub_filter_types text/html;
        sub_filter '__CSP_NONCE__' $request_id;

        add_header Cache-Control "no-cache, must-revalidate" always;
        add_header X-Content-Type-Options nosniff always;
        add_header Referrer-Policy strict-origin-when-cross-origin always;
        add_header Content-Security-Policy "default-src 'self'; base-uri 'self'; object-src 'none'; form-action 'self'; frame-ancestors 'self'; script-src 'nonce-$request_id' 'strict-dynamic' 'wasm-unsafe-eval' https: 'unsafe-inline'; style-src 'self' 'unsafe-inline'; img-src 'self' data: blob: https:; font-src 'self' data:; media-src 'self'; connect-src 'self' blob: https://*.paddle.com https://*.google-analytics.com https://*.analytics.google.com https://*.googlesyndication.com https://*.googleadservices.com https://*.doubleclick.net https://*.adtrafficquality.google https://www.google.com; frame-src https://*.paddle.com https://www.youtube.com https://youtube.com https://www.youtube-nocookie.com https://youtube-nocookie.com https://*.googlesyndication.com https://*.doubleclick.net https://*.adtrafficquality.google https://www.google.com; worker-src 'self' blob:; manifest-src 'self'" always;
        add_header Strict-Transport-Security "max-age=15768000" always;
    }

    # The client has no path router: the game lives at `/`, and every public
    # content page is a real file in the webroot. Falling back to index.html for
    # an unknown address turns every typo and every removed policy page into a
    # soft 404, which misleads people and crawlers alike. The manifest start_url
    # is `/`, so it still resolves through the webroot's index normally.
    location / {
        try_files $uri $uri/ =404;
    }
}

